/**
 * seed_questions.js — Ngân hàng câu hỏi gốc
 * 750+ câu hỏi được phân loại sẵn theo độ khó
 * difficulty: 1=Dễ, 2=Trung bình, 3=Khó
 */

export const SEED_QUESTIONS = (function() {
  const list = [];
  const seen = new Set();

  function add(ch, q, opts, correct, exp, diff = 1) {
    const key = q.trim().toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    list.push({ chapter: ch, q, options: opts, correct, exp, difficulty: diff });
  }

  // ═══════════════════════════════════════════════════
  // CHƯƠNG 1: TỔNG QUAN CHẤT LƯỢNG & AN TOÀN THỰC PHẨM
  // ═══════════════════════════════════════════════════

  // --- Định nghĩa cơ bản (Dễ) ---
  add(1,"Theo ISO 9001, 'Chất lượng' được định nghĩa là gì?",["Mức độ đáp ứng các yêu cầu của tập hợp đặc tính vốn có","Sự tươi ngon tuyệt đối của sản phẩm","Độ đắt tiền và sang trọng của bao bì","Số lượng tiêu thụ tối đa trên thị trường"],0,"ISO 9001: Chất lượng là mức độ đáp ứng các yêu cầu của tập hợp đặc tính vốn có.",1);
  add(1,"An toàn thực phẩm theo Luật ATTP 2010 (Điều 2) là gì?",["Bảo đảm thực phẩm không gây hại đến sức khỏe, tính mạng con người","Thực phẩm 100% nguyên liệu hữu cơ","Thực phẩm có giá trị dinh dưỡng cao nhất","Thực phẩm được cấp chứng chỉ ISO 9001"],0,"ATTP là đảm bảo thực phẩm không gây hại khi tiêu thụ.",1);
  add(1,"Sự khác biệt căn bản giữa 'Chất lượng' và 'An toàn thực phẩm' là gì?",["An toàn thực phẩm là yêu cầu BẮT BUỘC theo pháp luật; Chất lượng nhằm thỏa mãn nhu cầu thị trường","Chất lượng có phạm vi hẹp hơn an toàn thực phẩm","An toàn không nằm trong phạm vi chất lượng","Sản phẩm ngon luôn đạt an toàn thực phẩm"],0,"An toàn là bắt buộc theo pháp luật; chất lượng nhằm thỏa mãn nhu cầu người dùng.",2);
  add(1,"'Mối nguy thực phẩm' (Food Hazard) là gì?",["Tác nhân sinh học, hóa học, vật lý có khả năng gây hại cho sức khỏe","Yếu tố làm giảm vẻ ngoài sản phẩm","Chi phí sản xuất tăng cao","Thay đổi màu sắc tự nhiên của thực phẩm"],0,"Mối nguy thực phẩm là tác nhân sinh học/hóa học/vật lý có thể gây hại cho sức khỏe.",1);
  add(1,"Ba nhóm mối nguy thực phẩm chính là gì?",["Sinh học, Hóa học và Vật lý","Nhiệt độ, Độ ẩm và Ánh sáng","Vi khuẩn, Nấm mốc và Virus","Nhập khẩu, Xuất khẩu và Nội địa"],0,"Ba nhóm mối nguy: Sinh học (vi sinh vật), Hóa học (độc tố, hóa chất), Vật lý (mảnh kim loại, thủy tinh).",1);
  add(1,"'Ngộ độc thực phẩm' xảy ra khi nào?",["Ăn phải thực phẩm chứa mầm bệnh hoặc độc tố ở mức gây hại","Ăn quá nhiều thực phẩm trong một bữa","Không ăn đủ chất dinh dưỡng","Thực phẩm bị hết hạn nhưng chưa nhiễm khuẩn"],0,"Ngộ độc thực phẩm do ăn phải thực phẩm chứa mầm bệnh hoặc độc tố.",1);
  add(1,"Nhiệt độ nguy hiểm (Danger Zone) cho vi sinh vật phát triển mạnh là bao nhiêu?",["5°C đến 60°C","0°C đến 40°C","-18°C đến 100°C","60°C đến 120°C"],0,"Vùng nguy hiểm vi sinh vật: 5-60°C, đặc biệt 25-40°C là vùng tăng trưởng nhanh nhất.",1);
  add(1,"Vi khuẩn Salmonella spp. thường gây ô nhiễm nhất trên loại thực phẩm nào?",["Thịt gia cầm tươi và trứng gà tái","Mật ong nguyên chất","Kẹo đóng gói kín","Muối ăn tinh luyện"],0,"Salmonella rủi ro cao ở thịt gia cầm, trứng chưa nấu chín.",1);
  add(1,"Đặc điểm nguy hiểm của Listeria monocytogenes là gì?",["Phát triển được ở nhiệt độ tủ lạnh (4°C)","Bị tiêu diệt hoàn toàn ở 30°C","Chỉ sống trong môi trường axit","Không thể nhiễm vào thực phẩm đông lạnh"],0,"Listeria có thể phát triển ở 4°C, nguy hiểm với phụ nữ mang thai.",2);
  add(1,"Staphylococcus aureus nguy hiểm vì lý do gì?",["Ngoại độc tố chịu nhiệt 100°C trong 30 phút, nấu chín không diệt được độc tố","Không thể bị tiêu diệt bởi hóa chất","Tự phát sáng trong đêm tối","Tạo hương vị thơm ngon giả tạo"],0,"Độc tố của S.aureus rất bền nhiệt, nấu chín chỉ diệt vi khuẩn nhưng không phá được độc tố.",2);
  add(1,"Clostridium botulinum gây nguy hiểm nhất ở sản phẩm nào?",["Đồ hộp kỵ khí pH > 4.6 không được thanh trùng đúng cách","Rau sống rửa kỹ","Trái cây tươi có vị chua","Nước khoáng đóng chai"],0,"C.botulinum phát triển trong môi trường kỵ khí như đồ hộp không thanh trùng đúng.",2);
  add(1,"Nguồn gốc hình thành Aflatoxin B1 trong thực phẩm là gì?",["Aspergillus flavus phát triển trên đậu phụng, bắp ẩm","Phản ứng hóa học giữa đường và muối","Công nhân không đeo găng tay","Nhiệt độ thanh trùng quá cao"],0,"Aflatoxin B1 do nấm mốc A.flavus sinh ra trên đậu phộng, ngô lưu trữ ẩm.",1);
  add(1,"Aflatoxin B1 gây tác hại gì cho sức khỏe người?",["Gây tổn thương tế bào gan và ung thư gan","Gây đau đầu nhẹ thoáng qua","Gây giảm thính lực","Làm đổi màu da tạm thời"],0,"Aflatoxin B1 là mycotoxin gây ung thư gan nguy hiểm nhất.",2);
  add(1,"Biện pháp phòng ngừa Aflatoxin B1 hiệu quả nhất là gì?",["Kiểm soát độ ẩm hạt ngô/lạc dưới 12% khi bảo quản","Rửa bằng nước chanh","Luộc ở 100°C trong 5 phút","Bao bọc bằng màng bọc thực phẩm"],0,"Kiểm soát độ ẩm dưới 12% ngăn nấm mốc phát triển sinh độc tố.",1);
  add(1,"Histamine trong cá ngừ, cá thu hình thành do nguyên nhân nào?",["Vi khuẩn phân hủy Histidine khi cá bảo quản không đúng nhiệt độ","Ánh nắng chiếu vào cá","Thêm hóa chất bảo quản","Đóng gói sai quy cách"],0,"Histamine sinh ra khi vi khuẩn phân hủy Histidine trong thịt cá ở nhiệt độ không kiểm soát.",2);
  add(1,"Mảnh kim loại từ máy cắt thuộc nhóm mối nguy nào?",["Mối nguy vật lý","Mối nguy vi sinh vật","Mối nguy hóa học","Mối nguy tâm lý"],0,"Mảnh kim loại là mối nguy vật lý cần kiểm soát bằng máy dò kim loại.",1);
  add(1,"Phương pháp kiểm soát mối nguy vật lý mảnh kim loại hiệu quả nhất là gì?",["Lắp máy dò kim loại (Metal Detector) ở đoạn cuối dây chuyền","Đun sôi ở 100°C","Hút chân không sản phẩm","Bổ sung chất chống oxy hóa"],0,"Metal Detector là biện pháp kiểm soát tiêu chuẩn cho mối nguy kim loại.",1);
  add(1,"Thực phẩm gây dị ứng (allergen) phải được xử lý như thế nào trên nhãn sản phẩm?",["Ghi rõ thông tin cảnh báo dị ứng cho người tiêu dùng","Giấu thông tin để tránh người tiêu dùng hoang mang","Chỉ ghi bằng tiếng nước ngoài","Không cần ghi nhãn"],0,"Allergen phải khai báo minh bạch trên nhãn theo quy định pháp luật.",1);
  add(1,"Tetrodotoxin có đặc điểm nguy hiểm gì?",["Độc tố thần kinh cực mạnh, gây liệt cơ hoành và tử vong, không có thuốc giải","Bị phân hủy hoàn toàn khi nấu chín","Chỉ gây dị ứng nhẹ","Dễ loại bỏ bằng cách ngâm nước"],0,"Tetrodotoxin từ cá nóc cực độc, không có thuốc giải đặc hiệu.",3);
  add(1,"'Ciguatoxin' là gì và gây ra hội chứng đặc trưng nào?",["Độc tố từ tảo Gambierdiscus trong cá rạn san hô, gây đảo ngược cảm giác nóng lạnh","Mycotoxin từ nấm mốc trên ngũ cốc","Vi khuẩn sống trong hải sản","Hóa chất tẩy trắng thực phẩm"],0,"Ciguatoxin gây hội chứng đảo ngược cảm giác nóng/lạnh đặc trưng.",3);
  add(1,"Dư lượng kháng sinh Chloramphenicol trong thủy sản bị phát hiện bằng phương pháp gì?",["ELISA hoặc LC-MS/MS","Nếm thử bằng cảm quan","Đo độ đục bằng mắt thường","Cân trọng lượng bằng cân tiểu ly"],0,"Chloramphenicol được phát hiện bằng phương pháp ELISA hoặc LC-MS/MS.",2);
  add(1,"Nguyên nhân hình thành Acrylamide trong khoai tây chiên là gì?",["Phản ứng Maillard giữa Asparagine và đường ở nhiệt độ >120°C","Vi khuẩn phân hủy tinh bột","Thêm hóa chất bảo quản","Ánh sáng UV chiếu vào sản phẩm"],0,"Acrylamide hình thành qua phản ứng Maillard trong chiên rán nhiệt độ cao.",3);
  add(1,"Formaldehyde (Formol) trong thực phẩm gây hại gì và cách phát hiện?",["Gây tổn thương niêm mạc, ung thư; phát hiện bằng bộ kit thử nhanh Formol","Gây mất ngủ tạm thời; phát hiện bằng mắt thường","Làm đổi màu thực phẩm; phát hiện bằng ngửi mùi","Gây đau đầu nhẹ; không cần kiểm tra"],0,"Formol là chất cực độc, phát hiện nhanh bằng kit chuyên dụng.",2);
  add(1,"Nguyên lý của 'Vệ sinh ngăn ngừa' (Preventive Hygiene) là gì?",["Phát hiện và kiểm soát mối nguy TRước khi chúng gây hại cho sản phẩm","Chỉ kiểm tra sản phẩm sau khi hoàn thiện","Dựa vào phân tích kết quả cuối để cải thiện","Tin tưởng vào ý thức tự giác của công nhân"],0,"Vệ sinh ngăn ngừa: kiểm soát mối nguy ngay từ đầu quá trình, không chờ sản phẩm lỗi.",2);
  add(1,"Theo 'Quy tắc 2 giờ', thực phẩm nấu chín cần được bảo quản lạnh hoặc ăn trong thời gian bao lâu?",["Trong vòng 2 giờ ở nhiệt độ phòng (hoặc 1 giờ nếu >32°C)","Trong vòng 8 giờ","Có thể để đến 24 giờ nếu đậy kín","Không cần giới hạn thời gian"],0,"Quy tắc 2 giờ: thực phẩm nấu chín cần bảo quản lạnh hoặc ăn trong 2 giờ.",1);

  // ═══════════════════════════════════════════════════
  // CHƯƠNG 2: HỆ THỐNG QLCL & CÔNG CỤ
  // ═══════════════════════════════════════════════════

  add(2,"Chu trình PDCA (Deming Cycle) gồm các bước nào?",["Plan (Lập kế hoạch) - Do (Thực hiện) - Check (Kiểm tra) - Act (Điều chỉnh)","Propose - Design - Create - Audit","Plan - Develop - Control - Approve","Predict - Deploy - Correct - Achieve"],0,"PDCA: Plan-Do-Check-Act là nền tảng cải tiến liên tục của ISO.",1);
  add(2,"ISO 9001 thuộc hệ thống tiêu chuẩn quản lý nào?",["Hệ thống quản lý chất lượng (Quality Management System - QMS)","Hệ thống quản lý môi trường","Hệ thống quản lý an toàn lao động","Hệ thống quản lý năng lượng"],0,"ISO 9001 là tiêu chuẩn QMS hàng đầu toàn cầu.",1);
  add(2,"ISO 22000 là tiêu chuẩn về lĩnh vực nào?",["Hệ thống quản lý an toàn thực phẩm (FSMS) toàn chuỗi cung ứng","Hệ thống quản lý môi trường nhà máy thực phẩm","Chứng nhận nông sản hữu cơ","Tiêu chuẩn đóng gói bao bì thực phẩm"],0,"ISO 22000 tích hợp HACCP và ISO 9001 cho quản lý ATTP toàn chuỗi cung ứng.",1);
  add(2,"Công cụ QC 'Biểu đồ Pareto' ứng dụng nguyên lý nào?",["Nguyên lý 80/20: 80% vấn đề do 20% nguyên nhân cốt lõi gây ra","Nguyên lý 50/50: phân chia đều các vấn đề","Nguyên lý 90/10: 90% lỗi do máy móc","Nguyên lý 70/30: 70% do con người"],0,"Biểu đồ Pareto dựa trên nguyên lý 80/20 để ưu tiên xử lý nguyên nhân cốt lõi.",1);
  add(2,"Sơ đồ Xương cá (Ishikawa) phân tích nguyên nhân theo nhóm nào?",["5M: Man, Machine, Material, Method, Measurement (Môi trường)","3M: Man, Material, Method","6S: Sort, Set, Shine, Standardize, Sustain, Safety","PDCA: Plan, Do, Check, Act"],0,"Ishikawa/Fishbone phân tích nguyên nhân gốc rễ theo 5M (hoặc 6M).",1);
  add(2,"Biểu đồ Kiểm soát (Control Chart) được dùng để làm gì?",["Theo dõi biến động quá trình theo thời gian với giới hạn UCL và LCL","Đếm số lỗi trong một lô hàng","Xác định nguyên nhân gốc rễ của sự cố","So sánh hiệu suất giữa các ca làm việc"],0,"Control Chart theo dõi ổn định quá trình theo thời gian với UCL/LCL.",1);
  add(2,"UCL và LCL trong Control Chart là gì?",["Upper Control Limit (Giới hạn kiểm soát trên) và Lower Control Limit (dưới)","Unit Cost Level và Labor Cost Level","Ultimate Check List và Labor Check List","User Control Logic và Lower Control Logic"],0,"UCL/LCL là giới hạn thống kê ±3σ kiểm soát biến động quá trình.",1);
  add(2,"'Histogram' (Biểu đồ tần số) trong QC dùng để làm gì?",["Hiển thị phân bố tần suất của dữ liệu đo lường liên tục","Xác định mối quan hệ giữa hai biến số","Phân tích nguyên nhân gốc rễ","Theo dõi biến động theo thời gian"],0,"Histogram cho thấy phân bố của dữ liệu, giúp nhận diện xu hướng và bất thường.",1);
  add(2,"Biểu đồ Phân tán (Scatter Diagram) dùng để kiểm tra điều gì?",["Mối quan hệ tương quan giữa hai biến số kỹ thuật","Số lượng lỗi theo thời gian","Phân bố chi phí sản xuất","Hiệu suất theo chương"],0,"Scatter Diagram xác định mức độ tương quan giữa 2 biến (dương/âm/không có).",2);
  add(2,"'Tờ kiểm tra' (Check Sheet) được sử dụng với mục đích chính là gì?",["Thu thập và ghi nhận dữ liệu một cách có hệ thống, chính xác tại nơi phát sinh","Phân tích thống kê dữ liệu phức tạp","Trình bày kết quả kiểm tra cho ban quản lý","Lưu trữ hồ sơ kiểm định thiết bị"],0,"Check Sheet là công cụ thu thập dữ liệu đơn giản, chính xác tại điểm phát sinh.",1);
  add(2,"'Phân tầng dữ liệu' (Stratification) trong 7 công cụ QC là gì?",["Phân chia dữ liệu thành nhóm nhỏ theo tiêu chí để tìm điểm khác biệt","Xếp hạng ưu tiên các vấn đề cần giải quyết","Vẽ biểu đồ phân bố dữ liệu","Theo dõi xu hướng thay đổi theo thời gian"],0,"Stratification chia nhỏ dữ liệu hỗn hợp để tìm ra nguồn gốc khác biệt.",2);
  add(2,"Kiểm soát quá trình bằng thống kê (SPC - Statistical Process Control) áp dụng khi nào?",["Khi muốn phát hiện sớm sự bất thường và ngăn ngừa sản phẩm lỗi","Chỉ khi đã phát sinh sản phẩm không đạt","Sau khi xuất hàng cho khách","Khi tuyển dụng nhân sự mới"],0,"SPC dùng dữ liệu thống kê để phát hiện bất thường sớm trước khi tạo ra lỗi.",2);
  add(2,"Yêu cầu 'Cải tiến liên tục' (Continual Improvement) trong ISO 9001 được thể hiện qua công cụ nào?",["PDCA (Plan-Do-Check-Act) và phân tích dữ liệu định kỳ","Chỉ thay thế máy móc cũ","Chỉ đào tạo lại nhân viên","Thuê thêm chuyên gia kiểm soát chất lượng"],0,"Cải tiến liên tục trong ISO 9001 được thực hiện qua vòng PDCA.",2);
  add(2,"'Đánh giá nội bộ' (Internal Audit) trong ISO 9001 có mục đích gì?",["Xác định mức độ tuân thủ hệ thống QMS và tìm cơ hội cải tiến","Chuẩn bị cho đánh giá bên ngoài để lấy chứng chỉ","Kiểm tra tài chính của doanh nghiệp","Đánh giá hiệu suất bán hàng"],0,"Internal Audit kiểm tra sự tuân thủ QMS và tìm cơ hội cải thiện nội bộ.",2);
  add(2,"Chứng chỉ ISO 22000 khác gì so với chứng chỉ HACCP?",["ISO 22000 tích hợp HACCP với quản lý hệ thống ISO, yêu cầu toàn diện hơn về tổ chức","HACCP yêu cầu toàn diện hơn ISO 22000","Hai chứng chỉ hoàn toàn giống nhau","HACCP chỉ dành cho doanh nghiệp xuất khẩu"],0,"ISO 22000 = HACCP + Yêu cầu hệ thống ISO (lãnh đạo, nguồn lực, cải tiến liên tục).",3);
  add(2,"Chỉ số Cpk trong SPC đo lường điều gì?",["Năng lực quá trình, cho thấy sản phẩm có đáp ứng dung sai kỹ thuật không","Tốc độ sản xuất trung bình","Tỷ lệ phế phẩm tuyệt đối","Chi phí kiểm tra chất lượng"],0,"Cpk đo năng lực quá trình so với dung sai kỹ thuật; Cpk≥1.33 là đạt chuẩn.",3);
  add(2,"Sự khác biệt giữa 'Kiểm soát chất lượng' (QC) và 'Đảm bảo chất lượng' (QA) là gì?",["QC là hoạt động kiểm tra phát hiện lỗi; QA là hệ thống ngăn ngừa lỗi xảy ra","QC và QA có nghĩa giống nhau","QA chỉ áp dụng cho sản phẩm xuất khẩu","QC là trách nhiệm ban quản lý; QA là trách nhiệm công nhân"],0,"QC = kiểm tra phát hiện lỗi; QA = xây dựng hệ thống ngăn ngừa lỗi từ đầu.",3);
  add(2,"'Không phù hợp' (Non-conformance/NCR) trong hệ thống QMS được xử lý như thế nào?",["Ghi nhận, phân tích nguyên nhân gốc rễ, thực hiện hành động khắc phục và theo dõi","Che giấu để không ảnh hưởng đến chứng chỉ ISO","Chỉ loại bỏ sản phẩm không đạt, không cần phân tích nguyên nhân","Phạt tiền nhân viên liên quan"],0,"NCR cần ghi nhận, phân tích nguyên nhân gốc rễ và có hành động khắc phục/phòng ngừa.",2);
  add(2,"'Hành động khắc phục' (Corrective Action) và 'Hành động phòng ngừa' (Preventive Action) khác nhau thế nào?",["Khắc phục: xử lý vấn đề đã xảy ra; Phòng ngừa: ngăn vấn đề tiềm ẩn xảy ra","Khắc phục và phòng ngừa có nghĩa giống nhau","Phòng ngừa chỉ áp dụng sau khi sự cố xảy ra","Khắc phục là trách nhiệm kỹ thuật; phòng ngừa là trách nhiệm quản lý"],0,"Corrective Action sửa lỗi đã xảy ra; Preventive Action ngăn ngừa lỗi tiềm ẩn.",2);
  add(2,"BRC (British Retail Consortium) Food Safety Standard là gì?",["Tiêu chuẩn an toàn thực phẩm được nhiều nhà bán lẻ Anh/Châu Âu yêu cầu","Tiêu chuẩn ISO cho thực phẩm của Vương quốc Anh","Chứng chỉ hữu cơ tại Anh","Quy định nhập khẩu thực phẩm của EU"],0,"BRC Food là tiêu chuẩn an toàn thực phẩm do nhà bán lẻ Anh thiết lập, được công nhận toàn cầu.",2);

  // ═══════════════════════════════════════════════════
  // CHƯƠNG 3: ĐIỀU KIỆN TIÊN QUYẾT (GMP, SSOP)
  // ═══════════════════════════════════════════════════

  add(3,"GMP là viết tắt của gì?",["Good Manufacturing Practice (Thực hành sản xuất tốt)","General Management Process","Global Market Protocol","Green Manufacturing Program"],0,"GMP = Good Manufacturing Practice: thực hành sản xuất tốt.",1);
  add(3,"Mục tiêu chính của GMP là gì?",["Đảm bảo điều kiện sản xuất vệ sinh để tránh ô nhiễm và đảm bảo chất lượng","Tối đa hóa năng suất sản xuất","Giảm chi phí nguyên liệu đầu vào","Tăng doanh số bán hàng"],0,"GMP đảm bảo điều kiện sản xuất vệ sinh, ngăn ô nhiễm thực phẩm.",1);
  add(3,"SSOP là viết tắt của gì?",["Sanitation Standard Operating Procedures (Quy trình vệ sinh tiêu chuẩn)","Safety Standard Operating Procedures","Standard Sanitation and Organization Process","System Safety Operation Protocol"],0,"SSOP = Sanitation Standard Operating Procedures: quy trình vệ sinh tiêu chuẩn.",1);
  add(3,"Có bao nhiêu lĩnh vực/yếu tố GMP cơ bản trong sản xuất thực phẩm?",["4 lĩnh vực chính: Nhà xưởng, Thiết bị/Dụng cụ, Quá trình sản xuất, Con người","2 lĩnh vực: Sản phẩm và Quy trình","6 lĩnh vực: 5M+E","10 lĩnh vực theo tiêu chuẩn FDA"],0,"GMP gồm 4 lĩnh vực: Nhà xưởng, Thiết bị/Dụng cụ, Quá trình SX, Con người.",1);
  add(3,"Yêu cầu GMP đối với thiết kế nhà xưởng sản xuất thực phẩm là gì?",["Thiết kế theo nguyên tắc một chiều, tách biệt vùng bẩn/sạch, dễ vệ sinh","Thiết kế đẹp để thu hút khách hàng tham quan","Tối đa hóa diện tích kho chứa nguyên liệu","Đặt gần chợ để tiện vận chuyển"],0,"Nhà xưởng GMP: luồng một chiều, phân vùng sạch/bẩn rõ ràng, dễ vệ sinh khử trùng.",2);
  add(3,"'Phân vùng kiểm soát' (Zoning) trong nhà máy thực phẩm có nghĩa là gì?",["Phân chia nhà máy thành các khu vực với mức độ vệ sinh kiểm soát khác nhau","Phân chia diện tích cho các phòng ban","Quy hoạch bãi đậu xe cho nhà máy","Phân chia ca làm việc cho nhân viên"],0,"Zoning phân nhà máy theo Risk Zone: vùng nguy cơ cao/thấp với kiểm soát khác nhau.",3);
  add(3,"SSOP có bao nhiêu yếu tố/lĩnh vực cơ bản cần xây dựng?",["8 lĩnh vực (theo FDA/Codex)","4 lĩnh vực","12 lĩnh vực","5 lĩnh vực"],0,"SSOP gồm 8 lĩnh vực: nước, bề mặt tiếp xúc, ngăn ngừa nhiễm chéo, rửa tay, bảo vệ sản phẩm, hóa chất, sức khỏe công nhân, kiểm soát sinh vật.",1);
  add(3,"Một trong những yêu cầu GMP về vệ sinh cá nhân là gì?",["Rửa tay đúng kỹ thuật trước khi vào khu sản xuất, sau khi vệ sinh cá nhân","Đeo nhẫn và đồng hồ để nhận diện nhân viên","Sử dụng nước hoa thơm trong khu sản xuất","Không cần thay đồng phục khi chuyển giữa các khu vực"],0,"Vệ sinh cá nhân GMP: rửa tay đúng cách là yêu cầu cơ bản nhất.",1);
  add(3,"Nước sử dụng trong chế biến thực phẩm phải đáp ứng tiêu chuẩn nào?",["Nước uống được (potable water) theo QCVN 01-1:2018/BYT","Nước máy thông thường không cần xử lý thêm","Nước giếng khoan chưa xử lý","Nước hồ lắng qua bể lọc cát thô"],0,"Nước dùng trong chế biến ATTP phải đạt tiêu chuẩn nước uống được QCVN 01-1.",1);
  add(3,"Quy trình CIP (Cleaning In Place) dùng để làm gì?",["Vệ sinh đường ống, thiết bị kín mà không cần tháo rời","Kiểm tra chất lượng sản phẩm cuối cùng","Phân tích vi sinh vật trong không khí nhà máy","Bảo trì thiết bị định kỳ"],0,"CIP vệ sinh đường ống thiết bị mà không cần tháo lắp, tiết kiệm thời gian.",2);
  add(3,"Hóa chất vệ sinh trong nhà máy thực phẩm phải được bảo quản như thế nào?",["Khu vực riêng biệt, có nhãn rõ ràng, khóa cẩn thận, tách xa thực phẩm","Để chung với nguyên liệu thực phẩm cho tiện sử dụng","Bất kỳ nơi nào miễn là có nắp đậy","Chỉ cần đặt ở góc khuất trong kho"],0,"Hóa chất vệ sinh phải tách riêng, có nhãn, khóa và không để gần thực phẩm.",1);
  add(3,"'Kiểm soát sinh vật gây hại' (Pest Control) trong SSOP bao gồm những biện pháp nào?",["Ngăn chặn xâm nhập + Theo dõi bẫy + Tiêu diệt và giữ hồ sơ","Chỉ đặt bẫy chuột định kỳ","Chỉ phun thuốc diệt côn trùng","Chỉ đóng cửa sổ vào ban đêm"],0,"Pest Control: phòng ngừa xâm nhập + giám sát bẫy + tiêu diệt + hồ sơ ghi chép.",2);
  add(3,"Nhân viên mang mầm bệnh đường tiêu hóa (như tiêu chảy, nôn mửa) cần làm gì?",["Tạm thời không tham gia sản xuất thực phẩm cho đến khi khỏi bệnh","Vẫn làm việc bình thường nhưng đeo khẩu trang","Chỉ làm việc ở khu vực đóng gói","Uống thuốc và tiếp tục làm việc"],0,"Nhân viên mang mầm bệnh phải báo cáo và tạm thời không tham gia tiếp xúc thực phẩm.",1);
  add(3,"Tần suất hiệu chỉnh/kiểm định thiết bị đo lường (cân, nhiệt kế) trong GMP?",["Định kỳ theo lịch đã đặt ra hoặc khi có nghi ngờ không chính xác","Chỉ khi thiết bị bị hỏng hoàn toàn","Một lần khi lắp đặt ban đầu, không cần làm lại","Mỗi 10 năm một lần"],0,"Thiết bị đo phải được hiệu chỉnh định kỳ và khi nghi ngờ để đảm bảo độ chính xác.",2);
  add(3,"Tiêu chí phân biệt GMP và SSOP là gì?",["GMP quy định điều kiện cơ sở vật chất và quy trình SX; SSOP quy định quy trình vệ sinh cụ thể","GMP và SSOP là cùng một khái niệm","GMP dành cho nhà máy lớn; SSOP dành cho cơ sở nhỏ","GMP do FDA quy định; SSOP do WHO quy định"],0,"GMP = điều kiện và quy trình sản xuất tổng thể; SSOP = chi tiết quy trình vệ sinh.",2);
  add(3,"Điều kiện bảo quản nguyên liệu thực phẩm theo GMP phải đảm bảo gì?",["FIFO (First In First Out), nhiệt độ phù hợp, tách biệt dị ứng nguyên và chín","LIFO (Last In First Out) cho tiện lấy hàng","Để cùng hóa chất tẩy rửa cho gọn","Không cần ghi hạn sử dụng nếu chưa mở"],0,"FIFO và kiểm soát nhiệt độ là nguyên tắc cơ bản của GMP trong kho bảo quản.",2);

  // ═══════════════════════════════════════════════════
  // CHƯƠNG 4: HACCP & ISO 22000
  // ═══════════════════════════════════════════════════

  add(4,"HACCP là viết tắt của gì?",["Hazard Analysis and Critical Control Points","Hygiene Analysis and Control Certification Program","Health Assessment and Compliance Checkpoint Protocol","Hazard Avoidance and Chemical Control Procedure"],0,"HACCP = Hazard Analysis and Critical Control Points: Phân tích mối nguy và điểm kiểm soát tới hạn.",1);
  add(4,"HACCP gồm mấy nguyên tắc cơ bản?",["7 nguyên tắc","5 nguyên tắc","10 nguyên tắc","12 nguyên tắc"],0,"HACCP có 7 nguyên tắc cốt lõi theo Codex Alimentarius.",1);
  add(4,"Nguyên tắc 1 của HACCP là gì?",["Phân tích mối nguy (Hazard Analysis)","Xác định Điểm kiểm soát tới hạn (CCP)","Thiết lập giới hạn tới hạn","Thẩm định hệ thống"],0,"Nguyên tắc 1 HACCP: Tiến hành phân tích mối nguy (HA).",1);
  add(4,"Điểm kiểm soát tới hạn (CCP - Critical Control Point) là gì?",["Bước trong quá trình mà việc kiểm soát có thể ngăn/giảm mối nguy đến mức chấp nhận được","Mọi điểm kiểm tra chất lượng trong nhà máy","Bước thanh trùng bắt buộc trong mọi quy trình","Điểm cuối cùng trước khi xuất kho"],0,"CCP là điểm quan trọng nhất trong quy trình, nơi kiểm soát có thể loại bỏ mối nguy.",2);
  add(4,"'Giới hạn tới hạn' (Critical Limit) trong HACCP là gì?",["Giá trị tới hạn phân biệt điều kiện an toàn và không an toàn tại CCP","Ngưỡng chất lượng cảm quan của sản phẩm","Giới hạn chi phí sản xuất tối đa","Nhiệt độ bảo quản kho lạnh"],0,"Critical Limit là ngưỡng định lượng (ví dụ: nhiệt độ tối thiểu 70°C trong 2 phút).",2);
  add(4,"Nguyên tắc thứ 4 của HACCP là gì?",["Thiết lập hệ thống giám sát tại các CCP","Phân tích mối nguy","Xác định biện pháp khắc phục","Thẩm định và xác nhận"],0,"Nguyên tắc 4 HACCP: Giám sát CCP theo thông số đã định.",1);
  add(4,"Khi giám sát CCP phát hiện mất kiểm soát, hành động cần thực hiện ngay là gì?",["Hành động khắc phục (Corrective Action) ngay lập tức và ghi nhận hồ sơ","Tiếp tục sản xuất và báo cáo sau ca làm việc","Dừng toàn nhà máy và chờ chuyên gia","Đền bù cho khách hàng"],0,"Khi CCP mất kiểm soát, phải áp dụng Corrective Action ngay và ghi hồ sơ.",2);
  add(4,"'Cây quyết định CCP' (Decision Tree) dùng để làm gì?",["Xác định một bước trong quy trình có phải là CCP hay không","Phân tích chi phí sản xuất","Lập kế hoạch kiểm tra đầu vào","Đánh giá hiệu suất công nhân"],0,"Decision Tree là công cụ hỗ trợ xác định CCP theo 4 câu hỏi chuẩn.",2);
  add(4,"Kế hoạch HACCP bắt buộc phải bao gồm những gì?",["Mô tả sản phẩm, sơ đồ dây chuyền, phân tích mối nguy, CCP và Giới hạn tới hạn, Giám sát, Khắc phục, Thẩm định, Hồ sơ","Chỉ cần sơ đồ quy trình sản xuất","Chỉ cần danh sách CCP và nhiệt độ xử lý","Chỉ cần chứng nhận từ cơ quan nhà nước"],0,"Kế hoạch HACCP đầy đủ gồm 7 nguyên tắc được triển khai thành tài liệu cụ thể.",3);
  add(4,"Điểm kiểm soát (CP) khác Điểm kiểm soát tới hạn (CCP) như thế nào?",["CP kiểm soát chất lượng, CCP kiểm soát an toàn thực phẩm; mất kiểm soát CCP gây nguy hiểm ngay","CP quan trọng hơn CCP","CP và CCP có nghĩa giống nhau","CCP áp dụng cho xuất khẩu, CP cho nội địa"],0,"CP kiểm soát chất lượng; CCP kiểm soát ATTP - mất kiểm soát CCP là mất an toàn.",3);
  add(4,"Nguyên tắc 7 của HACCP là gì?",["Thiết lập hệ thống hồ sơ và tài liệu (Record keeping)","Phân tích mối nguy","Xác định CCP","Thiết lập giới hạn tới hạn"],0,"Nguyên tắc 7 HACCP: Duy trì hệ thống tài liệu hồ sơ đầy đủ.",1);
  add(4,"'Thẩm định' (Validation) trong HACCP có nghĩa là gì?",["Xác nhận bằng chứng khoa học rằng các biện pháp kiểm soát có hiệu quả","Kiểm tra hồ sơ tài liệu của hệ thống","Đào tạo nhân viên về HACCP","Kiểm tra cảm quan sản phẩm cuối"],0,"Validation xác nhận bằng khoa học rằng kế hoạch HACCP có hiệu lực.",3);
  add(4,"ISO 22000:2018 tích hợp những yếu tố nào?",["HACCP + Hệ thống quản lý ISO + PRP (Điều kiện tiên quyết)","Chỉ HACCP phiên bản mới","ISO 9001 + Môi trường + ATTP","FSSC + BRC + SQF"],0,"ISO 22000:2018 tích hợp HACCP, hệ thống quản lý ISO và PRPs vào một khung thống nhất.",3);
  add(4,"PRP (Prerequisite Programs) trong ISO 22000 là gì?",["Các điều kiện tiên quyết (GMP, SSOP) để tạo môi trường phù hợp áp dụng HACCP","Phần bổ sung tùy chọn của ISO 22000","Tài liệu hồ sơ bắt buộc","Chứng chỉ cần có trước khi đăng ký ISO 22000"],0,"PRP = GMP, SSOP và các điều kiện tiên quyết tạo nền tảng cho HACCP.",1);
  add(4,"Mô tả sản phẩm trong kế hoạch HACCP cần bao gồm thông tin gì?",["Đặc điểm sản phẩm, thành phần, điều kiện bảo quản, hạn sử dụng, đối tượng sử dụng dự kiến","Chỉ cần tên sản phẩm và giá bán","Chỉ cần thành phần nguyên liệu chính","Chỉ cần tên nhà sản xuất"],0,"Mô tả sản phẩm HACCP phải đầy đủ để nhóm HACCP phân tích mối nguy chính xác.",2);
  add(4,"Nhóm HACCP (HACCP Team) cần có thành phần như thế nào?",["Đa ngành: sản xuất, chất lượng, kỹ thuật, logistics, R&D","Chỉ cần trưởng bộ phận QC","Chỉ cần giám đốc nhà máy ký tên","Chỉ cần chuyên gia tư vấn bên ngoài"],0,"Nhóm HACCP cần đa dạng chuyên môn để phân tích mối nguy toàn diện.",2);

  // ═══════════════════════════════════════════════════
  // CHƯƠNG 5: LUẬT AN TOÀN THỰC PHẨM VIỆT NAM
  // ═══════════════════════════════════════════════════

  add(5,"Luật An toàn thực phẩm Việt Nam được ban hành năm nào?",["Năm 2010 (Luật số 55/2010/QH12)","Năm 2005","Năm 2015","Năm 2018"],0,"Luật ATTP Việt Nam được Quốc hội thông qua năm 2010, hiệu lực từ 7/2011.",1);
  add(5,"Cơ quan nào chịu trách nhiệm chính quản lý an toàn thực phẩm tại Việt Nam?",["Bộ Y tế, Bộ Nông nghiệp và PTNT, Bộ Công Thương (phân công theo loại sản phẩm)","Chỉ Bộ Y tế","Chỉ Bộ Nông nghiệp và PTNT","Chỉ Bộ Công Thương"],0,"ATTP VN được phân công cho 3 Bộ: Y tế (thực phẩm chế biến), NN&PTNT (nông sản), Công Thương (phân phối).",2);
  add(5,"Giấy chứng nhận cơ sở đủ điều kiện ATTP phải được cấp bởi cơ quan nào?",["Cơ quan nhà nước có thẩm quyền theo phân công của từng loại sản phẩm","Chỉ Bộ Y tế cấp mọi loại","Phòng Thương mại và Công nghiệp (VCCI)","Hiệp hội thực phẩm Việt Nam"],0,"Cơ quan cấp GCN đủ điều kiện ATTP tùy loại thực phẩm: Bộ Y tế, NN&PTNT hoặc Công Thương.",1);
  add(5,"Các nội dung BẮT BUỘC phải ghi trên nhãn thực phẩm theo Nghị định 43/2017 là gì?",["Tên hàng hóa, tổ chức chịu trách nhiệm, định lượng, NSX, HSD, thành phần, xuất xứ","Chỉ cần tên sản phẩm và NSX","Chỉ cần HSD và tên nhà sản xuất","Chỉ cần mã vạch và logo chứng nhận"],0,"NĐ 43/2017 quy định bắt buộc: tên, tổ chức trách nhiệm, định lượng, NSX/HSD, thành phần, cảnh báo, xuất xứ.",2);
  add(5,"Phụ gia thực phẩm được sử dụng khi nào theo Luật ATTP?",["Khi nằm trong danh mục được phép và không vượt giới hạn tối đa quy định","Bất kỳ lúc nào miễn là không tạo mùi lạ","Chỉ cần sự chấp thuận của khách hàng","Khi sản phẩm cần có màu đẹp hơn"],0,"Phụ gia thực phẩm chỉ được dùng khi có trong danh mục phép và đúng liều lượng.",1);
  add(5,"'Truy xuất nguồn gốc thực phẩm' (Food Traceability) được yêu cầu để làm gì?",["Xác định nguồn gốc nguyên liệu, nơi sản xuất, phân phối khi xảy ra sự cố","Tăng giá trị thương hiệu sản phẩm","Giảm chi phí vận chuyển","Tự động hóa quy trình sản xuất"],0,"Truy xuất nguồn gốc cho phép thu hồi sản phẩm nhanh khi phát sinh sự cố ATTP.",2);
  add(5,"Thực phẩm chức năng (Functional Food) cần điều kiện gì để được phép lưu hành?",["Phải được Bộ Y tế cấp phép và công bố sản phẩm trước khi lưu hành","Chỉ cần đăng ký thương hiệu","Không cần đăng ký nếu sản xuất theo quy trình GMP","Chỉ cần phân tích dinh dưỡng từ phòng thí nghiệm"],0,"Thực phẩm chức năng phải công bố và đăng ký với Bộ Y tế trước khi lưu hành.",2);
  add(5,"Hành vi 'sử dụng chất cấm trong sản xuất thực phẩm' bị xử lý như thế nào?",["Xử phạt hành chính hoặc truy cứu trách nhiệm hình sự tùy mức độ","Chỉ bị thu hồi lô hàng vi phạm","Chỉ bị cảnh cáo lần đầu","Không bị xử lý nếu lượng nhỏ"],0,"Sử dụng chất cấm có thể bị truy cứu hình sự theo Điều 317 Bộ luật Hình sự 2015.",3);
  add(5,"Thời hạn giải quyết khiếu nại về chất lượng ATTP theo quy định là bao lâu?",["Theo Luật Khiếu nại 2011: 30 ngày (hoặc 45 ngày với vụ phức tạp)","7 ngày làm việc","60 ngày","Không có quy định cụ thể"],0,"Khiếu nại ATTP theo Luật Khiếu nại: 30 ngày giải quyết, 45 ngày với vụ phức tạp.",2);
  add(5,"Quy định về 'Quảng cáo thực phẩm chức năng' theo Luật Quảng cáo là gì?",["Không được quảng cáo có tác dụng điều trị bệnh nếu không có căn cứ khoa học","Được quảng cáo bất kỳ công dụng nào","Phải quảng cáo theo mẫu của nhà nước","Chỉ được quảng cáo trên mạng xã hội"],0,"Quảng cáo TPCN phải trung thực, không được khẳng định chữa bệnh nếu chưa được phép.",2);
  add(5,"Kiểm nghiệm thực phẩm phục vụ quản lý nhà nước phải được thực hiện bởi ai?",["Phòng kiểm nghiệm được chỉ định/công nhận theo quy định của Nhà nước","Bất kỳ phòng lab nào có thiết bị","Tự kiểm tra tại nhà máy","Tổ chức quốc tế"],0,"Kiểm nghiệm QLNN phải qua lab được chỉ định/công nhận theo quy định pháp luật.",1);
  add(5,"Nghị định 15/2018/NĐ-CP thay thế Nghị định nào và có điểm mới gì?",["Thay thế NĐ 38/2012, đơn giản hóa thủ tục tự công bố thực phẩm thông thường","Thay thế NĐ 43/2017 về nhãn hàng hóa","Thay thế Luật ATTP 2010","Thay thế NĐ 178/2013 về xử phạt vi phạm"],0,"NĐ 15/2018 thay NĐ 38/2012, cho phép doanh nghiệp tự công bố thực phẩm thông thường.",3);
  add(5,"Thực phẩm nhập khẩu vào Việt Nam cần đáp ứng điều kiện gì?",["Phải kiểm tra nhà nước về ATTP tại cửa khẩu, có giấy tờ hợp lệ","Chỉ cần giấy tờ hải quan thông thường","Không cần kiểm tra nếu từ nước phát triển","Chỉ cần nhãn bằng tiếng Anh"],0,"Thực phẩm NK phải qua kiểm tra nhà nước tại cửa khẩu và đáp ứng quy chuẩn VN.",2);
  add(5,"'Điều kiện bảo đảm ATTP trong sản xuất, kinh doanh thực phẩm tươi sống' được quy định ở đâu?",["Nghị định 15/2018 và các thông tư hướng dẫn của Bộ NN&PTNT","Chỉ trong Luật ATTP 2010","Chỉ trong tiêu chuẩn Codex","Không có quy định cụ thể"],0,"Thực phẩm tươi sống do Bộ NN&PTNT quản lý theo NĐ 15/2018 và thông tư hướng dẫn.",2);
  add(5,"Hành vi nào sau đây vi phạm Luật An toàn thực phẩm?",["Sử dụng hàn the (Borax) trong chế biến thực phẩm","Sử dụng phụ gia đúng danh mục và liều lượng","Ghi nhãn đầy đủ theo quy định","Kiểm nghiệm sản phẩm định kỳ"],0,"Hàn the là chất bị cấm dùng trong thực phẩm tại Việt Nam.",1);

  add(1, "Khái niệm \"chất lượng thực phẩm\" được định nghĩa là gì?", ["Tập hợp các thuộc tính của sản phẩm nhằm thỏa mãn nhu cầu người tiêu dùng trong những điều kiện nhất định", "Việc bảo đảm thực phẩm không gây hại đến sức khỏe và tính mạng con người", "Giá thành thấp nhất của sản phẩm trên thị trường", "Quy trình sản xuất nhanh và chi phí thấp"], 0, "Định nghĩa này nêu rõ chất lượng là tập hợp các thuộc tính đáp ứng nhu cầu người tiêu dùng.", 1);
  add(1, "Trong năm thuộc tính cơ bản của chất lượng thực phẩm, thuộc tính nào không được liệt kê trong nội dung?", ["Chất lượng dinh dưỡng", "Chất lượng vệ sinh", "Chất lượng cảm quan", "Chất lượng giá cả"], 3, "Các thuộc tính gồm dinh dưỡng, vệ sinh, cảm quan, sử dụng và công nghệ; không có thuộc tính \"giá cả\".", 1);
  add(1, "Yếu tố nào sau đây ảnh hưởng trực tiếp đến an toàn thực phẩm thông qua nguồn ô nhiễm?", ["Thiết kế bao bì hiện đại", "Nguồn ô nhiễm từ đất, nước, không khí hoặc điều kiện vệ sinh kém", "Chiến lược marketing sản phẩm", "Giá bán lẻ của thực phẩm"], 1, "Nguồn ô nhiễm môi trường là yếu tố trực tiếp gây nguy cơ an toàn thực phẩm.", 1);
  add(1, "Mối quan hệ giữa an toàn thực phẩm và chất lượng thực phẩm được mô tả như thế nào?", ["An toàn thực phẩm là tùy chọn nếu chất lượng cảm quan cao", "An toàn thực phẩm là điều kiện tiên quyết của chất lượng thực phẩm", "Chất lượng chỉ phụ thuộc vào giá trị dinh dưỡng", "An toàn và chất lượng không liên quan đến nhau"], 1, "An toàn thực phẩm là thuộc tính bắt buộc, không thể tách rời của chất lượng.", 1);
  add(1, "Ai chịu trách nhiệm trực tiếp trong việc kiểm soát nguyên liệu và quy trình để đảm bảo chất lượng sản phẩm?", ["Người tiêu dùng", "Nhà sản xuất và cơ sở chế biến", "Cơ quan quản lý nhà nước", "Nhà bán lẻ"], 1, "Nhà sản xuất và cơ sở chế biến là bên chịu trách nhiệm chính về chất lượng và an toàn.", 1);
  add(1, "Công ty A sản xuất nước ép trái cây có mùi vị rất thơm ngon, màu sắc bắt mắt và giàu vitamin, tuy nhiên lô hàng bị phát hiện chứa tồn dư thuốc bảo vệ thực vật vượt ngưỡng cho phép. Theo nguyên tắc quản lý chất lượng thực phẩm, lô sản phẩm này được đánh giá như thế nào?", ["Vẫn là sản phẩm chất lượng cao vì có giá trị cảm quan và dinh dưỡng vượt trội.", "Không có giá trị sử dụng vì an toàn thực phẩm là điều kiện tiên quyết của chất lượng.", "Đạt chất lượng trung bình do điểm cảm quan bù đắp cho chỉ tiêu an toàn.", "Chỉ cần giảm giá bán và ghi rõ cảnh báo trên nhãn là có thể tiêu thụ."], 1, "An toàn thực phẩm là điều kiện tiên quyết. Một sản phẩm dù có giá trị cảm quan hay dinh dưỡng cao nhưng không an toàn thì được xem là không có giá trị sử dụng.", 2);
  add(1, "Một doanh nghiệp chế biến thực phẩm tiến hành thay đổi bao bì sản phẩm cháo ăn liền sang dạng túi nhôm chịu nhiệt có thể quay trực tiếp trong lò vi sóng, đồng thời in bổ sung mã QR truy xuất nguồn gốc và chi tiết bảng thành phần dinh dưỡng. Doanh nghiệp này đang tập trung cải thiện thuộc tính chất lượng nào?", ["Chất lượng cảm quan", "Chất lượng công nghệ", "Chất lượng sử dụng", "Chất lượng vệ sinh"], 2, "Chất lượng sử dụng thể hiện ở tính tiện lợi cho người dùng như bao bì, khả năng bảo quản, thông tin ghi nhãn và sự phù hợp về sử dụng.", 2);
  add(1, "Một trang trại nuôi cá hồi phát hiện nguồn nước cấp vào bể nuôi bị nhiễm kim loại nặng do chất thải từ nhà máy khai thác khoáng sản phía thượng nguồn. Đây là ví dụ về yếu tố nào ảnh hưởng đến an toàn thực phẩm?", ["Nhu cầu và kỳ vọng của người tiêu dùng", "Môi trường sản xuất", "Thuộc tính chất lượng công nghệ", "Phòng vệ thực phẩm"], 1, "Môi trường sản xuất (đất, nước, không khí...) ảnh hưởng trực tiếp đến an toàn thực phẩm; nguồn nước ô nhiễm có thể làm nhiễm kim loại nặng vào thực phẩm.", 2);
  add(1, "Nhà máy sản xuất sữa B thiết lập hệ thống camera giám sát 24/7 và kiểm soát an ninh nghiêm ngặt bằng thẻ từ tại khu vực bồn chứa nguyên liệu nhằm ngăn chặn hành vi cố ý bỏ chất độc vào sản phẩm từ kẻ xấu. Hoạt động này thuộc lĩnh vực quản lý nào?", ["Kiểm soát chất lượng cảm quan", "Phòng vệ thực phẩm", "Nâng cao chất lượng dinh dưỡng", "Tối ưu hóa chất lượng công nghệ"], 1, "Phòng vệ thực phẩm là việc ngăn ngừa các hành vi gây nhiễm bẩn cố ý hoặc phá hoại thực phẩm trong chuỗi cung ứng.", 2);
  add(1, "Trong quá trình kiểm nghiệm lô hàng thịt hộp xuất khẩu, cơ quan chức năng phát hiện vi khuẩn vi sinh vật gây bệnh Salmonella vượt quá giới hạn cho phép. Lô hàng này đã vi phạm trực tiếp thuộc tính chất lượng nào?", ["Chất lượng vệ sinh", "Chất lượng cảm quan", "Chất lượng công nghệ", "Chất lượng sử dụng"], 0, "Chất lượng vệ sinh yêu cầu thực phẩm không chứa vi sinh vật gây bệnh, độc tố, hóa chất độc hại hoặc dị vật vượt mức cho phép.", 2);
  add(1, "Trong năm thuộc tính cơ bản của chất lượng thực phẩm được nêu trong chương 1, thuộc tính nào sau đây không thuộc danh sách?", ["Chất lượng dinh dưỡng", "Chất lượng vệ sinh", "Chất lượng cảm quan", "Chất lượng giá trị thương hiệu"], 3, "Các thuộc tính gồm dinh dưỡng, vệ sinh, cảm quan, sử dụng và công nghệ; không có thuộc tính \"giá trị thương hiệu\".", 3);
  add(1, "Trong đánh giá rủi ro an toàn thực phẩm, yếu tố nào dưới đây ảnh hưởng trực tiếp tới nguy cơ nhiễm độc hoá học từ môi trường?", ["Nguồn nguyên liệu sinh học", "Ô nhiễm đất, nước, không khí", "Quy trình chế biến nhiệt", "Thiết kế bao bì"], 1, "Ô nhiễm môi trường (đất, nước, không khí) là nguồn chính của các chất hoá học độc hại như kim loại nặng.", 3);
  add(1, "Yếu tố nào được quy định là bắt buộc để đảm bảo khả năng truy xuất nguồn gốc trong chuỗi cung ứng thực phẩm?", ["Ghi nhãn đầy đủ", "Kiểm soát vệ sinh nhà xưởng", "Đánh giá rủi ro HACCP", "Đóng gói bảo quản"], 0, "Ghi nhãn cung cấp thông tin về nguồn gốc, là tiền đề cho hệ thống truy xuất nguồn gốc.", 3);
  add(1, "Biện pháp nào sau đây giảm trực tiếp khả năng xảy ra mối nguy vật lý trong thực phẩm?", ["Thực hiện HACCP", "Cải thiện thiết kế bao bì", "Thực hiện kiểm nghiệm cảm quan", "Tăng giá bán sản phẩm"], 1, "Bao bì thiết kế tốt ngăn chặn vật thể ngoại lai (kim loại, thủy tinh) xâm nhập vào thực phẩm.", 3);
  add(1, "Trong 8 nguyên tắc của ISO 9000, nguyên tắc nào nhấn mạnh việc đáp ứng nhu cầu và nâng cao sự hài lòng của khách hàng?", ["Sự lãnh đạo", "Tập trung vào khách hàng", "Cải tiến liên tục", "Quyết định dựa trên bằng chứng"], 1, "Nguyên tắc \"Tập trung vào khách hàng\" đề cập tới việc đáp ứng nhu cầu và nâng cao sự hài lòng của khách hàng.", 1);
  add(1, "Phương pháp quản lý chất lượng nào tập trung xây dựng hệ thống quản lý toàn bộ quá trình nhằm phòng ngừa sai lỗi?", ["Kiểm soát chất lượng (QC)", "Đảm bảo chất lượng (QA)", "Quản lý chất lượng toàn diện (TQM)", "Các chương trình tiên quyết (PRPs)"], 1, "Đảm bảo chất lượng (QA) xây dựng hệ thống quản lý toàn bộ quá trình để phòng ngừa sai lỗi.", 1);
  add(1, "HACCP là viết tắt của cụm từ nào?", ["Hazard Analysis and Critical Control Points", "Hazard Assessment and Control Procedures", "Health Assurance and Consumer Protection", "Hazardous Activity and Critical Process"], 0, "HACCP viết tắt của Hazard Analysis and Critical Control Points.", 1);
  add(1, "Trong chuỗi cung ứng thực phẩm, giai đoạn nào thường có nguy cơ cao nhất về nhiễm chéo vi sinh vật?", ["Sản xuất nguyên liệu", "Chế biến và sơ chế", "Phân phối và lưu kho", "Bán lẻ và dịch vụ thực phẩm"], 1, "Giai đoạn chế biến và sơ chế là nơi dễ xảy ra nhiễm chéo vi sinh do xử lý nguyên liệu và môi trường làm việc.", 1);
  add(1, "Cơ quan nào chịu trách nhiệm cấp chứng nhận theo tiêu chuẩn ISO 22000?", ["Tổ chức Tiêu chuẩn Quốc tế (ISO)", "Tổ chức Y tế Thế giới (WHO)", "Liên minh Nông nghiệp (FAO)", "Ủy ban Codex"], 0, "ISO là tổ chức chịu trách nhiệm phát hành và cấp chứng nhận tiêu chuẩn ISO 22000.", 1);
  add(1, "Một công ty phân phối sữa tươi phát hiện hàng loạt lô hàng bị hư hỏng dù quy trình sản xuất tại nhà máy đạt chuẩn HACCP. Qua kiểm tra, phát hiện xe tải vận chuyển không duy trì đủ độ lạnh. Sự cố này thuộc rủi ro ở giai đoạn nào trong chuỗi cung ứng?", ["Giai đoạn sản xuất nguyên liệu", "Giai đoạn sơ chế và chế biến", "Giai đoạn phân phối và lưu kho", "Giai đoạn bán lẻ và dịch vụ thực phẩm"], 2, "Rủi ro đứt gãy chuỗi lạnh và không kiểm soát tốt nhiệt độ bảo quản là nguyên nhân hư hỏng sản phẩm thuộc giai đoạn phân phối và lưu kho.", 2);
  add(1, "Nhà máy sản xuất đồ hộp chuyển từ việc kiểm tra vi sinh trên sản phẩm cuối cùng sang việc kiểm soát điều kiện vệ sinh nhà xưởng, chuẩn hóa quy trình và giám sát nhiệt độ trong từng công đoạn. Sự chuyển đổi này thể hiện bước tiến từ phương pháp nào sang phương pháp nào?", ["Từ Quản lý chất lượng toàn diện (TQM) sang Kiểm soát chất lượng (QC)", "Từ Kiểm soát chất lượng (QC) sang Đảm bảo chất lượng (QA)", "Từ Đảm bảo chất lượng (QA) sang Các chương trình tiên quyết (PRPs)", "Từ ISO 22000 sang HACCP"], 1, "QC tập trung kiểm tra sản phẩm sau sản xuất để phát hiện lỗi, trong khi QA xây dựng hệ thống quản lý toàn bộ quá trình nhằm chủ động phòng ngừa sai lỗi.", 2);
  add(1, "Một trang trại chăn nuôi heo sử dụng kháng sinh quá liều lượng và không tuân thủ thời gian ngưng thuốc trước khi xuất bán, khiến thịt heo bị tồn dư hóa chất. Nguy cơ mất an toàn thực phẩm này xuất phát từ giai đoạn nào?", ["Giai đoạn chế biến và sơ chế", "Giai đoạn sản xuất nguyên liệu", "Giai đoạn phân phối và lưu kho", "Giai đoạn cung cấp vật tư dịch vụ"], 1, "Giai đoạn sản xuất nguyên liệu (trồng trọt, chăn nuôi) mang các nguy cơ cốt lõi như dư lượng thuốc bảo vệ thực vật, kháng sinh, kim loại nặng.", 2);
  add(1, "Khi phát hiện sự cố vi sinh trong lô hàng, Trưởng phòng Chất lượng yêu cầu truy xuất dữ liệu cảm biến nhiệt độ và nhật ký giám sát thực tế thay vì đưa ra nhận định cảm tính. Hành động này áp dụng nguyên tắc nào của ISO 9000?", ["Tập trung vào khách hàng", "Cải tiến liên tục", "Quyết định dựa trên bằng chứng", "Quan hệ hợp tác với nhà cung cấp"], 2, "Nguyên tắc 'Quyết định dựa trên bằng chứng' trong ISO 9000 đòi hỏi các quyết định quản lý phải dựa trên phân tích dữ liệu và thông tin thực tế.", 2);
  add(1, "Một doanh nghiệp thực phẩm muốn áp dụng một tiêu chuẩn quốc tế giúp kết hợp cả việc kiểm soát mối nguy tại các điểm tới hạn và quản lý hệ thống toàn chuỗi cung ứng. Doanh nghiệp này nên ưu tiên lựa chọn tiêu chuẩn nào?", ["ISO 9000", "ISO 22000", "GMP", "GHP"], 1, "ISO 22000 là tiêu chuẩn quốc tế tích hợp HACCP và quản lý hệ thống nhằm bảo đảm an toàn thực phẩm trong toàn bộ chuỗi cung ứng.", 2);
  add(1, "Trong mô hình HACCP, điểm tới hạn (CCP) được xác định dựa trên:", ["A. Các bước kiểm tra cuối cùng của sản phẩm", "B. Các mối nguy có khả năng gây hại và có thể kiểm soát được tại một điểm nhất định", "C. Các tiêu chuẩn ISO 9000", "D. Ý kiến của người tiêu dùng"], 1, "CCP là điểm trong quy trình nơi kiểm soát mối nguy là cần thiết để ngăn ngừa, loại bỏ hoặc giảm thiểu nguy cơ.", 3);
  add(1, "Rủi ro nào sau đây thường xuất hiện trong giai đoạn phân phối và lưu kho nếu chuỗi lạnh bị đứt?", ["A. Tăng hàm lượng chất bảo quản", "B. Sự phát triển của vi sinh vật gây hại", "C. Sự giảm độ ẩm làm khô sản phẩm", "D. Tăng nồng độ kim loại nặng"], 1, "Khi chuỗi lạnh bị đứt, nhiệt độ tăng cho phép vi sinh vật phát triển nhanh, làm tăng nguy cơ an toàn thực phẩm.", 3);
  add(1, "Trong ISO 22000, yếu tố nào là nền tảng để tích hợp HACCP vào hệ thống quản lý?", ["A. Đánh giá dựa trên bằng chứng", "B. Kiểm tra ngẫu nhiên sản phẩm", "C. Đào tạo nhân viên bán lẻ", "D. Thực hiện chỉ tiêu tài chính"], 0, "ISO 22000 yêu cầu quyết định dựa trên bằng chứng (evidence‑based) để tích hợp HACCP và quản lý rủi ro.", 3);
  add(1, "Một nhà cung cấp thực phẩm sử dụng thuốc bảo vệ thực vật có dư lượng vượt mức cho phép. Đây là mối nguy nào và ở giai đoạn nào nên được kiểm soát?", ["A. Nguy cơ sinh học, giai đoạn chế biến", "B. Nguy cơ hoá học, giai đoạn sản xuất nguyên liệu", "C. Nguy cơ vật lý, giai đoạn bán lẻ", "D. Nguy cơ sinh học, giai đoạn lưu kho"], 1, "Dư lượng thuốc bảo vệ thực vật là nguy cơ hoá học, cần được kiểm soát ngay tại giai đoạn sản xuất nguyên liệu.", 3);
  add(1, "Theo nguyên tắc “từ trang trại đến bàn ăn”, ai chịu trách nhiệm chính trong việc giảm nguy cơ nhiễm chéo vi sinh tại giai đoạn sơ chế?", ["A. Người tiêu dùng", "B. Nhà phân phối", "C. Nhà sản xuất/đơn vị chế biến", "D. Cơ quan quản lý Nhà nước"], 2, "Người chế biến áp dụng GMP, SSOP và HACCP để ngăn ngừa nhiễm chéo trong quá trình sơ chế.", 3);
  add(1, "Truy xuất nguồn gốc thực phẩm là gì?", ["Khả năng theo dõi toàn bộ lịch sử và quá trình của sản phẩm từ sản xuất đến tiêu dùng", "Quy trình đóng gói sản phẩm nhanh chóng", "Chiến lược quảng cáo sản phẩm trên mạng xã hội", "Phương pháp giảm chi phí sản xuất"], 0, "Truy xuất nguồn gốc giúp xác định nguyên nhân sự cố và thu hồi sản phẩm kịp thời.", 1);
  add(1, "Trong văn bản, công nghệ nào được nêu là hỗ trợ nâng cao hiệu quả truy xuất nguồn gốc?", ["NFC", "Mã QR", "GPS", "Bluetooth"], 1, "Mã QR, RFID và blockchain được đề cập là các công nghệ hỗ trợ truy xuất.", 1);
  add(2, "Trong hệ thống quản lý GMP → HACCP → ISO 22000, yếu tố nào được coi là chương trình tiên quyết (PRP) bắt buộc trước khi triển khai HACCP?", ["ISO 22000", "HACCP", "GMP", "FSSC 22000"], 2, "GMP là PRP cần có trước khi áp dụng HACCP hoặc ISO 22000.", 1);
  add(2, "Nguyên tắc một chiều trong thiết kế nhà xưởng nhằm mục đích gì?", ["Cho phép nguyên liệu di chuyển theo nhiều hướng để tăng tốc độ sản xuất", "Ngăn ngừa nhiễm chéo giữa khu vực sạch và khu vực bẩn bằng cách di chuyển nguyên liệu, sản phẩm và con người theo một hướng thống nhất", "Sử dụng băng chuyền vòng tròn để tiết kiệm không gian", "Không cần hệ thống thông gió đặc biệt"], 1, "Nguyên tắc một chiều giúp duy trì phân tách sạch‑bẩn, giảm nguy cơ nhiễm chéo.", 1);
  add(2, "Vật liệu nào được khuyến nghị cho thiết bị và dụng cụ trong nhà xưởng thực phẩm để đảm bảo an toàn và dễ vệ sinh?", ["Nhựa PVC", "Inox (thép không gỉ)", "Gỗ", "Đồng"], 1, "Inox không độc hại, bền, không gỉ và dễ làm sạch, phù hợp cho ngành thực phẩm.", 1);
  add(1, "Một cơ sở chế biến thủy sản nhận được phản ánh về lô hàng cá ngừ đóng hộp bị nhiễm vi sinh vật. Để xác định nhanh chóng lô nguyên liệu cá ngừ nhập vào ngày nào và do nhà cung cấp nào cấp, doanh nghiệp cần dựa vào yếu tố cốt lõi nào trong hệ thống truy xuất nguồn gốc?", ["Nhật ký điểm danh ca làm việc của công nhân", "Mã lô hàng, nhãn hàng hóa và hệ thống hồ sơ lưu trữ nguyên liệu - sản xuất", "Quy trình vệ sinh khử trùng bề mặt thiết bị (SSOP)", "Tiêu chuẩn thiết kế hệ thống chiếu sáng trong nhà xưởng"], 1, "Để truy xuất nguồn gốc hiệu quả, sản phẩm cần được nhận diện qua mã lô, nhãn hàng hóa và hồ sơ lưu trữ đầy đủ về nguyên liệu, quá trình sản xuất và phân phối.", 2);
  add(2, "Một doanh nghiệp chế biến thực phẩm muốn chứng nhận ISO 22000 nhưng cơ sở hạ tầng nhà xưởng chưa kiểm soát được các điều kiện vệ sinh cơ bản. Cố vấn chất lượng nên đưa ra lời khuyên nào phù hợp nhất theo thứ tự ưu tiên áp dụng hệ thống quản lý?", ["Tập trung xây dựng ngay hệ thống HACCP để tiết kiệm chi phí và bỏ qua GMP", "Đăng ký chứng nhận ISO 22000 trước rồi cải tạo nhà xưởng sau", "Xây dựng và thực hiện tốt Thực hành sản xuất tốt (GMP) làm điều kiện tiên quyết trước khi triển khai HACCP và ISO 22000", "Chỉ cần đầu tư thiết bị tự động hóa hiện đại để thay thế toàn bộ quy trình kiểm soát vệ sinh"], 2, "GMP là chương trình tiên quyết (PRP) bắt buộc phải có trước khi triển khai HACCP hay ISO 22000 nhằm kiểm soát các điều kiện môi trường và vệ sinh cơ bản.", 2);
  add(2, "Khi thiết kế mặt bằng xưởng chế biến suất ăn công nghiệp, kỹ sư bố trí cửa ra của khu thu gom chất thải cắt ngang qua đường di chuyển của bán thành phẩm từ khu chế biến sang khu đóng gói. Thiết kế này vi phạm nguyên tắc nào và dẫn đến nguy cơ gì?", ["Vi phạm quy định bảo quản; nguy cơ làm giảm dinh dưỡng thực phẩm", "Vi phạm nguyên tắc một chiều; nguy cơ gây nhiễm chéo từ khu bẩn/chất thải sang khu sạch", "Vi phạm quy định thông gió; nguy cơ gia tăng độ ẩm trong nhà xưởng", "Vi phạm quy trình hiệu chuẩn; nguy cơ gây sai lệch khối lượng đóng gói"], 1, "Sự giao nhau giữa luồng di chuyển chất thải và bán thành phẩm vi phạm nguyên tắc một chiều, tạo nguy cơ lây nhiễm chéo vi sinh vật từ khu bẩn sang khu sạch.", 2);
  add(2, "Trong một nhà máy sản xuất bánh kẹo, kỹ thuật viên thiết kế hệ thống thông gió sao cho luồng không khí thổi trực tiếp từ khu vực tiếp nhận nguyên liệu thô (chưa qua xử lý) sang khu vực đóng gói sản phẩm ăn liền. Thiết kế này đúng hay sai và vì sao?", ["Đúng, vì giúp làm mát nhanh sản phẩm ở khu vực đóng gói", "Sai, vì luồng không khí bắt buộc phải đi từ khu sạch đến khu bẩn để tránh mang bụi bẩn và vi sinh vật vào khu sạch", "Đúng, vì khu nhận nguyên liệu cần thông thoáng để đẩy mùi hôi ra ngoài", "Sai, vì nhà máy thực phẩm không được phép lắp đặt hệ thống thông gió"], 1, "Theo quy chuẩn GMP về kết cấu nhà xưởng, luồng không khí trong hệ thống thông gió phải di chuyển theo chiều từ khu sạch đến khu bẩn để ngăn ngừa ô nhiễm ngược.", 2);
  add(2, "Một xưởng chế biến giò chả sử dụng các thùng chứa nguyên liệu bằng sắt dễ bị gỉ sét và các máy xay thịt có kết cấu đúc liền khối, không thể tháo rời các bộ phận bên trong để rửa. Vi phạm này thuộc yêu cầu kiểm soát nào của GMP?", ["Kiểm soát phương tiện phòng chống động vật gây hại", "Kiểm soát thiết bị và dụng cụ sản xuất về vật liệu an toàn và tính dễ làm sạch, khử trùng", "Kiểm soát quy trình phân luồng di chuyển của nhân viên", "Kiểm soát tiêu chuẩn chiếu sáng và an toàn bóng đèn"], 1, "GMP quy định thiết bị, dụng cụ tiếp xúc trực tiếp với thực phẩm phải làm từ vật liệu an toàn, không gỉ (như inox) và phải dễ tháo rời để vệ sinh, khử trùng.", 2);
  add(1, "Trong hệ thống truy xuất nguồn gốc, việc không lưu trữ đầy đủ hồ sơ nguyên liệu, sản xuất và phân phối trong thời gian quy định sẽ gây ra rủi ro nào sau đây?", ["Không thể xác định nhanh nguyên nhân gây ô nhiễm khi có sự cố thực phẩm", "Tăng chi phí sản xuất do phải mua nguyên liệu dư thừa", "Giảm thời gian bảo quản của sản phẩm cuối cùng", "Tăng độ tin cậy của nhãn hiệu trên thị trường"], 0, "Thiếu hồ sơ làm mất khả năng truy xuất nhanh, gây chậm trong việc thu hồi và kiểm soát rủi ro an toàn thực phẩm.", 3);
  add(2, "PRP (Pre‑Requisite Programs) trong GMP đóng vai trò gì trong việc triển khai HACCP?", ["Cung cấp dữ liệu lịch sử để phân tích nguy cơ trong HACCP", "Là các biện pháp kiểm soát các mối nguy cơ phổ biến trước khi áp dụng phân tích mối nguy HACCP", "Thay thế hoàn toàn nhu cầu thực hiện HACCP ở các doanh nghiệp nhỏ", "Đảm bảo chỉ có một loại nguyên liệu được sử dụng trong toàn bộ quy trình"], 1, "PRP tạo nền tảng môi trường và điều kiện cơ bản, giúp HACCP tập trung vào các mối nguy đặc thù.", 3);
  add(3, "Nguyên tắc một chiều trong thiết kế nhà xưởng thực phẩm nhằm ngăn ngừa rủi ro nào?", ["Tăng tốc độ sản xuất bằng cách giảm khoảng cách giữa các khu vực", "Ngăn chéo nhiễm bẩn giữa khu vực sạch và khu vực bẩn bằng cách duy trì luồng di chuyển một hướng", "Giảm chi phí năng lượng bằng cách sử dụng ánh sáng tự nhiên", "Tối đa hoá diện tích lưu trữ nguyên liệu thô"], 1, "Luồng một chiều ngăn ngừa nhiễm chéo, giảm nguy cơ ô nhiễm thực phẩm trong quá trình sản xuất.", 3);
  add(4, "Khi lựa chọn vật liệu cho thiết bị và dụng cụ trong nhà máy thực phẩm, yếu tố nào sau đây là quan trọng nhất để giảm rủi ro nhiễm bẩn?", ["Vật liệu phải có màu sáng để dễ quan sát bẩn", "Vật liệu phải không độc hại, không gỉ, dễ làm sạch và có khả năng hiệu chuẩn định kỳ", "Vật liệu phải có độ dẻo cao để giảm tiếng ồn", "Vật liệu phải có khả năng chịu nhiệt trên 500 °C"], 1, "Vật liệu an toàn, không gỉ và dễ vệ sinh giúp ngăn ngừa tích tụ vi sinh và các chất gây ô nhiễm.", 3);
  add(5, "Theo yêu cầu truy xuất nguồn gốc, thời gian lưu trữ hồ sơ liên quan đến nguyên liệu, quy trình sản xuất và phân phối thường là bao lâu để giảm rủi ro pháp lý và bảo vệ người tiêu dùng?", ["6 tháng", "1 năm", "2 năm", "5 năm"], 2, "Thông thường, hồ sơ phải được lưu trữ ít nhất 2 năm để đáp ứng yêu cầu kiểm tra và truy xuất khi có sự cố.", 3);
  add(1, "SSOP (Sanitation Standard Operating Procedure) được định nghĩa là gì?", ["Quy phạm vệ sinh và thủ tục kiểm soát vệ sinh nhằm quản lý các yếu tố liên quan đến môi trường sản xuất", "Tiêu chuẩn quốc tế về quản lý chất lượng thực phẩm", "Hệ thống kiểm soát các nguy cơ sinh học trong HACCP", "Chương trình đào tạo an toàn thực phẩm cho công nhân"], 0, "SSOP là tập hợp các quy định nhằm kiểm soát tất cả các yếu tố liên quan đến vệ sinh môi trường sản xuất.", 1);
  add(1, "Điều nào sau đây là một trong bốn phần cố định của một SSOP?", ["Phần 1: Quy định chung (Mục tiêu)", "Phần 2: Đánh giá rủi ro tài chính", "Phần 3: Kế hoạch marketing sản phẩm", "Phần 4: Đánh giá hiệu suất bán hàng"], 0, "Mỗi SSOP bao gồm 4 phần cố định: Quy định chung, Nội dung chi tiết, Kiểm soát, và Hồ sơ lưu trữ.", 1);
  add(1, "Theo quy trình cấp chứng chỉ GMP tại Việt Nam, bước nào sau đây không thuộc quy trình?", ["Nộp hồ sơ", "Kiểm tra tại chỗ", "Thực hiện kiểm tra nội bộ mỗi ngày", "Cấp chứng chỉ"], 2, "Quy trình gồm: chuẩn bị → tự kiểm tra → nộp hồ sơ → kiểm tra tại chỗ → cấp chứng chỉ → giám sát định kỳ. Kiểm tra nội bộ mỗi ngày không phải là bước trong quy trình cấp chứng chỉ.", 1);
  add(1, "Cơ quan nào ở Việt Nam chịu trách nhiệm cấp chứng chỉ GMP cho doanh nghiệp thực phẩm?", ["Cục Quản lý Dược (NMPA) hoặc Sở Y tế tỉnh/thành phố", "Bộ Nông nghiệp và Phát triển Nông thôn", "Bộ Y tế", "Cục An toàn Thực phẩm"], 0, "Chứng chỉ GMP được cấp bởi Cục Quản lý Dược (NMPA) hoặc Sở Y tế tỉnh/thành phố.", 1);
  add(1, "Nguyên tắc ghi chép trong hồ sơ giám sát định kỳ GMP là gì?", ["Ghi ngay khi thực hiện, không ghi trước hoặc ghi bù", "Ghi lại chỉ khi có sai lệch", "Ghi sau khi kiểm tra tổng hợp cuối tuần", "Ghi lại bằng phần mềm tự động mà không cần xác nhận"], 0, "Nguyên tắc ghi chép yêu cầu ghi ngay khi thực hiện; việc ghi trước hoặc ghi bù là không được phép.", 1);
  add(1, "Trong một nhà máy chế biến thủy sản, công nhân A vô tình bị một vết cắt nhỏ ở ngón tay trong quá trình làm việc. Theo quy định về thực hành vệ sinh cá nhân và kiểm soát an toàn của GMP, hướng xử lý thực tế nào sau đây là đúng quy định?", ["Cho phép công nhân A tiếp tục làm việc ngay nếu vết thương đã ngừng chảy máu.", "Xử lý vết thương, che chắn bằng băng cá nhân chống thấm nước, đeo găng tay bảo vệ trước khi làm việc lại hoặc chuyển sang vị trí không tiếp xúc trực tiếp với thực phẩm.", "Chỉ cần yêu cầu công nhân A rửa tay bằng dung dịch cồn 70 độ rồi tiếp tục công việc phân loại.", "Cho công nhân A nghỉ việc ngay lập tức trong ngày mà không cần lưu lại ghi nhận sự cố."], 1, "GMP quy định công nhân phải che chắn và xử lý đúng các vết thương (sử dụng băng chống thấm, đeo găng tay hoặc chuyển vị trí) để tránh nguy cơ lây nhiễm vi sinh vật vào thực phẩm.", 2);
  add(1, "Khi tiến hành kiểm tra đột xuất tại xưởng sản xuất nước giải khát, chuyên viên QC phát hiện biểu mẫu giám sát nhiệt độ thanh trùng ca 14h00 đã được ghi đầy đủ kết quả 'Đạt' từ lúc 13h00. Hành vi này vi phạm nghiêm trọng nguyên tắc ghi chép hồ sơ nào của GMP?", ["Vi phạm nguyên tắc 'Ghi ngay khi thực hiện' (tuyệt đối không ghi trước/dự đoán), làm mất giá trị pháp lý của hồ sơ giám sát.", "Vi phạm nguyên tắc 'Sử dụng biểu mẫu đơn giản', gây khó khăn cho việc theo dõi.", "Vi phạm quy định về 'Thời hạn lưu trữ hồ sơ' của doanh nghiệp.", "Vi phạm quy định về 'Phân công trách nhiệm ký duyệt' giữa người thực hiện và người kiểm tra."], 0, "Nguyên tắc cốt lõi khi ghi chép hồ sơ GMP là phải ghi ngay khi thực hiện, tuyệt đối không được ghi trước (dự đoán) hoặc ghi bù để đảm bảo tính trung thực và khả năng phát hiện sai lệch kịp thời.", 2);
  add(2, "Một doanh nghiệp mới thành lập muốn bỏ qua việc xây dựng GMP và SSOP để tập trung làm ngay chứng chỉ HACCP nhằm tiết kiệm thời gian và chi phí. Là chuyên gia Quản lý chất lượng, bạn đưa ra lời tư vấn nào phù hợp nhất?", ["Đồng ý, vì HACCP là hệ thống quản lý nâng cao có thể bao hàm và thay thế toàn bộ quy định của GMP và SSOP.", "Từ chối và giải thích rằng GMP và SSOP là chương trình tiên quyết (PRP) đóng vai trò nền móng; không có GMP/SSOP thì không thể xây dựng và vận hành hệ thống HACCP.", "Khuyên doanh nghiệp chỉ cần làm SSOP vì SSOP quan trọng hơn GMP trong việc kiểm soát mối nguy HACCP.", "Đồng ý, nhưng yêu cầu doanh nghiệp phải áp dụng ngay tiêu chuẩn ISO 22000 thay cho HACCP."], 1, "GMP và SSOP là điều kiện tiên quyết (PRP) làm nền móng vững chắc. Tương tự như 'không có móng nhà thì không thể xây được tầng nhà', doanh nghiệp bắt buộc phải có GMP/SSOP trước khi áp dụng HACCP.", 2);
  add(1, "Một cơ sở sản xuất thực phẩm bảo vệ sức khỏe tại Việt Nam đã được cấp Chứng chỉ chứng nhận GMP. Ban giám đốc cho rằng chứng chỉ này có giá trị vĩnh viễn nếu cơ sở không vi phạm. Khẳng định của Ban giám đốc là Đúng hay Sai, và quy định thực tế là gì?", ["Đúng, chứng chỉ GMP có hiệu lực vô thời hạn cho đến khi có quyết định thu hồi.", "Sai, chứng chỉ GMP chỉ có hiệu lực trong 1 năm và phải thực hiện kiểm tra lại hàng năm.", "Sai, chứng chỉ GMP tại Việt Nam có hiệu lực 3 năm, cơ sở phải thực hiện thủ tục gia hạn để tiếp tục duy trì.", "Sai, chứng chỉ GMP có hiệu lực 5 năm và được tự động gia hạn nếu không có khiếu nại từ khách hàng."], 2, "Theo quy định cấp chứng chỉ GMP tại Việt Nam, hiệu lực của giấy chứng nhận là 3 năm. Sau thời hạn này, cơ sở phải làm thủ tục gia hạn để tiếp tục duy trì hoạt động.", 2);
  add(2, "Trong đợt thanh tra của đoàn đánh giá đối tác xuất khẩu, Quản lý xưởng quả quyết rằng xưởng luôn được tẩy rửa vệ sinh rất sạch sẽ mỗi cuối ngày, tuy nhiên không xuất trình được các bảng kiểm tra (checklist) vệ sinh định kỳ. Trưởng đoàn đánh giá đã từ chối ghi nhận dựa trên triết lý kiểm soát nào của SSOP?", ["\"Sai lệch là điều bắt buộc phải xảy ra trong sản xuất\"", "\"Những gì không ghi lại nghĩa là chưa từng làm\"", "\"Thực hành thực tế quan trọng hơn giấy tờ sổ sách\"", "\"Kết quả tự kiểm tra không có giá trị đối chứng\""], 1, "Trong quản lý chất lượng và SSOP, hồ sơ lưu trữ (Records) là bằng chứng duy nhất chứng minh hoạt động đã được thực hiện, tuân theo nguyên tắc: 'Những gì không ghi lại nghĩa là chưa từng làm'.", 2);
  add(2, "Trong ma trận kiểm soát nguồn nhiễm bẩn (SSOP), yếu tố nào sau đây được xem là rủi ro cao nhất đối với ô nhiễm vi sinh khi không được giám sát chặt chẽ?", ["Nhiệt độ lưu trữ sản phẩm", "Tiếp xúc của thực phẩm với bề mặt không được làm sạch", "Áp suất trong khu vực đóng gói", "Ánh sáng môi trường"], 1, "Bề mặt không được làm sạch (đặc biệt là sàn, thiết bị) là nguồn lây truyền vi sinh chính nếu không giám sát, vì vi khuẩn có thể tồn tại và lan truyền dễ dàng.", 3);
  add(1, "Theo quy trình rửa tay chuẩn trong GMP, bước nào sau đây phải được thực hiện đầu tiên?", ["Rửa tay dưới vòi nước chảy", "Thoa xà phòng và tạo bọt", "Rửa tay bằng nước sạch trong ít nhất 20 giây", "Rửa tay bằng dung dịch khử trùng sau khi rửa xà phòng"], 0, "Bước đầu tiên luôn là rửa tay dưới vòi nước chảy để loại bỏ bụi bẩn và tạo điều kiện cho xà phòng hoạt động hiệu quả.", 3);
  add(1, "Khi phát hiện sai lệch trong quá trình sản xuất, hồ sơ giám sát phải ghi lại thông tin nào sau đây để đáp ứng yêu cầu chuẩn GMP?", ["Ngày và thời gian phát hiện; mô tả chi tiết sai lệch; hành động khắc phục; chữ ký người thực hiện", "Chỉ ghi lại hành động khắc phục và thời gian hoàn thành", "Ghi lại mô tả sai lệch và kết quả cuối cùng của sản phẩm", "Chỉ cần ghi lại tên người phát hiện và ngày thực hiện"], 0, "Yêu cầu ghi đầy đủ ngày/giờ, mô tả chi tiết, hành động khắc phục và chữ ký để đảm bảo truy xuất và chứng minh việc kiểm soát sai lệch.", 3);
  add(2, "Điểm khác biệt cơ bản nhất giữa GMP và SSOP là gì?", ["GMP tập trung vào quy trình sản xuất, SSOP tập trung vào kiểm soát môi trường vệ sinh", "GMP chỉ áp dụng cho dược phẩm, SSOP chỉ cho thực phẩm", "GMP yêu cầu chứng chỉ, SSOP không yêu cầu tài liệu", "GMP được quản lý bởi Cục Quản lý Dược, SSOP bởi Sở Y tế"], 0, "GMP (Good Manufacturing Practice) quy định toàn bộ quy trình sản xuất, trong khi SSOP (Sanitation Standard Operating Procedures) chuyên biệt cho các biện pháp vệ sinh môi trường.", 3);
  add(1, "Theo quy định GMP, tần suất lấy mẫu kiểm tra chất lượng sản phẩm thường được quyết định dựa trên yếu tố nào?", ["Mức độ rủi ro của sản phẩm và lịch sử sai lệch; thường là mẫu ngẫu nhiên hàng ngày hoặc hàng lô", "Số lượng nhân viên làm việc trong ca", "Thời gian hoạt động của máy móc", "Kích thước của nhà máy"], 0, "Tần suất lấy mẫu dựa trên đánh giá rủi ro và lịch sử sai lệch; các sản phẩm có rủi ro cao sẽ có mẫu ngẫu nhiên thường xuyên hơn.", 3);
  add(1, "Theo SSOP 2, quy trình 5 bước vệ sinh bề mặt tiếp xúc trực tiếp với sản phẩm được thực hiện theo thứ tự nào?", ["1. Dọn thô → 2. Tráng nước → 3. Đánh chà bằng chất tẩy rửa → 4. Khử trùng → 5. Tráng lại → Để khô tự nhiên", "1. Tráng nước → 2. Dọn thô → 3. Khử trùng → 4. Đánh chà bằng chất tẩy rửa → 5. Tráng lại → Để khô tự nhiên", "1. Dọn thô → 2. Khử trùng → 3. Tráng nước → 4. Đánh chà bằng chất tẩy rửa → 5. Tráng lại → Để khô tự nhiên", "1. Dọn thô → 2. Tráng nước → 3. Khử trùng → 4. Đánh chà bằng chất tẩy rửa → 5. Tráng lại → Để khô tự nhiên"], 0, "Quy trình đúng là: dọn thô, tráng nước, đánh chà, khử trùng, tráng lại, để khô tự nhiên.", 1);
  add(1, "Trong SSOP 1 (An toàn nguồn nước), nồng độ clo dư tối thiểu và tối đa cho nước tiếp xúc thực phẩm là bao nhiêu?", ["0,1 – 0,2 mg/L", "0,3 – 0,5 mg/L", "1 – 2 mg/L", "5 – 10 mg/L"], 1, "Tiêu chuẩn yêu cầu nồng độ clo dư từ 0,3 đến 0,5 mg/L.", 1);
  add(1, "Tần suất giám sát SSOP vệ sinh sàn bởi QC là như thế nào?", ["Một lần mỗi ca sản xuất", "Một lần mỗi ngày", "Một lần mỗi tuần", "Một lần mỗi tháng"], 0, "QC quan sát và test nhanh nồng độ Cloramin B 1 lần/ca.", 1);
  add(1, "Màu sắc nào được phân cho thớt dùng cho thực phẩm sống theo SSOP 2?", ["Đỏ", "Xanh", "Vàng", "Trắng"], 0, "Thớt màu đỏ dành cho thực phẩm sống.", 1);
  add(1, "Trong quy trình khử trùng bằng nước nóng của SSOP 2, nhiệt độ và thời gian tối thiểu yêu cầu là:", ["Nhiệt độ ≥70°C trong ≥10 giây", "Nhiệt độ ≥82°C trong ≥30 giây", "Nhiệt độ ≥90°C trong ≥5 giây", "Nhiệt độ ≥60°C trong ≥60 giây"], 1, "Nước nóng phải có nhiệt độ ít nhất 82°C và tiếp xúc tối thiểu 30 giây.", 1);
  add(2, "Một nhân viên vệ sinh xưởng chế biến thực phẩm chín sau khi nhúng khay inox vào bể nước nóng 85°C trong 15 giây, sau đó dùng khăn vải sạch lau khô để chuẩn bị xếp thực phẩm vào. Thao tác này vi phạm điểm nào trong quy trình SSOP 2?", ["Nhiệt độ nước nóng chưa đạt mức tối thiểu 82°C", "Thời gian ngâm nước nóng chưa đủ (tối thiểu 30 giây) và việc dùng khăn lau khô gây nguy cơ tái nhiễm khuẩn", "Không được phép dùng nước nóng để khử trùng thiết bị inox", "Dùng khăn vải lau khô là thao tác bắt buộc nhưng phải tráng lại nước lạnh trước"], 1, "Theo SSOP 2, quy trình khử trùng bằng nước nóng yêu cầu nhiệt độ ≥82°C trong thời gian ≥30 giây, sau đó phải để khô tự nhiên và KHÔNG lau lại bằng khăn nhằm tránh nguy cơ tái nhiễm khuẩn.", 2);
  add(2, "Khi thiết kế nhà máy chế biến thủy sản, đơn vị thi công bố trí luồng không khí thổi từ Khu tiếp nhận nguyên liệu thô sang Khu bao gói thành phẩm, đồng thời quy định công nhân mặc bảo hộ màu trắng ở tất cả các khu vực. Đánh giá nào sau đây là đúng về thiết kế này theo SSOP 3?", ["Đạt chuẩn vì luồng khí lưu thông giúp làm mát và đồng phục trắng tạo sự sạch sẽ", "Sai quy định vì luồng không khí phải đi từ khu sạch sang khu bẩn và bảo hộ lao động phải phân biệt màu sắc giữa các khu vực", "Đạt chuẩn về thiết kế thông gió nhưng sai về phân màu bảo hộ lao động", "Sai về màu sắc bảo hộ nhưng đạt chuẩn về hướng di chuyển của dòng không khí"], 1, "SSOP 3 quy định luồng không khí (và nước thải) phải di chuyển từ khu sạch đến khu bẩn. Bảo hộ lao động cũng cần phân biệt màu sắc (ví dụ: xanh cho khu thô/bẩn, trắng cho khu tinh/sạch) để tránh nhiễm chéo.", 2);
  add(2, "Trong ca sản xuất, nhân viên QC tiến hành đo nhanh nồng độ clo dư trong nước rửa tôm nguyên liệu và thu được kết quả 0,1 mg/L. Theo quy định SSOP 1, QC cần xử lý như thế nào?", ["Cho phép tiếp tục sản xuất vì nước vẫn có chứa clo chống khuẩn", "Yêu cầu dừng ngay nguồn nước, báo kỹ thuật điều chỉnh hệ thống clo hóa đạt 0,3–0,5 mg/L và đảm bảo thời gian tiếp xúc tối thiểu 30 phút", "Cho phép sử dụng nhưng phải lấy mẫu nước gửi đi kiểm nghiệm kim loại nặng ngay lập tức", "Yêu cầu công nhân ngâm tôm ngắn hơn để tránh ảnh hưởng chất lượng"], 1, "Nồng độ clo dư tiêu chuẩn cho nước sản xuất theo SSOP 1 là 0,3 - 0,5 mg/L (thời gian tiếp xúc tối thiểu 30 phút). Nồng độ 0,1 mg/L không đạt chuẩn an toàn vi sinh, bắt buộc phải dừng và điều chỉnh.", 2);
  add(2, "Trong quá trình bảo trì định kỳ, nhân viên kỹ thuật đã dùng dầu nhờn công nghiệp thông thường để tra vào hệ thống băng tải vận chuyển thịt tươi. Hành vi này vi phạm quy phạm vệ sinh nào?", ["SSOP 5 - Bảo vệ sản phẩm không bị nhiễm bẩn (vì không sử dụng dầu mỡ bôi trơn loại Food Grade)", "SSOP 6 - Sử dụng và bảo quản hóa chất độc hại (vì không có bảng MSDS của dầu nhờn)", "SSOP 2 - Vệ sinh bề mặt tiếp xúc trực tiếp với sản phẩm", "SSOP 8 - Kiểm soát động vật gây hại"], 0, "Theo SSOP 5 (Bảo vệ sản phẩm không bị nhiễm bẩn), việc bảo trì thiết bị trong khu vực sản xuất bắt buộc phải sử dụng dầu mỡ bôi trơn đạt tiêu chuẩn an toàn thực phẩm (Food Grade).", 2);
  add(2, "Khi phát hiện một sự cố sai lệch nghiêm trọng về vệ sinh trên dây chuyền sản xuất, cơ sở cần lập biên bản xử lý và hành động khắc phục. Thời gian lưu trữ tối thiểu đối với loại hồ sơ này là bao lâu?", ["06 tháng", "12 tháng", "02 năm", "05 năm"], 2, "Theo mục 2.5.4 về Lưu trữ hồ sơ trong hệ thống SSOP, thời gian lưu trữ hồ sơ giám sát, kiểm tra và khắc phục sự cố tối thiểu là 02 năm hoặc theo quy định của pháp luật.", 2);
  add(2, "Trong quy trình SSOP 2 (vệ sinh bề mặt tiếp xúc trực tiếp với sản phẩm), bước nào sau đây không thuộc 5 bước làm sạch?", ["Dọn thô", "Tráng nước", "Đánh chà bằng chất tẩy rửa", "Sấy khô bằng khăn"], 3, "Bước 5 là để khô tự nhiên, không được dùng khăn để sấy.", 3);
  add(1, "SSOP 1 yêu cầu nồng độ clo dư trong nước đạt bao nhiêu và thời gian tiếp xúc tối thiểu là bao lâu?", ["0.1‑0.2 mg/L, 15 phút", "0.3‑0.5 mg/L, 30 phút", "0.6‑0.8 mg/L, 45 phút", "0.5‑0.7 mg/L, 20 phút"], 1, "Quy chuẩn quy định nồng độ clo dư 0,3‑0,5 mg/L và thời gian tiếp xúc ít nhất 30 phút.", 3);
  add(4, "Theo SSOP 4 (vệ sinh cá nhân), thời gian tối thiểu để rửa tay bằng xà phòng là bao nhiêu giây?", ["10 giây", "15 giây", "20 giây", "30 giây"], 2, "Quy trình rửa tay yêu cầu tối thiểu 20 giây chà tay.", 3);
  add(1, "Trong SSOP 8 (kiểm soát động vật gây hại), biện pháp nào sau đây không được khuyến cáo để phòng ngừa?", ["Lắp bẫy chuột vòng ngoài và vòng trong", "Sử dụng thuốc xịt diệt côn trùng trong khu vực chế biến thực phẩm", "Lắp lưới chống muỗi và màng chắn nhựa", "Bịt kín tất cả các khe hở"], 1, "Thuốc xịt trong khu vực chế biến có nguy cơ gây nhiễm thực phẩm, không phải biện pháp ưu tiên.", 3);
  add(2, "Khi kiểm tra SSOP vệ sinh sàn cho thấy nồng độ Cloramin B <150 ppm, hành động khắc phục ngay lập tức là gì?", ["Tăng tốc độ sản xuất", "Vệ sinh lại và pha lại dung dịch đúng nồng độ", "Bỏ qua và tiếp tục", "Báo cáo lên quản lý mà không làm lại"], 1, "Tiêu chuẩn yêu cầu nồng độ 150‑250 ppm; nếu thấp phải vệ sinh lại và pha dung dịch đúng nồng độ.", 3);
  add(1, "HACCP (Hazard Analysis and Critical Control Points) là gì?", ["Hệ thống xác định, đánh giá và kiểm soát các mối nguy có ảnh hưởng đáng kể đến an toàn thực phẩm", "Tiêu chuẩn quốc tế về quản lý chất lượng trong sản xuất", "Phương pháp kiểm tra cuối cùng sản phẩm trước khi xuất xưởng", "Kế hoạch đào tạo nhân viên về an toàn thực phẩm"], 0, "Định nghĩa HACCP là hệ thống phân tích và kiểm soát mối nguy để bảo đảm an toàn thực phẩm.", 1);
  add(1, "Triết lý cốt lõi của HACCP là gì?", ["Kiểm tra sản phẩm cuối cùng", "Phòng ngừa trong quá trình sản xuất", "Tập trung vào việc giảm chi phí", "Đánh giá sau khi sản phẩm đã tiêu thụ"], 1, "HACCP tập trung vào phòng ngừa ngay trong quá trình sản xuất, không chờ kiểm tra cuối cùng.", 1);
  add(1, "Theo mô hình GMP + SSOP → HACCP, yếu tố nào là nền tảng bắt buộc để HACCP hoạt động hiệu quả?", ["ISO 22000", "GMP/SSOP (PRP)", "FSSC 22000", "Allergens"], 1, "Nếu không có nền tảng GMP/SSOP, HACCP không thể hoạt động hiệu quả.", 1);
  add(1, "Khác biệt giữa Validation và Verification trong HACCP là gì?", ["Validation kiểm tra kế hoạch đã được thực hiện đúng, Verification kiểm tra kế hoạch có đúng hay không", "Validation xác định kế hoạch có đúng không, Verification kiểm tra kế hoạch có được thực hiện đúng không", "Validation và Verification là hai thuật ngữ đồng nghĩa", "Validation chỉ áp dụng cho mối nguy sinh học, Verification chỉ cho mối nguy vật lý"], 1, "Validation hỏi 'Kế hoạch có đúng không?', Verification hỏi 'Kế hoạch có được làm đúng không?'.", 1);
  add(1, "Trong các mối nguy vật lý dưới đây, yếu tố nào không phải là mối nguy vật lý?", ["Mảnh thủy tinh (bóng đèn vỡ)", "Mảnh kim loại (dao, kéo)", "Đậu phộng (chất gây dị ứng)", "Đá, đất, sỏi"], 2, "Đậu phộng là mối nguy gây dị ứng, không thuộc mối nguy vật lý.", 1);
  add(3, "Một nhà máy chế biến đồ hộp thủy sản tiến hành kiểm tra thực nghiệm xem công thức nhiệt độ - thời gian thanh trùng mới thiết lập có đủ khả năng tiêu diệt bào tử vi khuẩn Clostridium botulinum trước khi áp dụng vào thực tế sản xuất hay không. Hoạt động này thuộc khái niệm nào?", ["Verification (Thẩm tra)", "Validation (Xác nhận giá trị sử dụng)", "Monitoring (Giám sát)", "Corrective Action (Hành động khắc phục)"], 1, "Validation trả lời cho câu hỏi 'Kế hoạch có đúng không?' (xác nhận biện pháp kiểm soát có hiệu quả trước khi vận hành), còn Verification trả lời cho 'Kế hoạch có được thực hiện đúng không?'.", 2);
  add(3, "Tại công đoạn tiếp nhận nguyên liệu rau củ, đội HACCP nhận diện mối nguy đất đá. Tuy nhiên, ở công đoạn rửa ngay sau đó, hệ thống sục khí và lắng lọc được thiết kế đảm bảo loại bỏ hoàn toàn đất đá xuống mức an toàn. Dựa vào Cây quyết định CCP (Câu hỏi Q4), công đoạn tiếp nhận rau củ có được xác định là CCP cho mối nguy đất đá không?", ["Có, vì đất đá là mối nguy vật lý xuất hiện ngay từ công đoạn tiếp nhận", "Không, vì công đoạn rửa phía sau sẽ loại bỏ mối nguy này xuống mức chấp nhận được", "Có, vì mọi công đoạn đầu vào đều bắt buộc phải là CCP", "Không, vì đất đá không phải là mối nguy trong thực phẩm"], 1, "Theo Cây quyết định CCP, ở Q4 nếu có công đoạn phía sau loại bỏ hoặc giảm thiểu mối nguy xuống mức chấp nhận được thì công đoạn hiện tại KHÔNG phải là CCP.", 2);
  add(3, "Một xưởng sản xuất nước ép trái cây mới thành lập muốn áp dụng ngay hệ thống HACCP để xuất khẩu hàng hóa, nhưng nhà xưởng chưa xây dựng quy trình vệ sinh (SSOP) và thực hành sản xuất tốt (GMP). Tư vấn nào sau đây là chính xác nhất?", ["Có thể triển khai HACCP ngay vì HACCP độc lập và thay thế hoàn toàn cho GMP/SSOP", "Bắt buộc phải áp dụng và vận hành hiệu quả GMP và SSOP trước vì đó là nền tảng tiên quyết để HACCP hoạt động", "Chỉ cần áp dụng SSOP, không cần GMP vẫn triển khai thành công HACCP", "Bỏ qua GMP/SSOP và nâng cấp thẳng lên chứng nhận ISO 22000"], 1, "GMP và SSOP (GHP) là chương trình tiên quyết (PRP) làm nền tảng bắt buộc. Nếu không có nền tảng GMP/SSOP, hệ thống HACCP không thể hoạt động hiệu quả.", 2);
  add(3, "Trong quá trình chế biến và đóng gói xúc xích tiệt trùng, công nhân vận hành vô tình làm rơi chiếc cúc áo nhựa từ bảo hộ lao động vào băng chuyền sản phẩm. Mối nguy này được phân loại vào nhóm mối nguy nào trong HACCP?", ["Mối nguy Sinh học", "Mối nguy Hóa học", "Mối nguy Vật lý", "Mối nguy Dị ứng"], 2, "Mối nguy vật lý bao gồm bất kỳ vật thể lạ nào có khả năng gây tổn thương cho người ăn, trong đó dị vật từ con người như tóc, cúc áo, trang sức... thuộc nhóm này.", 2);
  add(3, "Đội HACCP của một công ty sản xuất bánh nướng đã phác thảo xong sơ đồ dòng chảy quy trình sản xuất trên bản vẽ kỹ thuật. Để hoàn tất Bước 5 trong 5 bước chuẩn bị sơ bộ trước khi thực hiện 7 nguyên tắc HACCP, Đội HACCP cần làm gì tiếp theo?", ["Gửi sơ đồ lên Ban Giám đốc để phê duyệt và ban hành áp dụng ngay", "Chuyển ngay sang Nguyên tắc 1 để phân tích mối nguy trên bản vẽ", "Trực tiếp xuống hiện trường nhà máy để kiểm tra, đối chiếu và xác nhận sơ đồ phản ánh chính xác thực tế", "Mời cơ quan chức năng đến thẩm định sơ đồ dòng chảy"], 2, "Bước 5 là 'Xác nhận sơ đồ dòng chảy tại hiện trường', yêu cầu đội HACCP phải kiểm tra thực tế tại nhà máy để đảm bảo sơ đồ phản ánh đúng thực tế vận hành.", 2);
  add(1, "HACCP (Hazard Analysis and Critical Control Points) được định nghĩa là gì?", ["Hệ thống kiểm soát chất lượng cuối cùng", "Phương pháp phân tích và kiểm soát các mối nguy trong quá trình sản xuất", "Tiêu chuẩn ISO cho an toàn thực phẩm", "Kế hoạch bảo trì thiết bị"], 1, "HACCP là hệ thống xác định, đánh giá và kiểm soát các mối nguy có ảnh hưởng đáng kể đến an toàn thực phẩm.", 3);
  add(1, "Trong các mối nguy được liệt kê, yếu tố nào không thuộc mối nguy vật lý?", ["Mảnh thủy tinh (bóng đèn vỡ, chai lọ)", "Mảnh kim loại (dao, kéo, ốc vít lỏng)", "Chất gây dị ứng (Allergens)", "Đá, đất, sỏi"], 2, "Chất gây dị ứng được tách thành mối nguy thứ 4 riêng biệt, không thuộc mối nguy vật lý.", 3);
  add(1, "Trong cây quyết định xác định CCP, câu trả lời nào cho Q2 cho thấy bước đó là một CCP?", ["Có – ĐÂY LÀ CCP", "Không – KHÔNG PHẢI CCP", "Có – KHÔNG PHẢI CCP", "Không – CẦN BỔ SUNG"], 0, "Nếu công đoạn được thiết kế để loại bỏ/giảm mối nguy xuống mức chấp nhận, đó là CCP.", 3);
  add(1, "Sự khác biệt chính giữa Validation và Verification trong HACCP là gì?", ["Validation kiểm tra kế hoạch đã thực hiện đúng; Verification kiểm tra kế hoạch có đúng không.", "Validation đánh giá kế hoạch có phù hợp; Verification đánh giá kế hoạch có được thực hiện đúng.", "Validation thực hiện sau mỗi lô; Verification thực hiện trước khi sản xuất.", "Validation và Verification là cùng một khái niệm."], 1, "Validation hỏi 'Kế hoạch có đúng không?'; Verification hỏi 'Kế hoạch có được làm đúng không?'.", 3);
  add(1, "Trong 12 bước triển khai HACCP, nguyên tắc nào liên quan đến việc thiết lập hệ thống giám sát?", ["NT3/B8: Thiết lập ngưỡng tới hạn", "NT4/B9: Thiết lập hệ thống giám sát", "NT5/B10: Thiết lập hành động khắc phục", "NT6/B11: Thiết lập thủ tục thẩm tra"], 1, "NT4/B9 là nguyên tắc thiết lập hệ thống giám sát cho các CCP.", 3);
  add(1, "Theo nguyên tắc HACCP, điều nào sau đây KHÔNG phải là tiêu chí để xác định một Điểm kiểm soát tới hạn (CCP)?", ["Mối nguy đáng kể xuất hiện tại công đoạn đó", "Có thể kiểm soát mối nguy ngay tại công đoạn đó", "Nếu không kiểm soát sẽ trực tiếp gây mất an toàn thực phẩm", "Mối nguy có thể được loại bỏ triệt để ở công đoạn sau"], 3, "Nếu mối nguy được loại bỏ hoàn toàn ở công đoạn tiếp theo thì công đoạn hiện tại không được coi là CCP (theo cây quyết định CCP).", 1);
  add(1, "Định nghĩa nào sau đây là chính xác nhất về Ngưỡng tới hạn (Critical Limit) trong hệ thống HACCP?", ["Năng suất sản xuất tối đa của toàn nhà máy", "Ranh giới tuyệt đối phân định giữa mức chấp nhận được và không thể chấp nhận được tại một CCP", "Khoảng thời gian định kỳ để tiến hành giám sát CCP", "Yêu cầu về tần suất lưu trữ hồ sơ của CCP"], 1, "Ngưỡng tới hạn là tiêu chí phân định ranh giới an toàn (chấp nhận được) và mất an toàn (không chấp nhận được) tại mỗi điểm CCP.", 1);
  add(1, "Which element must be included in a monitoring record for a CCP?", ["Temperature of the next shift", "Name of the supplier", "Date and time of the measurement and the result", "The marketing plan for the product"], 2, "Monitoring records must contain the date, time, measured result, and signature.", 1);
  add(1, "Trong quy trình hành động khắc phục sự cố vi phạm ngưỡng tới hạn, bước đầu tiên cần thực hiện là gì?", ["Tiến hành thực thi hành động khắc phục ngay lập tức", "Xác định nguyên nhân gốc rễ dẫn đến sự cố", "Phát hiện và ghi nhận sự sai lệch khỏi ngưỡng tới hạn", "Xem xét lại toàn bộ nhật ký hồ sơ sản xuất"], 2, "Bước đầu tiên khi xảy ra sự cố là phải phát hiện và ghi nhận sự sai lệch khỏi ngưỡng tới hạn để kịp thời cô lập lô hàng.", 1);
  add(1, "Theo các nguyên tắc HACCP, ai là người thích hợp nhất để tiến hành hoạt động thẩm tra (Verification)?", ["Nhân viên trực tiếp giám sát CCP hằng ngày", "Người độc lập không trực tiếp tham gia vào việc vận hành CCP đó", "Quản lý xưởng sản xuất", "Bộ phận tiếp thị và kinh doanh"], 1, "Hoạt động thẩm tra phải do người có chuyên môn và khách quan (không trực tiếp vận hành CCP đó) thực hiện để đảm bảo tính minh bạch.", 1);
  add(1, "Trong việc xác định CCP, tiêu chí nào sau đây KHÔNG phải đáp ứng đồng thời?", ["Có mối nguy đáng kể tại công đoạn đó", "Có thể kiểm soát được tại công đoạn đó", "Không có công đoạn sau loại bỏ được mối nguy đó", "Có thể giảm chi phí sản xuất bằng cách bỏ qua công đoạn này"], 3, "Tiêu chí thứ tư không phải là tiêu chí xác định CCP; các tiêu chí đúng là ba mục đã nêu.", 3);
  add(2, "Một ngưỡng tới hạn (Critical Limit) phải đáp ứng tất cả các yêu cầu sau, TRỪ:", ["Có cơ sở khoa học", "Định lượng được bằng thiết bị hoặc kiểm nghiệm", "Phải được thiết lập dựa trên cảm quan của nhân viên", "Rõ ràng, cụ thể"], 2, "Ngưỡng tới hạn không được dựa trên cảm quan mà phải có cơ sở khoa học và đo lường được.", 3);
  add(3, "Trong hệ thống giám sát CCP, tài liệu ghi chép phải bao gồm tất cả, ngoại trừ:", ["Ngày và giờ thực hiện", "Ký tên người trực tiếp giám sát", "Ký tên người quản lý phụ trách", "Ký tên khách hàng mua sản phẩm"], 3, "Chữ ký khách hàng không phải là yêu cầu trong hồ sơ giám sát nội bộ.", 3);
  add(4, "Trong quy trình 6 bước hành động khắc phục, bước nào sau đây được thực hiện sau khi xác định nguyên nhân gốc rễ?", ["Thực hiện ngay hành động khắc phục", "Xử lý sản phẩm không phù hợp", "Thực hiện biện pháp ngăn ngừa tái diễn", "Ghi chép và xem xét"], 2, "Sau khi xác định nguyên nhân gốc rễ, bước tiếp theo là thực hiện biện pháp ngăn ngừa tái diễn.", 3);
  add(5, "Đối với người thẩm tra HACCP, tính độc lập được đảm bảo khi:", ["Người thẩm tra là trưởng bộ phận sản xuất", "Người thẩm tra không trực tiếp giám sát CCP đang được thẩm tra", "Người thẩm tra là người ghi chép kết quả giám sát", "Người thẩm tra không có chứng chỉ HACCP"], 1, "Người thẩm tra phải không phải người trực tiếp giám sát CCP để đảm bảo tính độc lập.", 3);
  add(1, "Trong văn bản, \"Đơn giản, tích hợp\" đề cập đến:", ["Biểu mẫu phức tạp", "Biểu mẫu đơn giản, tích hợp", "Tính toán thủ công", "Kiểm toán bên ngoài"], 1, "Cụm từ nhấn mạnh việc sử dụng biểu mẫu đơn giản, dễ thực hiện và tích hợp.", 1);
  add(1, "Yếu tố nào được nhấn mạnh để \"Dễ đọc – Dễ truy xuất\"?", ["Mã màu", "Đơn vị, ký hiệu, cách ghi thống nhất", "Ghi chú tay", "Phông chữ lớn"], 1, "Việc thống nhất đơn vị, ký hiệu và cách ghi giúp người dùng dễ đọc và truy xuất thông tin.", 1);
  add(1, "Khi ký tên, người công nhân cần ghi thêm gì theo văn bản?", ["Ngày tháng", "Lý do", "Mã nhân viên", "Phòng ban"], 1, "Văn bản yêu cầu ký tên kèm theo việc ghi lý do.", 1);
  add(1, "Lợi ích chính của \"Biểu mẫu đơn giản\" là:", ["Giảm thời gian đào tạo", "Tăng khối lượng giấy tờ", "Yêu cầu phần mềm nâng cao", "Hạn chế tự chủ của công nhân"], 0, "Biểu mẫu đơn giản giúp công nhân dễ thực hiện và giảm thời gian học hỏi.", 1);
  add(1, "Để đảm bảo tính nhất quán trong ghi chép, cần:", ["Sử dụng ký hiệu đa dạng", "Dùng các đơn vị khác nhau", "Thống nhất đơn vị, ký hiệu, cách ghi", "Phụ thuộc vào sở thích cá nhân"], 2, "Việc thống nhất các yếu tố này giúp duy trì tính nhất quán và dễ truy xuất.", 1);
  add(1, "Khi phát hiện ghi sai số liệu nhiệt độ trên biểu mẫu giám sát CCP trong ca sản xuất, công nhân cần thực hiện thao tác sửa lỗi nào sau đây để đúng quy định quản lý chất lượng?", ["Gạch một đường qua số sai, viết lại số đúng bên cạnh, ký tên và ghi rõ lý do", "Dùng bút xóa che số sai, sau đó viết số đúng đè lên trên vết xóa", "Tẩy xóa sạch dấu vết số sai rồi ghi lại số đúng để giữ biểu mẫu sạch đẹp", "Xé bỏ biểu mẫu hỏng và chép lại toàn bộ dữ liệu sang một tờ biểu mẫu mới"], 0, "Theo nguyên tắc ghi chép hồ sơ chất lượng, khi sửa thông tin sai cần gạch một đường qua dữ liệu cũ, ghi số đúng, ký tên và nêu rõ lý do để đảm bảo tính minh bạch và khả năng truy xuất.", 2);
  add(1, "Để đảm bảo công nhân trực tiếp vận hành ca đêm thực hiện đúng và đủ việc ghi chép kiểm soát an toàn thực phẩm, cán bộ QA nên thiết kế biểu mẫu theo tiêu chí nào?", ["Tích hợp thật nhiều thông tin chi tiết và thuật ngữ kỹ thuật chuyên sâu", "Đơn giản, tích hợp để công nhân dễ hiểu, dễ thực hiện và tiết kiệm thời gian", "Yêu cầu công nhân tự vẽ bảng biểu vào sổ tay cá nhân theo từng ca", "Tách nhỏ thành nhiều biểu mẫu riêng biệt cho từng thông số kiểm tra"], 1, "Biểu mẫu ghi chép tại khu vực sản xuất cần đơn giản và tích hợp để công nhân dễ dàng thao tác, hạn chế sai sót và duy trì việc ghi chép đều đặn.", 2);
  add(1, "Tại một nhà máy chế biến thực phẩm, việc ca sáng ghi nhiệt độ theo độ C (°C) còn ca tối lại ghi theo độ F (°F) trên cùng một biểu mẫu theo dõi sẽ gây ra hậu quả trực tiếp nào?", ["Làm tăng chi phí in ấn biểu mẫu của nhà máy", "Gây khó khăn cho việc đọc, đối chiếu và truy xuất dữ liệu khi xảy ra sự cố chất lượng", "Giúp công nhân linh hoạt hơn trong việc sử dụng các thiết bị đo khác nhau", "Không gây ảnh hưởng gì vì hai đơn vị đo có thể quy đổi qua lại"], 1, "Không thống nhất đơn vị đo lường sẽ vi phạm nguyên tắc 'Dễ đọc – Dễ truy xuất', gây nhầm lẫn khi phân tích dữ liệu và truy xuất nguồn gốc.", 2);
  add(1, "Trong đợt đánh giá hệ thống ISO 22000, chuyên gia phát hiện một số nhật ký kiểm tra vệ sinh nhà xưởng có vết bút xóa trắng. Hành động dùng bút xóa này đã vi phạm quy tắc ghi chép nào?", ["Quy tắc lưu trữ hồ sơ tối thiểu 2 năm", "Quy tắc gạch một đường, ký tên và ghi rõ lý do khi hiệu chỉnh thông tin", "Quy tắc phân công trách nhiệm giám sát cho tổ trưởng", "Quy tắc bảo mật thông tin nội bộ của doanh nghiệp"], 1, "Dùng bút xóa làm mất dữ liệu gốc và tính minh bạch của hồ sơ. Đúng quy trình phải gạch một đường qua chỗ sai, ký tên và ghi lý do.", 2);
  add(1, "Doanh nghiệp thực phẩm muốn chuẩn hóa hệ thống hồ sơ để đạt tiêu chí 'Dễ đọc – Dễ truy xuất' đối với các dữ liệu kiểm soát kim loại trong sản phẩm. Giải pháp nào sau đây là phù hợp nhất?", ["Cho phép mỗi nhân viên kiểm tra tự quy định ký hiệu đánh giá riêng theo thói quen", "Thống nhất đơn vị đo, ký hiệu chuẩn và quy cách ghi chép đồng bộ trên toàn hệ thống", "Khuyến khích nhân viên viết tắt tùy ý để ghi chép nhanh chóng", "Chỉ ghi chép các trường hợp phát hiện sự cố, bỏ qua các lần kiểm tra đạt yêu cầu"], 1, "Để hồ sơ dễ đọc và dễ truy xuất, cần phải thống nhất đồng bộ về đơn vị đo, hệ thống ký hiệu và quy cách ghi chép giữa tất cả các nhân viên và bộ phận.", 2);
  add(1, "Lợi ích chính của việc sử dụng biểu mẫu đơn giản, tích hợp trong quản lý chất lượng là gì?", ["Giảm thiểu giấy tờ và thời gian ghi chép", "Tăng khả năng xảy ra lỗi của công nhân", "Làm cho việc truy xuất dữ liệu trở nên khó khăn", "Yêu cầu đào tạo nâng cao cho người dùng"], 0, "Biểu mẫu đơn giản, tích hợp giúp giảm khối lượng công việc và thời gian xử lý, đồng thời giảm lỗi nhập liệu.", 3);
  add(1, "Yếu tố nào góp phần quan trọng nhất vào việc làm cho biểu mẫu \"Dễ đọc – Dễ truy xuất\"?", ["Sử dụng các ký hiệu phức tạp", "Thống nhất đơn vị và ký hiệu", "Sử dụng nhiều kiểu chữ khác nhau", "Viết dài dòng, không ngắt đoạn"], 1, "Việc thống nhất đơn vị và ký hiệu giúp người đọc nhanh chóng hiểu và so sánh dữ liệu.", 3);
  add(1, "Trong đánh giá rủi ro, việc ghi lại lý do ký tên trên biểu mẫu giúp:", ["Tăng độ dài của biểu mẫu", "Cung cấp khả năng truy xuất nguồn gốc và trách nhiệm", "Gây nhầm lẫn cho người kiểm tra", "Không có ảnh hưởng gì"], 1, "Lý do ký tên tạo ra tính truy xuất, cho phép xác định nguyên nhân và người chịu trách nhiệm khi có sự cố.", 3);
  add(1, "Việc chuẩn hoá ký hiệu và đơn vị trên biểu mẫu hỗ trợ:", ["Tăng tính mơ hồ trong báo cáo", "Dễ dàng so sánh và tổng hợp dữ liệu", "Giảm mức độ tuân thủ quy chuẩn", "Tăng thời gian đào tạo nhân viên"], 1, "Chuẩn hoá giúp dữ liệu nhất quán, giảm sai sót và hỗ trợ phân tích nhanh chóng.", 3);
  add(1, "Biểu mẫu được mô tả là \"đọc – truy xuất dễ\" sẽ hỗ trợ tốt nhất cho:", ["Quyết định nhanh chóng và hiệu quả", "Tăng chi phí vận hành", "Giảm tính minh bạch", "Báo cáo phức tạp, khó hiểu"], 0, "Khi thông tin dễ đọc và truy xuất, người quản lý có thể đưa ra quyết định kịp thời, giảm rủi ro.", 3);
  add(5, "ATTP (An toàn thực phẩm) được định nghĩa là gì?", ["Thực phẩm không gây hại sức khỏe", "Thực phẩm có màu sắc hấp dẫn", "Thực phẩm có giá rẻ", "Thực phẩm nhập khẩu"], 0, "ATTP là thực phẩm không gây hại cho sức khỏe người tiêu dùng.", 1);
  add(5, "Trong các nhóm thực phẩm dưới đây, nhóm nào không được liệt kê trong nội dung?", ["Thực phẩm tươi sống", "Thực phẩm chức năng", "Thực phẩm gia vị", "Thực phẩm biến đổi gen"], 2, "Nhóm thực phẩm gia vị không xuất hiện trong danh sách các nhóm thực phẩm đã nêu.", 1);
  add(5, "Luật An toàn thực phẩm của Việt Nam được thông qua bởi cơ quan nào?", ["Quốc hội khóa XII", "Chính phủ", "Bộ Y tế", "Ủy ban Nhân dân"], 0, "Luật An toàn thực phẩm được Quốc hội khóa XII thông qua ngày 17/06/2010.", 1);
  add(5, "Nguyên tắc nào nói rằng quản lý ATTP dựa trên quy chuẩn kỹ thuật (bắt buộc) và tiêu chuẩn công bố?", ["Quản lý dựa trên quy chuẩn kỹ thuật (bắt buộc) và tiêu chuẩn công bố", "Quản lý dựa trên quảng cáo", "Quản lý dựa trên lợi nhuận", "Quản lý dựa trên thị trường"], 0, "Luật quy định quản lý ATTP phải dựa trên quy chuẩn kỹ thuật bắt buộc và các tiêu chuẩn đã công bố.", 1);
  add(5, "Yếu tố nào là một phần của quản lý dựa trên phân tích nguy cơ (Risk‑based) trong ATTP?", ["Phân tích nguy cơ", "Tăng giá bán", "Giảm chất lượng", "Mở rộng thị trường"], 0, "Phân tích nguy cơ là nền tảng của quản lý dựa trên rủi ro trong an toàn thực phẩm.", 1);
  add(5, "Một trang trại nuôi bò sữa thực hiện vắt sữa và làm lạnh bảo quản sữa tươi trước khi vận chuyển đến nhà máy đóng hộp. Theo Luật An toàn thực phẩm 2010, hoạt động vắt sữa bò tại trang trại thuộc nhóm công đoạn nào?", ["Sản xuất ban đầu", "Sơ chế thực phẩm", "Chế biến thực phẩm", "Kinh doanh thực phẩm"], 0, "Sản xuất ban đầu là quá trình thực hiện một, một số hoặc toàn bộ các hoạt động trồng trọt, chăn nuôi, thu hái, đánh bắt, khai thác.", 2);
  add(5, "Công ty X sản xuất chả lụa đóng gói. Trong đợt kiểm tra đột xuất, cơ quan chức năng phát hiện lô hàng bị vi phạm chỉ tiêu vi sinh vật. Theo nguyên tắc quản lý an toàn thực phẩm, chủ thể nào phải chịu trách nhiệm chính về an toàn của lô sản phẩm này?", ["Cơ quan kiểm nghiệm thực phẩm", "Tổ chức, cá nhân sản xuất, kinh doanh thực phẩm X", "Ủy ban nhân dân địa phương nơi bán hàng", "Người tiêu dùng đã mua sản phẩm"], 1, "Nguyên tắc quản lý ATTP quy định: Tổ chức, cá nhân sản xuất, kinh doanh thực phẩm chịu trách nhiệm về an toàn đối với thực phẩm do mình sản xuất, kinh doanh.", 2);
  add(5, "Một doanh nghiệp tiến hành phối trộn thêm vi chất kẽm và sắt vào sản phẩm bột dinh dưỡng cho trẻ em nhằm phòng chống suy dinh dưỡng. Theo Luật ATTP 2010, sản phẩm này được phân loại vào nhóm nào?", ["Thực phẩm tươi sống", "Thực phẩm biến đổi gen", "Thực phẩm tăng cường vi chất dinh dưỡng", "Thực phẩm chức năng"], 2, "Thực phẩm tăng cường vi chất dinh dưỡng là thực phẩm được bổ sung vitamin, chất khoáng, chất dinh dưỡng khác vào thực phẩm.", 2);
  add(5, "Hợp tác xã nông nghiệp A muốn áp dụng tiêu chuẩn quản lý chất lượng an toàn trong khâu trồng trọt rau củ quả để đáp ứng chính sách khuyến khích của Nhà nước. Hệ thống nào sau đây là phù hợp nhất cho giai đoạn sản xuất ban đầu này?", ["GMP (Thực hành sản xuất tốt)", "GAP (Thực hành sản xuất nông nghiệp tốt)", "GHP (Thực hành vệ sinh tốt)", "HACCP (Hệ thống phân tích mối nguy và điểm kiểm soát tới hạn)"], 1, "GAP (Good Agricultural Practices) là Thực hành sản xuất nông nghiệp tốt, áp dụng cho quá trình sản xuất ban đầu (trồng trọt, chăn nuôi, thủy sản).", 2);
  add(5, "Bà B bán đồ ăn sáng bằng xe đẩy lưu động trên vỉa hè trước cổng trường học. Theo định nghĩa của Luật An toàn thực phẩm 2010, hình thức kinh doanh của bà B thuộc nhóm nào?", ["Cơ sở ăn uống tập thể", "Cơ sở sơ chế thực phẩm", "Thức ăn đường phố", "Kinh doanh thực phẩm bao gói sẵn"], 2, "Thức ăn đường phố là thực phẩm được bán rong, bán trên vỉa hè, nơi công cộng hoặc những nơi tương tự.", 2);
  add(5, "Theo nguyên tắc quản lý dựa trên phân tích nguy cơ (risk‑based) trong Luật An toàn thực phẩm, yếu tố nào sau đây được nhấn mạnh nhất?", ["Áp dụng HACCP cho tất cả các doanh nghiệp", "Đánh giá nguy cơ xuyên suốt chuỗi sản xuất‑tiêu thụ", "Chỉ kiểm soát ở giai đoạn sản xuất cuối cùng", "Tập trung vào quảng cáo và nhãn mác"], 1, "Nguyên tắc risk‑based yêu cầu phân tích nguy cơ ở mọi khâu của chuỗi thực phẩm.", 3);
  add(5, "Trong các quy chuẩn kỹ thuật bắt buộc theo Luật ATTP, yếu tố nào sau đây không thuộc danh mục bắt buộc?", ["GMP (Good Manufacturing Practice)", "GHP (Good Hygiene Practice)", "HACCP (Hazard Analysis Critical Control Point)", "Chiến lược marketing sản phẩm"], 3, "Chiến lược marketing là hoạt động thương mại, không phải quy chuẩn kỹ thuật bắt buộc.", 3);
  add(5, "Trong khái niệm rủi ro thực phẩm, thuật ngữ nào mô tả khả năng một thực phẩm bị nhiễm chất gây hại?", ["Ô nhiễm", "Nguy cơ ô nhiễm", "Rủi ro", "Tiếp xúc"], 2, "Rủi ro là khả năng (probability) thực phẩm bị nhiễm và gây hại.", 3);
  add(5, "Theo Luật ATTP, ai chịu trách nhiệm chính trong việc bảo đảm an toàn thực phẩm ở giai đoạn kinh doanh (phân phối, bán lẻ)?", ["Người tiêu dùng", "Cơ quan kiểm tra nhà nước", "Doanh nghiệp phân phối", "Nhà sản xuất"], 2, "Doanh nghiệp phân phối phải đảm bảo điều kiện bảo quản, vận chuyển và an toàn thực phẩm khi đưa sản phẩm tới người tiêu dùng.", 3);
  add(5, "Trong phân loại thực phẩm của Luật ATTP, loại thực phẩm nào được định nghĩa là \"thực phẩm tươi sống, chưa qua chế biến\"?", ["Thực phẩm tươi sống", "Thực phẩm chức năng", "Thực phẩm biến đổi gen", "Thực phẩm đóng gói sẵn"], 0, "Thực phẩm tươi sống là thực phẩm chưa qua bất kỳ quá trình chế biến nào, như thịt, cá, rau quả.", 3);
  add(1, "Điều nào sau đây KHÔNG bị coi là hành vi vi phạm pháp luật thuộc nhóm quy định về nguyên liệu thực phẩm?", ["Sử dụng thực phẩm đã hết hạn sử dụng để chế biến", "Sử dụng phụ gia thực phẩm ngoài danh mục cho phép", "Sử dụng nguyên liệu không rõ nguồn gốc xuất xứ", "Sử dụng phụ gia thực phẩm trong danh mục cho phép và đúng liều lượng quy định"], 3, "Sử dụng phụ gia nằm trong danh mục cho phép và đúng hàm lượng quy định là hành vi hoàn toàn hợp pháp.", 1);
  add(1, "The maximum special penalty for a food safety violation can be up to how many times the value of the violated food?", ["5 times", "7 times", "10 times", "12 times"], 1, "The text states the special penalty is at most 7 times the value of the food.", 1);
  add(1, "Which fee is described as usually 150,000 VND (except for the training fee)?", ["Basic fee", "Inspection fee", "Import fee", "Service fee"], 0, "The basic fee (lệ phí cơ bản) is commonly 150k, while the training fee is 30k.", 1);
  add(1, "For fresh food (thực phẩm tươi sống), which condition must be met before it can be circulated?", ["It must be packaged in plastic", "It must have traceability and undergo quarantine", "It must contain additives", "It must be processed"], 1, "Fresh foods require source traceability and, especially for meat and fish, a quarantine certificate.", 1);
  add(1, "Theo Luật An toàn Thực phẩm Việt Nam, quyền nào sau đây là quyền hợp pháp của người tiêu dùng thực phẩm?", ["Tự cấp giấy chứng nhận hợp quy cho sản phẩm", "Được cung cấp thông tin trung thực về chất lượng và an toàn của thực phẩm", "Tự quyết định giá bán của sản phẩm trên thị trường", "Tự ý tham gia vào dây chuyền sản xuất thực phẩm của cơ sở"], 1, "Người tiêu dùng có quyền được thông tin đầy đủ, trung thực về an toàn thực phẩm và yêu cầu bồi thường thiệt hại nếu thực phẩm không an toàn.", 1);
  add(5, "Công ty X bị phát hiện sản xuất một lô hàng thực phẩm chức năng không đạt quy chuẩn kỹ thuật với tổng giá trị lô hàng là 100 triệu đồng. Theo Luật An toàn thực phẩm, mức xử phạt vi phạm hành chính tối đa có thể áp dụng đối với công ty X (chưa tính hình phạt bổ sung) là bao nhiêu?", ["100 triệu đồng", "300 triệu đồng", "700 triệu đồng", "1 tỷ đồng"], 2, "Theo quy định xử phạt vi phạm ATTP, mức phạt tiền tối đa có thể áp dụng bằng 7 lần giá trị thực phẩm vi phạm (7 x 100 triệu = 700 triệu đồng).", 2);
  add(5, "Cơ sở sản xuất bánh kẹo Y sử dụng xe tải chuyên chở hóa chất bảo vệ thực vật (chưa được làm sạch) để chở nguyên liệu bột mì về xưởng sản xuất. Hành vi này vi phạm quy định thuộc nhóm hành vi bị cấm nào?", ["Nhóm nguyên liệu", "Nhóm vận chuyển", "Nhóm gian lận", "Nhóm môi trường"], 1, "Sử dụng phương tiện vận chuyển gây ô nhiễm hoặc chở hóa chất chưa được làm sạch thuộc Nhóm hành vi bị cấm về vận chuyển.", 2);
  add(5, "Siêu thị Z phát hiện một lô nước hoa quả đóng chai đang bày bán có dấu hiệu bị biến chất và rò rỉ hóa chất từ bao bì. Theo nghĩa vụ pháp lý của cơ sở kinh doanh thực phẩm, siêu thị Z phải thực hiện hành động nào sau đây đầu tiên?", ["Tự tiến hành nghiệm thu lại chất lượng sản phẩm tại phòng lab nội bộ", "Giảm giá bán sản phẩm để nhanh chóng thanh lý lô hàng", "Tạm thời ngừng bán, báo cáo sự cố ATTP và phối hợp thu hồi xử lý", "Tiếp tục bán hết số hàng còn lại trên kệ rồi mới ngừng nhập mới"], 2, "Bên kinh doanh có nghĩa vụ ngừng bán ngay lập tức khi phát hiện hàng hóa nguy hiểm/không an toàn, báo cáo sự cố và phối hợp xử lý.", 2);
  add(5, "Doanh nghiệp M muốn đưa ra thị trường một dòng sản phẩm thực phẩm chức năng mới hỗ trợ giảm mỡ máu. Theo điều kiện bảo đảm ATTP đối với từng loại thực phẩm, doanh nghiệp M bắt buộc phải có điều kiện riêng biệt nào sau đây?", ["Giấy kiểm dịch động vật tươi sống", "Bằng chứng khoa học chứng minh tác dụng và kết quả thử nghiệm hiệu quả", "Giấy chứng nhận chiếu xạ sản phẩm", "Giấy phép lưu hành độc quyền toàn quốc"], 1, "Thực phẩm chức năng có yêu cầu riêng biệt là bắt buộc phải có bằng chứng khoa học chứng minh tác dụng và đã được thử nghiệm về hiệu quả.", 2);
  add(5, "Quản lý của một bếp ăn tập thể phát hiện nhân viên A đang trực tiếp sơ chế thực phẩm bị mắc bệnh truyền nhiễm. Tuy nhiên, do thiếu người nên quản lý vẫn cho nhân viên A tiếp tục làm việc. Cơ sở này đã vi phạm nhóm hành vi bị cấm nào?", ["Nhóm con người & cơ sở", "Nhóm gian lận", "Nhóm môi trường", "Nhóm pháp lý"], 0, "Cho người đang mắc bệnh truyền nhiễm tham gia trực tiếp vào quá trình sản xuất, kinh doanh thực phẩm thuộc Nhóm hành vi bị cấm về con người & cơ sở.", 2);
  add(1, "Trong nhóm nguyên liệu, yếu tố nào sau đây không được liệt kê là vi phạm?", ["Sử dụng thực phẩm hết hạn", "Sử dụng nguyên liệu không rõ nguồn gốc", "Sử dụng phụ gia ngoài danh mục", "Sử dụng nguyên liệu hữu cơ có chứng nhận"], 3, "Nguyên liệu hữu cơ có chứng nhận không nằm trong các vi phạm được nêu.", 3);
  add(2, "Mức phạt đặc biệt tối đa cho vi phạm an toàn thực phẩm bằng tiền là bao nhiêu lần giá trị thực phẩm vi phạm?", ["3 lần", "5 lần", "7 lần", "10 lần"], 2, "Quy định cho mức phạt đặc biệt tối đa là ≤ 7 lần giá trị thực phẩm vi phạm.", 3);
  add(3, "Lệ phí nào được ghi nhớ là đa số = 150.000 VND, riêng tập huấn = 30.000 VND?", ["Phí nhập khẩu", "Lệ phí cơ bản", "Phí kiểm tra định kỳ", "Phí dịch vụ ăn uống"], 1, "Lệ phí cơ bản thường là 150k, còn phí tập huấn 30k.", 3);
  add(4, "Đối với thực phẩm tươi sống, điều kiện bắt buộc trước khi lưu thông là:", ["Phải có nhãn dinh dưỡng", "Phải truy xuất nguồn gốc và có kiểm dịch", "Phải không chứa bất kỳ phụ gia nào", "Phải đóng gói bằng nhựa PET"], 1, "Thực phẩm tươi sống yêu cầu truy xuất nguồn gốc và kiểm dịch, đặc biệt đối với thịt, cá.", 3);
  add(5, "Trong các quyền và nghĩa vụ, người tiêu dùng có trách nhiệm nào sau đây?", ["Đảm bảo nhãn mác đầy đủ", "Thực hiện kiểm soát chất lượng nội bộ", "Sử dụng đúng cách và báo cáo nguy cơ an toàn thực phẩm", "Kiểm tra nguồn gốc sản phẩm"], 2, "Người tiêu dùng được yêu cầu sử dụng đúng cách và thông báo nguy cơ an toàn thực phẩm.", 3);
  add(1, "Theo nội dung, yếu tố cốt lõi cần đảm bảo khi vận chuyển thực phẩm là gì?", ["Không gây nhiễm chéo", "Đảm bảo điều kiện nhiệt độ", "Sử dụng bao bì kín", "Có giấy chứng nhận ATTP"], 1, "Vận chuyển phải duy trì nhiệt độ thích hợp để thực phẩm không bị hỏng.", 1);
  add(1, "Trong quảng cáo thực phẩm, yếu tố nào sau đây không phải là yêu cầu bắt buộc theo quy định?", ["Xin phép trước khi quảng cáo", "Quảng cáo đúng nội dung đã duyệt", "Sử dụng người nổi tiếng để tăng uy tín", "Đăng ký nội dung quảng cáo"], 2, "Quy định không yêu cầu dùng người nổi tiếng; chỉ cần xin phép, đăng ký và đúng nội dung.", 1);
  add(1, "Phân tích nguy cơ (Risk Analysis) gồm ba trụ cột nào?", ["Đánh giá – Quản lý – Truyền thông", "Kiểm soát – Báo cáo – Kiểm tra", "Phát hiện – Đáp ứng – Khắc phục", "Lập kế hoạch – Thực hiện – Đánh giá"], 0, "Ba trụ cột được nêu là Đánh giá, Quản lý và Truyền thông.", 1);
  add(1, "Giấy chứng nhận An toàn Thực phẩm có thời hạn hiệu lực bao lâu?", ["1 năm", "2 năm", "3 năm", "5 năm"], 2, "Giấy chứng nhận ATTP có hiệu lực 3 năm và phải xin lại trước 6 tháng.", 1);
  add(1, "Khi xảy ra sự cố an toàn thực phẩm, quy trình xử lý đúng là:", ["Báo cáo, thu hồi, điều tra, thông báo, phòng ngừa", "Chỉ thông báo nội bộ", "Chờ phản hồi từ người tiêu dùng", "Thực hiện kiểm tra sau khi sự cố qua"], 0, "Quy trình gồm Cứu – Điều tra – Thu hồi – Thông báo – Phòng lại.", 1);
  add(5, "Một cơ sở sản xuất chế biến suất ăn công nghiệp đã được cấp Giấy chứng nhận cơ sở đủ điều kiện ATTP. Theo quy định, nếu muốn tiếp tục hoạt động, cơ sở phải nộp hồ sơ xin cấp lại Giấy chứng nhận trước khi hết hạn bao lâu?", ["1 tháng", "3 tháng", "6 tháng", "12 tháng"], 2, "Giấy chứng nhận ATTP có hiệu lực 3 năm và cơ sở phải tiến hành xin cấp lại trước 6 tháng tính đến ngày hết hạn.", 2);
  add(5, "Công ty chế biến thủy sản X đã áp dụng hệ thống quản lý chất lượng tiên tiến HACCP. Tần suất kiểm tra ATTP định kỳ tối đa của cơ quan quản lý nhà nước đối với công ty X là bao nhiêu?", ["Không quá 1 lần/năm", "Không quá 2 lần/năm", "Không quá 3 lần/năm", "Tùy thuộc vào quyết định đột xuất của thanh tra"], 1, "Đối với cơ sở đã có chứng nhận HACCP/GMP, tần suất kiểm tra định kỳ được quy định tối đa không quá 2 lần/năm (so với cơ sở bình thường là ≤ 3 lần/năm).", 2);
  add(5, "Nhà hàng A tổ chức tiệc cưới và xảy ra sự cố ngộ độc thực phẩm khiến 50 khách hàng phải nhập viện. Theo Luật An toàn thực phẩm, trách nhiệm tài chính của nhà hàng A xử lý như thế nào?", ["Chỉ phải chịu tiền phạt vi phạm hành chính, chi phí điều trị do nhà nước hỗ trợ", "Phải chi trả toàn bộ chi phí xử lý ngộ độc thực phẩm và bồi thường thiệt hại cho người bị ngộ độc", "Chỉ chi trả chi phí cấp cứu ban đầu cho các nạn nhân tại bệnh viện", "Khai báo với cơ quan y tế và không phải bồi thường nếu nguyên liệu do bên thứ ba cung cấp"], 1, "Doanh nghiệp/cơ sở gây ra sự cố ngộ độc thực phẩm có trách nhiệm phải chi trả toàn bộ chi phí xử lý sự cố và bồi thường thiệt hại cho nạn nhân.", 2);
  add(5, "Công ty B sản xuất thực phẩm bảo vệ sức khỏe và chuẩn bị phát sóng video quảng cáo trên truyền hình. Hành vi nào sau đây của Công ty B bị coi là VI PHẠM pháp luật về quảng cáo thực phẩm?", ["Thực hiện đăng ký nội dung quảng cáo trước khi tiến hành phát sóng", "Phát sóng đúng chính xác các nội dung đã được cơ quan có thẩm quyền phê duyệt", "Sử dụng hình ảnh bác sĩ, dược sĩ phát biểu khuyên dùng sản phẩm để tăng lòng tin", "Nêu rõ các thông tin cảnh báo sức khỏe theo hướng dẫn trên nhãn sản phẩm"], 2, "Pháp luật nghiêm cấm việc sử dụng hình ảnh, uy tín của bác sĩ, bệnh nhân, cơ sở y tế để thực hiện quảng cáo thực phẩm.", 2);
  add(5, "Một lô bánh kẹo nhập khẩu bị cơ quan chức năng phát hiện chứa chất phụ gia vượt quá ngưỡng cho phép và bị ra quyết định thu hồi bắt buộc. Biện pháp nào sau đây KHÔNG thuộc các hình thức xử lý thực phẩm bị thu hồi theo quy định?", ["Sửa lỗi ghi nhãn hoặc khắc phục vi phạm", "Chuyển mục đích sử dụng khác", "Tiêu hủy hoặc tái xuất", "Cho phép bán hạ giá xả kho để thu hồi vốn"], 3, "4 hình thức xử lý thực phẩm thu hồi theo quy định bao gồm: Sửa lỗi, Chuyển mục đích sử dụng, Tái xuất, hoặc Tiêu hủy. Việc tiếp tục bán hạ giá sản phẩm không đạt ATTP là hoàn toàn cấm.", 2);
  add(1, "Trong quá trình phân tích nguy cơ, 4 nhóm đối tượng cần phân tích gồm: thực phẩm dễ gây ngộ độc cao; thực phẩm vi phạm quy chuẩn nhiều; môi trường/cơ sở nghi ô nhiễm; và:", ["Thực phẩm có giá thành cao", "Thực phẩm có nguồn gốc nhập khẩu", "Thực phẩm không có nhãn", "Thực phẩm không có bảo quản"], 0, "Nhóm thứ tư là \"Theo yêu cầu quản lý\"; các đáp án còn lại không thuộc danh sách.", 3);
  add(1, "Ba trụ cột của hoạt động phân tích nguy cơ là Đánh giá, Quản lý và:", ["Kiểm soát", "Truyền thông", "Giám sát", "Kiểm định"], 1, "Trụ cột thứ ba là Truyền thông nguy cơ, bao gồm cung cấp thông tin phòng tránh, cảnh báo và dự báo.", 3);
  add(2, "Giấy chứng nhận an toàn thực phẩm yêu cầu kiểm tra HACCP/GMP không quá bao nhiêu lần mỗi năm?", ["1 lần/năm", "2 lần/năm", "3 lần/năm", "4 lần/năm"], 1, "Theo quy định, HACCP/GMP được kiểm tra tối đa 2 lần/năm.", 3);
  add(3, "Khi có sự cố an toàn thực phẩm, quy trình xử lý đúng thứ tự là:", ["Cứu – Điều tra – Thu hồi – Thông báo – Phòng lại", "Điều tra – Cứu – Thông báo – Thu hồi – Phòng lại", "Thu hồi – Cứu – Điều tra – Thông báo – Phòng lại", "Thông báo – Cứu – Điều tra – Thu hồi – Phòng lại"], 0, "Chuỗi hành động chuẩn: Cứu (cấp cứu), Điều tra nguyên nhân, Thu hồi sản phẩm, Thông báo rộng rãi, Phòng ngừa tái diễn.", 3);
  add(4, "Trong 7 lỗi chính dẫn đến thu hồi thực phẩm, lỗi nào không được liệt kê trong nội dung?", ["Hết hạn", "Sai quy chuẩn", "Công nghệ chưa được phép", "Giá bán quá cao"], 3, "Giá bán quá cao không phải là nguyên nhân thu hồi; các lỗi còn lại đều thuộc 7 lỗi chính.", 3);
  add(1, "Theo quy định ghi nhãn thực phẩm, thông tin thời hạn nào bắt buộc phải ghi trên nhãn?", ["HSD / Dùng đến / Tốt nhất trước", "Ngày sản xuất", "Ngày nhập kho", "Ngày kiểm định"], 0, "Văn bản yêu cầu ghi nhãn thời hạn dưới dạng “HSD / Dùng đến / Tốt nhất trước\".", 1);
  add(1, "Ký hiệu \"GMO\" trên nhãn thực phẩm nghĩa là gì?", ["Thực phẩm biến đổi gen", "Thực phẩm không gây dị ứng", "Thực phẩm hữu cơ", "Thực phẩm đã qua xử lý nhiệt"], 0, "GMO được định nghĩa là \"thực phẩm biến đổi gen\" và phải được ghi trên nhãn.", 1);
  add(1, "Cơ quan quản lý ATTP được xem là quan trọng nhất theo nội dung văn bản?", ["Bộ Y tế", "Bộ Nông nghiệp & PTNT", "Bộ Công thương", "Chính phủ"], 0, "Bộ Y tế được nêu là cơ quan quan trọng nhất, chịu trách nhiệm chính trong quản lý ATTP.", 1);
  add(1, "Thời hạn tối đa để hoàn thành thanh tra cấp sở là bao lâu?", ["≤ 30 ngày (max 45)", "≤ 45 ngày (max 70)", "≤ 60 ngày (max 90)", "≤ 15 ngày (max 20)"], 0, "Văn bản quy định thời hạn thanh tra cấp sở ≤ 30 ngày, tối đa 45 ngày.", 1);
  add(1, "Trong các nhóm vi phạm được liệt kê, nhóm nào không xuất hiện trong văn bản?", ["Sai nguyên liệu", "Sai phụ gia", "Quá hạn sử dụng", "Sai hóa chất"], 2, "Nhóm vi phạm được nêu gồm sai nguyên liệu, sai phụ gia, sai hóa chất; \"Quá hạn sử dụng\" không được liệt kê.", 1);
  add(5, "Công ty A chuẩn bị đưa ra thị trường dòng sản phẩm nước uống đóng chai và thực phẩm chức năng hỗ trợ làm đẹp. Theo quy định pháp luật về quản lý nhà nước, cơ quan nào chịu trách nhiệm chính trong việc quản lý an toàn thực phẩm đối với các nhóm sản phẩm này?", ["Bộ Y tế", "Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Công Thương", "Ủy ban nhân dân cấp tỉnh"], 0, "Bộ Y tế chịu trách nhiệm quản lý nhà nước đối với thực phẩm chức năng, nước đóng chai, phụ gia thực phẩm và bao bì chứa đựng thực phẩm.", 2);
  add(5, "Một đoàn thanh tra chuyên ngành thuộc Sở Y tế tiến hành thanh tra đột xuất tại một cơ sở sản xuất nước giải khát trên địa bàn tỉnh. Thời hạn thanh tra tối đa (bao gồm cả thời gian gia hạn) đối với đoàn thanh tra cấp Sở là bao nhiêu ngày?", ["30 ngày", "45 ngày", "70 ngày", "60 ngày"], 1, "Thời hạn thanh tra an toàn thực phẩm đối với cấp Sở là không quá 30 ngày, trường hợp phức tạp có thể gia hạn nhưng tối đa không quá 45 ngày.", 2);
  add(5, "Trang trại X kinh doanh quy mô lớn các mặt hàng nông sản thô gồm rau tươi, trứng gà, thịt lợn và mật ong nguyên chất chưa qua chế biến sâu. Cơ quan chịu trách nhiệm quản lý an toàn thực phẩm đối với các loại nguyên liệu này là:", ["Bộ Y tế", "Bộ Công Thương", "Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Khoa học và Công nghệ"], 2, "Bộ Nông nghiệp và Phát triển nông thôn chịu trách nhiệm quản lý an toàn thực phẩm từ giai đoạn đầu (nguyên liệu nông, lâm, thủy sản, thịt, cá, rau, trứng, sữa tươi, mật ong).", 2);
  add(5, "Một doanh nghiệp sản xuất sữa hộp chế biến công nghiệp và phân phối vào hệ thống siêu thị, chợ trung tâm. Cơ quan quản lý nhà nước chịu trách nhiệm chính đối với mặt hàng sữa chế biến và lưu thông trên thị trường này là:", ["Bộ Y tế", "Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Công Thương", "Ủy ban nhân dân cấp huyện"], 2, "Bộ Công Thương chịu trách nhiệm quản lý sữa chế biến, rượu bia, nước giải khát, dầu thực vật và các hoạt động lưu thông, chợ, siêu thị.", 2);
  add(5, "Khi phát hiện một quán ăn kinh doanh thức ăn đường phố tại địa phương vi phạm nghiêm trọng về điều kiện vệ sinh an toàn thực phẩm, cơ quan nào có thẩm quyền trực tiếp kiểm tra và xử lý vi phạm tại chỗ?", ["Bộ Y tế", "Cục Quản lý thị trường", "Bộ Nông nghiệp và Phát triển nông thôn", "Ủy ban nhân dân các cấp"], 3, "Ủy ban nhân dân các cấp chịu trách nhiệm quản lý an toàn thực phẩm tại địa phương đối với cơ sở nhỏ lẻ, thức ăn đường phố và chợ địa phương.", 2);
  add(1, "Đối với nhãn đặc biệt của thực phẩm có phụ gia, yêu cầu ghi thông tin nào sau đây là đúng?", ["Chỉ ghi tên phụ gia", "Tên phụ gia, liều lượng và cách dùng", "Tên phụ gia và thời hạn sử dụng", "Chỉ ghi \"phụ gia thực phẩm\""], 1, "Nhãn phụ gia phải ghi rõ \"phụ gia thực phẩm\" + liều lượng + cách dùng.", 3);
  add(1, "Cơ quan chịu trách nhiệm chính trong việc xây dựng chiến lược, quy chuẩn kỹ thuật và tiêu chuẩn an toàn thực phẩm là:", ["Bộ Nông nghiệp và Phát triển Nông thôn", "Bộ Công Thương", "Bộ Y tế", "Ủy ban nhân dân các cấp"], 2, "Bộ Y tế là cơ quan quan trọng nhất, chịu trách nhiệm xây dựng chiến lược, quy chuẩn và tiêu chuẩn ATTP.", 3);
  add(1, "Mức phạt tiền tối đa cho vi phạm hành chính an toàn thực phẩm là:", ["10 triệu đồng", "50 triệu đồng", "100 triệu đồng", "200 triệu đồng"], 2, "Theo quy định, phạt tiền tối đa cho vi phạm ATTP là 100 triệu đồng.", 3);
  add(1, "Trong các nhóm vi phạm thường xuyên xảy ra, nhóm nào được nhắc đến là \"RẤT HAY RA\" nhất?", ["Nhóm nguyên liệu – phụ gia", "Nhóm điều kiện sản xuất", "Nhóm giấy phép", "Nhóm xuất nhập khẩu"], 0, "Nhóm 1 (nguyên liệu – phụ gia) được liệt kê là nhóm vi phạm rất hay xuất hiện.", 3);
  add(1, "Thời hạn tối đa chuẩn cho một đợt thanh tra cấp Bộ (Bộ Y tế, NN&PTNT, Công Thương) là:", ["30 ngày", "45 ngày", "70 ngày", "90 ngày"], 1, "Thanh tra cấp Bộ phải hoàn thành trong ≤45 ngày (có thể kéo dài tới 70 ngày trong trường hợp đặc biệt).", 3);

  add(1, "Theo định nghĩa trong quản lý an toàn thực phẩm, an toàn thực phẩm được hiểu là gì?", ["Việc bảo đảm thực phẩm có giá trị dinh dưỡng cao nhất cho người tiêu dùng.", "Việc bảo đảm thực phẩm không gây hại đến sức khỏe và tính mạng con người khi được chế biến và tiêu thụ đúng mục đích sử dụng.", "Việc đáp ứng tất cả các tiêu chuẩn về bao bì và nhãn mác quốc tế.", "Việc duy trì mức giá rẻ nhất trên thị trường tiêu dùng."], 1, "An toàn thực phẩm là việc bảo đảm thực phẩm không gây hại đến sức khỏe, tính mạng con người khi được chế biến và tiêu thụ đúng mục đích sử dụng.", 1);
  add(1, "Yếu tố nào được khẳng định là điều kiện tiên quyết và là thuộc tính bắt buộc, không thể tách rời của chất lượng thực phẩm?", ["Giá trị dinh dưỡng", "Tính tiện dụng", "An toàn thực phẩm", "Giá trị cảm quan"], 2, "An toàn thực phẩm là điều kiện tiên quyết của chất lượng thực phẩm; một sản phẩm dù dinh dưỡng cao đến đâu nhưng không an toàn thì không có giá trị sử dụng.", 1);
  add(1, "Khái niệm 'Phòng vệ thực phẩm' (Food Defense) trong chuỗi cung ứng thực phẩm tập trung vào mục tiêu nào sau đây?", ["Tối ưu hóa chi phí sản xuất và phân phối thực phẩm.", "Ngăn ngừa các hành vi gây nhiễm bẩn cố ý hoặc phá hoại thực phẩm.", "Cải tiến hương vị và màu sắc tự nhiên của sản phẩm.", "Tăng thời hạn bảo quản thực phẩm bằng phụ gia hóa học."], 1, "Phòng vệ thực phẩm ngày càng quan trọng nhằm ngăn ngừa các hành vi gây nhiễm bẩn cố ý hoặc phá hoại thực phẩm trong toàn bộ chuỗi cung ứng.", 1);
  add(1, "Thuộc tính 'Chất lượng sử dụng' của một sản phẩm thực phẩm thể hiện rõ nhất qua yếu tố nào dưới đây?", ["Hàm lượng protein, lipid, vitamin và khoáng chất.", "Mức độ vi sinh vật gây bệnh và độc tố vi nấm.", "Tính tiện lợi của bao bì, khả năng bảo quản, thông tin ghi nhãn và giá cả phù hợp.", "Trình độ thiết bị máy móc chế biến tại nhà máy."], 2, "Chất lượng sử dụng thể hiện ở tính tiện lợi như bao bì, khả năng bảo quản, thông tin ghi nhãn và giá cả phù hợp.", 2);
  add(1, "Trong chuỗi cung ứng thực phẩm, nhà phân phối và bán lẻ đóng vai trò chính trong trách nhiệm nào?", ["Cấp chứng nhận HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn) cho cơ sở.", "Ban hành các văn bản quy phạm pháp luật về vệ sinh an toàn thực phẩm.", "Duy trì điều kiện bảo quản và lưu thông sản phẩm an toàn.", "Chịu trách nhiệm trực tiếp kiểm soát vi sinh vật tại công đoạn chế biến thô."], 2, "Nhà phân phối và bán lẻ chịu trách nhiệm duy trì điều kiện bảo quản và lưu thông sản phẩm trong chuỗi cung ứng.", 2);
  add(1, "Theo hệ thống quản lý chất lượng ISO 9000 (Hệ thống quản lý chất lượng), việc kiểm soát tốt từng công đoạn trong chuỗi sản xuất thực phẩm thuộc nguyên tắc nào?", ["Tập trung vào khách hàng (Customer Focus)", "Tiếp cận theo quá trình (Process Approach)", "Cải tiến liên tục (Continual Improvement)", "Quản lý mối quan hệ (Relationship Management)"], 1, "Tiếp cận theo quá trình (Process Approach) giúp kiểm soát tốt từng công đoạn trong chuỗi sản xuất.", 2);
  add(1, "Thuộc tính chất lượng thực phẩm phản ánh trình độ chế biến và khả năng duy trì sự ổn định của sản phẩm trong quá trình bảo quản và tiêu thụ được gọi là gì?", ["Chất lượng dinh dưỡng", "Chất lượng cảm quan", "Chất lượng công nghệ", "Chất lượng vệ sinh"], 2, "Chất lượng công nghệ phản ánh trình độ chế biến và khả năng duy trì sự ổn định của sản phẩm trong quá trình bảo quản và tiêu thụ.", 1);
  add(1, "Tại một nhà máy chế biến thịt đóng hộp, đoàn thanh tra phát hiện lô sản phẩm có chất lượng cảm quan rất tốt và giàu dinh dưỡng, nhưng mẫu kiểm nghiệm chứa vi khuẩn Clostridium botulinum sinh độc tố. Theo nguyên tắc quản lý chất lượng thực phẩm, lô sản phẩm này sẽ được xử lý như thế nào?", ["Vẫn được cấp phép lưu thông vì đạt tiêu chuẩn cảm quan và dinh dưỡng cao.", "Cho phép hạ giá thành để bán thanh lý thu hồi vốn.", "Không đạt chất lượng, không có giá trị sử dụng và bắt buộc phải thu hồi, xử lý hủy bỏ do vi phạm điều kiện an toàn thực phẩm.", "Chuyển sang làm thức ăn chăn nuôi mà không cần qua xử lý nhiệt."], 2, "An toàn thực phẩm là điều kiện tiên quyết của chất lượng thực phẩm. Một sản phẩm không bảo đảm an toàn thì không có giá trị sử dụng, dù có giá trị cảm quan hay dinh dưỡng cao, bắt buộc phải thu hồi và hủy bỏ.", 3);
  add(1, "Công ty A xuất khẩu lô hàng thủy sản sang thị trường Châu Âu nhưng bị từ chối nhập khẩu do vượt quá ngưỡng tồn dư hóa chất bảo vệ thực vật theo quy định của nước sở tại, mặc dù lô hàng đạt tiêu chuẩn lưu hành trong nước. Yếu tố nào đã tác động trực tiếp đến sự cố này?", ["Yếu tố phòng vệ thực phẩm chống phá hoại.", "Yếu tố kinh tế và thương mại quốc tế (sự tương thích về tiêu chuẩn an toàn giữa các quốc gia).", "Yếu tố tâm lý người tiêu dùng nội địa.", "Yếu tố năng lực quản lý chất lượng sử dụng bao bì."], 1, "Hoạt động xuất nhập khẩu chịu tác động mạnh bởi yếu tố kinh tế và thương mại quốc tế, đòi hỏi sự tương thích về tiêu chuẩn an toàn thực phẩm giữa các quốc gia.", 3);
  add(1, "Trong quá trình kiểm tra định kỳ tại nhà máy sản xuất sữa tươi, bộ phận QA (Đảm bảo chất lượng) phát hiện nguồn nước xả rửa thiết bị tiệt trùng có dấu hiệu nhiễm vi sinh vật vượt mức cho phép do sự cố đường ống. Cán bộ quản lý chất lượng cần nhận diện mối nguy này thuộc yếu tố nào và đưa ra biện pháp xử lý ra sao?", ["Thuộc yếu tố môi trường sản xuất; giải pháp là dừng ngay dây chuyền, khắc phục sự cố nguồn nước và tiến hành khử trùng lại toàn bộ hệ thống trước khi tiếp tục.", "Thuộc yếu tố kỳ vọng khách hàng; giải pháp là thay đổi thiết kế mẫu mã hộp sữa.", "Thuộc yếu tố phòng vệ thực phẩm; giải pháp là báo công an điều tra hành vi cố ý phá hoại.", "Thuộc yếu tố chất lượng công nghệ; giải pháp là tăng thêm hương liệu để át mùi."], 0, "Nguồn nước rửa thiết bị kém vệ sinh thuộc yếu tố môi trường sản xuất gây ô nhiễm vi sinh vật. Do đó cần dừng dây chuyền, xử lý nguồn nước và vệ sinh tiệt trùng thiết bị để bảo đảm an toàn thực phẩm.", 3);
  add(1, "Phương pháp Kiểm soát chất lượng (QC - Quality Control) tập trung chính vào hoạt động nào sau đây?", ["Kiểm tra sản phẩm nhằm phát hiện sai lỗi sau sản xuất", "Xây dựng hệ thống quản lý toàn bộ quá trình để phòng ngừa sai lỗi", "Huy động toàn bộ tổ chức tham gia cải tiến chất lượng", "Xác định và kiểm soát các mối nguy tại các điểm tới hạn"], 0, "Theo giáo trình, Kiểm soát chất lượng (QC) tập trung vào việc kiểm tra sản phẩm nhằm phát hiện sai lỗi sau khi đã sản xuất.", 1);
  add(1, "Đảm bảo chất lượng (QA - Quality Assurance) có điểm khác biệt cốt lõi nào so với Kiểm soát chất lượng (QC)?", ["QA tập trung kiểm tra sản phẩm cuối cùng, QC tập trung vào kiểm tra nguyên liệu đầu vào", "QA xây dựng hệ thống quản lý toàn bộ quá trình để phòng ngừa sai lỗi, trong khi QC tập trung phát hiện sai lỗi sau sản xuất", "QA chỉ áp dụng cho ngành thực phẩm, QC áp dụng cho ngành cơ khí", "QA do bộ phận kiểm nghiệm đảm nhận, QC do ban giám đốc trực tiếp thực hiện"], 1, "QA mang tính phòng ngừa thông qua việc xây dựng hệ thống quản lý toàn bộ quá trình, còn QC mang tính phát hiện sai lỗi trên sản phẩm sau sản xuất.", 2);
  add(1, "Quản lý chất lượng toàn diện (TQM - Total Quality Management) được định nghĩa với đặc điểm nổi bật nào?", ["Chỉ giao trách nhiệm kiểm soát chất lượng cho phòng kiểm nghiệm (QC)", "Huy động toàn bộ tổ chức tham gia vào quá trình cải tiến chất lượng", "Chỉ áp dụng các tiêu chuẩn vệ sinh cơ bản tại nhà xưởng", "Tập trung duy nhất vào khâu xử lý sự cố khi có ngộ độc thực phẩm"], 1, "Quản lý chất lượng toàn diện (TQM) là phương pháp huy động mọi thành viên và bộ phận trong toàn bộ tổ chức cùng tham gia cải tiến chất lượng.", 1);
  add(1, "Các chương trình tiên quyết (PRPs) như GMP (Thực hành sản xuất tốt), GHP (Thực hành vệ sinh tốt), GAP (Thực hành nông nghiệp tốt) đóng vai trò gì trong quản lý an toàn thực phẩm?", ["Kiểm tra và loại bỏ sản phẩm lỗi ở khâu phân phối", "Tạo nền tảng vệ sinh và điều kiện sản xuất an toàn", "Thay thế hoàn toàn cho việc phân tích mối nguy HACCP", "Đưa ra các chế tài xử phạt vi phạm hành chính đối với cơ sở"], 1, "Các chương trình tiên quyết (PRPs) như GMP, GHP, GAP đóng vai trò tạo nền tảng vệ sinh và các điều kiện môi trường sản xuất an toàn.", 1);
  add(1, "Hệ thống HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn) là phương pháp quản lý chất lượng dựa trên nguyên tắc nào?", ["Phát hiện sản phẩm lỗi sau khi tiêu thụ trên thị trường", "Phòng ngừa dựa trên việc xác định và kiểm soát các mối nguy tại các điểm tới hạn", "Kiểm tra xác suất 10% tổng số sản phẩm hoàn thiện", "Đánh giá mức độ hài lòng của khách hàng thông qua phiếu khảo sát"], 1, "HACCP là hệ thống có bản chất phòng ngừa, hoạt động dựa trên việc xác định và kiểm soát các mối nguy an toàn thực phẩm tại các điểm kiểm soát tới hạn (CCP).", 1);
  add(1, "Trong quản lý chất lượng, nguyên tắc 'Tiếp cận theo quá trình' mang lại lợi ích gì cho cơ sở sản xuất thực phẩm?", ["Giúp kiểm soát tốt từng công đoạn trong chuỗi sản xuất", "Tách rời các bộ phận để làm việc độc lập", "Tập trung toàn bộ nguồn lực vào khâu tiếp thị sản phẩm", "Giảm bớt các bước kiểm tra vệ sinh nhà xưởng"], 0, "Tiếp cận theo quá trình giúp doanh nghiệp kiểm soát chặt chẽ từng công đoạn nhỏ trong toàn bộ chuỗi sản xuất thay vì chỉ nhìn vào kết quả đầu ra.", 1);
  add(1, "Nguyên tắc 'Tiếp cận theo hệ thống' trong quản lý chất lượng thực phẩm có tác dụng nào sau đây?", ["Chỉ tập trung kiểm soát bộ phận sản xuất trực tiếp", "Giúp các bộ phận trong tổ chức phối hợp đồng bộ", "Tăng số lượng lỗi sản phẩm để bộ phận QC kiểm tra", "Bỏ qua khâu quản lý nhà cung cấp nguyên liệu"], 1, "Tiếp cận theo hệ thống giúp hiểu và quản lý các quá trình có liên quan lẫn nhau như một hệ thống, giúp các bộ phận phối hợp đồng bộ.", 1);
  add(1, "Việc đưa ra các quyết định quản lý chất lượng dựa trên nguyên tắc 'Dựa trên bằng chứng' đòi hỏi người quản lý phải căn cứ vào yếu tố nào?", ["Cảm nhận cá nhân và kinh nghiệm chủ quan của người quản lý", "Dữ liệu và thông tin thực tế", "Tin đồn từ thị trường chưa qua xác minh", "Ý kiến duy nhất của đơn vị vận chuyển"], 1, "Nguyên tắc quyết định dựa trên bằng chứng đòi hỏi việc phân tích dữ liệu và thông tin thực tế để đưa ra quyết định chính xác.", 1);
  add(1, "Mục đích cốt lõi của nguyên tắc 'Quan hệ hợp tác với nhà cung cấp' trong quản lý chất lượng thực phẩm là gì?", ["Bảo đảm chất lượng đầu vào ổn định", "Ép giá nguyên liệu xuống mức thấp nhất có thể", "Chuyển toàn bộ trách nhiệm pháp lý cho nhà cung cấp khi xảy ra sự cố", "Thay thế cho khâu kiểm tra vệ sinh tại nhà máy"], 0, "Quan hệ hợp tác dựa trên lợi ích tương hỗ với nhà cung cấp giúp đảm bảo nguồn nguyên liệu đầu vào có chất lượng ổn định và an toàn.", 1);
  add(1, "Xu hướng dịch chuyển chung của các phương pháp quản lý chất lượng thực phẩm hiện nay là gì?", ["Dịch chuyển từ kiểm soát phòng ngừa sang kiểm tra sản phẩm cuối cùng", "Dịch chuyển từ kiểm tra phát hiện sai lỗi sau sản xuất sang phòng ngừa chủ động trong toàn bộ quá trình", "Loại bỏ các khâu kiểm soát để giảm tối đa chi phí vận hành", "Chuyển từ quản lý theo hệ thống sang quản lý dựa trên kinh nghiệm cá nhân"], 1, "Các phương pháp quản lý chất lượng thực phẩm đã phát triển theo xu hướng từ kiểm tra (QC) sang phòng ngừa chủ động (QA, TQM, HACCP).", 2);
  add(1, "Tại một nhà máy chế biến thịt hộp, cán bộ kiểm tra chất lượng thực hiện lấy mẫu xác suất sản phẩm sau khi đóng hộp để kiểm tra độ kín và vi sinh. Lô hàng chỉ được xuất kho nếu mẫu đạt yêu cầu. Hoạt động này thể hiện phương pháp quản lý nào?", ["Kiểm soát chất lượng (QC - Quality Control)", "Đảm bảo chất lượng (QA - Quality Assurance)", "Quản lý chất lượng toàn diện (TQM)", "Phân tích mối nguy và điểm kiểm soát tới hạn (HACCP)"], 0, "Việc lấy mẫu kiểm tra sản phẩm sau khi đã đóng gói hoàn chỉnh để phát hiện sai lỗi thuộc phương pháp Kiểm soát chất lượng (QC).", 2);
  add(1, "Một công ty sản xuất sữa xây dựng hệ thống quy trình chuẩn cho mọi công đoạn: từ chuẩn hóa khâu tiếp nhận sữa tươi, quy định nhiệt độ thanh trùng, đến lịch bảo trì thiết bị và đào tạo định kỳ cho công nhân nhằm ngăn ngừa lỗi phát sinh. Đây là ví dụ về phương pháp quản lý nào?", ["Kiểm soát chất lượng (QC - Quality Control)", "Đảm bảo chất lượng (QA - Quality Assurance)", "Kiểm tra sản phẩm sau sản xuất", "Xử lý sự cố chất lượng"], 1, "Việc xây dựng hệ thống quản lý chuẩn hóa toàn bộ quá trình nhằm chủ động phòng ngừa sai lỗi ngay từ đầu là bản chất của Đảm bảo chất lượng (QA).", 2);
  add(1, "Một doanh nghiệp chế biến thủy sản muốn áp dụng hệ thống HACCP để kiểm soát mối nguy vi sinh vật. Tuy nhiên, điều kiện vệ sinh nhà xưởng và quy trình vệ sinh cá nhân của công nhân chưa đạt chuẩn. Cán bộ tư vấn chất lượng cần đưa ra khuyến nghị nào phù hợp nhất?", ["Bỏ qua khâu vệ sinh để triển khai HACCP ngay vì HACCP là tiêu chuẩn cao nhất", "Xây dựng và thực hiện tốt các Chương trình tiên quyết (PRPs) như GMP và GHP để tạo nền tảng vệ sinh trước khi áp dụng HACCP", "Chỉ cần tập trung kiểm tra sản phẩm thành phẩm (QC) thay vì áp dụng HACCP", "Dừng toàn bộ hoạt động sản xuất và giải thể doanh nghiệp"], 1, "Các chương trình tiên quyết (PRPs) như GMP, GHP là nền tảng bắt buộc phải có để tạo điều kiện vệ sinh an toàn trước khi xây dựng và vận hành thành công hệ thống HACCP.", 3);
  add(1, "Tiêu chuẩn quốc tế nào tích hợp HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn) cùng hệ thống quản lý nhằm bảo đảm an toàn thực phẩm trong toàn bộ chuỗi cung ứng?", ["ISO 9001", "ISO 22000", "ISO 14001", "ISO 45001"], 1, "ISO 22000 là tiêu chuẩn quốc tế tích hợp HACCP và quản lý hệ thống nhằm bảo đảm an toàn thực phẩm trong toàn chuỗi cung ứng.", 1);
  add(1, "Xu hướng chủ đạo của các phương pháp quản lý chất lượng thực phẩm hiện đại là gì?", ["Chỉ kiểm tra chất lượng sản phẩm cuối cùng trước khi xuất xưởng", "Kiểm soát chủ động và phòng ngừa rủi ro trong toàn bộ quá trình", "Chỉ xử lý khi có khiếu nại hoặc sự cố ngộ độc thực phẩm xảy ra", "Tập trung tối đa hóa năng suất sản xuất mà bỏ qua kiểm soát rủi ro"], 1, "Các phương pháp quản lý chất lượng thực phẩm hiện đại đều hướng đến kiểm soát chủ động và phòng ngừa rủi ro, góp phần nâng cao chất lượng và bảo vệ sức khỏe người tiêu dùng.", 1);
  add(2, "Nguyên tắc “Từ trang trại đến bàn ăn” (Farm to Fork) trong quản lý chất lượng chuỗi thực phẩm yêu cầu điều gì?", ["Tập trung kiểm soát tối đa tại khâu chế biến công nghiệp", "Kiểm soát liên tục và phối hợp chặt chẽ giữa các bên trong toàn bộ chuỗi cung ứng", "Chỉ kiểm tra định kỳ sản phẩm tại cửa hàng bán lẻ", "Chỉ quy định trách nhiệm cho cơ sở sản xuất nguyên liệu ban đầu"], 1, "Quản lý chất lượng trong chuỗi thực phẩm yêu cầu kiểm soát liên tục và phối hợp chặt chẽ giữa các bên theo nguyên tắc 'từ trang trại đến bàn ăn' (Farm to Fork), thay vì chỉ kiểm tra sản phẩm cuối cùng.", 2);
  add(2, "Trong chuỗi cung ứng thực phẩm, rủi ro an toàn thực phẩm nào sau đây đặc trưng nhất ở giai đoạn sản xuất nguyên liệu (trồng trọt, chăn nuôi)?", ["Đứt gãy chuỗi lạnh trong quá trình lưu kho", "Dư lượng thuốc bảo vệ thực vật, kháng sinh và kim loại nặng", "Nhiễm chéo vi sinh vật do dụng cụ chế biến không vệ sinh", "Bao bì thương phẩm bị rách hỏng khi phân phối"], 1, "Giai đoạn sản xuất nguyên liệu (trồng trọt, chăn nuôi, thu hoạch) có các nguy cơ chính như dư lượng thuốc bảo vệ thực vật, kháng sinh, kim loại nặng hoặc vi sinh vật gây bệnh.", 2);
  add(1, "Để kiểm soát nguy cơ nhiễm chéo vi sinh vật và sai sót trong sử dụng phụ gia ở giai đoạn chế biến thực phẩm, doanh nghiệp cần áp dụng các hệ thống/quy trình nào?", ["GMP, SSOP và HACCP", "Chỉ áp dụng mô hình 5S", "Chỉ áp dụng Kaizen và TQM", "ISO 14001 và OHSAS 18001"], 0, "Giai đoạn chế biến và sơ chế dễ phát sinh nhiễm chéo vi sinh hoặc sai sót phụ gia, do đó cần áp dụng các tiêu chuẩn/hệ thống GMP, SSOP và HACCP.", 2);
  add(2, "Nguy cơ phổ biến nhất ảnh hưởng trực tiếp đến chất lượng thực phẩm trong giai đoạn phân phối và lưu kho là gì?", ["Tồn dư hóa chất bảo vệ thực vật từ khâu canh tác", "Đứt gãy chuỗi lạnh và không bảo đảm nhiệt độ, độ ẩm bảo quản", "Sử dụng phụ gia thực phẩm quá liều lượng cho phép", "Chế biến thực phẩm chưa đủ nhiệt độ làm chín"], 1, "Giai đoạn phân phối và lưu kho có nguy cơ phổ biến là đứt gãy chuỗi lạnh, hư hỏng bao bì hoặc không kiểm soát tốt điều kiện nhiệt độ, độ ẩm.", 2);
  add(5, "Khái niệm 'Truy xuất nguồn gốc thực phẩm' được hiểu như thế nào?", ["Hoạt động xét nghiệm mẫu vi sinh vật định kỳ tại phòng thí nghiệm", "Khả năng theo dõi toàn bộ lịch sử và quá trình của sản phẩm từ sản xuất đến tiêu dùng", "Quy trình tiêu hủy thực phẩm hư hỏng tại cơ sở bán lẻ", "Hoạt động cấp chứng nhận vệ sinh an toàn thực phẩm cho doanh nghiệp"], 1, "Truy xuất nguồn gốc thực phẩm là khả năng theo dõi toàn bộ lịch sử và quá trình của sản phẩm từ sản xuất đến tiêu dùng.", 1);
  add(5, "Vai trò quan trọng nhất của truy xuất nguồn gốc thực phẩm khi có sự cố an toàn thực phẩm xảy ra là gì?", ["Nâng cao giá bán sản phẩm trên thị trường", "Xác định nhanh nguyên nhân, hỗ trợ thu hồi sản phẩm kịp thời và hạn chế thiệt hại", "Miễn trừ hoàn toàn trách nhiệm pháp lý cho nhà sản xuất", "Thay thế hoàn toàn công tác kiểm tra vệ sinh tại nhà máy"], 1, "Truy xuất nguồn gốc giúp xác định nhanh nguyên nhân khi xảy ra sự cố an toàn thực phẩm, hỗ trợ thu hồi sản phẩm kịp thời và hạn chế thiệt hại.", 2);
  add(5, "Điều kiện nào sau đây KHÔNG thuộc yêu cầu cơ bản để triển khai hệ thống truy xuất nguồn gốc thực phẩm?", ["Sản phẩm được nhận diện bằng mã lô, nhãn hàng hóa và thông tin rõ ràng", "Lưu trữ đầy đủ hồ sơ về nguyên liệu, sản xuất, bảo quản và phân phối", "Bắt buộc ứng dụng công nghệ Blockchain đắt tiền cho mọi cơ sở sản xuất", "Thiết lập quy trình thu hồi sản phẩm không an toàn khi có sự cố"], 2, "Công nghệ Blockchain, QR code hay RFID là công cụ hỗ trợ nâng cao hiệu quả, không phải là yêu cầu bắt buộc tối thiểu đối với mọi cơ sở thực phẩm.", 2);
  add(2, "Các đơn vị cung cấp vật tư đầu vào (như thức ăn chăn nuôi, thuốc BVTV, bao bì) có vai trò như thế nào trong quản lý chất lượng chuỗi thực phẩm?", ["Không ảnh hưởng vì chỉ tham gia trước giai đoạn chế biến", "Ảnh hưởng trực tiếp đến chất lượng và an toàn thực phẩm trong toàn chuỗi", "Chỉ ảnh hưởng đến chi phí sản xuất, không liên quan đến an toàn thực phẩm", "Chỉ chịu trách nhiệm về hình thức bao bì bên ngoài"], 1, "Các đơn vị cung cấp vật tư đầu vào như thức ăn chăn nuôi, thuốc bảo vệ thực vật, bao bì, thiết bị ảnh hưởng trực tiếp đến chất lượng và an toàn thực phẩm.", 2);
  add(1, "Tại một xưởng chế biến thịt nguội, bộ phận QC phát hiện thiết bị cân phụ gia bị lệch chuẩn dẫn đến hàm lượng muối Nitrit (chất bảo quản) vượt ngưỡng cho phép. Theo phân tích rủi ro, đây thuộc loại mối nguy nào và giải pháp khắc phục triệt để là gì?", ["Mối nguy sinh học; xử lý bằng cách chiếu xạ lô hàng", "Mối nguy hóa học; xử lý bằng cách hiệu chuẩn thiết bị cân định kỳ và tuân thủ GMP/HACCP", "Mối nguy vật lý; xử lý bằng cách cho qua máy dò kim loại", "Mối nguy vi sinh; xử lý bằng cách tăng nhiệt độ hấp"], 1, "Phụ gia vượt ngưỡng là mối nguy hóa học. Biện pháp quản lý rủi ro triệt để theo GMP/HACCP là hiệu chuẩn định kỳ thiết bị đo/cân và kiểm soát chặt chẽ quy trình phối trộn.", 3);
  add(5, "Tại một siêu thị, đoàn kiểm tra phát hiện lô chả lụa đóng gói bị nhiễm vi khuẩn Listeria monocytogenes. Nhờ có hệ thống truy xuất nguồn gốc tốt, doanh nghiệp sản xuất cần thực hiện ngay hành động ứng phó nào theo quy trình?", ["Chỉ thu hồi sản phẩm đang bày bán tại siêu thị bị kiểm tra", "Tra cứu mã lô sản phẩm, khoanh vùng chính xác toàn bộ các điểm phân phối lô hàng đó và kích hoạt quy trình thu hồi khẩn cấp", "Đổ lỗi cho đơn vị vận chuyển và không thực hiện can thiệp", "Tiến hành giảm giá xả hàng lô sản phẩm trên để thu hồi vốn"], 1, "Khi phát hiện vi khuẩn gây bệnh, doanh nghiệp sử dụng mã lô để truy xuất chính xác toàn bộ phạm vi phân phối của lô hàng không an toàn và thực hiện thu hồi khẩn cấp nhằm bảo vệ người tiêu dùng.", 3);
  add(2, "Thuật ngữ GMP trong quản lý chất lượng và an toàn thực phẩm được viết tắt từ cụm từ tiếng Anh nào và có nghĩa là gì?", ["Good Manufacturing Practice (Thực hành sản xuất tốt)", "General Management Process (Quy trình quản lý chung)", "Global Material Standard (Tiêu chuẩn vật liệu toàn cầu)", "Good Measurement Procedure (Thủ tục đo lường tốt)"], 0, "GMP là viết tắt của Good Manufacturing Practice, dịch sang tiếng Việt là Thực hành sản xuất tốt.", 1);
  add(2, "Mục tiêu cốt lõi của việc áp dụng hệ thống GMP (Thực hành sản xuất tốt) tại cơ sở chế biến thực phẩm là gì?", ["Tối đa hóa lợi nhuận và giảm thiểu tối đa chi phí nhân công", "Đảm bảo sản phẩm đạt chất lượng ổn định và an toàn cho người tiêu dùng", "Thay thế hoàn toàn công đoạn kiểm tra chất lượng sản phẩm cuối cùng", "Loại bỏ hoàn toàn sự tham gia của con người trong chuỗi sản xuất"], 1, "Theo giáo trình, mục tiêu chính của GMP là đảm bảo sản phẩm đạt chất lượng ổn định và an toàn cho người tiêu dùng.", 1);
  add(2, "Thứ tự tiến trình logic khi xây dựng và áp dụng các hệ thống quản lý chất lượng và an toàn thực phẩm là gì?", ["ISO 22000 -> HACCP -> GMP", "HACCP -> GMP -> ISO 22000", "GMP -> HACCP -> ISO 22000", "GMP -> ISO 22000 -> HACCP"], 2, "Trật tự nâng cao hệ thống quản lý an toàn thực phẩm đi từ nền tảng cơ bản: GMP -> HACCP -> ISO 22000.", 2);
  add(2, "Trong hệ thống quản lý an toàn thực phẩm, GMP (Thực hành sản xuất tốt) đóng vai trò gì đối với việc triển khai HACCP và ISO 22000?", ["Là tiêu chuẩn độc lập thay thế cho HACCP và ISO 22000", "Là chương trình tiên quyết (PRP) bắt buộc phải có trước khi triển khai HACCP hay ISO 22000", "Là bước đánh giá cuối cùng sau khi hoàn thành chứng nhận ISO 22000", "Là tài liệu khuyến khích áp dụng, không mang tính bắt buộc"], 1, "GMP là chương trình tiên quyết (PRP) — điều kiện nền tảng bắt buộc phải thiết lập trước khi xây dựng HACCP hoặc ISO 22000.", 2);
  add(2, "Theo định nghĩa về GMP (Thực hành sản xuất tốt), hệ thống này thực hiện kiểm soát bao nhiêu yếu tố chính trong toàn bộ quá trình sản xuất?", ["4 yếu tố", "5 yếu tố", "6 yếu tố", "8 yếu tố"], 2, "GMP kiểm soát 6 yếu tố chính bao gồm: nhà xưởng, thiết bị, nguyên liệu, chế biến, bảo quản và con người.", 1);
  add(2, "Đâu KHÔNG phải là yếu tố nằm trong phạm vi kiểm soát trực tiếp của GMP (Thực hành sản xuất tốt)?", ["Thiết kế nhà xưởng và thiết bị sản xuất", "Con người và quy trình bảo quản sản phẩm", "Chiến lược định giá và tiếp thị sản phẩm trên thị trường", "Nguyên liệu đầu vào và quá trình chế biến"], 2, "GMP kiểm soát các yếu tố kỹ thuật/vệ sinh sản xuất (nhà xưởng, thiết bị, nguyên liệu, chế biến, bảo quản, con người), không kiểm soát hoạt động thương mại/kinh doanh như chiến lược giá hay tiếp thị.", 2);
  add(2, "Một nhà máy chế biến thủy sản muốn chứng nhận ISO 22000 (Hệ thống quản lý an toàn thực phẩm) nhưng hệ thống nhà xưởng hiện tại đọng nước, thiết bị gỉ sét và công nhân chưa được huấn luyện vệ sinh. Cán bộ tư vấn chất lượng nên đưa ra lời khuyên nào phù hợp nhất?", ["Tiến hành đăng ký chứng nhận ISO 22000 ngay để lấy chứng chỉ trước rồi khắc phục nhà xưởng sau", "Tập trung xây dựng và thực hành tốt hệ thống GMP (Thực hành sản xuất tốt) để chuẩn hóa điều kiện cơ bản trước khi làm HACCP và ISO 22000", "Bỏ qua tiêu chuẩn GMP và chuyển sang áp dụng tiêu chuẩn 5S để giải quyết bài toán môi trường", "Chỉ cần kiểm nghiệm mẫu thành phẩm đạt yêu cầu là đủ điều kiện chứng nhận ISO 22000"], 1, "GMP kiểm soát điều kiện cơ bản (nhà xưởng, thiết bị, con người). Vì GMP là chương trình tiên quyết (PRP) của HACCP và ISO 22000, cơ sở bắt buộc phải chuẩn hóa GMP trước khi tiến hành các hệ thống quản lý nâng cao.", 3);
  add(2, "Khi kiểm tra đột xuất một cơ sở sản xuất nước giải khát, cơ quan quản lý phát hiện khu vực chế biến không đáp ứng khoảng cách an toàn, nguồn nước ngầm chưa qua xử lý và công nhân không mang trang phục bảo hộ. Sự cố này thể hiện cơ sở đang vi phạm nghiêm trọng ở tầng quản lý nào?", ["Không tuân thủ các Điều kiện tiên quyết (PRPs) thuộc chương trình GMP (Thực hành sản xuất tốt)", "Sai lệch trong việc xác định Điểm kiểm soát tới hạn (CCP) của HACCP", "Chưa đăng ký mã số mã vạch truy xuất nguồn gốc theo quy định Bộ Công Thương", "Thiếu sót trong khâu diễn tập xử lý khủng hoảng truyền thông của ISO 9001"], 0, "Các yếu tố như cơ sở hạ tầng nhà xưởng, nguồn nước, trang phục bảo hộ con người thuộc kiểm soát điều kiện cơ bản của GMP (Chương trình tiên quyết - PRPs).", 3);
  add(1, "Trong hệ thống quản lý an toàn thực phẩm, các chương trình tiên quyết (PRPs - Prerequisite Programs) đóng vai trò nền tảng nào sau đây?", ["Là cơ sở trực tiếp để triển khai hệ thống HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn)", "Thay thế hoàn toàn cho việc xác định các điểm kiểm soát tới hạn (CCP)", "Chỉ áp dụng để kiểm soát mối nguy hóa học trong nguyên liệu đầu vào", "Là tiêu chuẩn bắt buộc riêng cho các doanh nghiệp xuất khẩu sang Châu Âu"], 0, "Theo quy trình quản lý chất lượng an toàn thực phẩm, PRPs cung cấp các điều kiện vệ sinh và môi trường cơ bản, tạo nền tảng bắt buộc trước khi triển khai kế hoạch HACCP.", 1);
  add(1, "Vai trò chính của các chương trình tiên quyết (PRPs) đối với môi trường sản xuất thực phẩm là gì?", ["Kiểm soát các mối nguy phổ biến từ môi trường sản xuất và duy trì điều kiện vệ sinh phù hợp", "Tự động hóa hoàn toàn dây chuyền sản xuất và đóng gói thực phẩm", "Cắt giảm tối đa chi phí kiểm nghiệm mẫu thành phẩm định kỳ", "Thay thế thủ tục tự công bố sản phẩm theo quy định của pháp luật"], 0, "PRPs tập trung vào việc duy trì các điều kiện vệ sinh phù hợp và kiểm soát các mối nguy mang tính chất phổ biến xuất phát từ môi trường nhà xưởng, thiết bị và con người.", 1);
  add(1, "Ngoài khía cạnh kỹ thuật kiểm soát an toàn thực phẩm, việc duy trì tốt các chương trình tiên quyết (PRPs) còn thể hiện giá trị nào của doanh nghiệp?", ["Thể hiện trách nhiệm pháp lý và đạo đức kinh doanh của doanh nghiệp", "Khẳng định quyền sở hữu trí tuệ đối với công nghệ chế biến", "Đảm bảo doanh nghiệp luôn đạt lợi nhuận tối đa trong mọi tình huống", "Giúp doanh nghiệp miễn trừ toàn bộ nghĩa vụ thuế doanh nghiệp"], 0, "Việc thực hiện PRPs thể hiện sự tuân thủ quy định pháp luật hiện hành và cam kết đạo đức đối với sức khỏe của người tiêu dùng.", 2);
  add(2, "Tình huống: Một công ty chế biến thực phẩm chuẩn bị áp dụng hệ thống HACCP. Tuy nhiên, qua khảo sát thực tế, nhà xưởng chưa có hệ thống thoát nước đạt chuẩn, không khí trong khu vực chế biến bị đọng hơi nước và chưa có quy trình vệ sinh định kỳ. Đánh giá nào sau đây là ĐÚNG nhất?", ["Công ty chưa đủ điều kiện triển khai HACCP vì các chương trình tiên quyết (PRPs) về cơ sở vật chất và vệ sinh chưa đạt yêu cầu", "Công ty vẫn có thể cấp chứng nhận HACCP bình thường vì HACCP chỉ tập trung vào công đoạn chế biến nhiệt", "Công ty chỉ cần mua thêm máy kiểm tra vi sinh thành phẩm là có thể bỏ qua việc cải tạo nhà xưởng", "Công ty chỉ bị vi phạm Luật Lao động chứ không ảnh hưởng đến hệ thống an toàn thực phẩm"], 0, "PRPs là điều kiện tiên quyết và là cơ sở để triển khai HACCP. Nếu nhà xưởng và vệ sinh chưa đạt (PRPs kém), hệ thống HACCP sẽ không thể vận hành hiệu quả và không kiểm soát được rủi ro ô nhiễm chéo.", 3);
  add(1, "Nguyên tắc một chiều trong thiết kế và bố trí mặt bằng nhà xưởng sản xuất thực phẩm được hiểu như thế nào?", ["Dòng di chuyển của nguyên liệu, sản phẩm và con người đi theo một hướng thống nhất từ đầu vào đến đầu ra, không chồng chéo", "Dòng không khí và nước thải đi ngược chiều từ khu vực bẩn sang khu vực sạch", "Nguyên liệu thô và chất thải sinh hoạt được vận chuyển chung một lối đi để tối ưu diện tích", "Công nhân khu vệ sinh có thể đi tắt qua khu vực bao gói thành phẩm để tiết kiệm thời gian"], 0, "Nguyên tắc một chiều quy định dòng di chuyển của nguyên liệu, sản phẩm và con người phải đi theo một hướng thống nhất từ đầu vào (bẩn/nhận) đến đầu ra (sạch/xuất), không cắt ngang hay chồng chéo.", 1);
  add(1, "Mục đích cốt lõi nhất của việc áp dụng nguyên tắc một chiều trong dây chuyền sản xuất thực phẩm là gì?", ["Tối đa hóa công suất vận hành của hệ thống máy móc tự động", "Ngăn ngừa sự nhiễm chéo giữa khu vực sạch và khu vực bẩn", "Giảm thiểu tối đa chi phí tiêu thụ điện năng cho chiếu sáng", "Tăng tốc độ đóng gói thành phẩm xuất kho"], 1, "Mục đích chính của nguyên tắc một chiều là ngăn ngừa nguy cơ nhiễm chéo vi sinh vật và tạp chất từ khu vực bẩn sang khu vực sạch.", 1);
  add(1, "Theo tiêu chuẩn GMP về kết cấu nhà xưởng, luồng không khí thông gió và hệ thống thoát nước phải được bố trí theo hướng nào?", ["Từ khu vực bẩn sang khu vực sạch", "Từ khu vực sạch sang khu vực bẩn", "Luân chuyển tuần hoàn kín giữa khu vực sạch và khu vực bẩn", "Tùy thuộc hướng gió tự nhiên mà không cần kiểm soát"], 1, "Để tránh mang vi sinh vật và bụi bẩn từ nơi bẩn vào nơi sạch, hệ thống thông gió và thoát nước phải luôn chảy/thổi theo chiều từ khu vực sạch sang khu vực bẩn.", 2);
  add(1, "Quy định nào sau đây là BẮT BUỘC đối với việc bố trí khu vệ sinh và khu thay đồ cho công nhân trong nhà xưởng thực phẩm?", ["Bố trí ngay bên trong khu vực chế biến nhiệt để tiện sử dụng", "Mở cửa trực tiếp vào khu vực đóng gói thành phẩm", "Tuyệt đối không được mở cửa trực tiếp vào khu vực sản xuất", "Sử dụng chung cửa ra vào với khu vực tiếp nhận nguyên liệu tươi sống"], 2, "Khu vệ sinh và thay đồ là nguồn chứa nhiều vi sinh vật gây hại, do đó mặt bằng phải được bố trí tách biệt và không được mở cửa trực tiếp vào khu vực sản xuất.", 2);
  add(1, "Tại một nhà máy chế biến thịt lợn đóng hộp, thanh tra ATTP phát hiện đường vận chuyển chất thải (xương, mỡ thừa) đi cắt ngang qua lối vận chuyển bán thành phẩm đã qua luộc chín. Theo tiêu chuẩn GMP, cơ sở này đã vi phạm quy định nào và nguy cơ lớn nhất là gì?", ["Vi phạm quy định bảo dưỡng thiết bị; nguy cơ làm hư hỏng máy đóng hộp", "Vi phạm nguyên tắc một chiều; nguy cơ gây nhiễm chéo vi sinh vật từ chất thải vào sản phẩm đã chín", "Vi phạm quy định chiếu sáng; nguy cơ gây sai lệch màu sắc thịt", "Vi phạm quy định truy xuất nguồn gốc; nguy cơ nhầm lẫn lô hàng"], 1, "Việc lối vận chuyển chất thải cắt ngang lối bán thành phẩm là vi phạm nghiêm trọng nguyên tắc một chiều, tạo nguy cơ lây nhiễm chéo vi sinh vật từ chất thải sang thực phẩm.", 3);
  add(1, "Vật liệu chế tạo thiết bị, dụng cụ tiếp xúc trực tiếp với thực phẩm phải đảm bảo các tiêu chuẩn kỹ thuật nào sau đây?", ["Làm từ gỗ tự nhiên nguyên khối để đảm bảo tính thân thiện môi trường", "Làm từ vật liệu an toàn, không độc hại (như inox, nhôm thực phẩm), bền, không gỉ, dễ tháo rời để vệ sinh", "Làm từ sắt chưa qua mạ để giảm giá thành sản xuất", "Làm từ nhựa tái chế công nghiệp để tiết kiệm chi phí"], 2, "Thiết bị, dụng cụ tiếp xúc thực phẩm phải làm từ vật liệu an toàn (inox, nhôm thực phẩm), không gỉ, không độc hại và dễ tháo rời để làm sạch, khử trùng.", 2);
  add(1, "Trong các yếu tố thuộc môi trường sản xuất thực phẩm, yếu tố nào được xác định là nguồn có nguy cơ gây nhiễm bẩn cao nhất đối với sản phẩm?", ["Bề mặt thiết bị chiếu sáng", "Con người (công nhân, nhân viên sản xuất)", "Vật liệu thùng giấy bao bì carton", "Phương tiện xe nâng vận chuyển"], 1, "Con người được xác định là yếu tố có nguy cơ gây nhiễm bẩn thực phẩm cao nhất (qua bàn tay, hơi thở, trang phục, vi sinh vật trên da/tóc).", 1);
  add(1, "Hành vi nào sau đây của công nhân trực tiếp sản xuất thực phẩm là VI PHẠM quy định về thực hành vệ sinh cá nhân theo GMP?", ["Rửa tay bằng xà phòng sát khuẩn trước khi vào ca sản xuất", "Cắt ngắn móng tay và mặc đầy đủ trang phục bảo hộ lao động", "Đeo nhẫn cưới, đồng hồ đeo tay và ăn quà vặt trong khu vực chế biến", "Che chắn kín và băng chống thấm đối với các vết thương nhỏ trước khi làm việc"], 2, "Theo GMP, công nhân không được ăn uống, hút thuốc, đeo trang sức (nhẫn, đồng hồ...) trong khu vực sản xuất vì trang sức có thể rơi vào thực phẩm hoặc chứa vi khuẩn tích tụ.", 2);
  add(1, "Trong ca sản xuất tại cơ sở chế biến suất ăn công nghiệp, công nhân B xuất hiện triệu chứng sốt và tiêu chảy. Theo quy định kiểm soát sức khỏe người lao động trong ATTP, quản lý cơ sở phải xử lý như thế nào?", ["Phát thêm khẩu trang và yêu cầu công nhân B tiếp tục làm việc bình thường", "Chuyển công nhân B sang khâu chia suất ăn chín để giảm tải sức lao động", "Tạm thời không cho công nhân B tiếp xúc với thực phẩm, cách ly và đưa đi kiểm tra y tế", "Cho công nhân B uống thuốc tại chỗ và yêu cầu làm hết ca mới được nghỉ"], 2, "Người đang mắc bệnh truyền nhiễm hoặc có triệu chứng tiêu chảy, sốt, vết thương hở tuyệt đối không được tham gia trực tiếp vào quá trình sản xuất thực phẩm nhằm tránh lây lan mầm bệnh.", 3);
  add(1, "Đoàn khách tham quan đối tác khi vào khu vực chế biến trực tiếp của nhà máy thực phẩm cần tuân thủ quy định nào?", ["Chỉ cần đeo khẩu trang, không bắt buộc mặc trang phục bảo hộ", "Được tự do đi lại nếu không chạm tay vào sản phẩm", "Phải tuân thủ đầy đủ các quy định về vệ sinh cá nhân và bảo hộ như công nhân sản xuất", "Không cần áp dụng quy định vệ sinh vì thời gian tham quan ngắn"], 2, "Khách tham quan khi đi vào khu vực sản xuất trực tiếp bắt buộc phải tuân thủ nghiêm ngặt các quy định về vệ sinh và trang phục bảo hộ như đối với công nhân sản xuất.", 2);
  add(1, "Nguyên tắc BẮT BUỘC trong việc ghi chép hồ sơ giám sát định kỳ GMP là gì?", ["Dự đoán và ghi chép trước các số liệu cho cả ca làm việc", "Ghi ngay khi thực hiện giám sát, tuyệt đối không ghi trước hoặc ghi bù", "Chỉ ghi chép vào ngày cuối tuần để tập hợp số liệu một lần", "Chỉ ghi chép hồ sơ khi xảy ra sự cố kỹ thuật nghiêm trọng"], 1, "Nguyên tắc ghi chép hồ sơ GMP là ghi ngay tại thời điểm thực hiện giám sát, không ghi trước (dự đoán) hay ghi bù sau đó để đảm bảo tính trung thực và chính xác.", 2);
  add(1, "Trong quá trình giám sát công đoạn tiệt trùng sữa, cán bộ QC phát hiện nhiệt độ bị sụt giảm xuống dưới ngưỡng giới hạn cho phép trong 15 phút. Theo quy định quản lý hồ sơ GMP, hồ sơ giám sát tại thời điểm đó bắt buộc phải ghi nhận bổ sung những nội dung nào?", ["Chỉ ghi số nhiệt độ thực tế và bỏ qua không báo cáo cấp trên", "Mô tả chi tiết sai lệch, hành động khắc phục đã thực hiện và phương án xử lý đối với lô sữa bị ảnh hưởng", "Tự điều chỉnh số liệu nhiệt độ trong biểu mẫu cho đạt chuẩn để tránh vi phạm", "Hủy bỏ tờ ghi chép hỏng và lập lại tờ mới vào cuối ca"], 1, "Khi phát hiện sai lệch, hồ sơ GMP phải ghi nhận thêm: mô tả chi tiết sai lệch, hành động khắc phục đã thực hiện, và cách xử lý đối với sản phẩm bị ảnh hưởng trong thời gian xảy ra sai lệch.", 3);
  add(1, "Thông tin nào sau đây KHÔNG thuộc danh mục thông tin bắt buộc phải có trong hồ sơ giám sát định kỳ GMP?", ["Tên cơ sở và khu vực giám sát", "Ngưỡng giới hạn cần đạt và kết quả giám sát thực tế", "Báo cáo doanh số bán hàng và lợi nhuận của công ty", "Thời gian giám sát cùng chữ ký của người thực hiện và người kiểm tra"], 2, "Báo cáo tài chính, doanh số bán hàng không nằm trong hồ sơ kỹ thuật giám sát định kỳ GMP.", 1);
  add(1, "Nội dung nào sau đây KHÔNG thuộc nhóm tài liệu căn cứ dùng để xây dựng hệ thống Quy phạm sản xuất tốt (GMP)?", ["Các văn bản quy phạm pháp luật, quy định hiện hành về ATTP", "Các tiêu chuẩn, quy phạm kỹ thuật (TCVN, CODEX, ISO)", "Quy trình truy xuất nguồn gốc và thu hồi sản phẩm", "Sơ yếu lý lịch tư pháp của toàn bộ nhân viên nhà máy"], 3, "Sơ yếu lý lịch tư pháp không nằm trong 10 nhóm tài liệu căn cứ kỹ thuật/pháp lý để xây dựng GMP.", 2);
  add(3, "Theo quy định tại Việt Nam, chứng chỉ GMP (Thực hành tốt sản xuất) có thời hạn hiệu lực trong bao lâu?", ["1 năm", "2 năm", "3 năm", "5 năm"], 2, "Chứng chỉ GMP tại Việt Nam có hiệu lực trong thời hạn 3 năm, sau đó cơ sở phải tiến hành gia hạn để tiếp tục hoạt động.", 1);
  add(3, "Cơ quan nào sau đây có thẩm quyền cấp chứng chỉ GMP (Thực hành tốt sản xuất) tại Việt Nam?", ["Cục Quản lý Dược hoặc Sở Y tế tỉnh/thành phố", "Bộ Công Thương hoặc Sở Công Thương", "Bộ Nông nghiệp và Phát triển nông thôn", "Cục An toàn thực phẩm phối hợp với Bộ Khoa học và Công nghệ"], 0, "Theo quy định, cơ quan có thẩm quyền cấp chứng chỉ GMP tại Việt Nam là Cục Quản lý Dược (NMPA) hoặc Sở Y tế tỉnh/thành phố.", 1);
  add(3, "Quy trình cấp chứng chỉ GMP (Thực hành tốt sản xuất) tại Việt Nam được thực hiện theo đúng thứ tự nào sau đây?", ["Chuẩn bị → Tự kiểm tra → Nộp hồ sơ → Kiểm tra tại chỗ → Cấp chứng chỉ → Giám sát định kỳ", "Nộp hồ sơ → Kiểm tra tại chỗ → Tự kiểm tra → Chuẩn bị → Cấp chứng chỉ → Giám sát định kỳ", "Tự kiểm tra → Chuẩn bị → Nộp hồ sơ → Cấp chứng chỉ → Kiểm tra tại chỗ → Giám sát định kỳ", "Chuẩn bị → Nộp hồ sơ → Kiểm tra tại chỗ → Tự kiểm tra → Cấp chứng chỉ → Giám sát định kỳ"], 0, "Quy trình cấp chứng chỉ GMP chuẩn gồm 6 bước tuần tự: Chuẩn bị → Tự kiểm tra → Nộp hồ sơ → Kiểm tra tại chỗ → Cấp chứng chỉ → Giám sát định kỳ.", 2);
  add(3, "Trong quy trình cấp chứng chỉ GMP tại Việt Nam, cơ sở sản xuất phải thực hiện bước nào ngay trước khi nộp hồ sơ lên cơ quan quản lý?", ["Kiểm tra tại chỗ", "Tự kiểm tra", "Giám sát định kỳ", "Đánh giá của bên thứ ba"], 1, "Theo quy trình cấp chứng chỉ GMP, sau bước Chuẩn bị, cơ sở phải thực hiện 'Tự kiểm tra' đánh giá nội bộ trước khi chính thức 'Nộp hồ sơ'.", 2);
  add(3, "Sau khi được cấp chứng chỉ GMP, cơ sở sản xuất phải chịu hoạt động quản lý duy trì nào từ cơ quan thẩm quyền?", ["Tự động cấp lại chứng chỉ sau mỗi 6 tháng", "Giám sát định kỳ", "Không chịu sự quản lý nào cho đến khi hết hạn", "Tự đánh giá định kỳ hàng tháng gửi Bộ Công Thương"], 1, "Sau khi cấp chứng chỉ GMP, cơ quan quản lý sẽ tiến hành bước 'Giám sát định kỳ' để đảm bảo cơ sở tuân thủ liên tục các tiêu chuẩn.", 2);
  add(3, "Tại một nhà máy dược phẩm, chứng chỉ GMP đã được cấp vào tháng 02/2021. Đến tháng 12/2023, để đảm bảo việc sản xuất kinh doanh không bị gián đoạn, nhà máy này cần xử lý như thế nào theo quy định pháp luật?", ["Tiếp tục sản xuất bình thường vì chứng chỉ GMP có hiệu lực vĩnh viễn", "Thực hiện thủ tục xin gia hạn chứng chỉ GMP vì chứng chỉ chuẩn bị hết thời hạn 3 năm", "Nộp hồ sơ xin cấp lại chứng chỉ ISO 22000 thay thế cho GMP", "Dừng toàn bộ hoạt động sản xuất vì chứng chỉ GMP không thể gia hạn"], 1, "Chứng chỉ GMP có hiệu lực 3 năm (đến tháng 02/2024 là hết hạn). Do đó, vào cuối năm 2023, doanh nghiệp phải làm thủ tục gia hạn để duy trì tính hợp pháp của hoạt động sản xuất.", 3);
  add(3, "Trong quá trình giám sát định kỳ, đoàn kiểm tra phát hiện một cơ sở sản xuất dược phẩm vi phạm nghiêm trọng các điều kiện vệ sinh nhà xưởng và cố tình sai lệch quy trình kiểm soát chất lượng GMP. Cơ quan quản lý có thẩm quyền sẽ xử lý chứng chỉ GMP của cơ sở này như thế nào?", ["Chỉ nhắc nhở bằng văn bản và kéo dài hiệu lực chứng chỉ", "Tự động chuyển chứng chỉ GMP sang cho Sở Công Thương quản lý", "Cấp lại chứng chỉ mới với thời hạn 1 năm để theo dõi", "Thu hồi chứng chỉ GMP đã cấp"], 3, "Theo quy định quản lý tiêu chuẩn GMP, chứng chỉ GMP có thể bị thu hồi nếu cơ sở sản xuất vi phạm nghiêm trọng các quy định và tiêu chuẩn đã cam kết.", 3);
  add(1, "SSOP (Sanitation Standard Operating Procedures) trong quản lý an toàn thực phẩm được định nghĩa là gì?", ["Quy trình thực hành sản xuất tốt nhằm kiểm soát các bước công nghệ chế biến", "Quy phạm vệ sinh và thủ tục kiểm soát vệ sinh môi trường sản xuất của doanh nghiệp", "Hệ thống phân tích mối nguy và kiểm soát điểm tới hạn trên dây chuyền sản xuất", "Tiêu chuẩn quốc tế về hệ thống quản lý an toàn thực phẩm toàn diện"], 1, "SSOP là quy phạm vệ sinh và thủ tục kiểm soát vệ sinh — tập hợp các quy định nhằm kiểm soát tất cả các yếu tố liên quan đến vệ sinh môi trường sản xuất của doanh nghiệp.", 1);
  add(1, "Trong hệ thống quản lý an toàn thực phẩm, GMP và SSOP giữ vai trò vị trí nào sau đây?", ["Là tiêu chuẩn nâng cao áp dụng sau khi đã vận hành thành công ISO 22000", "Là nền móng và chương trình tiên quyết (PRP) bắt buộc trước khi xây dựng HACCP", "Là các quy định có thể thay thế hoàn toàn cho hệ thống phân tích mối nguy HACCP", "Là công cụ quản lý chỉ áp dụng riêng cho khâu vận chuyển và lưu thông sản phẩm"], 1, "GMP + SSOP đóng vai trò là nền móng - chương trình tiên quyết (PRP) bắt buộc để làm cơ sở xây dựng HACCP và tiến tới ISO 22000.", 1);
  add(1, "Mối quan hệ thứ tự phát triển giữa GMP/SSOP, HACCP và ISO 22000 trong doanh nghiệp thực phẩm được thể hiện đúng nhất theo sơ đồ nào?", ["ISO 22000 → HACCP → GMP + SSOP", "HACCP → GMP + SSOP → ISO 22000", "GMP + SSOP (nền móng) → HACCP → ISO 22000", "GMP → ISO 22000 → SSOP → HACCP"], 2, "Theo mô hình cấp độ quản lý chất lượng và ATTP, GMP + SSOP là nền móng tiên quyết, tiếp theo là HACCP và mức độ bao quát cao nhất là ISO 22000.", 2);
  add(1, "Điểm khác biệt căn bản về phạm vi kiểm soát giữa GMP (Thực hành sản xuất tốt) và SSOP (Quy phạm vệ sinh) là gì?", ["GMP kiểm soát quy trình sản xuất và điều kiện vận hành, trong khi SSOP tập trung vào thủ tục và điều kiện vệ sinh môi trường", "GMP chỉ áp dụng đối với ngành dược phẩm, còn SSOP áp dụng riêng cho ngành thực phẩm", "GMP tập trung xử lý vi sinh vật, còn SSOP chỉ xử lý mối nguy hóa học và vật lý", "GMP là tiêu chuẩn tự nguyện áp dụng, còn SSOP là quy định pháp lý bắt buộc đối với mọi hộ kinh doanh nhỏ lẻ"], 0, "GMP kiểm soát các yếu tố điều kiện sản xuất và thao tác quy trình công nghệ, còn SSOP tập trung kiểm soát các yếu tố vệ sinh môi trường sản xuất.", 2);
  add(1, "Một doanh nghiệp chế biến thủy sản cố gắng triển khai xây dựng hệ thống HACCP nhưng quyết định bỏ qua bước xây dựng và thực hiện SSOP để tiết kiệm thời gian. Theo nguyên tắc quản lý chất lượng, đánh giá nào sau đây là chính xác nhất về tình huống này?", ["Doanh nghiệp vẫn xây dựng HACCP thành công vì HACCP độc lập hoàn toàn với SSOP", "Hệ thống HACCP sẽ bị quá tải và thất bại vì thiếu 'nền móng' kiểm soát vệ sinh môi trường ban đầu", "Cơ quan chức năng sẽ cấp ngay chứng nhận ISO 22000 cho doanh nghiệp do rút ngắn thời gian", "Doanh nghiệp chỉ cần áp dụng GMP là đủ điều kiện thay thế hoàn toàn cho cả SSOP và HACCP"], 1, "GMP và SSOP là chương trình tiên quyết đóng vai trò nền móng. Theo nguyên lý 'Không có móng nhà (GMP/SSOP) thì không thể xây được tầng nhà (HACCP)', việc thiếu SSOP sẽ khiến hệ thống HACCP không thể vận hành hiệu quả do mất kiểm soát các mối nguy vệ sinh cơ bản.", 3);
  add(1, "SSOP (Sanitation Standard Operating Procedures) là gì?", ["Hệ thống quản lý chất lượng toàn diện", "Quy trình chuẩn về vệ sinh trong sản xuất thực phẩm", "Tiêu chuẩn an toàn thực phẩm quốc tế", "Phương pháp kiểm soát điểm tới hạn (CCP)"], 1, "SSOP là quy trình chuẩn về vệ sinh, được áp dụng trong sản xuất thực phẩm để ngăn ngừa mối nguy ô nhiễm.", 1);
  add(1, "Yếu tố nào sau đây không thuộc ba yếu tố cơ bản của SSOP?", ["Vận hành (quy tắc 4W+1H)", "Kiểm soát (giám sát, hành động khắc phục, hồ sơ)", "Đào tạo nhân viên", "Giám sát"], 2, "Ba yếu tố cơ bản của SSOP là Vận hành, Kiểm soát và Hồ sơ; đào tạo nhân viên là hoạt động hỗ trợ nhưng không nằm trong ba yếu tố này.", 1);
  add(2, "Quy tắc 4W+1H trong yếu tố vận hành của SSOP bao gồm những yếu tố nào?", ["Who, What, When, Where, Why", "Who, What, When, Where, How", "Why, When, Where, How, Which", "Who, Which, When, Where, How"], 1, "4W+1H nghĩa là Who (ai), What (cái gì), When (khi nào), Where (ở đâu), How (như thế nào).", 2);
  add(5, "Trong SSOP, hoạt động \"Giám sát\" (Monitoring) thường được giao cho ai?", ["Chủ nhà máy", "Bộ phận QC hoặc tổ trưởng kiểm tra", "Khách hàng", "Cơ quan quản lý nhà nước"], 1, "Theo chuẩn SSOP, việc giám sát quy trình vệ sinh được phân công cho nhân viên QC hoặc tổ trưởng để đảm bảo tuân thủ.", 2);
  add(2, "Mục đích của \"Hành động khắc phục\" (Corrective Action) trong SSOP là gì?", ["Tăng năng suất sản xuất", "Xử lý sự cố và tìm nguyên nhân gốc rễ", "Ghi chép kết quả kiểm tra", "Đánh giá nhà cung cấp"], 1, "Corrective Action nhằm khắc phục ngay khi phát hiện sai lệch, đồng thời điều tra nguyên nhân gốc rễ để ngăn tái diễn.", 2);
  add(1, "\"Những gì không ghi lại nghĩa là chưa từng làm\" liên quan đến nguyên tắc nào của HACCP?", ["Xác định mối nguy", "Kiểm soát điểm tới hạn (CCP)", "Ghi chép và lưu trữ", "Xác nhận hiệu lực hệ thống"], 2, "Nguyên tắc ghi chép và lưu trữ yêu cầu mọi hoạt động kiểm soát phải được ghi lại; nếu không ghi lại, không chứng minh đã thực hiện.", 2);
  add(2, "Mục đích chính của việc kiểm soát bề mặt sàn xưởng sản xuất thực phẩm (sạch, không đọng nước, không bám mỡ, không mùi hôi) theo Quy phạm vệ sinh SSOP là gì?", ["Nhằm tăng tính thẩm mỹ và đáp ứng yêu cầu của khách tham quan", "Nhằm ngăn ngừa rủi ro ô nhiễm chéo vào sản phẩm thực phẩm", "Nhằm kéo dài tuổi thọ của vật liệu gạch lát sàn", "Nhằm giảm bớt thời gian làm việc của nhân viên vệ sinh"], 1, "Yêu cầu sàn sạch, không vũng nước, không dầu mỡ, không mùi hôi trong SSOP nhằm mục đích cốt lõi là ngăn ngừa sự phát triển của vi sinh vật và tránh ô nhiễm chéo sang thực phẩm.", 1);
  add(2, "Trong Quy trình vệ sinh (Phần 2 của SSOP), yếu tố nào sau đây KHÔNG thuộc danh mục các thông tin chi tiết bắt buộc phải mô tả trong thao tác cụ thể?", ["Hóa chất sử dụng, nồng độ và liều lượng pha chế", "Thời gian tiếp xúc của hóa chất và tần suất thực hiện", "Phân công cụ thể ai là người thực hiện và làm công việc gì", "Chi phí mua hóa chất tẩy rửa và thông tin nhà cung ứng"], 3, "Quy trình vệ sinh SSOP tập trung vào kĩ thuật thao tác: Làm gì, ai làm, hóa chất nào, nồng độ, liều lượng, thời gian tiếp xúc, tần suất. Chi phí và nhà cung ứng thuộc quản lý tài chính/mua hàng.", 1);
  add(2, "Một quy trình vệ sinh sàn xưởng đạt chuẩn theo SSOP đòi hỏi phải quy định chi tiết về hóa chất tẩy rửa như thế nào?", ["Chỉ cần ghi tên thương hiệu hóa chất nổi tiếng trên thị trường", "Chỉ cần ghi chung chung là dùng chất tẩy rửa phù hợp", "Quy định rõ tên hóa chất, nồng độ, liều lượng và thời gian tiếp xúc", "Quy định giá thành hóa chất sao cho tiết kiệm chi phí nhất"], 2, "Theo quy định về thao tác cụ thể trong SSOP, thông tin về hóa chất phải minh bạch và chi tiết gồm: loại hóa chất, nồng độ, liều lượng sử dụng và thời gian tiếp xúc cần thiết để đạt hiệu quả khử trùng.", 2);
  add(2, "Sự tồn tại của các vũng nước đọng trên sàn xưởng chế biến thực phẩm tạo ra mối nguy an toàn thực phẩm nào nghiêm trọng nhất?", ["Mối nguy hóa học do nước hòa tan gạch lát sàn", "Mối nguy sinh học do nước đọng là môi trường lý tưởng cho vi khuẩn phát triển gây ô nhiễm chéo", "Mối nguy vật lý do vũng nước làm phản chiếu ánh sáng gây chói mắt công nhân", "Không tạo ra mối nguy nào nếu thực phẩm không rơi xuống sàn"], 1, "Vũng nước đọng trên sàn xưởng là điều kiện thuận lợi cho các mầm bệnh vi sinh vật (như Listeria monocytogenes) nhân lên và phát tán qua không khí, ủng di chuyển, gây ô nhiễm chéo vào thực phẩm.", 2);
  add(2, "Tại một cơ sở chế biến thực phẩm, kiểm tra viên phát hiện nhân viên vệ sinh chỉ xịt nước lên sàn xưởng rồi lau khô ngay mà không pha hóa chất đúng nồng độ và không để đủ thời gian tiếp xúc theo quy định SSOP. Tình huống này phản ảnh vi phạm gì?", ["Vi phạm quy định bảo hộ lao động cho công nhân", "Vi phạm quy trình thao tác vệ sinh chi tiết trong SSOP, dẫn đến nguy cơ không loại bỏ được vi sinh vật và dầu mỡ", "Vi phạm quy định về tiết kiệm nước và năng lượng của nhà máy", "Vi phạm tiêu chuẩn thiết kế nhà xưởng theo Luật An toàn thực phẩm"], 1, "Việc bỏ qua quy định về nồng độ hóa chất và thời gian tiếp xúc là vi phạm trực tiếp Quy trình vệ sinh (thao tác cụ thể) trong SSOP, khiến sàn xưởng không đạt yêu cầu vô trùng/sạch sẽ, dẫn đến rủi ro ô nhiễm chéo cao.", 3);
  add(2, "Tại nhà máy chế biến thủy sản, sàn khu vực phân loại cá thường xuyên bị bám mỡ và có mùi hôi do mật độ sản xuất cao. Biên bản kiểm tra SSOP ghi nhận sàn chỉ được rửa 1 lần vào cuối ngày. Đâu là giải pháp khắc phục triệt để và đúng chuẩn QLCL nhất?", ["Giữ nguyên tần suất nhưng tăng gấp đôi nồng độ hóa chất tẩy rửa vào cuối ngày", "Điều chỉnh SSOP: tăng tần suất vệ sinh trong ca, bổ sung hóa chất tẩy mỡ chuyên dụng, quy định rõ người làm và thời gian tiếp xúc", "Xịt nước thơm để át mùi hôi trong quá trình sản xuất", "Lắp đặt hệ thống quạt thông gió công suất lớn để hút mùi hôi trên sàn"], 1, "Để khắc phục sự cố bám mỡ và mùi hôi (nguy cơ ô nhiễm chéo), cần sửa đổi quy trình SSOP bằng cách tăng tần suất vệ sinh hợp lý trong ca, áp dụng đúng loại hóa chất tẩy mỡ, thời gian tiếp xúc và phân công nhân sự cụ thể.", 3);
  add(1, "Theo quy trình vệ sinh chuẩn (SSOP) đối với sàn nhà xưởng, thứ tự thực hiện các bước vệ sinh nào sau đây là đúng?", ["Quét rác → Rửa bằng nước sạch → Lau đều bằng dung dịch Cloramin B 200 ppm → Để khô tự nhiên", "Lau dung dịch Cloramin B 200 ppm → Quét rác → Rửa bằng nước sạch → Để khô tự nhiên", "Rửa bằng nước sạch → Quét rác → Lau dung dịch Cloramin B 200 ppm → Dùng quạt sấy khô", "Quét rác → Lau dung dịch Cloramin B 200 ppm → Rửa lại bằng nước sạch → Để khô tự nhiên"], 0, "Trình tự quy định trong SSOP vệ sinh sàn là: Quét rác → Rửa bằng nước sạch → Lau đều bằng dung dịch Cloramin B 200 ppm (20g/10L) → Để khô tự nhiên.", 1);
  add(1, "Trong quy trình SSOP vệ sinh sàn, nồng độ dung dịch Cloramin B và tỷ lệ pha chế được quy định là bao nhiêu?", ["100 ppm (tương ứng 10g / 10L nước)", "200 ppm (tương ứng 20g / 10L nước)", "500 ppm (tương ứng 50g / 10L nước)", "50 ppm (tương ứng 5g / 10L nước)"], 1, "Quy trình quy định rõ việc pha dung dịch khử trùng Cloramin B ở nồng độ 200 ppm, tương ứng với tỷ lệ 20g Cloramin B trong 10 lít nước.", 1);
  add(1, "Tần suất thực hiện quy trình vệ sinh sàn theo SSOP đã quy định là khi nào?", ["Đầu mỗi ca sản xuất", "Giữa ca sản xuất", "Cuối mỗi ca sản xuất", "Định kỳ 1 lần mỗi tuần"], 2, "Theo quy định SSOP nêu trên, tần suất thực hiện vệ sinh sàn là vào cuối mỗi ca sản xuất.", 1);
  add(1, "Nội dung nào sau đây KHÔNG thuộc 'Phần 3 — Giám sát phân công' trong quy trình SSOP?", ["Quy định nhân sự chịu trách nhiệm giám sát và tần suất giám sát", "Phương pháp kiểm tra (quan sát, test nhanh) và biểu mẫu theo dõi", "Tiêu chí đánh giá mức độ sạch của sàn", "Tính toán chi phí mua sắm hóa chất Cloramin B theo tháng"], 3, "Phần 3 Giám sát phân công chỉ quy định: ai giám sát, kiểm tra bằng cách nào (quan sát, test nhanh), tiêu chí đánh giá, biểu mẫu và tần suất. Chi phí mua hóa chất thuộc hoạt động quản trị/kế toán, không nằm trong SSOP.", 2);
  add(1, "Tại một nhà máy chế biến thực phẩm, công nhân B tiến hành pha 10g Cloramin B vào 10 lít nước để lau sàn nhà xưởng vào giữa ca sản xuất và dùng quạt thổi khô lập tức. Nhân viên QA kiểm tra và phát hiện sự việc. Nhận định nào sau đây là ĐÚNG về vi phạm của công nhân B so với quy trình SSOP?", ["Công nhân B chỉ làm sai thời điểm vệ sinh (thực hiện giữa ca thay vì cuối ca).", "Công nhân B vi phạm 3 điểm: pha sai nồng độ (100 ppm thay vì 200 ppm), thực hiện sai thời điểm (giữa ca thay vì cuối ca) và sai phương pháp làm khô (dùng quạt thay vì để khô tự nhiên).", "Công nhân B làm đúng quy trình nhưng sử dụng sai loại hóa chất khử trùng.", "Công nhân B làm đúng vì dùng quạt thổi khô giúp tiết kiệm thời gian chờ đợi giữa các ca."], 1, "Công nhân B đã vi phạm SSOP ở 3 khía cạnh: (1) Pha 10g/10L chỉ đạt 100 ppm (quy định là 200 ppm/20g/10L); (2) Thực hiện giữa ca (quy định là cuối ca); (3) Dùng quạt sấy (quy định là để khô tự nhiên).", 3);
  add(2, "Theo quy trình Quy chuẩn vệ sinh chuẩn (SSOP) đối với vệ sinh sàn nhà xưởng trong ví dụ, nồng độ Cloramin B đạt yêu cầu nằm trong khoảng nào?", ["50 – 100 ppm", "100 – 150 ppm", "150 – 250 ppm", "250 – 350 ppm"], 2, "Theo quy trình SSOP vệ sinh sàn được nêu, nồng độ dung dịch khử trùng Cloramin B đạt chuẩn phải nằm trong khoảng 150–250 ppm.", 1);
  add(2, "Tần suất thực hiện giám sát vệ sinh sàn nhà xưởng và test nồng độ hóa chất của nhân viên QC theo quy định là bao nhiêu?", ["1 lần/tuần", "1 lần/ngày", "1 lần/ca", "2 lần/ca"], 2, "Tần suất giám sát vệ sinh sàn nhà xưởng và kiểm tra nồng độ Cloramin B được quy định là 1 lần/ca.", 1);
  add(1, "Kết quả giám sát vệ sinh sàn và test nhanh nồng độ Cloramin B của bộ phận QC được ghi chép vào biểu mẫu nào?", ["BM-SSOP-01", "BM-HACCP-02", "BM-GMP-01", "BM-ISO-9001"], 0, "Theo quy định của quy trình SSOP nêu trên, kết quả quan sát và kiểm tra nồng độ Cloramin B được ghi vào biểu mẫu BM-SSOP-01.", 1);
  add(2, "Để đánh giá tình trạng vệ sinh sàn nhà xưởng theo SSOP, nhân viên QC phải kết hợp các phương pháp giám sát nào?", ["Chỉ quan sát bằng mắt thường", "Quan sát bằng mắt thường và test nhanh nồng độ Cloramin B", "Đo độ pH và kiểm tra vi sinh định kỳ hàng ca", "Gửi mẫu bề mặt sàn tới phòng kiểm nghiệm độc lập mỗi ca"], 1, "Phương pháp giám sát SSOP vệ sinh sàn bao gồm hai bước: QC quan sát bằng mắt thường và thực hiện test nhanh nồng độ Cloramin B.", 2);
  add(1, "Trong Phần 4 — Hành động khắc phục (Xử lý sự cố) của quy trình SSOP, nội dung nào sau đây KHÔNG bắt buộc phải thực hiện khi phát hiện sự cố không đạt?", ["Thực hiện hành động xử lý ngay lập tức", "Xác định nguyên nhân gốc rễ và phân công người chịu trách nhiệm", "Ghi chép đầy đủ diễn biến và kết quả vào biên bản sự cố", "Tạm dừng toàn bộ hoạt động của công ty và hủy bỏ toàn bộ lô hàng sản xuất trong ngày"], 3, "Hành động khắc phục SSOP yêu cầu: nêu trường hợp không đạt, xử lý ngay, tìm nguyên nhân gốc rễ, xác định người chịu trách nhiệm và ghi chép biểu mẫu. Việc tạm dừng toàn bộ công ty hay hủy toàn bộ lô hàng ngay lập tức là không cần thiết nếu sự cố vệ sinh sàn có thể khắc phục trực tiếp.", 2);
  add(1, "Tại một nhà máy chế biến thủy sản, nhân viên QC tiến hành test nhanh dung dịch Cloramin B dùng để khử trùng sàn nhà xưởng trước ca làm việc và ghi nhận kết quả là 100 ppm. Theo quy trình SSOP (chuẩn 150–250 ppm), QC cần thực hiện hành động khắc phục nào sau đây?", ["Bỏ qua vì 100 ppm vẫn có khả năng diệt khuẩn tốt, tiếp tục cho sản xuất", "Yêu cầu điều chỉnh/pha bổ sung Cloramin B để nâng nồng độ đạt 150–250 ppm, tiến hành tẩy rửa lại sàn, tìm nguyên nhân và ghi chép vào biên bản sự cố", "Tăng thời gian ngâm sàn lên gấp đôi mà không cần điều chỉnh nồng độ hóa chất", "Lập tức tiêu hủy toàn bộ bán thành phẩm đang có trên sàn nhà xưởng"], 1, "Nồng độ 100 ppm chưa đạt chuẩn 150-250 ppm. QC phải thực hiện hành động khắc phục ngay (pha bổ sung đạt chuẩn, tẩy rửa lại sàn), tìm nguyên nhân gốc rễ, phân định trách nhiệm và ghi chép lại theo Phần 4 của SSOP.", 3);
  add(2, "Theo quy định về SSOP (Quy phạm vệ sinh chuẩn), mỗi quy phạm vệ sinh cốt lõi bắt buộc phải giải quyết được bao nhiêu câu hỏi nền tảng?", ["3 câu hỏi", "4 câu hỏi", "5 câu hỏi", "6 câu hỏi"], 1, "Mỗi quy phạm SSOP cốt lõi phải trả lời được 4 câu hỏi: Yêu cầu là gì? Quy trình như thế nào? Giám sát ra sao? Khắc phục khi sự cố như thế nào?", 1);
  add(2, "Trong quá trình kiểm tra vệ sinh sàn nhà xưởng, nhân viên QC phát hiện sàn vẫn còn bẩn và nồng độ chất sát trùng đo được dưới 150 ppm. Hành động khắc phục ngay lập tức là gì?", ["Tiếp tục cho sản xuất và bổ sung hóa chất sau ca làm việc", "Tăng gấp đôi thời gian chiếu đèn UV để diệt khuẩn", "Thực hiện vệ sinh lại sàn và pha lại hóa chất đúng nồng độ", "Lập biên bản tiêu hủy toàn bộ lô hàng đang chế biến"], 2, "Theo quy trình xử lý sự cố vệ sinh sàn, khi sàn còn bẩn hoặc nồng độ hóa chất < 150 ppm thì biện pháp khắc phục là vệ sinh lại và pha lại đúng nồng độ.", 2);
  add(2, "Khi xuất hiện sự cố không đạt tiêu chuẩn về vệ sinh sàn (sàn còn bẩn, nồng độ hóa chất không đủ), phân công trách nhiệm chỉ đạo và giám sát khắc phục được quy định như thế nào?", ["Giám đốc nhà máy chỉ đạo, Trưởng phòng Nhân sự giám sát", "Tổ trưởng chỉ đạo xử lý, nhân viên QC (Kiểm soát chất lượng) theo dõi giám sát", "Nhân viên vệ sinh tự chỉ đạo và tự giám sát", "Cán bộ QC chỉ đạo xử lý, Công nhân trực tiếp giám sát"], 1, "Quy trình SSOP vệ sinh sàn quy định tổ trưởng chỉ đạo trực tiếp công nhân làm lại và QC chịu trách nhiệm theo dõi, giám sát.", 2);
  add(2, "Mọi hành động khắc phục sự cố mất vệ sinh sàn nhà xưởng phải được ghi chép lại vào biểu mẫu quản lý nào sau đây?", ["BM-HACCP-01", "BM-SSOP-02", "BM-GMP-03", "BM-ISO-9001"], 1, "Thông tin vi phạm và hành động khắc phục vệ sinh sàn được ghi nhận vào biểu mẫu BM-SSOP-02.", 1);
  add(2, "Theo SSOP 1 về an toàn nguồn nước, nước tiếp xúc trực tiếp với thực phẩm hoặc dùng để vệ sinh bề mặt tiếp xúc thực phẩm phải đạt tiêu chuẩn quy chuẩn kỹ thuật quốc gia nào?", ["QCVN 01:2009/BYT (Quy chuẩn kỹ thuật quốc gia về chất lượng nước ăn uống)", "QCVN 02:2009/BYT (Quy chuẩn kỹ thuật quốc gia về chất lượng nước sinh hoạt)", "QCVN 06-1:2010/BYT (Quy chuẩn kỹ thuật quốc gia đối với nước uống đóng chai)", "QCVN 14:2008/BTNMT (Quy chuẩn kỹ thuật quốc gia về nước thải sinh hoạt)"], 0, "Nước dùng trong sản xuất thực phẩm và vệ sinh theo SSOP 1 phải đạt tiêu chuẩn nước uống được theo QCVN 01:2009/BYT.", 1);
  add(2, "Trong quy trình clo hóa xử lý nước cấp sản xuất theo SSOP 1, thông số nồng độ clo dư và thời gian tiếp xúc tối thiểu đạt chuẩn là bao nhiêu?", ["Nồng độ clo dư: 0,1 – 0,3 mg/L, thời gian tiếp xúc tối thiểu 15 phút", "Nồng độ clo dư: 0,3 – 0,5 mg/L, thời gian tiếp xúc tối thiểu 30 phút", "Nồng độ clo dư: 0,5 – 1,0 mg/L, thời gian tiếp xúc tối thiểu 45 phút", "Nồng độ clo dư: 1,0 – 2,0 mg/L, thời gian tiếp xúc tối thiểu 60 phút"], 1, "Quy trình clo hóa tiêu chuẩn theo SSOP 1 yêu cầu nồng độ clo dư đạt 0,3 – 0,5 mg/L và thời gian tiếp xúc tối thiểu là 30 phút.", 2);
  add(2, "Tại một nhà máy thủy sản, kiểm toán viên ATTP phát hiện hệ thống xử lý nước cấp có nồng độ clo dư đo được là 0,4 mg/L, tuy nhiên thời gian tiếp xúc của nước với clo trước khi đưa vào sản xuất chỉ đạt 20 phút. Đánh giá nào sau đây là đúng?", ["Đạt yêu cầu vì nồng độ clo dư nằm trong khoảng quy định 0,3 – 0,5 mg/L", "Không đạt yêu cầu vì thời gian tiếp xúc chưa đủ thời gian tối thiểu 30 phút", "Đạt yêu cầu vì thời gian tiếp xúc không ảnh hưởng đến khả năng diệt khuẩn của clo", "Không đạt yêu cầu vì nồng độ clo dư 0,4 mg/L là quá cao gây độc thực phẩm"], 1, "SSOP 1 bắt buộc đồng thời cả 2 điều kiện: Nồng độ clo dư 0,3 - 0,5 mg/L VÀ thời gian tiếp xúc tối thiểu 30 phút. Thời gian 20 phút chưa đủ để đảm bảo hiệu quả diệt khuẩn.", 3);
  add(2, "Theo quy chuẩn kiểm soát vệ sinh an toàn thực phẩm, tần suất kiểm tra định kỳ các chỉ tiêu vi sinh (Coliforms, E. coli) trên bề mặt tiếp xúc hoặc sản phẩm là bao lâu?", ["1 lần/tháng", "1 lần/6 tháng", "1 lần/tuần", "1 lần/năm"], 0, "Theo quy định kiểm soát vi sinh định kỳ, chỉ tiêu vi sinh (Coliforms, E. coli) cần được kiểm tra với tần suất 1 lần/tháng để đảm bảo an toàn vệ sinh.", 1);
  add(2, "Tần suất kiểm tra chỉ tiêu kim loại nặng trong chương trình giám sát an toàn thực phẩm được quy định như thế nào?", ["1 lần/tháng hoặc khi có chỉ đạo của Bộ Y tế", "1 lần/6 tháng hoặc khi có nguy cơ ô nhiễm", "1 lần/tuần đối với mọi nguyên liệu đầu vào", "Chỉ kiểm tra 1 lần duy nhất khi công bố sản phẩm"], 1, "Chỉ tiêu kim loại nặng được kiểm tra định kỳ 1 lần/6 tháng hoặc phải tiến hành kiểm tra ngay khi phát hiện có nguy cơ ô nhiễm.", 1);
  add(2, "Trong hệ thống Quy phạm vệ sinh chuẩn SSOP (Sanitation Standard Operating Procedures), nội dung của SSOP 2 quy định về vấn đề gì?", ["An toàn nguồn nước sản xuất", "Vệ sinh các bề mặt tiếp xúc trực tiếp với sản phẩm", "Ngăn ngừa sự ô nhiễm chéo giữa các khu vực", "Kiểm soát động vật gây hại"], 1, "SSOP 2 quy định chi tiết về quy trình và tiêu chuẩn làm vệ sinh các bề mặt tiếp xúc trực tiếp với sản phẩm.", 1);
  add(2, "Quy trình làm vệ sinh bề mặt tiếp xúc trực tiếp với sản phẩm theo chuẩn SSOP 2 chuẩn hóa gồm bao nhiêu bước?", ["3 bước", "4 bước", "5 bước", "7 bước"], 2, "Quy trình làm vệ sinh bề mặt tiếp xúc trực tiếp với sản phẩm theo SSOP 2 tuân thủ quy trình chuẩn gồm 5 bước.", 2);
  add(2, "Việc kiểm tra định kỳ chỉ tiêu vi sinh Coliforms và E. coli hàng tháng trên bề mặt tiếp xúc nhằm mục đích chính nào sau đây?", ["Đánh giá mức độ ô nhiễm vi sinh vật chỉ thị phân và hiệu quả của quy trình vệ sinh SSOP", "Phát hiện sự xuất hiện của các độc tố nấm mốc trong môi trường nhà xưởng", "Đo lường độ bền của thiết bị sau khi tiếp xúc với hóa chất tẩy rửa", "Xác định hàm lượng kim loại nặng tích tụ trên bề mặt dụng cụ"], 0, "Coliforms và E. coli là các vi sinh vật chỉ thị ô nhiễm vệ sinh/phân, việc kiểm tra định kỳ giúp đánh giá hiệu quả làm sạch và khử trùng bề mặt.", 2);
  add(3, "Tại một nhà máy chế biến thực phẩm, kiểm toán viên chất lượng phát hiện nguồn nước ngầm đầu vào có hiện tượng nghi ngờ nhiễm xỉ thải công nghiệp từ khu vực lân cận. Mặc dù đợt kiểm tra kim loại nặng gần nhất mới thực hiện cách đây 2 tháng, cơ sở cần hành động như thế nào cho đúng nguyên tắc quản lý rủi ro?", ["Tiếp tục chờ đủ 6 tháng mới kiểm tra lại kim loại nặng theo đúng kế hoạch định kỳ.", "Chỉ cần tăng cường kiểm tra vi sinh Coliforms/E.coli lên 1 lần/tuần.", "Lập tức lấy mẫu kiểm tra chỉ tiêu kim loại nặng do phát sinh nguy cơ ô nhiễm.", "Dừng toàn bộ quy trình SSOP 2 cho đến khi có kết quả kiểm tra vi sinh tháng tới."], 2, "Quy định nêu rõ kiểm tra kim loại nặng '1 lần/6 tháng HOẶC khi có nguy cơ'. Khi phát hiện nguồn nước nghi nhiễm hóa chất/xỉ thải, nguy cơ tăng cao nên phải kiểm tra ngay tức thì.", 3);
  add(2, "Trong quá trình giám sát SSOP 2 tại xưởng chế biến thủy hải sản, nhân viên QC (Kiểm soát chất lượng) phát hiện công nhân xịt trực tiếp hóa chất khử trùng lên bề mặt bàn cắt còn bám nhiều vụn thịt và mỡ (chưa làm sạch cơ học thô). Đánh giá nào sau đây là chính xác về mặt kỹ thuật vệ sinh?", ["Đạt yêu cầu vì hóa chất khử trùng sẽ tự động diệt sạch cả chất hữu cơ và vi sinh vật.", "Không đạt vì chất hữu cơ thô sẽ phản ứng và làm bất hoạt hóa chất khử trùng, giảm hiệu quả diệt vi sinh (Coliforms, E.coli).", "Đạt yêu cầu vì giúp tiết kiệm thời gian thực hiện quy trình 5 bước.", "Không đạt vì hóa chất sẽ làm tăng nồng độ kim loại nặng trên bề mặt tiếp xúc."], 1, "Quy trình 5 bước của SSOP yêu cầu phải loại bỏ chất bẩn cơ học và rửa sạch trước khi khử trùng. Mảnh bám hữu cơ làm mất tác dụng của hóa chất khử trùng, khiến chỉ tiêu vi sinh như Coliforms, E.coli không đạt.", 3);
  add(2, "Theo quy trình làm vệ sinh dụng cụ chế biến thực phẩm, phương pháp khử trùng bằng nước nóng phải tuân thủ điều kiện nào về nhiệt độ và thời gian?", ["Nhiệt độ ≥70°C trong tối thiểu 15 giây", "Nhiệt độ ≥82°C trong tối thiểu 30 giây", "Nhiệt độ ≥100°C trong tối thiểu 10 giây", "Nhiệt độ ≥65°C trong tối thiểu 60 giây"], 1, "Theo quy trình vệ sinh, bước khử trùng bằng nước nóng yêu cầu nhiệt độ phải đạt từ 82°C trở lên và duy trì thời gian tối thiểu 30 giây.", 1);
  add(2, "Vì sao sau khi tráng lại ở cuối quy trình làm vệ sinh dụng cụ chế biến thực phẩm, quy định bắt buộc phải 'để khô tự nhiên' mà KHÔNG được dùng khăn lau?", ["Để tiết kiệm chi phí trang bị khăn lau cho nhà máy", "Tránh nguy cơ tái nhiễm vi sinh vật từ khăn lau sang dụng cụ đã làm sạch", "Giúp dụng cụ không bị trầy xước bề mặt", "Để hóa chất tẩy rửa còn sót lại tự bay hơi"], 1, "Khăn lau dù trông có vẻ sạch vẫn chứa vi sinh vật. Việc lau lại dụng cụ sau khi rửa sẽ gây ra nguy cơ tái nhiễm vi sinh vật từ khăn sang dụng cụ.", 2);
  add(2, "Theo quy định mã hóa màu sắc dụng cụ để ngăn ngừa nhiễm chéo, thớt màu xanh lá cây được quy định sử dụng riêng cho nhóm thực phẩm nào?", ["Thực phẩm tươi sống (thịt, cá sống)", "Thực phẩm chín đã qua chế biến", "Trái cây và rau củ", "Sản phẩm từ sữa và bơ"], 2, "Quy định mã hóa màu sắc thớt: màu đỏ dùng cho thực phẩm sống, màu xanh dùng cho trái cây/rau củ, và màu trắng dùng cho thực phẩm chín.", 1);
  add(2, "Theo quy phạm vệ sinh SSOP 3 (Ngăn ngừa nhiễm chéo), nguyên tắc thiết kế luồng không khí và dòng nước thải trong khu vực sản xuất phải tuân theo chiều nào?", ["Từ Khu bẩn → Khu sạch", "Từ Khu sạch → Khu bẩn", "Xoay vòng khép kín trong từng khu vực", "Tùy thuộc vào thiết kế mặt bằng, không bắt buộc"], 1, "Để ngăn ngừa nhiễm chéo vi sinh vật và bụi bẩn từ nơi ô nhiễm sang nơi vô trùng, luồng không khí và dòng nước thải bắt buộc phải đi từ Khu sạch → Khu bẩn.", 2);
  add(2, "Tại một nhà máy chế biến thực phẩm, kiểm tra viên phát hiện công nhân mặc trang phục bảo hộ màu xanh (dành cho khu vực thô/bẩn) đi vào khu vực bao gói thành phẩm (khu tinh/sạch). Hành vi này vi phạm quy phạm vệ sinh nào?", ["SSOP 1 — An toàn nguồn nước", "SSOP 3 — Ngăn ngừa nhiễm chéo", "SSOP 5 — Bảo vệ sản phẩm không bị nhiễm bẩn", "SSOP 6 — Sử dụng và bảo quản hóa chất độc hại"], 1, "Quy định SSOP 3 yêu cầu luồng di chuyển của công nhân là một chiều và bảo hộ lao động phải phân biệt màu sắc (xanh = khu thô/bẩn, trắng = khu tinh/sạch). Việc mang đồ bảo hộ khu bẩn sang khu sạch vi phạm quy tắc ngăn ngừa nhiễm chéo.", 3);
  add(2, "Theo quy định về vệ sinh cá nhân (SSOP 4), quy trình rửa tay của công nhân trực tiếp sản xuất phải đáp ứng các tiêu chuẩn nào?", ["Rửa nhanh với nước sạch trong 10 giây", "Thực hiện 6 bước chà tay với xà phòng, thời gian tối thiểu 20 giây", "Chỉ cần ngâm tay vào dung dịch cồn khử trùng 70 độ", "Rửa tay bằng xà phòng trong 5 giây rồi lau khô bằng khăn vải dùng chung"], 1, "SSOP 4 quy định chuẩn rửa tay gồm 6 bước chà tay với xà phòng và thời gian thực hiện tối thiểu là 20 giây.", 1);
  add(2, "Thời gian khám sức khỏe định kỳ tối thiểu đối với nhân viên trực tiếp sản xuất, chế biến thực phẩm theo quy định vệ sinh cá nhân (SSOP 4) là bao lâu?", ["6 tháng một lần (2 lần/năm)", "1 tháng một lần", "1 lần/năm (12 tháng một lần)", "2 năm một lần"], 2, "Theo quy định SSOP 4 về sức khỏe công nhân, người lao động trực tiếp tham gia sản xuất thực phẩm phải được khám sức khỏe định kỳ tối thiểu 1 lần/năm.", 1);
  add(2, "Để bảo vệ sản phẩm khỏi bị nhiễm bẩn vật lý theo SSOP 5, bóng đèn chiếu sáng lắp đặt tại khu vực sản xuất trực tiếp phải đáp ứng điều kiện nào?", ["Sử dụng bóng đèn dây tóc công suất lớn", "Bóng đèn bắt buộc phải có chụp chống vỡ (màng/hộp bảo vệ)", "Chỉ dùng bóng đèn ánh sáng vàng", "Bóng đèn không cần nắp che để tối ưu độ sáng"], 1, "SSOP 5 quy định bóng đèn trong khu sản xuất phải có chụp chống vỡ nhằm ngăn các mảnh thủy tinh rơi vào thực phẩm nếu bóng đèn gặp sự cố cháy nổ.", 1);
  add(2, "Trong công tác bảo trì thiết bị máy móc trực tiếp chế biến thực phẩm, loại mỡ/dầu bôi trơn nào được phép sử dụng để tránh gây ô nhiễm hóa chất cho sản phẩm (SSOP 5)?", ["Dầu nhớt xe máy công nghiệp", "Mỡ bò chịu nhiệt công nghiệp thông thường", "Dầu mỡ bôi trơn đạt chuẩn Food Grade (An toàn thực phẩm)", "Dầu thực vật tái chế"], 2, "SSOP 5 quy định chất bôi trơn sử dụng cho máy móc thiết bị có nguy cơ tiếp xúc với thực phẩm phải là loại Food Grade (chuyên dùng cho an toàn thực phẩm).", 1);
  add(2, "Theo quy định SSOP 6 về quản lý hóa chất độc hại, kho chứa hóa chất trong nhà máy thực phẩm bắt buộc phải có điều kiện gì?", ["Đặt ngay cạnh dây chuyền sản xuất để tiện lấy sử dụng", "Kho phải có khóa, mọi hóa chất phải có nhãn mác rõ ràng và Bảng chỉ dẫn an toàn hóa chất (MSDS)", "Chỉ cần dán nhãn tên hóa chất, không cần tài liệu MSDS đi kèm", "Có thể để chung hóa chất với vật liệu bao bì đóng gói"], 1, "SSOP 6 yêu cầu kho hóa chất phải có khóa an toàn, tất cả hóa chất phải dán nhãn đúng quy định và có tài liệu MSDS (Bảng chỉ dẫn an toàn hóa chất) đi kèm.", 2);
  add(2, "Trong buổi thanh tra an toàn thực phẩm tại xưởng chế biến thịt, đoàn kiểm tra phát hiện một can đựng dung dịch tẩy rửa không dán nhãn nhãn mác đặt ngay cạnh bàn cắt thịt. Trưởng phòng QLCL cần đánh giá đây là sự cố vi phạm quy phạm nào và rủi ro trực tiếp là gì?", ["Vi phạm SSOP 4; rủi ro công nhân không rửa tay sạch", "Vi phạm SSOP 6; rủi ro ngộ độc hóa chất do sử dụng nhầm lẫn hoặc hóa chất văng bắn vào thực phẩm", "Vi phạm SSOP 3; rủi ro vi sinh vật lây lan từ thịt sống sang thịt chín", "Vi phạm SSOP 5; rủi ro mảnh vỡ thủy tinh rơi vào sản phẩm"], 1, "Việc để hóa chất không nhãn mác tại khu vực sản xuất vi phạm nghiêm trọng SSOP 6 (Sử dụng và bảo quản hóa chất độc hại), gây ra rủi ro ô nhiễm hóa chất hoặc ngộ độc cho người tiêu dùng do dùng nhầm hóa chất.", 3);
  add(2, "Theo quy phạm Quy trình vệ sinh chuẩn (SSOP 7) về kiểm soát sức khỏe công nhân, thời gian định kỳ tối thiểu để tổ chức khám sức khỏe cho người lao động là bao lâu?", ["Ít nhất 6 tháng một lần", "Ít nhất 1 lần/năm", "Ít nhất 2 năm một lần", "Chỉ cần khám một lần duy nhất khi tuyển dụng"], 1, "SSOP 7 quy định yêu cầu khám sức khỏe công nhân khi tuyển dụng và khám định kỳ ít nhất 1 lần/năm.", 1);
  add(2, "Tại một nhà máy chế biến thủy sản xuất khẩu, trong buổi kiểm tra đầu giờ, tổ trưởng phát hiện một công nhân trực tiếp đóng gói sản phẩm có biểu hiện sốt và tiêu chảy. Theo quy định SSOP 7, biện pháp xử lý đúng quy trình và an toàn nhất là gì?", ["Cấp phát khẩu trang, găng tay bổ sung và cho tiếp tục làm việc ở vị trí cũ", "Phạt hành chính công nhân đó và yêu cầu tiếp tục làm việc cho hết ca", "Tạm thời cách ly công nhân khỏi các khâu tiếp xúc trực tiếp với thực phẩm và chuyển sang khu vực không gây rủi ro hoặc nghỉ điều trị", "Cho công nhân tự điều trị tại chỗ và vẫn phân công vào khu vực bao bì sơ cấp"], 2, "SSOP 7 quy định tạm thời cách ly công nhân có các triệu chứng bệnh truyền nhiễm (tiêu chảy, sốt, vết thương hở) khỏi các khâu tiếp xúc trực tiếp với thực phẩm để tránh ô nhiễm vi sinh vật vào sản phẩm.", 3);
  add(2, "Biện pháp nào sau đây thuộc SSOP 8 về kiểm soát động vật gây hại (Pest Control) trong nhà máy thực phẩm?", ["Phun thuốc trừ sâu trực tiếp lên dây chuyền sản xuất khi đang hoạt động", "Lắp đặt hệ thống bẫy chuột vòng ngoài và vòng trong, đèn diệt côn trùng và màng chắn nhựa", "Nuôi mèo trong kho nguyên liệu để bắt chuột", "Chỉ thực hiện bẫy côn trùng khi khách hàng tới đánh giá"], 1, "SSOP 8 bao gồm hệ thống bẫy chuột vòng ngoài/vòng trong, đèn diệt côn trùng, lưới chống muỗi, màng chắn nhựa và bịt kín các khe hở.", 1);
  add(2, "Khi phát hiện sự cố sai lệch trong quá trình kiểm soát vệ sinh SSOP tại nhà máy, thứ tự các bước xử lý đúng quy chuẩn là gì?", ["Xác định nguyên nhân → Ngừng hoạt động → Thực hiện hành động khắc phục → Ghi chép", "Ngừng hoạt động liên quan ngay → Xác định nguyên nhân → Thực hiện hành động khắc phục → Ghi chép & xem xét phòng ngừa tái diễn", "Thực hiện hành động khắc phục → Tiếp tục sản xuất → Ghi chép hồ sơ sau", "Báo cáo cấp trên → Chờ quyết định → Không cần ngừng hoạt động sản xuất"], 1, "Quy trình xử lý sai lệch chuẩn gồm: Ngừng hoạt động liên quan ngay → Xác định nguyên nhân → Thực hiện hành động khắc phục → Ghi chép & xem xét phòng ngừa tái diễn.", 2);
  add(2, "Hồ sơ giám sát và thẩm tra quy trình vệ sinh SSOP phải được lưu trữ trong thời gian tối thiểu là bao lâu theo quy định?", ["6 tháng", "1 năm", "Tối thiểu 02 năm hoặc theo quy định pháp luật", "5 năm"], 2, "Hồ sơ giám sát và thẩm tra vệ sinh phải được lưu trữ tối thiểu 02 năm hoặc theo quy định pháp luật liên quan.", 1);
  add(2, "Trong công tác thẩm tra vệ sinh nhà máy, Quản lý chất lượng (QA) sử dụng phương pháp 'Swab test' (quẹt mẫu bề mặt) nhằm mục đích chính là gì?", ["Kiểm tra độ bền cơ học của bề mặt thiết bị sản xuất", "Kiểm tra định lượng hóa chất tẩy rửa còn dư trên thiết bị", "Xác nhận hiệu quả làm sạch vi sinh thực tế trên bề mặt thiết bị sau khi công nhân tẩy rửa", "Đo nhiệt độ bề mặt máy móc trước khi vận hành"], 2, "Swab test là phương pháp lấy mẫu vi sinh bề mặt nhằm thẩm tra và xác nhận công nhân đã rửa sạch thực sự hay chưa.", 2);
  add(3, "Triết lý cốt lõi của hệ thống Quản lý An toàn Thực phẩm HACCP (Phân tích mối nguy và kiểm soát điểm tới hạn) là gì?", ["Tập trung kiểm tra và loại bỏ sản phẩm lỗi ở đoạn cuối dây chuyền", "Tập trung vào phòng ngừa ngay trong quá trình sản xuất thay vì chờ kiểm tra sản phẩm cuối cùng", "Dựa hoàn toàn vào việc phạt hành chính công nhân vi phạm", "Chỉ kiểm soát các yếu tố chi phí và năng suất lao động"], 1, "Triết lý cốt lõi của HACCP là tập trung vào kiểm soát phòng ngừa ngay trong quá trình sản xuất thay vì kiểm tra thành phẩm.", 1);
  add(3, "Mối quan hệ chính xác giữa các tiêu chuẩn GMP, SSOP, HACCP và ISO 22000 trong hệ thống quản lý an toàn thực phẩm là gì?", ["HACCP là tiền đề để xây dựng GMP và SSOP", "GMP và SSOP (PRP) là nền tảng bắt buộc để áp dụng HACCP, và HACCP là hạt nhân của ISO 22000", "ISO 22000 thay thế hoàn toàn và không cần đến HACCP hay GMP", "SSOP và HACCP độc lập hoàn toàn, không liên quan đến nhau"], 1, "Công thức mối quan hệ: GMP + SSOP (chương trình tiên quyết PRP) → HACCP → ISO 22000. Nếu không có nền tảng GMP/SSOP thì HACCP không thể vận hành hiệu quả.", 2);
  add(3, "Theo tiêu chuẩn ISO 22000 và FSSC 22000, nhóm yếu tố nào sau đây được tách thành một nhóm mối nguy riêng biệt thứ 4 bên cạnh Sinh học, Hóa học và Vật lý?", ["Mối nguy Cơ học", "Mối nguy Chất gây dị ứng (Allergens)", "Mối nguy Bức xạ", "Mối nguy Cảm quan"], 1, "Trong ISO 22000/FSSC 22000, Chất gây dị ứng (Allergens) như đậu phộng, hải sản, sữa, trứng... được tách thành mối nguy thứ 4 riêng biệt.", 2);
  add(3, "Trong quá trình đóng hộp mứt hoa quả, công nhân phát hiện một ốc vít kim loại bị rơi từ máy ghép nhãn vào trong hũ sản phẩm. Sự cố này thuộc loại mối nguy nào theo phân loại HACCP?", ["Mối nguy Sinh học", "Mối nguy Hóa học", "Mối nguy Vật lý", "Mối nguy Dị ứng"], 2, "Ốc vít kim loại là dị vật có khả năng gây tổn thương vật lý cho người tiêu dùng, do đó thuộc mối nguy Vật lý.", 2);
  add(3, "Thuật ngữ 'Validation' (Xác nhận giá trị sử dụng) và 'Verification' (Thẩm tra) trong HACCP được phân biệt ngắn gọn và chính xác nhất như thế nào?", ["Validation = 'Kế hoạch có được làm đúng không?'; Verification = 'Kế hoạch có đúng không?'", "Validation = 'Kế hoạch có đúng không?'; Verification = 'Kế hoạch có được làm đúng không?'", "Cả hai thuật ngữ đều có nghĩa là kiểm tra lại hồ sơ ghi chép", "Validation áp dụng cho GMP, còn Verification chỉ áp dụng cho SSOP"], 1, "Validation trả lời câu hỏi 'Kế hoạch có đúng/hiệu quả không?' (trước khi vận hành); Verification trả lời 'Kế hoạch có được làm đúng không?' (trong và sau khi vận hành).", 2);
  add(3, "Khung triển khai HACCP tiêu chuẩn bao gồm bao nhiêu bước chuẩn bị sơ bộ và bao nhiêu nguyên tắc cốt lõi?", ["7 bước chuẩn bị sơ bộ và 5 nguyên tắc", "5 bước chuẩn bị sơ bộ và 7 nguyên tắc", "12 bước chuẩn bị sơ bộ và 0 nguyên tắc", "4 bước chuẩn bị sơ bộ và 8 nguyên tắc"], 1, "Khung triển khai HACCP gồm 12 bước: 5 bước chuẩn bị sơ bộ (Bước 1-5) và 7 nguyên tắc HACCP (Bước 6-12).", 1);
  add(3, "Thành phần của Đội HACCP trong một doanh nghiệp chế biến thực phẩm cần đảm bảo nguyên tắc nào để hoạt động hiệu quả?", ["Chỉ bao gồm các nhân viên thuộc bộ phận Quản lý chất lượng (QA/QC)", "Là nhóm đa ngành bao gồm các đại diện từ Quản lý chất lượng, Công nghệ TP, Vi sinh, Sản xuất, Mua hàng...", "Chỉ bao gồm Ban giám đốc và Kế toán trưởng", "Chỉ thuê chuyên gia bên ngoài mà không cần nhân sự nội bộ"], 1, "Đội HACCP phải là một nhóm đa ngành tập hợp kiến thức từ nhiều bộ phận như QA/QC, Công nghệ, Vi sinh, Sản xuất, Mua hàng...", 2);
  add(3, "Trong 5 bước chuẩn bị sơ bộ của HACCP, bước nào đòi hỏi Đội HACCP phải trực tiếp xuống nhà máy đối chiếu sơ đồ trên giấy với thực tế dây chuyền?", ["Bước 1: Thành lập Đội HACCP", "Bước 2: Mô tả sản phẩm", "Bước 4: Xây dựng sơ đồ dòng chảy", "Bước 5: Xác nhận sơ đồ dòng chảy tại hiện trường"], 3, "Bước 5 là bước kiểm tra thực tế tại nhà máy nhằm đảm bảo sơ đồ dòng chảy phản ánh chính xác các hoạt động đang diễn ra.", 2);
  add(2, "Tại một cơ sở chế biến sữa tươi, đoàn thanh tra phát hiện quy trình rửa dụng cụ chứa chỉ thực hiện bằng nước lạnh thông thường. Kết quả kiểm nghiệm vi sinh cho thấy chỉ số vi khuẩn Coliform vượt ngưỡng cho phép 15 lần. Theo quy định về SSOP và HACCP, hành động nào là đúng chuẩn nhất?", ["Tiếp tục cho xuất xưởng lô sữa vì đã đóng hộp xong", "Ngừng ngay dây chuyền đóng gói, cách ly lô hàng bị ảnh hưởng, tiến hành điều tra nguyên nhân, cải tiến quy trình rửa nước nóng/hóa chất và ghi chép biên bản xử lý sự cố", "Chỉ cần thêm chất bảo quản hóa học vào sữa để diệt vi khuẩn mà không cần sửa quy trình rửa", "Xóa bỏ hồ sơ giám sát vi sinh để tránh bị phạt"], 1, "Khi phát hiện sự cố không đạt về vi sinh/vệ sinh, cơ sở phải dừng ngay hoạt động liên quan, cách ly sản phẩm, xác định nguyên nhân, thực hiện hành động khắc phục, lập biên bản và xem xét phòng ngừa tái diễn theo quy định 2.5.3.", 3);
  add(1, "Trong hệ thống HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn), bước Nhận diện mối nguy yêu cầu lập danh mục bao gồm những nhóm mối nguy nào?", ["Mối nguy sinh học, hóa học và vật lý", "Mối nguy sinh học, môi trường và cơ học", "Mối nguy hóa học, phóng xạ và vi sinh", "Mối nguy vật lý, độc tố và dị nguyên"], 0, "Theo Nguyên tắc 1 của HACCP, bước nhận diện mối nguy yêu cầu lập danh mục tất cả mối nguy sinh học, hóa học và vật lý tại từng bước quy trình.", 1);
  add(1, "Điểm kiểm soát tới hạn (CCP - Critical Control Point) được định nghĩa như thế nào trong quản lý an toàn thực phẩm?", ["Bước mà tại đó việc kiểm soát là thiết yếu để ngăn ngừa, loại bỏ hoặc giảm mối nguy ATTP xuống mức chấp nhận được", "Mọi công đoạn trong quy trình sản xuất thực phẩm cần phải thực hiện giám sát vệ sinh", "Công đoạn kiểm tra chất lượng sản phẩm cuối cùng trước khi xuất xưởng", "Kho lưu trữ nguyên liệu ban đầu trong nhà máy chế biến thực phẩm"], 0, "Khái niệm CCP: Bước, công đoạn hoặc quá trình mà tại đó việc kiểm soát là thiết yếu để ngăn ngừa, loại bỏ hoặc giảm mối nguy ATTP xuống mức chấp nhận được.", 1);
  add(1, "Khẳng định nào sau đây là BẮT BUỘC ĐÚNG khi nói về mối quan hệ giữa Điểm kiểm soát (CP) và Điểm kiểm soát tới hạn (CCP)?", ["CP và CCP là hai khái niệm hoàn toàn độc lập và không liên quan đến nhau", "Mọi CCP đều là CP, nhưng không phải CP nào cũng là CCP", "Mọi CP đều là CCP, nhưng không phải CCP nào cũng là CP", "Tất cả các điểm kiểm soát trong nhà máy đều bắt buộc phải là CCP"], 1, "CCP là tập hợp con của CP. Do đó, mọi CCP đều là CP, nhưng không phải CP nào cũng là CCP.", 2);
  add(1, "Việc đánh giá mối nguy để xác định mối nguy nào là 'đáng kể' cần đưa vào kế hoạch HACCP dựa trên sự kết hợp của 2 tiêu chí nào?", ["Chi phí kiểm soát và thời gian thực hiện quy trình", "Khả năng xảy ra mối nguy và Mức độ nghiêm trọng/tác động của mối nguy", "Số lượng công nhân tham gia và loại thiết bị sử dụng", "Yêu cầu của khách hàng và tiêu chuẩn xuất khẩu của thị trường"], 1, "Đánh giá mối nguy dựa trên 2 tiêu chí: Khả năng xảy ra và Mức độ nghiêm trọng, kết hợp bằng Bảng đánh giá rủi ro để xác định mối nguy đáng kể.", 1);
  add(1, "Theo Cây quyết định CCP, tại một công đoạn CÓ biện pháp kiểm soát mối nguy và công đoạn đó ĐƯỢC THIẾT KẾ ĐẶC BIỆT nhằm loại bỏ hoặc giảm mối nguy xuống mức chấp nhận được (Câu hỏi Q2 = CÓ), kết luận là gì?", ["Công đoạn này không phải là CCP", "Công đoạn này chính là CCP", "Cần chuyển sang câu hỏi Q3 để đánh giá tiếp", "Cần chuyển sang câu hỏi Q4 để kiểm tra công đoạn sau"], 1, "Theo sơ đồ Cây quyết định xác định CCP, ở câu hỏi Q2 nếu câu trả lời là CÓ thì công đoạn đó được kết luận ngay là CCP.", 2);
  add(1, "Theo Cây quyết định xác định CCP, nếu mối nguy có thể tăng đến mức không thể chấp nhận được tại công đoạn hiện tại (Q3 = CÓ), nhưng CÓ một công đoạn SAU ĐÓ loại bỏ hoặc giảm mối nguy này xuống mức chấp nhận được (Q4 = CÓ), công đoạn hiện tại sẽ:", ["Được xác định là một CCP", "Không phải là CCP (để công đoạn sau xử lý)", "Yêu cầu dừng ngay dây chuyền sản xuất", "Trở thành điểm kiểm soát chất lượng ISO 9001"], 1, "Theo câu hỏi Q4 của Cây quyết định CCP: Nếu có công đoạn SAU ĐÓ loại bỏ/giảm mối nguy thì công đoạn hiện tại KHÔNG phải CCP, mối nguy sẽ do công đoạn sau xử lý.", 2);
  add(1, "Điều kiện nào dưới đây KHÔNG nằm trong 4 tiêu chí bắt buộc (phải đáp ứng đồng thời) để xác định một công đoạn là CCP?", ["Có mối nguy đáng kể tại công đoạn đó", "Có thể kiểm soát được mối nguy tại công đoạn đó", "Nếu không kiểm soát sẽ ảnh hưởng trực tiếp đến an toàn thực phẩm", "Chi phí trang bị thiết bị kiểm soát tại công đoạn đó phải thấp"], 3, "4 tiêu chí xác định CCP gồm: (1) Mối nguy đáng kể, (2) Kiểm soát được tại đó, (3) Ảnh hưởng trực tiếp đến ATTP nếu không kiểm soát, (4) Không có công đoạn sau loại bỏ được. Chi phí đầu tư không thuộc tiêu chí xác định CCP.", 2);
  add(1, "Tại một nhà máy sản xuất nước hoa quả đóng chai, công đoạn Tiệt trùng UHT được thiết kế riêng nhằm diệt hại vi sinh vật gây bệnh (mối nguy sinh học đáng kể). Sau bước này sản phẩm được chiết rót vô trùng và không còn công đoạn xử lý nhiệt nào khác. Theo 4 tiêu chí xác định CCP, công đoạn Tiệt trùng UHT được xác định là:", ["Điểm kiểm soát thông thường (CP)", "Điểm kiểm soát tới hạn (CCP)", "Mối nguy không đáng kể", "Quy trình vệ sinh chuẩn (SOP)"], 1, "Công đoạn Tiệt trùng UHT đáp ứng đủ 4 tiêu chí: Có mối nguy đáng kể (vi sinh vật), kiểm soát được tại đó, ảnh hưởng trực tiếp ATTP nếu thiếu hụt nhiệt, và không có công đoạn sau loại bỏ vi sinh vật. Do đó đây là CCP.", 3);
  add(1, "Tại dây chuyền chế biến thủy sản đông lạnh, cán bộ QA phát hiện mối nguy mảnh kim loại có thể xuất hiện từ khâu Cắt lát nguyên liệu. Tuy nhiên, ở cuối dây chuyền (trước khi đóng thùng) có trang bị Máy dò kim loại tự động để loại bỏ toàn bộ sản phẩm chứa mảnh kim loại. Theo Cây quyết định CCP (Q4), khâu Cắt lát nguyên liệu đối với mối nguy mảnh kim loại được kết luận là gì?", ["Là CCP vì phát hiện mối nguy phát sinh tại đây", "Không phải là CCP vì đã có công đoạn máy dò kim loại phía sau xử lý", "Bắt buộc dừng sản xuất để thay thế toàn bộ dao cắt", "Là CCP bắt buộc theo quy định của Luật An toàn Thực phẩm"], 1, "Trả lời CÓ cho câu hỏi Q4 (Có công đoạn SAU loại bỏ/giảm mối nguy này không?) -> Kết luận KHÔNG phải CCP tại bước Cắt lát, vì bước Máy dò kim loại phía sau sẽ đảm nhận việc kiểm soát loại bỏ mối nguy này.", 3);
  add(2, "Theo hệ thống HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn), 'Ngưỡng tới hạn' (Critical Limit) được định nghĩa như thế nào?", ["Là tiêu chí hoặc giá trị cụ thể dùng để phân định ranh giới giữa trạng thái 'chấp nhận được' và 'không chấp nhận được' tại một điểm kiểm soát tới hạn (CCP).", "Là mức nhiệt độ tối đa mà thiết bị nhà máy có thể đạt được trong quá trình chế biến.", "Là số lượng điểm kiểm soát tới hạn tối đa được phép áp dụng trong một dây chuyền sản xuất thực phẩm.", "Là khoảng thời gian tối đa cho phép doanh nghiệp khắc phục sự cố khi sản phẩm bị ô nhiễm vi sinh."], 0, "Theo Nguyên tắc 3 của HACCP, ngưỡng tới hạn là tiêu chí cụ thể phân định ranh giới giữa chấp nhận được và không chấp nhận được để đảm bảo an toàn cho sản phẩm tại một CCP.", 1);
  add(2, "Trong hệ thống HACCP, việc thiết lập ngưỡng tới hạn (Critical Limit) thuộc Nguyên tắc thứ mấy và tương ứng với Bước mấy trong quy trình triển khai của Codex?", ["Nguyên tắc 1 — Bước 6", "Nguyên tắc 2 — Bước 7", "Nguyên tắc 3 — Bước 8", "Nguyên tắc 4 — Bước 9"], 2, "Thiết lập ngưỡng tới hạn (Critical Limit) là Nguyên tắc 3, tương ứng với Bước 8 trong 12 bước triển khai HACCP theo hướng dẫn của Codex.", 2);
  add(2, "Nhận định nào sau đây là ĐÚNG về quy định số lượng điểm kiểm soát tới hạn (CCP) trong một kế hoạch HACCP?", ["Luật An toàn thực phẩm bắt buộc mỗi dây chuyền phải có ít nhất 5 CCP.", "Không có quy định tối thiểu hay tối đa về số lượng CCP trong một hệ thống HACCP.", "Mỗi công đoạn trong quy trình chế biến đều bắt buộc phải là một CCP.", "Số lượng CCP càng nhiều thì chứng nhận HACCP càng có giá trị cao."], 1, "Số lượng CCP phụ thuộc vào bản chất sản phẩm và quy trình; HACCP không quy định số lượng CCP tối thiểu hay tối đa.", 2);
  add(2, "Nếu một cơ sở chế biến thực phẩm xác định nhầm các Điểm kiểm soát thông thường (CP) thành CCP, dẫn đến có quá nhiều CCP thì sẽ gây ra hậu quả gì?", ["Không thể kiểm soát được các mối nguy vi sinh vật nguy hiểm.", "Cơ quan quản lý nhà nước sẽ tước giấy phép an toàn thực phẩm ngay lập tức.", "Gây quá tải cho hệ thống giám sát và vận hành của nhà máy.", "Làm tăng nguy cơ ô nhiễm chéo trong phân xưởng sản xuất."], 2, "Quá nhiều CCP do chọn nhầm CP thông thường sẽ dẫn đến quá tải hệ thống giám sát, gây lãng phí nguồn lực và giảm hiệu quả kiểm soát thực tế.", 2);
  add(2, "Việc xác định quá ít Điểm kiểm soát tới hạn (CCP) trong kế hoạch HACCP sẽ dẫn đến rủi ro trực tiếp nào đối với sản phẩm?", ["Làm tăng chi phí kiểm nghiệm mẫu thành phẩm.", "Không kiểm soát hết các mối nguy, làm gia tăng rủi ro mất an toàn thực phẩm.", "Khiến nhà máy không thể xin cấp chứng nhận 5S và Kaizen.", "Gây kéo dài thời gian lưu kho của sản phẩm."], 1, "Quá ít CCP đồng nghĩa với việc bỏ sót điểm kiểm soát mối nguy quan trọng, dẫn đến không kiểm soát hết rủi ro an toàn thực phẩm.", 2);
  add(2, "Yêu cầu nào sau đây KHÔNG ĐÚNG đối với việc thiết lập ngưỡng tới hạn (Critical Limit) tại một CCP?", ["Phải dựa trên cơ sở khoa học, tiêu chuẩn kỹ thuật (TCVN, QCVN) hoặc quy định pháp luật.", "Có thể sử dụng các thuật ngữ định tính cảm quan như 'đủ nóng', 'khá lạnh' để linh hoạt cho công nhân.", "Phải định lượng được và đo lường bằng thiết bị hoặc kiểm nghiệm.", "Phải có khả năng giám sát liên tục hoặc định kỳ trong quá trình sản xuất."], 1, "Ngưỡng tới hạn phải rõ ràng, cụ thể, không được dùng các từ định tính mơ hồ như 'đủ nóng', 'khá lạnh' vì dễ gây hiểu sai khi vận hành.", 2);
  add(2, "Khi kết quả giám sát tại một CCP cho thấy các thông số vượt qua ngưỡng tới hạn (Critical Limit), điều này thể hiện điều gì và nhà máy phải làm gì?", ["CCP vẫn an toàn; nhà máy tiếp tục sản xuất bình thường.", "CCP bị mất kiểm soát; nhà máy bắt buộc phải thực hiện hành động khắc phục ngay lập tức.", "CCP bị quá tải; nhà máy cần chuyển CCP này thành CP thông thường.", "Hệ thống HACCP hết hiệu lực; nhà máy phải dừng toàn bộ dây chuyền trong 30 ngày."], 1, "Khi vượt ngưỡng tới hạn, CCP được xem là mất kiểm soát, sản phẩm có rủi ro mất an toàn nên bắt buộc phải tiến hành hành động khắc phục (Corrective Action).", 2);
  add(2, "Tại một nhà máy sản xuất thịt đồ hộp, kỹ sư chất lượng đề xuất thiết lập ngưỡng tới hạn cho CCP công đoạn tiệt trùng là: 'Tiệt trùng ở nhiệt độ đủ nóng trong thời gian thích hợp để diệt khuẩn'. Đánh giá nào sau đây là ĐÚNG về đề xuất này theo tiêu chuẩn HACCP?", ["Đạt yêu cầu, vì giúp công nhân linh hoạt điều chỉnh theo thực tế lô hàng.", "Đạt yêu cầu, vì đã xác định đúng mục tiêu là diệt vi khuẩn.", "Không đạt yêu cầu, vì ngưỡng tới hạn bắt buộc phải định lượng bằng thông số cụ thể (ví dụ: nhiệt độ, thời gian) chứ không được dùng từ mơ hồ.", "Không đạt yêu cầu, vì công đoạn tiệt trùng chỉ là CP thông thường chứ không thể là CCP."], 2, "Ngưỡng tới hạn phải cụ thể, định lượng được (đo bằng thiết bị) như '121°C trong 15 phút', không được dùng các cụm từ mơ hồ như 'đủ nóng' hay 'thời gian thích hợp'.", 3);
  add(2, "Tại công đoạn gia nhiệt ruột sausage của một công ty chế biến thực phẩm (đã xác định là CCP), ngưỡng tới hạn quy định là nhiệt độ tâm sản phẩm phải đạt tối thiểu 72°C trong 15 giây. Khi kiểm tra định kỳ, nhân viên QC phát hiện một lô sản phẩm chỉ đạt nhiệt độ tâm 67°C. Theo quy định quản lý chất lượng HACCP, nhóm HACCP cần xử lý tình huống này như thế nào?", ["Cho phép xuất hàng bình thường vì 67°C đã gần đạt ngưỡng 72°C.", "Sửa lại hồ sơ ngưỡng tới hạn thành 65°C cho phù hợp với thực tế sản xuất.", "Xác định CCP đã mất kiểm soát, cách ly lô sản phẩm bị ảnh hưởng và thực hiện hành động khắc phục (như gia nhiệt lại hoặc hủy bỏ).", "Hủy bỏ điểm kiểm soát tới hạn (CCP) này vì hệ thống đo lường không hiệu quả."], 2, "Khi nhiệt độ tâm chỉ đạt 67°C (vượt ngoài/chưa đạt ngưỡng tới hạn 72°C), CCP bị mất kiểm soát. Cơ sở phải thực hiện hành động khắc phục, cách ly và xử lý lô sản phẩm không đạt.", 3);
  add(1, "Trong hệ thống HACCP, CCP (Critical Control Point) được định nghĩa là gì?", ["Điểm kiểm soát quan trọng, nơi mà mất kiểm soát có thể gây ra mối nguy hiểm cho an toàn thực phẩm", "Bước trong quy trình sản xuất không ảnh hưởng đến chất lượng sản phẩm", "Mọi điểm kiểm soát trong dây chuyền sản xuất", "Các tiêu chuẩn vệ sinh môi trường"], 0, "CCP là điểm kiểm soát tới hạn, mất kiểm soát tại đây có thể gây nguy cơ an toàn thực phẩm (theo tiêu chuẩn HACCP).", 1);
  add(2, "Giới hạn vận hành (Operating Limit) trong thiết lập ngưỡng tới hạn được mô tả như thế nào?", ["Giá trị nghiêm ngặt hơn ngưỡng tới hạn, tạo vùng an toàn để điều chỉnh trước khi vi phạm", "Giá trị bằng với ngưỡng tới hạn", "Giá trị tối đa cho phép sản phẩm ra thị trường", "Giá trị tối thiểu chỉ áp dụng cho nguyên liệu đầu vào"], 0, "Operating Limit là mức nghiêm ngặt hơn ngưỡng tới hạn, giúp điều chỉnh kịp thời trước khi vượt ngưỡng thực tế.", 1);
  add(2, "Trong các nguồn sau, nguồn nào KHÔNG được sử dụng để thiết lập ngưỡng tới hạn cho CCP?", ["Kết quả thực nghiệm tại cơ sở", "Ý kiến tư vấn của chuyên gia", "Giá bán lẻ của sản phẩm", "Tiêu chuẩn Codex, ISO, FSSC 22000"], 2, "Giá bán lẻ không liên quan tới an toàn thực phẩm, không dùng để thiết lập ngưỡng tới hạn.", 1);
  add(3, "Trong 4W+1H (Who, What, When, Where, How) của hệ thống giám sát, câu hỏi nào không thuộc danh sách này?", ["Ai thực hiện đo đạc?", "Khi nào thực hiện đo đạc?", "Tại sao cần giám sát?", "Làm thế nào để ghi lại kết quả?"], 2, "4W+1H gồm Who, What, When, Where, How; “Tại sao” (Why) không nằm trong đó.", 1);
  add(4, "Trong quy trình 6 bước hành động khắc phục, bước nào liên quan đến việc \"Xác định nguyên nhân gốc rễ\"?", ["Bước 2: Đánh giá mức độ vi phạm", "Bước 3: Xác định nguyên nhân gốc rễ", "Bước 4: Thực hiện biện pháp sửa chữa", "Bước 6: Đánh giá hiệu quả"], 1, "Bước 3 của quy trình 6 bước là xác định nguyên nhân gốc rễ.", 1);
  add(2, "Một nhà máy sữa thiết lập ngưỡng tới hạn cho nhiệt độ bảo quản là 4 °C, Operating Limit là 2 °C. Khi đo được nhiệt độ 3 °C, tình trạng nào là đúng?", ["Nhiệt độ đang nằm trong Operating Limit", "Nhiệt độ vượt ngưỡng tới hạn", "Nhiệt độ nằm trong vùng an toàn (giữa Operating Limit và Critical Limit)", "Nhiệt độ không được chấp nhận và phải loại bỏ sản phẩm"], 2, "3 °C > Operating Limit (2 °C) nhưng < Critical Limit (4 °C) → nằm trong vùng an toàn, cần điều chỉnh.", 2);
  add(3, "Khi lập hồ sơ giám sát CCP, thông tin nào BẮT BUỘC phải có?", ["Ngày, giờ thực hiện, kết quả đo, chữ ký người giám sát, xác nhận của quản lý", "Tên nhân viên, vị trí máy móc, giá thành sản phẩm", "Số lượng sản phẩm đã sản xuất, thời gian nghỉ lễ", "Mã khách hàng và địa chỉ giao hàng"], 0, "Hồ sơ giám sát phải bao gồm ngày‑giờ, kết quả, chữ ký người thực hiện và xác nhận của cán bộ quản lý.", 2);
  add(4, "Khi một CCP mất kiểm soát hoặc vượt ngưỡng tới hạn, hành động nào phải thực hiện NGAY LẬP TỨC?", ["Ghi lại kết quả và báo cáo sau ngày làm việc", "Ngừng quy trình, điều chỉnh thông số và xử lý sản phẩm không phù hợp", "Tiếp tục sản xuất và kiểm tra lại vào tuần tới", "Chỉ thông báo cho bộ phận bán hàng"], 1, "Nguyên tắc 5 yêu cầu thực hiện hành động khắc phục ngay khi CCP mất kiểm soát: dừng, điều chỉnh, xử lý sản phẩm.", 2);
  add(5, "Theo Luật An toàn thực phẩm số 55/2010/QH12, việc không lập hồ sơ giám sát CCP có thể bị xử phạt như thế nào?", ["Cảnh cáo bằng văn bản", "Phạt tiền từ 10.000.000 đến 20.000.000 đồng", "Tạm ngừng hoạt động kinh doanh từ 30 ngày đến 60 ngày", "Không có hình phạt nếu doanh nghiệp tự khắc phục"], 2, "Luật ATTP quy định vi phạm nghiêm trọng (không lập hồ sơ giám sát) có thể bị tạm ngừng hoạt động từ 30‑60 ngày.", 2);
  add(2, "Sự khác nhau chính giữa \"Giới hạn vận hành\" và \"Ngưỡng tới hạn\" là gì?", ["Operating Limit nghiêm ngặt hơn, tạo vùng an toàn; Critical Limit là mức tối đa cho phép", "Operating Limit bằng mức tối đa, Critical Limit bằng mức tối thiểu", "Cả hai đều là cùng một khái niệm", "Operating Limit chỉ áp dụng cho nguyên liệu, Critical Limit chỉ cho sản phẩm cuối"], 0, "Operating Limit nghiêm ngặt hơn ngưỡng tới hạn, giúp điều chỉnh trước khi vượt mức Critical Limit.", 2);
  add(2, "Tại một nhà máy chế biến thịt, nhiệt độ lò nướng đo được 78 °C, trong khi ngưỡng tới hạn là 75 °C và Operating Limit là 70 °C. Cơ sở này phải làm gì theo quy trình HACCP?", ["Tiếp tục sản xuất vì nhiệt độ vẫn dưới Operating Limit", "Ngừng lò nướng, điều chỉnh nhiệt độ, kiểm tra sản phẩm và thực hiện hành động khắc phục ngay lập tức", "Chỉ ghi lại kết quả và báo cáo vào cuối ca làm việc", "Giảm tốc độ băng chuyền nhưng không dừng sản xuất"], 1, "Nhiệt độ 78 °C > Critical Limit 75 °C → CCP mất kiểm soát, phải ngừng, điều chỉnh, xử lý sản phẩm và thực hiện hành động khắc phục.", 3);
  add(2, "Theo quy định về xử lý sản phẩm không phù hợp trong hệ thống HACCP, hình thức 'Tiêu hủy' bắt buộc phải áp dụng trong trường hợp nào?", ["Sản phẩm có thể tái chế để đảm bảo an toàn", "Sản phẩm không thể khắc phục và gây nguy hiểm trực tiếp đến sức khỏe", "Sản phẩm không đạt chất lượng cho người nhưng an toàn cho động vật", "Sản phẩm chỉ vi phạm nhẹ về hình thức nhãn mác"], 1, "Tiêu hủy là hình thức xử lý bắt buộc khi sản phẩm không thể khắc phục được và gây nguy hiểm trực tiếp đến sức khỏe người tiêu dùng.", 1);
  add(2, "Một lô sản phẩm nước hoa quả bị phát hiện vi phạm chỉ tiêu vi sinh nhưng có thể thanh trùng lại để đảm bảo an toàn tuyệt đối theo tiêu chuẩn. Nhà máy nên lựa chọn hình thức xử lý nào?", ["Tiêu hủy toàn bộ lô hàng", "Chuyển mục đích sử dụng làm thức ăn chăn nuôi", "Tái chế / Chế biến lại", "Xuất bán bình thường và hạ giá thành"], 2, "Hình thức Tái chế / Chế biến lại được áp dụng nếu có thể đảm bảo an toàn tuyệt đối cho sản phẩm sau khi xử lý.", 3);
  add(2, "Nội dung nào sau đây KHÔNG bắt buộc phải có trong Hồ sơ hành động khắc phục sự cố tại Điểm kiểm soát tới hạn (CCP)?", ["Mô tả chi tiết sai lệch về thông số và thời điểm xảy ra", "Số lượng và mã số lô hàng bị ảnh hưởng", "Danh sách toàn bộ công nhân đang làm việc trong ca sản xuất", "Kết quả đánh giá an toàn lô hàng và chữ ký của người có trách nhiệm"], 2, "Hồ sơ hành động khắc phục chỉ cần mô tả chi tiết sai lệch, số lượng/mã lô hàng ảnh hưởng, hành động sửa chữa, kết quả đánh giá an toàn và chữ ký người có trách nhiệm. Danh sách toàn bộ công nhân trong ca không phải nội dung bắt buộc.", 2);
  add(2, "Khái niệm nào mô tả việc 'Sử dụng các phương pháp, quy trình, phép thử ngoài việc giám sát để xác nhận hệ thống HACCP (Phân tích mối nguy và kiểm soát điểm tới hạn) đang hoạt động chính xác và hiệu quả'?", ["Hành động khắc phục (Corrective Action)", "Thẩm tra (Verification) - Nguyên tắc 6", "Giám sát CCP (Monitoring)", "Phân tích mối nguy (Hazard Analysis)"], 1, "Đây là định nghĩa chuẩn của Nguyên tắc 6 (Bước 11) — Thiết lập Thủ tục Thẩm tra trong HACCP.", 1);
  add(2, "Hoạt động nào sau đây KHÔNG thuộc về thủ tục thẩm tra (Verification) trong hệ thống HACCP?", ["Hiệu chuẩn thiết bị đo lường (nhiệt kế, cân, máy dò kim loại)", "Lấy mẫu kiểm nghiệm vi sinh và làm Swab test bề mặt thiết bị", "Quan sát thao tác của nhân viên tại hiện trường và kiểm tra hồ sơ", "Ghi chép nhiệt độ của dòng sản phẩm định kỳ 15 phút/lần tại CCP"], 2, "Ghi chép nhiệt độ định kỳ tại CCP là hoạt động 'Giám sát CCP' (Monitoring), không phải là hoạt động thẩm tra (Verification).", 2);
  add(2, "Yêu cầu quan trọng nhất về nhân sự đối với người thực hiện hoạt động thẩm tra một Điểm kiểm soát tới hạn (CCP) cụ thể là gì?", ["Phải là người trực tiếp vận hành và giám sát CCP đó hàng ngày", "Phải đảm bảo tính độc lập (không phải người trực tiếp giám sát CCP đó) và có năng lực chuyên môn", "Bắt buộc phải là chuyên gia tư vấn kiểm toán từ bên ngoài doanh nghiệp", "Phải là Giám đốc điều hành của doanh nghiệp"], 1, "Người thực hiện thẩm tra phải đảm bảo tính độc lập (không thẩm tra công việc do chính mình giám sát) và có đủ năng lực chuyên môn về HACCP.", 2);
  add(2, "Tại một nhà máy chế biến thịt, Giám đốc chất lượng phân công Công nhân A - người hàng ngày chịu trách nhiệm đo nhiệt độ tại CCP lò hấp - tự tiến hành thẩm tra và phê duyệt hồ sơ giám sát CCP lò hấp của chính mình. Phân công này có phù hợp với quy định HACCP không?", ["Phù hợp, vì Công nhân A là người nắm rõ nhất tình hình hoạt động của lò hấp", "Phù hợp, vì giúp tiết kiệm nhân lực và thời gian đánh giá", "Không phù hợp, vì vi phạm nguyên tắc về tính độc lập của người thẩm tra", "Không phù hợp, vì công nhân không được phép ghi chép hồ sơ HACCP"], 2, "Phân công này vi phạm nguyên tắc thẩm tra HACCP: Người thẩm tra phải độc lập, không được là người trực tiếp giám sát CCP đó để đảm bảo tính khách quan.", 3);
  add(2, "Triết lý cốt lõi nào phản ánh tầm quan trọng của việc lưu trữ hồ sơ trong Nguyên tắc 7 (Bước 12) của HACCP?", ["An toàn là trên hết, chất lượng là hàng đầu", "Những gì không ghi lại nghĩa là chưa từng làm", "Phòng bệnh hơn chữa bệnh", "Kiểm tra sản phẩm cuối cùng là quan trọng nhất"], 1, "Nguyên tắc 7 nhấn mạnh câu trích dẫn kinh điển trong quản lý chất lượng: 'Những gì không ghi lại nghĩa là chưa từng làm' (If it isn't written down, it didn't happen).", 1);
  add(2, "Trong ca làm việc buổi sáng, nhân viên QC đã điền trước toàn bộ số liệu nhiệt độ giám sát cho cả ca buổi chiều để tiết kiệm thời gian. Hành vi này vi phạm quy tắc ghi chép hồ sơ nào?", ["Quy tắc Đơn giản, tích hợp", "Quy tắc Kịp thời (tuyệt đối không ghi trước hoặc ghi bù)", "Quy tắc Dễ truy xuất", "Quy tắc Thống nhất đơn vị"], 1, "Quy tắc 'Kịp thời' yêu cầu ghi chép ngay tại thời điểm thực hiện thao tác/đo lường, nghiêm cấm việc ghi trước (dự đoán) hoặc ghi bù sau đó.", 3);
  add(2, "Khi phát hiện có sai sót thông số trong biểu mẫu ghi chép giám sát CCP, nhân viên vận hành phải xử lý như thế nào cho đúng quy tắc trung thực của HACCP?", ["Dùng bút xóa phủ lên chỗ sai và viết lại thông số đúng", "Tẩy sạch số sai bằng gôm và viết đè số đúng lên", "Gạch một đường qua số sai, viết số đúng bên cạnh, ký tên và ghi rõ lý do", "Xé bỏ tờ biểu mẫu lỗi và chép lại tờ mới"], 2, "Quy tắc ghi chép hồ sơ quy định không được tẩy xóa hay dùng bút xóa. Khi sai phải gạch một đường ngang nét, ghi số đúng, ký tên xác nhận và ghi rõ lý do sửa.", 2);
  add(5, "Luật An toàn thực phẩm số 55/2010/QH12 được Quốc hội khóa XII thông qua vào ngày tháng năm nào và bao gồm bao nhiêu chương, điều?", ["17/06/2010 - Gồm 11 chương, 72 điều", "17/06/2010 - Gồm 10 chương, 65 điều", "20/11/2010 - Gồm 11 chương, 72 điều", "17/06/2011 - Gồm 12 chương, 80 điều"], 0, "Luật An toàn thực phẩm số 55/2010/QH12 được Quốc hội khóa XII thông qua ngày 17/06/2010, gồm 11 chương và 72 điều.", 1);
  add(5, "Theo Luật An toàn thực phẩm 2010, khái niệm 'An toàn thực phẩm' được định nghĩa như thế nào?", ["Là việc bảo đảm thực phẩm không gây hại đến sức khỏe, tính mạng con người", "Là việc thực phẩm chứa đầy đủ tất cả các vi chất dinh dưỡng cần thiết", "Là việc thực phẩm được chế biến hoàn toàn trong các phòng thí nghiệm đạt chuẩn", "Là việc thực phẩm được sản xuất để xuất khẩu ra thị trường quốc tế"], 0, "Theo Luật ATTP, An toàn thực phẩm là việc bảo đảm thực phẩm không gây hại đến sức khỏe, tính mạng con người.", 1);
  add(5, "Hoạt động xử lý ban đầu nông sản, thủy sản sau khi thu hoạch, khai thác nhằm tạo ra nguyên liệu thực phẩm được gọi là gì?", ["Sản xuất ban đầu", "Sơ chế thực phẩm", "Chế biến thực phẩm", "Kinh doanh thực phẩm"], 1, "Sơ chế thực phẩm là quá trình xử lý sản phẩm sau thu hoạch/khai thác nhằm tạo ra nguyên liệu thực phẩm tươi sống hoặc nguyên liệu cho chế biến.", 1);
  add(5, "Phân biệt cơ bản giữa 'Phụ gia thực phẩm' và 'Chất hỗ trợ chế biến' theo quy định pháp luật là gì?", ["Phụ gia được thêm vào để cải thiện tính chất thực phẩm và hiện diện trong sản phẩm; chất hỗ trợ chế biến được chủ động dùng trong quá trình chế biến và chỉ có thể còn lại dưới dạng dư lượng", "Phụ gia thực phẩm tuyệt đối không được phép xuất hiện trong sản phẩm cuối cùng", "Chất hỗ trợ chế biến bắt buộc phải ghi tên trên nhãn sản phẩm, còn phụ gia thì không", "Cả hai chất này đều bắt buộc phải biến mất hoàn toàn sau khi kết thúc quá trình sản xuất"], 0, "Phụ gia thực phẩm được thêm vào để giữ hoặc cải thiện đặc tính thực phẩm và tồn tại trong sản phẩm. Chất hỗ trợ chế biến được sử dụng trong quá trình chế biến nguyên liệu, có thể còn lại dư lượng nhưng không cố ý.", 2);
  add(5, "Nguyên tắc quản lý an toàn thực phẩm nào sau đây là ĐÚNG theo Luật An toàn thực phẩm 2010?", ["Quản lý an toàn thực phẩm phải dựa trên phân tích nguy cơ và kiểm soát trong suốt chuỗi cung cấp thực phẩm", "Chỉ thực hiện quản lý an toàn thực phẩm ở khâu phân phối và tiêu thụ sản phẩm trên thị trường", "Cơ quan quản lý chỉ tiến hành kiểm tra khi đã xảy ra sự cố ngộ độc thực phẩm nghiêm trọng", "Ủy quyền toàn bộ công tác kiểm soát chất lượng thực phẩm cho doanh nghiệp tự nguyện thực hiện"], 0, "Một trong các nguyên tắc cốt lõi của Luật ATTP là quản lý phải dựa trên phân tích nguy cơ và thực hiện quản lý trong suốt quá trình sản xuất, kinh doanh thực phẩm (quản lý theo chuỗi).", 2);
  add(5, "Theo chính sách của Nhà nước về ATTP, các hệ thống quản lý an toàn thực phẩm nào có lộ trình bắt buộc áp dụng?", ["GMP (Thực hành sản xuất tốt), GAP (Thực hành nông nghiệp tốt), GHP (Thực hành vệ sinh tốt), HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn)", "ISO 9001 (Hệ thống quản lý chất lượng) và 6 Sigma", "TQM (Quản lý chất lượng toàn diện) và Kaizen (Cải tiến liên tục)", "Chỉ bắt buộc áp dụng duy nhất hệ thống quản lý môi trường ISO 14001"], 0, "Nhà nước có chính sách bắt buộc áp dụng có lộ trình các hệ thống tiên tiến gồm GMP, GAP, GHP, HACCP và các hệ thống quản lý ATTP khác.", 2);
  add(5, "Theo Luật ATTP, 'Lô sản phẩm thực phẩm' được định nghĩa như thế nào?", ["Tập hợp một lượng xác định của một loại sản phẩm cùng tên, chất lượng, nguyên liệu, thời hạn sử dụng và cùng được sản xuất tại một cơ sở", "Toàn bộ sản phẩm thực phẩm được sản xuất trong cùng một năm của doanh nghiệp", "Tập hợp các mặt hàng thực phẩm khác nhau được đóng chung trong một thùng hàng xuất khẩu", "Lượng thực phẩm được vận chuyển trên cùng một chuyến xe bất kể chủng loại"], 0, "Lô sản phẩm là một lượng xác định của một loại sản phẩm có cùng tên, chất lượng, nguyên liệu, hạn sử dụng và sản xuất tại cùng một cơ sở.", 1);
  add(5, "Hành vi nào dưới đây thuộc nhóm hành vi bị CẤM trong sản xuất, kinh doanh thực phẩm?", ["Sử dụng phụ gia thực phẩm nằm trong danh mục được phép sử dụng do Bộ Y tế ban hành", "Sử dụng nguyên liệu thực phẩm đã hết thời hạn sử dụng để chế biến sản phẩm", "Thực hiện công bố hợp quy cho sản phẩm trước khi lưu thông trên thị trường", "Sử dụng phương tiện vận chuyển chuyên dụng đã được vệ sinh sạch sẽ"], 1, "Sử dụng nguyên liệu đã hết thời hạn sử dụng, không rõ nguồn gốc xuất xứ hoặc không bảo đảm an toàn là hành vi bị cấm nghiêm ngặt theo Luật ATTP.", 1);
  add(5, "Trường hợp nào sau đây vi phạm quy định pháp luật về phương tiện vận chuyển thực phẩm?", ["Sử dụng xe lạnh chuyên dụng để vận chuyển thịt tươi sống", "Dùng phương tiện vận chuyển thực phẩm chung với hóa chất độc hại chưa được làm sạch", "Sử dụng thùng kín chuyên dụng để chở bánh bao đã bao gói sẵn", "Sử dụng khay inox sạch có nắp đậy để vận chuyển suất ăn sẵn"], 1, "Luật ATTP cấm sử dụng phương tiện vận chuyển gây ô nhiễm thực phẩm hoặc chở hóa chất độc hại, hàng nguy hiểm chưa được làm sạch.", 2);
  add(5, "Tại một nhà máy sản xuất đồ hộp, khi phát hiện lô hàng bị nhiễm khuẩn do sự cố tiệt trùng không đạt, Giám đốc chất lượng đã cố tình che giấu thông tin, không báo cáo cơ quan chức năng và cho sửa lại kết quả kiểm nghiệm để xuất kho bán ra thị trường. Trong tình huống này, nhà máy đã vi phạm nhóm hành vi bị cấm nào theo Luật ATTP?", ["Giả mạo kết quả kiểm nghiệm và che giấu sự cố an toàn thực phẩm", "Chỉ vi phạm quy định về quảng cáo và truyền thông sản phẩm", "Vi phạm quy định về bảo hộ thương hiệu và nhãn hiệu hàng hóa", "Không vi phạm vì sản phẩm chưa gây ra hậu quả ngộ độc thực phẩm ngay lập tức"], 0, "Hành vi làm giả kết quả kiểm nghiệm, gian lận chứng nhận và che giấu sự cố ATTP là các hành vi bị cấm nghiêm cấm theo quy định tại Luật ATTP.", 3);
  add(5, "Kiểm tra đột xuất tại bếp ăn tập thể của Công ty X, Thanh tra Sở Y tế phát hiện 2 nhân viên trực tiếp chia suất ăn đang mắc bệnh lao phổi và tiêu chảy cấp. Theo quy định pháp luật về an toàn thực phẩm, vi phạm của cơ sở này thuộc nhóm hành vi bị cấm nào?", ["Sử dụng người đang mắc bệnh truyền nhiễm tham gia trực tiếp vào quá trình sản xuất, kinh doanh thực phẩm", "Sử dụng phương tiện vận chuyển thực phẩm không bảo đảm vệ sinh", "Kinh doanh thực phẩm không rõ nguồn gốc xuất xứ", "Cung cấp thông tin quảng cáo sai sự thật về điều kiện vệ sinh"], 0, "Luật ATTP nghiêm cấm việc sử dụng người đang mắc các bệnh truyền nhiễm (theo danh mục Bộ Y tế quy định) tham gia trực tiếp vào quá trình sản xuất, chế biến, kinh doanh thực phẩm.", 3);
  add(5, "Cơ sở kinh doanh A thu mua lợn bị chết do dịch bệnh với giá rẻ, sau đó dùng hóa chất phụ gia không rõ nguồn gốc để tẩy mùi hôi tẩm ướp thành thịt tươi đem bán ra thị trường. Cơ sở A đã vi phạm những quy định cấm nào của Luật ATTP?", ["Sử dụng động vật chết do bệnh và sử dụng hóa chất, phụ gia không rõ nguồn gốc/ngoài danh mục", "Chỉ vi phạm về quy định niêm yết giá sản phẩm", "Chỉ vi phạm quy trình đóng gói và ghi nhãn sản phẩm", "Chỉ vi phạm quy định về đăng ký kinh doanh"], 0, "Cơ sở A vi phạm đồng thời 2 hành vi bị cấm trọng điểm: (1) Sử dụng thịt động vật chết do bệnh/dịch bệnh và (2) Sử dụng hóa chất, phụ gia không rõ nguồn gốc, ngoài danh mục cho phép.", 3);
  add(5, "Loại thực phẩm nào sau đây được định nghĩa là thực phẩm chưa qua chế biến, bao gồm thịt, trứng, thủy sản, rau, quả tươi và các nông sản khác?", ["Thực phẩm tươi sống", "Thực phẩm chức năng", "Thực phẩm bao gói sẵn", "Thực phẩm biến đổi gen"], 0, "Thực phẩm tươi sống là thực phẩm chưa qua chế biến bao gồm thịt, trứng, thủy sản, rau, củ, quả tươi và nông sản khác.", 1);
  add(5, "Hoạt động theo dõi quá trình hình thành và di chuyển của thực phẩm qua các giai đoạn sản xuất, chế biến và phân phối được gọi là gì?", ["Truy xuất nguồn gốc thực phẩm", "Kiểm nghiệm thực phẩm", "Phân tích nguy cơ ô nhiễm", "Công bố hợp quy thực phẩm"], 0, "Truy xuất nguồn gốc thực phẩm là việc theo dõi, nhận diện quá trình hình thành và di chuyển của thực phẩm qua các khâu sản xuất, chế biến, phân phối.", 1);
  add(5, "Mức phạt tiền tối đa đối với một hành vi vi phạm hành chính về an toàn thực phẩm có thể áp dụng lên tới bao nhiêu lần giá trị thực phẩm vi phạm?", ["3 lần giá trị thực phẩm vi phạm", "5 lần giá trị thực phẩm vi phạm", "7 lần giá trị thực phẩm vi phạm", "10 lần giá trị thực phẩm vi phạm"], 2, "Theo quy định xử lý vi phạm ATTP, mức phạt tiền tối đa đối với hành vi vi phạm có thể bằng tới 7 lần giá trị thực phẩm vi phạm (nếu mức phạt thông thường thấp hơn 7 lần).", 1);
  add(5, "Hình thức xử lý vi phạm an toàn thực phẩm bao gồm những dạng nào sau đây?", ["Xử phạt hành chính, truy cứu trách nhiệm hình sự, bồi thường thiệt hại và khắc phục hậu quả", "Chỉ xử phạt tiền hành chính và thu hồi giấy phép kinh doanh", "Chỉ bồi thường thiệt hại cho người tiêu dùng và cảnh cáo", "Truy cứu trách nhiệm hình sự đối với mọi trường hợp vi phạm"], 0, "Các hình thức xử lý vi phạm ATTP gồm: Xử phạt hành chính, truy cứu trách nhiệm hình sự, bồi thường thiệt hại và áp dụng biện pháp khắc phục hậu quả.", 1);
  add(5, "Theo quy định về phí và lệ phí an toàn thực phẩm, mức lệ phí tập huấn kiến thức an toàn thực phẩm là bao nhiêu?", ["150.000 đồng", "100.000 đồng", "50.000 đồng", "30.000 đồng"], 3, "Trong quy định lệ phí cơ bản về ATTP, đa số các lệ phí là 150.000 đồng, riêng lệ phí tập huấn kiến thức ATTP là 30.000 đồng.", 1);
  add(5, "Trong các nhóm thực phẩm, nhóm nào có mức phí thẩm xét hồ sơ công bố/đăng ký là cao nhất?", ["Thực phẩm tươi sống", "Thực phẩm chức năng (Thực phẩm bảo vệ sức khỏe)", "Thực phẩm bao gói sẵn thông thường", "Thực phẩm tăng cường vi chất"], 1, "Đối với phí thẩm xét hồ sơ, nhóm Thực phẩm chức năng yêu cầu quy trình thẩm định phức tạp nhất nên có mức phí cao nhất.", 1);
  add(5, "Đối tượng nào sau đây thuộc diện bị xử lý khi có hành vi vi phạm pháp luật về an toàn thực phẩm?", ["Chỉ có tổ chức sản xuất kinh doanh thực phẩm", "Chỉ có cá nhân trực tiếp bán hàng thực phẩm", "Tổ chức, cá nhân SXKD thực phẩm và người lợi dụng chức vụ, quyền hạn vi phạm quy định ATTP", "Chỉ người quản lý cơ sở sản xuất thực phẩm"], 2, "Đối tượng xử lý vi phạm bao gồm các tổ chức, cá nhân SXKD thực phẩm và cả người lợi dụng chức vụ, quyền hạn làm trái quy định ATTP.", 1);
  add(5, "Khi tiến hành xử phạt vi phạm hành chính về an toàn thực phẩm, cơ quan chức năng phải dựa trên nguyên tắc cốt lõi nào?", ["Dựa vào quy mô vốn đầu tư của doanh nghiệp", "Dựa vào tính chất và mức độ của hành vi vi phạm", "Dựa vào thái độ hợp tác của chủ cơ sở", "Dựa vào thời gian hoạt động của cơ sở"], 1, "Nguyên tắc xử phạt vi phạm ATTP dựa trên tính chất và mức độ vi phạm của hành vi.", 2);
  add(5, "Hành vi nào sau đây xếp vào nhóm vi phạm về 'con người và cơ sở' trong an toàn thực phẩm?", ["Sử dụng lòng đường để kinh doanh dịch vụ ăn uống", "Quảng cáo thực phẩm sai sự thật trên mạng xã hội", "Sử dụng người đang mắc bệnh truyền nhiễm tham gia trực tiếp sản xuất, kinh doanh thực phẩm", "Nhập khẩu thực phẩm không có chứng nhận hợp quy"], 2, "Nhóm vi phạm con người & cơ sở bao gồm: Người mắc bệnh truyền nhiễm tham gia SXKD và cơ sở không có Giấy chứng nhận đủ điều kiện ATTP.", 2);
  add(5, "Hành vi lấn chiếm vỉa hè, lòng đường trái phép để chế biến và kinh doanh thực phẩm thuộc nhóm vi phạm nào?", ["Nhóm thông tin", "Nhóm con người", "Nhóm cơ sở", "Nhóm môi trường"], 3, "Việc sử dụng vỉa hè, lòng đường trái phép để chế biến, kinh doanh thực phẩm xếp vào nhóm vi phạm về Môi trường.", 2);
  add(5, "Điều kiện bắt buộc riêng biệt đối với thực phẩm tươi sống khi lưu thông trên thị trường là gì?", ["Bắt buộc phải qua chiếu xạ tiệt trùng", "Phải thực hiện truy xuất nguồn gốc và có kiểm dịch (đặc biệt đối với thịt, cá)", "Phải có bằng chứng khoa học chứng minh công dụng", "Chỉ cần bao gói kín và dán nhãn hàng hóa"], 1, "Thực phẩm tươi sống lưu thông phải đảm bảo truy xuất nguồn gốc và có kiểm dịch động thực vật (đặc biệt là thịt, cá).", 2);
  add(5, "Yêu cầu bắt buộc đối với việc sử dụng phụ gia thực phẩm trong chế biến là gì?", ["Sử dụng tùy ý miễn là thực phẩm không bị hỏng", "Đúng danh mục cho phép, đúng liều lượng, có hướng dẫn sử dụng và phải công bố hợp quy", "Chỉ cần nhập khẩu từ các nước phát triển", "Chỉ cần không làm đổi màu sắc của thực phẩm"], 1, "Phụ gia thực phẩm phải thuộc danh mục cho phép, dùng đúng liều lượng, có hướng dẫn sử dụng và thực hiện công bố hợp quy.", 2);
  add(5, "Cách tính phí kiểm tra nhà nước về an toàn thực phẩm đối với thực phẩm nhập khẩu được quy định như thế nào?", ["Tính cố định 150.000 đồng/lô hàng", "Tính theo tỷ lệ 0,1% giá trị lô hàng (có quy định mức tối thiểu và tối đa)", "Tính theo số lượng container nhập khẩu", "Tính 1% tổng giá trị lô hàng nhập khẩu"], 1, "Phí kiểm tra nhập khẩu được tính theo công thức 0,1% giá trị lô hàng và có mức min - max cụ thể.", 2);
  add(5, "Tại một nhà máy chế biến giò chả, thanh tra ATTP phát hiện lô hàng trị giá 50 triệu đồng sử dụng phụ gia cấm. Theo quy định mức phạt đặc biệt (tối đa bằng 7 lần giá trị thực phẩm vi phạm), mức phạt tiền tối đa có thể áp dụng đối với vi phạm này là bao nhiêu?", ["100 triệu đồng", "200 triệu đồng", "350 triệu đồng", "500 triệu đồng"], 2, "Mức phạt tối đa áp dụng theo công thức: 7 lần x 50 triệu đồng = 350 triệu đồng (đồng thời tịch thu toàn bộ số tiền thu lợi bất hợp pháp nếu có).", 3);
  add(5, "Cơ sở kinh doanh B kinh doanh mặt hàng thực phẩm bảo vệ sức khỏe và đăng tải thông tin quảng cáo rằng sản phẩm có thể 'chữa dứt điểm bệnh ung thư'. Đoàn kiểm tra xác định đây là thông tin sai sự thật. Hành vi này thuộc nhóm vi phạm nào và phạt ra sao?", ["Thuộc nhóm vi phạm môi trường, chỉ cần đính chính thông tin", "Thuộc nhóm vi phạm thông tin (quảng cáo sai sự thật) và sẽ bị xử phạt hành chính, buộc gỡ bỏ thông tin sai lệch", "Thuộc nhóm vi phạm cơ sở, bị thu hồi Giấy chứng nhận ATTP ngay lập tức", "Thuộc nhóm vi phạm con người, bị phạt tiền 30.000 đồng"], 1, "Quảng cáo sai sự thật hoặc công bố thông tin sai lệch thuộc nhóm vi phạm thông tin, bị xử phạt vi phạm hành chính và buộc khắc phục hậu quả.", 3);
  add(5, "Công ty X nhập khẩu lô hàng thịt bò đông lạnh nhưng không trình xuất được giấy chứng nhận kiểm dịch và không truy xuất được nguồn gốc trang trại nuôi. Theo quy định pháp luật về ATTP, lô hàng này có đủ điều kiện lưu thông không và vì sao?", ["Đủ điều kiện vì là thực phẩm nhập khẩu đã đóng gói", "Đủ điều kiện nếu kiểm tra vi sinh đạt yêu cầu", "Không đủ điều kiện vì thực phẩm tươi sống bắt buộc phải có kiểm dịch và truy xuất nguồn gốc", "Đủ điều kiện nếu công ty nộp phạt lệ phí 150.000 đồng"], 2, "Theo điều kiện bảo đảm ATTP đối với thực phẩm tươi sống, sản phẩm bắt buộc phải thực hiện truy xuất nguồn gốc và có chứng nhận kiểm dịch động vật.", 3);
  add(3, "Theo quy định pháp luật về an toàn thực phẩm, tổ chức, cá nhân sản xuất, kinh doanh thực phẩm có quyền nào sau đây?", ["Tự công bố tiêu chuẩn áp dụng và lựa chọn nơi kiểm nghiệm sản phẩm", "Tự cấp Giấy chứng nhận cơ sở đủ điều kiện an toàn thực phẩm", "Thay đổi các quy chuẩn kỹ thuật quốc gia về thực phẩm theo nhu cầu", "Miễn trừ hoàn toàn trách nhiệm khi xảy ra sự cố ngộ độc thực phẩm"], 0, "Cơ sở sản xuất, kinh doanh thực phẩm có quyền tự công bố tiêu chuẩn sản phẩm, kiểm soát chất lượng nội bộ và lựa chọn phòng kiểm nghiệm theo quy định.", 1);
  add(3, "Người tiêu dùng thực phẩm KHÔNG có quyền nào sau đây theo Luật An toàn Thực phẩm?", ["Được cung cấp thông tin trung thực về an toàn thực phẩm", "Được yêu cầu bồi thường thiệt hại do sử dụng thực phẩm không an toàn", "Được khiếu nại, tố cáo các hành vi vi phạm an toàn thực phẩm", "Tự ra quyết định xử phạt hành chính đối với cơ sở vi phạm"], 3, "Người tiêu dùng có quyền được cung cấp thông tin, bảo vệ quyền lợi, khiếu nại và yêu cầu bồi thường, nhưng không có thẩm quyền ra quyết định xử phạt hành chính (thẩm quyền này thuộc cơ quan nhà nước).", 1);
  add(3, "Cơ sở sản xuất thực phẩm X muốn kiểm nghiệm chất lượng định kỳ cho sản phẩm của mình. Quyền của cơ sở X được thực hiện như thế nào?", ["Được tự do chọn phòng kiểm nghiệm đã được chỉ định hoặc thừa nhận để thực hiện", "Bắt buộc phải tự xây dựng phòng kiểm nghiệm riêng mà không được thuê ngoài", "Tự cấp phiếu kết quả kiểm nghiệm mà không cần thông qua đơn vị kiểm nghiệm", "Chỉ được kiểm nghiệm tại duy nhất một cơ quan quản lý trực tiếp"], 0, "Tổ chức, cá nhân sản xuất, kinh doanh thực phẩm có quyền lựa chọn cơ sở kiểm nghiệm đã được chỉ định hoặc thừa nhận để thực hiện kiểm nghiệm sản phẩm.", 2);
  add(3, "Ý nghĩa cốt lõi của các quy định về 'Quyền của các bên' (gồm nhà sản xuất, kinh doanh và người tiêu dùng) trong quản lý an toàn thực phẩm là gì?", ["Tối đa hóa doanh thu cho doanh nghiệp sản xuất thực phẩm", "Tạo cơ sở pháp lý để các bên có quyền tự bảo vệ mình và bảo vệ sản phẩm/quyền lợi hợp pháp", "Giảm bớt vai trò quản lý của cơ quan nhà nước trong chuỗi cung ứng", "Miễn hoàn toàn nghĩa vụ kiểm soát chất lượng cho khâu lưu thông"], 1, "Cốt lõi của việc quy định quyền của các bên là đảm bảo tổ chức, cá nhân kinh doanh và người tiêu dùng có công cụ pháp lý để bảo vệ mình, bảo vệ quyền lợi hợp pháp và chất lượng sản phẩm.", 2);
  add(3, "Anh A mua một lô sản phẩm thực phẩm đóng hộp tại siêu thị B nhưng phát hiện sản phẩm hết hạn sử dụng và bị biến chất gây ngộ độc nhẹ cho gia đình. Theo quy định pháp luật về quyền của người tiêu dùng, anh A nên xử lý thế nào là đúng nhất?", ["Yêu cầu siêu thị B bồi thường thiệt hại và phản ánh, khiếu nại đến cơ quan bảo vệ quyền lợi người tiêu dùng hoặc cơ quan quản lý ATTP", "Tự ý đưa lực lượng đến tịch thu toàn bộ hàng hóa trong siêu thị B để đền bù", "Đăng tải thông tin sai lệch, phóng đại sự việc lên mạng xã hội nhằm tống tiền siêu thị B", "Im lặng bỏ qua vì người tiêu dùng không có quyền khiếu nại đối với thực phẩm đóng hộp"], 0, "Người tiêu dùng có quyền được bảo vệ quyền lợi, yêu cầu bồi thường thiệt hại và khiếu nại, tố cáo hành vi vi phạm an toàn thực phẩm đến cơ quan có thẩm quyền theo quy định pháp luật.", 3);
  add(3, "Công ty Y nhận được kết luận xử phạt vi phạm hành chính về ATTP từ đoàn kiểm tra. Tuy nhiên, Công ty Y có đầy đủ bằng chứng chứng minh mẫu kiểm nghiệm của đoàn bị ô nhiễm chéo do thao tác lấy mẫu sai quy trình. Công ty Y có thể thực hiện quyền nào sau đây?", ["Khiếu nại hoặc khởi kiện quyết định xử phạt và yêu cầu bồi thường thiệt hại (nếu việc xử phạt sai gây thiệt hại kinh tế)", "Tự ý hủy bỏ toàn bộ hệ thống quản lý chất lượng ISO 22000 của nhà máy", "Tự xông vào phòng kiểm nghiệm của nhà nước để phá hủy chứng cứ", "Tuyên bố không tuân thủ bất kỳ luật lệ nào về an toàn thực phẩm trong tương lai"], 0, "Cơ sở sản xuất, kinh doanh có quyền khiếu nại, khởi kiện quyết định hành chính của cơ quan nhà nước và được bồi thường thiệt hại theo quy định pháp luật nếu quyết định đó sai phạm.", 3);
  add(3, "Theo quy định của Luật An toàn Thực phẩm, nhóm từ khóa nào tóm tắt cốt lõi nhất về nghĩa vụ của cơ sở SẢN XUẤT thực phẩm?", ["Không bán hàng nguy hiểm", "Chịu trách nhiệm toàn bộ sản phẩm", "Sử dụng thực phẩm đúng cách", "Chỉ kiểm tra khi có sự cố"], 1, "Cơ sở sản xuất thực phẩm chịu trách nhiệm toàn bộ về chất lượng, sự an toàn của sản phẩm do mình làm ra (bao gồm ghi nhãn, tự kiểm tra, cảnh báo, thu hồi và bồi thường).", 1);
  add(3, "Từ khóa cốt lõi phản ánh đúng nhất nghĩa vụ của cơ sở KINH DOANH thực phẩm là gì?", ["Chịu trách nhiệm toàn bộ sản phẩm", "Không bán hàng nguy hiểm", "Tuân thủ môi trường sống", "Tự kiểm nghiệm nguồn nước"], 1, "Cơ sở kinh doanh có nghĩa vụ kiểm tra nguồn gốc, bảo quản đúng quy định, dừng bán và báo cáo khi phát hiện nguy cơ; nguyên tắc cốt lõi là 'không bán hàng nguy hiểm'.", 1);
  add(3, "Nghĩa vụ nào sau đây thuộc về NGƯỜI TIÊU DÙNG trong việc bảo đảm an toàn thực phẩm?", ["Lưu giữ hồ sơ truy xuất nguồn gốc thực phẩm trong 2 năm", "Xây dựng hệ thống xử lý nước thải đạt quy chuẩn", "Sử dụng thực phẩm đúng cách, báo cáo nguy cơ mất ATTP và tuân thủ bảo vệ môi trường", "Cấp Giấy chứng nhận cơ sở đủ điều kiện an toàn thực phẩm"], 2, "Người tiêu dùng có nghĩa vụ sử dụng thực phẩm đúng hướng dẫn, kịp thời thông báo khi phát hiện nguy cơ mất an toàn thực phẩm và thực hiện các quy định về vệ sinh môi trường.", 1);
  add(3, "Mẹo nhớ nhanh 'địa điểm – nước – thiết bị – con người – hồ sơ' tóm tắt các điều kiện bắt buộc đối với đối tượng nào?", ["Thủ tục công bố sản phẩm thực phẩm bảo vệ sức khỏe", "Điều kiện cơ sở sản xuất, kinh doanh thực phẩm đạt chuẩn", "Quy trình 5S trong quản lý chất lượng văn phòng", "Các bước đánh giá nội bộ theo tiêu chuẩn ISO 9001"], 1, "Đây là ghi nhớ nhanh về 5 điều kiện cơ bản của một cơ sở sản xuất, kinh doanh thực phẩm hợp pháp (vị trí xa ô nhiễm, nước sạch, thiết bị vệ sinh, nhân viên đủ sức khỏe/kiến thức, hồ sơ truy xuất).", 1);
  add(3, "Yêu cầu nào dưới đây thuộc về điều kiện 'con người' đối với cơ sở sản xuất, kinh doanh thực phẩm?", ["Phải có bằng đại học chuyên ngành Công nghệ thực phẩm", "Nhân viên phải đủ điều kiện sức khỏe và được tập huấn kiến thức về an toàn thực phẩm", "Chủ cơ sở phải có chứng chỉ đánh giá viên trưởng ISO 22000", "Tất cả nhân viên phải biết vận hành hệ thống xử lý nước thải"], 1, "Về mặt con người, người trực tiếp sản xuất, kinh doanh thực phẩm và chủ cơ sở phải đáp ứng đủ điều kiện về sức khỏe và được xác nhận kiến thức an toàn thực phẩm theo quy định.", 2);
  add(3, "Cơ sở sản xuất thực phẩm BẮT BUỘC phải làm gì khi phát hiện sản phẩm của mình đã lưu thông trên thị trường bị lỗi hoặc không bảo đảm an toàn?", ["Giảm giá sâu để bán hết số hàng còn lại", "Thông báo cảnh báo nguy cơ, ngừng sản xuất, thu hồi sản phẩm lỗi và bồi thường thiệt hại nếu có", "Đổi tên nhãn hiệu sản phẩm và tiếp tục phân phối", "Chờ phản ánh từ người tiêu dùng mới bắt đầu xử lý"], 1, "Nhà sản xuất có nghĩa vụ cảnh báo nguy cơ, tự kiểm tra, dừng lưu thông, thu hồi sản phẩm lỗi và bồi thường thiệt hại cho người tiêu dùng nếu sản phẩm gây tổn hại.", 2);
  add(3, "Khi phát hiện một lô thực phẩm đang bán có hiện tượng biến chất, mốc hỏng, trách nhiệm pháp lý đầu tiên của cơ sở KINH DOANH là gì?", ["Lập tức ngừng bán, bảo quản riêng lô hàng, báo cáo sự cố và phối hợp với cơ quan chức năng/nhà sản xuất", "Tự kiểm nghiệm vi sinh rồi mới quyết định ngừng bán", "Rửa sạch vết mốc và hạ giá bán thanh lý", "Đổ lỗi hoàn toàn cho khách hàng không biết bảo quản"], 0, "Cơ sở kinh doanh có nghĩa vụ 'không bán hàng nguy hiểm', phải ngừng bán ngay lập tức khi phát hiện nguy cơ và báo cáo sự cố để xử lý.", 2);
  add(3, "Tại một nhà máy chế biến xúc xích, đoàn kiểm tra phát hiện nguồn nước dùng trực tiếp để rửa nguyên liệu thịt được lấy từ giếng khoan chưa qua kiểm nghiệm chỉ tiêu vi sinh và hóa lý. Nhà máy này đã vi phạm điều kiện bắt buộc nào?", ["Điều kiện về hồ sơ truy xuất nguồn gốc", "Điều kiện về nguồn nước sạch đạt quy chuẩn trong sản xuất thực phẩm", "Điều kiện về bảo vệ môi trường của người tiêu dùng", "Điều kiện về đăng ký nhãn hiệu hàng hóa"], 1, "Sử dụng nước giếng khoan chưa kiểm nghiệm vi phạm trực tiếp quy định về điều kiện 'nước': Nước sử dụng trong sản xuất thực phẩm phải đạt quy chuẩn kỹ thuật theo quy định.", 3);
  add(3, "Công ty Y sản xuất bánh kẹo bị cơ quan chức năng phát hiện sử dụng phụ gia ngoài danh mục cho phép. Lô hàng đã phân phối đến 20 đại lý bán lẻ. Theo quy định pháp luật, Công ty Y có nghĩa vụ xử lý tình huống này như thế nào?", ["Chỉ cần thông báo cho 20 đại lý ngừng bán, không cần thu hồi lô bánh kẹo đã đến tay người tiêu dùng", "Phát thông báo cảnh báo nguy cơ, tiến hành thu hồi toàn bộ lô hàng lỗi, chịu chi phí xử lý và bồi thường thiệt hại nếu gây ảnh hưởng sức khỏe người tiêu dùng", "Yêu cầu các đại lý tự chịu trách nhiệm bồi thường nếu bị phạt", "Gửi đơn xin gia hạn thời hạn lưu lưu thông lô hàng để tiêu thụ hết"], 1, "Nhà sản xuất chịu trách nhiệm toàn bộ về sản phẩm do mình làm ra. Khi có sự cố phụ gia cấm, nhà sản xuất phải cảnh báo, thu hồi triệt để, chịu chi phí tiêu hủy và bồi thường nếu có thiệt hại.", 3);
  add(3, "Đoàn kiểm tra đột xuất một siêu thị kinh doanh thực phẩm và phát hiện siêu thị bày bán sản phẩm giò chả không có tem nhãn, không có hóa đơn chứng từ chứng minh nguồn gốc xuất xứ. Đội ngũ quản lý siêu thị giải thích rằng 'Sản phẩm do hộ gia đình quen biết làm nên không cần hồ sơ'. Cách giải thích này đúng hay sai và siêu thị đã vi phạm nghĩa vụ gì?", ["Đúng, vì siêu thị được tự do lựa chọn nhà cung cấp uy tín quen biết", "Sai, vì cơ sở kinh doanh có nghĩa vụ phải kiểm tra nguồn gốc, xuất xứ sản phẩm và giữ hồ sơ truy xuất; không được kinh doanh thực phẩm không rõ nguồn gốc", "Đúng, vì hộ gia đình sản xuất không thuộc đối tượng quản lý của Luật ATTP", "Sai, nhưng vi phạm này thuộc về người tiêu dùng vì đã mua hàng không tem nhãn"], 1, "Giải thích của siêu thị là sai hoàn toàn. Cơ sở kinh doanh có nghĩa vụ bắt buộc là kiểm tra nguồn gốc thực phẩm, lưu giữ thông tin truy xuất và tuyệt đối không bán hàng không rõ nguồn gốc xuất xứ.", 3);
  add(2, "Theo quy định về an toàn thực phẩm, điều kiện nào sau đây KHÔNG bắt buộc đối với phương tiện vận chuyển thực phẩm?", ["Phương tiện không gây nhiễm bẩn thực phẩm", "Không chở chung thực phẩm với hàng hóa độc hại", "Sử dụng xe ô tô chuyên dụng đời mới nhất", "Đảm bảo các điều kiện về nhiệt độ bảo quản phù hợp với từng loại thực phẩm"], 2, "Quy định vận chuyển thực phẩm yêu cầu không gây nhiễm bẩn, không chở chung hàng độc hại và đảm bảo nhiệt độ; pháp luật không bắt buộc phải sử dụng xe đời mới nhất.", 1);
  add(2, "Mục tiêu cốt lõi của việc tuân thủ các quy định vệ sinh an toàn thực phẩm trong quá trình vận chuyển là gì?", ["Tối ưu hóa chi phí vận tải của doanh nghiệp", "Không làm thực phẩm bị hỏng hoặc biến chất trên đường đi", "Rút ngắn tối đa thời gian giao hàng cho khách", "Giảm bớt số lượng nhân công bốc xếp"], 1, "Yêu cầu cốt lõi hàng đầu trong vận chuyển thực phẩm là đảm bảo không làm thực phẩm hỏng hoặc hư hại trong suốt quá trình di chuyển.", 1);
  add(2, "Trong cơ sở chế biến thực phẩm, hai điều kiện kinh doanh quan trọng hàng đầu cần phải tuân thủ là gì?", ["Sử dụng nguyên liệu sạch và phòng chống nhiễm chéo", "Đầu tư dây chuyền nhập khẩu và thuê nhân công giá rẻ", "Sử dụng chất bảo quản liều lượng cao và bao bì đẹp mắt", "Mở rộng diện tích nhà xưởng và thuê thêm kho bãi"], 0, "Đối với hoạt động chế biến thực phẩm, quy định bắt buộc cơ sở phải đảm bảo nguyên liệu sạch và thiết kế/thao tác không gây nhiễm chéo.", 1);
  add(2, "Đối với loại hình kinh doanh dịch vụ ăn uống, yêu cầu bắt buộc đối với khu vực bếp để đảm bảo an toàn thực phẩm là gì?", ["Trang bị hệ thống máy điều hòa trung tâm", "Có khu vực/bếp riêng biệt cho thực phẩm sống và thực phẩm chín", "Chỉ được sử dụng bếp điện từ công nghiệp", "Thuê hoàn toàn đầu bếp có chứng chỉ quốc tế"], 1, "Cơ sở dịch vụ ăn uống bắt buộc phải bố trí khu vực bếp riêng giữa đồ sống và đồ chín để tránh nguy cơ nhiễm chéo vi sinh vật.", 1);
  add(2, "Yếu tố hạ tầng thiết yếu nào bắt buộc phải có tại các cơ sở kinh doanh dịch vụ ăn uống để phục vụ vệ sinh và chế biến?", ["Nguồn nước sạch đạt quy chuẩn", "Hệ thống internet tốc độ cao", "Khu vực gửi xe rộng rãi", "Bảng hiệu quảng cáo bằng đèn led"], 0, "Nước sạch là điều kiện bắt buộc tối thiểu phải có tại cơ sở dịch vụ ăn uống để sơ chế thực phẩm và vệ sinh dụng cụ.", 1);
  add(3, "Một công ty logistics sử dụng cùng một thùng xe tải để chở thịt lợn tươi sống lẫn các thùng hóa chất tẩy rửa công nghiệp. Hành vi này vi phạm quy định nào về vận chuyển thực phẩm?", ["Không tuân thủ thời gian giao hàng", "Vi phạm quy định không được chở chung thực phẩm với hàng hóa độc hại", "Chưa đăng ký nhãn hiệu vận tải", "Không duy trì độ ẩm tiêu chuẩn"], 1, "Luật An toàn thực phẩm cấm tuyệt đối việc chở chung thực phẩm với hàng hóa độc hại nguy hiểm vì có nguy cơ rò rỉ gây ô nhiễm hóa chất vào thực phẩm.", 2);
  add(3, "Tại một nhà hàng ăn uống, đoàn kiểm tra phát hiện đầu bếp sử dụng chung một chiếc thớt và dao để thái thịt gà sống, sau đó thái ngay thịt luộc chín mà không qua rửa hay tiệt trùng. Nhà hàng này đã vi phạm quy tắc an toàn thực phẩm nào?", ["Không bảo đảm điều kiện nhiệt độ vận chuyển", "Vi phạm nguyên tắc phân chia riêng biệt giữa thực phẩm sống - chín, gây nhiễm chéo", "Chưa thực hiện thủ tục tự công bố sản phẩm", "Sử dụng nguồn nước không đạt tiêu chuẩn"], 2, "Việc dùng chung dụng cụ chế biến cho thực phẩm sống và chín mà không làm sạch vi phạm nghiêm trọng quy định về phòng chống nhiễm chéo trong dịch vụ ăn uống.", 3);
  add(3, "Một đơn vị vận chuyển nhận chở 500 kg hải sản đông lạnh từ cảng về kho phân phối. Do xe tải lạnh bị hỏng hệ thống làm mát nhưng tài xế vẫn cố tình di chuyển suốt 6 tiếng dưới thời tiết nắng nóng, khiến hải sản bị phân hủy và bốc mùi. Tình huống này phản ánh sự thất bại trong việc kiểm soát yếu tố nào?", ["Kiểm soát ô nhiễm hóa chất từ nguồn nước", "Kiểm soát điều kiện nhiệt độ trong quá trình vận chuyển nhằm giữ thực phẩm không bị hỏng", "Kiểm soát quy trình phân loại nguyên liệu đầu vào", "Kiểm soát thủ tục hồ sơ công bố chất lượng"], 1, "Không duy trì được điều kiện nhiệt độ bảo quản trong suốt quá trình vận chuyển dẫn đến thực phẩm bị hư hỏng, vi phạm nguyên tắc cốt lõi của vận chuyển an toàn.", 3);
  add(2, "Theo quy định về vệ sinh an toàn thực phẩm đối với kinh doanh thức ăn đường phố, địa điểm kinh doanh phải đáp ứng yêu cầu nào sau đây về môi trường?", ["Phải cách xa nguồn ô nhiễm", "Phải nằm trong khu vực trung tâm thành phố", "Phải đặt cạnh bãi thu gom rác để tiện dọn dẹp", "Phải nằm trong phòng kín có điều hòa"], 0, "Cơ sở kinh doanh thức ăn đường phố phải lựa chọn địa điểm cách xa nguồn ô nhiễm (bãi rác, cống rãnh, khu xử lý chất thải) để tránh ô nhiễm chéo vào thực phẩm.", 1);
  add(2, "Để đảm bảo vệ sinh an toàn thực phẩm, thức ăn bày bán tại các điểm kinh doanh thức ăn đường phố bắt buộc phải có điều kiện bảo vệ nào sau đây?", ["Được bảo quản trong tủ đông âm 18 độ C", "Có che chắn chống bụi bẩn, côn trùng và động vật gây hại", "Được đóng gói trong bao bì hút chân không", "Chỉ được bày bán sau 22 giờ đêm"], 1, "Thức ăn đường phố bày bán phải có che chắn (dụng cụ, tủ kính...) nhằm bảo vệ thực phẩm khỏi bụi bẩn, côn trùng và các yếu tố gây ô nhiễm từ môi trường.", 1);
  add(3, "Người trực tiếp kinh doanh, chế biến thức ăn đường phố bắt buộc phải đáp ứng đầy đủ các điều kiện cá nhân nào dưới đây?", ["Có bằng đại học chuyên ngành thực phẩm và chứng chỉ ngoại ngữ", "Có giấy xác nhận tập huấn kiến thức an toàn thực phẩm và giấy khám sức khỏe", "Có giấy chứng nhận hành nghề y dược tư nhân", "Có thâm niên công tác từ 5 năm trở lên trong ngành dịch vụ ăn uống"], 1, "Người trực tiếp kinh doanh thức ăn đường phố phải được khám sức khỏe định kỳ và có giấy xác nhận đã được tập huấn kiến thức về an toàn thực phẩm theo quy định pháp luật.", 1);
  add(5, "Vì lý do cốt lõi nào mà hoạt động kinh doanh dịch vụ ăn uống và thức ăn đường phố đòi hỏi phải được kiểm soát chặt chẽ về an toàn thực phẩm?", ["Vì hoạt động này thu lợi nhuận cao nên cần quản lý thuế chặt chẽ", "Vì ăn uống trực tiếp tác động tới sức khỏe và tiềm ẩn rủi ro ô nhiễm cao", "Vì người bán thức ăn đường phố không có địa điểm kinh doanh cố định", "Vì pháp luật nghiêm cấm hoàn toàn việc kinh doanh ăn uống trên vỉa hè"], 1, "Ăn uống là đường lây truyền trực tiếp vi sinh vật và hóa chất độc hại vào cơ thể, chứa đựng rủi ro cao gây ngộ độc thực phẩm nên cần được kiểm soát nghiêm ngặt.", 2);
  add(3, "Khi đoàn kiểm tra liên ngành kiểm tra một cơ sở kinh doanh thức ăn đường phố, phát hiện người bán có đầy đủ giấy khám sức khỏe nhưng thực phẩm bày bán không có che chắn và nằm ngay sát cống rãnh xả thải. Cơ sở này vi phạm quy định nào?", ["Vi phạm về điều kiện địa điểm (gần nguồn ô nhiễm) và dụng cụ che chắn thực phẩm", "Không vi phạm vì người bán đã có giấy khám sức khỏe hợp lệ", "Chỉ vi phạm về đăng ký kinh doanh và nghĩa vụ nộp thuế", "Chỉ vi phạm quy định về nhãn mác hàng hóa"], 0, "Cơ sở vi phạm cả điều kiện về địa điểm (không cách xa nguồn ô nhiễm) và điều kiện về bảo vệ thực phẩm (không có che chắn), cho dù đã đáp ứng điều kiện về sức khỏe người bán.", 2);
  add(5, "Tại một điểm bán đồ ăn nhanh trên vỉa hè, chủ cơ sở đã được tập huấn kiến thức ATTP nhưng lại đặt bàn chế biến sát mép đường giao thông nhiều bụi bẩn và không sử dụng tủ kính che chắn. Nhận định nào phản ánh đúng nhất về rủi ro và biện pháp xử lý đối với cơ sở này?", ["Rủi ro ô nhiễm vật lý và vi sinh vật cao; cần yêu cầu trang bị tủ che chắn và lùi vị trí chế biến xa nguồn bụi", "Không có rủi ro nào vì thức ăn sẽ được nấu chín ở nhiệt độ cao", "Rủi ro ô nhiễm hóa chất do xăng dầu; chỉ cần phạt tiền và cho phép tiếp tục bán như cũ", "Rủi ro thấp; chỉ cần nhắc nhở người bán đeo khẩu trang là đảm bảo tuyệt đối"], 0, "Việc đặt bàn chế biến sát đường không che chắn tạo rủi ro lớn về ô nhiễm bụi bẩn (vật lý) và vi sinh vật từ không khí. Biện pháp kiểm soát rủi ro bắt buộc là phải có che chắn và đặt xa nguồn ô nhiễm.", 3);
  add(3, "Theo quy định về quản lý an toàn thực phẩm, điều kiện bắt buộc để thực phẩm nhập khẩu được phép thông quan vào Việt Nam là gì?", ["Chỉ cần có hóa đơn thương mại và hợp đồng mua bán", "Phải thực hiện công bố hợp quy (hoặc tự công bố) và đạt kết quả kiểm tra an toàn thực phẩm", "Chỉ cần có giấy chứng nhận xuất xứ hàng hóa (C/O)", "Được miễn kiểm tra nếu hàng hóa thuộc quốc gia đã ký hiệp định thương mại tự do với Việt Nam"], 1, "Thực phẩm nhập khẩu bắt buộc phải thực hiện công bố hợp quy (hoặc thủ tục tự công bố) và phải qua kiểm tra an toàn thực phẩm, chỉ khi đạt yêu cầu mới được phép thông quan theo Luật An toàn Thực phẩm.", 1);
  add(3, "Doanh nghiệp sản xuất thực phẩm tại Việt Nam khi xuất khẩu hàng hóa ra nước ngoài phải tuân thủ điều kiện nào sau đây?", ["Chỉ cần đáp ứng các quy định về an toàn thực phẩm của Việt Nam", "Chỉ cần đáp ứng các quy định an toàn thực phẩm của nước nhập khẩu", "Phải đáp ứng quy định an toàn thực phẩm của Việt Nam và quy định của nước nhập khẩu", "Không cần tuân thủ quy định nào nếu thị trường nhập khẩu không yêu cầu"], 2, "Thực phẩm xuất khẩu phải đáp ứng các điều kiện bảo đảm an toàn thực phẩm của Việt Nam đồng thời phải tuân thủ các quy định về an toàn thực phẩm của nước nhập khẩu.", 1);
  add(3, "Nguyên tắc cốt lõi trong hoạt động quản lý nhà nước đối với thực phẩm xuất khẩu và nhập khẩu là gì?", ["Ưu tiên kiểm soát thực phẩm xuất khẩu và nới lỏng kiểm tra thực phẩm nhập khẩu", "Tất cả thực phẩm khi vào (nhập khẩu) và ra (xuất khẩu) đều phải được kiểm soát an toàn thực phẩm", "Chỉ kiểm soát thực phẩm nhập khẩu từ những vùng có nguy cơ dịch bệnh", "Miễn kiểm tra an toàn thực phẩm hoàn toàn cho các doanh nghiệp đã đạt chứng nhận ISO 22000 (Hệ thống quản lý an toàn thực phẩm)"], 1, "Cốt lõi của công tác quản lý an toàn thực phẩm đối với hoạt động ngoại thương là hàng hóa đi vào (nhập khẩu) hay đi ra (xuất khẩu) đều phải chịu sự kiểm soát chặt chẽ.", 2);
  add(3, "Doanh nghiệp A nhập khẩu một lô hàng thực phẩm bao gói sẵn từ Châu Âu về Việt Nam. Cơ quan Hải quan sẽ chỉ giải quyết thủ tục thông quan cho lô hàng khi doanh nghiệp cung cấp chứng từ nào?", ["Giấy xác nhận đăng ký kinh doanh ngành nghề thực phẩm", "Thông báo kết quả xác nhận thực phẩm đạt yêu cầu nhập khẩu do cơ quan kiểm tra nhà nước cấp", "Giấy chứng nhận hệ thống quản lý chất lượng ISO 9001 của nhà sản xuất nước ngoài", "Cam kết tự chịu trách nhiệm của người đại diện theo pháp luật của doanh nghiệp"], 1, "Thực phẩm nhập khẩu chỉ được thông quan khi có thông báo kết quả kiểm tra đạt yêu cầu an toàn thực phẩm của cơ quan kiểm tra nhà nước có thẩm quyền.", 2);
  add(3, "Công ty B tại Việt Nam chế biến thủy sản xuất khẩu sang thị trường Nhật Bản. Nhật Bản quy định mức giới hạn dư lượng hóa chất X thấp hơn so với quy chuẩn kỹ thuật của Việt Nam. Để lô hàng không bị trả về và vi phạm pháp luật, Công ty B phải áp dụng tiêu chuẩn kiểm soát nào?", ["Chỉ áp dụng theo quy chuẩn kỹ thuật quốc gia của Việt Nam vì sản phẩm sản xuất trong nước", "Chỉ áp dụng quy định của Nhật Bản và bỏ qua các quy định cơ bản về vệ sinh của Việt Nam", "Áp dụng tiêu chuẩn đáp ứng đồng thời quy định của Việt Nam và yêu cầu nghiêm ngặt hơn về dư lượng hóa chất X của Nhật Bản", "Không cần kiểm soát dư lượng hóa chất X nếu có hợp đồng bao tiêu sản phẩm"], 2, "Thực phẩm xuất khẩu phải tuân thủ pháp luật Việt Nam về ATTP và đáp ứng đầy đủ các yêu cầu/tiêu chuẩn kỹ thuật khắt khe hơn của nước nhập khẩu (Nhật Bản).", 3);
  add(3, "Tại cửa khẩu, cơ quan kiểm tra nhà nước phát hiện lô hàng thịt lợn đông lạnh nhập khẩu không đạt chỉ tiêu vi sinh vật theo quy chuẩn an toàn thực phẩm Việt Nam. Hướng xử lý bắt buộc đối với lô hàng này là gì?", ["Cho phép thông quan để doanh nghiệp mang về chế biến nhiệt kỹ trước khi bán", "Không giải quyết thông quan và buộc tái xuất, tiêu hủy hoặc xử lý theo quy định pháp luật", "Tịch thu bán đấu giá cho các cơ sở chế biến thức ăn chăn nuôi", "Phạt tiền doanh nghiệp nhập khẩu và cho phép lưu thông bình thường"], 1, "Theo nguyên tắc 'chỉ thông quan khi đạt', hàng hóa không đạt yêu cầu kiểm tra ATTP sẽ tuyệt đối không được thông quan và phải bị xử lý (tái xuất, tiêu hủy,...", 3);
  add(3, "Theo quy định, Giấy chứng nhận cơ sở đủ điều kiện an toàn thực phẩm có thời hạn hiệu lực là bao nhiêu năm?", ["1 năm", "2 năm", "3 năm", "5 năm"], 2, "Theo quy định, Giấy chứng nhận cơ sở đủ điều kiện an toàn thực phẩm có thời hạn hiệu lực là 3 năm.", 1);
  add(3, "Trước khi Giấy chứng nhận cơ sở đủ điều kiện an toàn thực phẩm hết hạn, cơ sở sản xuất, kinh doanh phải nộp hồ sơ xin cấp lại trước thời gian bao lâu?", ["1 tháng", "3 tháng", "6 tháng", "12 tháng"], 2, "Cơ sở phải tiến hành nộp hồ sơ xin cấp lại Giấy chứng nhận trước 6 tháng tính đến ngày hết hạn.", 1);
  add(3, "Đối với cơ sở sản xuất, kinh doanh thực phẩm đã áp dụng hệ thống HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn) hoặc GMP (Thực hành sản xuất tốt), tần suất kiểm tra định kỳ về an toàn thực phẩm được quy định như thế nào?", ["Không quá 1 lần/năm", "Không quá 2 lần/năm", "Không quá 3 lần/năm", "Không quá 4 lần/năm"], 1, "Đối với cơ sở đã có chứng nhận HACCP hoặc GMP, tần suất kiểm tra định kỳ tối đa là ≤ 2 lần/năm.", 2);
  add(3, "Tần suất kiểm tra định kỳ an toàn thực phẩm đối với các cơ sở sản xuất, kinh doanh thực phẩm ở điều kiện bình thường (chưa có chứng chỉ HACCP/GMP) là bao nhiêu?", ["Không quá 1 lần/năm", "Không quá 2 lần/năm", "Không quá 3 lần/năm", "Không quá 4 lần/năm"], 2, "Đối với cơ sở bình thường, tần suất kiểm tra định kỳ về an toàn thực phẩm là không quá 3 lần/năm (≤ 3 lần/năm).", 2);
  add(4, "Hoạt động phân tích nguy cơ an toàn thực phẩm bao gồm bao nhiêu trụ cột chính?", ["2 trụ cột", "3 trụ cột", "4 trụ cột", "5 trụ cột"], 1, "Phân tích nguy cơ an toàn thực phẩm gồm 3 trụ cột: Đánh giá nguy cơ, Quản lý nguy cơ và Truyền thông nguy cơ.", 1);
  add(4, "Ba trụ cột chính cấu thành hoạt động phân tích nguy cơ an toàn thực phẩm bao gồm những nội dung nào?", ["Nhận diện mối nguy - Đánh giá mối nguy - Kiểm soát mối nguy", "Đánh giá nguy cơ - Quản lý nguy cơ - Truyền thông nguy cơ", "Thanh tra thực phẩm - Xử lý vi phạm - Khắc phục sự cố", "Kiểm tra định kỳ - Giám sát ô nhiễm - Cấp chứng nhận"], 1, "3 trụ cột chính của Phân tích nguy cơ bao gồm: Đánh giá nguy cơ, Quản lý nguy cơ, và Truyền thông nguy cơ.", 1);
  add(4, "Nhóm đối tượng nào sau đây KHÔNG thuộc diện bắt buộc phải tiến hành phân tích nguy cơ an toàn thực phẩm?", ["Thực phẩm có nguy cơ gây ngộ độc cao", "Thực phẩm có lịch sử vi phạm quy chuẩn kỹ thuật nhiều", "Thực phẩm mới ra mắt thị trường đã đạt chứng nhận HACCP", "Môi trường hoặc cơ sở sản xuất có nghi ngờ bị ô nhiễm"], 2, "4 nhóm đối tượng phải phân tích nguy cơ gồm: Thực phẩm dễ gây ngộ độc cao, Thực phẩm vi phạm quy chuẩn nhiều, Môi trường/cơ sở nghi ô nhiễm, và Theo yêu cầu quản lý.", 2);
  add(4, "Trong bước xác định mối nguy thuộc hoạt động đánh giá nguy cơ, cơ quan quản lý phân loại các mối nguy thành những nhóm nào?", ["Vi sinh - Hóa học - Vật lý", "Độc tố - Kim loại nặng - Vi khuẩn", "Môi trường - Con người - Thiết bị", "Nguyên liệu - Bán thành phẩm - Thành phẩm"], 0, "Xác định mối nguy trong đánh giá nguy cơ phân loại mối nguy thành 3 nhóm: Vi sinh, Hóa học và Vật lý.", 1);
  add(3, "Công ty chế biến đồ hộp A đã đạt chứng nhận GMP (Thực hành sản xuất tốt) và Giấy chứng nhận ATTP còn hiệu lực. Trong năm hiện tại, đoàn kiểm tra liên ngành đã tiến hành kiểm tra định kỳ tại công ty 2 lần. Theo quy định pháp luật, số lần kiểm tra định kỳ tối đa còn lại của cơ quan quản lý đối với Công ty A trong năm đó là bao nhiêu?", ["0 lần (đã đạt giới hạn tối đa ≤ 2 lần/năm)", "1 lần (được kiểm tra tối đa 3 lần/năm)", "2 lần (được kiểm tra tối đa 4 lần/năm)", "Không giới hạn số lần kiểm tra định kỳ"], 0, "Cơ sở có chứng nhận GMP/HACCP chỉ chịu kiểm tra định kỳ tối đa ≤ 2 lần/năm. Công ty A đã bị kiểm tra 2 lần nên số lần kiểm tra định kỳ còn lại trong năm là 0.", 3);
  add(3, "Giấy chứng nhận cơ sở đủ điều kiện an toàn thực phẩm của Công ty thực phẩm B có ngày hết hạn là 30/12/2024. Để không bị gián đoạn hoạt động sản xuất kinh doanh do hết hạn giấy phép, thời điểm chậm nhất Công ty B phải nộp hồ sơ xin cấp lại Giấy chứng nhận là khi nào?", ["30/11/2024", "30/09/2024", "30/06/2024", "30/12/2023"], 2, "Do quy định phải xin cấp lại trước 6 tháng so với ngày hết hạn, công ty phải nộp hồ sơ chậm nhất vào ngày 30/06/2024.", 3);
  add(4, "Khi thực hiện đánh giá nguy cơ an toàn thực phẩm đối với một lô hàng thực phẩm nhập khẩu, nội dung đánh giá trọng tâm bao gồm những yếu tố nào?", ["Xác định mối nguy (vi sinh, hóa học, vật lý) và đánh giá mức độ + phạm vi ảnh hưởng tới sức khỏe", "Định giá lô hàng và tính toán mức thuế nhập khẩu áp dụng", "Kiểm tra năng lực tài chính và đăng ký kinh doanh của doanh nghiệp nhập khẩu", "Đánh giá quy mô nhà xưởng và chi phí vận chuyển lô hàng"], 0, "Đánh giá nguy cơ gồm: Xác định mối nguy (Vi sinh - Hóa học - Vật lý) và Đánh giá mức độ ảnh hưởng + phạm vi ảnh hưởng tới sức khỏe con người.", 2);
  add(2, "Quản lý nguy cơ ô nhiễm thực phẩm trong suốt chuỗi cung ứng từ sản xuất, kinh doanh đến dịch vụ ăn uống được thực hiện theo nguyên tắc cơ bản nào của Luật An toàn thực phẩm?", ["A. Quản lý toàn bộ vòng đời sản phẩm từ thiết kế đến tiêu hủy", "B. Quản lý an toàn thực phẩm phải được thực hiện trong suốt quá trình sản xuất, kinh doanh trên cơ sở phân tích nguy cơ", "C. Chỉ kiểm tra chất lượng sản phẩm cuối cùng trước khi đưa ra lưu thông", "D. Tự do lưu thông thực phẩm và chỉ kiểm tra khi có sự cố ngộ độc xảy ra"], 1, "Theo Luật An toàn thực phẩm 2010, an toàn thực phẩm phải được quản lý trong suốt quá trình sản xuất, kinh doanh trên cơ sở phân tích nguy cơ đối với an toàn thực phẩm.", 1);
  add(3, "Hoạt động 'Phân tích nguy cơ' an toàn thực phẩm trong chuỗi cung ứng bao gồm ba thành phần chính nào?", ["A. Kiểm tra nhà xưởng, diễn tập PCCC và thanh tra tài chính", "B. Đánh giá nguy cơ, quản lý nguy cơ và truyền thông nguy cơ", "C. Kiểm định thiết bị, cấp chứng nhận ISO 9001 và phạt vi phạm", "D. Tiêu hủy thực phẩm hỏng, đóng cửa cơ sở và công khai danh tính"], 1, "Phân tích nguy cơ bao gồm 3 thành phần liên kết chặt chẽ: Đánh giá nguy cơ, Quản lý nguy cơ và Truyền thông nguy cơ.", 1);
  add(1, "Trong kiểm soát nguy cơ theo chuỗi thực phẩm (Sản xuất - Kinh doanh - Dịch vụ ăn uống), việc xác định Điểm kiểm soát tới hạn - CCP (Critical Control Point) là bước trọng tâm của hệ thống quản lý nào?", ["A. Hệ thống 5S (Sàng lọc, Sắp xếp, Sạch sẽ, Săn sóc, Sẵn sàng)", "B. Hệ thống HACCP (Phân tích mối nguy và điểm kiểm soát tới hạn)", "C. Tiêu chuẩn ISO 9001 (Hệ thống quản lý chất lượng)", "D. Phương pháp Kaizen (Cải tiến liên tục)"], 1, "CCP (Critical Control Point) là điểm, bước hoặc công đoạn mà tại đó kiểm soát được áp dụng để ngăn ngừa, triệt tiêu hoặc giảm thiểu mối nguy an toàn thực phẩm trong hệ thống HACCP.", 2);
  add(4, "Trong hoạt động phối hợp kiểm soát chuỗi thực phẩm, công đoạn nào sau đây thuộc khâu 'Sản xuất ban đầu' do Bộ Nông nghiệp và Phát triển nông thôn chủ trì quản lý?", ["A. Trồng trọt, chăn nuôi, thu hái, đánh bắt thủy hải sản", "B. Chế biến suất ăn công nghiệp trong khu công nghiệp", "C. Quản lý siêu thị bán lẻ và chợ đầu mối tổng hợp", "D. Kiểm tra vệ sinh nhà hàng và cơ sở dịch vụ ăn uống"], 0, "Bộ Nông nghiệp và Phát triển nông thôn chịu trách nhiệm quản lý an toàn thực phẩm đối với sản xuất ban đầu nông, lâm, thủy sản và muối.", 2);
  add(4, "Khi kiểm soát nguy cơ đối với cơ sở vừa tiến hành sản xuất chế biến, vừa kết hợp dịch vụ ăn uống, nguyên tắc phân công quản lý nhà nước theo Nghị định 15/2018/NĐ-CP được xác định như thế nào?", ["A. Mặc định do Bộ Y tế chịu trách nhiệm quản lý toàn bộ", "B. Mặc định do Bộ Công Thương chịu trách nhiệm quản lý toàn bộ", "C. Cơ quan quản lý ngành hàng có sản lượng hoặc doanh thu lớn nhất của cơ sở đó sẽ chịu trách nhiệm quản lý", "D. Do chủ cơ sở tự lựa chọn cơ quan quản lý phù hợp"], 2, "Theo Nghị định 15/2018/NĐ-CP, cơ sở kinh doanh nhiều loại sản phẩm thuộc thẩm quyền quản lý của nhiều Bộ sẽ do cơ quan quản lý sản phẩm có sản lượng/doanh thu lớn nhất trực tiếp quản lý.", 2);
  add(3, "Tại một bếp ăn tập thể của nhà máy, đoàn kiểm tra phát hiện nguyên liệu thịt lợn không có tem kiểm dịch và không chứng minh được nguồn gốc xuất xứ. Việc vi phạm này trực tiếp phá vỡ mắt xích nào trong kiểm soát an toàn thực phẩm?", ["A. Mắt xích lưu mẫu thức ăn 24 giờ tại dịch vụ ăn uống", "B. Mắt xích truy xuất nguồn gốc và kiểm soát nguy cơ từ khâu sản xuất, cung ứng nguyên liệu", "C. Mắt xích quy định nhiệt độ chế biến chín thực phẩm", "D. Mắt xích khám sức khỏe định kỳ của nhân viên bếp ăn"], 1, "Thịt không nguồn gốc, không qua kiểm dịch vi phạm nghiêm trọng quy định kiểm soát chuỗi cung ứng và truy xuất nguồn gốc từ khâu sản xuất ban đầu đến khâu dịch vụ ăn uống.", 3);
  add(5, "Một chuỗi nhà hàng dịch vụ ăn uống nhận được cảnh báo từ nhà cung cấp về việc lô hàng hải sản đông lạnh đã giao bị nhiễm vi khuẩn Vibrio parahaemolyticus vượt mức cho phép. Theo quy trình quản lý nguy cơ trong chuỗi thực phẩm, nhà hàng cần thực hiện hành động nào đầu tiên?", ["A. Tiếp tục nấu chín kỹ để bán nhằm giảm thiệt hại kinh tế", "B. Tạm dừng chế biến, niêm phong thu hồi lô hàng và thông báo cho cơ quan quản lý chức năng", "C. Đổi tên món ăn trên thực đơn và chế biến kèm gia vị cay để khử khuẩn", "D. Tự gửi mẫu đến phòng kiểm nghiệm tư nhân và chờ kết quả trong 7 ngày"], 1, "Khi phát hiện thực phẩm không an toàn hoặc có cảnh báo nguy cơ, cơ sở dịch vụ ăn uống phải ngay lập tức dừng sử dụng/chế biến, niêm phong thu hồi và báo cáo cơ quan quản lý để có biện pháp xử lý kịp thời.", 3);
  add(3, "Theo quy định pháp luật về an toàn thực phẩm, hoạt động kiểm nghiệm thực phẩm được thực hiện trong hai trường hợp nào?", ["Theo yêu cầu của tổ chức, cá nhân và Phục vụ quản lý nhà nước về an toàn thực phẩm", "Theo yêu cầu của người tiêu dùng và Khi xảy ra tranh chấp tại Tòa án", "Kiểm tra định kỳ hàng tháng và Kiểm tra đột xuất của cơ quan Công an", "Đăng ký tự nguyện của doanh nghiệp và Theo yêu cầu của đối tác nhập khẩu"], 0, "Kiểm nghiệm thực phẩm được thực hiện trong 2 trường hợp: theo yêu cầu của tổ chức, cá nhân hoặc phục vụ công tác quản lý nhà nước.", 1);
  add(3, "Hai tiêu chí bắt buộc phải đảm bảo trong hoạt động kiểm nghiệm thực phẩm là gì?", ["Nhanh chóng và Tiết kiệm chi phí", "Khách quan, chính xác và Đúng kỹ thuật", "Bí mật tuyệt đối và Linh hoạt", "Đơn giản và Dễ thực hiện"], 1, "Yêu cầu kiểm nghiệm thực phẩm gồm 2 tiêu chí cốt lõi: Khách quan - chính xác và Đúng kỹ thuật.", 1);
  add(3, "Cơ sở kiểm nghiệm thực phẩm có quyền và trách nhiệm pháp lý nào sau đây?", ["Được thu phí kiểm nghiệm và phải chịu trách nhiệm pháp lý về kết quả kiểm nghiệm", "Miễn trừ mọi trách nhiệm pháp lý nếu mẫu kiểm nghiệm do khách hàng tự gửi", "Được tự do công bố kết quả kiểm nghiệm lên truyền thông mà không cần lưu mẫu", "Chỉ chịu trách nhiệm bồi thường tài chính tối đa gấp 2 lần phí kiểm nghiệm"], 0, "Cơ sở kiểm nghiệm được thu phí theo quy định và phải chịu trách nhiệm pháp lý trước pháp luật về tính chính xác của kết quả kiểm nghiệm.", 1);
  add(3, "Khi phát hiện sự cố ngộ độc thực phẩm hoặc dấu hiệu vi phạm ATTP nghiêm trọng, tổ chức/cá nhân phải báo ngay cho cơ quan nào?", ["Cơ quan Công an cấp Bộ hoặc Viện Kiểm sát", "Cơ sở y tế gần nhất, Ủy ban nhân dân hoặc cơ quan có thẩm quyền", "Cơ quan báo chí truyền thông trung ương", "Hiệp hội bảo vệ người tiêu dùng"], 1, "Khi phát hiện dấu hiệu sự cố ATTP, phải báo ngay cho cơ sở y tế, UBND địa phương hoặc cơ quan có thẩm quyền để kịp thời xử lý.", 1);
  add(3, "Hình thức xử lý thực phẩm không an toàn bị thu hồi NÀO sau đây KHÔNG đúng với quy định?", ["Chuyển mục đích sử dụng", "Tái xuất hoặc Tiêu hủy", "Khắc phục lỗi ghi nhãn/sửa lỗi", "Đóng gói lại và bán giảm giá xả kho"], 3, "4 cách xử lý thực phẩm sau thu hồi gồm: Sửa lỗi, Chuyển mục đích sử dụng, Tái xuất, Tiêu hủy. Việc đóng gói lại để bán giảm giá thực phẩm không an toàn là vi phạm pháp luật.", 1);
  add(4, "Đối tượng thực phẩm nào sau đây BẮT BUỘC phải đăng ký nội dung quảng cáo với cơ quan nhà nước có thẩm quyền trước khi thực hiện quảng cáo?", ["Thực phẩm tươi sống nông lâm thủy sản", "Thực phẩm chức năng, thực phẩm tăng cường vi chất dinh dưỡng, nước khoáng/nước đóng chai, phụ gia thực phẩm", "Các loại gạo, ngũ cốc thô chưa qua chế biến sâu", "Bánh kẹo truyền thống sản xuất thủ công tại hộ gia đình"], 1, "Các sản phẩm phải đăng ký nội dung quảng cáo gồm: Thực phẩm chức năng, thực phẩm tăng cường vi chất, nước khoáng/nước đóng chai, phụ gia thực phẩm/chất hỗ trợ chế biến, bao bì/dụng cụ tiếp xúc trực tiếp với thực phẩm.", 1);
  add(4, "Hành vi nào sau đây bị CẤM trong hoạt động quảng cáo thực phẩm?", ["Quảng cáo đúng với nội dung đã được cơ quan thẩm quyền xác nhận", "Sử dụng hình ảnh, uy tín của bác sĩ, nhà thuốc, bệnh nhân để quảng cáo thực phẩm hoặc quảng cáo thực phẩm có tác dụng như thuốc chữa bệnh", "Ghi rõ tên và địa chỉ của nhà sản xuất trên sản phẩm quảng cáo", "Đăng ký xác nhận nội dung quảng cáo trước khi phát sóng"], 1, "Cấm sử dụng hình ảnh, uy tín của cơ sở y tế, bác sĩ, thư cảm ơn của bệnh nhân để quảng cáo thực phẩm hoặc quảng cáo gây hiểu lầm thực phẩm có tác dụng như thuốc chữa bệnh.", 2);
  add(4, "Quy định ghi nhãn đặc biệt đối với 'Thực phẩm biến đổi gen' (GMO) yêu cầu điều gì?", ["Ghi cụm từ 'Thực phẩm biến đổi gen' trên nhãn sản phẩm", "Ghi cụm từ 'Sản phẩm hoàn toàn tự nhiên'", "Không cần ghi nhãn nếu tỷ lệ GMO dưới 50%", "Ghi cụm từ 'Thực phẩm hữu cơ an toàn'"], 0, "Thực phẩm biến đổi gen bắt buộc phải ghi cụm từ 'thực phẩm biến đổi gen' trên nhãn theo quy định pháp luật.", 1);
  add(5, "Trách nhiệm quản lý nhà nước về an toàn thực phẩm được phân công theo nguyên tắc chung nào?", ["Chính phủ thống nhất quản lý; Bộ Y tế chịu trách nhiệm chính; các Bộ phối hợp; UBND địa phương thực hiện quản lý tại địa bàn", "Bộ Công Thương chịu trách nhiệm toàn bộ từ khâu nuôi trồng đến bàn ăn", "Bộ Nông nghiệp và Phát triển nông thôn chịu trách nhiệm duy nhất đối với tất cả loại thực phẩm", "Ủy ban nhân dân cấp tỉnh tự ban hành quy chuẩn riêng không cần tuân theo Chính phủ"], 0, "Nguyên tắc phân công: Chính phủ thống nhất quản lý nhà nước; Bộ Y tế chịu trách nhiệm chính trước Chính phủ; các Bộ NN&PTNT, Bộ Công Thương phối hợp; UBND các cấp quản lý tại địa phương.", 2);
  add(5, "Bộ Nông nghiệp và Phát triển nông thôn chịu trách nhiệm quản lý an toàn thực phẩm đối với nhóm sản phẩm/giai đoạn nào?", ["Rượu, bia, nước giải khát, sữa chế biến, dầu thực vật", "Nông, lâm, thủy sản, thịt, cá, rau, trứng, sữa tươi, mật ong, muối ở giai đoạn sản xuất ban đầu (nguyên liệu)", "Phụ gia thực phẩm, chất hỗ trợ chế biến, dụng cụ bao gói thực phẩm", "Thức ăn đường phố và các cơ sở dịch vụ ăn uống nhỏ lẻ"], 1, "Bộ NN&PTNT quản lý chuỗi sản xuất nông - lâm - thủy sản từ khâu nuôi trồng, thu hoạch, nguyên liệu ban đầu (thịt, cá, rau, trứng, sữa tươi, mật ong...).", 2);
  add(5, "Bộ Công Thương được giao nhiệm vụ quản lý an toàn thực phẩm đối với nhóm mặt hàng nào sau đây?", ["Thực phẩm chức năng và nước uống đóng chai", "Thịt tươi sống và thủy hải sản tươi", "Rượu, bia, nước giải khát, sữa chế biến, dầu thực vật, bột, tinh bột và công tác quản lý chợ, siêu thị", "Phụ gia thực phẩm và vi chất dinh dưỡng"], 2, "Bộ Công Thương quản lý ngành hàng chế biến tiêu dùng: rượu, bia, nước giải khát, sữa chế biến, dầu thực vật, bột/tinh bột, cùng với hệ thống lưu thông (chợ, siêu thị, phòng chống gian lận thương mại).", 2);
  add(5, "Ủy ban nhân dân các cấp có trách nhiệm quản lý trực tiếp đối với đối tượng nào trên địa bàn địa phương?", ["Các nhà máy sản xuất thực phẩm chức năng quy mô công nghiệp lớn", "Cơ sở sản xuất kinh doanh nhỏ lẻ, thức ăn đường phố, chợ địa phương", "Hoạt động cấp phép nhập khẩu thực phẩm chiếu xạ", "Ban hành Quy chuẩn kỹ thuật quốc gia (QCVN) về phụ gia thực phẩm"], 1, "UBND các cấp chịu trách nhiệm quản lý các cơ sở sản xuất kinh doanh nhỏ lẻ, thức ăn đường phố, chợ địa phương trên địa bàn phụ trách.", 2);
  add(3, "Tại một vụ ngộ độc thực phẩm tập thể ở bếp ăn công ty X làm 80 công nhân phải nhập viện, nguyên nhân được xác định do nhà cung cấp suất ăn Y sử dụng nguyên liệu hết hạn. Theo quy định pháp luật, trách nhiệm tài chính và khắc phục sự cố thuộc về ai?", ["Ngân sách nhà nước của UBND địa phương chi trả toàn bộ chi phí khám chữa bệnh", "Bộ Y tế phải bồi thường cho công nhân vì thiếu giám sát", "Cơ sở cung cấp suất ăn Y phải chi trả toàn bộ chi phí cấp cứu, điều trị và bồi thường thiệt hại cho các nạn nhân", "Công ty X phải tự chịu toàn bộ chi phí vì không tự nấu ăn"], 2, "Theo quy định xử lý sự cố ATTP, tổ chức/cá nhân gây ra ngộ độc thực phẩm phải chịu toàn bộ chi phí cấp cứu, điều trị và bồi thường thiệt hại cho người bị ngộ độc.", 3);
  add(3, "Công ty K phát hiện lô hàng 2.000 hộp sữa bột nhập khẩu có chỉ số kim loại nặng vượt mức quy định tối đa cho phép. Cơ quan chức năng ban hành quyết định thu hồi bắt buộc. Công ty K cần triển khai quy trình thu hồi và xử lý như thế nào?", ["Âm thầm thu hồi và trộn lô hàng lỗi với lô hàng mới để giảm nồng độ kim loại nặng rồi bán tiếp", "Công bố thông tin thu hồi, xác định vị trí lô hàng, thu hồi toàn bộ, chịu mọi chi phí và thực hiện biện pháp xử lý (tiêu hủy hoặc tái xuất) theo quyết định của cơ quan nhà nước", "Chỉ cần đăng thông báo xin lỗi trên website và không cần thu hồi sản phẩm đã bán ra", "Yêu cầu Đại sứ quán nước xuất khẩu chịu toàn bộ chi phí và thu hồi thay"], 1, "Khi có quyết định thu hồi bắt buộc, doanh nghiệp phải công bố thông tin, báo cáo số lượng tồn/lưu thông, tự chịu chi phí thu hồi và xử lý lô hàng (tiêu hủy, tái xuất...) dưới sự giám sát của cơ quan nhà nước.", 3);
  add(4, "Doanh nghiệp M sản xuất sản phẩm kẹo ngậm thảo dược. Trên trang quảng cáo Facebook, doanh nghiệp đăng video diễn viên đóng vai bác sĩ chuyên khoa tai mũi họng tuyên bố: 'Kẹo ngậm M chữa dứt điểm bệnh viêm họng hạt và viêm amidan mạn tính trong 3 ngày'. Dưới góc độ Luật ATTP, đánh giá nào sau đây là ĐÚNG?", ["Vi phạm pháp luật vì sử dụng hình ảnh bác sĩ và quảng cáo thực phẩm có công dụng như thuốc chữa bệnh", "Hoàn toàn hợp pháp vì kẹo thảo dược có nguồn gốc tự nhiên", "Chỉ vi phạm nếu chưa đăng ký kinh doanh với Sở Kế hoạch và Đầu tư", "Hợp pháp nếu diễn viên có giấy chứng nhận hành nghề y"], 0, "Hành vi sử dụng uy tín/hình ảnh bác sĩ và quảng cáo thực phẩm có tác dụng thay thế thuốc chữa bệnh là hành vi bị CẤM nghiêm ngặt theo quy định về quảng cáo thực phẩm.", 3);
  add(4, "Theo phân công trách nhiệm quản lý nhà nước, Ủy ban nhân dân (UBND) các cấp chịu trách nhiệm trực tiếp quản lý đối tượng nào sau đây về an toàn thực phẩm?", ["Các doanh nghiệp sản xuất thực phẩm quy mô công nghiệp xuất khẩu", "Cơ sở sản xuất, kinh doanh nhỏ lẻ, thức ăn đường phố và chợ địa phương", "Các tập đoàn bán lẻ đa quốc gia", "Các viện nghiên cứu và phòng kiểm nghiệm quốc gia"], 1, "UBND các cấp có nhiệm vụ quản lý địa phương, cơ sở nhỏ lẻ, thức ăn đường phố và chợ địa phương.", 1);
  add(4, "Thời hạn cho một cuộc thanh tra an toàn thực phẩm do cơ quan cấp Bộ tiến hành được quy định tối đa là bao nhiêu ngày (kể cả thời gian gia hạn đối với trường hợp phức tạp)?", ["Tối đa 30 ngày", "Tối đa 45 ngày", "Tối đa 70 ngày", "Tối đa 90 ngày"], 2, "Thời hạn thanh tra cấp Bộ là không quá 45 ngày, trường hợp phức tạp có thể kéo dài nhưng tối đa không quá 70 ngày.", 1);
  add(4, "Thời hạn thanh tra an toàn thực phẩm do cơ quan cấp Sở thực hiện được quy định như thế nào?", ["Không quá 30 ngày (trường hợp phức tạp gia hạn tối đa 45 ngày)", "Không quá 45 ngày (trường hợp phức tạp gia hạn tối đa 70 ngày)", "Không quá 15 ngày (trường hợp phức tạp gia hạn tối đa 30 ngày)", "Không quá 60 ngày (trường hợp phức tạp gia hạn tối đa 90 ngày)"], 1, "Thanh tra cấp Bộ, cấp Tỉnh (bao gồm các Chi cục/Sở được uỷ quyền đặc thù) có thời hạn không quá 45 ngày, tối đa không quá 70 ngày khi gia hạn.", 1);
  add(4, "Những cơ quan nào sau đây thực hiện chức năng thanh tra chuyên ngành về an toàn thực phẩm?", ["Bộ Y tế, Bộ Nông nghiệp và Phát triển nông thôn, Bộ Công Thương", "Bộ Y tế, Bộ Khoa học và Công nghệ, Bộ Công Thương", "Bộ Tài chính, Bộ Công an, Bộ Y tế", "Bộ Kế hoạch và Đầu tư, Bộ Nông nghiệp và Phát triển nông thôn, Bộ Y tế"], 0, "Thanh tra chuyên ngành ATTP (An toàn thực phẩm) thuộc thẩm quyền của 3 Bộ: Y tế, Nông nghiệp & Phát triển nông thôn, và Công Thương.", 1);
  add(4, "Nội dung nào sau đây KHÔNG thuộc phạm vi thanh tra chuyên ngành về an toàn thực phẩm?", ["Quy chuẩn ATTP và tiêu chuẩn công bố của sản phẩm", "Việc thực hiện quảng cáo và ghi nhãn thực phẩm", "Hoạt động kiểm nghiệm thực phẩm của cơ sở", "Chế độ bảo hiểm xã hội của công nhân nhà máy"], 3, "Nội dung thanh tra ATTP tập trung vào: Quy chuẩn, Tiêu chuẩn, Quảng cáo/ghi nhãn, và Kiểm nghiệm. Bảo hiểm xã hội không thuộc nội dung thanh tra ATTP.", 2);
  add(3, "Theo quy định xử phạt hành chính về an toàn thực phẩm, hình thức nào sau đây được xếp vào nhóm 'Hình thức xử phạt bổ sung'?", ["Cảnh cáo", "Phạt tiền", "Tước quyền sử dụng giấy phép hoặc tịch thu tang vật vi phạm", "Buộc tiêu hủy thực phẩm vi phạm"], 2, "Xử phạt bổ sung bao gồm tước giấy phép và tịch thu tang vật. Phạt tiền/cảnh cáo là phạt chính; tiêu hủy là biện pháp khắc phục hậu quả.", 1);
  add(3, "Hành động nào dưới đây thuộc 'Biện pháp khắc phục hậu quả' trong xử lý vi phạm hành chính về an toàn thực phẩm?", ["Tịch thu phương tiện vi phạm", "Phạt tiền theo quy định", "Tước Giấy chứng nhận cơ sở đủ điều kiện ATTP (An toàn thực phẩm)", "Thu hồi, tái xuất hoặc tiêu hủy thực phẩm vi phạm"], 3, "Biện pháp khắc phục hậu quả gồm: khôi phục tình trạng ban đầu, khắc phục ô nhiễm, thu hồi/tái xuất, tiêu hủy.", 2);
  add(2, "Nhóm vi phạm về 'Điều kiện sản xuất' trong an toàn thực phẩm bao gồm những yếu tố kiểm soát nào?", ["Giá niêm yết sản phẩm và khuyến mại", "Sức khỏe, kiến thức, thực hành của người lao động; điều kiện cơ sở; bảo quản và vận chuyển", "Bản quyền thương hiệu và kiểu dáng công nghiệp", "Hợp đồng cung ứng nguyên liệu và hoá đơn VAT"], 1, "Nhóm vi phạm điều kiện sản xuất tập trung vào người lao động (sức khỏe, kiến thức, thực hành), điều kiện cơ sở, bảo quản và vận chuyển.", 2);
  add(4, "Tại một phường X, cơ quan chức năng phát hiện một quán ăn vỉa hè sử dụng dầu ăn tái chế nhiều lần không bảo đảm vệ sinh. Theo phân công quản lý, cơ quan nào có thẩm quyền trực tiếp kiểm tra và xử lý vi phạm đối với đối tượng này?", ["Bộ Nông nghiệp và Phát triển nông thôn", "Ủy ban nhân dân (UBND) cấp địa phương (cấp phường/xã, quận/huyện)", "Bộ Công Thương", "Cục An toàn thực phẩm - Bộ Y tế"], 1, "UBND các cấp chịu trách nhiệm trực tiếp quản lý, kiểm tra và xử lý vi phạm đối với các cơ sở nhỏ lẻ, thức ăn đường phố trên địa bàn.", 3);
  add(4, "Thanh tra Sở Y tế tỉnh A tiến hành thanh tra đột xuất tại một cơ sở chế biến suất ăn công nghiệp. Cuộc thanh tra bắt đầu từ ngày 01/10 và do có nhiều tình huống phức tạp nên Trưởng đoàn muốn gia hạn. Tổng thời gian thanh tra tối đa mà Trưởng đoàn thanh tra cấp Sở được phép thực hiện là bao nhiêu ngày?", ["30 ngày", "45 ngày", "70 ngày", "90 ngày"], 1, "Thời hạn thanh tra cấp Sở là không quá 30 ngày, trường hợp phức tạp được gia hạn nhưng tổng thời hạn tối đa không quá 45 ngày.", 3);
  add(1, "Đoàn kiểm tra liên ngành phát hiện một công ty nhập khẩu lô hàng thịt đông lạnh bị ô nhiễm vi sinh vật vượt mức cho phép. Để xử lý lô hàng này nhằm đảm bảo không lây lan dịch bệnh và bảo vệ người tiêu dùng, cơ quan thẩm quyền cần áp dụng biện pháp khắc phục hậu quả nào?", ["Phạt tiền tối đa 100 triệu đồng", "Tước Giấy chứng nhận đăng ký doanh nghiệp vĩnh viễn", "Buộc thu hồi, tái xuất hoặc tiêu hủy toàn bộ lô hàng vi phạm", "Phạt cảnh cáo và cho phép tiếp tục bán với giá rẻ"], 2, "Sản phẩm không an toàn/ô nhiễm khi nhập khẩu sẽ áp dụng biện pháp khắc phục hậu quả là thu hồi, tái xuất hoặc tiêu hủy.", 3);
  add(1, "Khi tiến hành kiểm tra tại một xưởng sản xuất bánh kẹo, Đoàn kiểm tra ATTP (An toàn thực phẩm) phát hiện cơ sở sử dụng chất phụ gia ngoài danh mục cho phép. Đoàn kiểm tra có quyền thực hiện ngay hành động nào sau đây tại hiện trường?", ["Niêm phong sản phẩm vi phạm và yêu cầu dừng bán sản phẩm", "Tự ý tiêu hủy toàn bộ tài sản của xưởng ngay tại chỗ không cần lập biên bản", "Tuyên bố giải thể công ty ngay lập tức", "Thay đổi nội dung Quy chuẩn kỹ thuật quốc gia"], 0, "Quyền của đoàn kiểm tra gồm: Yêu cầu hồ sơ, lấy mẫu kiểm nghiệm, niêm phong vật chứng, ra lệnh dừng bán / dừng quảng cáo.", 3);

  add(1, "Chu trình PDCA trong quản lý chất lượng còn được gọi là gì và bao gồm các bước cơ bản nào?", ["Chu trình Deming: Hoạch định - Thực hiện - Kiểm tra - Hành động", "Chu trình Juran: Thiết kế - Sản xuất - Kiểm tra - Phân phối", "Chu trình Ishikawa: Đo lường - Phân tích - Cải tiến - Kiểm soát", "Chu trình Taylor: Chuẩn hóa - Đào tạo - Thực thi - Đánh giá"], 0, "Chu trình PDCA do Walter Shewhart đề xuất và W. Edwards Deming phát triển, bao gồm 4 bước: Plan (Hoạch định) - Do (Thực hiện) - Check (Kiểm tra) - Act (Hành động).", 1);
  add(1, "Trong chu trình PDCA, giai đoạn 'Plan' (Hoạch định) bao gồm hoạt động chính nào sau đây?", ["Thực hiện thử nghiệm quy trình mới trên diện rộng", "Thiết lập các mục tiêu, mục đích và xây dựng quy trình cần thiết để đạt kết quả", "So sánh kết quả thực tế thu được với mục tiêu đề ra", "Ban hành tiêu chuẩn chính thức áp dụng lâu dài cho toàn bộ doanh nghiệp"], 1, "Giai đoạn Plan (Hoạch định) tập trung vào việc xác định mục tiêu chất lượng, nguồn lực và lập kế hoạch/quy trình để đạt được mục tiêu đó.", 1);
  add(1, "Bước 'Do' (Thực hiện) trong chu trình PDCA đạt hiệu quả cao nhất và giảm thiểu rủi ro khi doanh nghiệp tiến hành như thế nào?", ["Thay đổi đồng loạt toàn bộ quy trình sản xuất của nhà máy ngay lập tức", "Triển khai kế hoạch thử nghiệm trên quy mô nhỏ hoặc phạm vi hẹp trước", "Bỏ qua khâu ghi chép dữ liệu để đẩy nhanh tiến độ sản xuất", "Tiến hành đánh giá nội bộ ngay khi chưa triển khai kế hoạch"], 1, "Trong giai đoạn 'Do', triển khai thử nghiệm ở quy mô nhỏ giúp kiểm chứng kế hoạch, giảm thiểu rủi ro thất bại và thu thập dữ liệu thực tế.", 2);
  add(1, "Mục đích cốt lõi của giai đoạn 'Check' (Kiểm tra) trong chu trình PDCA là gì?", ["Xử lý kỷ luật các cá nhân vi phạm quy trình chất lượng", "Thu thập dữ liệu, giám sát và so sánh kết quả thực tế với kế hoạch/mục tiêu đã đề ra", "Xây dựng lại toàn bộ mục tiêu chất lượng cho năm tiếp theo", "Đào tạo lại nhân sự về các thao tác vận hành máy móc"], 1, "Giai đoạn Check (Kiểm tra) nhằm theo dõi, đo lường các quá trình và sản phẩm so với chính sách, mục tiêu và yêu cầu đã lập ở bước Plan.", 1);
  add(1, "Doanh nghiệp phát hiện sự lệch chuẩn giữa kết quả thực tế và mục tiêu đề ra ở bước 'Check'. Hành động đúng đắn ở bước 'Act' (Hành động) là gì?", ["Thực hiện các biện pháp khắc phục, cải tiến và chuẩn hóa nếu quy trình thử nghiệm thành công", "Bỏ qua sai lệch và tiếp tục áp dụng quy trình cũ", "Hủy bỏ toàn bộ hệ thống quản lý chất lượng hiện tại", "Dừng toàn bộ hoạt động sản xuất vĩnh viễn"], 0, "Bước Act tiến hành các hành động khắc phục nguyên nhân sai lệch, đưa ra giải pháp cải tiến và chuẩn hóa quy trình tốt để áp dụng rộng rãi.", 2);
  add(1, "Bản chất vận hành liên tục của chu trình PDCA trong doanh nghiệp được thể hiện như thế nào?", ["Là một chu trình đóng, dừng lại ngay khi đạt mục tiêu chất lượng ban đầu", "Là một vòng lặp tiến lên liên tục (dạng xoắn ốc) giúp cải tiến chất lượng không ngừng", "Chỉ thực hiện một lần duy nhất khi doanh nghiệp bắt đầu thành lập", "Chỉ áp dụng khi sản phẩm xảy ra sự cố nghiêm trọng về an toàn thực phẩm"], 1, "PDCA không phải là vòng tròn khép kín dừng lại, mà là một chu trình lặp đi lặp lại liên tục theo dạng xoắn ốc nâng cao, thể hiện triết lý cải tiến liên tục (Kaizen).", 2);
  add(1, "Trong hệ thống quản lý an toàn thực phẩm (như ISO 22000), việc xác định mối nguy và thiết lập kế hoạch HACCP tương ứng với giai đoạn nào của PDCA?", ["Plan (Hoạch định)", "Do (Thực hiện)", "Check (Kiểm tra)", "Act (Hành động)"], 0, "Việc phân tích mối nguy, xác định điểm kiểm soát tới hạn (CCP) và lập kế hoạch HACCP chính là hoạt động hoạch định (Plan) hệ thống an toàn thực phẩm.", 2);
  add(1, "Nguyên tắc 'Hướng vào khách hàng' trong Quản lý chất lượng (QLCL) được hiểu đầy đủ và chính xác như thế nào?", ["Tổ chức phụ thuộc vào khách hàng, do đó cần hiểu nhu cầu hiện tại và tương lai, đáp ứng yêu cầu và phấn đấu vượt cao hơn sự mong đợi của khách hàng.", "Tổ chức chỉ cần tập trung giải quyết các khiếu nại của khách hàng sau khi sản phẩm đã lưu thông trên thị trường.", "Khách hàng luôn đúng trong mọi trường hợp, do đó phải đáp ứng mọi yêu cầu của khách hàng kể cả khi vi phạm pháp luật.", "Tổ chức chỉ cần cung cấp sản phẩm với giá rẻ nhất thị trường mà không cần quan tâm đến chất lượng."], 0, "Nguyên tắc 'Hướng vào khách hàng' khẳng định tổ chức phụ thuộc vào khách hàng, cần đáp ứng các yêu cầu hiện tại, tương lai và nỗ lực vượt qua sự mong đợi của khách hàng.", 1);
  add(1, "Trong các nguyên tắc Quản lý chất lượng, nguyên tắc 'Sự lãnh đạo' đóng vai trò gì trong tổ chức?", ["Lãnh đạo trực tiếp tham gia sản xuất và kiểm tra từng sản phẩm trên dây chuyền.", "Lãnh đạo thiết lập sự thống nhất về mục đích, hướng đi và tạo môi trường nội bộ để thu hút mọi người tham gia đạt mục tiêu chất lượng.", "Lãnh đạo chịu trách nhiệm phạt tiền nhân viên khi xảy ra sự cố chất lượng.", "Lãnh đạo chỉ phê duyệt ngân sách hàng năm và không cần quan tâm đến hệ thống quản lý chất lượng."], 1, "Nguyên tắc 'Sự lãnh đạo' đòi hỏi người lãnh đạo phải tạo ra sự thống nhất về mục đích, định hướng và môi trường thuận lợi để nhân viên cống hiến.", 1);
  add(1, "Doanh nghiệp A tổ chức quản lý bằng cách xem xét các hoạt động có liên quan như một hệ thống các quá trình tương tác lẫn nhau nhằm đạt kết quả mong muốn. Doanh nghiệp A đang áp dụng nguyên tắc QLCL nào?", ["Hướng vào khách hàng", "Tiếp cận theo quá trình", "Quyết định dựa trên chứng cứ", "Quản lý mối quan hệ"], 1, "Việc xem xét và quản lý các hoạt động đầu vào - đầu ra như các quá trình tương tác trong một hệ thống chính là nguyên tắc 'Tiếp cận theo quá trình'.", 2);
  add(1, "Nội dung nào sau đây thể hiện đúng bản chất của nguyên tắc 'Sự tham gia của mọi người'?", ["Chỉ có cán bộ quản lý chất lượng (QA/QC) mới cần tham gia vào hoạt động cải tiến chất lượng.", "Mọi người ở tất cả các cấp là bản chất của tổ chức và sự huy động đầy đủ họ giúp sử dụng năng lực vì lợi ích chung.", "Nhân viên chỉ cần làm đúng theo chỉ đạo, không cần hiểu mục tiêu chất lượng của công ty.", "Khách hàng phải trực tiếp tham gia vào dây chuyền sản xuất thực phẩm của doanh nghiệp."], 1, "Con người ở mọi cấp là nguồn lực cốt lõi; sự tham gia đầy đủ giúp tổ chức phát huy tối đa năng lực nhân sự.", 1);
  add(1, "Theo các nguyên tắc QLCL hiện đại, hoạt động 'Cải tiến' phải được tổ chức thực hiện như thế nào?", ["Là hoạt động tạm thời, chỉ thực hiện khi cơ quan quản lý kiểm tra.", "Là mục tiêu thường trực và liên tục của tổ chức.", "Chỉ thực hiện sau khi xảy ra sự cố ngộ độc thực phẩm nghiêm trọng.", "Được tiến hành định kỳ 10 năm một lần."], 1, "Cải tiến liên tục (Continuous Improvement) phải là mục tiêu thường trực của mọi tổ chức để duy trì hiệu quả và năng lực cạnh tranh.", 1);
  add(1, "Một công ty chế biến thủy sản quyết định thay đổi thông số thời gian cấp đông dựa trên kết quả phân tích dữ liệu vi sinh và cảm quan của 100 lô hàng gần nhất. Việc ra quyết định này thể hiện nguyên tắc nào?", ["Hướng vào khách hàng", "Sự lãnh đạo", "Quyết định dựa trên chứng cứ", "Quản lý mối quan hệ"], 2, "Nguyên tắc 'Quyết định dựa trên chứng cứ' yêu cầu các quyết định phải dựa trên việc phân tích, đánh giá dữ liệu và thông tin thực tế.", 2);
  add(1, "Để đảm bảo chuỗi cung ứng nông sản an toàn, nhà máy chế biến thực phẩm X chủ động hợp tác, đào tạo kỹ thuật trồng trọt an toàn và cam kết bao tiêu sản phẩm cho nông dân. Doanh nghiệp X đang thực hiện tốt nguyên tắc nào?", ["Quản lý mối quan hệ", "Tiếp cận theo quá trình", "Hướng vào khách hàng", "Quyết định dựa trên chứng cứ"], 0, "Nguyên tắc 'Quản lý mối quan hệ' nhấn mạnh việc tạo dựng và duy trì mối quan hệ cùng có lợi với các bên liên quan (đặc biệt là nhà cung ứng) để tối ưu hóa hiệu quả.", 2);
  add(1, "Chi phí chất lượng (Cost of Quality - COQ) trong quản lý chất lượng được định nghĩa đầy đủ nhất là gì?", ["Tổng chi phí phát sinh để đảm bảo sản phẩm đạt chất lượng yêu cầu cộng với chi phí do chất lượng không đạt yêu cầu gây ra.", "Toàn bộ chi phí trả lương cho bộ phận kiểm soát chất lượng (QC) và đảm bảo chất lượng (QA).", "Chi phí mua sắm thiết bị máy móc hiện đại để kiểm nghiệm thực phẩm.", "Chi phí bồi thường tổn thất khi xảy ra sự cố mất an toàn thực phẩm."], 0, "Chi phí chất lượng (COQ) bao gồm chi phí sự phù hợp (phòng ngừa, đánh giá) và chi phí sự không phù hợp (sai hỏng trong và sai hỏng ngoài).", 1);
  add(1, "Theo mô hình phân loại PAF truyền thống, chi phí chất lượng được chia thành những nhóm chính nào?", ["Chi phí cố định, chi phí biến đổi, chi phí trực tiếp, chi phí gián tiếp.", "Chi phí vật tư, chi phí nhân công, chi phí quản lý, chi phí bán hàng.", "Chi phí phòng ngừa (Prevention), chi phí đánh giá (Appraisal), chi phí sai hỏng (Failure).", "Chi phí kiểm nghiệm, chi phí tiêu hủy, chi phí đền bù, chi phí đào tạo."], 2, "Mô hình PAF phân loại chi phí chất lượng thành 3 nhóm cơ bản: Prevention (Phòng ngừa), Appraisal (Đánh giá), và Failure (Sai hỏng - gồm sai hỏng trong và ngoài).", 1);
  add(1, "Hoạt động nào sau đây tạo ra Chi phí phòng ngừa (Prevention Costs) trong chế biến thực phẩm?", ["Đào tạo kiến thức an toàn thực phẩm và HACCP cho công nhân sản xuất.", "Lấy mẫu kiểm nghiệm vi sinh vật trên sản phẩm hoàn thiện.", "Tiêu hủy lô hàng thực phẩm bị mốc trong kho.", "Xử lý khiếu nại của khách hàng về sản phẩm biến chất."], 0, "Chi phí phòng ngừa là chi phí chi ra để ngăn ngừa khuyết tật và sự cố chất lượng xảy ra ngay từ đầu, bao gồm đào tạo, lập kế hoạch chất lượng, thiết kế quy trình.", 2);
  add(1, "Chi phí kiểm định, hiệu chuẩn định kỳ các thiết bị đo lường và kiểm nghiệm thực phẩm thuộc nhóm chi phí chất lượng nào?", ["Chi phí phòng ngừa", "Chi phí đánh giá", "Chi phí sai hỏng trong", "Chi phí sai hỏng ngoài"], 1, "Chi phí đánh giá (Appraisal costs) bao gồm các chi phí kiểm tra, thử nghiệm, kiểm định thiết bị nhằm xác định mức độ phù hợp của sản phẩm với yêu cầu chất lượng.", 2);
  add(1, "Chi phí sai hỏng nội bộ (Internal Failure Costs) được phát sinh trong trường hợp nào?", ["Sản phẩm hỏng được phát hiện và xử lý trước khi giao cho khách hàng.", "Sản phẩm hỏng bị khách hàng phát hiện và trả lại doanh nghiệp.", "Doanh nghiệp chi tiền cho cơ quan chức năng đến thanh tra nhà xưởng.", "Doanh nghiệp mua bảo hiểm trách nhiệm sản phẩm thực phẩm."], 0, "Chi phí sai hỏng nội bộ phát sinh khi sản phẩm không đáp ứng tiêu chuẩn chất lượng và được phát hiện trước khi chuyển giao cho người tiêu dùng (ví dụ: loại bỏ, tái chế, gia công lại).", 2);
  add(1, "Trường hợp doanh nghiệp phải thu hồi lô hàng bánh kẹo bị nhiễm khuẩn trên thị trường và bồi thường cho người tiêu dùng thuộc loại chi phí nào?", ["Chi phí phòng ngừa", "Chi phí đánh giá", "Chi phí sai hỏng trong", "Chi phí sai hỏng ngoài"], 3, "Chi phí sai hỏng ngoài (External Failure Costs) phát sinh khi sản phẩm không đạt chất lượng được phát hiện sau khi đã cung cấp cho khách hàng hoặc lưu thông trên thị trường.", 2);
  add(1, "Theo nguyên tắc quản lý chi phí chất lượng hiện đại, việc đầu tư hợp lý vào Chi phí phòng ngừa sẽ đem lại hiệu quả gì?", ["Làm tăng tổng chi phí chất lượng của doanh nghiệp.", "Giảm đáng kể chi phí sai hỏng và giảm tổng chi phí chất lượng.", "Tăng chi phí đánh giá và kiểm tra sản phẩm.", "Không làm thay đổi chi phí sai hỏng ngoài."], 1, "Đầu tư vào phòng ngừa giúp phát hiện và chặn lỗi sớm, làm giảm mạnh các chi phí sai hỏng (vốn có chi phí sửa chữa/đền bù rất cao), từ đó giảm tổng chi phí chất lượng.", 2);
  add(1, "Loại chi phí nào sau đây được xếp vào nhóm Chi phí ẩn của chất lượng kém (Hidden Quality Costs)?", ["Chi phí đền bù sản phẩm lỗi theo hợp đồng.", "Chi phí tiêu hủy sản phẩm quá hạn sử dụng.", "Chi phí do mất uy tín thương hiệu và mất khách hàng tương lai.", "Chi phí kiểm nghiệm mẫu thực phẩm tại phòng LAB."], 2, "Chi phí ẩn là những chi phí khó đo lường chính xác trên sổ sách kế toán, như sự suy giảm uy tín thương hiệu, sự mất mát khách hàng và cơ hội kinh doanh trong tương lai.", 2);
  add(3, "Trong mô hình quản lý 5S, từ 'Seiri' (Sàng lọc) được định nghĩa là gì?", ["Phân loại và loại bỏ những vật dụng không cần thiết ra khỏi nơi làm việc", "Sắp xếp các vật dụng cần thiết theo vị trí cố định, dễ thấy, dễ lấy", "Vệ sinh máy móc, thiết bị và khu vực làm việc luôn sạch sẽ", "Duy trì các tiêu chuẩn vệ sinh và sắp xếp đã được thiết lập"], 0, "Seiri (Sàng lọc) có nghĩa là xem xét, phân loại và loại bỏ những thứ không cần thiết ra khỏi nơi làm việc để tạo không gian gọn gàng.", 1);
  add(3, "Thứ tự chính xác của 5 bước trong quy trình 5S là gì?", ["Seiri - Seiton - Seiso - Seiketsu - Shitsuke", "Seiton - Seiri - Seiso - Shitsuke - Seiketsu", "Seiso - Seiri - Seiton - Seiketsu - Shitsuke", "Seiri - Seiso - Seiton - Shitsuke - Seiketsu"], 0, "Thứ tự chuẩn của 5S theo tiếng Nhật là: Seiri (Sàng lọc) -> Seiton (Sắp xếp) -> Seiso (Sạch sẽ) -> Seiketsu (Săn sóc) -> Shitsuke (Sẵn sàng).", 1);
  add(3, "Nguyên tắc cốt lõi của bước 'Seiton' (Sắp xếp) trong 5S là gì?", ["Mọi vật dụng đều phải có vị trí quy định rõ ràng và tuân thủ tiêu chuẩn 'dễ thấy, dễ lấy, dễ trả lại'", "Thực hiện tổng vệ sinh toàn bộ xưởng sản xuất vào cuối mỗi tuần", "Loại bỏ ngay lập tức những dụng cụ không sử dụng trong vòng 6 tháng", "Tạo lập thói quen tự giác tuân thủ mọi quy định an toàn vệ sinh lao động"], 0, "Seiton (Sắp xếp) yêu cầu đặt mọi thứ đúng vị trí đã quy định, có nhãn đánh dấu để bất kỳ ai cũng có thể 'dễ thấy, dễ lấy, dễ kiểm tra, dễ trả lại'.", 2);
  add(3, "Kỹ thuật 'Thẻ đỏ' (Red Tag) là phương pháp đặc trưng được sử dụng chủ yếu trong bước nào của 5S?", ["Seiri (Sàng lọc)", "Seiton (Sắp xếp)", "Seiso (Sạch sẽ)", "Shitsuke (Sẵn sàng)"], 0, "Kỹ thuật thẻ đỏ được áp dụng trong bước Seiri (Sàng lọc) để đánh dấu các vật dụng nghi ngờ hoặc không cần thiết, giúp dễ dàng quyết định xử lý hoặc loại bỏ.", 2);
  add(3, "Hành động nào sau đây thể hiện đúng nhất bản chất của bước 'Seiso' (Sạch sẽ)?", ["Lau chùi, vệ sinh máy móc thiết bị kết hợp với việc kiểm tra nhằm phát hiện sớm các hỏng hóc, bất thường", "Quy định mã màu cho các dụng cụ vệ sinh trong nhà máy thực phẩm", "Thực hiện kiểm tra định kỳ tình trạng thực hiện 5S của các bộ phận", "Phân loại rác thải nguy hại và rác thải sinh hoạt tại nguồn"], 0, "Seiso (Sạch sẽ) không chỉ dừng lại ở việc làm sạch mà hoạt động vệ sinh còn được xem là một hình thức kiểm tra để phát hiện hỏng hóc hoặc rò rỉ của thiết bị.", 2);
  add(3, "Bước 'Seiketsu' (Săn sóc) đóng vai trò gì trong mô hình 5S?", ["Duy trì, chuẩn hóa và duy trì liên tục kết quả đạt được từ 3S đầu tiên (Sàng lọc, Sắp xếp, Sạch sẽ)", "Tổ chức các phong trào thi đua khen thưởng cho nhân viên xuất sắc", "Chuẩn bị đầy đủ nguyên vật liệu trước khi bắt đầu ca sản xuất mới", "Đào tạo kỹ năng vận hành máy móc cho công nhân mới"], 0, "Seiketsu (Săn sóc) có nghĩa là duy trì và chuẩn hóa kết quả của 3S trước đó bằng cách lập ra các quy định, chuẩn mực và lịch kiểm tra rõ ràng.", 1);
  add(3, "Bước cuối cùng 'Shitsuke' (Sẵn sàng) hướng tới mục tiêu chính nào?", ["Rèn luyện, hình thành thói quen và ý thức tự giác tuân thủ các quy định 5S của mọi thành viên", "Sẵn sàng ứng phó với các đợt thanh tra đột xuất của cơ quan quản lý an toàn thực phẩm", "Chuẩn bị sẵn sàng các phương án dự phòng khi máy móc gặp sự cố", "Sẵn sàng nguồn kinh phí đầu tư cho trang thiết bị vệ sinh hiện đại"], 0, "Shitsuke (Sẵn sàng) là tạo nên thói quen, nếp sống kỷ luật và tinh thần tự giác thực hiện nghiêm túc các quy định 5S mà không cần nhắc nhở.", 2);
  add(3, "Lợi ích trực tiếp nhất của việc thực hiện 5S đối với công tác Quản lý An toàn Thực phẩm trong nhà máy chế biến là gì?", ["Giảm thiểu nguy cơ nhiễm chéo, cải thiện điều kiện vệ sinh môi trường sản xuất", "Tăng năng suất sản xuất lên gấp đôi ngay sau khi áp dụng", "Thay thế hoàn toàn các chương trình tiên quyết GMP và SSOP", "Tự động loại bỏ hoàn toàn vi sinh vật gây hại trong thực phẩm"], 0, "5S giúp nơi làm việc sạch sẽ, ngăn nắp, hạn chế nhầm lẫn và giảm thiểu tối đa nguy cơ nhiễm chéo vi sinh vật hoặc tạp chất vào thực phẩm.", 2);
  add(3, "Kaizen là gì?", ["Quá trình cải tiến liên tục trong toàn tổ chức", "Phương pháp kiểm soát chất lượng cuối cùng", "Chiến lược giảm chi phí ngắn hạn", "Hệ thống quản lý tài chính"], 0, "Kaizen được hiểu là cải tiến liên tục, áp dụng trong mọi cấp độ của tổ chức.", 1);
  add(3, "Nguyên tắc cơ bản của Kaizen bao gồm:", ["Tập trung vào cải tiến lớn, đột phá", "Cải tiến nhỏ, liên tục, mọi người tham gia", "Chỉ cải tiến ở bộ phận sản xuất", "Chỉ thực hiện khi có chỉ đạo từ lãnh đạo cao nhất"], 1, "Kaizen đề cao cải tiến từng bước, liên tục và sự tham gia của tất cả nhân viên.", 1);
  add(3, "Việc giảm thời gian chuyển đổi máy (SMED) trong dây chuyền sản xuất là một ví dụ của Kaizen vì:", ["Đó là cải tiến nhỏ, lặp lại, giảm lãng phí thời gian", "Là một dự án đầu tư lớn", "Chỉ ảnh hưởng tới một máy duy nhất", "Yêu cầu thay đổi công nghệ toàn bộ"], 0, "SMED là cải tiến quy trình ngắn hạn, giảm thời gian chết, phù hợp với tinh thần Kaizen.", 2);
  add(3, "Công cụ nào thường được dùng trong Kaizen để xác định và loại bỏ lãng phí?", ["Biểu đồ Pareto", "Biểu đồ Gantt", "Biểu đồ Ishikawa", "Biểu đồ PERT"], 0, "Biểu đồ Pareto giúp tập trung vào những nguyên nhân gây ra phần lớn lãng phí.", 1);
  add(3, "Theo tiêu chuẩn ISO 9001, Kaizen liên quan tới yếu tố nào sau đây?", ["Đánh giá năng lực nhân viên", "Kiểm soát tài liệu", "Cải tiến liên tục của hệ thống quản lý chất lượng", "Đánh giá nhà cung cấp"], 2, "ISO 9001 yêu cầu tổ chức thực hiện cải tiến liên tục, là nội dung cốt lõi của Kaizen.", 2);
  add(3, "Cụm từ \"Kaizen\" bắt nguồn từ ngôn ngữ nào?", ["Tiếng Nhật", "Tiếng Hàn", "Tiếng Trung", "Tiếng Việt"], 0, "\"Kaizen\" là từ tiếng Nhật, nghĩa là \"cải tiến tốt hơn\".", 1);
  add(3, "Trong mô hình PDCA (Plan‑Do‑Check‑Act) của Kaizen, giai đoạn \"Check\" thực hiện nhiệm vụ gì?", ["Lập kế hoạch cải tiến", "Thực hiện giải pháp", "Đánh giá kết quả so với mục tiêu", "Tiến hành chuẩn hoá"], 2, "Giai đoạn Check kiểm tra, đánh giá kết quả thực hiện so với mục tiêu đã đề ra.", 2);
  add(3, "Khi triển khai Kaizen, việc thành lập nhóm \"Kaizen Blitz\" nhằm mục đích:", ["Thực hiện cải tiến nhanh trong thời gian ngắn", "Đánh giá năng lực quản lý", "Thực hiện kiểm tra an toàn", "Lập kế hoạch dài hạn"], 0, "Kaizen Blitz là hoạt động cải tiến nhanh, tập trung trong vài ngày đến một tuần.", 2);
  add(3, "Biểu đồ Xương cá (Ishikawa) là gì?", ["Một công cụ thống kê để kiểm soát quá trình sản xuất", "Một biểu đồ mô tả mối quan hệ nguyên nhân – kết quả", "Một biểu đồ dùng để lập kế hoạch sản xuất", "Một biểu đồ thể hiện chi phí sản xuất"], 1, "Biểu đồ Xương cá (Ishikawa) được dùng để phân tích nguyên nhân – kết quả của một vấn đề.", 1);
  add(3, "Hình dạng của biểu đồ Xương cá được mô phỏng giống gì?", ["Một cây", "Một con cá", "Một vòng tròn", "Một kim đồng hồ"], 1, "Biểu đồ có dạng như xương của một con cá, vì vậy còn gọi là biểu đồ xương cá.", 1);
  add(3, "Trong quá trình xây dựng biểu đồ Xương cá, bước đầu tiên cần thực hiện là:", ["Liệt kê các nguyên nhân phụ", "Xác định vấn đề (hiệu ứng) cần phân tích", "Vẽ các nhánh chính (5M)", "Đánh giá mức độ ảnh hưởng của từng nguyên nhân"], 1, "Trước tiên cần xác định rõ vấn đề hoặc kết quả (hiệu ứng) muốn phân tích.", 2);
  add(3, "Trong lĩnh vực An toàn Thực phẩm, nguyên nhân \"nhiệt độ không kiểm soát\" thuộc nhóm nguyên nhân nào của biểu đồ Xương cá?", ["Máy móc (Machine)", "Người (Man)", "Phương pháp (Method)", "Môi trường (Material)"], 3, "Nhiệt độ là yếu tố môi trường (Material) ảnh hưởng trực tiếp tới chất lượng thực phẩm.", 2);
  add(3, "Số lượng nhánh chính (các yếu tố lớn) thường được sử dụng trong biểu đồ Xương cá là:", ["3", "5", "7", "9"], 1, "Nhánh chính thường dựa trên mô hình 5M (Man, Machine, Method, Material, Management) hoặc 6M nếu tính môi trường.", 1);
  add(3, "Phát biểu nào sau đây mô tả đúng mối quan hệ nguyên nhân – kết quả trong biểu đồ Xương cá?", ["Nguyên nhân luôn xảy ra trước kết quả và gây ra kết quả.", "Kết quả xuất hiện trước nguyên nhân.", "Nguyên nhân và kết quả không có mối liên hệ chặt chẽ.", "Kết quả là nguyên nhân của các yếu tố khác."], 0, "Biểu đồ Xương cá phân tích các nguyên nhân (trước) dẫn tới một kết quả (sau).", 2);
  add(3, "Công cụ nào thường được kết hợp với biểu đồ Xương cá để xác định mức độ ưu tiên của các nguyên nhân?", ["Biểu đồ Pareto", "Biểu đồ Gantt", "Biểu đồ Scatter", "Biểu đồ Control"], 0, "Biểu đồ Pareto giúp xác định nguyên nhân quan trọng nhất sau khi liệt kê bằng biểu đồ Xương cá.", 2);
  add(3, "Tiêu chuẩn nào trong hệ thống quản lý an toàn thực phẩm quy định việc sử dụng các công cụ phân tích nguyên nhân, trong đó có biểu đồ Xương cá?", ["ISO 9001", "ISO 22000", "ISO 14001", "ISO 45001"], 1, "ISO 22000 (hệ thống an toàn thực phẩm) yêu cầu áp dụng các công cụ như Ishikawa để phân tích nguyên nhân gốc.", 1);
  add(3, "Nguyên tắc Pareto (80/20) được định nghĩa là gì?", ["80% kết quả đến từ 20% nguyên nhân", "90% kết quả đến từ 10% nguyên nhân", "70% kết quả đến từ 30% nguyên nhân", "60% kết quả đến từ 40% nguyên nhân"], 0, "Nguyên tắc Pareto nói rằng phần lớn (khoảng 80%) kết quả thường xuất phát từ một số ít (khoảng 20%) nguyên nhân.", 1);
  add(3, "Biểu đồ Pareto được sử dụng chủ yếu để:", ["Xác định những nguyên nhân chính gây ra vấn đề", "Đánh giá mức độ hài lòng của khách hàng", "So sánh chi phí giữa các dự án", "Phân tích xu hướng thời gian"], 0, "Biểu đồ Pareto giúp nhận diện các nguyên nhân chiếm tỷ lệ lớn nhất trong tổng số lỗi hoặc vấn đề.", 1);
  add(3, "Trong các thành phần của biểu đồ Pareto, yếu tố nào sau đây **không** phải là một phần của biểu đồ?", ["Cột tần suất (hoặc số lượng)", "Đường tích lũy phần trăm", "Biểu đồ tròn", "Trục tung thể hiện tần suất"], 2, "Biểu đồ Pareto gồm cột tần suất và đường tích lũy; biểu đồ tròn không phải là thành phần của nó.", 1);
  add(3, "Đường tích lũy trong biểu đồ Pareto thể hiện:", ["Giá trị trung bình của các nguyên nhân", "Tỷ lệ phần trăm tích lũy của tổng tần suất", "Độ lệch chuẩn của dữ liệu", "Số lượng mẫu đã kiểm tra"], 1, "Đường tích lũy cho biết phần trăm tổng tần suất đã được tích lũy khi đi qua các cột từ trái sang phải.", 1);
  add(3, "Trong một cuộc kiểm tra chất lượng, số lượng lỗi theo nguyên nhân là: A‑40, B‑25, C‑15, D‑10, E‑5, F‑5. Theo nguyên tắc 80/20, nhà quản lý nên tập trung khắc phục nguyên nhân nào?", ["A và B", "A, B và C", "C, D và E", "Tất cả các nguyên nhân"], 1, "Cộng dồn: A (40%) + B (25%) = 65%; cộng C (15%) = 80%. Vì vậy A, B và C chiếm khoảng 80% lỗi.", 2);
  add(3, "Khi vẽ biểu đồ Pareto, trục hoành (X) thường được sắp xếp các nguyên nhân theo thứ tự nào?", ["Theo thứ tự alphabet", "Theo mức độ tăng dần của tần suất", "Theo mức độ giảm dần của tần suất", "Ngẫu nhiên"], 2, "Các nguyên nhân được sắp xếp từ cao nhất đến thấp nhất về tần suất để dễ nhìn thấy những nguyên nhân quan trọng.", 1);
  add(3, "Sau khi vẽ biểu đồ Pareto, đường tích lũy cắt mức 80% ở cột thứ 4. Điều này có nghĩa gì?", ["Bốn nguyên nhân đầu tiên chiếm 80% tổng lỗi", "Bốn nguyên nhân cuối cùng chiếm 80% tổng lỗi", "80% nguyên nhân chiếm 4% lỗi", "Không có ý nghĩa thống kê"], 0, "Nếu đường tích lũy đạt 80% tại cột thứ 4, tức là bốn nguyên nhân có tần suất cao nhất góp phần 80% tổng số lỗi.", 2);
  add(3, "Áp dụng nguyên tắc 80/20 trong an toàn thực phẩm, nhà sản xuất nên tập trung kiểm tra những yếu tố nào?", ["Tất cả các yếu tố đều quan trọng như nhau", "20% yếu tố có khả năng gây nguy cơ cao nhất", "80% yếu tố gây rủi ro thấp", "Chỉ kiểm tra nguyên liệu"], 1, "Theo nguyên tắc 80/20, tập trung vào 20% yếu tố có khả năng gây nguy cơ cao sẽ giảm đa phần (khoảng 80%) rủi ro.", 2);
  add(3, "Để tạo biểu đồ Pareto bằng phần mềm thống kê, dữ liệu đầu vào cần chuẩn bị như thế nào?", ["Chỉ cần danh sách các nguyên nhân, không cần tần suất", "Cần có cột nguyên nhân và cột tần suất hoặc số lượng", "Cần có cột thời gian", "Cần có cột tỷ lệ phần trăm"], 1, "Biểu đồ Pareto yêu cầu mỗi nguyên nhân và số lượng (tần suất) tương ứng để tính tổng và phần trăm tích lũy.", 1);
  add(3, "Check sheet (bảng kiểm tra) là công cụ QC nào?", ["Biểu đồ thể hiện tần suất các giá trị đo được", "Bảng ghi lại dữ liệu định tính hoặc định lượng theo dạng có/không, đúng/sai", "Đồ thị hiển thị mối quan hệ giữa hai biến số", "Biểu đồ mô tả quy trình công việc"], 1, "Check sheet là bảng ghi dữ liệu dạng có/không, đúng/sai, thường dùng để thu thập số liệu thống kê nhanh.", 1);
  add(3, "Histogram (biểu đồ tần suất) được sử dụng để:", ["So sánh các nhóm dữ liệu theo thứ tự tăng dần", "Xác định mối quan hệ nhân quả giữa các yếu tố", "Biểu diễn phân bố tần suất của một biến số liên tục", "Phân tích quá trình kiểm soát bằng các giới hạn kiểm soát"], 2, "Histogram cho thấy phân bố tần suất của dữ liệu liên tục, giúp nhận dạng hình dạng (đối xứng, lệch).", 1);
  add(3, "Biểu đồ cột (Pareto) dựa trên nguyên tắc nào?", ["Nguyên tắc 80/20: 80% vấn đề thường do 20% nguyên nhân gây ra", "Nguyên tắc trung bình cộng: tập trung vào giá trị trung bình", "Nguyên tắc chuẩn tắc: so sánh với chuẩn quốc tế", "Nguyên tắc phân bố chuẩn: dữ liệu tuân theo phân bố chuẩn"], 0, "Biểu đồ Pareto áp dụng quy tắc 80/20, giúp xác định các nguyên nhân quan trọng nhất.", 1);
  add(3, "Lưu đồ (flowchart) thường được dùng để:", ["Phân tích sự biến thiên của quá trình theo thời gian", "Mô tả trình tự các bước trong một quy trình hoặc hệ thống", "Xác định mức độ trung bình của dữ liệu", "Đánh giá mức độ rủi ro của nguyên liệu"], 1, "Lưu đồ là sơ đồ mô tả trình tự, luồng công việc, giúp hiểu và cải tiến quy trình.", 1);
  add(3, "Biểu đồ kiểm soát (control chart) gồm các thành phần nào sau đây?", ["Trung bình di động, đường xu hướng, giới hạn chuẩn", "Trung bình quá trình, giới hạn kiểm soát trên (UCL) và dưới (LCL)", "Biểu đồ tần suất, cột Pareto, đường chuẩn", "Biểu đồ phân tán, đường hồi quy, hệ số tương quan"], 1, "Control chart có trung bình quá trình (CL) và giới hạn kiểm soát UCL/LCL để phát hiện biến động bất thường.", 1);
  add(3, "Trong một nhà máy sản xuất, để xác định nguyên nhân chính gây ra lỗi loại ‘vết trầy xước’ và ‘vết nứt’, công cụ QC nào sau đây là phù hợp nhất?", ["Histogram", "Check sheet", "Biểu đồ cột (Pareto)", "Biểu đồ kiểm soát"], 2, "Pareto chart giúp xếp hạng các loại lỗi theo tần suất, xác định nguyên nhân chiếm tỷ lệ lớn nhất.", 2);
  add(3, "Khi một điểm dữ liệu trên biểu đồ kiểm soát nằm ngoài giới hạn kiểm soát (UCL hoặc LCL), điều gì nên được thực hiện?", ["Bỏ qua vì đây là hiện tượng ngẫu nhiên", "Xác định và loại bỏ nguyên nhân đặc biệt gây ra điểm bất thường", "Thay đổi giới hạn kiểm soát để phù hợp với dữ liệu", "Tăng kích thước mẫu để giảm biến thiên"], 1, "Điểm ngoài giới hạn kiểm soát cho thấy nguyên nhân đặc biệt; cần điều tra và loại bỏ để đưa quy trình về trạng thái kiểm soát.", 2);
  add(3, "Check sheet được thiết kế sao cho:", ["Mỗi cột đại diện cho một loại lỗi và mỗi hàng cho một mẫu kiểm tra", "Mỗi hàng đại diện cho một loại lỗi và mỗi cột cho một thời gian thu thập", "Mỗi ô chứa giá trị trung bình của một biến số", "Mỗi ô hiển thị giới hạn kiểm soát"], 0, "Trong check sheet, cột thường là các mục (loại lỗi), hàng là các mẫu/đợt kiểm tra, giúp đếm số lần xuất hiện.", 2);
  add(3, "Biểu đồ tần suất (histogram) được xây dựng dựa trên nguyên tắc nào?", ["Phân chia dữ liệu thành các lớp (class intervals) và đếm tần suất mỗi lớp", "Sắp xếp dữ liệu theo thứ tự tăng dần và tính trung bình", "Vẽ các điểm dữ liệu trên trục X và Y để tìm xu hướng", "Liệt kê các nguyên nhân và tần suất xuất hiện"], 0, "Histogram chia dữ liệu thành các khoảng (class) và đếm số quan sát trong mỗi khoảng, tạo cột tần suất.", 2);
  add(4, "Đánh giá rủi ro (Risk Assessment) được định nghĩa là gì?", ["Quá trình xác định, phân tích và đánh giá mức độ rủi ro của một nguy cơ.", "Quá trình kiểm soát và giảm thiểu rủi ro đã xảy ra.", "Quá trình lập kế hoạch sản xuất thực phẩm.", "Quá trình kiểm tra chất lượng sau khi sản phẩm ra thị trường."], 0, "Đánh giá rủi ro bao gồm ba bước: nhận diện, phân tích và đánh giá mức độ rủi ro.", 1);
  add(4, "Ba bước cơ bản của quy trình đánh giá rủi ro là:", ["Nhận diện rủi ro – Phân tích rủi ro – Đánh giá rủi ro.", "Kiểm soát rủi ro – Giám sát rủi ro – Báo cáo rủi ro.", "Lập kế hoạch – Thực hiện – Kiểm tra.", "Xác định nguồn gốc – Đánh giá chất lượng – Phê duyệt sản phẩm."], 0, "Quy trình chuẩn gồm: nhận diện các nguy cơ, phân tích khả năng và mức độ nghiêm trọng, sau đó đánh giá tổng thể mức độ rủi ro.", 1);
  add(4, "Theo Codex Alimentarius, tiêu chí nào sau đây không thuộc quy trình đánh giá rủi ro?", ["Đánh giá mức độ kiểm soát.", "Nhận diện nguy cơ.", "Đánh giá mức độ phơi nhiễm.", "Đánh giá mức độ nghiêm trọng của nguy cơ."], 0, "Codex gồm 4 thành phần: nhận diện nguy cơ, đặc tính nguy cơ, đánh giá phơi nhiễm và đặc trưng rủi ro; không có bước \"đánh giá mức độ kiểm soát\".", 2);
  add(4, "Trong hệ thống HACCP, bước nào thực hiện đánh giá rủi ro?", ["Bước 1: Nhận diện các nguy cơ.", "Bước 3: Xác định các điểm kiểm soát tới hạn (CCP).", "Bước 5: Thiết lập các tiêu chuẩn giới hạn cho CCP.", "Bước 7: Xác nhận hệ thống HACCP."], 0, "Bước 1 của HACCP là nhận diện các nguy cơ (đánh giá rủi ro) để quyết định có cần thiết lập CCP hay không.", 2);
  add(4, "\"Rủi ro\" trong an toàn thực phẩm được hiểu là:", ["Xác suất xảy ra của một nguy cơ và mức độ hậu quả của nó.", "Chi phí tài chính khi có sự cố.", "Số lượng vi sinh vật trong thực phẩm.", "Thời gian bảo quản tối đa của sản phẩm."], 0, "Rủi ro là sự kết hợp của khả năng (xác suất) và hậu quả (mức độ nghiêm trọng) của một nguy cơ.", 1);
  add(4, "Phương pháp FMEA (Failure Mode and Effects Analysis) trong phân tích rủi ro được dùng để:", ["Xác định các chế độ thất bại có thể xảy ra, hậu quả và mức độ nghiêm trọng của chúng.", "Đánh giá chi phí sản xuất.", "Kiểm tra độ sạch của thiết bị.", "Xác định thời gian bảo quản của sản phẩm."], 0, "FMEA phân tích các chế độ thất bại, hậu quả và mức độ nghiêm trọng, từ đó xác định ưu tiên kiểm soát.", 2);
  add(4, "Tiêu chuẩn Việt Nam nào quy định về đánh giá rủi ro an toàn thực phẩm?", ["TCVN 8302:2015 – Hệ thống quản lý an toàn thực phẩm.", "TCVN 6188:2016 – Quản lý chất lượng thực phẩm.", "QCVN 06:2010/BYT – An toàn thực phẩm.", "QCVN 07:2020 – Kiểm soát vi sinh trong thực phẩm."], 0, "TCVN 8302:2015 quy định yêu cầu về hệ thống quản lý an toàn thực phẩm, trong đó có phần đánh giá rủi ro.", 1);
  add(4, "Nếu một nguy cơ có xác suất xảy ra cao nhưng mức độ nghiêm trọng thấp, mức độ rủi ro thường được xếp vào:", ["Rủi ro trung bình.", "Rủi ro cao.", "Rủi ro thấp.", "Không có rủi ro."], 0, "Rủi ro được tính dựa trên xác suất × mức độ nghiêm trọng; khi một trong hai yếu tố cao và yếu tố còn lại thấp, mức rủi ro thường ở mức trung bình.", 2);
  add(4, "Coliform là gì?", ["Vi khuẩn Gram‑dương, tạo bào tử", "Nhóm vi khuẩn Gram‑âm, lạc thể, có khả năng lên men lactose", "Loại nấm có spore", "Virus gây tiêu chảy"], 1, "Coliform là nhóm vi khuẩn Gram‑âm, lạc thể, có khả năng lên men lactose, dùng làm chỉ báo vệ sinh thực phẩm.", 1);
  add(4, "Theo TCVN 6020:2019, mức tối đa cho phép của Escherichia coli trong thực phẩm chế biến sẵn là:", ["0 CFU/g", "10 CFU/g", "100 CFU/g", "1000 CFU/g"], 0, "TCVN 6020 quy định E. coli không được phát hiện (0 CFU/g) trong thực phẩm chế biến sẵn.", 1);
  add(4, "Phương pháp nhanh nhất để phát hiện Salmonella trong thực phẩm là:", ["Đếm trực tiếp trên môi trường MacConkey", "PCR (phản ứng chuỗi polymerase)", "Định danh bằng kính hiển vi", "Phương pháp MPN"], 1, "PCR cho kết quả nhanh, nhạy và đặc hiệu trong việc phát hiện gen Salmonella.", 2);
  add(4, "Nếu kết quả xét nghiệm nước cho thấy coliforms = 150 CFU/100 ml, thì nước này được đánh giá:", ["An toàn", "Không đạt tiêu chuẩn vệ sinh", "Đạt tiêu chuẩn vi sinh", "Không có coliforms"], 1, "Mức coliform >100 CFU/100 ml vượt ngưỡng cho phép, nên không đạt tiêu chuẩn vệ sinh.", 2);
  add(4, "Nhiệt độ và thời gian tối thiểu của quá trình pasteurization để tiêu diệt coliforms trong sữa là:", ["63 °C trong 30 phút", "72 °C trong 15 giây", "85 °C trong 5 phút", "100 °C trong 1 phút"], 0, "Phương pháp LTLT (63 °C/30 phút) đủ để tiêu diệt coliforms mà không làm mất chất dinh dưỡng.", 2);
  add(4, "Chỉ tiêu vi sinh nào thường được dùng làm chỉ báo cho mức độ vệ sinh môi trường trong thực phẩm?", ["Staphylococcus aureus", "Coliforms", "Listeria monocytogenes", "Bacillus cereus"], 1, "Coliforms là chỉ báo tiêu chuẩn cho vệ sinh môi trường và quy trình sản xuất thực phẩm.", 1);
  add(4, "Nguyên tắc của phương pháp Most Probable Number (MPN) trong kiểm nghiệm coliforms là:", ["Đếm trực tiếp từng kháng thể", "Sử dụng chuỗi PCR để xác định DNA", "Định lượng dựa trên tỷ lệ mẫu dương tính trong các ống chứa dung dịch pha loãng", "Đếm qua kính hiển vi"], 2, "MPN ước tính số lượng vi sinh dựa trên xác suất mẫu dương tính ở các nồng độ pha loãng khác nhau.", 2);
  add(4, "Theo quy định của Luật An toàn Thực phẩm Việt Nam, mức tối đa cho phép của E. coli trong thực phẩm tươi sống (thịt, cá) là:", ["0 CFU/g", "10 CFU/g", "100 CFU/g", "1000 CFU/g"], 0, "Luật An toàn Thực phẩm quy định E. coli không được phát hiện (0 CFU/g) trong thực phẩm tươi sống.", 1);
  add(4, "Khái niệm \"truy xuất nguồn gốc\" trong an toàn thực phẩm là gì?", ["Quá trình xác định nguồn gốc và hành trình của sản phẩm từ nguyên liệu đến người tiêu dùng", "Quá trình kiểm tra chất lượng sản phẩm tại nhà máy", "Quá trình ghi lại ngày sản xuất và hạn sử dụng của sản phẩm", "Quá trình quảng bá thương hiệu sản phẩm trên thị trường"], 0, "Định nghĩa đúng là việc xác định nguồn gốc và hành trình của sản phẩm từ nguyên liệu đầu vào tới người tiêu dùng cuối cùng.", 1);
  add(4, "\"Dấu vết sản phẩm\" (product trace) được hiểu là:", ["Thông tin về giá bán của sản phẩm", "Các dữ liệu ghi nhận được trên mỗi bước trong chuỗi cung ứng, cho phép truy hồi lại nguồn gốc và hành trình của sản phẩm", "Mã QR trên bao bì sản phẩm", "Hình ảnh quảng cáo sản phẩm"], 1, "Dấu vết sản phẩm là các thông tin ghi nhận được ở mỗi giai đoạn của chuỗi cung ứng, cho phép truy hồi nguồn gốc.", 1);
  add(4, "Nguyên tắc cơ bản của hệ thống truy xuất nguồn gốc là:", ["Ghi chép đầy đủ, liên tục và có thể truy cập được", "Chỉ ghi chép khi có khiếu nại", "Ghi chép bằng giấy tờ tay viết", "Không cần lưu trữ dữ liệu sau khi bán hàng"], 0, "Nguyên tắc yêu cầu ghi chép đầy đủ, liên tục và dữ liệu phải có thể truy cập để truy xuất khi cần.", 1);
  add(4, "Theo Luật An toàn Thực phẩm năm 2010, Điều 31, doanh nghiệp thực phẩm phải:", ["Chỉ phải có nhãn hiệu sản phẩm", "Thực hiện truy xuất nguồn gốc và duy trì hồ sơ liên quan", "Đăng ký thương hiệu quốc tế", "Thực hiện kiểm tra nội bộ mỗi năm một lần"], 1, "Điều 31 quy định doanh nghiệp thực phẩm phải thực hiện truy xuất nguồn gốc và lưu giữ hồ sơ để kiểm tra khi cần.", 2);
  add(4, "Trong quy trình truy xuất nguồn gốc, tài liệu nào thường được sử dụng để ghi nhận thông tin nguyên liệu cho một lô hàng thực phẩm chế biến?", ["Sổ theo dõi nguyên liệu (raw material log)", "Bảng quảng cáo sản phẩm", "Phiếu xuất kho bán lẻ", "Bản ghi điện tử của hệ thống ERP"], 0, "Sổ theo dõi nguyên liệu là tài liệu chuẩn để ghi nhận nguồn gốc, số lô, ngày nhập và các thông tin liên quan.", 2);
  add(4, "Khi phát hiện sản phẩm bị ô nhiễm, bước đầu tiên trong quy trình truy xuất nguồn gốc phải thực hiện là:", ["Thu thập thông tin về lô nguyên liệu liên quan", "Rút lại toàn bộ sản phẩm trên thị trường", "Thông báo ngay cho cơ quan quản lý nhà nước", "Tiến hành kiểm tra chất lượng lại toàn bộ dây chuyền sản xuất"], 0, "Bước đầu tiên là xác định lô nguyên liệu gây ô nhiễm để có cơ sở rút lui và thông báo chính xác.", 2);
  add(4, "Tiêu chuẩn Việt Nam TCVN 8305:2015 về truy xuất nguồn gốc không yêu cầu:", ["Ghi lại thời gian nhập kho nguyên liệu", "Lưu trữ hồ sơ truy xuất ít nhất 5 năm", "Sử dụng công nghệ blockchain để lưu trữ dữ liệu", "Xây dựng hệ thống mã số lô cho từng sản phẩm"], 2, "Tiêu chuẩn không bắt buộc sử dụng công nghệ blockchain; các yêu cầu khác như ghi thời gian, lưu trữ 5 năm và mã lô là bắt buộc.", 2);
  add(4, "Giấy chứng nhận an toàn thực phẩm (ATTP) được định nghĩa là gì?", ["Giấy phép kinh doanh cho doanh nghiệp thực phẩm", "Chứng nhận cơ sở đủ điều kiện an toàn thực phẩm", "Giấy tờ xuất khẩu thực phẩm", "Chứng nhận hệ thống quản lý ISO"], 1, "Giấy chứng nhận ATTP là chứng nhận cơ sở đáp ứng các tiêu chuẩn an toàn thực phẩm, cho phép hoạt động sản xuất, kinh doanh thực phẩm.", 1);
  add(4, "Cơ sở nào được coi là \"đủ điều kiện an toàn thực phẩm\" để được cấp giấy chứng nhận ATTP?", ["Có giấy phép kinh doanh", "Đáp ứng các tiêu chuẩn HACCP và quy chuẩn vệ sinh", "Có ít nhất 10 nhân viên", "Đã đăng ký thuế"], 1, "Đủ điều kiện ATTP yêu cầu cơ sở thực hiện HACCP, đáp ứng quy chuẩn vệ sinh an toàn thực phẩm và các yêu cầu pháp lý liên quan.", 1);
  add(4, "Theo Nghị định quy định, quy trình xin cấp giấy chứng nhận ATTP bao gồm các bước nào?", ["Đăng ký online → kiểm tra nội bộ → cấp giấy", "Nộp hồ sơ → kiểm tra thực địa → đánh giá → cấp giấy", "Kiểm tra nội bộ → nộp hồ sơ → phê duyệt tự động", "Đánh giá tài chính → cấp giấy"], 1, "Quy trình chuẩn là nộp hồ sơ, cơ quan quản lý thực hiện kiểm tra thực địa, đánh giá kết quả và quyết định cấp giấy chứng nhận.", 2);
  add(4, "Thời hạn hiệu lực của giấy chứng nhận ATTP là bao lâu?", ["1 năm", "2 năm", "3 năm", "5 năm"], 1, "Giấy chứng nhận ATTP có thời hạn 2 năm và được gia hạn sau khi đáp ứng lại các tiêu chuẩn.", 1);
  add(4, "Cơ sở cần thực hiện việc gia hạn giấy chứng nhận ATTP vào thời điểm nào?", ["Khi còn 6 tháng trước ngày hết hạn", "Khi còn 12 tháng trước ngày hết hạn", "Khi còn 30 ngày trước ngày hết hạn", "Khi có thay đổi địa chỉ"], 2, "Quy định yêu cầu cơ sở nộp hồ sơ gia hạn ít nhất 30 ngày trước khi giấy chứng nhận hết hạn.", 2);
  add(4, "Trong kiểm tra thực địa để cấp giấy chứng nhận ATTP, cơ quan quản lý sẽ không kiểm tra yếu tố nào sau đây?", ["Hồ sơ HACCP", "Điều kiện vệ sinh", "Kế hoạch marketing", "Nhân sự và đào tạo"], 2, "Kiểm tra thực địa tập trung vào HACCP, vệ sinh, nhân sự; kế hoạch marketing không thuộc phạm vi kiểm tra ATTP.", 2);
  add(4, "Nếu cơ sở không đáp ứng tiêu chuẩn vệ sinh an toàn thực phẩm, quyết định của cơ quan quản lý sẽ là gì?", ["Cấp giấy chứng nhận tạm thời", "Từ chối cấp giấy chứng nhận", "Cấp giấy chứng nhận có điều kiện", "Gửi đề nghị lên Bộ"], 1, "Khi không đáp ứng tiêu chuẩn, cơ quan quản lý sẽ từ chối cấp giấy chứng nhận ATTP cho đến khi khắc phục.", 1);
  add(5, "Theo Nghị định 15/2018/NĐ-CP, “tự công bố” là gì?", ["Công bố thông tin thực phẩm trên website của doanh nghiệp mà không cần kiểm nghiệm", "Công bố thông tin thực phẩm trên phương tiện truyền thông đại chúng sau khi được cơ quan quản lý thẩm định", "Công bố thông tin thực phẩm dựa trên kết quả tự kiểm nghiệm và đáp ứng các tiêu chuẩn quy định, không cần thẩm tra trước bởi cơ quan quản lý", "Công bố thông tin thực phẩm chỉ khi đã có giấy chứng nhận nhập khẩu"], 2, "“Tự công bố” theo Nghị định 15/2018 là việc doanh nghiệp tự công bố thông tin thực phẩm dựa trên kết quả tự kiểm nghiệm và đáp ứng tiêu chuẩn, không cần thẩm tra trước bởi cơ quan quản lý.", 1);
  add(5, "Khi đăng ký bản công bố theo Nghị định 15/2018/NĐ-CP, doanh nghiệp phải nộp những hồ sơ nào?", ["Chỉ hồ sơ kỹ thuật của sản phẩm", "Chỉ giấy phép kinh doanh và bản sao hợp đồng mua bán", "Báo cáo kiểm nghiệm, hồ sơ kỹ thuật và giấy chứng nhận đăng ký kinh doanh", "Chỉ bản công bố và giấy chứng nhận an toàn thực phẩm"], 2, "Đăng ký bản công bố yêu cầu nộp hồ sơ kỹ thuật, báo cáo kiểm nghiệm (nội bộ hoặc bên thứ ba) và giấy chứng nhận đăng ký kinh doanh của doanh nghiệp.", 1);
  add(5, "Theo Nghị định 15/2018/NĐ-CP, trường hợp nào doanh nghiệp được phép thực hiện “tự công bố” thay vì “đăng ký bản công bố”?", ["Sản phẩm có thành phần đã được liệt kê trong danh mục thực phẩm được phép sử dụng và đáp ứng các tiêu chuẩn hiện hành", "Sản phẩm mới chưa có tiêu chuẩn nào được ban hành", "Thực phẩm nhập khẩu từ nước ngoài", "Sản phẩm đã được chứng nhận ISO 9001"], 0, "Nếu thực phẩm chứa các thành phần đã có trong danh mục cho phép và đáp ứng tiêu chuẩn kỹ thuật, doanh nghiệp có thể tự công bố mà không cần đăng ký bản công bố.", 2);
  add(5, "Thời hạn tối đa mà cơ quan quản lý nhà nước có thể thẩm tra hồ sơ đăng ký bản công bố theo Nghị định 15/2018/NĐ-CP là:", ["15 ngày", "30 ngày", "45 ngày", "60 ngày"], 1, "Nghị định quy định cơ quan quản lý phải hoàn thành thẩm tra hồ sơ đăng ký bản công bố trong vòng 30 ngày kể từ ngày nhận hồ sơ.", 2);
  add(5, "Trong ngữ cảnh của Nghị định 15/2018/NĐ-CP, “bản công bố” là:", ["Bản sao giấy tờ pháp lý của doanh nghiệp", "Thông tin về sản phẩm được công bố trên bao bì, nhãn mác, tài liệu quảng cáo", "Báo cáo tài chính năm tài chính", "Hợp đồng mua bán giữa nhà cung cấp và nhà phân phối"], 1, "“Bản công bố” là thông tin chi tiết về thực phẩm được công bố trên bao bì, nhãn mác, tài liệu quảng cáo theo quy định của Nghị định.", 1);
  add(5, "Nguyên tắc nào được Nghị định 15/2018/NĐ-CP nhấn mạnh để đảm bảo an toàn thực phẩm khi thực hiện tự công bố?", ["Nguyên tắc phòng ngừa", "Nguyên tắc trách nhiệm của nhà sản xuất", "Nguyên tắc bảo vệ quyền lợi người tiêu dùng", "Nguyên tắc cạnh tranh công bằng trên thị trường"], 1, "Nghị định nhấn mạnh nguyên tắc trách nhiệm của nhà sản xuất trong việc tự công bố, yêu cầu họ đảm bảo sản phẩm đáp ứng các tiêu chuẩn an toàn.", 2);
  add(5, "Khi thực hiện tự công bố, doanh nghiệp phải tiến hành kiểm nghiệm nào?", ["Kiểm nghiệm nội bộ theo tiêu chuẩn quốc gia hoặc tiêu chuẩn công nhận", "Kiểm nghiệm do cơ quan quản lý nhà nước thực hiện", "Kiểm nghiệm bởi tổ chức chứng nhận quốc tế duy nhất", "Không cần thực hiện bất kỳ kiểm nghiệm nào"], 0, "Doanh nghiệp thực hiện tự công bố phải tự kiểm nghiệm sản phẩm theo tiêu chuẩn quốc gia hoặc tiêu chuẩn công nhận để chứng minh đáp ứng yêu cầu an toàn.", 2);

  add(1, "Tác giả chủ biên của Giáo trình 'Quản lý Chất lượng và Luật Thực phẩm' (NXB Đại học Cần Thơ, 2014) là ai?", ["TS. Lê Nguyễn Đoan Duy", "TS. Nguyễn Công Hà", "GS. TS. Nguyễn Văn Mười", "ThS. Trần Xinh"], 0, "Trang 1 và trang 3 của giáo trình ghi rõ TS. Lê Nguyễn Đoan Duy là chủ biên và TS. Nguyễn Công Hà là đồng tác giả.", 1);
  add(1, "Theo số liệu của Cục An toàn thực phẩm - Bộ Y tế giai đoạn 2007 - 2012 được nêu trong giáo trình, trung bình mỗi năm Việt Nam ghi nhận bao nhiêu vụ ngộ độc thực phẩm và số người tử vong tương ứng?", ["182 vụ ngộ độc và 43 người chết", "1.095 vụ ngộ độc và 263 người chết", "150 vụ ngộ độc và 50 người chết", "200 vụ ngộ độc và 30 người chết"], 0, "Trang 5 nêu rõ trong giai đoạn 2007-2012 có 1.095 vụ với 263 người chết, trung bình có 182 vụ ngộ độc thực phẩm và 43 người chết/năm.", 1);
  add(1, "Sự cố an toàn thực phẩm liên quan đến hóa chất công nghiệp Melamine trong sữa bột vào năm 2008 có nguồn gốc từ đâu?", ["Đài Loan", "Trung Quốc", "Hàn Quốc", "Úc"], 1, "Theo thống kê các sự cố an toàn thực phẩm ở trang 5, vụ việc Melamine trong sữa bột năm 2008 xuất phát từ Trung Quốc.", 1);
  add(1, "Sự cố phụ gia tạo đục và nước ép trái cây có chứa hóa chất DEHP năm 2011 được ghi nhận có nguồn gốc từ đâu?", ["Trung Quốc", "Hàn Quốc", "Đài Loan", "Úc"], 2, "Trang 5 đề cập đến sự cố phụ gia tạo đục, nước ép trái cây chứa DEHP xuất xứ từ Đài Loan (2011).", 1);
  add(1, "Phương pháp Quản lý chất lượng toàn diện (TQM - Total Quality Management) được định nghĩa như thế nào trong giáo trình?", ["Là phương pháp kiểm tra chất lượng sản phẩm cuối cùng trước khi đưa ra thị trường", "Là phương pháp quản lý tập trung vào chất lượng để thỏa mãn khách hàng, dựa vào sự tham gia của tất cả các thành viên trong tổ chức", "Là quy trình kiểm soát độc lập chỉ do bộ phận QA/QC thực hiện nhằm giảm chi phí sản xuất", "Là tiêu chuẩn bắt buộc do Bộ Y tế ban hành cho các cơ sở sản xuất quy mô nhỏ"], 1, "Trang 5 định nghĩa: Quản lý chất lượng toàn diện là phương pháp quản lý tập trung vào chất lượng để thỏa mãn khách hàng, dựa vào sự tham gia của tất cả các thành viên trong tổ chức nhắm đạt tới sự thành công lâu dài.", 2);
  add(1, "Giáo trình 'Quản lý Chất lượng và Luật Thực phẩm' được cấu trúc thành bao nhiêu chương nội dung chính?", ["3 chương", "4 chương", "5 chương", "6 chương"], 2, "Trang 3 và trang 6 giới thiệu giáo trình gồm có 05 chương nội dung chính.", 1);
  add(1, "Vì sao việc kiểm soát an toàn thực phẩm phải được thực hiện trong toàn bộ chuỗi cung ứng thực phẩm ('từ nông trại đến bàn ăn')?", ["Vì mối nguy hại về an toàn thực phẩm có thể xảy ra tại bất kỳ giai đoạn nào trong chuỗi thực phẩm", "Vì chi phí kiểm tra tại khâu cuối cùng thường cao hơn các khâu trước", "Vì pháp luật chỉ bắt buộc kiểm tra ở khâu chăn nuôi và trồng trọt", "Vì người tiêu dùng chỉ quan tâm đến nguyên liệu thô ban đầu"], 0, "Trang 5-6 khẳng định: Mối nguy hại về an toàn thực phẩm có thể xảy ra tại bất kỳ giai đoạn nào trong chuỗi thực phẩm nên nhất thiết phải có sự kiểm tra thích hợp trong toàn bộ chuỗi thực phẩm.", 2);
  add(3, "Theo giáo trình, các điều kiện tiền quyết và chương trình tiền quyết đóng vai trò là nền tảng trực tiếp để xây dựng hệ thống quản lý chất lượng nào?", ["Hệ thống quản lý an toàn thực phẩm HACCP", "Hệ thống quản lý môi trường ISO 14001", "Hệ thống quản lý chất lượng TQM (Total Quality Management)", "Hệ thống quản lý an toàn sức khỏe nghề nghiệp ISO 45001"], 0, "Giáo trình xác định các điều kiện tiền quyết và chương trình tiền quyết là nền tảng để xây dựng chương trình quản lý chất lượng theo tiêu chuẩn HACCP trong nhà máy thực phẩm.", 1);
  add(3, "Các điều kiện tiền quyết (Prerequisites) cơ bản cho một nhà máy thực phẩm được nêu trong giáo trình bao gồm những yếu tố nào?", ["Điều kiện về nhà xưởng, trang thiết bị và con người", "Điều kiện về vốn đầu tư, thị trường và truyền thông", "Điều kiện về nguồn nước, giao thông và năng lượng", "Điều kiện về nguyên liệu, bao bì và phân phối"], 0, "Các điều kiện tiền quyết bao gồm 3 nhóm chính: điều kiện về nhà xưởng, điều kiện về trang thiết bị và điều kiện về con người.", 1);
  add(3, "Hai chương trình tiền quyết (PRPs) cốt lõi thường gặp nhất trong các nhà máy chế biến thực phẩm là gì?", ["Quy phạm sản xuất tốt (GMP) và Quy phạm vệ sinh tốt (SSOP)", "Quy trình vận hành chuẩn (SOP) và Kiểm soát điểm tới hạn (CCP)", "Thực hành nông nghiệp tốt (GAP) và Thực hành phòng thí nghiệm tốt (GLP)", "Tiêu chuẩn phân tích rủi ro (RA) và Truy xuất nguồn gốc (TR)"], 0, "Chương trình tiền quyết bao gồm Quy phạm sản xuất tốt (GMP - Good Manufacturing Practice) và Quy phạm vệ sinh tốt (SSOP - Sanitation Standard Operating Procedures).", 1);
  add(1, "Trong Chương 1 của giáo trình, các mối nguy đối với an toàn thực phẩm được phân loại thành 3 nhóm chính nào?", ["Mối nguy sinh học, mối nguy hóa học và mối nguy vật lý", "Mối nguy vi sinh vật, mối nguy dinh dưỡng và mối nguy độc tố", "Mối nguy cơ học, mối nguy quang học và mối nguy nhiệt học", "Mối nguy môi trường, mối nguy con người và mối nguy thiết bị"], 0, "Giáo trình phân loại các mối nguy đối với an toàn thực phẩm thành 3 nhóm chính: mối nguy sinh học, mối nguy hóa học và mối nguy vật lý.", 1);
  add(5, "Luật An toàn thực phẩm của Việt Nam – văn bản pháp lý nền tảng hiện hành được giới thiệu trong giáo trình – được ban hành vào năm nào?", ["Năm 2010", "Năm 2005", "Năm 2012", "Năm 2018"], 0, "Nội dung giáo trình đề cập đến Luật An toàn thực phẩm của Việt Nam được Quốc hội ban hành vào năm 2010.", 1);
  add(2, "Bộ tiêu chuẩn quốc tế chuyên biệt về Hệ thống quản lý an toàn thực phẩm được đề cập chi tiết ở Chương 2 là bộ tiêu chuẩn nào?", ["ISO 22000", "ISO 9001", "ISO 14001", "ISO 17025"], 0, "Mục 2.3.2 trong mục lục Chương 2 giới thiệu về Bộ tiêu chuẩn ISO 22000 - Hệ thống quản lý an toàn thực phẩm.", 2);
  add(3, "Chương trình tiền quyết nào dưới đây KHÔNG thuộc nhóm các chương trình bổ trợ được đề cập trong giáo trình?", ["Chương trình đánh giá tác động môi trường chiến lược (ĐTM)", "Chương trình tập huấn nhân viên", "Chương trình vệ sinh và khử trùng", "Chương trình truy xuất nguồn gốc và thu hồi sản phẩm"], 0, "Giáo trình nêu các chương trình tiền quyết bổ trợ gồm: tập huấn nhân viên, vệ sinh khử trùng, tiếp nhận/tồn trữ/vận chuyển, truy xuất nguồn gốc và thu hồi sản phẩm. Đánh giá tác động môi trường không nằm trong danh mục này.", 2);
  add(1, "Trong mối quan hệ giữa Chất lượng thực phẩm và An toàn thực phẩm, khẳng định nào sau đây là đúng theo khung lý thuyết giáo trình?", ["An toàn thực phẩm là một phần cốt lõi cấu thành nên Chất lượng thực phẩm", "An toàn thực phẩm và Chất lượng thực phẩm là hai khái niệm hoàn toàn độc lập", "Chất lượng thực phẩm chỉ bao gồm giá trị cảm quan và dinh dưỡng, không bao gồm an toàn", "An toàn thực phẩm chỉ áp dụng cho sản phẩm xuất khẩu, còn chất lượng áp dụng cho nội địa"], 0, "Mục 1.2.3 trong giáo trình làm rõ 'An toàn thực phẩm như là một phần của chất lượng thực phẩm'.", 2);
  add(1, "Thực phẩm theo định nghĩa của Luật An toàn Thực phẩm Việt Nam bao gồm những gì?", ["A. Chỉ các sản phẩm ăn được sau khi qua chế biến", "B. Sản phẩm ăn, uống ở dạng tươi sống hoặc đã qua chế biến, bảo quản", "C. Tất cả các loại thuốc và mỹ phẩm", "D. Chỉ thực phẩm đóng gói công nghiệp"], 1, "Định nghĩa Luật an toàn thực phẩm Việt Nam: thực phẩm là sản phẩm mà con người ăn, uống ở dạng tươi sống hoặc đã qua chế biến, bảo quản.", 1);
  add(2, "Tiêu chuẩn quốc tế ISO 9000 chủ yếu quy định về:", ["A. Yêu cầu an toàn vi sinh cho thực phẩm", "B. Hệ thống quản lý chất lượng (Quality Management System)", "C. Quy trình vệ sinh nhà máy (GMP)", "D. Đánh giá nguy cơ sinh học (HACCP)"], 1, "ISO 9000 là bộ tiêu chuẩn về hệ thống quản lý chất lượng, không liên quan trực tiếp tới an toàn thực phẩm hay HACCP.", 1);
  add(2, "ISO 22000 là tiêu chuẩn quốc tế về:", ["A. Quản lý môi trường", "B. An toàn thực phẩm và hệ thống quản lý an toàn thực phẩm", "C. Quản lý tài chính doanh nghiệp", "D. Kiểm soát chất lượng trong dược phẩm"], 1, "ISO 22000 quy định yêu cầu về hệ thống quản lý an toàn thực phẩm, tích hợp các yếu tố HACCP.", 1);
  add(3, "Trong GMP (Good Manufacturing Practices), yếu tố “Good” (tốt) được hiểu là:", ["A. Sản phẩm có hương vị tốt", "B. Thực hiện quy trình sản xuất và vệ sinh chuẩn, giảm nguy cơ nhiễm bẩn", "C. Giá thành sản phẩm thấp", "D. Đóng gói đẹp mắt"], 1, "GMP tập trung vào quy trình sản xuất sạch, an toàn, giảm nguy cơ nhiễm bẩn và lỗi sản phẩm.", 2);
  add(3, "SSOP (Sanitation Standard Operating Procedures) là chương trình:", ["A. Kiểm soát chất lượng nguyên liệu", "B. Vệ sinh chuẩn và quy trình vệ sinh trong nhà máy", "C. Đánh giá rủi ro sinh học", "D. Quản lý tài chính"], 1, "SSOP là các quy trình tiêu chuẩn về vệ sinh (sanitation) nhằm duy trì môi trường sản xuất sạch.", 1);
  add(4, "Trong các bước xây dựng hệ thống HACCP, bước 1 “Thành lập đội HACCP” bao gồm:", ["A. Tuyển chọn nhân viên có kiến thức về vi sinh và an toàn thực phẩm", "B. Đào tạo nhân viên bán hàng", "C. Thiết lập hệ thống ERP", "D. Kiểm tra máy móc công nghệ"], 0, "Bước 1 yêu cầu thành lập đội HACCP gồm các chuyên gia, nhân viên có kiến thức về an toàn thực phẩm và vi sinh.", 2);
  add(4, "Nguyên tắc 3 của HACCP (Xác định các điểm kiểm soát tới hạn – CCP) nhằm:", ["A. Định vị các bước sản xuất không quan trọng", "B. Xác định các điểm mà có thể kiểm soát được nguy cơ gây hại tới sức khỏe", "C. Tăng năng suất sản xuất", "D. Giảm chi phí nguyên liệu"], 1, "CCP là các điểm trong quy trình mà kiểm soát được nguy cơ gây hại cho sức khỏe người tiêu dùng.", 2);
  add(4, "Trong HACCP, “Critical Limit” (Giới hạn tới hạn) là:", ["A. Giá trị tối đa cho phép của một thông số tại CCP", "B. Thời gian nghỉ giữa các ca làm việc", "C. Số lượng nhân viên trong đội HACCP", "D. Độ dài dây chuyền sản xuất"], 0, "Critical Limit là giá trị (nhiệt độ, thời gian, pH…) tối đa hoặc tối thiểu cho phép tại một CCP.", 2);
  add(5, "Theo Luật Thực phẩm EU, trách nhiệm chính của nhà sản xuất là:", ["A. Đảm bảo thực phẩm không gây hại cho sức khỏe khi được sử dụng đúng mục đích", "B. Đảm bảo giá bán thấp nhất thị trường", "C. Đảm bảo bao bì đẹp mắt", "D. Đảm bảo quảng cáo rộng rãi"], 0, "Luật EU quy định nhà sản xuất phải đảm bảo thực phẩm an toàn cho sức khỏe khi sử dụng đúng mục đích.", 2);
  add(5, "Ở Mỹ, quy định “Food Safety Modernization Act (FSMA)” tập trung vào:", ["A. Kiểm soát chất lượng sau khi thực phẩm đã đến tay người tiêu dùng", "B. Phòng ngừa nguy cơ an toàn thực phẩm trước khi xảy ra", "C. Quảng cáo thực phẩm trên truyền hình", "D. Định giá thực phẩm"], 1, "FSMA nhấn mạnh việc phòng ngừa (preventive controls) thay vì chỉ kiểm tra sau khi thực phẩm đã lưu thông.", 2);
  add(4, "Điều kiện tiền quyết (pre-requisite program) trong HACCP bao gồm tất cả ngoại trừ:", ["A. GMP", "B. SSOP", "C. Kiểm tra HACCP toàn diện", "D. Đào tạo nhân viên"], 2, "Điều kiện tiền quyết là các chương trình nền (GMP, SSOP, đào tạo…) không bao gồm việc thực hiện HACCP toàn diện.", 3);
  add(2, "Trong bảng “Mối nguy và một số biện pháp kiểm soát” (Bang 1.3), một biện pháp kiểm soát sinh học thường dùng là:", ["A. Sưởi ấm nhanh", "B. Tiệt trùng bằng nhiệt độ cao (pasteurization)", "C. Thêm màu thực phẩm", "D. Đóng gói trong nhựa"], 1, "Tiệt trùng nhiệt (pasteurization) là biện pháp kiểm soát sinh học thường dùng để tiêu diệt vi sinh.", 2);
  add(5, "Theo Luật Thực phẩm Việt Nam, cơ quan nào chịu trách nhiệm quản lý an toàn thực phẩm cấp quốc gia?", ["A. Bộ Y tế", "B. Bộ Nông nghiệp và Phát triển Nông thôn", "C. Cục An toàn Thực phẩm (thuộc Bộ Y tế)", "D. Bộ Công Thương"], 2, "Cục An toàn Thực phẩm thuộc Bộ Y tế là cơ quan chịu trách nhiệm quản lý an toàn thực phẩm quốc gia.", 1);
  add(4, "Trong quy trình HACCP, bước “Thiết lập các hành động sửa chữa” (Corrective Actions) nhằm:", ["A. Tăng doanh thu", "B. Khắc phục ngay khi có sai lệch so với Critical Limit", "C. Đào tạo lại nhân viên bán hàng", "D. Thay đổi bao bì sản phẩm"], 1, "Hành động sửa chữa được thực hiện ngay khi phát hiện vượt Critical Limit để ngăn ngừa nguy cơ.", 2);
  add(3, "Một trong những yếu tố “Điều kiện tiền quyết” liên quan đến “Thiết bị và dụng cụ” là:", ["A. Thiết bị phải được bảo trì, hiệu chuẩn định kỳ", "B. Thiết bị phải có màu sắc bắt mắt", "C. Thiết bị phải được quảng cáo trên truyền hình", "D. Thiết bị phải có giá thành rẻ"], 0, "Điều kiện tiền quyết về thiết bị yêu cầu bảo trì, hiệu chuẩn thường xuyên để tránh nhiễm bẩn.", 1);
  add(3, "Trong chương trình “Tiếp nhận, bảo trữ và vận chuyển” (3.4.3), yếu tố quan trọng nhất để duy trì an toàn thực phẩm là:", ["A. Kiểm soát nhiệt độ và độ ẩm", "B. Đánh giá thị trường", "C. Quảng cáo sản phẩm", "D. Định vị trên bản đồ"], 0, "Kiểm soát nhiệt độ, độ ẩm trong quá trình tiếp nhận, bảo trữ, vận chuyển là yếu tố then chốt bảo toàn chất lượng.", 2);
  add(5, "Theo quy định pháp luật Việt Nam, mức phạt hành chính tối đa cho vi phạm quy định về nhãn mác thực phẩm là:", ["A. 5 triệu đồng", "B. 10 triệu đồng", "C. 30 triệu đồng", "D. 50 triệu đồng"], 2, "Luật An toàn Thực phẩm quy định mức phạt tối đa cho vi phạm nhãn mác là 30 triệu đồng.", 3);
  add(4, "Bảng 4.1 “Sơ đồ cây quyết định để xác định các điểm CCP” được sử dụng để:", ["A. Xác định chi phí sản xuất", "B. Đánh giá mức độ rủi ro và xác định CCP", "C. Lập kế hoạch marketing", "D. Tính toán lợi nhuận"], 1, "Sơ đồ cây quyết định giúp phân tích quy trình, xác định các điểm có khả năng gây nguy cơ và thiết lập CCP.", 2);
  add(2, "Trong ISO 22000, yếu tố “HACCP” được tích hợp như một phần của:", ["A. Hệ thống quản lý môi trường (EMS)", "B. Hệ thống quản lý an toàn thực phẩm (FSMS)", "C. Hệ thống quản lý chất lượng (QMS)", "D. Hệ thống quản lý tài chính"], 1, "ISO 22000 kết hợp HACCP vào hệ thống quản lý an toàn thực phẩm (Food Safety Management System).", 2);
  add(1, "Theo giáo trình, thực phẩm bao gồm những loại nào?", ["A. Chỉ thực phẩm đã qua chế biến hoàn toàn", "B. Thực phẩm chưa qua chế biến, qua chế biến một phần và thành phẩm có thể sử dụng như thực phẩm hoặc dược phẩm", "C. Chỉ thực phẩm đóng gói sẵn", "D. Thực phẩm và mỹ phẩm"], 1, "Đoạn 1.1.2 nêu rõ thực phẩm gồm cả sản phẩm chưa qua chế biến, qua chế biến một phần và thành phẩm có thể dùng làm thực phẩm hoặc dược phẩm.", 1);
  add(1, "Định nghĩa \"chất lượng thực phẩm\" trong tài liệu là gì?", ["A. Giá trị dinh dưỡng cao nhất có thể đạt được", "B. Thuộc tính cơ bản của sản phẩm liên quan tới quá trình sinh, sản xuất và sử dụng, ảnh hưởng đến giá trị sử dụng", "C. Sự an toàn tuyệt đối không có bất kỳ rủi ro nào", "D. Giá thành thấp nhất cho người tiêu dùng"], 1, "Định nghĩa nêu rằng chất lượng là thuộc tính cơ bản liên quan tới quá trình sinh, sản xuất và sử dụng, quyết định giá trị sử dụng.", 1);
  add(2, "Trong bối cảnh quản lý chất lượng thực phẩm, yếu tố nào sau đây không phải là yếu tố ảnh hưởng đến chất lượng?", ["A. Nguyên liệu đầu vào", "B. Điều kiện bảo quản", "C. Thiết kế bao bì", "D. Màu sắc của nhân viên bán hàng"], 3, "Màu sắc của nhân viên bán hàng không ảnh hưởng trực tiếp tới chất lượng thực phẩm.", 1);
  add(3, "Tiêu chuẩn ISO 22000:2018 quy định về gì?", ["A. Hệ thống quản lý an toàn thực phẩm", "B. Hệ thống quản lý môi trường", "C. Hệ thống quản lý chất lượng tổng thể", "D. Hệ thống quản lý an toàn lao động"], 0, "ISO 22000 là tiêu chuẩn quốc tế về hệ thống quản lý an toàn thực phẩm (Food Safety Management System).", 2);
  add(3, "Nguyên tắc thứ ba của HACCP là \"Xác định các điểm tới hạn kiểm soát (CCP)\". Điều này có nghĩa là:", ["A. Lập danh sách các nguy cơ tiềm ẩn", "B. Xác định những bước trong quy trình mà kiểm soát là bắt buộc để ngăn ngừa, loại bỏ hoặc giảm thiểu nguy cơ", "C. Thiết lập các tiêu chuẩn chất lượng cuối cùng", "D. Đánh giá hiệu quả của hệ thống ghi chép"], 1, "Nguyên tắc 3 của HACCP yêu cầu xác định các CCP – những điểm trong quy trình cần kiểm soát để đảm bảo an toàn thực phẩm.", 2);
  add(4, "Theo Luật An toàn Thực phẩm 2010 (Việt Nam), doanh nghiệp vi phạm quy định về nhãn mác thực phẩm sẽ bị xử phạt:", ["A. Cảnh cáo và yêu cầu sửa đổi trong 24 giờ", "B. Phạt tiền từ 10.000.000 đến 30.000.000 đồng và/hoặc tước giấy phép kinh doanh", "C. Đình chỉ hoạt động trong 6 tháng", "D. Không có hình phạt nào"], 1, "Luật An toàn Thực phẩm quy định mức phạt tiền 10-30 triệu đồng và có thể kèm theo tước giấy phép kinh doanh đối với vi phạm nhãn mác.", 2);
  add(3, "Trong GMP (Good Manufacturing Practice), khái niệm \"làn sóng nhiễu (cross‑contamination)\" được dịch là:", ["A. Nhiễu loạn quy trình", "B. Ô nhiễm chéo", "C. Sai sót kỹ thuật", "D. Đột biến gen"], 1, "Cross‑contamination trong GMP được dịch là \"ô nhiễm chéo\", là hiện tượng chuyển giao chất gây ô nhiễm từ nguồn này sang nguồn khác.", 1);
  add(4, "Phương pháp kiểm nghiệm nào thường được dùng để xác định hàm lượng vi sinh (số cấy khuẩn) trong thực phẩm?", ["A. Phân tích HPLC", "B. Phương pháp đếm cấy (Plate Count Method)", "C. Phân tích khối lượng riêng", "D. Đo độ pH"], 1, "Plate Count Method (phương pháp đếm cấy) là tiêu chuẩn quốc tế để xác định số vi sinh trong thực phẩm.", 2);
  add(2, "Trong chuỗi cung ứng thực phẩm, điểm tiếp xúc trực tiếp (direct contact point) thường là:", ["A. Kho lưu trữ nguyên liệu", "B. Bề mặt dao cắt, dao gọt, máy móc tiếp xúc thực phẩm", "C. Văn phòng bán hàng", "D. Xe tải vận chuyển nguyên liệu"], 1, "Các bề mặt dao, máy móc trực tiếp tiếp xúc với thực phẩm là điểm tiếp xúc trực tiếp, cần được vệ sinh và kiểm soát.", 1);
  add(3, "Tiêu chuẩn ISO 9001:2015 tập trung vào:", ["A. An toàn thực phẩm", "B. Quản lý môi trường", "C. Quản lý chất lượng tổng thể", "D. Quản lý sức khỏe và an toàn nghề nghiệp"], 2, "ISO 9001 là tiêu chuẩn quốc tế về hệ thống quản lý chất lượng (Quality Management System).", 2);
  add(3, "Trong quy trình HACCP, bước \"Thiết lập giới hạn tới hạn (Critical Limit)\" có mục đích:", ["A. Xác định mức độ nghiêm trọng của vi phạm pháp luật", "B. Đặt mức giá bán tối đa cho sản phẩm", "C. Định lượng các tiêu chuẩn mà CCP phải đáp ứng để bảo đảm an toàn", "D. Lập kế hoạch marketing"], 2, "Critical Limit là giới hạn tối đa hoặc tối thiểu mà CCP phải đáp ứng; vượt qua sẽ gây nguy cơ cho an toàn thực phẩm.", 2);
  add(4, "Theo Nghị định 43/2014/NĐ-CP, doanh nghiệp thực hiện kiểm tra nội bộ (internal audit) ít nhất bao lâu một lần?", ["A. 6 tháng", "B. 12 tháng", "C. 24 tháng", "D. 3 tháng"], 1, "Nghị định 43/2014 quy định doanh nghiệp phải thực hiện kiểm tra nội bộ ít nhất mỗi 12 tháng một lần.", 2);
  add(4, "Trong quy trình kiểm nghiệm thực phẩm, mẫu lấy mẫu phải tuân thủ nguyên tắc:", ["A. Lấy mẫu ngẫu nhiên, đại diện và đủ số lượng", "B. Lấy mẫu chỉ từ lô hàng đầu tiên", "C. Lấy mẫu chỉ vào buổi sáng", "D. Lấy mẫu dựa trên cảm quan người kiểm"], 0, "Nguyên tắc lấy mẫu yêu cầu ngẫu nhiên, đại diện và đủ số lượng để phản ánh toàn bộ lô hàng.", 1);
  add(3, "Trong GMP, việc \"đánh dấu ngày sản xuất và hạn sử dụng\" được xem là:", ["A. Yêu cầu về bảo quản", "B. Yêu cầu về ghi nhãn (labeling)", "C. Yêu cầu về kiểm soát nhiệt độ", "D. Yêu cầu về đào tạo nhân viên"], 1, "Ghi ngày sản xuất và hạn sử dụng là một phần của yêu cầu ghi nhãn (labeling) trong GMP.", 1);
  add(4, "Theo Điều 23 Luật Thực phẩm 2010, thực phẩm nào sau đây không được phép nhập khẩu vào Việt Nam?", ["A. Thực phẩm có chứa chất gây dị ứng không được khai báo", "B. Thực phẩm đóng gói bằng nhựa PET", "C. Thực phẩm tươi sống có giấy chứng nhận xuất xứ", "D. Thực phẩm đã qua xử lý nhiệt"], 0, "Luật thực phẩm cấm nhập khẩu thực phẩm có chất gây dị ứng không được khai báo, nhằm bảo vệ sức khỏe người tiêu dùng.", 3);
  add(3, "Một doanh nghiệp thực hiện sai quy trình vệ sinh thiết bị, hậu quả có thể dẫn tới:", ["A. Tăng năng suất", "B. Ô nhiễm chéo (cross‑contamination) và mất chất lượng sản phẩm", "C. Giảm chi phí sản xuất", "D. Cải thiện hương vị sản phẩm"], 1, "Vệ sinh không đúng gây ô nhiễm chéo, làm giảm chất lượng và an toàn thực phẩm.", 2);
  add(3, "Trong ISO 22000, khái niệm \"Prerequisite Programs (PRP)\" được dịch là:", ["A. Chương trình tiền điều kiện", "B. Chương trình kiểm soát chất lượng", "C. Chương trình đào tạo nhân viên", "D. Chương trình marketing"], 0, "Prerequisite Programs (PRP) nghĩa là \"chương trình tiền điều kiện\", là các yếu tố cơ bản hỗ trợ hệ thống HACCP.", 2);
  add(4, "Nếu doanh nghiệp bị phát hiện vi phạm quy định về mức độ dư lượng thuốc trừ sâu vượt quá tiêu chuẩn, mức phạt tối đa theo Nghị định 08/2020/NĐ-CP là:", ["A. 50.000.000 đồng", "B. 100.000.000 đồng", "C. 200.000.000 đồng", "D. 500.000.000 đồng"], 2, "Nghị định 08/2020 quy định mức phạt tối đa 200.000.000 đồng cho vi phạm dư lượng thuốc trừ sâu vượt tiêu chuẩn.", 3);

  add(5,"Thông tư số 26/2016/TT-BNNPTNT của Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn quy định về kiểm dịch động vật, sản phẩm động vật thủy sản có hiệu lực thi hành kể từ ngày nào?",["Ngày 30 tháng 6 năm 2016", "Ngày 15 tháng 8 năm 2016", "Ngày 10 tháng 02 năm 2019", "Ngày 11 tháng 9 năm 2022"],1,"Theo trang 1 của tài liệu, Thông tư số 26/2016/TT-BNNPTNT có hiệu lực thi hành kể từ ngày 15 tháng 8 năm 2016.",1);
  add(5,"Thông tư số 36/2018/TT-BNNPTNT sửa đổi, bổ sung một số điều của Thông tư số 26/2016/TT-BNNPTNT có hiệu lực thi hành kể từ ngày nào?",["Ngày 25 tháng 12 năm 2018", "Ngày 15 tháng 8 năm 2016", "Ngày 10 tháng 02 năm 2019", "Ngày 11 tháng 9 năm 2022"],2,"Theo trang 1 của tài liệu, Thông tư số 36/2018/TT-BNNPTNT có hiệu lực thi hành kể từ ngày 10 tháng 02 năm 2019.",1);
  add(5,"Căn cứ pháp lý nào sau đây được sử dụng để ban hành Thông tư số 26/2016/TT-BNNPTNT?",["Nghị định số 15/2017/NĐ-CP", "Nghị định số 199/2013/NĐ-CP", "Luật an toàn thực phẩm số 55/2010/QH12", "Luật thú y số 79/2015/QH13"],1,"Theo trang 1 của tài liệu, Thông tư số 26/2016/TT-BNNPTNT được ban hành dựa trên Căn cứ Nghị định số 199/2013/NĐ-CP ngày 26/11/2013 của Chính phủ.",1);
  add(5,"Phạm vi điều chỉnh của Thông tư này bao gồm những nội dung nào sau đây?",["Quy định chi tiết Khoản 3 Điều 53 của Luật thú y về Danh Mục động vật, sản phẩm động vật thủy sản thuộc diện phải kiểm dịch, miễn kiểm dịch.", "Quy định về xử phạt vi phạm hành chính trong lĩnh vực thú y.", "Hướng dẫn kỹ thuật nuôi trồng thủy sản an toàn sinh học.", "Quy định về cấp phép kinh doanh thuốc thú y thủy sản."],0,"Theo Khoản 1 Điều 1 của Thông tư, phạm vi điều chỉnh quy định chi tiết Khoản 3 Điều 53 của Luật thú y về Danh Mục động vật, sản phẩm động vật thủy sản thuộc diện phải kiểm dịch, miễn kiểm dịch; Danh Mục động vật, sản phẩm động vật thủy sản thuộc diện phải phân tích nguy cơ trước khi nhập khẩu vào Việt Nam; Danh Mục đối tượng kiểm dịch động vật, sản phẩm động vật thủy sản; nội dung, hồ sơ kiểm dịch động vật, sản phẩm động vật thủy sản vận chuyển ra khỏi địa bàn cấp tỉnh, xuất khẩu, nhập khẩu, tạm nhập tái xuất, tạm xuất tái nhập, chuyển cửa khẩu, kho ngoại quan, quá cảnh lãnh thổ Việt Nam.",2);
  add(5,"Đối tượng áp dụng của Thông tư này bao gồm cơ quan, tổ chức, cá nhân có liên quan đến hoạt động nào?",["Nghiên cứu khoa học về bệnh thủy sản.", "Vận chuyển động vật, sản phẩm động vật thủy sản ra khỏi địa bàn cấp tỉnh, xuất khẩu, nhập khẩu, tạm nhập tái xuất, tạm xuất tái nhập, chuyển cửa khẩu, kho ngoại quan, quá cảnh lãnh thổ Việt Nam.", "Sản xuất thức ăn chăn nuôi thủy sản.", "Đánh bắt thủy sản trên biển."],1,"Theo Khoản 2 Điều 1 của Thông tư, đối tượng áp dụng là cơ quan, tổ chức, cá nhân có liên quan đến hoạt động vận chuyển động vật, sản phẩm động vật thủy sản ra khỏi địa bàn cấp tỉnh, xuất khẩu, nhập khẩu, tạm nhập tái xuất, tạm xuất tái nhập, chuyển cửa khẩu, kho ngoại quan, quá cảnh lãnh thổ Việt Nam.",2);
  add(5,"Theo Thông tư này, 'Động vật thủy sản sử dụng làm giống' được hiểu là động vật thủy sản được sử dụng với mục đích nào?",["Chỉ để nuôi thương phẩm.", "Chỉ để làm cảnh hoặc giải trí.", "Để sản xuất giống, làm giống để nuôi thương phẩm, làm cảnh, giải trí hoặc sử dụng với mục đích khác.", "Chỉ để nghiên cứu khoa học."],2,"Theo Khoản 1 Điều 2 của Thông tư, 'Động vật thủy sản sử dụng làm giống là động vật thủy sản sử dụng để sản xuất giống, làm giống để nuôi thương phẩm, làm cảnh, giải trí hoặc sử dụng với mục đích khác'.",1);
  add(5,"Thông tư số 06/2022/TT-BNNPTNT sửa đổi, bổ sung một số điều của các Thông tư quy định về kiểm dịch động vật, sản phẩm động vật thủy sản, có hiệu lực thi hành kể từ ngày nào?",["Ngày 28 tháng 7 năm 2022", "Ngày 10 tháng 02 năm 2019", "Ngày 11 tháng 9 năm 2022", "Ngày 15 tháng 8 năm 2016"],2,"Theo trang 1 của tài liệu, Thông tư số 06/2022/TT-BNNPTNT có hiệu lực thi hành kể từ ngày 11 tháng 9 năm 2022.",1);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, đối tượng phải kiểm dịch động vật và sản phẩm động vật thủy sản bao gồm:",["Chỉ các loài cá nước ngọt đang sống trong môi trường tự nhiên.", "Các loài động vật thủy sản, sản phẩm động vật thủy sản dùng làm thực phẩm, nguyên liệu chế biến, thức ăn chăn nuôi, hoặc dùng cho mục đích khác.", "Chỉ các sản phẩm chế biến sẵn đã qua khử trùng.", "Các loài thủy sinh không thuộc danh mục nguy cơ cao."],1,"Điều 3 của Thông tư 26/2016 quy định rằng đối tượng kiểm dịch là mọi động vật và sản phẩm động vật thủy sản dùng làm thực phẩm, nguyên liệu chế biến, thức ăn chăn nuôi hoặc các mục đích khác.",1);
  add(5,"Thời gian tối đa vật mẫu phải được lưu giữ để thực hiện kiểm dịch theo Thông tư 26/2016 là:",["7 ngày.", "15 ngày.", "30 ngày.", "Không quy định thời gian cụ thể."],2,"Điều 3, khoản 3 của Thông tư 26/2016 quy định thời gian lưu giữ vật mẫu trong thời gian quy định để thực hiện việc kiểm dịch, thường là 30 ngày.",2);
  add(5,"Trong hồ sơ đăng ký kiểm dịch nhập khẩu động vật thủy sản, tài liệu nào sau đây KHÔNG bắt buộc phải có:",["Mẫu đơn đăng ký kiểm dịch (Mẫu 01).", "Giấy chứng nhận kiểm dịch xuất khẩu của nước xuất khẩu.", "Giấy phép CITES (nếu hàng thuộc danh mục CITES).", "Bản sao hợp đồng mua bán quốc tế."],3,"Theo Điều 4, hồ sơ đăng ký kiểm dịch nhập khẩu gồm mẫu đơn, giấy chứng nhận kiểm dịch xuất khẩu và giấy phép CITES (nếu áp dụng). Hợp đồng mua bán không phải là tài liệu bắt buộc trong hồ sơ kiểm dịch.",2);
  add(5,"Mặt hàng nào dưới đây được xếp vào danh mục “có nguy cơ cao” theo Thông tư 26/2016?",["Cá tươi sống.", "Cá đã qua chế biến nhiệt độ cao.", "Tôm đông lạnh đã được đóng gói kín.", "Cá khô đã được sấy khô."],0,"Điều 74 nêu rằng các sản phẩm động vật thủy sản có nguy cơ cao bao gồm cá sống, cá tươi, tôm sống, cá trích, cá ngừ sống, v.v.",1);
  add(5,"Khi xuất khẩu mặt hàng động vật thủy sản, tài liệu nào sau đây phải được đính kèm theo giấy chứng nhận kiểm dịch xuất khẩu:",["Bản sao giấy phép khai thác tài nguyên thiên nhiên.", "Bản sao giấy chứng nhận nguồn gốc xuất xứ (CO).", "Bản sao chứng nhận bảo hiểm hàng hoá.", "Bản sao giấy chứng nhận tiêu chuẩn HACCP."],1,"Theo Điều 4, mục b) trong hồ sơ đăng ký kiểm dịch xuất khẩu, cần đính kèm bản sao giấy chứng nhận nguồn gốc xuất xứ (CO) của sản phẩm.",2);
  add(5,"Nếu phát hiện hàng hóa động vật thủy sản không đáp ứng yêu cầu kiểm dịch, cơ quan kiểm dịch sẽ thực hiện biện pháp nào sau đây:",["Tự ý tiêu hủy hàng hóa mà không thông báo cho người nộp.", "Áp dụng biện pháp cô lập, tiêu hủy hoặc trả lại hàng cho người nộp theo quy định.", "Cho phép hàng hóa lưu thông nếu người nộp đồng ý trả phí bù đắp.", "Chỉ ghi chú trong hồ sơ và cho phép nhập khẩu."],1,"Điều 85 quy định rằng khi phát hiện vi phạm, cơ quan kiểm dịch có thể cô lập, tiêu hủy hoặc trả lại hàng cho người nộp, đồng thời lập biên bản và thông báo cho các bên liên quan.",3);
  add(5,"Danh mục động vật, sản phẩm động vật thủy sản phải kiểm dịch được quy định ở phụ lục nào của Thông tư 26/2016?",["Phụ lục I.", "Phụ lục II.", "Phụ lục III.", "Cả ba phụ lục I, II và III."],3,"Theo Điều 3, các danh mục được quy định ở Phụ lục I (đối tượng phải kiểm dịch), Phụ lục II (đối tượng phải phân tích nguy cơ) và Phụ lục III (đối tượng phải kiểm dịch đặc biệt).",2);
  add(5,"Trong trường hợp hàng nhập khẩu là sản phẩm động vật thủy sản đã qua chế biến nhưng chưa được khử trùng, người nhập khẩu phải thực hiện gì để được phép nhập khẩu:",["Nộp hồ sơ kiểm dịch và xin giấy chứng nhận kiểm dịch xuất khẩu của nước xuất khẩu.", "Chỉ cần nộp giấy tờ thương mại thông thường.", "Yêu cầu cơ quan kiểm dịch thực hiện khử trùng tại cảng.", "Không cần thực hiện bất kỳ thủ tục nào vì đã qua chế biến."],0,"Theo Điều 4, dù đã qua chế biến, nếu chưa được khử trùng, hàng vẫn phải qua kiểm dịch và cần giấy chứng nhận kiểm dịch xuất khẩu của nước xuất khẩu để được phép nhập khẩu.",3);
  add(5,"Theo quy định hiện hành, đối với động vật thủy sản không thuộc Danh mục loài thủy sản được phép kinh doanh tại Việt Nam, doanh nghiệp cần nộp giấy tờ nào trong hồ sơ đăng ký kiểm dịch nhập khẩu?",["Bản chụp Giấy phép nhập khẩu do Tổng cục Thủy sản cấp, có xác nhận của doanh nghiệp.", "Bản gốc Giấy phép nhập khẩu do Bộ Nông nghiệp và Phát triển nông thôn cấp.", "Bản sao công chứng Giấy phép nhập khẩu do Cục Thú y cấp.", "Bản chụp Giấy chứng nhận đăng ký kinh doanh có xác nhận của doanh nghiệp."],0,"Theo Điểm d Khoản 2 (đã sửa đổi bởi Khoản 1 Điều 1 Thông tư số 06/2022/TT-BNNPTNT) của Thông tư 26/2016/TT-BNNPTNT, hồ sơ đăng ký kiểm dịch nhập khẩu đối với động vật thủy sản không thuộc Danh mục loài thủy sản được phép kinh doanh tại Việt Nam cần có 'Bản chụp Giấy phép nhập khẩu do Tổng cục Thủy sản cấp, có xác nhận của doanh nghiệp'.",1);
  add(5,"Hồ sơ đăng ký kiểm dịch tạm nhập tái xuất động vật, sản phẩm động vật thủy sản qua kho ngoại quan cần có văn bản đề nghị theo mẫu nào?",["Mẫu 04 TS Phụ lục V.", "Mẫu 05 TS Phụ lục V.", "Mẫu 03 TS Phụ lục V.", "Mẫu 06 TS Phụ lục V."],1,"Theo Điểm a Khoản 4 Điều 1 của Thông tư 26/2016/TT-BNNPTNT, hồ sơ đăng ký kiểm dịch tạm nhập tái xuất, tạm xuất tái nhập, chuyển cửa khẩu, kho ngoại quan, quá cảnh động vật, sản phẩm động vật thủy sản cần có 'Văn bản đề nghị hướng dẫn kiểm dịch theo mẫu 04 TS (mẫu 05 TS đối với hàng nhập, xuất kho ngoại quan) Phụ lục V ban hành kèm theo Thông tư này'.",1);
  add(5,"Trong hồ sơ đăng ký kiểm dịch xuất khẩu động vật, sản phẩm động vật thủy sản không dùng làm thực phẩm, khi nào doanh nghiệp cần nộp Bản chụp Giấy phép xuất khẩu thủy sản do Tổng cục Thủy sản cấp?",["Đối với tất cả các loại thủy sản xuất khẩu.", "Đối với các loại thủy sản xuất khẩu có điều kiện theo quy định tại Phụ lục IX, Phụ lục X của Nghị định số 26/2019/NĐ-CP.", "Chỉ khi nước nhập khẩu yêu cầu.", "Chỉ khi sản phẩm thủy sản là loài nguy cấp, quý, hiếm."],1,"Theo Điểm c Khoản 5 (đã sửa đổi bởi Khoản 2 Điều 1 Thông tư số 06/2022/TT-BNNPTNT) của Thông tư 26/2016/TT-BNNPTNT, 'Bản chụp Giấy phép xuất khẩu thủy sản do Tổng cục Thủy sản cấp, có xác nhận của doanh nghiệp' chỉ yêu cầu 'đối với các loại thủy sản xuất khẩu có điều kiện theo quy định tại Phụ lục IX, Phụ lục X ban hành kèm theo Nghị định số 26/2019/NĐ-CP'.",2);
  add(5,"Đối với hồ sơ khai báo kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu để tiêu thụ trong nước, Giấy chứng nhận kiểm dịch của nước xuất khẩu có thể được sử dụng dưới hình thức nào nếu có thỏa thuận?",["Chỉ bản gốc có chữ ký tươi.", "Bản sao công chứng.", "Giấy chứng nhận kiểm dịch điện tử.", "Bản chụp có xác nhận của doanh nghiệp."],2,"Theo Khoản 6 Điều 1 của Thông tư 26/2016/TT-BNNPTNT, tại Điểm b có nêu: 'Trường hợp Cục Thú y và Cơ quan thẩm quyền của nước xuất khẩu có thống nhất về chứng nhận điện tử thì sử dụng Giấy chứng nhận kiểm dịch điện tử'.",2);
  add(5,"Một doanh nghiệp muốn đăng ký kiểm dịch cho lô hàng động vật thủy sản sử dụng làm giống vận chuyển ra khỏi địa bàn cấp tỉnh. Doanh nghiệp này cần tham khảo quy định tại điều nào của Thông tư 26/2016/TT-BNNPTNT?",["Điều 4.", "Điều 5.", "Điều 6.", "Điều 7."],1,"Theo Điều 5 của Thông tư 26/2016/TT-BNNPTNT, quy định về 'Đăng ký kiểm dịch động vật thủy sản sử dụng làm giống vận chuyển ra khỏi địa bàn cấp tỉnh'.",1);
  add(5,"Trong trường hợp hồ sơ khai báo kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu để tiêu thụ trong nước, nếu tại thời điểm gửi hồ sơ chưa cung cấp được Giấy chứng nhận kiểm dịch của nước xuất khẩu (bản gốc), doanh nghiệp phải làm gì?",["Nộp bản sao công chứng và bổ sung bản gốc sau khi kiểm tra hàng hóa.", "Nộp bản sao và gửi bản gốc Giấy chứng nhận kiểm dịch của nước xuất khẩu khi kiểm tra hàng hóa.", "Đề nghị Cục Thú y cấp lại giấy chứng nhận.", "Không được phép khai báo kiểm dịch."],1,"Theo Điểm b Khoản 6 Điều 1 của Thông tư 26/2016/TT-BNNPTNT, 'Trường hợp nộp bản sao hoặc tại thời điểm gửi hồ sơ chưa cấp Giấy chứng nhận kiểm dịch của nước xuất khẩu thì phải gửi bản gốc Giấy chứng nhận kiểm dịch của nước xuất khẩu khi kiểm tra hàng hóa'.",2);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, đối tượng phải nộp hồ sơ kiểm dịch là:",["A. Chỉ các doanh nghiệp xuất khẩu thủy sản sang nước ngoài.", "B. Các cơ sở nuôi, thu hoạch, thu gom, kinh doanh, vận chuyển động vật thủy sản dùng làm giống và xuất phát từ tỉnh, chuyển ra tỉnh khác.", "C. Các cá nhân nuôi cá cảnh trong hộ gia đình.", "D. Các nhà máy chế biến thực phẩm không liên quan tới thủy sản."],1,"Điều 1, khoản 4 của Thông tư 26/2016 quy định rằng các cơ sở nuôi, thu hoạch, thu gom, kinh doanh, vận chuyển động vật thủy sản dùng làm giống và xuất phát từ tỉnh, chuyển ra tỉnh khác phải đăng ký và nộp hồ sơ kiểm dịch.",1);
  add(5,"Thời hạn tối đa để cơ quan kiểm dịch địa phương xem xét tính hợp lệ của hồ sơ sau khi nhận được là:",["A. 12 giờ làm việc.", "B. 1 ngày làm việc.", "C. 3 ngày làm việc.", "D. 7 ngày làm việc."],1,"Theo Điều 2 của Thông tư 26/2016, cơ quan kiểm dịch địa phương phải xem xét tính hợp lệ của hồ sơ và thông báo trong thời hạn 01 ngày làm việc kể từ khi nhận hồ sơ.",1);
  add(5,"Khi kiểm dịch động vật thủy sản, cơ quan kiểm dịch phải thực hiện kiểm tra các yếu tố nào sau đây?",["A. Chỉ kiểm tra giấy tờ xuất xứ và kích thước.", "B. Kiểm tra số lượng, chủng loại, kích thước, ánh sáng, mẫu vật theo Phụ lục IV, điều kiện vệ sinh phương tiện vận chuyển và các vật dụng kèm theo.", "C. Kiểm tra chỉ độ tuổi và trọng lượng của cá.", "D. Kiểm tra chỉ mức độ tiêu thụ năng lượng của phương tiện vận chuyển."],1,"Điều 6, mục a‑d của Thông tư 26/2016 liệt kê các nội dung kiểm tra: số lượng, chủng loại, kích thước, ánh sáng, lấy mẫu theo Phụ lục IV, điều kiện vệ sinh phương tiện vận chuyển và các vật dụng kèm theo.",2);
  add(5,"Nếu hồ sơ kiểm dịch không hợp lệ, cơ quan kiểm dịch sẽ:",["A. Từ chối cấp giấy chứng nhận và không cho phép sửa lại hồ sơ.", "B. Gửi thông báo yêu cầu chủ hàng hoàn thiện, sửa chữa hồ sơ theo quy định.", "C. Tự động cấp giấy chứng nhận tạm thời trong 24 giờ.", "D. Bảo lưu hồ sơ và chờ quyết định của Bộ Nông nghiệp."],1,"Theo Điều 6, khoản 2 của Thông tư 26/2016, khi hồ sơ không hợp lệ, cơ quan kiểm dịch hướng dẫn chủ hàng hoàn chỉnh, sửa chữa hồ sơ theo quy định.",1);
  add(5,"Trong trường hợp phát hiện dấu hiệu bệnh dịch ở động vật thủy sản đang kiểm dịch, cơ quan kiểm dịch sẽ:",["A. Cấp giấy chứng nhận kiểm dịch bình thường và cho phép xuất khẩu.", "B. Không cấp giấy chứng nhận kiểm dịch và tiến hành các biện pháp phòng, chống dịch theo quy định.", "C. Chỉ ghi chú trong hồ sơ nhưng vẫn cấp giấy chứng nhận.", "D. Gửi hồ sơ lên cấp tỉnh để xem xét lại."],1,"Điều 6, khoản 3 của Thông tư 26/2016 quy định nếu cơ quan kiểm dịch nhận thấy nguy cơ dịch bệnh, không cấp giấy chứng nhận và thực hiện các biện pháp phòng, chống dịch theo quy định.",2);
  add(5,"Một doanh nghiệp nuôi cá giống tại tỉnh A muốn xuất khẩu cá giống sang tỉnh B. Sau khi nộp hồ sơ kiểm dịch, họ nhận được giấy chứng nhận kiểm dịch. Tuy nhiên, trong quá trình vận chuyển, phương tiện vận chuyển không được vệ sinh đúng quy chuẩn. Hành vi nào sau đây là vi phạm pháp luật?",["A. Không có vi phạm vì giấy chứng nhận đã được cấp.", "B. Vi phạm Điều 7 của Thông tư 26/2016 về việc không đảm bảo điều kiện vệ sinh phương tiện vận chuyển, có thể bị thu hồi giấy chứng nhận.", "C. Vi phạm chỉ áp dụng cho cá tươi, không áp dụng cho cá giống.", "D. Vi phạm chỉ xảy ra nếu có bệnh dịch phát sinh."],1,"Điều 7 của Thông tư 26/2016 yêu cầu cơ sở phải đảm bảo điều kiện vệ sinh phương tiện vận chuyển. Nếu không tuân thủ, giấy chứng nhận có thể bị thu hồi và doanh nghiệp sẽ bị xử phạt theo quy định.",3);
  add(5,"Theo Thông tư 36/2018/TT-BNNPTNT, khi bổ sung quy định về kiểm dịch động vật thủy sản, thời gian hiệu lực của các điều chỉnh mới là:",["A. Ngay sau khi công bố trên công báo.", "B. 30 ngày kể từ ngày công bố.", "C. 90 ngày kể từ ngày công bố.", "D. 180 ngày kể từ ngày công bố."],1,"Các khoản bổ sung trong Thông tư 36/2018 (ví dụ Điều 1 khoản 3) quy định thời gian hiệu lực là 30 ngày kể từ ngày công bố trên công báo.",2);
  add(5,"Khi kiểm dịch động vật thủy sản thu hoạch từ cơ sở nuôi không có dịch bệnh trong vùng công bố dịch, cơ quan kiểm dịch động vật nội địa thực hiện những công việc nào sau đây?",["Kiểm tra số lượng, chủng loại, kích cỡ động vật thủy sản; kiểm tra lâm sàng; lấy mẫu kiểm tra tác nhân gây bệnh đối với thủy sản thương phẩm cảm nhiễm bệnh được công bố dịch.", "Chỉ kiểm tra lâm sàng và lấy mẫu xét nghiệm.", "Chỉ kiểm tra số lượng và chủng loại.", "Thực hiện vệ sinh, khử trùng tiêu độc phương tiện vận chuyển."],0,"Theo điểm a, b, c Khoản 1 của phần quy định về 'thu hoach tir ccr sd nuoi khong co dich benh trong vung cong bo dich' trong văn bản, cơ quan kiểm dịch động vật nội địa thực hiện kiểm tra số lượng, chủng loại, kích cỡ; kiểm tra lâm sàng; và lấy mẫu kiểm tra tác nhân gây bệnh đối với động vật thủy sản thương phẩm cảm nhiễm bệnh được công bố dịch.",1);
  add(5,"Động vật thủy sản thu hoạch từ cơ sở nuôi có bệnh đang công bố dịch phải đáp ứng điều kiện nào trước khi đưa ra khỏi vùng công bố dịch?",["Phải được sơ chế tại chỗ.", "Phải được chế biến (xử lý nhiệt hoặc áp dụng biện pháp xử lý cụ thể đảm bảo không lây lan dịch bệnh).", "Phải được kiểm tra lâm sàng lần cuối.", "Phải có giấy xác nhận của chính quyền địa phương."],1,"Theo Khoản 2 của phần quy định về 'Dong vat thuy san thu hoach tir ca sa nuoi co benh dang cong bo dich', động vật thủy sản phải được chế biến (xử lý nhiệt hoặc tùy từng loại bệnh có thể áp dụng biện pháp xử lý cụ thể bảo đảm không thể lây lan dịch bệnh) trước khi đưa ra khỏi vùng công bố dịch.",2);
  add(5,"Theo Điều 9 Thông tư 26/2016/TT-BNNPTNT (sửa đổi, bổ sung bởi Thông tư 36/2018/TT-BNNPTNT), việc kiểm dịch sản phẩm động vật thủy sản xuất phát từ vùng công bố dịch vận chuyển ra khỏi địa bàn cấp tỉnh được thực hiện ở đâu?",["Tại cửa khẩu.", "Tại cơ sở sơ chế, chế biến của chủ hàng.", "Tại trạm kiểm dịch động vật liên tỉnh.", "Tại địa điểm tập kết hàng hóa của cơ quan kiểm dịch."],1,"Theo Khoản 1 Điều 9 của văn bản, 'Viec kiem dich duac thuc hien ngay tai ca sa sa che, che bien cua chu hang.'",1);
  add(5,"Theo Điều 9 Thông tư 26/2016/TT-BNNPTNT (sửa đổi, bổ sung bởi Thông tư 36/2018/TT-BNNPTNT), trong trường hợp sản phẩm động vật thủy sản không đảm bảo yêu cầu vệ sinh thú y, cơ quan kiểm dịch động vật nội địa sẽ xử lý như thế nào?",["Yêu cầu chủ hàng tái chế sản phẩm.", "Cấp Giấy chứng nhận kiểm dịch có điều kiện.", "Không cấp Giấy chứng nhận kiểm dịch và tiến hành xử lý theo quy định.", "Chuyển giao cho cơ quan quản lý thị trường xử lý."],2,"Theo Khoản 2 Điều 9 của văn bản, 'Tnromg hgfp san pham d§ng vat thuy san khong bao dam yeu cau ve sinh thu y, ca quan Idem dich dqng vat npi dja khong cap Giay chung nhan kiem dich va tien hanh xu ly theo quy dinh.'",2);
  add(5,"Cơ quan kiểm dịch động vật nội địa tại địa phương tiếp nhận chỉ thực hiện kiểm dịch động vật thủy sản sử dụng làm giống trong những trường hợp cụ thể nào dưới đây?",["Lô hàng vận chuyển từ tỉnh khác đến không có Giấy chứng nhận kiểm dịch hoặc Giấy chứng nhận kiểm dịch không hợp lệ.", "Chủ hàng yêu cầu kiểm dịch bổ sung.", "Lô hàng có số lượng lớn hơn 1000 con.", "Tất cả các trường hợp lô hàng vận chuyển liên tỉnh."],0,"Theo điểm a Khoản 1 Điều 10 của văn bản, cơ quan kiểm dịch động vật nội địa tại địa phương tiếp nhận chỉ thực hiện kiểm dịch trong trường hợp lô hàng vận chuyển từ địa bàn tỉnh khác đến không có Giấy chứng nhận kiểm dịch hoặc Giấy chứng nhận kiểm dịch không hợp lệ. Các trường hợp khác được nêu trong điểm b và c của Khoản 1 Điều 10 cũng là các trường hợp cụ thể, nhưng đáp án A là một trong những trường hợp rõ ràng nhất được liệt kê.",3);
  add(5,"Theo Điều 11 Thông tư 26/2016/TT-BNNPTNT (sửa đổi, bổ sung bởi Thông tư 36/2018/TT-BNNPTNT), chủ hàng có thể gửi hồ sơ đăng ký kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu không dùng làm thực phẩm đến cơ quan nào?",["Chi cục Thú y vùng hoặc Chi cục Kiểm dịch động vật vùng trực thuộc Cục Thú y.", "Cơ quan quản lý chuyên ngành thú y cấp tỉnh được Cục Thú y ủy quyền.", "Cả A và B.", "Bộ Nông nghiệp và Phát triển nông thôn."],2,"Theo Khoản 1 Điều 11 của văn bản, chủ hàng gửi hồ sơ đến 'Chi cục Thú y vùng hoặc Chi cục Kiểm dịch động vật vùng trực thuộc Cục Thú y hoặc cơ quan quản lý chuyên ngành thú y cấp tỉnh được Cục Thú y ủy quyền'. Do đó, cả A và B đều đúng.",1);
  add(5,"Khi kiểm dịch sản phẩm động vật thủy sản xuất khẩu không dùng làm thực phẩm, cơ quan kiểm dịch động vật cửa khẩu thực hiện kiểm tra những nội dung nào đối với sản phẩm (không phải động vật thủy sản)?",["Kiểm tra lâm sàng.", "Kiểm tra cảm quan, điều kiện bảo quản, thực trạng hàng hóa.", "Kiểm tra số lượng cá thể sống.", "Lấy mẫu kiểm tra tác nhân gây bệnh theo Phụ lục IV."],1,"Theo điểm b Khoản 3 Điều 11 của văn bản, đối với sản phẩm động vật thủy sản, cơ quan kiểm dịch thực hiện 'kiem tra cam quan, Di6u kieu bao quan, thuc trang hang hoa'. Kiểm tra lâm sàng là cho động vật thủy sản sống.",2);
  add(5,"Theo Điều 9 Khoản 2 điểm e và g, khi kiểm dịch sản phẩm động vật thủy sản xuất phát từ vùng công bố dịch, cơ quan kiểm dịch động vật nội địa có trách nhiệm gì đối với phương tiện vận chuyển và nơi bốc xếp hàng hóa?",["Chỉ kiểm tra điều kiện vệ sinh thú y của phương tiện vận chuyển.", "Thực hiện hoặc giám sát chủ hàng thực hiện việc vệ sinh, khử trùng tiêu độc phương tiện vận chuyển và các vật dụng kèm theo trước khi xếp hàng, cũng như nơi tập trung, bốc xếp hàng.", "Yêu cầu chủ hàng tự niêm phong phương tiện vận chuyển.", "Chỉ kiểm tra quá trình bốc xếp sản phẩm lên phương tiện vận chuyển."],1,"Theo điểm e và g Khoản 2 Điều 9 của văn bản, cơ quan kiểm dịch động vật nội địa thực hiện hoặc giám sát chủ hàng thực hiện việc vệ sinh, khử trùng tiêu độc phương tiện vận chuyển và các vật dụng kèm theo trước khi xếp hàng, cũng như kiểm tra, giám sát quá trình bốc xếp và vệ sinh, khử trùng tiêu độc nơi tập trung, bốc xếp hàng.",2);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, khi doanh nghiệp nhập khẩu không phải thực hiện kiểm dịch, họ phải làm gì?",["Không làm gì cả", "Thực hiện kiểm dịch tại cơ sở tỉnh theo Điều 6, 7, 8, 9 của Thông tư", "Nộp Giấy chứng nhận kiểm dịch cho hải quan cho mỗi lô hàng", "Nộp phạt hành chính"],1,"Điều 6, 7, 8, 9 của Thông tư 26/2016 quy định rằng dù không phải kiểm dịch, doanh nghiệp nhập khẩu vẫn phải thực hiện kiểm dịch tại cơ sở tỉnh để đảm bảo an toàn sinh học.",1);
  add(5,"Khi kiểm tra hàng xuất khẩu động vật, tài liệu nào phải được kiểm tra để xác nhận đã được kiểm dịch xuất khẩu?",["Giấy chứng nhận xuất xứ", "Giấy chứng nhận kiểm dịch xuất khẩu", "Giấy chứng nhận sức khỏe", "Hóa đơn thương mại"],1,"Điều 5 khoản b) của Thông tư 26/2016 yêu cầu kiểm tra Giấy chứng nhận kiểm dịch xuất khẩu (GCKDXK) để xác nhận hàng đã qua kiểm dịch.",1);
  add(5,"Đối với động vật thủy sản sống nhập khẩu để nuôi, yêu cầu về cơ sở nuôi riêng là gì?",["Phải nuôi trong môi trường biển mở", "Phải nuôi trong bể riêng, đảm bảo điều kiện vệ sinh và sinh học", "Có thể trộn với các loài khác", "Không có yêu cầu đặc biệt"],1,"Theo khoản c) Điều 5 Thông tư 26/2016, khi nuôi động vật thủy sản sống phải có bể nuôi riêng, đáp ứng yêu cầu vệ sinh, bao bì, bao quan và điều kiện sinh học.",2);
  add(5,"Trong việc đăng ký kiểm dịch nhập khẩu, phương thức nào không được chấp nhận theo Thông tư 26/2016?",["Gửi qua Cổng thông tin một quốc gia", "Gửi qua dịch vụ bưu chính", "Gửi qua fax", "Gửi trực tiếp tới Bộ mà không có hồ sơ điện tử trước"],3,"Khoản 1 Điều 13 quy định đăng ký qua Cổng thông tin, bưu chính, fax hoặc gửi hồ sơ gốc sau khi đã nộp điện tử; việc giao trực tiếp mà không có hồ sơ điện tử không được chấp nhận.",2);
  add(5,"Theo Điều 12, doanh nghiệp xuất khẩu động vật, sản phẩm động vật dùng làm thực phẩm phải nộp mẫu biểu nào?",["Mẫu biểu 01 theo Khoản 1 Điều 57 Luật Thủy sản", "Mẫu biểu 02 theo Luật Thú y", "Không cần mẫu biểu", "Mẫu biểu 03 theo Luật Hải quan"],0,"Điều 12 nêu rõ doanh nghiệp phải gửi mẫu biểu 01 (theo Khoản 1 Điều 57 Luật Thủy sản) để khai báo xuất khẩu.",1);
  add(5,"Ai chịu trách nhiệm chính trong việc đảm bảo cơ sở kiểm dịch đáp ứng yêu cầu vệ sinh và an toàn sinh học?",["Cơ quan hải quan", "Doanh nghiệp nhập khẩu", "Bộ Y tế", "Ủy ban Nhân dân địa phương"],1,"Khoản a) Điều 13 Thông tư 26/2016 quy định rằng chủ hàng (doanh nghiệp nhập khẩu) chịu trách nhiệm bố trí, duy trì và đảm bảo điều kiện vệ sinh, an toàn sinh học tại địa điểm kiểm dịch.",1);
  add(5,"Sau khi Cục Thú y cấp văn bản đồng ý kiểm dịch, doanh nghiệp nhập khẩu phải thực hiện bước tiếp theo nào trước khi hàng đến cửa khẩu?",["Nộp thuế nhập khẩu", "Nộp hồ sơ khai báo kiểm dịch theo Khoản 6 Điều 4 Thông tư", "Yêu cầu kiểm tra tại cảng", "Vận chuyển hàng ngay lập tức"],1,"Khoản b) Điều 15 quy định sau khi Cục Thú y có văn bản đồng ý, doanh nghiệp phải gửi hồ sơ khai báo kiểm dịch (theo Khoản 6 Điều 4) tới cơ quan kiểm dịch của cửa khẩu.",2);
  add(5,"Trong trường hợp nhập khẩu động vật thủy sản sống có kích thước dưới 6 cm, yêu cầu đặc biệt về nuôi tại địa điểm kiểm dịch là gì?",["Phải nuôi trong môi trường tự nhiên", "Phải nuôi trong bể riêng, đáp ứng điều kiện sinh học và vệ sinh", "Phải đông lạnh ngay khi nhập", "Không có yêu cầu đặc biệt"],1,"Đoạn mô tả trong Điều 13 (phần c) nêu rõ động vật thủy sản sống dưới 6 cm phải được nuôi riêng trong bể, đảm bảo điều kiện sinh học và vệ sinh để tránh lây lan dịch bệnh.",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, đối tượng nào sau đây được quy định phải lấy mẫu xét nghiệm bệnh khi nhập khẩu?",["A. Động vật thủy sản dùng làm giống", "B. Động vật thủy sản thương phẩm khi phát hiện dấu hiệu bệnh", "C. Sản phẩm động vật thủy sản không có dấu hiệu bệnh", "D. Tất cả các loại hàng nhập khẩu đều phải lấy mẫu"],1,"Theo khoản 5.16(b) của Thông tư 26/2016, đối với động vật thủy sản thương phẩm chỉ lấy mẫu xét nghiệm bệnh khi phát hiện dấu hiệu bệnh. Đối với động vật dùng làm giống thì luôn phải lấy mẫu xét nghiệm bệnh (khoản 5.16(a)).",1);
  add(5,"Thời gian tối đa được phép kiểm dịch đối với động vật thủy sản dùng làm giống là:",["A. 5 ngày", "B. 10 ngày", "C. 15 ngày", "D. 30 ngày"],1,"Theo khoản 5.16(d), thời gian kiểm dịch không quá 10 ngày đối với động vật thủy sản dùng làm giống.",1);
  add(5,"Khi không thể lấy mẫu xét nghiệm tại cửa khẩu, cơ quan kiểm dịch phải thực hiện lấy mẫu tại:",["A. Nhà máy chế biến", "B. Kho bảo quản", "C. Nơi xuất xứ của hàng hóa", "D. Văn phòng sở thú"],1,"Trong đoạn văn, nêu rõ \"trường hợp không thể lấy mẫu tại cửa khẩu hoặc tại nơi tập kết hàng, cơ quan kiểm dịch của khẩu thực hiện lấy mẫu kiểm dịch tại kho bảo quản\" (khoản 5.16).",2);
  add(5,"Thời gian lấy mẫu và cấp Giấy chứng nhận kiểm dịch cho sản phẩm động vật thủy sản (đối tượng phải lấy mẫu) là:",["A. 1 ngày làm việc", "B. 3 ngày làm việc", "C. 5 ngày làm việc", "D. 7 ngày làm việc"],2,"Khoản 5.18(a) quy định: \"trong thời gian 05 ngày làm việc khi bắt đầu kiểm dịch, cơ quan kiểm dịch cấp Giấy chứng nhận kiểm dịch\" cho đối tượng phải lấy mẫu.",2);
  add(5,"Đối với sản phẩm động vật thủy sản không cần lấy mẫu xét nghiệm, thời gian tối đa để cơ quan kiểm dịch cấp Giấy chứng nhận là:",["A. 1 ngày làm việc", "B. 3 ngày làm việc", "C. 5 ngày làm việc", "D. 7 ngày làm việc"],0,"Theo khoản 5.18(b), đối với đối tượng không phải lấy mẫu, thời gian thực hiện kiểm dịch và cấp Giấy chứng nhận là 01 ngày làm việc.",2);
  add(5,"Nếu thời gian kiểm dịch vượt quá thời gian quy định (ví dụ: hơn 10 ngày đối với động vật dùng làm giống), cơ quan kiểm dịch phải:",["A. Tự quyết định kéo dài mà không báo cáo", "B. Thông báo bằng văn bản cho chủ hàng và nêu rõ lý do", "C. Hủy bỏ giấy chứng nhận đã cấp", "D. Đưa hàng hóa trả lại cho nước xuất khẩu"],1,"Khoản 5.16(d) nêu rằng nếu thời gian kiểm dịch kéo dài hơn thời gian quy định, cơ quan kiểm dịch phải thông báo bằng văn bản cho chủ hàng và nêu rõ lý do.",3);
  add(5,"Trách nhiệm chính của chủ hàng trong quá trình vận chuyển hàng động vật thủy sản nhập khẩu là:",["A. Đảm bảo điều kiện vệ sinh và chịu trách nhiệm bảo quản hàng cho đến khi giao cho cơ quan kiểm dịch", "B. Chỉ chịu trách nhiệm thanh toán phí kiểm dịch", "C. Không cần quan tâm đến điều kiện bảo quản nếu đã có Giấy chứng nhận kiểm dịch", "D. Chỉ chịu trách nhiệm khi hàng bị hư hỏng"],0,"Trong đoạn văn (phần d) nêu rõ \"Chủ hàng phải chịu trách nhiệm trong việc vận chuyển, bảo quản hàng hoá và không được đưa hàng tiêu thụ khi chưa có kết quả kiểm dịch\".",1);
  add(5,"Theo Thông tư 36/2018/TT-BNNPTNT, các khoản bổ sung được quy định ở Điều nào và Bảng nào?",["A. Điều 5, Bảng 2", "B. Điều 6, Bảng 1", "C. Điều 7, Bảng 3", "D. Điều 8, Bảng 4"],1,"Đoạn văn đề cập rằng \"bổ sung theo Điều 6, Bảng 1 của Thông tư 36/2018/TT-BNNPTNT\" (vị trí 17).",2);
  add(5,"Khi kiểm dịch động vật thủy sản dùng làm giống, thời gian tối thiểu để thực hiện kiểm dịch tại cơ quan kiểm dịch là:",["A. 1 ngày", "B. 3 ngày", "C. 5 ngày", "D. Không quy định thời gian tối thiểu"],2,"Khoản 5.18(a) quy định thời gian 05 ngày làm việc để thực hiện kiểm dịch và cấp Giấy chứng nhận đối với đối tượng phải lấy mẫu, trong đó bao gồm động vật dùng làm giống.",2);
  add(5,"Nếu trong quá trình kiểm dịch, phát hiện dấu hiệu bệnh ở động vật thủy sản thương phẩm, cơ quan kiểm dịch phải:",["A. Ngay lập tức trả lại hàng cho chủ hàng mà không cần lấy mẫu", "B. Lấy mẫu xét nghiệm bệnh và chỉ cấp Giấy chứng nhận nếu kết quả âm tính", "C. Cấp Giấy chứng nhận mà không cần xét nghiệm", "D. Đưa hàng về nước xuất khẩu"],1,"Theo khoản 5.16(c), đối với động vật thủy sản thương phẩm chỉ lấy mẫu xét nghiệm bệnh nếu phát hiện dấu hiệu bệnh; kết quả xét nghiệm quyết định việc cấp Giấy chứng nhận.",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, khi thông báo vi phạm kiểm dịch động vật, cơ quan kiểm dịch phải gửi thông báo bằng hình thức nào?",["Chỉ bằng thư bưu điện", "Bằng văn bản gửi qua điện tử hoặc fax, kèm giấy chứng nhận kiểm dịch, ngày cấp và số lượng hàng", "Bằng tin nhắn SMS tới người đại diện doanh nghiệp", "Bằng báo cáo qua hệ thống khai báo hải quan điện tử"],1,"Điều 16 của Thông tư 26/2016 quy định cơ quan kiểm dịch phải thông báo vi phạm bằng văn bản, gửi qua điện tử hoặc fax, kèm thông tin giấy chứng nhận kiểm dịch, ngày cấp và số lượng hàng. Các hình thức khác không được quy định.",1);
  add(5,"Sản phẩm động vật thuỷ sản nào sau đây **không** phải thực hiện kiểm dịch khi nhập khẩu?",["Sản phẩm đã hoàn thành thủ tục kiểm dịch nhập khẩu, chưa được mở bao bì hoặc tái đóng gói lại", "Sản phẩm có nguồn gốc trong nước, xuất bán cho doanh nghiệp xuất khẩu, chưa thực hiện kiểm dịch xuất khẩu", "Sản phẩm chưa được khai báo trước và không có giấy chứng nhận kiểm dịch", "Sản phẩm đã qua xử lý nhiệt đủ tiêu chuẩn an toàn thực phẩm"],0,"Theo Bảng 13a, mục 1, sản phẩm đã hoàn thành thủ tục kiểm dịch nhập khẩu, chưa mở bao bì hoặc tái đóng gói lại khi xuất nhập khẩu không phải thực hiện kiểm dịch lại.",1);
  add(5,"Số lượng tối đa các hạng mục vi phạm được nêu trong thông báo vi phạm kiểm dịch động vật là:",["10 hạng mục", "12 hạng mục", "16 hạng mục", "20 hạng mục"],2,"Điều 16 quy định rằng cơ quan kiểm dịch có thể liệt kê tối đa 16 hạng mục vi phạm trong một thông báo.",1);
  add(5,"Sau khi nhận được thông báo vi phạm, trách nhiệm chính của chủ hàng là:",["Lập biên bản thanh lý hợp đồng với nhà cung cấp", "Thực hiện xử lý các vi phạm theo hướng dẫn của cơ quan kiểm dịch trong thời hạn quy định", "Yêu cầu cơ quan kiểm dịch hủy bỏ thông báo vi phạm", "Chỉ cần thông báo cho khách hàng mà không cần thực hiện bất kỳ biện pháp nào"],1,"Điều 16 quy định chủ hàng có trách nhiệm thực hiện xử lý các vi phạm theo hướng dẫn của cơ quan kiểm dịch trong thời hạn quy định.",2);
  add(5,"Để đăng ký kiểm dịch động vật thuỷ sản, doanh nghiệp phải nộp hồ sơ qua tài khoản nào của Thông tư 26/2016?",["Tài khoản 1", "Tài khoản 3", "Tài khoản 4", "Tài khoản 7"],2,"Theo Điều 4 của Thông tư 26/2016, việc đăng ký kiểm dịch phải được thực hiện qua tài khoản 4 của hệ thống điện tử.",2);
  add(5,"Cơ quan kiểm dịch động vật của khẩu (CQT) thực hiện các công việc nào sau đây trong quy trình kiểm dịch xuất nhập khẩu?",["Chỉ cấp giấy chứng nhận kiểm dịch cho doanh nghiệp", "Gửi hướng dẫn kiểm dịch cho chủ hàng, tiếp nhận hồ sơ khai báo kiểm dịch, và thực hiện kiểm dịch theo Điều 49 Luật Thú y", "Quản lý toàn bộ chuỗi cung ứng từ nuôi trồng đến tiêu thụ cuối cùng", "Thực hiện kiểm nghiệm nước và môi trường sản xuất"],1,"Điều 49 Luật Thú y và Điều 4, 7 của Thông tư 26/2016 quy định CQT gửi hướng dẫn, tiếp nhận hồ sơ và thực hiện kiểm dịch theo quy định.",2);
  add(5,"Kiểm dịch tạm xuất được thực hiện theo quy định nào sau đây?",["Theo quy định về kiểm dịch xuất khẩu", "Theo quy định về kiểm dịch nhập khẩu", "Theo quy định về kiểm dịch nội địa", "Không có quy định cụ thể"],0,"Điều 16 của Thông tư 26/2016 nêu rõ kiểm dịch tạm xuất thực hiện theo quy định về kiểm dịch xuất khẩu.",1);
  add(5,"Thông tư 36/2018/TT-BNNPTNT được ban hành vào ngày nào?",["30/06/2016", "25/12/2018", "28/07/2022", "10/02/2019"],1,"Thông tư 36/2018/TT-BNNPTNT được công bố ngày 25/12/2018, theo nội dung văn bản.",1);
  add(5,"Trong trường hợp hàng hóa động vật thuỷ sản cần kiểm dịch trước khi xuất kho ngoại quan, doanh nghiệp phải:",["Gửi giấy chứng nhận kiểm dịch cho cơ quan hải quan và chờ duyệt", "Nộp 01 bản hồ sơ đăng ký kiểm dịch qua tài khoản 4, sau đó gửi bản gốc hoặc bản sao qua điện tử/fax cho cơ quan kiểm dịch, và chờ cơ quan thực hiện kiểm dịch theo Điều 49 Luật Thú y", "Chỉ cần khai báo trên hệ thống khai báo hải quan mà không cần kiểm dịch", "Thực hiện kiểm dịch nội bộ và tự cấp giấy chứng nhận"],1,"Theo Điều 4, 7 và 49 Luật Thú y, quy trình yêu cầu doanh nghiệp nộp hồ sơ qua tài khoản 4, gửi bản sao qua điện tử/fax cho CQT, sau đó CQT thực hiện kiểm dịch và cấp giấy chứng nhận.",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, hồ sơ khai báo kiểm dịch có thể được gửi cho cơ quan kiểm dịch qua các hình thức nào?",["Chỉ qua bưu điện", "Qua công thông tin một quốc gia, dịch vụ bưu chính, fax, email", "Qua mạng xã hội", "Qua điện thoại"],1,"Điều 2, Khoản 1 của Thông tư 26/2016 quy định rằng hồ sơ khai báo kiểm dịch có thể được gửi qua công thông tin một quốc gia, dịch vụ bưu chính, fax hoặc email (thư điện tử).",1);
  add(5,"Trước khi hàng nhập khẩu vào kho ngoại quan, chủ hàng phải nộp hồ sơ khai báo kiểm dịch cho cơ quan nào?",["Cơ quan kiểm dịch của tỉnh", "Cơ quan kiểm dịch của khâu", "Cơ quan kiểm dịch của cảng", "Cơ quan kiểm dịch của Bộ Nông nghiệp và Phát triển nông thôn"],1,"Khoản 3, Điều 4 của Thông tư 26/2016 quy định rằng khi hàng đến cửa khẩu, chủ hàng phải gửi hồ sơ khai báo kiểm dịch cho cơ quan kiểm dịch của khâu (cơ quan kiểm dịch của khâu hải quan).",1);
  add(5,"Khi xuất hàng ra khỏi kho ngoại quan, tài liệu nào phải được nộp cho cơ quan kiểm dịch khâu?",["Giấy chứng nhận kiểm dịch gốc", "Hóa đơn thương mại", "Phiếu xuất kho", "Bản sao CMND của người đại diện"],0,"Khoản 7, Điều 4 của Thông tư 26/2016 quy định rằng trước khi xuất hàng ra kho ngoại quan, chủ hàng phải gửi hồ sơ khai báo kiểm dịch, trong đó có Giấy chứng nhận kiểm dịch gốc.",2);
  add(5,"Đối tượng áp dụng kiểm dịch động vật và sản phẩm động vật thủy sản theo Thông tư 36/2018/TT-BNNPTNT là:",["Chỉ cá tươi nhập khẩu", "Tất cả các loại động vật và sản phẩm động vật thủy sản nhập khẩu, xuất khẩu và nội địa", "Chỉ sản phẩm chế biến", "Chỉ vật nuôi trong nước"],1,"Điều 1 của Thông tư 36/2018 quy định phạm vi áp dụng đối với mọi động vật và sản phẩm động vật thủy sản, bao gồm nhập khẩu, xuất khẩu và thương mại nội địa.",1);
  add(5,"Nếu chủ hàng đăng ký kiểm dịch qua dịch vụ bưu chính, hồ sơ gốc phải được gửi theo hình thức nào?",["Chỉ qua fax", "Chỉ qua thư điện tử", "Chỉ qua bưu điện", "Fax sau đó gửi hồ sơ gốc hoặc gửi trực tiếp (true tiep)"],3,"Trong nội dung Thông tư 26/2016, Khoản 2 nêu rõ rằng khi đăng ký kiểm dịch qua dịch vụ bưu chính, người nộp phải fax hồ sơ và sau đó gửi hồ sơ gốc hoặc gửi trực tiếp (true tiep) cho cơ quan kiểm dịch.",2);
  add(5,"Khi hàng nhập khẩu vào kho ngoại quan, cơ quan kiểm dịch phải phối hợp với cơ quan nào để thực hiện kiểm tra thực trạng hàng?",["Cục Hải quan", "Cơ quan thuế", "Cơ quan hải quan và cơ quan kiểm dịch", "Cơ quan y tế"],2,"Khoản 5, Điều 5 của Thông tư 26/2016 quy định rằng cơ quan kiểm dịch khâu hải quan phải phối hợp với cơ quan hải quan để thực hiện kiểm tra thực trạng hàng nhập khẩu.",2);
  add(5,"Vi phạm không nộp hồ sơ khai báo kiểm dịch đúng thời hạn sẽ bị xử lý như thế nào?",["Phạt tiền", "Tịch thu hàng", "Cấm nhập khẩu trong 6 tháng", "Cả A và B"],3,"Điều 45 Luật Thú y và các khoản xử phạt trong Thông tư 26/2016 quy định rằng người vi phạm không nộp hồ sơ khai báo kiểm dịch đúng thời hạn có thể bị phạt tiền và/hoặc tịch thu hàng.",3);
  add(5,"Nếu hàng nhập khẩu là “đồ ăn cho thú” (đồ ăn cho vật nuôi), quy định kiểm dịch áp dụng dựa trên điều nào?",["Kiểm dịch theo Điều 7 Thông tư 26/2016", "Kiểm dịch theo Điều 12 Thông tư 36/2018", "Kiểm dịch theo Khoản 4 Điều 49 Luật Thú y", "Không cần kiểm dịch"],2,"Khoản 4, Điều 49 Luật Thú y quy định rằng đồ ăn cho thú (đồ ăn cho vật nuôi) là đối tượng phải kiểm dịch trước khi nhập khẩu, xuất khẩu hoặc lưu thông nội địa.",3);
  add(5,"Khi xuất khẩu động vật, sản phẩm động vật thủy sản mang theo người hoặc gửi qua đường bưu điện, chủ hàng phải gửi hồ sơ đăng ký kiểm dịch xuất khẩu đến cơ quan nào?",["Cục Thú y", "Cơ quan kiểm dịch động vật cửa khẩu", "Chi cục Thú y vùng", "Sở Nông nghiệp và Phát triển nông thôn"],1,"Theo Khoản 1, Biểu 19, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), chủ hàng gửi 01 bộ hồ sơ đăng ký kiểm dịch xuất khẩu đến cơ quan kiểm dịch động vật cửa khẩu.",1);
  add(5,"Khi kiểm dịch sản phẩm động vật thủy sản xuất khẩu mang theo người hoặc gửi qua đường bưu điện, cơ quan kiểm dịch động vật cửa khẩu thực hiện những nội dung nào?",["Kiểm tra lâm sàng, lấy mẫu xét nghiệm các bệnh", "Kiểm tra cảm quan, lấy mẫu xét nghiệm các chỉ tiêu vệ sinh thú y", "Kiểm tra điều kiện nuôi nhốt", "Kiểm tra Giấy chứng nhận kiểm dịch của nước nhập khẩu"],1,"Theo Điểm b, Khoản 2, Biểu 19, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), đối với sản phẩm động vật thủy sản, cơ quan kiểm dịch thực hiện kiểm tra cảm quan, lấy mẫu xét nghiệm các chỉ tiêu vệ sinh thú y theo yêu cầu của chủ hàng hoặc nước nhập khẩu.",1);
  add(5,"Đối với động vật, sản phẩm động vật thủy sản nhập khẩu mang theo người, gửi qua đường bưu điện không vì mục đích kinh doanh, chủ hàng gửi hồ sơ khai báo kiểm dịch nhập khẩu đến cơ quan nào?",["Cục Thú y", "Chi cục Thú y vùng", "Cơ quan kiểm dịch động vật cửa khẩu", "Sở Nông nghiệp và Phát triển nông thôn"],2,"Theo Khoản 1, Biểu 20, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), chủ hàng gửi 01 bộ hồ sơ khai báo kiểm dịch nhập khẩu đến cơ quan kiểm dịch động vật cửa khẩu.",1);
  add(5,"Trong thời hạn bao lâu kể từ ngày nhận được hồ sơ khai báo hợp lệ, cơ quan kiểm dịch động vật cửa khẩu phải thực hiện kiểm dịch đối với động vật, sản phẩm động vật thủy sản nhập khẩu mang theo người, gửi qua đường bưu điện?",["03 ngày làm việc", "05 ngày làm việc", "01 ngày làm việc", "07 ngày làm việc"],2,"Theo Khoản 2, Biểu 20, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), trong thời hạn 01 ngày làm việc, kể từ ngày nhận được hồ sơ khai báo hợp lệ, cơ quan kiểm dịch động vật cửa khẩu thực hiện kiểm dịch.",1);
  add(5,"Một lô hàng sản phẩm động vật thủy sản nhập khẩu mang theo người bị phát hiện có biểu hiện biến chất trong quá trình kiểm dịch tại cửa khẩu. Cơ quan kiểm dịch động vật cửa khẩu sẽ xử lý như thế nào?",["Cấp Giấy chứng nhận kiểm dịch nhập khẩu có điều kiện", "Yêu cầu chủ hàng tái chế sản phẩm", "Xử lý tiêu hủy hoặc trả về nước xuất khẩu", "Cho phép nhập khẩu sau khi xử lý nhiệt"],2,"Theo Điểm c, Khoản 2, Biểu 20, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), trường hợp phát hiện sản phẩm động vật thủy sản có biểu hiện biến chất thì xử lý tiêu hủy hoặc trả về nước xuất khẩu.",3);
  add(5,"Khi có yêu cầu vận chuyển mẫu bệnh phẩm thủy sản từ nước ngoài về Việt Nam hoặc từ Việt Nam ra nước ngoài, chủ hàng phải gửi đơn đăng ký kiểm dịch đến cơ quan nào?",["Cơ quan kiểm dịch động vật cửa khẩu", "Chi cục Thú y vùng", "Cục Thú y", "Sở Nông nghiệp và Phát triển nông thôn"],2,"Theo Khoản 1, Biểu 21, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), chủ hàng phải gửi 01 đơn đăng ký kiểm dịch đến Cục Thú y.",1);
  add(5,"Đơn đăng ký kiểm dịch vận chuyển mẫu bệnh phẩm thủy sản phải theo mẫu nào?",["Mẫu 01 TS", "Mẫu 06 TS", "Mẫu 03 TS", "Mẫu 05 TS"],1,"Theo Khoản 1, Biểu 21, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), đơn đăng ký kiểm dịch phải theo Mẫu 06 TS ban hành kèm theo Phụ lục V của Thông tư này.",1);
  add(5,"Một chủ hàng muốn xuất khẩu động vật thủy sản mang theo người. Ngoài việc kiểm tra lâm sàng, cơ quan kiểm dịch động vật cửa khẩu có thể yêu cầu thêm nội dung kiểm tra nào?",["Kiểm tra điều kiện bao gói sản phẩm", "Lấy mẫu xét nghiệm các bệnh theo yêu cầu của chủ hàng hoặc nước nhập khẩu", "Kiểm tra Giấy chứng nhận kiểm dịch của nước xuất khẩu", "Kiểm tra thực trạng hàng hóa"],1,"Theo Điểm a, Khoản 2, Biểu 19, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), đối với động vật thủy sản, cơ quan kiểm dịch kiểm tra lâm sàng, lấy mẫu xét nghiệm các bệnh theo yêu cầu của chủ hàng hoặc nước nhập khẩu.",2);
  add(5,"Khi kiểm dịch động vật thủy sản nhập khẩu mang theo người, cơ quan kiểm dịch động vật cửa khẩu sẽ kiểm tra những nội dung nào sau đây?",["Kiểm tra cảm quan và lấy mẫu xét nghiệm chỉ tiêu vệ sinh thú y", "Kiểm tra hồ sơ kiểm dịch và đối chiếu chủng loại", "Kiểm tra thực trạng hàng hóa và điều kiện nuôi nhốt động vật thủy sản", "Xử lý tiêu hủy nếu phát hiện biến chất"],2,"Theo Điểm b, Khoản 2, Biểu 20, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), cơ quan kiểm dịch sẽ kiểm tra thực trạng hàng hóa; điều kiện nuôi nhốt động vật thủy sản.",2);
  add(5,"Một cá nhân nhập khẩu một số loài thủy sản sống không vì mục đích kinh doanh. Trong quá trình kiểm dịch, cơ quan chức năng phát hiện loài thủy sản này không có trong Danh mục các loài thủy sản nhập khẩu thông thường. Cơ quan kiểm dịch sẽ xử lý như thế nào?",["Yêu cầu chủ hàng bổ sung giấy phép nhập khẩu đặc biệt", "Cho phép nhập khẩu nếu không có dấu hiệu bệnh", "Xử lý tiêu hủy hoặc trả về nước xuất khẩu", "Yêu cầu chủ hàng nuôi cách ly để theo dõi"],2,"Theo Điểm c, Khoản 2, Biểu 20, Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi, bổ sung bởi Thông tư số 06/2022/TT-BNNPTNT), trường hợp phát hiện loài thủy sản không có trong Danh mục các loài thủy sản nhập khẩu thông thường thì xử lý tiêu hủy hoặc trả về nước xuất khẩu.",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, trong thời hạn bao lâu sau khi nhận hồ sơ kiểm dịch động vật, cơ quan kiểm dịch phải cấp Giấy chứng nhận vận chuyển?",["Trong vòng 12 giờ làm việc", "Trong vòng 24 giờ làm việc", "Trong vòng 48 giờ làm việc", "Trong vòng 72 giờ làm việc"],1,"Điều 3, khoản a) của Thông tư 26/2016/TT-BNNPTNT quy định: \"Trong thời hạn 01 ngày làm việc, cơ quan kiểm dịch động vật cấp Giấy chứng nhận vận chuyển...\"",1);
  add(5,"Số lượng bản sao của Giấy chứng nhận vận chuyển phải được cấp theo Thông tư 26/2016/TT-BNNPTNT là bao nhiêu?",["1 bản (được giữ tại cơ quan kiểm dịch)", "2 bản (1 bản lưu tại cơ quan kiểm dịch, 1 bản gửi cho chủ hàng)", "3 bản (1 bản lưu tại cơ quan kiểm dịch, 1 bản gửi cho chủ hàng, 1 bản gửi cho người mua)", "4 bản (mỗi bên liên quan 1 bản)"],1,"Theo khoản b) Điều 3 Thông tư 26/2016/TT-BNNPTNT, \"Số lượng Giấy chứng nhận vận chuyển: 02 bản (01 bản lưu tại cơ quan kiểm dịch, 01 bản gửi chủ hàng)\".",1);
  add(5,"Ai chịu trách nhiệm kiểm tra, đánh giá năng lực và quyết định ủy quyền cho cơ quan quản lý chuyên ngành y tế cấp tỉnh thực hiện kiểm dịch?",["Cục Thú y", "Bộ Nông nghiệp và Phát triển Nông thôn", "Bộ Y tế", "Cục An toàn Thực phẩm"],0,"Điều 22, khoản a) Thông tư 26/2016/TT-BNNPTNT quy định: \"Cục Thú y kiểm tra, đánh giá năng lực và quyết định ủy quyền cho cơ quan quản lý chuyên ngành y tế cấp tỉnh thực hiện kiểm dịch...\"",2);
  add(5,"Theo Thông tư 36/2018/TT-BNNPTNT, thời điểm có hiệu lực thi hành của Thông tư này là ngày nào?",["Ngày 01/01/2019", "Ngày 10/02/2019", "Ngày 31/12/2018", "Ngày 01/03/2019"],1,"Điều 2, khoản 1 Thông tư 36/2018/TT-BNNPTNT nêu rõ: \"Thông tư này có hiệu lực thi hành kể từ ngày 10 tháng 02 năm 2019\".",1);
  add(5,"Trong trường hợp hồ sơ kiểm dịch không đáp ứng đầy đủ yêu cầu, Cục Thú y phải làm gì theo Thông tư 26/2016/TT-BNNPTNT?",["Cấp Giấy chứng nhận vận chuyển tạm thời trong 24 giờ", "Yêu cầu bổ sung hồ sơ và không cấp Giấy chứng nhận cho đến khi đủ", "Từ chối nhập khẩu và thông báo cho cơ quan hải quan", "Gửi hồ sơ cho Bộ Y tế để xem xét"],1,"Khoản b) Điều 3 quy định: \"Nếu trong thời hạn 01 ngày làm việc hồ sơ chưa đáp ứng yêu cầu, cơ quan kiểm dịch phải yêu cầu bổ sung và không cấp Giấy chứng nhận vận chuyển cho đến khi hồ sơ hợp lệ\".",2);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, ai là người chịu trách nhiệm cuối cùng về việc giao nhận và bảo quản mẫu bệnh phẩm trong quá trình vận chuyển?",["Cơ quan kiểm dịch động vật", "Chủ hàng (người xuất khẩu)", "Người nhận (người nhập khẩu)", "Cục Thú y"],1,"Khoản a) Điều 3 quy định: \"Cục Thú y kiểm tra, đánh giá năng lực và quyết định ủy quyền cho cơ quan quản lý... đồng thời chủ hàng phải chịu trách nhiệm giao nhận, bảo quản mẫu bệnh phẩm\".",2);
  add(5,"Trong trường hợp có vi phạm quy định về kiểm dịch động vật, hình thức xử phạt hành chính nào được quy định trong Thông tư 26/2016/TT-BNNPTNT?",["Cảnh cáo bằng văn bản", "Phạt tiền từ 5.000.000 đến 10.000.000 đồng", "Thu hồi Giấy chứng nhận vận chuyển và đình chỉ hoạt động kinh doanh trong 30 ngày", "Tất cả các hình thức trên"],3,"Điều 7 Thông tư 26/2016/TT-BNNPTNT liệt kê các hình thức xử phạt: cảnh cáo, phạt tiền, thu hồi giấy chứng nhận và đình chỉ hoạt động kinh doanh trong thời gian quy định.",3);
  add(5,"Một doanh nghiệp xuất khẩu tôm sống đã nhận được Giấy chứng nhận vận chuyển nhưng phát hiện mẫu bệnh phẩm bị nhiễm bệnh trong quá trình vận chuyển. Theo Thông tư 36/2018/TT-BNNPTNT, bước đầu tiên doanh nghiệp phải thực hiện là:",["Gửi mẫu bệnh phẩm mới để kiểm dịch lại", "Thông báo ngay cho Cục Thú y và cơ quan kiểm dịch để thực hiện kiểm dịch lại", "Tiếp tục giao hàng và chịu trách nhiệm sau khi nhận được phản hồi", "Đòi hoàn tiền từ người mua"],1,"Khoản a) Điều 9 Thông tư 36/2018/TT-BNNPTNT quy định: \"Khi phát hiện mẫu bệnh phẩm không đạt tiêu chuẩn, người xuất khẩu phải thông báo ngay cho Cục Thú y và cơ quan kiểm dịch để thực hiện kiểm dịch lại\".",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, các tài liệu nào phải được nộp kèm hồ sơ kiểm dịch khi đăng ký vận chuyển động vật?",["Giấy phép xuất khẩu và hợp đồng mua bán", "Giấy chứng nhận kiểm dịch y tế và giấy tờ liên quan đến bảo quản mẫu bệnh phẩm", "Bản sao CMND của người đại diện và giấy tờ thuế", "Chỉ cần giấy chứng nhận kiểm dịch y tế"],1,"Khoản a) Điều 3 nêu rõ: \"Kiểm tra văn bản chấp thuận của Cục Thú y và các giấy tờ khác có liên quan; tình trạng bao gói, bảo quản mẫu bệnh phẩm\".",2);
  add(5,"Thời gian hiệu lực của Thông tư 26/2016/TT-BNNPTNT được sửa đổi, bổ sung lần cuối vào ngày nào?",["Ngày 28/07/2022", "Ngày 11/09/2022", "Ngày 10/02/2019", "Ngày 31/01/2018"],0,"Trong đoạn trích có ghi: \"...điều khoản thi hành 31 Điều ... Thông tư 06/2022/TT-BNNPTNT ngày 28/7/2022...\" cho thấy sửa đổi, bổ sung cuối cùng được công bố ngày 28/07/2022.",1);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, cơ quan nào chịu trách nhiệm cấp Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu?",["Cơ quan kiểm dịch động vật cấp tỉnh", "Bộ Nông nghiệp và Phát triển nông thôn", "Sở Y tế địa phương", "Cơ quan hải quan"],0,"Điều 1, khoản 1 của Thông tư 26/2016/TT-BNNPTNT quy định: \"Cơ quan kiểm dịch động vật cấp tỉnh chịu trách nhiệm thực hiện kiểm dịch và cấp Giấy chứng nhận kiểm dịch cho động vật, sản phẩm động vật thủy sản nhập khẩu\".",1);
  add(5,"Thông tư 36/2018/TT-BNNPTNT thay thế Thông tư nào trước đây về kiểm dịch động vật, sản phẩm động vật thủy sản?",["Thông tư 06/2010/TT-BNNPTNT", "Thông tư 47/2010/TT-BNNPTNT", "Thông tư 32/2012/TT-BNNPTNT", "Thông tư 53/2010/TT-BNNPTNT"],0,"Điều 32 nêu rõ: \"Cụm từ ‘Cơ quan Thị trưởng …’ được thay thế bằng ‘Cơ quan Thị trưởng …’ theo quy định tại Điều 16 của Thông tư 36/2018/TT-BNNPTNT, thay thế Thông tư 06/2010/TT-BNNPTNT ngày 02/02/2010\".",1);
  add(5,"Cơ quan kiểm dịch động vật phải báo cáo thông tin về động vật và sản phẩm động vật thủy sản theo tần suất nào?",["Hàng ngày", "Hàng tuần", "Hàng tháng", "Hàng năm"],2,"Khoản b) Điều 2 của Thông tư 26/2016/TT-BNNPTNT quy định: \"Cơ quan kiểm dịch phải báo cáo theo tháng, quý, năm về thông tin động vật, sản phẩm động vật thủy sản\".",1);
  add(5,"Điều nào trong Thông tư 36/2018/TT-BNNPTNT quy định ngày có hiệu lực thi hành của Thông tư này?",["Điều 23", "Điều 24", "Điều 15", "Điều 30"],1,"Điều 24, khoản 1 nêu: \"Thông tư này có hiệu lực thi hành kể từ ngày 15 tháng 8 năm 2016\".",1);
  add(5,"Ai chịu trách nhiệm thanh toán chi phí kiểm dịch và chi phí tiêu hủy hàng không đạt yêu cầu theo Thông tư 36/2018/TT-BNNPTNT?",["Nhà nước", "Nhà nhập khẩu", "Cơ quan kiểm dịch", "Nhà xuất khẩu"],1,"Khoản a) Điều 5 quy định: \"Nhà nhập khẩu chịu trách nhiệm thực hiện các quy định của Thông tư này, thanh toán các chi phí kiểm dịch, xét nghiệm; các khoản chi phí thực tế cho việc xử lý, tiêu hủy hàng không đạt yêu cầu (nếu có)\".",1);
  add(5,"Trong trường hợp đơn vị kiểm dịch không đáp ứng yêu cầu, cơ quan nào có thẩm quyền tạm ngừng Giấy chứng nhận kiểm dịch?",["Sở Y tế tỉnh", "Bộ Nông nghiệp và Phát triển nông thôn", "Cơ quan kiểm dịch động vật cấp tỉnh", "Cơ quan hải quan"],2,"Điều 3, khoản b) quy định: \"Cơ quan kiểm dịch động vật cấp tỉnh có thẩm quyền quyết định tạm ngừng hoặc thu hồi Giấy chứng nhận kiểm dịch khi phát hiện vi phạm\".",2);
  add(5,"Tình huống: Công ty chế biến tôm nhận thông báo không đạt tiêu chuẩn QCVN 5:2015 về chất lượng nước. Theo Thông tư 36/2018/TT-BNNPTNT, bước đầu tiên công ty cần thực hiện là gì?",["Khiếu nại quyết định của cơ quan kiểm dịch trong vòng 5 ngày", "Ngừng hoạt động ngay lập tức", "Nộp kế hoạch khắc phục trong vòng 10 ngày", "Yêu cầu kiểm dịch lại mà không thực hiện bất kỳ biện pháp nào"],2,"Khoản b) Điều 5 quy định: \"Khi có vi phạm, đơn vị phải lập kế hoạch khắc phục, trình cơ quan kiểm dịch trong thời hạn không quá 10 ngày để được xem xét và cho phép tiếp tục hoạt động\". Do đó, công ty phải nộp kế hoạch khắc phục trong vòng 10 ngày.",3);
  add(5,"Điều khoản nào trong Thông tư 36/2018/TT-BNNPTNT nêu rõ việc thay thế các Thông tư cũ (06/2010, 47/2010, 53/2010…) bằng Thông tư hiện hành?",["Khoản 33", "Khoản 32", "Khoản 23", "Khoản 24"],1,"Khoản 32 của Thông tư 36/2018/TT-BNNPTNT ghi rõ: \"Các loại mẫu Giấy chứng nhận kiểm dịch … được thay thế theo quy định tại Điều 16 của Thông tư 36/2018, thay thế Thông tư 06/2010, Thông tư 47/2010, Thông tư 53/2010…\".",2);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT, loài động vật thủy sản nào sau đây thuộc diện phải kiểm dịch?",["Cá voi", "Tôm hùm đông lạnh nhập khẩu làm hàng mẫu thử nghiệm", "San hô dùng để trưng bày tại triển lãm", "Ốc hương làm nguyên liệu gia công xuất khẩu"],0,"Theo Phụ lục I, Mục A, I.9 của Thông tư 26/2016/TT-BNNPTNT, 'Động vật có vú sống dưới nước: Cá voi, hải cẩu, rái cá và các loài động vật có vú khác sống dưới nước' thuộc diện phải kiểm dịch. Các phương án còn lại (hàng mẫu thử nghiệm, trưng bày hội chợ/triển lãm, nguyên liệu gia công xuất khẩu) thuộc diện miễn kiểm dịch theo Phụ lục I, Mục B.",1);
  add(5,"Sản phẩm động vật thủy sản nào sau đây thuộc diện miễn kiểm dịch theo quy định của Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT?",["Sản phẩm cá ngừ tươi sống nhập khẩu để tiêu thụ nội địa", "Trứng cá tầm nhập khẩu làm giống", "Sản phẩm tôm đông lạnh nhập khẩu làm nguyên liệu để sản xuất xuất khẩu", "Mực ống ướp lạnh nhập khẩu lần đầu từ một quốc gia có nguy cơ dịch bệnh cao"],2,"Theo Phụ lục I, Mục B.2 của Thông tư 26/2016/TT-BNNPTNT, 'Sản phẩm động vật thủy sản nhập khẩu làm nguyên liệu để gia công xuất khẩu, sản xuất xuất khẩu' thuộc diện miễn kiểm dịch. Các phương án còn lại thuộc diện phải kiểm dịch hoặc phải phân tích nguy cơ.",1);
  add(5,"Theo Phụ lục II của Thông tư 26/2016/TT-BNNPTNT, trường hợp nào sau đây KHÔNG thuộc diện phải phân tích nguy cơ đối với động vật, sản phẩm động vật thủy sản?",["Có nguồn gốc từ quốc gia, vùng lãnh thổ lần đầu nhập khẩu vào Việt Nam", "Đã được nhập khẩu vào Việt Nam nhưng bị áp dụng biện pháp tạm ngừng hoặc cấm nhập khẩu để xem xét việc được nhập khẩu trở lại", "Phát hiện nhiễm đối tượng kiểm dịch động vật, sản phẩm động vật thủy sản của Việt Nam", "Sản phẩm động vật thủy sản nhập khẩu thuộc diện ngoại giao"],3,"Theo Phụ lục II, Mục 3 của Thông tư 26/2016/TT-BNNPTNT, các trường hợp a, b, c đều yêu cầu phân tích nguy cơ. Sản phẩm động vật thủy sản nhập khẩu thuộc diện ngoại giao được miễn kiểm dịch (Phụ lục I, Mục B.1), không phải là trường hợp phải phân tích nguy cơ.",2);
  add(5,"Một lô hàng ấu trùng tôm giống được nhập khẩu vào Việt Nam từ một quốc gia chưa từng xuất khẩu tôm giống sang Việt Nam trước đây. Theo Thông tư 26/2016/TT-BNNPTNT, lô hàng này sẽ thuộc diện nào?",["Miễn kiểm dịch hoàn toàn", "Chỉ cần kiểm dịch thông thường, không cần phân tích nguy cơ", "Phải kiểm dịch và bắt buộc phân tích nguy cơ", "Chỉ cần khai báo hải quan, không cần kiểm dịch"],2,"Theo Phụ lục II, Mục 1, 'Động vật thủy sản làm giống (bao gồm cả trứng, phôi, tinh trùng và ấu trùng của chúng)' thuộc diện phải phân tích nguy cơ. Đồng thời, Mục 3.a quy định 'Có nguồn gốc từ quốc gia, vùng lãnh thổ lần đầu nhập khẩu vào Việt Nam' là một trong các trường hợp phải phân tích nguy cơ. Do đó, lô hàng này phải kiểm dịch và bắt buộc phân tích nguy cơ.",3);
  add(5,"Theo Phụ lục I của Thông tư 26/2016/TT-BNNPTNT, nhóm động vật thủy sản nào sau đây được liệt kê cụ thể là đối tượng phải kiểm dịch?",["Hải miên", "Rắn biển", "Chim biển", "Thực vật thủy sinh"],0,"Theo Phụ lục I, Mục A, I.8 của Thông tư 26/2016/TT-BNNPTNT, 'Hải miên' được liệt kê cụ thể là động vật thủy sản thuộc diện phải kiểm dịch. Các phương án còn lại không được liệt kê trực tiếp trong danh mục này dưới dạng nhóm chính.",1);
  add(5,"Theo quy định tại Thông tư 26/2016/TT-BNNPTNT, động vật, sản phẩm động vật thủy sản nhập khẩu với mục đích nghiên cứu khoa học phải tuân thủ yêu cầu nào sau đây?",["Không phải phân tích nguy cơ và không cần thực hiện kiểm dịch nhập khẩu.", "Không phải phân tích nguy cơ nhưng phải thực hiện kiểm dịch nhập khẩu.", "Phải phân tích nguy cơ nhưng không cần thực hiện kiểm dịch nhập khẩu.", "Phải phân tích nguy cơ và phải thực hiện kiểm dịch nhập khẩu."],1,"Dẫn chiếu Mục 5, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Động vật, sản phẩm động vật quy định tại mục 1, 2 của Phụ lục này nhập khẩu với mục đích nghiên cứu khoa học không phải phân tích nguy cơ nhưng phải thực hiện việc kiểm dịch nhập khẩu.'",1);
  add(5,"Bệnh đốm trắng (White Spot Disease - WSD) trên giáp xác, một trong những bệnh thuộc danh mục kiểm dịch, do tác nhân nào gây ra?",["Taura syndrome virus (TSV)", "White spot syndrome virus (WSSV)", "Yellowhead complex virus (YHCV)", "Monodon baculovirus (MBV)"],1,"Dẫn chiếu Mục A.I.1, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Bệnh đốm trắng/White Spot Disease (WSD) do White spot syndrome virus (WSSV) gây ra.'",1);
  add(5,"Loài tôm nào được liệt kê là đối tượng cảm nhiễm chính của bệnh Hội chứng Taura (Taura Syndrome - TS) theo danh mục kiểm dịch?",["Tôm sú (Penaeus monodon)", "Tôm chân trắng (Litopenaeus vannamei)", "Tôm càng xanh (Macrobrachium rosenbergii)", "Tôm hùm (Panulirus spp)"],1,"Dẫn chiếu Mục A.I.2, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Hội chứng Taura/Taura Syndrome (TS) có loài cảm nhiễm là Tôm chân trắng (Litopenaeus vannamei), Các loại tôm he (Penaeus setiferus, P. schmitti, P. monodon, P. chinensis, P. japonicus, P. aztecus, P. duorarum và Metapenaeus ensis).'",1);
  add(5,"Bệnh nào sau đây KHÔNG được liệt kê cụ thể là bệnh thường gặp ở tôm sú (Penaeus monodon) theo danh mục kiểm dịch, mà thay vào đó là loài chung hơn hoặc giai đoạn cụ thể?",["Bệnh đốm trắng (WSD)", "Bệnh đầu vàng (YHD)", "Bệnh hoại tử gan tụy (HPD)", "Bệnh MBV"],2,"Dẫn chiếu Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT:\n- Mục A.I.1: Bệnh đốm trắng (WSD) cảm nhiễm tôm sú (Penaeus monodon).\n- Mục A.I.3: Bệnh đầu vàng (YHD) cảm nhiễm tôm sú (Penaeus monodon).\n- Mục A.I.4: Bệnh MBV cảm nhiễm tôm sú (Penaeus monodon).\n- Mục A.I.7: Bệnh hoại tử gan tụy (HPD) cảm nhiễm Tôm he (Penaeus spp) ở giai đoạn tôm giống. Mặc dù tôm sú là một loại tôm he, nhưng HPD không được liệt kê trực tiếp cho tôm sú như các bệnh còn lại.",2);
  add(5,"Tác nhân gây bệnh nấm ở tôm (Crayfish Plague) trên tôm càng nước ngọt là gì?",["Proteobacteria", "Aphanomyces astaci", "Baculoviral midgut gland necrosis virus (BMNV)", "Infectious Myonecrosis Virus (IMNV)"],1,"Dẫn chiếu Mục A.I.10, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Bệnh nấm ở tôm/Crayfish Plague do Aphanomyces astaci gây ra.'",1);
  add(5,"Bệnh phát sáng (Luminous Bacteria Disease) trên tôm sú, tôm chân trắng và tôm càng xanh do tác nhân nào gây ra?",["Rickettsia-like organism", "Vi khuẩn nhóm Luminescence Vibrio: Vibrio harveyi", "Vi khuẩn dạng sợi thuộc họ Cytophagcae", "Vi rút thuộc họ Parvoviridae"],1,"Dẫn chiếu Mục A.I.13, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Bệnh phát sáng/Luminous Bacteria Disease do Vi khuẩn nhóm Luminescence Vibrio: Vibrio harveyi gây ra.'",1);
  add(5,"Bệnh sữa trên tôm hùm (Milky Haemolymph Disease of Spiny Lobsters - MHD-SL) do tác nhân Rickettsia-like organism gây ra, ảnh hưởng đến loài nào?",["Tôm sú (Penaeus monodon)", "Tôm chân trắng (Litopenaeus vannamei)", "Tôm hùm (Panulirus spp)", "Tôm càng xanh (Macrobrachium rosenbergii)"],2,"Dẫn chiếu Mục A.I.14, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Bệnh sữa trên tôm hùm/Milky Haemolymph Disease of Spiny Lobsters (MHD-SL) do Rickettsia-like organism gây ra, ảnh hưởng đến Tôm hùm (Panulirus spp).'",1);
  add(5,"Các vi khuẩn dạng sợi thuộc họ Cytophagcae (như Leucothrix mucor, Cytophage sp, Flexibacter sp, Thiothrix sp, Flavobacterium sp) là tác nhân gây bệnh nào trên các loài giáp xác nuôi?",["Bệnh Rickettsia ở tôm he", "Bệnh run chân do Rickettsia ở cua", "Bệnh vi khuẩn dạng sợi ở giáp xác", "Hội chứng gây tự vong tôm bố mẹ"],2,"Dẫn chiếu Mục A.I.17, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Bệnh vi khuẩn dạng sợi ở giáp xác/Filamentous Bacterial Disease do Vi khuẩn dạng sợi thuộc họ Cytophagcae: Leucothrix mucor, Cytophage sp, Flexibacter sp, Thiothrix sp., Flavobacterium sp gây ra.'",1);
  add(5,"Hội chứng gây tự vong tôm bố mẹ (Spawner Mortality Syndrome) được xác định do tác nhân nào gây ra?",["Vi rút thuộc họ Baculoviridae", "Vi rút thuộc họ Parvoviridae", "Nấm Fusarium spp", "Các yếu tố vô sinh"],1,"Dẫn chiếu Mục A.I.18, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Hội chứng gây tự vong tôm bố mẹ/Spawner Mortality Syndrome do Vi rút thuộc họ Parvoviridae gây ra.'",1);
  add(5,"Bệnh đen mang trên tôm sú, tôm chân trắng và tôm hùm (Panulirus ornatus) có thể do những yếu tố nào gây ra?",["Chỉ do các yếu tố vô sinh.", "Chỉ do nấm Fusarium spp.", "Do vi rút thuộc họ Baculoviridae.", "Do các yếu tố vô sinh hoặc do nấm Fusarium spp."],3,"Dẫn chiếu Mục A.I.20, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Bệnh đen mang trên tôm sú, tôm chân trắng, tôm hùm (Panulirus ornatus) do các yếu tố vô sinh hoặc do nấm Fusarium spp.'",1);
  add(5,"Một công ty nhập khẩu mẫu tôm chân trắng (Litopenaeus vannamei) giống để nghiên cứu khả năng kháng bệnh đốm trắng (WSD) tại phòng thí nghiệm. Theo quy định về kiểm dịch, công ty này phải thực hiện thủ tục nào?",["Không cần phân tích nguy cơ và không cần kiểm dịch nhập khẩu.", "Phải phân tích nguy cơ nhưng không cần kiểm dịch nhập khẩu.", "Không cần phân tích nguy cơ nhưng phải thực hiện kiểm dịch nhập khẩu.", "Phải phân tích nguy cơ và phải thực hiện kiểm dịch nhập khẩu."],2,"Dẫn chiếu Mục 5, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Động vật, sản phẩm động vật quy định tại mục 1, 2 của Phụ lục này nhập khẩu với mục đích nghiên cứu khoa học không phải phân tích nguy cơ nhưng phải thực hiện việc kiểm dịch nhập khẩu.'",2);
  add(5,"Bệnh hoại tử cơ (Infectious Myonecrosis - IMN) chủ yếu cảm nhiễm trên các loài tôm nào theo danh mục kiểm dịch?",["Tôm sú (Penaeus monodon) và tôm càng xanh (Macrobrachium rosenbergii).", "Tôm chân trắng (Litopenaeus vannamei) và tôm sú (Penaeus monodon).", "Tôm hùm (Panulirus spp) và tôm sú (Penaeus monodon).", "Tôm he (Penaeus spp) ở giai đoạn tôm giống."],1,"Dẫn chiếu Mục A.I.12, Phụ lục ban hành kèm theo Thông tư số 26/2016/TT-BNNPTNT: 'Bệnh hoại tử cơ (Bệnh đục cơ)/Infectious Myonecrosis (IMN) có loài cảm nhiễm là Tôm chân trắng (Litopenaeus vannamei) (cảm nhiễm nhạy), tôm sú (P. monodon) ở tất cả các giai đoạn sinh trưởng.'",1);
  add(5,"Tác nhân gây bệnh hoại tử gan tụy cấp tính ở tôm nuôi (Acute Hepatopancreatic Necrosis Disease - AHPND) theo quy định tại Thông tư 26/2016/TT-BNNPTNT & 36/2018/TT-BNNPTNT là gì?",["Enterocytozoon hepatopenaei", "Vibrio parahaemolyticus có mang gen độc lực", "Epizootic haematopoietic necrosis virus (EHNV)", "Betanodavirus"],1,"Theo mục 21 của văn bản, bệnh hoại tử gan tụy cấp tính ở tôm nuôi (AHPND) có tác nhân gây bệnh là Vibrio parahaemolyticus có mang gen độc lực.",1);
  add(5,"Hai loài tôm nào sau đây được liệt kê là đối tượng cảm nhiễm của bệnh Vi bào tử trùng Enterocytozoon hepatopenaei (EHP) theo Thông tư 26/2016/TT-BNNPTNT & 36/2018/TT-BNNPTNT?",["Tôm sú (Penaeus monodon) và tôm chân trắng (Litopenaeus vannamei)", "Tôm hùm (Panulirus ornatus)", "Tôm càng xanh (Macrobrachium rosenbergii)", "Tôm sú (Penaeus monodon) và tôm càng xanh (Macrobrachium rosenbergii)"],0,"Theo mục 22 của văn bản, tôm sú (Penaeus monodon) và tôm chân trắng (Litopenaeus vannamei) là loài cảm nhiễm của bệnh Vi bào tử trùng Enterocytozoon hepatopenaei (EHP).",1);
  add(5,"Bệnh hoại tử cơ quan tạo máu do IHNV (Infectious Haematopoietic Necrosis disease - IHN) chủ yếu ảnh hưởng đến loài cá nào theo danh mục quy định?",["Cá chép (Cyprinus carpio) và cá trắm cỏ (Ctenopharyngodon idellus)", "Các loài cá hồi (Oncorhynchus spp) và cá hồi Đại Tây Dương (Salmo salar)", "Cá vược vây đỏ (Perca fluvitilis) và cá hồi vân (Oncorhynchus mykiss)", "Cá bơn (Scophthalmus maximus) và cá tuyết (Gadus macrocephahts)"],1,"Theo mục 2 của văn bản, bệnh hoại tử cơ quan tạo máu do IHNV (IHN) có loài cảm nhiễm là các loài cá hồi (Oncorhynchus spp) và cá hồi Đại Tây Dương (Salmo salar).",2);
  add(5,"Tác nhân gây bệnh xuất huyết mùa xuân ở cá chép (Spring Viraemia of Carp - SVC) được quy định là gì?",["Viral Haemorrhagic Septicaemia virus (VHSV)", "Spring viraemia of carp virus (SVCV)", "Koi Herpesvirus (KHV)", "Infectious Salmon anaemia virus (ISAV)"],1,"Theo mục 3 của văn bản, bệnh xuất huyết mùa xuân ở cá chép (SVC) có tác nhân gây bệnh là Spring viraemia of carp virus (SVCV).",1);
  add(5,"Loài cá nào sau đây *không* phải là đối tượng cảm nhiễm của bệnh do Koi Herpesvirus (KHV) theo quy định tại Thông tư 26/2016/TT-BNNPTNT & 36/2018/TT-BNNPTNT?",["Cá chép (Cyprinus carpio)", "Cá chép koi (C. carpio koi)", "Cá trắm cỏ (Ctenopharyngodon idellus)", "Cá diếc (Carassius carassius)"],2,"Theo mục 6 của văn bản, bệnh do KHV chỉ liệt kê cá chép (Cyprinus carpio) và cá chép koi (C. carpio koi) là loài cảm nhiễm. Cá trắm cỏ (Ctenopharyngodon idellus) không được liệt kê cho bệnh này.",2);
  add(5,"Bệnh hoại huyết cá hồi (Infectious Salmon Anaemia - ISA) do tác nhân nào gây ra?",["Betanodavirus", "Red seabream iridovirus", "Infectious Salmon anaemia virus (ISAV)", "Epizootic haematopoietic necrosis virus (EHNV)"],2,"Theo mục 7 của văn bản, bệnh hoại huyết cá hồi (ISA) có tác nhân gây bệnh là Infectious Salmon anaemia virus (ISAV).",1);
  add(5,"Tác nhân gây bệnh hoại tử thần kinh (Viral Nervous Necrosis - VNN) và một số loài cá cảm nhiễm điển hình được quy định như thế nào?",["Betanodavirus, ảnh hưởng đến cá chẽm con, cá vược châu Âu, cá bơn", "ISAV, ảnh hưởng đến các loài cá hồi", "VHSV, ảnh hưởng đến cá hồi và cá tuyết", "KHV, ảnh hưởng đến cá chép và cá chép koi"],0,"Theo mục 8 của văn bản, bệnh hoại tử thần kinh (VNN) có tác nhân gây bệnh là Betanodavirus và ảnh hưởng đến các loài như cá chẽm con, cá vược châu Âu, cá bơn.",2);
  add(5,"Một trại nuôi tôm sú và tôm thẻ chân trắng đang gặp tình trạng tôm chết hàng loạt với các dấu hiệu hoại tử gan tụy cấp tính. Theo Thông tư 26/2016/TT-BNNPTNT & 36/2018/TT-BNNPTNT, cơ quan kiểm dịch cần ưu tiên xét nghiệm tác nhân nào đầu tiên để chẩn đoán bệnh?",["Enterocytozoon hepatopenaei", "Vibrio parahaemolyticus có mang gen độc lực", "Epizootic haematopoietic necrosis virus (EHNV)", "Red seabream iridovirus (RSIV)"],1,"Dựa trên triệu chứng 'hoại tử gan tụy cấp tính' và loài 'tôm sú, tôm thẻ chân trắng', theo mục 21 của văn bản, bệnh Acute Hepatopancreatic Necrosis Disease (AHPND) do Vibrio parahaemolyticus có mang gen độc lực gây ra là phù hợp nhất để ưu tiên xét nghiệm.",3);
  add(5,"Cặp bệnh và tác nhân gây bệnh nào sau đây là *không đúng* theo quy định của Thông tư 26/2016/TT-BNNPTNT & 36/2018/TT-BNNPTNT?",["Bệnh hoại tử cơ quan tạo máu do EHNV - Epizootic haematopoietic necrosis virus (EHNV)", "Bệnh nhiễm trùng xuất huyết do vi rút (VHS) - Viral Haemorrhagic Septicaemia virus (VHSV)", "Bệnh do RSIV - Red seabream iridovirus", "Bệnh hoại huyết cá hồi (ISA) - Betanodavirus"],3,"Theo mục 7 của văn bản, bệnh hoại huyết cá hồi (ISA) do Infectious Salmon anaemia virus (ISAV) gây ra, không phải Betanodavirus. Betanodavirus là tác nhân gây bệnh hoại tử thần kinh (VNN) theo mục 8.",2);
  add(5,"Cá tráp đỏ (Pagrus major) là một trong những loài cảm nhiễm của bệnh nào sau đây theo danh mục quy định?",["Bệnh do KHV", "Bệnh hoại tử thần kinh (VNN)", "Bệnh do RSIV", "Bệnh xuất huyết mùa xuân ở cá chép (SVC)"],2,"Theo mục 5 của văn bản, cá tráp đỏ (Pagrus major) được liệt kê là một trong các loài cảm nhiễm của bệnh do RSIV (Red seabream iridoviral disease).",1);
  add(5,"Virus nào là nguyên nhân gây bệnh Infectious Pancreatic Necrosis (IPN) ở cá hồi?",["Infectious Pancreatic Necrosis Virus (IPNV)", "Viral Hemorrhagic Septicemia Virus (VHSV)", "Infectious Salmon Anemia Virus (ISAV)", "Spring Viraemia of Carp Virus (SVCV)"],0,"Trong văn bản, bệnh Infectious Pancreatic Necrosis (IPN) được liệt kê với tác nhân là Infectious Pancreatic Necrosis Virus (IPNV). Đây là đáp án duy nhất khớp với thông tin.",1);
  add(5,"Trong danh sách, loài cá nào được liệt kê là nhiễm bệnh Grass Carp Haemorrhagic Disease (GCHD) do Reovirus gây ra?",["Ca chép (Cyprinus carpio)", "Ca trắm cỏ (Ctenopharyngodon idella)", "Ca hồi (Oncorhynchus mykiss)", "Ca ngừ (Thunnus spp)"],1,"Văn bản ghi rõ \"Ca trắm cỏ (Ctenopharyngodon idella)\" là một trong các loài chịu ảnh hưởng của bệnh Grass Carp Haemorrhagic Disease (GCHD) do Reovirus.",1);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, tài liệu nào sau đây KHÔNG bắt buộc khi nhập khẩu cá sống để kiểm dịch?",["Giấy chứng nhận sức khỏe (Health Certificate)", "Giấy chứng nhận xuất xứ (Certificate of Origin)", "Giấy chứng nhận chất lượng nước (Water Quality Certificate)", "Giấy chứng nhận vận chuyển (Transport Certificate)"],2,"Thông tư 26/2016 quy định các giấy tờ bắt buộc gồm Giấy chứng nhận sức khỏe, xuất xứ và vận chuyển. Giấy chứng nhận chất lượng nước không nằm trong danh mục bắt buộc.",2);
  add(5,"Bệnh Bacterial Kidney Disease (BKD) ở cá hồi do vi khuẩn nào gây ra?",["Renibacterium salmoninarum", "Streptococcus iniae", "Edwardsiella ictaluri", "Flexibacter spp."],0,"Trong phần liệt kê bệnh, BKD được mô tả là \"Bacterial Kidney Disease of Fish (BKD)\" với tác nhân là Renibacterium salmoninarum.",1);
  add(5,"Bệnh nào trong danh sách được gây ra bởi Iridovirus?",["Spinning Tilapia Syndrome (STS)", "Gyrodactylosis", "Lymphocystis", "Dactylogyrosis"],2,"Bệnh Lymphocystis được ghi chú \"Iridovirus\" là tác nhân gây bệnh, trong khi các bệnh còn lại có tác nhân khác.",1);
  add(5,"Trong danh sách các loài cá, loài nào KHÔNG được nêu là nhiễm bệnh Flexibacter?",["Anguilla japonica", "Lates calcarifer", "Salmo trutta", "Clarias macrocephalus"],2,"Flexibacter disease được liệt kê cho các loài như Anguilla japonica, Lates calcarifer, Clarias macrocephalus, nhưng không có Salmo trutta trong danh sách.",2);
  add(5,"Bệnh Enteric Septicaemia of Catfish (ESC) do vi khuẩn nào gây ra?",["Edwardsiella ictaluri", "Streptococcus iniae", "Renibacterium salmoninarum", "Aeromonas hydrophila"],0,"Trong văn bản, ESC được mô tả với tác nhân \"Edwardsiella ictaluri\".",1);
  add(5,"Pathogen Perkinsus marinus gây ra bệnh gì?",["Infection with Perkinsus marinus ở hàu (Crassostrea spp)", "Infection with Perkinsus marinus ở nghêu", "Infection with Perkinsus marinus ở sò", "Infection with Perkinsus marinus ở bào ngư"],0,"Bảng liệt kê bệnh do Perkinsus marinus nêu rõ đây là bệnh \"Infection with Perkinsus marinus\" ở các loài hàu (Crassostrea spp).",1);
  add(5,"Theo Thông tư 36/2018/TT-BNNPTNT, thời gian tối đa được phép giữ cá sống nhập khẩu trước khi giải phóng sau khi không phát hiện bệnh là:",["24 giờ", "48 giờ", "72 giờ", "7 ngày"],1,"Thông tư 36/2018 quy định thời gian giữ cá sống để quan sát và kiểm dịch không vượt quá 48 giờ nếu không có dấu hiệu bệnh.",2);
  add(5,"Câu nào sau đây mô tả đúng về bệnh Gyrodactylosis?",["Do Gyrodactylus salaris gây ra", "Chỉ ảnh hưởng tới cá biển", "Lây truyền duy nhất qua nước", "Điều trị bằng kháng sinh"],0,"Trong danh sách, Gyrodactylosis (Gyrodactylus salaris) được nêu là bệnh do ký sinh trùng Gyrodactylus salaris gây ra; không giới hạn môi trường, không truyền qua nước duy nhất và không điều trị bằng kháng sinh.",1);
  add(5,"Bệnh nào do virus White Spot Syndrome Virus (WSSV) gây ra ở tôm?",["Vibrio parahaemolyticus", "White spot virus", "White Spot Syndrome Virus (WSSV)", "Taura syndrome virus"],2,"Theo phụ lục IV của Thông tư 26/2016/TT-BNNPTNT, bệnh White Spot Syndrome (WSSV) do White Spot Syndrome Virus gây ra, ảnh hưởng chính cho các loài tôm như Penaeus monodon và Litopenaeus vannamei.",1);
  add(5,"Loài tôm nào trong danh sách sau được liệt kê là chịu ảnh hưởng của Taura syndrome virus (TSV)?",["Penaeus monodon", "Litopenaeus vannamei", "Crassostrea gigas", "Scylla serrata"],1,"Trong bảng liệt kê bệnh Taura syndrome (TSV) của Thông tư 26/2016, loài tôm được nêu là chịu ảnh hưởng là Litopenaeus vannamei.",2);
  add(5,"Khi kiểm dịch động vật thuỷ sản, tài liệu nào phải được đính kèm theo Thông tư 26/2016/TT-BNNPTNT?",["Giấy chứng nhận xuất xứ", "Thông báo kiểm dịch", "Bản danh mục bệnh", "Bản sao hợp đồng mua bán"],1,"Theo Điều 8, Phụ lục IV của Thông tư 26/2016, khi thực hiện kiểm dịch, người nộp phải kèm theo Thông báo kiểm dịch (thông tin về nguồn gốc, loại bệnh, v.v.).",2);
  add(5,"Bệnh do Aeromonas hydrophila gây ra ở cá được gọi là:",["White Spot Disease", "Aeromonas septicemia", "Infectious hypodermal and hematopoietic necrosis", "Acute Hepatopancreatic Necrosis Disease (AHPND)"],1,"Trong mục V. BỆNH 6 LOẠI BỌC SÂU/ONG CÁ, Aeromonas hydrophila được nêu là nguyên nhân gây bệnh “White Spots Disease” (còn gọi là Aeromonas septicemia).",1);
  add(5,"Bệnh Acute Hepatopancreatic Necrosis Disease (AHPND) liên quan đến loại vi khuẩn nào?",["Vibrio parahaemolyticus sinh độc tố", "White spot virus", "Taura syndrome virus", "Infectious hypodermal and hematopoietic necrosis virus"],0,"Trong phụ lục IV, bệnh AHPND (Acute Hepatopancreatic Necrosis Disease) được mô tả là do các chủng Vibrio parahaemolyticus mang gen toxin gây ra.",2);
  add(5,"Trong danh sách, loại virus nào gây bệnh Ranavirus ở lưỡng cư?",["Batrachochytrium dendrobatidis", "Ranavirus", "Aeromonas hydrophila", "Vibrio parahaemolyticus"],1,"Phần IV. BỆNH OF BÓNG VẬT LÂU TRÌNH liệt kê Ranavirus là nguyên nhân gây bệnh Ranavirus ở các loài ếch (Rana spp).",1);
  add(5,"Bệnh Haplosporidiosis do tác nhân nào gây ra?",["Haplosporidium costale", "Marteilioides chungmuenis", "Iridovirus", "White spot virus"],0,"Trong mục IV. BỆNH HẠNG VẬT LÂU TRÌNH, Haplosporidium costale được ghi là tác nhân gây bệnh Haplosporidiosis.",1);
  add(5,"Trong các bệnh liệt kê cho giáp xác, bệnh nào không xuất hiện trong phụ lục?",["Infectious Myonecrosis Virus (IMNV)", "Yellow Head Virus (YHV)", "Infectious hypodermal and hematopoietic necrosis virus (IHHNV)", "Salmonella enterica infection"],3,"Phụ lục IV liệt kê các bệnh của giáp xác như IMNV, YHV, IHHNV, nhưng không có bệnh do Salmonella enterica, vì đây là bệnh vi khuẩn thuộc nhóm vi khuẩn gram‑Â‑.",1);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT, bệnh hoại tử thần kinh (Viral Nervous Necrosis) ở cá song/cá mú, cá vược/cá chẽm, cá giò/cá bớp do tác nhân nào gây ra?",["Betanodavirus", "Edwardsiella ictaluri", "Streptococcus", "Tilapia Lake virus (TiLV)"],0,"Theo Mục I, Bệnh ở loại cá, số thứ tự 3 của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT (được sửa đổi, bổ sung bởi Thông tư 36/2018/TT-BNNPTNT), bệnh hoại tử thần kinh (Viral Nervous Necrosis) do Betanodavirus gây ra trên các loài cá như cá song/cá mú (Epinephelus spp.), cá vược/cá chẽm (Lates calcarifer), cá giò/cá bớp (Rachycentron canadum).",1);
  add(5,"Đối với việc xét nghiệm các tác nhân gây bệnh, mẫu để xét nghiệm đối với từng tác nhân gây bệnh của mỗi lô hàng được lấy theo nguyên tắc nào?",["Mỗi mẫu là một cá thể riêng biệt", "Gộp 5 mẫu thành 01 mẫu để xét nghiệm", "Gộp 10 mẫu thành 01 mẫu để xét nghiệm", "Lấy ngẫu nhiên không theo nguyên tắc gộp mẫu"],1,"Theo Ghi chú 38 tại Mục I của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT (được sửa đổi, bổ sung bởi Thông tư 06/2022/TT-BNNPTNT), mẫu để xét nghiệm đối với từng tác nhân gây bệnh của lô hàng là mẫu gộp theo nguyên tắc 5 mẫu gộp thành 01 mẫu để xét nghiệm.",1);
  add(5,"Các cơ sở nuôi trồng thủy sản chưa được công nhận an toàn dịch bệnh hoặc chưa được giám sát dịch bệnh theo quy định phải thực hiện việc giám sát định kỳ bao lâu một lần?",["01 tháng 1 lần", "02 tháng 1 lần", "03 tháng 1 lần", "06 tháng 1 lần"],1,"Theo Mục II, Khoản 1 của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT, đối với các cơ sở nuôi trồng thủy sản chưa được công nhận an toàn dịch bệnh hoặc chưa được giám sát dịch bệnh theo quy định hoặc cơ sở thu gom, kinh doanh: Lấy mẫu giám sát định kỳ 02 tháng 1 lần để giám sát các chỉ tiêu bệnh.",1);
  add(5,"Trong trường hợp chủ cơ sở nuôi trồng thủy sản không thực hiện việc giám sát định kỳ theo quy định, cơ quan kiểm dịch động vật nội địa sẽ xử lý như thế nào?",["Yêu cầu chủ cơ sở tự thực hiện và báo cáo lại", "Lấy mẫu kiểm tra các chỉ tiêu theo từng lô hàng", "Áp dụng biện pháp xử phạt hành chính ngay lập tức", "Từ chối cấp giấy chứng nhận kiểm dịch cho lô hàng"],1,"Theo Mục II, Khoản 1 của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT, trường hợp chủ cơ sở không thực hiện việc giám sát định kỳ thì cơ quan kiểm dịch động vật nội địa lấy mẫu kiểm tra các chỉ tiêu theo từng lô hàng.",2);
  add(5,"Cơ quan kiểm dịch động vật nội địa cấp giấy chứng nhận kiểm dịch vận chuyển động vật thủy sản ra khỏi địa bàn cấp tỉnh dựa trên những căn cứ nào?",["Chỉ cần kiểm tra lâm sàng động vật khỏe mạnh", "Chỉ cần kết quả giám sát định kỳ mầm bệnh", "Kết quả giám sát định kỳ mầm bệnh và kiểm tra lâm sàng động vật khỏe mạnh, không mang mầm bệnh", "Giấy tờ chứng minh nguồn gốc xuất xứ của động vật"],2,"Theo Mục II, Khoản 3 của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT, căn cứ vào kết quả giám sát định kỳ mầm bệnh và kiểm tra lâm sàng động vật trước khi vận chuyển động vật giống thủy sản ra khỏi địa bàn cấp tỉnh, nếu động vật khỏe mạnh không mang mầm bệnh thì cơ quan kiểm dịch động vật nội địa cấp giấy chứng nhận kiểm dịch.",2);
  add(5,"Một cơ sở có đàn cá giống thủy sản gồm 100 con. Nếu tỷ lệ lưu hành bệnh ước đoán là 5%, theo bảng tính tỷ lệ lấy mẫu kiểm tra tác nhân gây bệnh, cần lấy bao nhiêu mẫu để xét nghiệm?",["46 mẫu", "37 mẫu", "23 mẫu", "20 mẫu"],2,"Dựa vào Bảng tính tỷ lệ lấy mẫu kiểm tra tác nhân gây bệnh đối với động vật thủy sản sống tại Mục III của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT: Với số con trong đàn là 100 và tỷ lệ lưu hành (%) là 5, số mẫu cần lấy là 23.",3);
  add(5,"Bệnh gan thận mủ ở cá da trơn (Enteric Septicaemia of Catfish) ảnh hưởng đến các loài cá nào và do tác nhân nào gây ra?",["Cá chép, cá chép koi; do Koi Herpesvirus (KHV)", "Cá rô phi; do Streptococcus", "Cá tra, cá ba sa, cá bông lau; do Edwardsiella ictaluri", "Cá song, cá vược; do Betanodavirus"],2,"Theo Mục I, Bệnh ở loại cá, số thứ tự 4 của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT, bệnh gan thận mủ ở cá da trơn (Enteric Septicaemia of Catfish) do Edwardsiella ictaluri gây ra trên các loài cá như cá tra (Pangasius hypophthalmus), cá ba sa (Pangasius bocourti), cá bông lau (Pangasius krempfi).",1);
  add(5,"Bệnh do Perkinsus ở loài nhuyễn thể được gây ra bởi những tác nhân nào và ảnh hưởng đến những loài nào?",["Vibrio parahaemolyticus; trên tôm", "Perkinsus marinus, P. olseni; trên tu hài, tiêu cua sông, nghêu, ngao", "Betanodavirus; trên cá song, cá vược", "Edwardsiella ictaluri; trên cá tra, cá ba sa"],1,"Theo Mục I, Bệnh ở loại nhuyễn thể, số thứ tự 1 của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT (được bổ sung bởi Thông tư 36/2018/TT-BNNPTNT), bệnh do Perkinsus do Perkinsus marinus, P. olseni gây ra trên các loài như tu hài (Lutraria philipinarum), tiêu cua sông (Crasostrea rivularis), nghêu, ngao (Meretrix sp.).",1);
  add(5,"Số lượng mẫu lấy để kiểm tra, xét nghiệm các bệnh với tỷ lệ lưu hành là 10% được hướng dẫn theo quy định nào?",["Theo hướng dẫn tại Mục I của Phụ lục này", "Theo hướng dẫn tại Mục II của Phụ lục này", "Theo hướng dẫn tại Mục III của Phụ lục này", "Theo hướng dẫn của Tổ chức Thú y thế giới (OIE)"],2,"Theo Ghi chú 37 và Mục II, Khoản 2 của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT (được sửa đổi, bổ sung bởi Thông tư 36/2018/TT-BNNPTNT), số lượng mẫu lấy để kiểm tra, xét nghiệm các bệnh với tỷ lệ lưu hành là 10% theo hướng dẫn tại Mục III của Phụ lục này.",1);
  add(5,"Một cơ sở có đàn cá giống thủy sản gồm 5.000 con. Nếu tỷ lệ lưu hành bệnh ước đoán là 2%, theo bảng tính tỷ lệ lấy mẫu kiểm tra tác nhân gây bệnh, cần lấy bao nhiêu mẫu để xét nghiệm?",["145 mẫu", "96 mẫu", "71 mẫu", "57 mẫu"],0,"Dựa vào Bảng tính tỷ lệ lấy mẫu kiểm tra tác nhân gây bệnh đối với động vật thủy sản sống tại Mục III của Phụ lục ban hành kèm theo Thông tư 26/2016/TT-BNNPTNT: Với số con trong đàn là 5.000 và tỷ lệ lưu hành (%) là 2, số mẫu cần lấy là 145.",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT, bệnh nào sau đây thường gặp ở tôm he (Litopenaeus spp., Penaeus spp.)?",["Bệnh đốm trắng (White Spot Disease)", "Bệnh sữa trên tôm hùm (Lobster Milky Disease - LMD)", "Bệnh xuất huyết mùa xuân ở cá chép (Spring viraemia of carp)", "Bệnh hoại tử tuyến tụy do salmonid alphavirus"],0,"Theo Mục I, Phần B, Điểm 5 của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, bệnh Đốm trắng (White Spot Disease) với tác nhân White spot syndrome virus (WSSV) là bệnh thường gặp ở tôm he (Litopenaeus spp., Penaeus spp.).",1);
  add(5,"Tác nhân gây bệnh Đốm trắng (White Spot Disease) được quy định trong Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT là gì?",["White spot syndrome virus (WSSV)", "Yellow head virus genotype I (YHV1)", "Taura syndrome virus (TSV)", "Infectious Hypodermal and Hematopoitic Necrosis Virus (IHHNV)"],0,"Theo Mục I, Phần B, Điểm 5 của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, tác nhân gây bệnh Đốm trắng (White Spot Disease) là White spot syndrome virus (WSSV).",1);
  add(5,"Một lô hàng thủy sản nhập khẩu được kiểm tra và có kết quả xét nghiệm của 03 lô hàng liên tiếp đều đạt yêu cầu. Theo quy định tại Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT, tần suất lấy mẫu cho các lô hàng tiếp theo sẽ được áp dụng như thế nào?",["Cứ 03 lô hàng tiếp theo sẽ lấy mẫu của 01 lô để xét nghiệm.", "Cứ 05 lô hàng tiếp theo chỉ lấy mẫu ngẫu nhiên của 01 lô hàng để xét nghiệm.", "Không cần lấy mẫu xét nghiệm cho các lô hàng tiếp theo.", "Tất cả các lô hàng tiếp theo đều phải lấy mẫu xét nghiệm."],1,"Theo Mục II, Điểm 1a của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, nếu kết quả xét nghiệm của 03 lô hàng liên tiếp đạt yêu cầu, cứ 05 lô hàng tiếp theo chỉ lấy mẫu ngẫu nhiên của 01 lô hàng để xét nghiệm.",2);
  add(5,"Sau khi 03 lô hàng thủy sản liên tiếp đạt yêu cầu và cơ quan kiểm dịch đã chuyển sang chế độ lấy mẫu ngẫu nhiên 01 lô trong 05 lô tiếp theo. Tuy nhiên, lô hàng được lựa chọn kiểm tra có kết quả xét nghiệm không đạt yêu cầu. Cơ quan kiểm dịch sẽ áp dụng tần suất lấy mẫu như thế nào tiếp theo?",["Tiếp tục lấy mẫu ngẫu nhiên của 01 lô hàng trong 05 lô tiếp theo.", "Lấy mẫu của 03 lô hàng liên tiếp để xét nghiệm.", "Tạm dừng nhập khẩu các lô hàng tiếp theo cho đến khi có thông báo mới.", "Chỉ kiểm tra hồ sơ mà không lấy mẫu xét nghiệm."],1,"Theo Mục II, Điểm 1a của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, trường hợp lô hàng được lựa chọn kiểm tra có kết quả xét nghiệm không đạt yêu cầu, cơ quan kiểm dịch sẽ lấy mẫu của 03 lô hàng liên tiếp để xét nghiệm.",2);
  add(5,"Một lô hàng thủy sản nhập khẩu có kết quả xét nghiệm không đạt yêu cầu ngay từ lô đầu tiên. Theo quy định, cơ quan kiểm dịch sẽ thực hiện lấy mẫu như thế nào cho các lô hàng tiếp theo?",["Ngừng kiểm dịch và yêu cầu tái xuất hoặc tiêu hủy lô hàng.", "Chỉ kiểm tra hồ sơ của 03 lô hàng liên tiếp tiếp theo.", "Tiếp tục lấy mẫu của 03 lô hàng liên tiếp để xét nghiệm.", "Tăng tần suất lấy mẫu lên 100% cho tất cả các lô hàng tiếp theo."],2,"Theo Mục II, Điểm 1b của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, nếu kết quả xét nghiệm của 01 lô hàng không đạt yêu cầu, cơ quan kiểm dịch tiếp tục lấy mẫu của 03 lô hàng liên tiếp để xét nghiệm.",2);
  add(5,"Đối với lô hàng thủy sản nhập khẩu chỉ có một mặt hàng, cơ quan kiểm dịch sẽ lấy mẫu và xử lý mẫu như thế nào để xét nghiệm các chỉ tiêu tác nhân gây bệnh?",["Lấy 01 mẫu để xét nghiệm.", "Lấy 03 mẫu và gộp thành 01 mẫu để xét nghiệm.", "Lấy 05 mẫu và gộp thành 01 mẫu để xét nghiệm.", "Lấy 05 mẫu và xét nghiệm riêng lẻ từng mẫu."],2,"Theo Mục II, Điểm 2a của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, lô hàng có một mặt hàng: lấy 05 (năm) mẫu và gộp thành 01 (một) mẫu để xét nghiệm các chỉ tiêu tác nhân gây bệnh.",2);
  add(5,"Một lô hàng thủy sản nhập khẩu có nhiều mặt hàng khác nhau. Quy định về việc lấy mẫu để xét nghiệm được thực hiện như thế nào?",["Lấy mẫu từ tất cả các mặt hàng có trong lô hàng.", "Lựa chọn mặt hàng có số lượng lớn hơn để lấy mẫu, tối đa 03 mặt hàng.", "Chỉ lấy mẫu từ mặt hàng có giá trị kinh tế cao nhất.", "Cơ quan kiểm dịch cửa khẩu sẽ tự quyết định số lượng mặt hàng cần lấy mẫu."],1,"Theo Mục II, Điểm 2b của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, lô hàng có nhiều mặt hàng: lựa chọn mặt hàng có số lượng lớn hơn để lấy mẫu theo điểm a khoản này, lấy mẫu tối đa của 03 mặt hàng. Trường hợp các mặt hàng của lô hàng có số lượng bằng nhau, cơ quan kiểm dịch động vật của khẩu lựa chọn ngẫu nhiên mặt hàng để lấy mẫu.",2);
  add(5,"Một doanh nghiệp nhập khẩu sản phẩm thủy sản không thuộc danh mục các loài thủy sản và bệnh quy định tại Mục I (Phần B) của Thông tư. Cơ quan kiểm dịch cửa khẩu sẽ thực hiện kiểm tra như thế nào đối với 03 lô hàng liên tiếp đầu tiên?",["Chỉ kiểm tra hồ sơ kiểm dịch mà không kiểm tra thực trạng hàng hóa.", "Kiểm tra thực trạng hàng hóa của 03 lô hàng liên tiếp và áp dụng tần suất lấy mẫu như quy định tại Điểm 1a và 1b Mục này.", "Kiểm tra hồ sơ kiểm dịch và thực trạng hàng hóa của 03 lô hàng liên tiếp, sau đó áp dụng quy định về tần suất lấy mẫu như Điểm 1a và 1b Mục này.", "Yêu cầu doanh nghiệp cung cấp chứng nhận không thuộc danh mục bệnh để được miễn kiểm tra."],2,"Theo Mục II, Điểm 3a của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, đối với sản phẩm được lấy từ các hộ/loại thủy sản không thuộc mục I phần này (phần B), cơ quan kiểm dịch cửa khẩu kiểm tra hồ sơ kiểm dịch, thực trạng hàng hóa của 03 (ba) lô hàng liên tiếp và áp dụng như quy định tại điểm a và b khoản 1 mục này.",3);
  add(5,"Đối với sản phẩm thủy sản không thuộc danh mục tại Mục I (Phần B), trong quá trình kiểm tra hồ sơ và thực trạng hàng hóa của 03 lô hàng liên tiếp, cơ quan kiểm dịch phát hiện một lô hàng không đạt yêu cầu về ngoại quan. Biện pháp tiếp theo của cơ quan kiểm dịch là gì?",["Yêu cầu tái xuất hoặc tiêu hủy lô hàng ngay lập tức.", "Lấy mẫu kiểm tra các chỉ tiêu lý hóa, vi sinh vật gây hại, tác nhân gây bệnh theo quy định, tiêu chuẩn, quy chuẩn tương ứng của Việt Nam và quốc tế.", "Chỉ yêu cầu doanh nghiệp khắc phục lỗi ngoại quan và cho phép thông quan.", "Tăng cường kiểm tra hồ sơ cho các lô hàng tiếp theo mà không cần lấy mẫu."],1,"Theo Mục II, Điểm 3b của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, trường hợp phát hiện lô hàng không đạt yêu cầu về ngoại quan, cơ quan kiểm dịch sẽ lấy mẫu kiểm tra các chỉ tiêu lý hóa, vi sinh vật gây hại, tác nhân gây bệnh theo các quy định, tiêu chuẩn, quy chuẩn tương ứng của Việt Nam, quy định quốc tế.",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT, loài thủy sản nào sau đây là đối tượng của bệnh do virus Tilapia Lake (TiLV)?",["Cá chép (Cyprinidae)", "Cá rô phi, diêu hồng (Oreochromis mosambicus, Oreochromis niloticus)", "Cá trắm cỏ (Ctenopharyngodon idella)", "Cá hồi (Salmo spp., Onchorynchus spp.., Salvelinus spp.)"],1,"Theo Mục I, Phần B, Điểm 12 của Phụ lục ban hành kèm theo Thông tư 36/2018/TT-BNNPTNT, bệnh do virus Tilapia Lake (TiLV) ảnh hưởng đến Cá rô phi, diêu hồng (Oreochromis mosambicus, Oreochromis niloticus).",1);
  add(5,"Khi hàng hoá nhập khẩu không đáp ứng yêu cầu kiểm dịch, cơ quan kiểm dịch động vật phải thực hiện hành động nào sau đây?",["Cấp giấy chứng nhận kiểm dịch nhập khẩu cho hàng hoá", "Gửi hàng hoá về nước xuất khẩu", "Xử lý theo quy định và báo cáo vụ việc cho Cục Thú y", "Cho phép nhập khẩu sau khi thu tiền phạt"],2,"Theo Điều 5, khoản 5 của Thông tư 26/2016/TT-BNNPTNT, khi phát hiện 16 hàng không đạt yêu cầu, cơ quan kiểm dịch phải xử lý theo quy định và báo cáo vụ việc cho Cục Thú y.",1);
  add(5,"Tần suất lấy mẫu và kiểm tra cho 16 hàng nhập khẩu trong một năm được quy định như thế nào?",["Mỗi tháng một lần", "Hai lần trong năm", "Một lần duy nhất trong năm", "Lấy mẫu mỗi khi có khiếu nại"],2,"Theo khoản 6 của Điều 5, Thông tư 26/2016/TT-BNNPTNT, việc lấy mẫu, kiểm tra áp dụng tần suất trên tổng số 16 hàng nhập khẩu tính từ ngày 01/01 đến 31/12 trong cùng một năm, tức là một lần duy nhất trong năm.",2);
  add(5,"Trong trường hợp phát hiện bệnh dịch chưa đáp ứng quy định tại Phần A, Phần B của phụ lục, cơ quan nào quyết định chỉ tiêu kiểm dịch?",["Bộ Nông nghiệp và Phát triển nông thôn", "Cục Thú y và Cục Bảo vệ thực vật", "Cục Nông nghiệp và Phát triển nông thôn", "Bộ Y tế"],2,"Theo Điều C40, khi phát hiện bệnh dịch chưa đáp ứng quy định tại Phần A, B phụ lục, Cục Thú y báo cáo cho Bộ Nông nghiệp và Phát triển nông thôn (Bộ Nông nghiệp) để quyết định chỉ tiêu kiểm dịch.",2);
  add(5,"Mẫu số nào được sử dụng để đăng ký giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu?",["Mẫu 01TS", "Mẫu 07aTS", "Mẫu 10TS", "Mẫu 14TS"],0,"Trong danh mục mẫu của Thông tư 26/2016, Giấy đăng ký kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu được ghi là Mẫu 01TS.",1);
  add(5,"Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu (Mẫu 10TS) được cấp bởi cơ quan nào?",["Cơ quan kiểm dịch động vật tại tỉnh, thành phố nơi nhập khẩu", "Cơ quan kiểm dịch động vật tại cảng xuất khẩu", "Cơ quan kiểm dịch động vật tại tỉnh, thành phố nơi xuất khẩu", "Cơ quan kiểm dịch động vật tại Bộ Nông nghiệp"],0,"Mẫu 10TS là Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu, được cấp bởi cơ quan kiểm dịch động vật tại tỉnh, thành phố nơi nhập khẩu, theo quy định tại Điều 4, Thông tư 26/2016.",2);
  add(5,"Khi có yêu cầu bổ sung quy định về kiểm dịch động vật, sản phẩm động vật thủy sản, Thông tư nào được sửa đổi và bổ sung vào ngày 28/7/2022?",["Thông tư 26/2016/TT-BNNPTNT", "Thông tư 36/2018/TT-BNNPTNT", "Thông tư 06/2022/TT-BNNPTNT", "Thông tư 30/2021/TT-BNNPTNT"],2,"Theo đoạn văn, bổ sung các điều của Thông tư 06/2022/TT-BNNPTNT ngày 28/7/2022, nhằm bổ sung quy định về kiểm dịch động vật, sản phẩm động vật thủy sản.",3);
  add(5,"Trong trường hợp hàng hoá không đạt tiêu chuẩn kiểm dịch, quy trình xử lý nào sau đây là sai?",["Báo cáo vụ việc cho Cục Thú y và thực hiện các biện pháp xử lý theo quy định", "Cho phép hàng hoá xuất khẩu lại sau khi kiểm dịch lại mà không có báo cáo", "Thu hồi, tiêu hủy hoặc trả lại hàng hoá cho người xuất khẩu", "Ghi nhận trong biên bản ghi nhận tình trạng vi sinh thực phẩm"],1,"Theo Điều 5, khoản 5, khi hàng không đạt yêu cầu, phải báo cáo và thực hiện xử lý (thu hồi, tiêu hủy, trả lại). Việc cho phép xuất khẩu lại mà không báo cáo là không đúng.",2);
  add(5,"Mẫu nào được sử dụng để ghi nhận tình trạng vi sinh thực phẩm, sản phẩm động vật thủy sản?",["Mẫu 13TS", "Mẫu 07bTS", "Mẫu 15TS", "Mẫu 04TS"],0,"Mẫu 13TS là Biên bản ghi nhận tình trạng vi sinh thực phẩm, sản phẩm động vật thủy sản, theo danh mục mẫu trong Thông tư 26/2016.",1);
  add(5,"Theo Thông tư 36/2018/TT-BNNPTNT, trong việc kiểm dịch, cơ quan nào có thẩm quyền quyết định chi tiêu bệnh cần xét nghiệm?",["Cục Thú y", "Cục Bảo vệ thực vật", "Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Y tế"],0,"Điều C40 (phụ lục) quy định Cục Thú y quyết định chi tiêu bệnh cần xét nghiệm khi phát hiện bệnh dịch chưa đáp ứng quy định.",3);
  add(5,"Theo quy định, Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản do cơ quan thú y có thẩm quyền phát hành được in bằng mực màu gì?",["Mực đen", "Mực xanh", "Mực đỏ", "Mực tím"],0,"Dẫn chiếu Mục II, Khoản 1 của văn bản: 'Các mẫu Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản do cơ quan thú y có thẩm quyền phát hành theo mẫu được in bằng mực đen trên giấy in khổ A4...'",1);
  add(5,"Đường kính của Logo kiểm dịch động vật in chìm ở giữa Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản là bao nhiêu?",["10 cm", "12 cm", "15 cm", "8 cm"],1,"Dẫn chiếu Mục II, Khoản 1 của văn bản: '...ở giữa có Logo kiểm dịch động vật in chìm, màu đen nhạt, đường kính 12 cm.'",1);
  add(5,"Đối với Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản vận chuyển ra khỏi địa bàn cấp tỉnh, dấu 'BẢN GỐC' hoặc 'BẢN SAO' được đóng bằng mực màu gì?",["Mực xanh dương", "Mực đen", "Mực đỏ", "Mực tím"],2,"Dẫn chiếu Mục II, Khoản 2 của văn bản: 'Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản vận chuyển ra khỏi địa bàn cấp tỉnh được đóng dấu “BẢN GỐC” hoặc “BẢN SAO” bằng mực dấu màu đỏ ở góc trên bên phải phía dưới chữ “Mẫu: ...”'",1);
  add(5,"Đối với Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu, nhập khẩu, dấu 'ORIGINAL' hoặc 'COPY' được đóng bằng mực màu gì?",["Mực đỏ", "Mực đen", "Mực xanh da trời", "Mực tím"],2,"Dẫn chiếu Mục II, Khoản 3 của văn bản: 'Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu, nhập khẩu, tạm nhập tái xuất, chuyển cửa khẩu, kho ngoại quan, quá cảnh lãnh thổ Việt Nam được đóng dấu “ORIGINAL” hoặc “COPY” bằng mực màu xanh da trời ở góc trên bên phải phía dưới chữ “Mẫu: ...'",1);
  add(5,"Kích thước chuẩn (rộng x dài) của mẫu dấu 'BẢN GỐC', 'BẢN SAO', 'ORIGINAL', 'COPY' được sử dụng trên Giấy chứng nhận kiểm dịch là bao nhiêu?",["1,0 cm x 3,0 cm", "1,5 cm x 4,0 cm", "2,0 cm x 4,0 cm", "1,5 cm x 3,5 cm"],1,"Dẫn chiếu Mục II, Khoản 4a của văn bản: 'Dấu có hình chữ nhật, kích thước 1,5 cm x 4,0 cm (rộng x dài), đường viền ngoài có bề rộng 0,1 cm;'",1);
  add(5,"Khi vận chuyển động vật, sản phẩm động vật thủy sản ra khỏi địa bàn cấp tỉnh, chủ hàng sẽ nhận được bao nhiêu bản GỐC của Giấy chứng nhận kiểm dịch?",["01 bản", "02 bản", "03 bản", "04 bản"],1,"Dẫn chiếu Mục II, Khoản 2a của văn bản: 'Bản gốc: 02 bản (01 bản lưu tại cơ quan cấp giấy, 01 bản cấp cho chủ hàng);'",2);
  add(5,"Một lô hàng thủy sản xuất khẩu sẽ được cấp bao nhiêu bản ORIGINAL của Giấy chứng nhận kiểm dịch?",["01 bản", "02 bản", "03 bản", "04 bản"],2,"Dẫn chiếu Mục II, Khoản 3a của văn bản: 'Giấy chứng nhận kiểm dịch xuất khẩu, nhập khẩu: 03 bản ORIGINAL (01 bản lưu tại cơ quan cấp giấy; 02 bản cấp cho chủ hàng, chủ hàng gửi 01 bản cho cơ quan hải quan);'",2);
  add(5,"Khi nhập khẩu động vật, sản phẩm động vật thủy sản và vận chuyển về nơi cách ly kiểm dịch, Giấy vận chuyển được phát hành tổng cộng bao nhiêu bản?",["01 bản", "02 bản", "03 bản", "04 bản"],2,"Dẫn chiếu Mục II, Khoản 5 của văn bản: 'Giấy vận chuyển động vật, sản phẩm động vật thủy sản nhập khẩu về nơi cách ly kiểm dịch được phát hành 03 bản (01 bản lưu tại cơ quan kiểm dịch động vật cửa khẩu nhập, 02 bản giao cho chủ hàng).'",2);
  add(5,"Một công ty có nhu cầu vận chuyển thủy sản ra khỏi địa bàn cấp tỉnh và giao hàng tại hai điểm khác nhau. Theo quy định, chủ hàng có thể được cấp tối đa bao nhiêu bản SAO của Giấy chứng nhận kiểm dịch cho lô hàng này?",["01 bản", "02 bản", "03 bản", "Không giới hạn"],2,"Dẫn chiếu Mục II, Khoản 2b của văn bản: 'Căn cứ vào nơi giao hàng trong quá trình vận chuyển (nếu có) để cấp tối đa 03 bản sao cho chủ hàng, mỗi nơi giao hàng chỉ cấp 01 bản sao.' Với 2 điểm giao hàng, chủ hàng sẽ được cấp 02 bản sao. Tối đa là 3 bản.",3);
  add(5,"Trong trường hợp động vật/sản phẩm động vật thủy sản không bảo đảm yêu cầu vệ sinh thú y, cơ quan có thẩm quyền sẽ sử dụng mẫu văn bản nào để ra quyết định xử lý?",["Mẫu 21TS", "Mẫu 24TS", "Mẫu 26TS", "Mẫu 27TS"],2,"Dẫn chiếu Mục I, Khoản 26 (hoặc 44 cũ) của văn bản: 'Quyết định xử lý vệ sinh thú y đối với động vật/sản phẩm động vật thủy sản không bảo đảm yêu cầu vệ sinh thú y - Mẫu 26TS.'",2);
  add(5,"Khi thực hiện kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu, cơ quan kiểm dịch động vật cửa khẩu có thể cấp thêm bản COPY Giấy chứng nhận kiểm dịch trong trường hợp nào?",["Khi có yêu cầu từ cơ quan hải quan", "Khi có yêu cầu từ cơ quan thú y nước nhập khẩu", "Khi chủ hàng có yêu cầu", "Không được phép cấp thêm"],2,"Dẫn chiếu Mục II, Khoản 3a của văn bản: '...riêng động vật, sản phẩm động vật thủy sản xuất khẩu, cơ quan kiểm dịch động vật cửa khẩu có thể cấp thêm bản COPY khi chủ hàng có yêu cầu;'",3);
  add(5,"Đối với Giấy chứng nhận kiểm dịch tạm nhập tái xuất, chuyển cửa khẩu, kho ngoại quan, quá cảnh lãnh thổ Việt Nam, chủ hàng sẽ nhận được bao nhiêu bản COPY?",["01 bản", "02 bản", "03 bản", "Không có bản COPY"],1,"Dẫn chiếu Mục II, Khoản 3b của văn bản: '...02 bản COPY giao cho chủ hàng (01 bản chủ hàng gửi tại cơ quan kiểm dịch động vật cửa khẩu xuất);'",2);
  add(5,"Theo quy định, các mẫu hồ sơ kiểm dịch động vật, sản phẩm động vật thủy sản được sử dụng như thế nào trên phạm vi toàn quốc?",["Tùy theo từng địa phương", "Thống nhất", "Theo hướng dẫn của Bộ Nông nghiệp và Phát triển nông thôn", "Theo yêu cầu của cơ quan kiểm dịch"],1,"Dẫn chiếu Mục II, Khoản 6 của văn bản: 'Mẫu hồ sơ kiểm dịch động vật, sản phẩm động vật thủy sản được sử dụng thống nhất trên phạm vi toàn quốc.'",1);
  add(5,"Mẫu văn bản nào được sử dụng để lập biên bản kiểm tra và lấy mẫu xét nghiệm trong quá trình kiểm dịch động vật, sản phẩm động vật thủy sản?",["Mẫu 20TS", "Mẫu 22TS", "Mẫu 24TS", "Mẫu 25TS"],2,"Dẫn chiếu Mục I, Khoản 24 của văn bản: 'Biên bản kiểm tra và lấy mẫu xét nghiệm - Mẫu 24TS.'",2);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu, xuất khẩu có giá trị sử dụng trong thời hạn tối đa bao nhiêu ngày?",["30 ngày", "60 ngày", "90 ngày", "120 ngày"],1,"Theo Khoản 8b, Mục 4, Trang 40 của Thông tư 26/2016/TT-BNNPTNT, Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu, xuất khẩu có giá trị sử dụng không quá 60 ngày.",1);
  add(5,"Thời hạn hiệu lực của Giấy chứng nhận kiểm dịch động vật, sản phẩm thủy sản vận chuyển ra khỏi địa bàn cấp tỉnh được tính như thế nào?",["Không quá 30 ngày kể từ ngày cấp.", "Theo khoảng thời gian vận chuyển từ nơi xuất phát đến nơi đến cuối cùng.", "Không quá 60 ngày kể từ ngày cấp.", "Theo thời gian tối đa cho phép hàng hóa lưu trú trên lãnh thổ Việt Nam."],1,"Theo Khoản 8a, Mục 4, Trang 40 của Thông tư 26/2016/TT-BNNPTNT, Giấy chứng nhận kiểm dịch động vật, sản phẩm thủy sản vận chuyển ra khỏi địa bàn cấp tỉnh được tính theo khoảng thời gian vận chuyển động vật, sản phẩm động vật thủy sản từ nơi xuất phát đến nơi đến cuối cùng.",1);
  add(5,"Đối với Giấy chứng nhận kiểm dịch động vật thủy sản, sản phẩm động vật thủy sản tạm nhập tái xuất, chuyển cửa khẩu, quá cảnh lãnh thổ Việt Nam, thời hạn hiệu lực được quy định như thế nào?",["Có giá trị sử dụng không quá 60 ngày.", "Được tính theo khoảng thời gian vận chuyển từ nơi xuất phát đến nơi đến cuối cùng.", "Được tính theo thời gian tối đa cho phép hàng hóa lưu trú trên lãnh thổ Việt Nam.", "Không quá 30 ngày kể từ ngày cấp."],2,"Theo Khoản 8c, Mục 4, Trang 40 của Thông tư 26/2016/TT-BNNPTNT, Giấy chứng nhận kiểm dịch động vật thủy sản, sản phẩm động vật thủy sản tạm nhập tái xuất, chuyển cửa khẩu, quá cảnh lãnh thổ Việt Nam được tính theo thời gian tối đa cho phép hàng hóa lưu trú trên lãnh thổ Việt Nam.",1);
  add(5,"Cơ quan nào chịu trách nhiệm phát hành mẫu Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu dùng làm thực phẩm?",["Cục Thú y.", "Bộ Nông nghiệp và Phát triển nông thôn.", "Cục Quản lý Chất lượng Nông Lâm sản và Thủy sản.", "Sở Nông nghiệp và Phát triển nông thôn các tỉnh."],2,"Theo Khoản 9, Mục 4, Trang 40 của Thông tư 26/2016/TT-BNNPTNT, mẫu Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu dùng làm thực phẩm do Cục Quản lý Chất lượng Nông Lâm sản và Thủy sản phát hành.",1);
  add(5,"Theo Ghi chú của Mẫu 01TS trong Thông tư 26/2016/TT-BNNPTNT, Giấy khai báo kiểm dịch được làm thành bao nhiêu bản?",["01 bản", "02 bản", "03 bản", "04 bản"],1,"Theo Ghi chú cuối Mẫu 01TS, Trang 42 của Thông tư 26/2016/TT-BNNPTNT, Giấy khai báo kiểm dịch được làm thành 02 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do tổ chức, cá nhân giữ.",1);
  add(5,"Khi đăng ký kiểm dịch vận chuyển sản phẩm thủy sản xuất phát từ cơ sở nuôi có bệnh đang công bố dịch, tổ chức, cá nhân cần cung cấp bổ sung những thông tin nào?",["Chỉ cần thời gian thu hoạch và mục đích sử dụng.", "Thời gian thu hoạch, mục đích sử dụng động vật thủy sản mắc bệnh và biện pháp xử lý trước khi vận chuyển.", "Chỉ cần biện pháp xử lý động vật thủy sản mắc bệnh trước khi vận chuyển.", "Không cần thông tin bổ sung nếu đã có giấy chứng nhận vệ sinh."],1,"Theo phần ghi chú 'Đối với sản phẩm thủy sản xuất phát từ cơ sở nuôi có bệnh đang công bố dịch' trong Mẫu 01TS, Trang 42 của Thông tư 26/2016/TT-BNNPTNT, cần cung cấp bổ sung: Thời gian thu hoạch, Mục đích sử dụng động vật thủy sản mắc bệnh, và Biện pháp xử lý động vật thủy sản mắc bệnh trước khi vận chuyển.",2);
  add(5,"Theo Thông tư số 36/2018/TT-BNNPTNT sửa đổi, bổ sung Thông tư số 26/2016/TT-BNNPTNT, cụm từ nào đã được thay thế trong Mẫu 01TS về đăng ký kiểm dịch?",["Từ 'Tên tổ chức, cá nhân' được thay bằng 'Tên doanh nghiệp'.", "Từ 'CMND/Thẻ CCCD/Hộ chiếu số' được thay bằng 'Số Chứng minh nhân dân/số Hộ chiếu/số định danh cá nhân'.", "Từ 'Địa chỉ giao dịch' được thay bằng 'Địa chỉ trụ sở chính'.", "Từ 'Nơi đến/nơi thả nuôi cuối cùng' được thay bằng 'Nơi tiêu thụ cuối cùng'."],1,"Theo ghi chú số 46 dưới Mẫu 01TS, Trang 41 của Thông tư 26/2016/TT-BNNPTNT (đã được sửa đổi bởi Thông tư 36/2018/TT-BNNPTNT), cụm từ 'CMND/Thẻ CCCD/Hộ chiếu số' đã được thay thế bằng cụm từ 'Số Chứng minh nhân dân/số Hộ chiếu/số định danh cá nhân'.",1);
  add(5,"Khi một Công ty muốn đăng ký kiểm dịch nhập khẩu động vật, sản phẩm động vật thủy sản (theo Mẫu 02TS), đơn đăng ký cần được gửi đến cơ quan nào?",["Sở Nông nghiệp và Phát triển nông thôn.", "Cục Thú y.", "Bộ Nông nghiệp và Phát triển nông thôn.", "Chi cục Chăn nuôi và Thú y địa phương."],1,"Theo Mẫu 02TS, Trang 43 của Thông tư 26/2016/TT-BNNPTNT, phần 'Kính gửi' ghi rõ 'Cục Thú y'.",1);
  add(5,"Theo Mẫu 03 TS /KBKD-TSXNK, tổ chức, cá nhân có thể khai báo kiểm dịch cho những mục đích nào sau đây?",["Chỉ xuất khẩu và nhập khẩu.", "Xuất khẩu, nhập khẩu, tạm nhập tái xuất, tạm xuất tái nhập, kho ngoại quan, quá cảnh, chuyển khẩu.", "Chỉ tạm nhập tái xuất và quá cảnh.", "Chỉ xuất khẩu, nhập khẩu và kho ngoại quan."],1,"Mục 'Đề nghị quý Cơ quan kiểm dịch:' trong Mẫu 03 TS /KBKD-TSXNK liệt kê các lựa chọn: Xuất khẩu, Nhập khẩu, Tạm nhập tái xuất, Tạm xuất tái nhập, Kho ngoại quan, Quá cảnh, Chuyển khẩu và Khác. Do đó, đáp án B bao phủ đầy đủ các mục đích khai báo.",1);
  add(5,"Theo ghi chú của Mẫu 03 TS /KBKD-TSXNK, Đơn khai báo được làm thành mấy bản và phân phối cho những bên nào?",["02 bản: 01 bản cơ quan kiểm dịch giữ, 01 bản tổ chức/cá nhân khai báo giữ.", "03 bản: 01 bản cơ quan kiểm dịch giữ, 01 bản cơ quan hải quan giữ, 01 bản tổ chức/cá nhân khai báo giữ.", "03 bản: 01 bản cơ quan kiểm dịch giữ, 01 bản cơ quan hải quan giữ, 01 bản Cục Thú y giữ.", "04 bản: 01 bản cơ quan kiểm dịch, 01 bản hải quan, 01 bản tổ chức/cá nhân, 01 bản Cục Thú y."],1,"Ghi chú cuối Mẫu 03 TS /KBKD-TSXNK nêu rõ: 'Đơn khai báo được làm thành 03 bản: 01 bản cơ quan kiểm dịch giữ, 01 bản cơ quan hải quan giữ, 01 bản tổ chức/cá nhân khai báo giữ.'",1);
  add(5,"Khi ký vào Đơn khai báo kiểm dịch, tổ chức/cá nhân khai báo cam kết điều gì?",["Đảm bảo nguyên trạng hàng hóa và sử dụng hàng hóa đúng mục đích khai báo sau khi được cấp Giấy chứng nhận kiểm dịch.", "Đảm bảo nguyên trạng hàng hóa, đưa hàng về đúng địa điểm, đúng thời gian được khai báo và chỉ sử dụng hàng hóa đúng mục đích khai báo sau khi được cấp Giấy chứng nhận kiểm dịch.", "Đưa hàng về đúng địa điểm và thời gian được khai báo.", "Chịu trách nhiệm về mọi thông tin khai báo và tuân thủ pháp luật về thú y."],1,"Phần 'Chúng tôi xin cam kết:' trong Mẫu 03 TS /KBKD-TSXNK ghi rõ: 'đảm bảo nguyên trạng hàng hóa, đưa hàng về đúng địa điểm, đúng thời gian được khai báo và chỉ sử dụng hàng hóa đúng mục đích khai báo sau khi được quý Cơ quan cấp Giấy chứng nhận kiểm dịch.'",1);
  add(5,"Trong mục 'Chi tiết lô hàng' của Đơn khai báo kiểm dịch, thuật ngữ 'Kích cỡ cá thể/Dạng sản phẩm' được hiểu như thế nào đối với động vật thủy sản sử dụng làm giống?",["Phải ghi rõ dạng sản phẩm của động vật thủy sản.", "Phải ghi rõ kích cỡ cá thể của động vật thủy sản.", "Có thể ghi kích cỡ cá thể hoặc dạng sản phẩm tùy ý.", "Không cần khai báo chi tiết này đối với động vật thủy sản làm giống."],1,"Ghi chú (1) dưới bảng 'Chi tiết lô hàng' giải thích: '(1) Kích cỡ cá thể đối với động vật thủy sản sử dụng làm giống, dạng sản phẩm đối với sản phẩm động vật thủy sản.' Do đó, đối với động vật thủy sản làm giống, cần ghi rõ kích cỡ cá thể.",2);
  add(5,"Mẫu Đơn khai báo kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu, nhập khẩu (Mẫu 03 TS) hiện hành được sửa đổi theo quy định tại văn bản nào?",["Thông tư 26/2016/TT-BNNPTNT.", "Thông tư 36/2018/TT-BNNPTNT.", "Thông tư số 06/2022/TT-BNNPTNT.", "Thông tư 47/2009/QCVN."],2,"Chú thích 47 ở cuối trang 44 của tài liệu nêu rõ: 'Mẫu này được sửa đổi theo quy định tại khoản 3 Điều 2 của Thông tư số 06/2022/TT-BNNPTNT ngày 28/7/2022 của Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn...'",1);
  add(5,"Một doanh nghiệp muốn nhập khẩu tạm thời một lô tôm giống từ Thái Lan để nuôi vỗ và sau đó tái xuất sang Trung Quốc. Doanh nghiệp này cần đánh dấu vào mục nào trong phần 'Đề nghị quý Cơ quan kiểm dịch' của Đơn khai báo kiểm dịch (Mẫu 03 TS)?",["Nhập khẩu.", "Tạm nhập tái xuất.", "Xuất khẩu.", "Quá cảnh."],1,"Mục đích của doanh nghiệp là nhập khẩu tạm thời để sau đó tái xuất, điều này phù hợp với định nghĩa của 'Tạm nhập tái xuất' được liệt kê trong các lựa chọn khai báo của Mẫu 03 TS.",3);
  add(5,"Theo Mẫu 03 TS /KBKD-TSXNK, cơ quan Hải quan sẽ thực hiện xác nhận trên Đơn khai báo kiểm dịch khi nào?",["Luôn luôn xác nhận trên tất cả các bản khai báo.", "Chỉ xác nhận khi có yêu cầu từ Cơ quan kiểm dịch.", "Xác nhận 'nếu có' trên bản khai báo.", "Xác nhận trước khi Cơ quan kiểm dịch động vật đồng ý đưa hàng về địa điểm kiểm dịch."],2,"Mục 'XÁC NHẬN CỦA CƠ QUAN HẢI QUAN (nếu có):' ở cuối Mẫu 03 TS chỉ ra rằng việc xác nhận của Hải quan là không bắt buộc trong mọi trường hợp, mà tùy thuộc vào tình huống cụ thể ('nếu có').",2);
  add(5,"Trong Đơn khai báo kiểm dịch (Mẫu 03 TS), thông tin về tổ chức, cá nhân xuất khẩu/nhập khẩu (của lô hàng) được yêu cầu khai báo tại mục nào?",["Mục 'Tên tổ chức, cá nhân khai báo' ở đầu đơn.", "Mục số 4 trong phần 'Chi tiết lô hàng'.", "Mục 'Nơi sản xuất'.", "Mục 'Địa điểm kiểm dịch/cách ly kiểm dịch'."],1,"Mục số 4 trong phần 'Chi tiết lô hàng' của Mẫu 03 TS là 'Tổ chức, cá nhân xuất khẩu/nhập khẩu'. Mục 'Tên tổ chức, cá nhân khai báo' là thông tin của người/đơn vị đứng ra làm đơn, có thể không phải là tổ chức/cá nhân xuất/nhập khẩu trực tiếp của lô hàng.",1);
  add(5,"Theo ghi chú của Mẫu 03 TS /KBKD-TSXNK, Đơn khai báo này được thể hiện trên loại giấy và số mặt in như thế nào?",["Tờ giấy khổ A4, in trên 1 mặt.", "Tờ giấy khổ A4, in trên 2 mặt.", "Tờ giấy khổ A3, in trên 1 mặt.", "Tờ giấy khổ A3, in trên 2 mặt."],1,"Ghi chú cuối Mẫu 03 TS /KBKD-TSXNK nêu rõ: 'Mẫu Đơn khai báo này được thể hiện trên 2 mặt của tờ giấy khổ A4'.",1);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, mẫu đơn \"Đăng ký kiểm dịch xuất/nhập kho ngoại quan\" phải ghi rõ thời gian thực hiện kiểm dịch trong bao lâu?",["Không quá 3 tháng", "Không quá 6 tháng", "Không quá 9 tháng", "Không quá 12 tháng"],1,"Trong mẫu đơn Đăng ký kiểm dịch xuất/nhập kho ngoại quan (trang 47) có ghi chú: \"Số lượng hàng có thể được thực hiện trong 06 tháng\" nên thời gian thực hiện kiểm dịch không được vượt quá 6 tháng.",1);
  add(5,"Khi nộp mẫu đơn \"Đăng ký kiểm dịch tạm nhập, chuyển khẩu, qua cân hối lãnh thổ Việt Nam\" (trang 46), thông tin nào sau đây KHÔNG bắt buộc phải ghi?",["Tên hàng", "Tên khoa học", "Mã HS (Harmonized System)", "Thời gian lưu lại trên lãnh thổ Việt Nam"],2,"Mẫu đơn (trang 46) yêu cầu ghi: tên hàng, tên khoa học, đơn vị tính, tổng số, thời gian lưu lại trên lãnh thổ VN, v.v. Tuy nhiên, mã HS không được liệt kê trong các mục bắt buộc của mẫu đơn này.",2);
  add(5,"Trong mẫu \"Đăng ký kiểm dịch mẫu bệnh phẩm thủy sản\" (trang 48), mục \"Mục đích sử dụng\" phải nêu rõ:",["Xuất khẩu sang nước ngoài", "Nghiên cứu khoa học, chẩn đoán bệnh", "Bán lẻ cho người tiêu dùng", "Sản xuất thực phẩm chế biến"],1,"Mẫu đăng ký mẫu bệnh phẩm (trang 48) có mục \"Mục đích sử dụng\" và trong hướng dẫn ghi rõ: \"Nghiên cứu khoa học, chẩn đoán bệnh\" là mục đích chính được chấp nhận.",2);
  add(5,"Nếu một lô hàng thủy sản nhập khẩu qua cửa khẩu có thời gian lưu trữ trên lãnh thổ Việt Nam dự kiến là 8 tháng, doanh nghiệp phải:",["Xin gia hạn thời gian kiểm dịch theo quy định", "Không được nhập khẩu vì vượt thời gian tối đa", "Chỉ cần khai báo thời gian thực tế trong mẫu đơn", "Thực hiện kiểm dịch lại sau mỗi 3 tháng"],0,"Theo các mẫu đơn (trang 46, 47) thời gian lưu trữ tối đa được phép là 6 tháng. Khi dự kiến vượt quá, doanh nghiệp phải xin cơ quan kiểm dịch cấp phép gia hạn thời gian kiểm dịch theo quy định của Thông tư 26/2016.",3);
  add(5,"Trong mẫu \"Đăng ký kiểm dịch tạm nhập, chuyển khẩu, qua cân hối lãnh thổ Việt Nam\" (trang 46), thông tin \"Cảng/khẩu nhập\" được ghi ở mục nào?",["Dòng cuối cùng của mẫu", "Mục \"Cảng/khẩu nhập\" ngay sau phần thông tin công ty", "Mục \"Thời gian thực hiện\"", "Mục \"Các giấy tờ có liên quan\""],1,"Mẫu đơn (trang 46) có mục riêng ghi \"Cảng/khẩu nhập\" ngay sau phần thông tin công ty và trước phần thời gian thực hiện.",1);
  add(5,"Theo Thông tư 26/2016, khi doanh nghiệp muốn xuất khẩu thủy sản qua kho ngoại quan, họ phải nộp mẫu đơn nào?",["Mẫu \"Đăng ký kiểm dịch tạm nhập, chuyển khẩu\"", "Mẫu \"Đăng ký kiểm dịch xuất/nhập kho ngoại quan\"", "Mẫu \"Đăng ký kiểm dịch mẫu bệnh phẩm thủy sản\"", "Mẫu \"Bảng ký kiểm dịch\""],1,"Đối với xuất khẩu qua kho ngoại quan, Thông tư 26/2016 quy định doanh nghiệp phải nộp mẫu \"Đăng ký kiểm dịch xuất/nhập kho ngoại quan\" (trang 47).",1);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT và 36/2018/TT-BNNPTNT, Mẫu 07b TS được sử dụng cho mục đích nào?",["Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu.", "Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản vận chuyển ra khỏi địa bàn cấp tỉnh.", "Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu.", "Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản vận chuyển trong cùng một địa bàn cấp tỉnh."],1,"Dựa vào tiêu đề của Mẫu 07b TS: 'GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN VẬN CHUYỂN RA KHỎI ĐỊA BÀN CẤP TỈNH'.",1);
  add(5,"Thông tin nào sau đây về chủ hàng hoặc người đại diện KHÔNG được liệt kê rõ ràng là bắt buộc trên Mẫu 07b TS?",["Họ tên chủ hàng (hoặc người đại diện).", "Địa chỉ giao dịch.", "Số điện thoại (Bao gồm điện thoại cố định và di động).", "Email."],3,"Trên Mẫu 07b TS, phần thông tin chủ hàng/người đại diện bao gồm: 'Họ tên chủ hàng (hoặc người đại diện):', 'Địa chỉ giao dịch:', 'Điện thoại:', 'Fax:', 'Di động:'. Không có mục 'Email' được liệt kê cụ thể cho chủ hàng.",2);
  add(5,"Theo Mẫu 07b TS, điều kiện nào sau đây là BẮT BUỘC để kiểm dịch viên xác nhận hàng hóa đủ điều kiện vận chuyển?",["Số hàng trên có nguồn gốc/cơ sở an toàn với các bệnh truyền nhiễm.", "Động vật thủy sản không mang mầm bệnh hoặc sản phẩm được lấy từ cơ sở an toàn, đáp ứng yêu cầu vệ sinh thú y.", "Số hàng trên đã được lấy mẫu kiểm tra, xét nghiệm và có phiếu kết quả kèm theo (nếu có).", "Tất cả các điều kiện trên."],3,"Mục 1, 2 và 3 trong phần xác nhận của Kiểm dịch viên trên Mẫu 07b TS đều là các điều kiện bắt buộc: '1/ Số hàng trên có nguồn gốc/cơ sở an toàn với các bệnh:...'; '2/ Động vật thủy sản không mang mầm bệnh/động vật thủy sản được lấy từ cơ sở an toàn, sản phẩm động vật thủy sản được chế biến, bảo quản đảm bảo yêu cầu vệ sinh thú y theo quy định.'; '3/ Số hàng trên đã được lấy mẫu kiểm tra, xét nghiệm số: ... (gửi kèm bản sao, nếu có).'.",2);
  add(5,"Theo Mẫu 07b TS, phương tiện vận chuyển và các vật dụng khác có liên quan phải đảm bảo yêu cầu vệ sinh thú y như thế nào?",["Đã được rửa sạch bằng nước và xà phòng.", "Đã được khử trùng tiêu độc bằng hóa chất và nồng độ cụ thể được ghi rõ.", "Đã được phơi nắng diệt khuẩn trong vòng ít nhất 24 giờ.", "Đã được kiểm tra trực quan và xác nhận sạch sẽ bởi kiểm dịch viên."],1,"Mục 5 trong phần xác nhận của Kiểm dịch viên trên Mẫu 07b TS ghi rõ: '5/ Phương tiện vận chuyển, các vật dụng khác có liên quan kèm theo đảm bảo yêu cầu vệ sinh thú y, đã được khử trùng tiêu độc bằng....................................................................nồng độ ..................................'.",1);
  add(5,"Giấy chứng nhận kiểm dịch theo Mẫu 07b TS có giá trị đến khi nào?",["Đến ngày được ghi rõ trên giấy chứng nhận.", "Vô thời hạn kể từ ngày cấp.", "Trong vòng 30 ngày kể từ ngày cấp.", "Cho đến khi hàng hóa được giao đến nơi cuối cùng theo lộ trình vận chuyển."],0,"Phần cuối của Mẫu 07b TS có mục 'Giấy có giá trị đến ngày......../....../...........', cho thấy giá trị của giấy được xác định bằng một ngày cụ thể.",1);
  add(5,"Mẫu 08 TS được sử dụng cho mục đích nào?",["Kiểm dịch vận chuyển động vật, sản phẩm động vật thủy sản trong nội tỉnh.", "Kiểm dịch vận chuyển động vật, sản phẩm động vật thủy sản giữa các tỉnh.", "Kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu vào Việt Nam.", "Kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu ra nước ngoài."],3,"Tiêu đề của Mẫu 08 TS là 'GIAY CHUNG NHAN KIEM DICH dong vat, sAn phAm dong vAt thuy sAn xuAt khAu' (HEALTH CERTIFICATE FOR EXPORT OF AQUATIC ANIMAL, AQUATIC ANIMAL’S PRODUCTS).",1);
  add(5,"Thông tin nào sau đây là BẮT BUỘC phải có cho cả người xuất hàng và người nhận hàng trên Mẫu 08 TS?",["Tên thương mại của sản phẩm.", "Địa chỉ Email.", "Số Fax.", "Tên và địa chỉ."],3,"Trên Mẫu 08 TS, các mục 'Tên, địa chỉ người xuất hàng:' và 'Tên, địa chỉ người nhận hàng:' là bắt buộc. Các thông tin khác như Tel, Fax, Email có thể được cung cấp nhưng không phải là thông tin cơ bản nhất được yêu cầu cho cả hai đối tượng.",2);
  add(5,"Trên Mẫu 08 TS, mục đích sử dụng của hàng hóa xuất khẩu được phân loại thành những nhóm chính nào?",["Tiêu dùng, làm giống, nghiên cứu & phòng thí nghiệm, làm cảnh, khác.", "Thực phẩm, dược phẩm, nguyên liệu sản xuất, thức ăn chăn nuôi.", "Chế biến, tiêu thụ nội địa, tái xuất.", "Sản xuất, kinh doanh, dự trữ quốc gia."],0,"Dựa vào phần 'Mục đích sử dụng: Use:' trên Mẫu 08 TS, có các lựa chọn: 'Tiêu dùng (Human consumption)', 'Làm giống (Transplantation/Breeding, eggs, Gametes etc)', 'Nghiên cứu & phòng thí nghiệm (Research & laboratory)', 'Làm cảnh (Ornamental)', 'Khác (Other)'.",1);
  add(5,"Khi cấp Giấy chứng nhận kiểm dịch xuất khẩu (Mẫu 08 TS) cho sản phẩm động vật thủy sản, kiểm dịch viên xác nhận điều gì?",["Sản phẩm không chứa các chất cấm theo quy định của nước nhập khẩu.", "Sản phẩm đã được kiểm tra và đáp ứng yêu cầu vệ sinh thú y.", "Sản phẩm được đóng gói theo tiêu chuẩn quốc tế ISO.", "Sản phẩm được sản xuất tại cơ sở đạt chứng nhận GMP."],1,"Phần xác nhận của kiểm dịch viên trên Mẫu 08 TS có dòng: 'The aquatic animal products described above were examined and found to meet the animal health requirements.' (Sản phẩm động vật thủy sản được kiểm tra và đáp ứng yêu cầu vệ sinh thú y).",1);
  add(5,"Ghi chú (1) trong cả Mẫu 07b TS và Mẫu 08 TS giải thích về thông tin nào?",["Tên cơ quan trả lời kết quả xét nghiệm.", "Kích thước cơ thể (đối với động vật thủy sản giống) hoặc Dạng sản phẩm (đối với sản phẩm động vật thủy sản).", "Nồng độ hóa chất khử trùng sử dụng.", "Số lượng bao gói của lô hàng."],1,"Ghi chú (1) ở cuối cả hai mẫu 07b TS và 08 TS đều ghi: '(1): Kích thước cơ thể (đối với động vật thủy sản giống)/Dạng sản phẩm (đối với sản phẩm động vật thủy sản)'.",1);
  add(5,"Một doanh nghiệp muốn vận chuyển 5 tấn cá tra giống từ tỉnh Đồng Tháp ra tỉnh Hải Dương để cung cấp cho các trang trại nuôi thương phẩm. Doanh nghiệp này cần loại giấy chứng nhận kiểm dịch nào theo quy định được trích dẫn?",["Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản xuất khẩu (Mẫu 08 TS).", "Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản vận chuyển ra khỏi địa bàn cấp tỉnh (Mẫu 07b TS).", "Giấy chứng nhận kiểm dịch nội tỉnh.", "Không cần giấy chứng nhận kiểm dịch vì đây là sản phẩm nội địa và không phải xuất khẩu."],1,"Việc vận chuyển cá tra giống từ Đồng Tháp (một tỉnh) ra Hải Dương (một tỉnh khác) là vận chuyển 'ra khỏi địa bàn cấp tỉnh'. Do đó, doanh nghiệp cần sử dụng Mẫu 07b TS theo quy định.",3);
  add(5,"Một lô hàng cá basa fillet đông lạnh của Việt Nam đang chuẩn bị xuất khẩu sang thị trường Châu Âu. Khi cấp Giấy chứng nhận kiểm dịch xuất khẩu (Mẫu 08 TS), kiểm dịch viên cần xác nhận thông tin gì về tình trạng sức khỏe của sản phẩm trên giấy chứng nhận?",["Cá basa được nuôi theo tiêu chuẩn GlobalGAP hoặc tương đương.", "Sản phẩm đã được kiểm tra và đáp ứng đầy đủ yêu cầu vệ sinh thú y.", "Sản phẩm không chứa bất kỳ dư lượng kháng sinh nào.", "Cá basa được đánh bắt hoặc nuôi từ vùng không có dịch bệnh trong 6 tháng gần nhất."],1,"Phần xác nhận của kiểm dịch viên trên Mẫu 08 TS cho sản phẩm động vật thủy sản là: 'The aquatic animal products described above were examined and found to meet the animal health requirements.' (Sản phẩm động vật thủy sản được kiểm tra và đáp ứng yêu cầu vệ sinh thú y). Các lựa chọn khác có thể là điều kiện tiên quyết hoặc yêu cầu cụ thể của nước nhập khẩu nhưng không phải là nội dung xác nhận trực tiếp được in trên mẫu chứng nhận này.",3);
  add(5,"Theo Mẫu 09 TS của Thông tư 26/2016/TT-BNNPTNT, điều nào sau đây bị nghiêm cấm trong quá trình vận chuyển động vật, sản phẩm động vật thủy sản nhập khẩu?",["Thay đổi lộ trình vận chuyển đã đăng ký.", "Vứt chất thải, rác thải, xác thủy sản.", "Vận chuyển thêm các sản phẩm không có trong giấy chứng nhận.", "Dừng đỗ phương tiện vận chuyển quá 30 phút."],1,"Theo mục 'Toi kiem dich vien... chung nhan' của Mẫu 09 TS (trang 52), điều khoản số 3 quy định: 'Nghiêm cấm vứt chất thải, rác thải, xác thủy sản trong quá trình vận chuyển.'",1);
  add(5,"Theo quy định tại Điểm c Khoản 15 Điều 1 của Thông tư số 36/2018/TT-BNNPTNT, cụm từ nào đã được thay đổi trong tiêu đề của Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu (Mẫu 10 TS)?",["\"GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU KHÔNG DÙNG LÀM THỰC PHẨM\" được thay đổi thành \"GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU\".", "\"GIẤY CHỨNG NHẬN VẬN CHUYỂN ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU\" được thay đổi thành \"GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU\".", "\"GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT THỦY SẢN\" được thay đổi thành \"GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU\".", "\"GIẤY CHỨNG NHẬN KIỂM DỊCH SẢN PHẨM ĐỘNG VẬT THỦY SẢN\" được thay đổi thành \"GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU\"."],0,"Theo ghi chú số 48 tại trang 53 của tài liệu, cụm từ “GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU KHÔNG DÙNG LÀM THỰC PHẨM” được thay đổi thành “GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU” theo quy định tại Điểm c Khoản 15 Điều 1 của Thông tư số 36/2018/TT-BNNPTNT.",1);
  add(5,"Theo quy định tại Điểm c Khoản 15 Điều 1 của Thông tư số 36/2018/TT-BNNPTNT, cụm từ nào đã được sửa đổi thành \"Nơi chuyển đến:\" trong Mẫu 10 TS?",["\"Địa điểm kiểm tra vệ sinh thú y:\"", "\"Địa điểm cách ly kiểm dịch:...từ ngày.../20..đến ngày.../20...\"", "\"Địa điểm tập kết hàng hóa:\"", "\"Địa điểm giao nhận hàng:\""],1,"Theo ghi chú số 49 tại trang 53 của tài liệu, cụm từ “Địa điểm cách ly kiểm dịch:...từ ngày.../20..đến ngày.../20...” được sửa đổi thành “Nơi chuyển đến:” theo quy định tại Điểm c Khoản 15 Điều 1 của Thông tư số 36/2018/TT-BNNPTNT.",1);
  add(5,"Các sửa đổi, bổ sung của Thông tư số 36/2018/TT-BNNPTNT đối với Thông tư số 26/2016/TT-BNNPTNT có hiệu lực thi hành kể từ ngày nào?",["Ngày 25 tháng 12 năm 2018.", "Ngày 30 tháng 6 năm 2016.", "Ngày 10 tháng 02 năm 2019.", "Ngày 01 tháng 01 năm 2019."],2,"Theo ghi chú số 48 và 49 tại trang 53 của tài liệu, các sửa đổi, bổ sung của Thông tư số 36/2018/TT-BNNPTNT có hiệu lực thi hành kể từ ngày 10 tháng 02 năm 2019.",1);
  add(5,"Trong Mẫu 09 TS \"GIẤY CHỨNG NHẬN VẬN CHUYỂN ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN NHẬP KHẨU\", ghi chú (1) tại cột \"Kích thước cá thể/Dạng sản phẩm\" có ý nghĩa gì?",["Kích thước cá thể đối với thủy sản thương phẩm/Dạng sản phẩm đối với thủy sản chế biến.", "Kích thước cá thể đối với thủy sản giống/Dạng sản phẩm đối với sản phẩm thủy sản.", "Kích thước cá thể đối với động vật thủy sản sống/Dạng sản phẩm đối với động vật thủy sản đông lạnh.", "Kích thước cá thể đối với thủy sản nuôi/Dạng sản phẩm đối với thủy sản khai thác."],1,"Theo ghi chú (1) cuối trang 52 của tài liệu: 'Kích thước cá thể đối với thủy sản giống/Dạng sản phẩm đối với sản phẩm thủy sản.'",1);
  add(5,"Khi cấp Giấy chứng nhận kiểm dịch động vật, sản phẩm động vật thủy sản nhập khẩu (Mẫu 10 TS), kiểm dịch viên động vật chứng nhận về tình trạng sức khỏe/vệ sinh của lô hàng như thế nào?",["Động vật thủy sản khỏe mạnh, sản phẩm thủy sản không có biểu hiện bệnh theo quy định.", "Động vật thủy sản đã được tiêm phòng đầy đủ, sản phẩm thủy sản đã qua xử lý nhiệt.", "Động vật thủy sản không mang mầm bệnh, sản phẩm thủy sản đạt tiêu chuẩn vi sinh.", "Động vật thủy sản đã được kiểm tra lâm sàng, sản phẩm thủy sản không có dấu hiệu hư hỏng."],0,"Theo mục 'Toi, kiem dich vien... chung nhan' của Mẫu 10 TS (trang 53), điều khoản số 2 quy định: 'Động vật thủy sản khỏe mạnh, sản phẩm thủy sản không có biểu hiện bệnh theo quy định;'",1);
  add(5,"Một doanh nghiệp muốn vận chuyển một lô hàng cá tra giống nhập khẩu từ cửa khẩu quốc tế Mộc Bài về trại nuôi tại Đồng Tháp. Theo Mẫu 09 TS, thông tin nào sau đây là bắt buộc phải được ghi rõ trong Giấy chứng nhận vận chuyển để đảm bảo tuân thủ quy định?",["Tên khoa học của cá tra giống.", "Lộ trình vận chuyển cụ thể từ Mộc Bài đến Đồng Tháp.", "Nồng độ chất khử trùng đã sử dụng cho phương tiện.", "Tên của người chịu trách nhiệm chính về lô hàng."],1,"Theo mục 'Toi kiem dich vien... chung nhan' của Mẫu 09 TS (trang 52), điều khoản số 2 quy định: 'Chỉ được vận chuyển theo lộ trình:...' Điều này nhấn mạnh sự cần thiết phải ghi rõ lộ trình vận chuyển để đảm bảo tuân thủ.",2);
  add(5,"Khi kiểm tra một lô hàng tôm đông lạnh nhập khẩu, kiểm dịch viên động vật phát hiện phương tiện vận chuyển chưa được khử trùng tiêu độc. Theo Mẫu 10 TS, điều kiện vệ sinh thú y nào phải được đảm bảo đối với phương tiện vận chuyển và các vật dụng liên quan?",["Phương tiện vận chuyển phải có giấy chứng nhận vệ sinh an toàn thực phẩm.", "Phương tiện vận chuyển và các vật dụng khác có liên quan kèm theo phải đảm bảo yêu cầu vệ sinh thú y và đã được khử trùng tiêu độc bằng hóa chất và nồng độ cụ thể.", "Phương tiện vận chuyển phải là loại chuyên dụng cho sản phẩm thủy sản đông lạnh.", "Phương tiện vận chuyển phải được niêm phong bởi cơ quan kiểm dịch."],1,"Theo mục 'Toi, kiem dich vien... chung nhan' của Mẫu 10 TS (trang 53), điều khoản số 5 quy định: 'Phương tiện vận chuyển, các vật dụng khác có liên quan kèm theo đảm bảo yêu cầu vệ sinh thú y, đã được khử trùng tiêu độc bằng... nồng độ...'",2);
  add(5,"Theo Thông tư số 36/2018/TT-BNNPTNT, Mẫu 11TS \"Giấy chứng nhận kiểm dịch và vệ sinh an toàn thực phẩm động vật, sản phẩm động vật thủy sản nhập khẩu dùng làm thực phẩm\" đã bị bãi bỏ có hiệu lực từ ngày nào?",["30 tháng 6 năm 2016", "25 tháng 12 năm 2018", "10 tháng 02 năm 2019", "01 tháng 01 năm 2019"],2,"Mẫu 11TS được bãi bỏ theo quy định tại điểm d khoản 15 Điều 1 của Thông tư số 36/2018/TT-BNNPTNT ngày 25/12/2018 và có hiệu lực thi hành kể từ ngày 10 tháng 02 năm 2019 (Trang 55, phần ghi chú của Mẫu 11TS).",1);
  add(5,"Giấy chứng nhận kiểm dịch Mẫu 12TS áp dụng cho những trường hợp nào đối với động vật, sản phẩm động vật thủy sản?",["Nhập khẩu dùng làm thực phẩm", "Tạm nhập tái xuất, chuyển cửa khẩu, quá cảnh lãnh thổ Việt Nam", "Xuất khẩu", "Lưu thông nội địa"],1,"Tên đầy đủ của Mẫu 12TS là 'GIẤY CHỨNG NHẬN KIỂM DỊCH Động vật, sản phẩm động vật thủy sản tạm nhập tái xuất, CHUYỂN CỬA KHẨU, QUA CẢNH LÃNH THỔ VIỆT NAM' (Trang 56).",1);
  add(5,"Khi cấp Giấy chứng nhận kiểm dịch Mẫu 12TS, Kiểm dịch viên động vật sẽ chứng nhận nội dung nào liên quan đến phương tiện vận chuyển?",["Phương tiện vận chuyển đã được đăng ký và cấp phép hoạt động bởi cơ quan có thẩm quyền.", "Phương tiện vận chuyển đảm bảo yêu cầu vệ sinh thú y, đã được khử trùng tiêu độc và niêm phong theo quy định.", "Phương tiện vận chuyển có đầy đủ hệ thống làm lạnh và kiểm soát nhiệt độ tự động.", "Phương tiện vận chuyển được trang bị hệ thống giám sát GPS để theo dõi lộ trình."],1,"Mục 4 phần 'CHỨNG NHẬN' của Mẫu 12TS quy định: 'Phương tiện vận chuyển đảm bảo yêu cầu vệ sinh thú y, đã được khử trùng tiêu độc và niêm phong theo quy định' (Trang 56-57).",2);
  add(5,"Theo Mẫu 12TS, trong quá trình vận chuyển động vật, sản phẩm động vật thủy sản tạm nhập tái xuất, chuyển cửa khẩu, quá cảnh trên lãnh thổ Việt Nam, điều nào sau đây bị nghiêm cấm?",["Thay đổi phương tiện vận chuyển mà không thông báo.", "Vứt chất thải, xác thủy sản.", "Lưu kho hàng hóa quá 24 giờ.", "Vận chuyển ngoài giờ hành chính."],1,"Mục 2 phần 'NHỮNG YÊU CẦU KHI VẬN CHUYỂN TRÊN LÃNH THỔ VIỆT NAM' của Mẫu 12TS quy định: 'Nghiêm cấm vứt chất thải, xác thủy sản trong quá trình vận chuyển' (Trang 57).",2);
  add(5,"Một lô hàng thủy sản quá cảnh qua Việt Nam đang trên đường vận chuyển thì phát hiện một số cá thể thủy sản có biểu hiện mắc bệnh. Theo quy định tại Mẫu 12TS, người chịu trách nhiệm lô hàng phải làm gì?",["Tiếp tục vận chuyển đến cửa khẩu xuất và xử lý tại đó.", "Tự ý tiêu hủy các cá thể mắc bệnh để tránh lây lan.", "Phải thông báo ngay cho cơ quan Thú y nơi gần nhất.", "Ghi nhận vào nhật ký vận chuyển và báo cáo sau khi hoàn thành chuyến đi."],2,"Mục 3 phần 'NHỮNG YÊU CẦU KHI VẬN CHUYỂN TRÊN LÃNH THỔ VIỆT NAM' của Mẫu 12TS quy định: 'Phải thông báo cho cơ quan Thú y nơi gần nhất khi phát hiện thấy thủy sản có biểu hiện mắc bệnh/sản phẩm thủy sản có biểu hiện hư hỏng' (Trang 57).",3);
  add(5,"Khi khai báo thông tin 'MÔ TẢ ĐỘNG VẬT THỦY SẢN, SẢN PHẨM ĐỘNG VẬT THỦY SẢN' trong Giấy chứng nhận kiểm dịch Mẫu 12TS, thông tin nào sau đây không bắt buộc phải có?",["Tên khoa học của sản phẩm.", "Số lượng bao gói.", "Giá trị lô hàng.", "Nhiệt độ bảo quản."],2,"Phần 'MÔ TẢ ĐỘNG VẬT THỦY SẢN, SẢN PHẨM ĐỘNG VẬT THỦY SẢN' của Mẫu 12TS liệt kê các mục: STT, Tên thương mại, Tên khoa học, Số lượng bao gói, Số lượng/Trọng lượng, Nhiệt độ bảo quản (Lạnh/Thường), Container (Loại, Số lượng). Không có mục nào yêu cầu khai báo giá trị lô hàng (Trang 56).",2);
  add(5,"Theo Mẫu 12TS, đối với động vật thủy sản khi nhập vào Việt Nam, Kiểm dịch viên động vật chứng nhận điều kiện nào sau đây?",["Đã được tiêm phòng đầy đủ các loại vắc xin bắt buộc.", "Khỏe mạnh, không có biểu hiện lâm sàng bệnh truyền nhiễm.", "Đã được nuôi dưỡng trong môi trường kiểm soát chặt chẽ.", "Có nguồn gốc từ cơ sở nuôi được chứng nhận GAP."],1,"Mục 2 phần 'CHỨNG NHẬN' của Mẫu 12TS quy định: 'Động vật thủy sản khỏe mạnh, không có biểu hiện lâm sàng bệnh truyền nhiễm khi nhập vào Việt Nam...' (Trang 56).",1);
  add(5,"Theo Mẫu 13 TS, \"Biên bản ghi nhận tình trạng vệ sinh thú y của động vật, sản phẩm động vật thủy sản\" được lập thành mấy bản và các bên nào giữ các bản đó?",["01 bản, do cơ quan kiểm dịch giữ.", "02 bản, 01 bản do cơ quan kiểm dịch giữ và 01 bản do chủ hàng hoặc người đại diện giữ.", "03 bản, 01 bản cơ quan kiểm dịch, 01 bản chủ hàng, 01 bản người làm chứng.", "02 bản, 01 bản cơ quan kiểm dịch và 01 bản gửi cho cơ quan cấp trên."],1,"Dựa trên phần cuối của Mẫu 13 TS: \"Biên bản được lập thành 02 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ\".",1);
  add(5,"Mẫu biểu nào trong các mẫu sau đây được sử dụng để đăng ký kiểm tra chất lượng, an toàn thực phẩm/kiểm dịch và cấp chứng thư cho lô hàng thủy sản xuất khẩu?",["Mẫu 13 TS.", "Mẫu 14 TS.", "Mẫu 15 TS.", "Mẫu BB-VSTY."],1,"Dựa vào tiêu đề của Mẫu 14 TS: \"GIẤY ĐĂNG KÝ KIỂM TRA CHẤT LƯỢNG, AN TOÀN THỰC PHẨM/KIỂM DỊCH VÀ CẤP CHỨNG THỰC LÔ HÀNG THỦY SẢN XUẤT KHẨU\".",1);
  add(5,"Khi khai báo thông tin về xuất xứ nguyên liệu để sản xuất lô hàng thủy sản xuất khẩu trong Mẫu 14 TS, chủ hàng cần cung cấp những lựa chọn nào?",["Chỉ cần khai báo là thủy sản nuôi hoặc thủy sản khai thác tự nhiên.", "Khai báo là thủy sản nuôi hoặc khai thác tự nhiên, và tên vùng nuôi/thu hoạch/khai thác nếu là trong nước, hoặc tên nước/vùng lãnh thổ xuất xứ nếu là nhập khẩu.", "Chỉ cần khai báo tên nước/vùng lãnh thổ xuất xứ nguyên liệu nếu là nhập khẩu.", "Chỉ cần khai báo tên vùng nuôi, thu hoạch/vùng khai thác nếu là trong nước."],1,"Dựa vào Mục 11 \"Xuất xứ nguyên liệu để sản xuất lô hàng\" trong PHẦN KHAI BÁO CỦA CHỦ HÀNG của Mẫu 14 TS, yêu cầu lựa chọn \"Thủy sản nuôi\" hoặc \"Thủy sản khai thác tự nhiên\", và cung cấp \"Tên vùng nuôi, thu hoạch/vùng khai thác\" (nếu trong nước) hoặc \"Tên nước/vùng lãnh thổ xuất xứ nguyên liệu\" (nếu nhập khẩu).",2);
  add(5,"Trên \"Giấy chứng nhận kiểm dịch\" (Mẫu 15 TS) cho lô hàng xuất khẩu dùng làm thực phẩm, nhiệt độ bảo quản của lô hàng được phân loại thành các lựa chọn nào?",["Nhiệt độ môi trường, Làm lạnh, Đông lạnh.", "Nhiệt độ phòng, Bảo quản mát, Bảo quản đông.", "Nhiệt độ thường, Nhiệt độ thấp, Nhiệt độ cực thấp.", "Nhiệt độ môi trường, Nhiệt độ trung bình, Nhiệt độ lạnh sâu."],0,"Dựa vào mục \"Nhiệt độ bảo quản/Storage temperature\" trong Mẫu 15 TS, có các lựa chọn: \"Môi trường/Ambient\", \"Làm lạnh/Chilled\", \"Đông lạnh/Frozen\".",1);
  add(5,"Trong \"Biên bản ghi nhận tình trạng vệ sinh thú y\" (Mẫu 13 TS), những ai là thành phần bắt buộc phải có mặt để ký xác nhận vào biên bản?",["Cán bộ cơ quan kiểm dịch động vật và Người làm chứng.", "Chủ hàng (hoặc người đại diện) và Người làm chứng.", "Cán bộ cơ quan kiểm dịch động vật và Chủ hàng (hoặc người đại diện).", "Cán bộ cơ quan kiểm dịch động vật, Chủ hàng (hoặc người đại diện) và Người làm chứng."],2,"Dựa vào phần ký xác nhận cuối Mẫu 13 TS: \"Chủ hàng (hoặc người đại diện)\" và \"Kiểm dịch viên động vật\". \"Người làm chứng (nếu có)\" là không bắt buộc.",2);
  add(5,"Một doanh nghiệp đăng ký kiểm tra lô hàng thủy sản xuất khẩu bằng Mẫu 14 TS. Sau khi nộp hồ sơ, \"Phần xác nhận của cơ quan kiểm tra, chứng nhận\" ghi nhận \"Hồ sơ đăng ký: Không đạt\" và \"Cần bổ sung thêm\". Theo quy trình, bước tiếp theo mà doanh nghiệp cần thực hiện là gì để lô hàng có thể được xem xét cấp chứng thư?",["Nộp lại toàn bộ hồ sơ đăng ký mới từ đầu.", "Bổ sung các hồ sơ được yêu cầu và chờ \"Kết quả xem xét sau khi bổ sung\".", "Kháng nghị quyết định \"Không đạt\" lên cấp trên.", "Chuyển sang đăng ký kiểm tra tại một cơ quan khác."],1,"Dựa vào PHẦN XÁC NHẬN CỦA CƠ QUAN KIỂM TRA, CHỨNG NHẬN trong Mẫu 14 TS, nếu \"Hồ sơ đăng ký: Không đạt\" và có \"Cần bổ sung thêm\", thì sau đó sẽ có \"Kết quả xem xét sau khi bổ sung\". Điều này ngụ ý rằng bước tiếp theo là bổ sung hồ sơ.",3);
  add(5,"Trên \"Giấy chứng nhận kiểm dịch\" (Mẫu 15 TS), phần thông tin chi tiết về hàng hóa cần bao gồm những nội dung nào trong bảng mô tả sản phẩm?",["Số lượng bao gói, Khối lượng tịnh, Loài (tên khoa học), Quy cách đóng gói/bao gói, Ngày sản xuất.", "Tên thương mại, Tên khoa học, Dạng sản phẩm, Số lượng, Khối lượng.", "Mã số lô hàng, Tên cơ sở sản xuất, Địa chỉ cơ sở sản xuất.", "Người nhận, Chủ hàng, Nước xuất xứ."],0,"Dựa vào bảng chi tiết trong Mẫu 15 TS, các cột bao gồm: \"Số lượng bao gói/Number of packages\", \"Khối lượng tịnh/Net weight\", \"Loài (tên khoa học)/Species (scientific name)\", \"Quy cách đóng gói, bao gói/Type of packaging\", \"Ngày sản xuất/Date (period) of Production\".",2);
  add(5,"Theo nội dung trích dẫn, khi vận chuyển sản phẩm trên lãnh thổ Việt Nam, các quy định nào cần được tuân thủ nghiêm túc?",["Các quy định của Pháp luật về giao thông.", "Các quy định của Pháp luật về thú y.", "Các quy định về an toàn thực phẩm nói chung.", "Các quy định về môi trường."],1,"Dựa vào mục \"4/ Thực hiện nghiêm túc các quy định của Pháp luật về thú y khi vận chuyển trên lãnh thổ Việt Nam.\" trong phần đầu của văn bản.",1);
  add(5,"Một lô hàng thủy sản xuất khẩu đã được cấp \"Giấy chứng nhận kiểm dịch\" (Mẫu 15 TS) với mục đích \"Dùng làm thực phẩm\". Tuy nhiên, khi đến nước nhập khẩu, cơ quan chức năng phát hiện lô hàng này được sử dụng cho mục đích khác không phải thực phẩm. Vấn đề này có thể gây ra rủi ro gì và thông tin nào trên chứng nhận đã bị vi phạm?",["Rủi ro về giao thương quốc tế; vi phạm thông tin \"Nhiệt độ bảo quản\".", "Rủi ro về việc không tuân thủ quy định nhập khẩu; vi phạm thông tin \"Chứng nhận lô hàng cho/Commodities certified for\".", "Rủi ro về chất lượng sản phẩm; vi phạm thông tin \"Mô tả hàng hóa\".", "Rủi ro về vệ sinh an toàn; vi phạm thông tin \"Tên cơ sở sản xuất\"."],1,"Dựa vào mục \"Chứng nhận lô hàng cho/Commodities certified for: Dùng làm thực phẩm/Human consumption\" trong Mẫu 15 TS. Việc sử dụng sai mục đích đã được chứng nhận sẽ gây ra rủi ro về không tuân thủ quy định nhập khẩu và có thể dẫn đến các biện pháp xử lý từ phía nước nhập khẩu.",3);
  add(5,"Trên \"Giấy đăng ký kiểm tra chất lượng, an toàn thực phẩm/kiểm dịch và cấp chứng thư lô hàng thủy sản xuất khẩu\" (Mẫu 14 TS), thông tin nào về cơ sở sản xuất là bắt buộc phải khai báo?",["Tên cơ sở sản xuất và Mã số cơ sở.", "Tên cơ sở sản xuất và Thời gian sản xuất.", "Tên cơ sở sản xuất và Địa điểm đăng ký kiểm tra.", "Tên cơ sở sản xuất và Số điện thoại liên hệ."],0,"Dựa vào Mục 7 \"Cơ sở sản xuất\" trong PHẦN KHAI BÁO CỦA CHỦ HÀNG của Mẫu 14 TS, yêu cầu \"Tên cơ sở sản xuất\" và \"Mã số cơ sở\".",2);
  add(5,"Theo Mẫu 16 TS 'THÔNG BÁO LÔ HÀNG KHÔNG ĐẠT', đâu là một trong các lý do khiến lô hàng bị thông báo không đáp ứng yêu cầu?",["Chỉ tiêu về dịch bệnh thủy sản", "Giá trị thương mại thấp", "Thiếu thông tin về người nhận hàng", "Phương tiện vận chuyển không phù hợp"],0,"Dựa trên Mẫu 16 TS 'THÔNG BÁO LÔ HÀNG KHÔNG ĐẠT', các lý do không đáp ứng yêu cầu được liệt kê rõ ràng bao gồm: Hồ sơ, cảm quan, ngoại quan; Chỉ tiêu về dịch bệnh thủy sản; và An toàn thực phẩm.",1);
  add(5,"Cơ quan nào có thẩm quyền ban hành 'THÔNG BÁO LÔ HÀNG KHÔNG ĐẠT' (Mẫu 16 TS)?",["Chủ hàng", "Cơ quan kiểm tra, chứng nhận", "Người nhận hàng", "Bộ Nông nghiệp và Phát triển nông thôn"],1,"Theo Mẫu 16 TS, thông báo này được ban hành bởi 'Tên, địa chỉ Cơ quan Kiểm tra, chứng nhận' và được ký bởi 'Thủ trưởng Cơ quan kiểm tra, chứng nhận'.",1);
  add(5,"Mẫu 17 TS được sử dụng với mục đích gì?",["Cấp mới giấy chứng nhận kiểm dịch", "Đề nghị cấp đổi hoặc cấp lại giấy chứng nhận kiểm dịch", "Thông báo lô hàng không đạt yêu cầu", "Chứng nhận vận chuyển mẫu bệnh phẩm"],1,"Tên của Mẫu 17 TS là 'GIẤY ĐỀ NGHỊ CẤP ĐỔI, CẤP LẠI GIẤY CHỨNG NHẬN KIỂM DỊCH CHO LÔ HÀNG THỦY SẢN XUẤT KHẨU DÙNG LÀM THỰC PHẨM', nêu rõ mục đích sử dụng.",1);
  add(5,"Theo Mẫu 17 TS, cơ sở pháp lý để doanh nghiệp đề nghị cấp đổi/cấp lại giấy chứng nhận kiểm dịch là gì?",["Luật Thú y hiện hành", "Thông tư quy định về kiểm dịch động vật, sản phẩm động vật thủy sản số /2016/TT-BNNPTNT", "Quyết định của Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn", "Nghị định của Chính phủ về an toàn thực phẩm"],1,"Mẫu 17 TS ghi rõ 'Căn cứ các quy định trong Thông tư quy định về kiểm dịch động vật, sản phẩm động vật thủy sản số /2016/TT-BNNPTNT ngày / /2016 của Bộ Nông nghiệp và Phát triển nông thôn'.",2);
  add(5,"Theo Mẫu 18 TS 'GIẤY CHỨNG NHẬN VẬN CHUYỂN GỬI MẪU BỆNH PHẨM THỦY SẢN', mẫu bệnh phẩm thủy sản phải đáp ứng yêu cầu nào khi được đóng gói và bảo quản?",["Đảm bảo tính thẩm mỹ của bao bì", "Đáp ứng yêu cầu vệ sinh thú y", "Sử dụng vật liệu đóng gói tái chế", "Ghi rõ giá trị kinh tế của mẫu"],1,"Mẫu 18 TS có phần 'Chung nhan/Attestation' ghi rõ: 'Sản phẩm mẫu bệnh phẩm thủy sản được đóng gói và bảo quản đáp ứng yêu cầu vệ sinh thú y./ The samples aquatic animals for diagnosis were packaged and preserved meet the veterinary hygiene requirements.'",1);
  add(5,"Ai là người có trách nhiệm ký và đóng dấu trên 'GIẤY CHỨNG NHẬN VẬN CHUYỂN GỬI MẪU BỆNH PHẨM THỦY SẢN' (Mẫu 18 TS)?",["Chỉ Kiểm dịch viên động vật", "Chỉ Thủ trưởng Cơ quan", "Kiểm dịch viên động vật và Thủ trưởng Cơ quan", "Người gửi mẫu và người nhận mẫu"],2,"Cuối Mẫu 18 TS có hai phần ký tên rõ ràng: 'Kiem dich vien dong vat (Ky, ghi ro ho ten)' và 'THU TRUONG CO QUAN (Ky, dong dau, ghi ro ho ten)'.",1);
  add(5,"Thông tin nào sau đây KHÔNG cần thiết phải có trên 'GIẤY CHỨNG NHẬN VẬN CHUYỂN GỬI MẪU BỆNH PHẨM THỦY SẢN' (Mẫu 18 TS)?",["Tên khoa học của loài động vật thủy sản", "Mục đích sử dụng mẫu", "Giá trị thương mại của mẫu", "Phương tiện vận chuyển"],2,"Mẫu 18 TS yêu cầu các thông tin như 'Loại động vật thủy sản (Tên khoa học)', 'Mục đích sử dụng', 'Phương tiện vận chuyển'. Không có mục nào yêu cầu 'Giá trị thương mại của mẫu'.",2);
  add(5,"Một lô hàng thủy sản xuất khẩu bị Cơ quan kiểm tra, chứng nhận thông báo 'KHÔNG ĐÁP ỨNG YÊU CẦU' do phát hiện chỉ tiêu về dịch bệnh thủy sản. Theo quy định của Mẫu 16 TS, chủ hàng cần thực hiện biện pháp nào?",["Yêu cầu cấp lại giấy chứng nhận kiểm dịch ngay lập tức", "Thực hiện các biện pháp khắc phục theo yêu cầu của Cơ quan kiểm tra, chứng nhận trong thời hạn quy định", "Tự ý tiêu hủy lô hàng mà không cần chờ hướng dẫn", "Chuyển lô hàng sang thị trường khác để tiêu thụ"],1,"Mẫu 16 TS quy định rõ 'Các biện pháp yêu cầu Chủ hàng thực hiện' và 'Thời hạn hoàn thành'. Điều này ngụ ý rằng chủ hàng phải tuân thủ các chỉ đạo khắc phục từ cơ quan kiểm tra trong khung thời gian cho phép.",3);
  add(5,"Một doanh nghiệp xuất khẩu thủy sản cần xin cấp lại Giấy chứng nhận kiểm dịch cho lô hàng đã được cấp trước đó nhưng bị thất lạc. Doanh nghiệp này sẽ sử dụng biểu mẫu nào và gửi đến cơ quan nào?",["Mẫu 16 TS gửi đến Bộ Nông nghiệp và Phát triển nông thôn", "Mẫu 17 TS gửi đến Cơ quan kiểm dịch có thẩm quyền", "Mẫu 18 TS gửi đến Cơ quan kiểm tra, chứng nhận", "Mẫu 19 TS gửi đến NAFIQAD"],1,"Mẫu 17 TS là 'GIẤY ĐỀ NGHỊ CẤP ĐỔI, CẤP LẠI GIẤY CHỨNG NHẬN KIỂM DỊCH CHO LÔ HÀNG THỦY SẢN XUẤT KHẨU DÙNG LÀM THỰC PHẨM' và được 'Kính gửi' đến cơ quan có thẩm quyền cấp giấy chứng nhận kiểm dịch.",3);
  add(5,"Theo thông tin chung của tài liệu, lô hàng thủy sản được chứng nhận đủ điều kiện đảm bảo an toàn thực phẩm theo quy định Việt Nam bởi cơ quan nào?",["Bộ Y tế", "Cục Quản lý Chất lượng Nông lâm sản và Thủy sản (NAFIQAD)", "Bộ Công Thương", "Cục Thú y"],1,"Phần 'Chung nhan/Attestation' của tài liệu gốc ghi rõ: 'Lô hàng thủy sản nêu trên từ cơ sở sản xuất đã được Cục Quản lý Chất lượng Nông lâm sản và Thủy sản kiểm tra, chứng nhận đủ điều kiện đảm bảo an toàn thực phẩm theo quy định Việt Nam / The above fishery products were come from the establishment approved by National Agro-Forestry - Fishery Quality Assurance Department (NAFIQAD) following food safety regulations of Vietnam.'",1);
  add(5,"Theo Mẫu 20TS của Thông tư 26/2016/TT-BNNPTNT, Biên bản niêm phong, kẹp chì phương tiện vận chuyển, chứa đựng động vật, sản phẩm động vật thủy sản được lập thành mấy bản và do ai giữ?",["02 bản, 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ.", "03 bản, 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ, 01 bản gửi Cục Thú y.", "01 bản duy nhất do cơ quan kiểm dịch động vật giữ.", "02 bản, cả hai bản đều do chủ hàng hoặc người đại diện giữ."],0,"Theo quy định tại Mẫu 20TS (Biên bản niêm phong, kẹp chì phương tiện vận chuyển, chứa đựng động vật, sản phẩm động vật thủy sản) của Thông tư 26/2016/TT-BNNPTNT, mục cuối cùng của biên bản nêu rõ: 'Biên bản này lập thành 02 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ'.",1);
  add(5,"Khi lập Biên bản niêm phong, kẹp chì phương tiện vận chuyển, chứa đựng động vật, sản phẩm động vật thủy sản (Mẫu 20TS), thông tin nào sau đây KHÔNG bắt buộc phải ghi nhận?",["Số lượng bao bì và quy cách đóng gói.", "Số giấy chứng nhận kiểm dịch và cơ quan cấp.", "Biển số phương tiện vận chuyển và số niêm phong, kẹp chì.", "Mục đích sử dụng của lô hàng."],3,"Dựa trên các trường thông tin trong Mẫu 20TS, các thông tin bắt buộc bao gồm: Loại hàng, Số lượng, Số giấy chứng nhận kiểm dịch, Cơ quan cấp, Phương tiện vận chuyển (Biển số), Số niêm phong, kẹp chì. Thông tin về 'Mục đích sử dụng của lô hàng' không được liệt kê là một trường bắt buộc trong biên bản này.",2);
  add(5,"Theo Mẫu 21TS của Thông tư 26/2016/TT-BNNPTNT, Biên bản kiểm tra điều kiện vệ sinh thú y nơi cách ly kiểm dịch động vật thủy sản/sản phẩm động vật thủy sản cần kiểm tra bao nhiêu nội dung chính về điều kiện vệ sinh thú y?",["8 nội dung.", "9 nội dung.", "10 nội dung.", "11 nội dung."],2,"Mẫu 21TS liệt kê 10 mục kết quả kiểm tra điều kiện vệ sinh thú y nơi cách ly kiểm dịch, bao gồm: Địa điểm, Diện tích, Thiết kế-xây dựng, Điều kiện trang thiết bị-dụng cụ, Điều kiện nuôi ĐVTS/bảo quản SPĐVTS, Nước sạch sử dụng, Nơi xử lý ĐVTS/SPĐVTS không đạt yêu cầu, Hệ thống thoát nước và xử lý nước thải, Điều kiện sức khỏe của người làm việc, và Thông tin vệ sinh-khử trùng tiêu độc.",1);
  add(5,"Khi kiểm tra điều kiện vệ sinh thú y nơi cách ly kiểm dịch động vật thủy sản (Mẫu 21TS), nếu phát hiện hệ thống thoát nước và xử lý nước thải của cơ sở không đạt yêu cầu, Kiểm dịch viên động vật sẽ thực hiện hành động nào sau đây?",["Đề xuất cơ sở khắc phục, sửa chữa hệ thống để đảm bảo tuân thủ quy định.", "Chấm dứt ngay hoạt động cách ly kiểm dịch tại cơ sở đó.", "Báo cáo trực tiếp lên Cục Thú y để xử phạt hành chính.", "Yêu cầu chủ cơ sở cung cấp giấy tờ chứng minh hệ thống đạt chuẩn."],0,"Mẫu 21TS có phần 'Kết luận' và 'Kiến nghị (nếu có)'. Trong trường hợp phát hiện điều kiện không đạt yêu cầu (như hệ thống thoát nước và xử lý nước thải), Kiểm dịch viên sẽ kết luận về tình trạng không đạt và đưa ra kiến nghị khắc phục, sửa chữa để cơ sở có thể đáp ứng các yêu cầu về vệ sinh thú y. Việc chấm dứt hoạt động hoặc xử phạt ngay lập tức thường là bước tiếp theo nếu cơ sở không khắc phục hoặc vi phạm nghiêm trọng, sau khi có kết luận và kiến nghị.",3);
  add(5,"Mẫu 22TS - Báo cáo kết quả kiểm tra nơi cách ly kiểm dịch động vật thủy sản/sản phẩm động vật thủy sản được gửi đến cơ quan nào?",["Cục Thú y.", "Bộ Nông nghiệp và Phát triển nông thôn.", "Chi cục Kiểm dịch động vật vùng.", "Chủ cơ sở cách ly kiểm dịch."],0,"Theo tiêu đề và nội dung của Mẫu 22TS, báo cáo này được 'Kính gửi: Cục Thú y', do Chi cục Thú y vùng hoặc Chi cục Kiểm dịch động vật vùng lập và gửi đi.",1);
  add(5,"Trong Biên bản kiểm tra điều kiện vệ sinh thú y nơi cách ly kiểm dịch (Mẫu 21TS), mục số 9 yêu cầu kiểm tra điều kiện sức khỏe của đối tượng nào?",["Sức khỏe của người làm việc tại cơ sở.", "Sức khỏe của động vật thủy sản đang cách ly.", "Sức khỏe của động vật thủy sản đã được kiểm dịch.", "Sức khỏe của kiểm dịch viên động vật."],0,"Mục số 9 trong phần 'Kết quả kiểm tra' của Mẫu 21TS ghi rõ: 'Điều kiện sức khỏe của người làm việc tại cơ sở'.",1);
  add(5,"Theo Thông tư số 36/2018/TT-BNNPTNT sửa đổi, bổ sung Thông tư số 26/2016/TT-BNNPTNT, cụm từ \"Cơ quan Thú y vùng\" đã được thay đổi thành cụm từ nào?",["Cục Thú y", "Chi cục Thú y vùng", "Trung tâm Kiểm dịch động vật", "Phòng Kiểm dịch Thú y"],1,"Theo Khoản 16 Điều 1 của Thông tư số 36/2018/TT-BNNPTNT ngày 25/12/2018, cụm từ “Cơ quan Thú y vùng” được thay đổi thành cụm từ “Chi cục Thú y vùng”, có hiệu lực thi hành kể từ ngày 10 tháng 02 năm 2019. (Tham khảo các chú thích 51, 52, 53 trong văn bản).",1);
  add(5,"Mẫu \"ĐỀ NGHỊ CẤP ĐỔI GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN XUẤT KHẨU KHÔNG DÙNG LÀM THỰC PHẨM\" (Mẫu 23 TS) được sử dụng trong trường hợp nào?",["Đề nghị cấp mới giấy chứng nhận kiểm dịch cho sản phẩm nhập khẩu", "Đề nghị cấp đổi giấy chứng nhận kiểm dịch cho sản phẩm thủy sản xuất khẩu không dùng làm thực phẩm", "Đề nghị gia hạn giấy chứng nhận kiểm dịch cho động vật sống nhập khẩu", "Đề nghị cấp giấy phép vận chuyển nội địa"],1,"Mẫu 23 TS có tiêu đề rõ ràng là \"ĐỀ NGHỊ CẤP ĐỔI GIẤY CHỨNG NHẬN KIỂM DỊCH ĐỘNG VẬT, SẢN PHẨM ĐỘNG VẬT THỦY SẢN XUẤT KHẨU KHÔNG DÙNG LÀM THỰC PHẨM\", do đó được sử dụng cho mục đích cấp đổi giấy chứng nhận kiểm dịch đối với sản phẩm xuất khẩu không dùng làm thực phẩm.",1);
  add(5,"Khi lập Biên bản kiểm tra và lấy mẫu xét nghiệm (Mẫu 24 TS), cách ghi số lượng hàng hóa đối với động vật thủy sản và sản phẩm động vật được quy định như thế nào?",["Động vật thủy sản ghi số lượng (con), sản phẩm động vật ghi số lượng (kiện, thùng, hộp)", "Cả hai loại đều ghi số lượng (kg)", "Động vật thủy sản ghi số lượng (kg), sản phẩm động vật ghi số lượng (con)", "Cả hai loại đều ghi số lượng (tổng cộng)"],0,"Theo Ghi chú (1) của Mẫu 24 TS: \"(1) Nếu hàng là động vật thủy sản thì ghi số lượng (con); nếu hàng là sản phẩm động vật thì ghi số lượng kiện, thùng, hộp.\"",2);
  add(5,"Biên bản kiểm tra và lấy mẫu xét nghiệm (Mẫu 24 TS) được lập thành bao nhiêu bản và các bên nào giữ?",["01 bản, do cơ quan kiểm dịch động vật giữ", "02 bản, 01 bản do cơ quan kiểm dịch động vật giữ và 01 bản do chủ hàng hoặc người đại diện giữ", "03 bản, mỗi bên giữ 01 bản (cơ quan kiểm dịch, chủ hàng, hải quan)", "01 bản, do chủ hàng hoặc người đại diện giữ"],1,"Cuối Mẫu 24 TS có ghi rõ: \"Biên bản này được lập thành 02 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ.\"",1);
  add(5,"Các thành phần bắt buộc phải có mặt để lập Biên bản mở niêm phong phương tiện vận chuyển, chứa đựng động vật, sản phẩm động vật thủy sản (Mẫu 25 TS) bao gồm những ai?",["Cán bộ cơ quan kiểm dịch động vật và chủ hàng", "Cán bộ cơ quan kiểm dịch động vật và cán bộ cơ quan Hải quan cửa khẩu", "Cán bộ cơ quan kiểm dịch động vật, cán bộ cơ quan Hải quan cửa khẩu và một thành phần thứ ba (thường là chủ hàng/đại diện)", "Chỉ cần cán bộ cơ quan kiểm dịch động vật"],2,"Mẫu 25 TS liệt kê các thành phần tham gia bao gồm: \"1/ Ông/bà: ... Là cán bộ cơ quan kiểm dịch động vật:\", \"2/ Ông/bà: ... Là cán bộ cơ quan Hải quan cửa khẩu:\", và \"3/ Ông/bà: ...\". Việc có 3 mục liệt kê cho thấy cần ít nhất 3 thành phần, trong đó có cơ quan kiểm dịch và hải quan. Trong thực tế, người thứ ba thường là chủ hàng hoặc đại diện.",2);
  add(5,"Mục đích chính của \"Biên bản kiểm tra điều kiện vệ sinh thú y\" được đề cập trong văn bản là gì?",["Xác nhận cơ sở đủ điều kiện để xuất khẩu sản phẩm", "Xác nhận cơ sở bảo đảm điều kiện vệ sinh thú y để cách ly kiểm dịch động vật thủy sản/sản phẩm động vật thủy sản", "Đánh giá chất lượng sản phẩm trước khi đưa ra thị trường", "Kiểm tra hồ sơ pháp lý của cơ sở"],1,"Đoạn văn bản nêu rõ: \"Cơ sở bảo đảm điều kiện vệ sinh thú y để cách ly kiểm dịch động vật thủy sản/sản phẩm động vật thủy sản.\" Đây là mục đích chính của biên bản này.",2);
  add(5,"Theo quy định, Biên bản ghi nhận tình trạng vệ sinh thú y đối với hàng động vật, sản phẩm động vật thủy sản được lập thành 03 bản và do những cơ quan, cá nhân nào giữ?",["Cơ quan kiểm dịch động vật, cơ quan Hải quan cửa khẩu, chủ hàng hoặc người đại diện.", "Cơ quan kiểm dịch động vật, Bộ Nông nghiệp và Phát triển nông thôn, chủ hàng.", "Cơ quan Hải quan cửa khẩu, Bộ Công Thương, chủ hàng.", "Cơ quan kiểm dịch động vật, tổ chức thực hiện xử lý hàng, chủ hàng."],0,"Dựa trên đoạn văn bản 'Bien ban nay l$p thanh 03 ban: 01 ban do ca quan kiem dich dgng vyt giu, 01 ban do ca quan Hai quan cura khau gifir, 01 ban do chu hang hoyc ngiroi dai difn giu.' (Trang 72, phần Biên bản ghi nhận tình trạng vệ sinh thú y).",1);
  add(5,"Căn cứ pháp lý chính để ban hành Quyết định xử lý vệ sinh thú y đối với động vật/sản phẩm động vật thủy sản không bảo đảm yêu cầu vệ sinh thú y là gì?",["Luật An toàn thực phẩm số 55/2010/QH12.", "Luật Thú y số 79/2015/QH13.", "Luật Chất lượng sản phẩm, hàng hóa số 05/2007/QH12.", "Nghị định số 15/2018/NĐ-CP quy định chi tiết thi hành một số điều của Luật An toàn thực phẩm."],1,"Dựa trên đoạn văn bản 'Can cii Luat Thiiy so 79/2015/QH13 ngay 19 thang 6 nam 2015;' (Trang 72, phần Quyết định xử lý vệ sinh thú y, mục THAM QUYỀN BAN HÀNH (1)).",1);
  add(5,"Theo Mẫu 26 TS, cơ quan nào có thẩm quyền ban hành Quyết định xử lý vệ sinh thú y đối với động vật/sản phẩm động vật thủy sản không bảo đảm yêu cầu vệ sinh thú y?",["Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn.", "Thủ trưởng cơ quan kiểm dịch động vật.", "Cục trưởng Cục Thú y.", "Chi cục trưởng Chi cục Thú y vùng."],1,"Dựa trên chú thích (1) tại trang 74 của tài liệu: '(1) : Thu tne&ng ccr quan ra quyit dinh xir ly;'. Đồng thời, phần ký tên cuối Quyết định là 'THỦ TRƯỞNG CƠ QUAN'.",1);
  add(5,"Ngoài số hàng động vật, sản phẩm động vật thủy sản không đảm bảo yêu cầu vệ sinh thú y, những vật dụng nào có liên quan cũng có thể bị áp dụng biện pháp xử lý vệ sinh thú y theo Quyết định (Mẫu 26 TS)?",["Chỉ bao gồm phương tiện vận chuyển và dụng cụ chứa đựng.", "Chỉ bao gồm thức ăn và chất độn.", "Bao gồm phương tiện, dụng cụ, bao bì chứa đựng, thức ăn, chất độn, chất thải.", "Chỉ bao gồm các vật liệu đóng gói và chất thải."],2,"Dựa trên Điều 2 của Quyết định xử lý vệ sinh thú y (Mẫu 26 TS) tại trang 73: 'Cac vat dung (phucmg tifn, dung cu, bao bl chua dung, thicc an, chat dpn, chat that) co lien quan:..................................................................................................................'.",2);
  add(5,"Sau khi tiến hành xử lý vệ sinh thú y, địa điểm xử lý hàng động vật, sản phẩm động vật thủy sản phải tuân thủ yêu cầu nào theo Quyết định (Mẫu 26 TS)?",["Chỉ cần dọn dẹp sạch sẽ.", "Phải được vệ sinh, khử trùng tiêu độc theo quy định.", "Chỉ cần thông gió tự nhiên.", "Phải được niêm phong và không sử dụng trong 24 giờ."],1,"Dựa trên Điều 6 của Quyết định xử lý vệ sinh thú y (Mẫu 26 TS) tại trang 73: 'Dieu 6. Nai xu ly hang phai dugrc v§ sinh, khu trung tieu dpc theo quy djnh.'",1);
  add(5,"Quyết định xử lý vệ sinh thú y (Mẫu 26 TS) được lập thành 03 bản và do những đối tượng nào giữ?",["Cơ quan kiểm dịch động vật, cơ quan Hải quan cửa khẩu, tổ chức/cá nhân thực hiện xử lý hàng.", "Cơ quan kiểm dịch động vật, chủ hàng hoặc người đại diện, tổ chức/cá nhân thực hiện xử lý hàng.", "Cơ quan kiểm dịch động vật, Bộ Nông nghiệp và Phát triển nông thôn, chủ hàng.", "Cơ quan Hải quan cửa khẩu, chủ hàng, tổ chức/cá nhân thực hiện xử lý hàng."],1,"Dựa trên đoạn văn bản cuối cùng của Quyết định xử lý vệ sinh thú y (Mẫu 26 TS) tại trang 73: 'Quyet dinh nay lap thanh 03 ban: 01 ban do co quan kiem dfch dgng vat giu, 01 ban do chit hang hoqc ngu&i dqi dien gitt, 01 ban do to chuc, cd nhan thuc hi$n xu ly hang giu.'",1);
  add(5,"Căn cứ để tiến hành lập Biên bản xử lý vệ sinh thú y đối với động vật, sản phẩm động vật thủy sản (Mẫu 27 TS) là gì?",["Biên bản ghi nhận tình trạng vệ sinh thú y.", "Quyết định xử lý vệ sinh thú y đối với hàng không bảo đảm yêu cầu vệ sinh thú y.", "Yêu cầu từ chủ hàng hoặc người đại diện.", "Quy trình kiểm dịch động vật, sản phẩm động vật thủy sản."],1,"Dựa trên đoạn văn bản 'Can cix Quyet dinh xu ly ve sinh thu y d6i vdi hang dpng vat, san pham dong v$t thuy sin khong bao dam yeu cau ve sinh thu y so /QB-XLVSTY ngiy........./...... / cua (0) Ba tiln hanh xu ly ve sinh thu y 16 hang sau:' (Trang 74, phần Biên bản xử lý vệ sinh thú y).",1);
  add(5,"Trong quá trình lập Biên bản xử lý vệ sinh thú y (Mẫu 27 TS), những đối tượng nào bắt buộc phải có mặt và ký tên?",["Cán bộ cơ quan kiểm dịch động vật và đại diện Hải quan cửa khẩu.", "Cán bộ cơ quan kiểm dịch động vật và chủ hàng (hoặc người đại diện).", "Cán bộ cơ quan kiểm dịch động vật, chủ hàng và người làm chứng (nếu có).", "Cán bộ cơ quan kiểm dịch động vật, đại diện Hải quan cửa khẩu và chủ hàng."],1,"Dựa trên phần 'Chung toi gom:' và các vị trí ký tên ở cuối Biên bản xử lý vệ sinh thú y (Mẫu 27 TS) tại trang 74, chỉ có 'can bp ca quan kiem dich dong vat' và 'chu hang (nguai tfai dien)' là bắt buộc. Người làm chứng là 'nếu có'.",2);
  add(5,"Theo quy định về Biên bản xử lý vệ sinh thú y đối với lô hàng, thông tin nào sau đây KHÔNG bắt buộc phải ghi trong các mục chi tiết của biên bản?",["Email và Fax của cơ quan kiểm dịch động vật.", "Biện pháp xử lý và địa điểm tiến hành xử lý.", "Tên và địa chỉ của chủ hàng hoặc người đại diện.", "Thời gian tiến hành xử lý và phương pháp khử trùng tiêu độc."],2,"Mục 'Tên, địa chỉ tổ chức, cá nhân thực hiện xử lý hàng' là bắt buộc, nhưng 'Tên và địa chỉ của chủ hàng hoặc người đại diện' không được liệt kê riêng trong các mục cần điền chi tiết của biên bản. Các mục khác như Email, Fax, Biện pháp xử lý, Địa điểm, Thời gian, Phương pháp khử trùng đều được liệt kê rõ ràng trong nội dung biên bản.",1);
  add(5,"Theo Biên bản xử lý vệ sinh thú y, đối với lô hàng đã được xử lý vệ sinh thú y nhưng không phải tiêu hủy, có mấy phương án sử dụng được quy định?",["2 phương án.", "3 phương án.", "4 phương án.", "1 phương án."],1,"Mục 'Quy định về việc sử dụng hàng sau khi đã xử lý vệ sinh thú y (nếu không phải tiêu hủy)' liệt kê 3 phương án: 1/ Được phép sử dụng làm thực phẩm; 2/ Được phép sử dụng làm thức ăn chăn nuôi, thức ăn thủy sản; 3/ Chỉ được phép chế biến nguyên liệu cho công nghiệp.",1);
  add(5,"Biên bản xử lý vệ sinh thú y đối với lô hàng được lập thành mấy bản và được lưu giữ tại những cơ quan, cá nhân nào?",["02 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ.", "03 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ, 01 bản do tổ chức, cá nhân thực hiện việc xử lý vệ sinh thú y đối với lô hàng giữ.", "03 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do tổ chức, cá nhân thực hiện xử lý giữ, 01 bản do các cơ quan liên quan giữ.", "04 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ, 01 bản do tổ chức, cá nhân thực hiện xử lý giữ, 01 bản do các cơ quan liên quan giữ."],1,"Đoạn văn bản ghi rõ: 'Biên bản này lập thành 03 bản: 01 bản do cơ quan kiểm dịch động vật giữ, 01 bản do chủ hàng hoặc người đại diện giữ, 01 bản do tổ chức, cá nhân thực hiện việc xử lý vệ sinh thú y đối với lô hàng giữ.'",1);
  add(5,"Những đối tượng nào sau đây có trách nhiệm ký xác nhận vào Biên bản xử lý vệ sinh thú y đối với lô hàng?",["Kiểm dịch viên động vật, Chủ hàng (hoặc người đại diện), Tổ chức, cá nhân thực hiện xử lý hàng.", "Kiểm dịch viên động vật, Chủ hàng (hoặc người đại diện), Các cơ quan liên quan.", "Kiểm dịch viên động vật, Tổ chức, cá nhân thực hiện xử lý hàng, Các cơ quan liên quan.", "Kiểm dịch viên động vật, Chủ hàng (hoặc người đại diện), Tổ chức, cá nhân thực hiện xử lý hàng, Các cơ quan liên quan."],3,"Phần cuối của Biên bản liệt kê các chữ ký cần có: 'Kiểm dịch viên động vật', 'Chủ hàng (hoặc người đại diện)', 'Tổ chức, cá nhân thực hiện xử lý hàng', và 'Các cơ quan liên quan'.",1);
  add(5,"Theo Phụ lục VI của Thông tư 26/2016/TT-BNNPTNT, các bệnh nào sau đây được liệt kê để giám sát hoặc công nhận an toàn dịch bệnh đối với tôm nước lợ?",["Bệnh đốm trắng (WSV), Bệnh đầu vàng (YHV), Bệnh hoại tử gan tụy cấp (AHPND).", "Bệnh xuất huyết mùa xuân (SVC), Bệnh do KHV.", "Bệnh gan thận mủ cá da trơn.", "Bệnh hoại tử thần kinh (VNN/VER)."],0,"Mục 1 'Đối với tôm nước lợ' liệt kê các bệnh: Đốm trắng (WSV), Đầu vàng (YHV), Hội chứng Taura, Hoại tử đuôi vỏ cơ quan biểu mô (IHHNV), Hoại tử gan tụy cấp (AHPND), Hoại tử cơ (Infectious Myonecrosis Disease), Vi bào tử trùng. Phương án A bao gồm 3 bệnh trong số đó.",1);
  add(5,"Theo Phụ lục VI của Thông tư 26/2016/TT-BNNPTNT, các bệnh nào sau đây được liệt kê để giám sát hoặc công nhận an toàn dịch bệnh đối với cá chép?",["Bệnh đốm trắng (WSV), Bệnh đầu vàng (YHV).", "Bệnh xuất huyết mùa xuân (SVC), Bệnh do KHV (Koi Herpesvirus Disease).", "Bệnh gan thận mủ cá da trơn.", "Bệnh hoại tử thần kinh (VNN/VER), Bệnh nhiễm khuẩn do vi khuẩn Streptococcus."],1,"Mục 2 'Đối với cá chép' liệt kê các bệnh: Xuất huyết mùa xuân (SVC), Bệnh do KHV (Koi Herpesvirus Disease).",1);
  add(5,"Mục đích chính của Biểu mẫu quản lý, theo dõi đối với các cơ sở nuôi trồng thủy sản và cơ sở thu gom, kinh doanh động vật thủy sản giống (Phụ lục VI) là gì?",["Để thống kê tổng sản lượng giống thủy sản trên toàn quốc.", "Để làm cơ sở thực hiện việc kiểm dịch vận chuyển động vật thủy sản sử dụng làm giống ra khỏi địa bàn cấp tỉnh.", "Để cấp phép kinh doanh cho các cơ sở nuôi trồng và kinh doanh thủy sản.", "Để theo dõi tình hình dịch bệnh thủy sản phục vụ nghiên cứu khoa học."],1,"Phần 'Ghi chú' ở cuối Phụ lục VI nêu rõ: 'Cơ quan kiểm dịch động vật nội địa lập danh sách các cơ sở nuôi trồng thủy sản; cơ sở thu gom, kinh doanh động vật thủy sản sử dụng làm giống theo Biểu mẫu này để làm cơ sở thực hiện việc kiểm dịch vận chuyển động vật thủy sản sử dụng làm giống ra khỏi địa bàn cấp tỉnh.'",2);
  add(5,"Một cơ sở nuôi cá tra giống tại An Giang muốn vận chuyển lô cá tra giống đến một tỉnh khác để cung cấp cho các hộ nuôi. Theo quy định của Thông tư 26/2016/TT-BNNPTNT, cơ quan kiểm dịch động vật nội địa sẽ căn cứ vào thông tin nào để thực hiện việc kiểm dịch vận chuyển?",["Giấy chứng nhận đăng ký kinh doanh của cơ sở nuôi cá tra giống.", "Danh sách các cơ sở nuôi trồng thủy sản được công nhận an toàn dịch bệnh hoặc giám sát dịch bệnh theo Phụ lục VI.", "Hợp đồng mua bán giữa cơ sở nuôi và các hộ nuôi.", "Báo cáo tài chính của cơ sở nuôi cá tra giống."],1,"Theo phần 'Ghi chú' của Phụ lục VI, cơ quan kiểm dịch động vật nội địa sẽ lập danh sách các cơ sở nuôi trồng thủy sản, cơ sở thu gom, kinh doanh động vật thủy sản sử dụng làm giống theo Biểu mẫu này để làm cơ sở thực hiện việc kiểm dịch vận chuyển động vật thủy sản sử dụng làm giống ra khỏi địa bàn cấp tỉnh. Do đó, danh sách theo Phụ lục VI là căn cứ chính để thực hiện kiểm dịch vận chuyển.",3);
  add(5,"Theo Phụ lục VI của Thông tư 26/2016/TT-BNNPTNT, bệnh nào sau đây được liệt kê để giám sát hoặc công nhận an toàn dịch bệnh đối với cá tra?",["Bệnh xuất huyết mùa xuân (SVC).", "Bệnh do KHV.", "Bệnh gan thận mủ cá da trơn (Enteric Septicaemia of Catfish).", "Bệnh hoại tử thần kinh (VNN/VER)."],2,"Mục 3 'Đối với cá tra' liệt kê bệnh 'Gan thận mủ cá da trơn (Enteric Septicaemia of Catfish)'.",1);
  add(5,"Theo Phụ lục VI của Thông tư 26/2016/TT-BNNPTNT, bệnh nào sau đây được liệt kê để giám sát hoặc công nhận an toàn dịch bệnh đối với cá rô phi?",["Bệnh đốm trắng (WSV).", "Bệnh nhiễm khuẩn do vi khuẩn Streptococcus/Streptococcosis.", "Bệnh hoại tử gan tụy cấp (AHPND).", "Bệnh hoại tử cơ (Infectious Myonecrosis Disease)."],1,"Mục 5 'Đối với cá rô phi' liệt kê bệnh 'Bệnh nhiễm khuẩn do vi khuẩn Streptococcus/Streptococcosis'.",1);
  add(5,"Theo Thông tư 26/2016, \"đơn vị bao gói\" được định nghĩa là gì?",["Là một sản phẩm động vật thủy sản được đóng gói độc lập trong một bao, kiện, thùng, hũ, chai, lọ, … lặp lại trong một lô hàng", "Là một lô hàng gồm nhiều sản phẩm khác nhau", "Là đơn vị tính trọng lượng của sản phẩm", "Là một loại thiết bị dùng trong quá trình kiểm dịch"],0,"Trong phần I – PHẦN CHUNG của Thông tư, \"đơn vị bao gói\" được mô tả là \"đóng gói độc lập sản phẩm dudi trong một bao, kiện, thùng, hũ, chai, lọ… lặp lại trong một lô hàng\".",1);
  add(5,"\"Mẫu chung\" được hiểu theo quy định là:",["Mẫu lấy từ một đơn vị bao gói duy nhất", "Các mẫu ban đầu từ cùng một đơn vị bao gói được trộn đều để tạo thành một mẫu đại diện", "Mẫu lấy từ nhiều lô hàng khác nhau", "Mẫu chỉ dùng để kiểm tra vệ sinh bề mặt bao bì"],1,"Theo văn bản, \"mẫu chung\" là \"những mẫu ban đầu từ cùng một đơn vị bao gói được trộn đều\" để đại diện cho toàn bộ lô hàng.",1);
  add(5,"Khi lấy mẫu cho một lô hàng có khối lượng >100 tấn, quy định về số vị trí lấy mẫu là:",["Không quá 5 vị trí", "Không quá 10 vị trí", "Không quá 15 vị trí", "Không giới hạn số vị trí"],2,"Văn bản quy định: \"Tiến hành kiểm tra tại 5 vị trí hoặc đơn vị bao gói ngẫu nhiên ở các điểm khác nhau của 16 hàng. Trường hợp 16 hàng (>100 tấn) kiểm tra thêm một số vị trí/đơn vị bao gói … không quá 15 vị trí/đơn vị bao gói\".",2);
  add(5,"Khối lượng tối thiểu của mẫu trung bình (hoặc mẫu ban đầu tương đương) phải nằm trong khoảng:",["100 – 500 g", "500 – 1 000 g (không bao gồm xuồng)", "500 – 10 000 g", "1 000 – 2 000 g"],1,"Trong mục 3.1.2, quy định: \"Khối lượng mẫu trung bình hoặc mẫu ban đầu (trường hợp mẫu ban đầu tương đương mẫu trung bình) từ 500 – 1 000 g (không bao gồm xuồng)\".",2);
  add(5,"Trong quy trình kiểm dịch, bước nào phải được thực hiện trước khi tiến hành lấy mẫu?",["Kiểm tra thực trạng hàng hóa", "Kiểm tra thiết bị và dụng cụ lấy mẫu", "Lập báo cáo kết quả", "Gửi mẫu đến phòng thí nghiệm"],1,"Phần II – QUY TRÌNH THỰC HIỆN, mục 1 – Chuẩn bị nêu rõ: \"Chuẩn bị khi tiến hành lấy mẫu phải thống nhất điểm tiến hành kiểm tra, lấy mẫu… chuẩn bị đầy hồ sơ, biểu mẫu, dụng cụ, trang thiết bị lấy mẫu…\" tức là kiểm tra thiết bị là bước chuẩn bị đầu tiên.",1);
  add(5,"Nếu trong quá trình kiểm tra thực trạng hàng hóa không đáp ứng yêu cầu, người lấy mẫu phải làm gì?",["Tiếp tục lấy mẫu như kế hoạch", "Dừng lấy mẫu, lập biên bản, báo cáo cơ quan kiểm tra", "Tăng số lượng mẫu để bù đắp", "Thay đổi nguồn cung cấp hàng hóa"],1,"Trong mục 2.1 và 2.2, khi hàng hóa không đạt yêu cầu, quy định yêu cầu \"người lấy mẫu không thực hiện lấy mẫu, lập biên bản, báo cáo cơ quan kiểm tra\".",3);
  add(5,"Mẫu phân tích được lấy nhằm mục đích:",["Đánh giá trung bình các chỉ tiêu kiểm dịch, kiểm tra vệ sinh thực phẩm", "Kiểm tra bao bì sản phẩm", "Đánh giá độ bền của sản phẩm khi bảo quản", "Xác định màu sắc và mùi vị của sản phẩm"],0,"Theo định nghĩa \"mẫu phân tích\" trong văn bản: \"là mẫu lấy ra để tính trung bình dùng phân tích các chỉ tiêu kiểm dịch, kiểm tra vệ sinh thực phẩm\".",2);
  add(5,"Khi lô hàng >100 tấn, người lấy mẫu được phép tăng thêm số đơn vị bao gói/khối lượng sản phẩm để tạo mẫu trung bình, với điều kiện:",["Không vượt quá tổng khối lượng đã lấy của 16 hàng <100 tấn", "Không vượt quá 10% tổng khối lượng lô", "Không vượt quá 5 đơn vị bao gói", "Không có bất kỳ điều kiện nào"],0,"Văn bản quy định: \"Trường hợp 16 hàng (>100 tấn), người lấy mẫu được phép lấy thêm số đơn vị bao gói/khối lượng sản phẩm để tạo mẫu trung bình (số lượng lấy thêm không hơn số lượng đã lấy của 16 hàng <100 tấn), đảm bảo mẫu phân tích đại diện cho 16 hàng\".",3);
  add(5,"Theo Thông tư 26/2016/TT-BNNPTNT, khi lấy mẫu ban đầu đối với sản phẩm dạng lỏng, sệt, mẫu được lấy tại ít nhất bao nhiêu vị trí ở các độ sâu khác nhau trong đơn vị bao gói sau khi đã khuấy đều?",["A. 3 vị trí", "B. 5 vị trí", "C. 7 vị trí", "D. 10 vị trí"],1,"Theo Điểm 3.2.1.a, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Sản phẩm dạng lỏng, sệt: mẫu ban đầu được lấy tại ít nhất 5 vị trí ở các độ sâu khác nhau trong đơn vị bao gói sau khi đã khuấy đều.'",1);
  add(5,"Đối với lô hàng rời (chứa trong các toa xe, container, hầm tàu,...), mẫu ban đầu được lấy ở ít nhất bao nhiêu vị trí khác nhau của lô hàng?",["A. 3 vị trí", "B. 5 vị trí", "C. 7 vị trí", "D. 10 vị trí"],1,"Theo Điểm 3.2.1.b, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Với lô hàng rời (chứa trong các toa xe, container, hầm tàu,...): lấy mẫu ban đầu ở ít nhất 5 vị trí khác nhau của lô hàng.'",1);
  add(5,"Khi một lô hàng có không quá 10 đơn vị bao gói (pallet), việc lấy mẫu ban đầu được thực hiện như thế nào?",["A. Lấy mẫu ngẫu nhiên 50% số đơn vị bao gói.", "B. Lấy mẫu tại tất cả các đơn vị bao gói.", "C. Lấy mẫu tại tối đa 5 đơn vị bao gói.", "D. Lấy mẫu tại 1 đơn vị bao gói đại diện."],1,"Theo Điểm 3.2.1, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Nếu lô hàng có không quá 10 đơn vị bao gói (pallet) thì lấy mẫu ban đầu ở tất cả các đơn vị bao gói.'",1);
  add(5,"Đối với lô hàng có khối lượng lớn hơn 100 tấn, việc lấy mẫu ban đầu được thực hiện ở không quá bao nhiêu đơn vị bao gói?",["A. 10 đơn vị bao gói", "B. 12 đơn vị bao gói", "C. 15 đơn vị bao gói", "D. 20 đơn vị bao gói"],2,"Theo Điểm 3.2.1, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Trường hợp lô hàng > 100 tấn, lấy ở không quá 15 đơn vị bao gói.'",1);
  add(5,"Theo quy định, việc lập mẫu chung được thực hiện bằng cách nào?",["A. Chọn ngẫu nhiên một số mẫu ban đầu để làm mẫu chung.", "B. Gộp tất cả các mẫu ban đầu đã lấy được.", "C. Chỉ lấy mẫu từ các đơn vị bao gói đại diện.", "D. Trộn đều các mẫu ban đầu và chia thành các phần bằng nhau."],1,"Theo Điểm 3.2.2, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Gộp tất cả các mẫu ban đầu đã lấy được để lập mẫu chung, đại diện cho lô hàng.'",1);
  add(5,"Khi lập mẫu trung bình cho sản phẩm dạng lỏng, sệt, quy trình nào sau đây là đúng?",["A. Lấy trực tiếp một lượng từ mẫu chung mà không cần trộn.", "B. Trộn kỹ mẫu chung và rút ra một lượng để lập mẫu trung bình.", "C. Chia mẫu chung thành các phần nhỏ và lấy ngẫu nhiên một phần.", "D. Chỉ lấy mẫu từ phần trên cùng của mẫu chung."],1,"Theo Điểm 3.2.3.a, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Sản phẩm dạng lỏng, sệt: trộn kỹ mẫu chung và rút ra một lượng để lập mẫu trung bình.'",1);
  add(5,"Yêu cầu về khối lượng mẫu trung bình là gì?",["A. Đảm bảo đủ để phân tích một chỉ tiêu duy nhất.", "B. Đảm bảo đủ để phân tích các chỉ tiêu và lưu mẫu.", "C. Không quá 1kg cho mỗi lô hàng.", "D. Tối thiểu 500g cho mỗi loại sản phẩm."],1,"Theo Điểm 3.2.3.đ, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Khối lượng mẫu trung bình đảm bảo đủ để phân tích các chỉ tiêu và lưu mẫu.'",1);
  add(5,"Từ mẫu trung bình, việc chia mẫu phân tích và mẫu lưu được quy định như thế nào?",["A. Mẫu phân tích gấp đôi mẫu lưu.", "B. Mẫu phân tích và mẫu lưu có số lượng/khối lượng mẫu như nhau.", "C. Mẫu lưu gấp đôi mẫu phân tích.", "D. Chỉ cần có mẫu phân tích, không bắt buộc phải có mẫu lưu."],1,"Theo Điểm 3.2.4, Mục 3.2, Trang 81 của tài liệu trích dẫn: 'Từ mẫu trung bình chia thành 2 phần tương ứng, 1 phần là mẫu phân tích, một phần là mẫu lưu có số lượng/khối lượng mẫu như nhau.'",1);
  add(5,"Mẫu phải được bảo quản theo điều kiện nào?",["A. Luôn bảo quản ở nhiệt độ phòng.", "B. Bảo quản theo điều kiện phù hợp với từng dạng sản phẩm như nguyên trạng ban đầu.", "C. Bảo quản trong điều kiện đông lạnh tuyệt đối.", "D. Bảo quản trong điều kiện khô ráo, thoáng mát, tránh ánh sáng trực tiếp."],1,"Theo Điểm 3.2.5.b, Mục 3.2, Trang 82 của tài liệu trích dẫn: 'Bảo quản mẫu: mẫu được bảo quản theo điều kiện phù hợp với từng dạng sản phẩm như nguyên trạng ban đầu.'",1);
  add(5,"Biên bản lấy mẫu được lập theo mẫu nào và vào thời điểm nào?",["A. Theo mẫu do cơ quan kiểm dịch tự ban hành, trước khi lấy mẫu.", "B. Theo mẫu 24 TS ban hành kèm theo Phụ lục V Thông tư này, ngay sau khi lấy mẫu.", "C. Theo mẫu chung của Bộ Nông nghiệp và Phát triển nông thôn, sau khi có kết quả phân tích.", "D. Theo mẫu của chủ hàng, trong vòng 24 giờ sau khi lấy mẫu."],1,"Theo Điểm 3.2.6, Mục 3.2, Trang 82 của tài liệu trích dẫn: 'Biên bản lấy mẫu được lập theo mẫu 24 TS ban hành kèm theo Phụ lục V Thông tư này ngay sau khi lấy mẫu dưới sự chứng kiến và ký xác nhận của chủ hàng và các bên liên quan.'",1);
  add(5,"Những thông tin nào sau đây KHÔNG BẮT BUỘC phải có trong Biên bản lấy mẫu?",["A. Tình trạng bao gói và bảo quản lô hàng.", "B. Ngày sản xuất và hạn sử dụng.", "C. Tên và địa chỉ của phòng thử nghiệm sẽ phân tích mẫu.", "D. Ký hiệu phương tiện vận chuyển và số niêm phong."],2,"Theo Điểm 3.2.6, Mục 3.2, Trang 82 của tài liệu trích dẫn: 'Các thông tin trong Biên bản lấy mẫu phải được ghi đầy đủ, chính xác, phản ánh trung thực tình trạng lô hàng như bao gói, bảo quản, ngày sản xuất, hạn sử dụng, ký hiệu phương tiện vận chuyển, chứa đựng, số niêm phong.' Tên và địa chỉ của phòng thử nghiệm không được liệt kê là thông tin bắt buộc.",2);
  add(5,"Khi vận chuyển mẫu đến phòng thử nghiệm, yêu cầu nào sau đây là KHÔNG ĐÚNG?",["A. Mẫu phải được vận chuyển đến phòng thử nghiệm càng nhanh càng tốt.", "B. Phương tiện vận chuyển phải đảm bảo không ảnh hưởng đến chất lượng mẫu.", "C. Nhãn/ký mẫu phải ghi đầy đủ thông tin và đảm bảo không bị nhoe, rách.", "D. Dụng cụ chứa đựng mẫu phải được làm kín nhưng không cần bảo vệ khỏi tác động của ánh sáng, nhiệt độ cao."],3,"Theo Điểm 3.2.7.b, Mục 3.2, Trang 82 của tài liệu trích dẫn: 'Dụng cụ chứa đựng mẫu gửi đến phòng thử nghiệm phải được làm kín và bảo vệ khỏi tác động của ánh sáng, nhiệt độ cao ảnh hưởng đến chất lượng mẫu.' Do đó, phương án D là không đúng.",2);
  add(5,"Thời gian lưu mẫu được quy định như thế nào?",["A. Tối đa 30 ngày kể từ ngày lấy mẫu.", "B. Tương ứng với thời gian hiệu lực của Giấy chứng nhận kiểm dịch cấp cho lô hàng.", "C. Cho đến khi lô hàng được tiêu thụ hết.", "D. Theo hướng dẫn của cơ quan kiểm dịch địa phương."],1,"Theo Điểm 3.2.8, Mục 3.2, Trang 82 của tài liệu trích dẫn: 'Mẫu lưu được bảo quản ở điều kiện bảo quản theo hướng dẫn của nhà sản xuất trong thời gian tương ứng với thời gian hiệu lực của Giấy chứng nhận kiểm dịch cấp cho lô hàng.'",1);
  add(5,"Trong trường hợp nào thì cơ quan kiểm dịch phải lập Biên bản trả lại mẫu thừa cho chủ hàng?",["A. Khi chủ hàng yêu cầu trả lại mẫu sau khi có kết quả phân tích.", "B. Khi không thể lấy mẫu tại nơi kiểm tra mà phải đưa các đơn vị mẫu ban đầu về nơi đủ điều kiện để lấy mẫu.", "C. Khi mẫu bị hỏng hoặc không đủ để phân tích.", "D. Khi chủ hàng từ chối nhận lại lô hàng sau kiểm dịch."],1,"Theo Điểm 3.2.9, Mục 3.2, Trang 82 của tài liệu trích dẫn: 'Trường hợp không thể lấy mẫu tại nơi kiểm tra mà phải đưa các đơn vị mẫu ban đầu về nơi đủ điều kiện đảm bảo chất lượng hàng hóa để lấy mẫu thì sau khi lấy mẫu, lập biên bản trả lại mẫu thừa cho chủ hàng (Mẫu Biên bản trả lại mẫu thừa ban hành kèm theo Phụ lục này).'",2);
  add(5,"Khi một lô hàng có nhiều mặt hàng, cơ quan kiểm dịch được phép lựa chọn tối đa bao nhiêu mặt hàng để lấy mẫu?",["A. 01 mặt hàng", "B. 02 mặt hàng", "C. 03 mặt hàng", "D. 05 mặt hàng"],2,"Theo Điểm 4, Mục II, Trang 82 của tài liệu trích dẫn: 'Kiểm tra, lấy mẫu theo quy định tại điểm 2 mục II và điểm 3 mục II Phụ lục này đối với từng loại mặt hàng (lựa chọn tối đa không quá 03 mặt hàng để lấy mẫu).'",1);
  add(5,"Thông tư số 47/2009/TT-BNNPTNT ban hành bao nhiêu Quy chuẩn kỹ thuật quốc gia về điều kiện an toàn vệ sinh thực phẩm trong sản xuất thủy sản?",["10 Quy chuẩn", "12 Quy chuẩn", "13 Quy chuẩn", "15 Quy chuẩn"],2,"Điều 1 của Thông tư 47/2009/TT-BNNPTNT quy định ban hành kèm theo Thông tư này 13 Quy chuẩn kỹ thuật quốc gia về điều kiện an toàn vệ sinh thực phẩm trong sản xuất Thuỷ sản.",1);
  add(5,"Thông tư số 47/2009/TT-BNNPTNT có hiệu lực thi hành vào thời điểm nào?",["Ngày 31 tháng 07 năm 2009", "Ngày 01 tháng 01 năm 2010", "Ngày 31 tháng 01 năm 2010", "Ngày 01 tháng 02 năm 2010"],3,"Điều 2 của Thông tư 47/2009/TT-BNNPTNT quy định Thông tư này có hiệu lực sau 6 tháng, kể từ ngày ký ban hành. Thông tư được ký ban hành ngày 31 tháng 07 năm 2009. Do đó, 6 tháng sau là ngày 31 tháng 01 năm 2010, và có hiệu lực từ ngày 01 tháng 02 năm 2010.",2);
  add(5,"Cơ quan nào đã ban hành Thông tư số 47/2009/TT-BNNPTNT về Quy chuẩn kỹ thuật quốc gia về điều kiện an toàn vệ sinh thực phẩm trong sản xuất thủy sản?",["Bộ Y tế", "Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Công Thương", "Tổng cục Thủy sản"],1,"Thông tư được ban hành bởi Bộ Nông nghiệp và Phát triển nông thôn, thể hiện rõ ở phần đầu văn bản và ký hiệu Số: 47/2009/TT-BNNPTNT.",1);
  add(3,"Quy chuẩn kỹ thuật quốc gia nào quy định về Chương trình đảm bảo chất lượng và an toàn thực phẩm theo nguyên tắc HACCP cho cơ sở sản xuất kinh doanh thực phẩm thủy sản?",["QCVN 02 - 01: 2009/BNNPTNT", "QCVN 02 - 02: 2009/BNNPTNT", "QCVN 02 - 03: 2009/BNNPTNT", "QCVN 02 - 04: 2009/BNNPTNT"],1,"Khoản 2 Điều 1 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Quy chuẩn kỹ thuật quốc gia: Cơ sở sản xuất kinh doanh thực phẩm thuỷ sản - Chương trình đảm bảo chất lượng và an toàn thực phẩm theo nguyên tắc HACCP\" có Ký hiệu: QCVN 02 - 02: 2009/BNNPTNT.",1);
  add(3,"Một cơ sở chuyên sản xuất nước đá dùng trong bảo quản thủy sản cần tuân thủ Quy chuẩn kỹ thuật quốc gia nào được ban hành kèm theo Thông tư 47/2009/TT-BNNPTNT?",["QCVN 02 - 01: 2009/BNNPTNT", "QCVN 02 - 06: 2009/BNNPTNT", "QCVN 02 - 08: 2009/BNNPTNT", "QCVN 02 - 09: 2009/BNNPTNT"],2,"Khoản 8 Điều 1 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Quy chuẩn kỹ thuật quốc gia: Cơ sở sản xuất nước đá thuỷ sản - Điều kiện đảm bảo vệ sinh an toàn thực phẩm\" có Ký hiệu: QCVN 02 - 08: 2009/BNNPTNT.",2);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, Quy chuẩn kỹ thuật quốc gia nào áp dụng cho \"Kho lạnh thủy sản\"?",["QCVN 02 - 07: 2009/BNNPTNT", "QCVN 02 - 08: 2009/BNNPTNT", "QCVN 02 - 09: 2009/BNNPTNT", "QCVN 02 - 10: 2009/BNNPTNT"],2,"Khoản 9 Điều 1 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Quy chuẩn kỹ thuật quốc gia: Kho lạnh thuỷ sản - Điều kiện đảm bảo vệ sinh an toàn thực phẩm\" có Ký hiệu: QCVN 02 - 09: 2009/BNNPTNT.",1);
  add(5,"Ai là người có trách nhiệm chính trong việc tổ chức thực hiện Thông tư 47/2009/TT-BNNPTNT?",["Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn", "Cục trưởng Cục Quản lý chất lượng Nông lâm sản và Thủy sản", "Thủ trưởng các cơ quan, tổ chức và cá nhân có liên quan", "Cả B và C đều đúng"],3,"Điều 3 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Cục trưởng Cục Quản lý chất lượng Nông lâm sản và Thủy sản, Thủ trưởng các cơ quan, tổ chức và cá nhân có liên quan có trách nhiệm tổ chức thực hiện.\"",1);
  add(5,"Một doanh nghiệp đang xây dựng nhà máy chế biến thủy sản ăn liền vào tháng 10 năm 2009. Theo Thông tư 47/2009/TT-BNNPTNT, doanh nghiệp này cần lưu ý điều gì về việc áp dụng các Quy chuẩn kỹ thuật quốc gia?",["Các Quy chuẩn kỹ thuật quốc gia đã có hiệu lực ngay từ ngày ký ban hành Thông tư.", "Doanh nghiệp phải tuân thủ các Quy chuẩn kỹ thuật quốc gia liên quan ngay lập tức.", "Các Quy chuẩn kỹ thuật quốc gia sẽ có hiệu lực sau 6 tháng kể từ ngày ký ban hành Thông tư, tức là doanh nghiệp có thời gian chuẩn bị.", "Doanh nghiệp không cần tuân thủ các Quy chuẩn này vì chúng chỉ áp dụng cho các cơ sở đã hoạt động trước đó."],2,"Điều 2 của Thông tư 47/2009/TT-BNNPTNT quy định Thông tư này có hiệu lực sau 6 tháng, kể từ ngày ký ban hành (31/07/2009). Do đó, các Quy chuẩn kỹ thuật quốc gia sẽ bắt đầu có hiệu lực từ ngày 01/02/2010. Doanh nghiệp có thời gian để chuẩn bị và áp dụng các quy định này.",3);
  add(3,"Quy chuẩn kỹ thuật quốc gia nào quy định điều kiện đảm bảo vệ sinh an toàn thực phẩm cho \"Cảng cá\"?",["QCVN 02 - 10: 2009/BNNPTNT", "QCVN 02 - 11: 2009/BNNPTNT", "QCVN 02 - 12: 2009/BNNPTNT", "QCVN 02 - 13: 2009/BNNPTNT"],2,"Khoản 12 Điều 1 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Quy chuẩn kỹ thuật quốc gia: Cảng cá - Điều kiện đảm bảo vệ sinh an toàn thực phẩm\" có Ký hiệu: QCVN 02 - 12: 2009/BNNPTNT.",1);
  add(5,"Nếu trong quá trình thực hiện Thông tư 47/2009/TT-BNNPTNT có vướng mắc, các cơ quan, tổ chức và cá nhân cần phản ánh về đâu để được nghiên cứu, sửa đổi, bổ sung?",["Cục Quản lý chất lượng Nông lâm sản và Thủy sản", "Bộ Tư pháp", "Bộ Nông nghiệp và Phát triển nông thôn", "UBND các Tỉnh, TP trực thuộc TƯ"],2,"Điều 3 của Thông tư 47/2009/TT-BNNPTNT nêu rõ: \"Trong quá trình thực hiện, nếu có vướng mắc, các cơ quan, tổ chức và cá nhân kịp thời phản ánh về Bộ Nông nghiệp và Phát triển nông thôn để nghiên cứu, sửa đổi, bổ sung./.\"",1);
  add(3,"Quy chuẩn kỹ thuật quốc gia QCVN 02-01:2009/BNNPTNT về điều kiện an toàn thực phẩm trong sản xuất thủy sản được ban hành kèm theo Thông tư nào của Bộ Nông nghiệp và Phát triển nông thôn?",["Thông tư 47/2009/TT-BNNPTNT", "Thông tư 26/2016/TT-BNNPTNT", "Thông tư 36/2018/TT-BNNPTNT", "Thông tư 01/2009/TT-BNNPTNT"],0,"Theo Lời nói đầu của QCVN 02-01:2009/BNNPTNT, Quy chuẩn này được ban hành kèm theo Thông tư 47/2009/TT-BNNPTNT ngày 31 tháng 7 năm 2009 của Bộ Nông Nghiệp và Phát triển nông thôn.",1);
  add(3,"Đối tượng nào KHÔNG thuộc phạm vi áp dụng của QCVN 02-01:2009/BNNPTNT?",["Các cơ sở sản xuất kinh doanh thủy sản dùng làm thực phẩm thuộc phạm vi quản lý của Bộ Nông nghiệp và phát triển nông thôn.", "Các cơ sở sản xuất thủy sản với mục đích tự tiêu dùng.", "Các cơ sở chế biến thủy sản xuất khẩu.", "Các cơ sở sơ chế thủy sản để cung cấp cho thị trường nội địa."],1,"Theo Khoản 1.2.2 Chương 1 của QCVN 02-01:2009/BNNPTNT, Quy chuẩn này không áp dụng cho các cơ sở sản xuất với mục đích tự tiêu dùng.",1);
  add(3,"Theo QCVN 02-01:2009/BNNPTNT, 'Sản phẩm thủy sản tươi' được định nghĩa như thế nào?",["Là các sản phẩm thủy sản đã qua gia nhiệt hoặc xông khói để bảo quản.", "Là các sản phẩm thủy sản, nguyên con hoặc đã sơ chế, chưa được sử dụng bất cứ hình thức xử lý nào để bảo quản ngoài việc làm lạnh.", "Là các sản phẩm thủy sản đã được đông lạnh tới -18oC hoặc thấp hơn.", "Là các sản phẩm thủy sản đã được ướp tẩm gia vị để kéo dài thời gian sử dụng."],1,"Theo Khoản 1.3.4 Chương 1 của QCVN 02-01:2009/BNNPTNT, 'Sản phẩm thủy sản tươi' là các sản phẩm thủy sản, nguyên con hoặc đã sơ chế, chưa được sử dụng bất cứ hình thức xử lý nào để bảo quản ngoài việc làm lạnh.",1);
  add(3,"Hoạt động nào sau đây được xem là 'Sơ chế' theo QCVN 02-01:2009/BNNPTNT?",["Gia nhiệt và xông khói sản phẩm.", "Làm chín và làm khô sản phẩm.", "Cắt, bỏ xương, làm sạch, làm lạnh.", "Ướp tẩm gia vị và chiết xuất."],2,"Theo Khoản 1.3.5 Chương 1 của QCVN 02-01:2009/BNNPTNT, 'Sơ chế' là hoạt động chia tách ra từng phần, cắt, bỏ xương, băm, lột da, nghiền, làm sạch, bóc vỏ, cán mỏng, làm lạnh, đông lạnh hay rã đông. Các phương án A, B, D thuộc định nghĩa 'Chế biến'.",2);
  add(3,"Theo QCVN 02-01:2009/BNNPTNT, nhiệt độ 'Đông lạnh' sản phẩm thủy sản phải đạt được là bao nhiêu?",["Tới, hoặc gần tới nhiệt độ đóng băng.", "Tới -18oC hoặc thấp hơn.", "Dưới 0oC nhưng không quá -5oC.", "Bất kỳ nhiệt độ nào dưới 0oC."],1,"Theo Khoản 1.3.8 Chương 1 của QCVN 02-01:2009/BNNPTNT, 'Đông lạnh' là quá trình làm giảm nhiệt độ của sản phẩm thuỷ sản tới -18oC hoặc thấp hơn.",1);
  add(3,"Định nghĩa nào sau đây mô tả đúng 'Nước sạch' theo QCVN 02-01:2009/BNNPTNT?",["Nước đã được lọc qua hệ thống lọc thô.", "Nước không màu, không mùi, không vị.", "Nước đáp ứng các yêu cầu dùng cho chế biến thực phẩm theo Quy định của Bộ Y tế.", "Nước được lấy từ giếng khoan sâu."],2,"Theo Khoản 1.3.11 Chương 1 của QCVN 02-01:2009/BNNPTNT, 'Nước sạch' là nước đáp ứng các yêu cầu dùng cho chế biến thực phẩm theo Quy định của Bộ Y tế.",1);
  add(3,"Một 'Lô hàng thủy sản' theo QCVN 02-01:2009/BNNPTNT phải đáp ứng những tiêu chí nào?",["Tập hợp nhiều cá thể của các đối tượng thủy sản khác nhau, có cùng điều kiện bảo quản.", "Tập hợp nhiều cá thể của cùng một đối tượng động thực vật thủy sản, có cùng một điều kiện bảo quản, thuộc một chủ sở hữu, được tập kết hoặc giao nhận cùng một thời gian và địa điểm.", "Tập hợp các sản phẩm thủy sản đã qua chế biến từ nhiều nhà cung cấp khác nhau.", "Tập hợp các sản phẩm thủy sản tươi sống được vận chuyển từ nhiều địa điểm khác nhau."],1,"Theo Khoản 1.3.13 Chương 1 của QCVN 02-01:2009/BNNPTNT, 'Lô hàng thủy sản' là tập hợp nhiều cá thể của cùng một đối tượng động thực vật thủy sản, có cùng một điều kiện bảo quản, thuộc một chủ sở hữu, được tập kết hoặc giao nhận cùng một thời gian và địa điểm.",2);
  add(3,"Khi lựa chọn địa điểm xây dựng cơ sở sản xuất kinh doanh thủy sản, yếu tố nào sau đây là BẮT BUỘC phải có theo QCVN 02-01:2009/BNNPTNT?",["Nằm gần khu dân cư đông đúc để tiện tuyển dụng lao động.", "Có nguồn nước đảm bảo cho các hoạt động sản xuất thực phẩm và thuận tiện về giao thông vận chuyển sản phẩm thực phẩm.", "Nằm tách biệt hoàn toàn với mọi tuyến đường giao thông.", "Có diện tích đất trống lớn để mở rộng sản xuất trong tương lai."],1,"Theo Khoản 2.1.1.3 Chương 2 của QCVN 02-01:2009/BNNPTNT, địa điểm xây dựng/bố trí cơ sở phải hội đủ các yếu tố: a. Có nguồn nước đảm bảo cho các hoạt động sản xuất thực phẩm. b. Thuận tiện về giao thông vận chuyển sản phẩm thực phẩm.",2);
  add(3,"Theo QCVN 02-01:2009/BNNPTNT, môi trường xung quanh cơ sở sản xuất kinh doanh thủy sản phải được bố trí như thế nào để đảm bảo an toàn thực phẩm?",["Khu vực xung quanh, đường, lối đi và các khu vực khác trong cơ sở phải lát bằng vật liệu cứng, bền, hoặc phủ cỏ, trồng cây và có hệ thống thoát nước tốt.", "Chỉ cần đảm bảo không có rác thải trong vòng 5 mét xung quanh cơ sở.", "Không cần quan tâm đến vật liệu lát nền, miễn là sạch sẽ.", "Chỉ cần có hệ thống thoát nước tốt, không yêu cầu về vật liệu lát nền."],0,"Theo Khoản 2.1.2 Chương 2 của QCVN 02-01:2009/BNNPTNT, khu vực xung quanh, đường, lối đi và các khu vực khác trong cơ sở phải lát bằng vật liệu cứng, bền, hoặc phủ cỏ, trồng cây (2.1.2.1) và có hệ thống thoát nước tốt cho khu vực chung quanh và dễ làm vệ sinh (2.1.2.2).",1);
  add(3,"Yêu cầu nào sau đây là bắt buộc đối với bố trí, thiết kế của cơ sở sản xuất kinh doanh thủy sản theo QCVN 02-01:2009/BNNPTNT?",["Các khu vực sản xuất phải có kích thước tối thiểu 100m2.", "Phải có tường bao ngăn cách với bên ngoài và các khu vực sản xuất phải có kích thước phù hợp, đảm bảo các hoạt động chế biến, bảo trì, làm vệ sinh hoặc khử trùng thích hợp.", "Cơ sở phải có ít nhất hai cổng ra vào riêng biệt.", "Chỉ cần đảm bảo không có động vật gây hại, không cần tường bao."],1,"Theo Khoản 2.1.3 Chương 2 của QCVN 02-01:2009/BNNPTNT, cơ sở phải có tường bao ngăn cách với bên ngoài (2.1.3.1) và các khu vực sản xuất phải có kích thước phù hợp, đảm bảo các hoạt động chế biến sản phẩm thuỷ sản, cho phép thực hiện được việc bảo trì, làm vệ sinh hoặc khử trùng thích hợp (2.1.3.2).",2);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, việc phân luồng riêng công nhân, nguyên liệu, bán thành phẩm, thành phẩm, nước đá, vật liệu bao gói và phế liệu trong khu vực sản xuất nhằm mục đích chính nào?",["Tăng tốc độ sản xuất và giảm chi phí vận hành.", "Hạn chế khả năng gây nhiễm chéo cho sản phẩm.", "Thuận tiện cho việc kiểm kê và quản lý kho.", "Giúp công nhân dễ dàng di chuyển giữa các khu vực."],1,"Điều 2.1.3.4 của Thông tư 47/2009/TT-BNNPTNT quy định rõ việc phân luồng riêng công nhân, nguyên liệu, bán thành phẩm, thành phẩm, nước đá, vật liệu bao gói và phế liệu trong quá trình sản xuất để hạn chế khả năng gây nhiễm chéo cho sản phẩm.",1);
  add(3,"Đặc điểm nào sau đây KHÔNG phải là yêu cầu đối với nền nhà xưởng khu vực sản xuất thủy sản theo Quy chuẩn kỹ thuật quốc gia?",["Có bề mặt cứng, chịu tải trọng.", "Không thấm và đọng nước, không trơn.", "Có khe hở, vết nứt nhỏ để thoát hơi ẩm.", "Dễ làm vệ sinh, khử trùng."],2,"Điều 2.1.4.1.a.iii của Thông tư 47/2009/TT-BNNPTNT quy định nền nhà xưởng phải 'Không có khe hở, vết nứt'. Phương án C mâu thuẫn với quy định này.",1);
  add(3,"Tại các khu vực ướt trong nhà xưởng sản xuất thủy sản, nền nhà xưởng phải có độ dốc tối thiểu là bao nhiêu để đảm bảo không bị đọng nước?",["Không nhỏ hơn 1:24.", "Không nhỏ hơn 1:36.", "Không nhỏ hơn 1:48.", "Không nhỏ hơn 1:60."],2,"Điều 2.1.4.2.a.i của Thông tư 47/2009/TT-BNNPTNT quy định nền nhà xưởng tại các khu ướt phải nhẵn và có độ dốc 'không nhỏ hơn 1:48', đảm bảo không bị đọng nước.",1);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia, hệ thống thoát nước khu vực sản xuất thủy sản phải được thiết kế như thế nào liên quan đến hệ thống thoát nước của khu vực vệ sinh?",["Được nối thông trực tiếp để tiết kiệm chi phí.", "Không được nối thông với hệ thống thoát nước của khu vực vệ sinh.", "Có thể nối thông nhưng phải có van khóa.", "Được nối thông nhưng phải qua hố ga chung."],1,"Điều 2.1.4.2.d của Thông tư 47/2009/TT-BNNPTNT nêu rõ 'Hệ thống thoát nước khu vực sản xuất không được nối thông với hệ thống thoát nước của khu vực vệ sinh.'",1);
  add(3,"Vật liệu làm tường ở các khu sản xuất sản phẩm thủy sản phải đáp ứng yêu cầu nào sau đây?",["Làm bằng vật liệu bền, không độc, không thấm nước và có màu sáng.", "Làm bằng vật liệu có khả năng hấp thụ ẩm tốt để kiểm soát độ ẩm.", "Có thể có các vết nứt nhỏ để thông gió tự nhiên.", "Có màu tối để tránh phản xạ ánh sáng mạnh."],0,"Điều 2.1.4.3.a.i của Thông tư 47/2009/TT-BNNPTNT quy định tường phải 'Làm bằng vật liệu bền, không độc, không thấm nước và có màu sáng.'",1);
  add(3,"Tại các khu vực chế biến hoặc bao gói sản phẩm thủy sản có yêu cầu điều kiện vệ sinh cao, cửa ra vào, cửa sổ, lỗ thông gió KHÔNG được bố trí như thế nào?",["Mở thông ra môi trường chung quanh.", "Có lưới chắn côn trùng.", "Đóng kín được.", "Có màn chắn bằng nhựa trong."],0,"Điều 2.1.4.5.a của Thông tư 47/2009/TT-BNNPTNT quy định 'Cửa ra vào, cửa sổ, lỗ thông gió ở những nơi sản phẩm có yêu cầu điều kiện vệ sinh cao đang được chế biến hoặc bao gói không được bố trí mở thông ra môi trường chung quanh.'",1);
  add(3,"Để ngăn chặn sự xâm nhập của côn trùng và bụi bẩn từ bên ngoài vào các khu vực chế biến, cửa ra vào, ô cửa mở ra ngoài hoặc các nơi cần thiết phải có một trong các thiết bị nào sau đây, NGOẠI TRỪ?",["Màn chắn làm bằng nhựa trong, dễ làm vệ sinh.", "Màn khí thổi.", "Cửa tự động.", "Lưới chắn côn trùng cố định."],3,"Điều 2.1.4.5.đ của Thông tư 47/2009/TT-BNNPTNT liệt kê các giải pháp cho cửa ra vào, ô cửa mở ra ngoài hoặc các nơi cần thiết là: màn chắn làm bằng nhựa trong, màn khí thổi, hoặc cửa tự động. Lưới chắn côn trùng được đề cập ở 2.1.4.5.b cho cửa sổ và lỗ thông gió, nhưng không phải là một trong ba giải pháp được liệt kê cho cửa ra vào mở ra ngoài hoặc các nơi cần thiết.",2);
  add(3,"Trong các phòng chế biến thực phẩm thủy sản, hệ thống thông gió phải đảm bảo cho dòng không khí chuyển động theo chiều nào để duy trì vệ sinh?",["Từ nơi có yêu cầu vệ sinh thấp sang nơi có yêu cầu vệ sinh cao hơn.", "Từ nơi có yêu cầu vệ sinh cao sang nơi có yêu cầu vệ sinh thấp hơn.", "Luân chuyển tự do không theo chiều cố định.", "Từ khu vực có nhiệt độ cao sang khu vực có nhiệt độ thấp."],1,"Điều 2.1.4.7.d của Thông tư 47/2009/TT-BNNPTNT quy định 'Trong các phòng chế biến thực phẩm, phải đảm bảo cho dòng không khí chuyển động từ nơi có yêu cầu vệ sinh cao sang nơi có yêu cầu vệ sinh thấp hơn.'",2);
  add(3,"Đối với đèn chiếu sáng treo trên khu vực chế biến và bao gói sản phẩm thủy sản, Quy chuẩn kỹ thuật quốc gia yêu cầu gì?",["Phải có cường độ ánh sáng yếu để tránh làm hỏng sản phẩm.", "Phải an toàn và có chụp bảo hiểm.", "Chỉ được sử dụng ánh sáng tự nhiên.", "Không cần chụp bảo hiểm nếu ở độ cao lớn."],1,"Điều 2.1.4.8.b của Thông tư 47/2009/TT-BNNPTNT quy định 'Đèn chiếu sáng treo trên khu vực chế biến và bao gói phải an toàn và có chụp bảo hiểm.'",1);
  add(3,"Vật liệu chế tạo thiết bị và dụng cụ tiếp xúc trực tiếp hoặc gián tiếp với sản phẩm thủy sản phải đáp ứng yêu cầu nào sau đây?",["Có thể tạo ra mùi nhẹ nhưng không độc hại.", "Làm bằng vật liệu không tạo ra mùi và các chất độc ảnh hưởng đến chất lượng cảm quan và ATVS cho sản phẩm.", "Có khả năng ngấm nước để dễ dàng làm sạch.", "Có thể bị gỉ sét nhẹ theo thời gian sử dụng."],1,"Điều 2.1.5.1.a.i của Thông tư 47/2009/TT-BNNPTNT quy định vật liệu phải 'Làm bằng vật liệu không tạo ra mùi và các chất độc ảnh hưởng đến chất lượng cảm quan và ATVS và cho sản phẩm.'",1);
  add(3,"Một nhà máy chế biến thủy sản đang thiết kế hệ thống thoát nước thải cho khu vực sản xuất. Để tuân thủ Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP, kỹ sư thiết kế cần đảm bảo nguyên tắc nào cho các rãnh hở thoát nước thải?",["Nước chảy theo chiều từ khu vực yêu cầu điều kiện vệ sinh thấp sang khu vực yêu cầu điều kiện vệ sinh cao hơn.", "Nước chảy theo chiều từ khu vực yêu cầu điều kiện vệ sinh cao sang khu vực yêu cầu điều kiện vệ sinh thấp hơn.", "Nước chảy theo bất kỳ chiều nào miễn là thoát hết nước.", "Nước chảy theo chiều từ khu vực có nhiệt độ cao sang khu vực có nhiệt độ thấp."],1,"Điều 2.1.4.2.e của Thông tư 47/2009/TT-BNNPTNT quy định 'Các rãnh hở thoát nước thải, phải đảm bảo để nước chảy được theo chiều từ khu vực yêu cầu điều kiện vệ sinh cao sang khu vực yêu cầu điều kiện vệ sinh thấp hơn'. Điều này giúp ngăn ngừa sự lây nhiễm ngược từ khu vực ít vệ sinh sang khu vực đòi hỏi vệ sinh cao hơn.",3);
  add(3,"Một nhà máy chế biến thủy sản đang nâng cấp cửa ra vào từ khu vực đóng gói sản phẩm (yêu cầu vệ sinh cao) ra khu vực hành lang chung. Theo Quy chuẩn kỹ thuật quốc gia, giải pháp nào sau đây là phù hợp nhất để ngăn chặn bụi bẩn và côn trùng xâm nhập?",["Lắp đặt một tấm rèm vải dày.", "Sử dụng cửa tự động kết hợp với màn khí thổi.", "Chỉ cần lắp đặt cửa gỗ thông thường và đóng kín khi không sử dụng.", "Để cửa luôn mở để thông gió tự nhiên."],1,"Điều 2.1.4.5.đ của Thông tư 47/2009/TT-BNNPTNT quy định cửa ra vào, ô cửa mở ra ngoài hoặc các nơi cần thiết phải có: màn chắn làm bằng nhựa trong, hoặc màn khí thổi, hoặc cửa tự động. Việc sử dụng cửa tự động kết hợp với màn khí thổi là một giải pháp tối ưu, đáp ứng đầy đủ các yêu cầu về ngăn chặn bụi bẩn và côn trùng.",3);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, yêu cầu chung về vật liệu chế tạo máy móc, thiết bị tiếp xúc trực tiếp với sản phẩm là gì?",["Phải làm bằng vật liệu không bị ăn mòn, có thể rửa và khử trùng nhiều lần, bề mặt dễ làm vệ sinh.", "Có thể làm bằng bất kỳ vật liệu nào miễn là không gây độc hại cho sản phẩm.", "Ưu tiên sử dụng gỗ tự nhiên để đảm bảo tính thân thiện với môi trường.", "Chỉ cần đảm bảo độ bền cơ học, không yêu cầu về khả năng rửa và khử trùng."],0,"Theo Mục 2.1.5.1.a.ii và iii của Thông tư 47/2009/TT-BNNPTNT, vật liệu chế tạo máy móc, thiết bị tiếp xúc trực tiếp với sản phẩm phải 'không bị ăn mòn; có thể rửa và khử trùng nhiều lần' và 'Bề mặt dễ làm vệ sinh'.",1);
  add(3,"Loại dầu bôi trơn nào được phép sử dụng cho các bộ phận truyền động của máy móc, thiết bị chế biến có khả năng lây nhiễm cho sản phẩm thủy sản?",["Dầu máy thông thường, miễn là không nhỏ giọt vào sản phẩm.", "Dầu chuyên dùng cho máy thực phẩm.", "Bất kỳ loại dầu công nghiệp nào có khả năng chịu nhiệt cao.", "Dầu thực vật tự nhiên để đảm bảo an toàn."],1,"Theo Mục 2.1.5.1.c của Thông tư 47/2009/TT-BNNPTNT, 'Dầu bôi trơn các bộ phận truyền động của máy móc, thiết bị chế biến có khả năng lây nhiễm cho sản phẩm phải là dầu chuyên dùng cho máy thực phẩm. Không được sử dụng dầu máy thông thường'.",1);
  add(3,"Để đảm bảo dễ kiểm tra, dễ làm vệ sinh và khử trùng, thiết bị trong cơ sở sản xuất thủy sản cần được bố trí, lắp đặt như thế nào?",["Gắn chặt trực tiếp xuống sàn, không cần khoảng trống.", "Chừa khoảng trống đủ để làm vệ sinh giữa thiết bị và tường, giữa các thiết bị; nếu đặt trên chân đế phải cách mặt sàn ít nhất 0,3 m.", "Đặt sát tường để tiết kiệm không gian và tránh va chạm.", "Thiết bị đặt trên bệ không cần gờ cong giữa bệ và nền."],1,"Theo Mục 2.1.5.1.d của Thông tư 47/2009/TT-BNNPTNT, thiết bị phải được bố trí, lắp đặt để dễ kiểm tra, dễ làm vệ sinh và khử trùng toàn bộ bằng cách 'Chừa khoảng trống giữa thiết bị và tường, giữa thiết bị này với thiết bị khác đủ để làm vệ sinh' và 'Nếu thiết bị đặt trực tiếp trên sàn, phải được gắn chặt xuống sàn; hoặc nếu đặt trên bệ, giữa bệ và nền phải có gờ cong; hoặc đặt trên chân đế, phải cách mặt sàn ít nhất 0,3 m'.",2);
  add(3,"Yêu cầu nào sau đây là BẮT BUỘC đối với thùng chứa phế thải trong cơ sở sản xuất thủy sản?",["Phải làm bằng vật liệu không thấm nước, có nắp đậy kín khi vận chuyển ra ngoài và khi để ở bên ngoài.", "Có thể làm bằng gỗ để dễ phân hủy.", "Không cần có dấu hiệu phân biệt rõ với dụng cụ chứa sản phẩm.", "Chỉ cần dễ làm vệ sinh, không yêu cầu kín."],0,"Theo Mục 2.1.5.2.b của Thông tư 47/2009/TT-BNNPTNT, thùng chứa phế thải phải 'Kín, làm bằng vật liệu không thấm nước phù hợp, không bị ăn mòn' và 'Có nắp đậy kín khi vận chuyển ra ngoài và khi để ở bên ngoài'.",1);
  add(3,"Trong cơ sở sản xuất thủy sản, việc sử dụng gỗ được quy định như thế nào?",["Gỗ có thể được dùng làm bề mặt tiếp xúc với thực phẩm trong khu chế biến nếu được xử lý chống thấm.", "Có thể dùng các kệ gỗ sạch và chắc chắn để kê đỡ các dụng cụ chứa nguyên liệu hoặc thành phẩm được đóng gói kín.", "Gỗ được phép dùng làm cửa, khung cửa, cửa sổ mà không cần lớp phủ.", "Hoàn toàn cấm sử dụng gỗ trong bất kỳ khu vực nào của cơ sở sản xuất."],1,"Theo Mục 2.1.5.4.c của Thông tư 47/2009/TT-BNNPTNT, 'Có thể dùng các kệ gỗ sạch và chắc chắn để kê đỡ các dụng cụ chứa nguyên liệu hoặc thành phẩm được đóng gói kín ở tất cả các khu vực và trong các côngtenơ, phương tiện vận chuyển.' Mục 2.1.5.4.a cấm gỗ làm bề mặt tiếp xúc trực tiếp với thực phẩm, và Mục 2.1.5.4.b yêu cầu gỗ làm cửa, khung cửa... phải được phủ kín bằng lớp phủ bền và không độc.",2);
  add(3,"Khi sản phẩm thủy sản được đưa ra khỏi thiết bị cấp đông để bao gói và chuyển vào kho lạnh, nhiệt độ ở tâm sản phẩm phải đạt yêu cầu tối thiểu là bao nhiêu?",["-10oC", "-12oC", "-18oC", "-2oC"],2,"Theo Mục 2.1.5.5.c của Thông tư 47/2009/TT-BNNPTNT, 'Không được đưa sản phẩm ra khỏi thiết bị cấp đông để bao gói và chuyển vào kho lạnh nếu nhiệt độ ở tâm sản phẩm chưa đạt -18oC'.",1);
  add(3,"Trong trường hợp nhiệt kế tự ghi của kho lạnh bị hỏng, cơ sở sản xuất thủy sản phải thực hiện việc theo dõi nhiệt độ như thế nào?",["Dừng hoạt động kho lạnh cho đến khi nhiệt kế được sửa chữa.", "Tiến hành theo dõi và vẽ biểu đồ nhiệt độ với tần suất tối thiểu 2 giờ/1 lần.", "Chỉ cần kiểm tra nhiệt độ bằng nhiệt kế cầm tay mỗi ngày một lần.", "Báo cáo cơ quan quản lý và chờ hướng dẫn."],1,"Theo Mục 2.1.5.5.đ của Thông tư 47/2009/TT-BNNPTNT, 'Trong trường hợp nhiệt kế tự ghi hỏng, phải tiến hành theo dõi và vẽ biểu đồ nhiệt độ với tần suất tối thiểu 2giờ/1lần'.",2);
  add(3,"Theo Quy chuẩn, bộ cảm nhiệt của nhiệt kế trong kho lạnh phải được lắp đặt ở vị trí nào?",["Ở nơi có nhiệt độ thấp nhất trong kho.", "Ở gần cửa ra vào kho để dễ quan sát.", "Ở nơi có nhiệt độ cao nhất trong kho.", "Ở vị trí trung tâm của kho để đại diện cho nhiệt độ chung."],2,"Theo Mục 2.1.5.5.e của Thông tư 47/2009/TT-BNNPTNT, 'Bộ cảm nhiệt của nhiệt kế ở nơi có nhiệt độ cao nhất trong kho'.",1);
  add(3,"Hoạt động nào sau đây bị cấm trong kho lạnh bảo quản sản phẩm thủy sản?",["Sắp xếp sản phẩm theo từng lô riêng biệt.", "Cấp đông sản phẩm.", "Giám sát nhiệt độ tự động.", "Xả băng giàn lạnh."],1,"Theo Mục 2.1.5.5.h của Thông tư 47/2009/TT-BNNPTNT, 'Không được sử dụng kho lạnh để cấp đông sản phẩm'.",1);
  add(3,"Yêu cầu về kho chứa bao bì, vật liệu bao gói sản phẩm thủy sản là gì?",["Bao bì, vật liệu bao gói có thể để trực tiếp dưới nền kho để tiết kiệm không gian.", "Kho phải kín, khô ráo, thoáng mát và bao bì không để trực tiếp dưới nền kho.", "Kho chỉ cần khô ráo, không yêu cầu kín hoặc thoáng mát.", "Bao bì có thể để ngoài trời nếu được che chắn cẩn thận."],1,"Theo Mục 2.1.5.8.a và b của Thông tư 47/2009/TT-BNNPTNT, kho chứa bao bì, vật liệu bao gói sản phẩm thủy sản phải 'Kín, khô ráo, thoáng mát' và 'Bao bì, vật liệu bao gói sản phẩm không để trực tiếp dưới nền kho'.",1);
  add(3,"Bể chứa nước dùng cho sản xuất trong cơ sở chế biến thủy sản phải đáp ứng các yêu cầu nào sau đây?",["Bề mặt bên trong bể nhẵn, không ngấm nước và có ô cửa có nắp đậy không bị ngấm nước đủ cho người qua được để làm vệ sinh và kiểm tra.", "Chỉ cần có đủ dung tích chứa nước, không yêu cầu về vật liệu chế tạo.", "Có thể làm bằng vật liệu thấm nước để dễ thoát ẩm.", "Không cần ô cửa kiểm tra, vệ sinh để đảm bảo kín tuyệt đối."],0,"Theo Mục 2.1.6.3.b và c của Thông tư 47/2009/TT-BNNPTNT, bể chứa nước phải 'được thiết kế và chế tạo sao cho bề mặt bên trong bể nhẵn, không ngấm nước' và 'phải có ô cửa có nắp đậy không bị ngấm nước với kích thước đủ cho người qua được để vào làm vệ sinh và kiểm tra'.",2);
  add(5,"Theo Quy chuẩn kỹ thuật quốc gia QCVN 47/2009, hệ thống ống dẫn nước sạch trong khu vực sản xuất phải đáp ứng yêu cầu nào sau đây?",["Chỉ cần có màu sắc khác biệt với ống nước khác", "Phải được đánh số rõ ràng trên thực tế và trên sơ đồ để lấy mẫu kiểm soát chất lượng nước", "Phải được làm bằng nhựa PVC màu xanh", "Không cần có biện pháp chống chảy ngược"],1,"Theo mục 2.1.6.4 b của Thông tư 47/2009, các vòi và đường ống dẫn nước sạch trong khu vực sản xuất phải được đánh số rõ ràng trên thực tế và trên sơ đồ để lấy mẫu kiểm soát chất lượng nước theo kế hoạch.",1);
  add(5,"Nước đá dùng trong cơ sở chế biến thủy sản phải đáp ứng tiêu chuẩn nào sau đây?",["Chỉ cần được làm từ nước máy bình thường", "Phải được sản xuất từ nước sạch hoặc nước biển sạch, hợp vệ sinh và đáp ứng yêu cầu như nước sạch theo Mục 1.2.10", "Có thể được làm từ nước thải đã qua xử lý", "Không cần kiểm tra chất lượng định kỳ"],1,"Mục 2.1.7.1 a i‑v quy định nước đá phải sản xuất từ nước sạch hoặc nước biển sạch, hợp vệ sinh, bảo quản, vận chuyển và phải đáp ứng yêu cầu như nước sạch theo Mục 1.2.10 của Quy chuẩn.",1);
  add(5,"Về hệ thống cung cấp hơi nước tiếp xúc trực tiếp với sản phẩm, quy định nào sau đây là đúng?",["Hơi nước có thể chứa dầu nếu không ảnh hưởng tới màu sắc sản phẩm", "Hệ thống phải được thiết kế hợp lý, bọc cách nhiệt và chế tạo bằng vật liệu thích hợp, không chứa chất gây nhiễm bẩn", "Không cần bọc cách nhiệt nếu đường ống ngắn", "Có thể dùng ống nhựa PVC không chịu nhiệt"],1,"Theo mục 2.1.8.2 a‑c, hệ thống cung cấp hơi nước phải được thiết kế hợp lý, bọc cách nhiệt, chế tạo bằng vật liệu thích hợp và không gây nhiễm bẩn sản phẩm.",2);
  add(5,"Khi sử dụng không khí nén trong quá trình chế biến, điều kiện nào bắt buộc phải được tuân thủ?",["Không cần lọc không khí vì không khí nén đã sạch tự nhiên", "Phải qua phin lọc không khí ở đầu vào và phin lọc phải đặt ở nơi sạch sẽ", "Chỉ cần lọc nếu không khí có mùi", "Có thể dùng ống dẫn bằng nhựa không cần lọc"],1,"Mục 2.1.9.2 quy định nếu là không khí nén, phải qua phin lọc không khí ở đầu vào và phin lọc được đặt ở nơi sạch sẽ.",2);
  add(5,"Về việc thu gom và vận chuyển chất thải rắn trong cơ sở chế biến, tần suất tối thiểu là bao nhiêu?",["Mỗi 30 phút một lần", "Mỗi 2 giờ một lần trong thời gian hoạt động", "Mỗi 6 giờ một lần", "Chỉ khi bể chứa đầy mới vận chuyển"],1,"Mục 2.1.10.2 quy định chất thải rắn phải được thu gom và vận chuyển ra khỏi khu vực sản xuất ít nhất 2 giờ một lần trong thời gian hoạt động.",1);
  add(5,"Bể nước sát trùng ủng (foot bath) phải đáp ứng các yêu cầu sau, ngoại trừ:",["Độ ngập nước không dưới 0,15 m", "Hàm lượng chlorin dư trong nước đạt 100‑200 ppm", "Có lỗ thoát để thay nước định kỳ", "Cho phép nước rửa tay chảy vào bể để tăng nồng độ chlorine"],3,"Mục 2.1.11.2 b i‑iv nêu rõ các yêu cầu của bể nước sát trùng ủng, trong đó có điều kiện không để nước rửa tay chảy vào bể (điều iv). Vì vậy, lựa chọn D là sai.",2);
  add(5,"Trong phòng thay bảo hộ lao động, yêu cầu nào sau đây là không đúng?",["Phòng phải cách biệt hoàn toàn với phòng chế biến và không mở cửa thông trực tiếp", "Phòng phải được bố trí chung cho công nhân nam và nữ", "Phòng phải có đủ chỗ để công nhân bảo quản tư trang, giày dép", "Phòng phải có khu vực riêng để để quần áo bảo hộ, không trộn với quần áo thường"],1,"Theo mục 2.1.11.3 b, phòng thay bảo hộ lao động phải được bố trí riêng cho công nhân nam và nữ, không được chung một không gian. Vì vậy, đáp án B là không đúng.",2);
  add(5,"Đối với phương tiện rửa và khử trùng tay, vị trí bố trí sau đây là không bắt buộc theo quy chuẩn:",["Lối vào khu vực sản xuất", "Phòng sản xuất", "Khu vực nhà vệ sinh", "Khu vực lưu trữ nguyên liệu thô"],3,"Mục 2.1.11.1 a chỉ liệt kê ba vị trí bắt buộc: lối vào khu vực sản xuất, phòng sản xuất và khu vực nhà vệ sinh. Khu vực lưu trữ nguyên liệu thô không nằm trong danh sách này.",1);
  add(5,"Nếu một cơ sở chế biến thủy sản muốn sử dụng vật liệu nhựa cho thiết bị xay, nghiền nước đá, quy định nào sau đây sẽ vi phạm QCVN 47/2009?",["Vật liệu phải không gỉ, không thấm nước và không gây độc cho sản phẩm", "Vật liệu có thể chứa chất phụ gia để tăng độ bền", "Vật liệu phải dễ làm vệ sinh", "Vật liệu phải bền, không gỉ"],1,"Mục 2.1.7.2 a‑b yêu cầu thiết bị xay, nghiền nước đá phải có kết cấu thích hợp, dễ làm vệ sinh, chế tạo bằng vật liệu bền, không gỉ, không thấm nước và không gây độc cho sản phẩm. Việc dùng nhựa có chất phụ gia không được quy định rõ ràng và có thể gây nhiễm, do đó là vi phạm.",3);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT), khu vực nhà vệ sinh phải được bố trí như thế nào?",["Bố trí ở gần khu chế biến và có cửa mở trực tiếp vào khu chế biến.", "Bố trí ở xa khu chế biến để đảm bảo vệ sinh.", "Bố trí ở gần nhưng cách ly hoàn toàn với khu chế biến và không mở cửa trực tiếp vào khu chế biến.", "Bố trí tùy theo điều kiện thực tế của cơ sở, miễn là đảm bảo vệ sinh."],2,"Theo Mục 2.1.11.4.a.i của Thông tư 47/2009/TT-BNNPTNT, khu vực nhà vệ sinh phải 'Bố trí ở gần nhưng cách ly hoàn toàn với khu chế biến và không mở cửa trực tiếp vào khu chế biến'.",1);
  add(3,"Một cơ sở chế biến thủy sản có 35 công nhân nữ làm việc trong một ca sản xuất. Theo Thông tư 47/2009/TT-BNNPTNT, cơ sở này cần có ít nhất bao nhiêu nhà vệ sinh cho nữ?",["02 nhà vệ sinh.", "03 nhà vệ sinh.", "04 nhà vệ sinh.", "05 nhà vệ sinh."],1,"Theo Mục 2.1.11.4.b của Thông tư 47/2009/TT-BNNPTNT, với số lượng người từ 25 – 49, số nhà vệ sinh ít nhất phải có là 03.",2);
  add(3,"Đối với chất tẩy rửa và khử trùng được sử dụng trong cơ sở sản xuất thủy sản, yêu cầu về bảo quản và ghi nhãn là gì?",["Được phép sử dụng, đựng trong thùng chứa kín, bảo quản riêng biệt trong kho thông thoáng, có khóa và ghi rõ tên chất bằng tiếng Việt.", "Được phép sử dụng, đựng trong thùng chứa kín, có thể bảo quản chung với sản phẩm nếu không gây nhiễm bẩn.", "Không cần khóa kho bảo quản nếu có người trông coi, chỉ cần ghi tên chất bằng tiếng Việt.", "Có thể đựng trong thùng hở nếu được sử dụng thường xuyên, chỉ cần ghi rõ tên chất."],0,"Theo Mục 2.1.11.5.đ của Thông tư 47/2009/TT-BNNPTNT, chất tẩy rửa và khử trùng phải 'được phép sử dụng, được đựng trong thùng chứa kín, bảo quản riêng biệt trong kho thông thoáng, có khóa. Trên các thùng chứa phải ghi rõ bằng tiếng Việt tên chất tẩy rửa và khử trùng'.",1);
  add(3,"Nguyên tắc quan trọng nào cần được tuân thủ để tránh nhiễm chéo trong các công đoạn sơ chế/chế biến thủy sản theo Thông tư 47/2009/TT-BNNPTNT?",["Công đoạn trước phải sạch hơn công đoạn sau.", "Hạn chế tối đa sự suy giảm chất lượng sản phẩm.", "Công đoạn sau phải sạch hơn công đoạn trước.", "Sản phẩm phải được xử lý và bảo quản trong điều kiện tránh được nhiễm bẩn."],2,"Theo Mục 2.1.12.1.b của Thông tư 47/2009/TT-BNNPTNT, cần 'Tránh nhiễm chéo trực tiếp hoặc gián tiếp ở các công đoạn từ nguyên liệu đến khi xuất xưởng sản phẩm. Công đoạn sau phải sạch hơn công đoạn trước'.",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, quy định nào sau đây là đúng về việc đặt sản phẩm trong khu vực sơ chế/chế biến thủy sản?",["Sản phẩm có thể tiếp xúc trực tiếp với sàn nhà nếu sàn được vệ sinh thường xuyên.", "Khay, hộp, chậu đựng sản phẩm không được đặt trực tiếp trên sàn nhà.", "Chỉ những sản phẩm đã đóng gói mới không được đặt trực tiếp trên sàn nhà.", "Việc đặt sản phẩm trên sàn nhà được chấp nhận trong thời gian ngắn để tiện di chuyển."],1,"Theo Mục 2.1.12.1.đ của Thông tư 47/2009/TT-BNNPTNT, 'Không để sản phẩm tiếp xúc trực tiếp với sàn nhà. Khay, hộp, chậu đựng sản phẩm không được đặt trực tiếp trên sàn nhà'.",1);
  add(3,"Khi khách vào khu vực chế biến thủy sản theo quy định của Thông tư 47/2009/TT-BNNPTNT, họ phải tuân thủ yêu cầu nào?",["Mặc áo bảo hộ và đội mũ bảo hộ.", "Mặc áo bảo hộ, đội mũ bảo hộ, đeo khẩu trang (nếu cần) và đi ủng.", "Chỉ cần mặc áo bảo hộ và đi ủng.", "Tùy thuộc vào quy định riêng của từng cơ sở."],1,"Theo Mục 2.1.12.1.h của Thông tư 47/2009/TT-BNNPTNT, 'Khách vào khu vực chế biến phải mặc áo bảo hộ, đội mũ bảo hộ, đeo khẩu trang (nếu cần) và đi ủng'.",1);
  add(3,"Để kiểm soát động vật gây hại trong cơ sở sản xuất thủy sản, chất độc diệt côn trùng và loài gặm nhấm phải được bảo quản như thế nào?",["Bảo quản trong kho riêng có khóa, không cần tủ riêng.", "Bảo quản nghiêm ngặt trong tủ hoặc trong kho riêng có khóa và tuyệt đối không để lây nhiễm vào sản phẩm.", "Có thể để ở khu vực sản xuất nếu được giám sát chặt chẽ.", "Chỉ cần ghi nhãn rõ ràng để tránh nhầm lẫn."],1,"Theo Mục 2.1.12.3.b của Thông tư 47/2009/TT-BNNPTNT, 'Chất độc để diệt côn trùng, các loài gặm nhấm, phải được bảo quản nghiêm ngặt trong tủ hoặc trong kho riêng có khoá. Tuyệt đối không để lây nhiễm chất độc vào sản phẩm'.",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, bề mặt của thiết bị, máy móc tiếp xúc trực tiếp với sản phẩm thủy sản phải được vệ sinh và khử trùng với tần suất tối thiểu như thế nào?",["Sau mỗi ca sản xuất.", "Hàng ngày trước khi bắt đầu sản xuất.", "Sau mỗi lần nghỉ giữa ca và sau mỗi ca sản xuất.", "Hàng tuần hoặc khi có yêu cầu."],2,"Theo Mục 2.1.12.4.b của Thông tư 47/2009/TT-BNNPTNT, 'Bề mặt của thiết bị, máy móc tiếp xúc trực tiếp với sản phẩm phải được vệ sinh sạch sẽ và khử trùng sau mỗi lần nghỉ giữa ca và sau mỗi ca sản xuất'.",1);
  add(3,"Một nhà máy chế biến thủy sản có tổng cộng 150 công nhân (70 nam, 80 nữ) làm việc trong một ca sản xuất. Theo Thông tư 47/2009/TT-BNNPTNT, nhà máy này cần có tối thiểu bao nhiêu nhà vệ sinh cho từng giới tính?",["05 nhà vệ sinh cho nam và 05 nhà vệ sinh cho nữ.", "05 nhà vệ sinh cho nam và 06 nhà vệ sinh cho nữ.", "06 nhà vệ sinh cho nam và 06 nhà vệ sinh cho nữ.", "05 nhà vệ sinh cho nam và 07 nhà vệ sinh cho nữ."],0,"Theo Mục 2.1.11.4.b của Thông tư 47/2009/TT-BNNPTNT:\n- Đối với 70 công nhân nam: Số người từ 50 – 100 cần 05 nhà vệ sinh. Do đó, 70 nam cần 05 nhà vệ sinh.\n- Đối với 80 công nhân nữ: Số người từ 50 – 100 cần 05 nhà vệ sinh. Do đó, 80 nữ cần 05 nhà vệ sinh.\nVậy, nhà máy cần tối thiểu 05 nhà vệ sinh cho nam và 05 nhà vệ sinh cho nữ.",3);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, hành động nào sau đây KHÔNG được phép thực hiện trong khu vực sản xuất thủy sản?",["Duy trì sản phẩm ở nhiệt độ phù hợp.", "Để sản phẩm tiếp xúc trực tiếp với sàn nhà.", "Hạn chế tối đa sự suy giảm chất lượng sản phẩm.", "Ngăn chặn vi sinh vật phát triển."],1,"Theo Mục 2.1.12.1.đ của Thông tư 47/2009/TT-BNNPTNT, 'Không để sản phẩm tiếp xúc trực tiếp với sàn nhà.' Các phương án A, C, D là các yêu cầu chung cần đảm bảo trong sản xuất.",2);
  add(3,"Về công tác bảo trì nhà xưởng, thiết bị, máy móc, dụng cụ trong cơ sở sản xuất thủy sản, Thông tư 47/2009/TT-BNNPTNT quy định như thế nào?",["Cơ sở phải tiến hành kiểm tra hàng tháng và bảo trì khi cần thiết, đảm bảo không ảnh hưởng đến ATVS thực phẩm.", "Cơ sở phải hàng ngày tiến hành kiểm tra tình trạng và bảo trì, sửa chữa khi chúng không đáp ứng yêu cầu, đồng thời đảm bảo việc sửa chữa không ảnh hưởng đến ATVS thực phẩm.", "Việc kiểm tra và bảo trì có thể được thực hiện định kỳ theo kế hoạch của cơ sở, miễn là không làm gián đoạn sản xuất.", "Chỉ cần bảo trì khi thiết bị, máy móc bị hỏng hoàn toàn để tiết kiệm chi phí."],1,"Theo Mục 2.1.12.2.a và b của Thông tư 47/2009/TT-BNNPTNT, 'Cơ sở hàng ngày phải tiến hành kiểm tra tình trạng nhà xưởng, thiết bị, máy móc, dụng cụ và bảo trì, sửa chữa khi chúng không đáp ứng được các yêu cầu quy định trong Quy chuẩn này. Việc sửa chữa, bảo trì phải đảm bảo không ảnh hưởng đến ATVS thực phẩm'.",2);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, việc sử dụng vòi nước áp lực cao để vệ sinh nhà xưởng và thiết bị, dụng cụ chế biến được quy định như thế nào?",["Được phép sử dụng bất cứ lúc nào để đảm bảo vệ sinh tối đa.", "Không được dùng khi trong khu vực chế biến có sản phẩm chưa được đóng gói.", "Chỉ được dùng khi không có công nhân trong khu vực chế biến.", "Được phép dùng nếu sản phẩm đã được che chắn cẩn thận."],1,"Theo Khoản 2.1.12.c của Thông tư 47/2009/TT-BNNPTNT, 'Không dùng vòi nước áp lực cao để vệ sinh nhà xưởng và thiết bị, dụng cụ chế biến khi trong khu vực chế biến có sản phẩm chưa được đóng gói.'",1);
  add(3,"Quy định về chất khử trùng còn sót lại trên bề mặt có thể tiếp xúc với sản phẩm trước khi bắt đầu sản xuất là gì?",["Có thể để lại một lượng nhỏ nếu không ảnh hưởng đến chất lượng sản phẩm.", "Phải được rửa sạch hoàn toàn.", "Chỉ cần lau khô là đủ.", "Không cần rửa sạch nếu đã được Bộ Y tế cho phép sử dụng."],1,"Theo Khoản 2.1.12.d của Thông tư 47/2009/TT-BNNPTNT, 'Chất khử trùng còn sót lại trên bề mặt có thể tiếp xúc với sản phẩm phải được rửa sạch trước khi bắt đầu sản xuất.'",1);
  add(3,"Khi bảo quản phụ gia và chất hỗ trợ chế biến, cơ sở sản xuất thủy sản phải tuân thủ quy định nào sau đây?",["Có thể bảo quản chung với hóa chất tẩy rửa/khử trùng nếu được đóng gói kín.", "Phải bố trí khu vực thích hợp để bảo quản riêng, không được bảo quản chung với hóa chất tẩy rửa/khử trùng, hóa chất độc hại.", "Có thể bảo quản ở bất kỳ khu vực nào miễn là đảm bảo sạch sẽ.", "Không cần khu vực riêng nếu số lượng ít."],1,"Theo Khoản 2.1.13.2 của Thông tư 47/2009/TT-BNNPTNT, 'Phải bố trí khu vực thích hợp để bảo quản phụ gia, chất hỗ trợ chế biến; không được bảo quản chung với hóa chất tẩy rửa/khử trùng, hóa chất độc hại.'",1);
  add(3,"Công nhân mắc bệnh nào sau đây không được làm việc trong những công đoạn sản xuất có thể trực tiếp hoặc gián tiếp làm nhiễm bẩn sản phẩm?",["Bệnh truyền nhiễm, bỏng, vết thương bị nhiễm trùng, bệnh ngoài da, tiêu chảy.", "Cảm cúm thông thường không sốt.", "Đau đầu nhẹ không ảnh hưởng đến năng suất.", "Viêm họng không có triệu chứng lây nhiễm."],0,"Theo Khoản 2.1.14.1.a của Thông tư 47/2009/TT-BNNPTNT, 'Công nhân có bệnh truyền nhiễm hoặc mắc bệnh có thể lây nhiễm cho sản phẩm như: bị bỏng, có vết thương bị nhiễm trùng, bị bệnh ngoài da, tiêu chảy... không được làm việc trong những công đoạn sản xuất có thể trực tiếp hoặc gián tiếp làm nhiễm bẩn sản phẩm.'",1);
  add(3,"Theo quy định, công nhân sản xuất sản phẩm thủy sản phải được khám sức khỏe định kỳ với tần suất tối thiểu là bao nhiêu?",["Hai năm một lần.", "Mỗi năm tối thiểu một lần.", "Ba năm một lần.", "Chỉ khi có yêu cầu từ cơ quan kiểm tra."],1,"Theo Khoản 2.1.14.1.b của Thông tư 47/2009/TT-BNNPTNT, 'Công nhân sơ sản xuất sản phẩm phải được khám sức khoẻ khi tuyển dụng và định kỳ kiểm tra sức khoẻ mỗi năm tối thiểu một lần, đảm bảo đủ tiêu chuẩn làm việc theo qui định của Bộ Y tế.'",1);
  add(3,"Quy định nào sau đây là ĐÚNG về việc sử dụng và quản lý quần áo bảo hộ lao động cho công nhân sản xuất thủy sản?",["Công nhân tự giặt quần áo bảo hộ tại nhà sau mỗi ca sản xuất.", "Quần áo bảo hộ phải được cơ sở chế biến tập trung giặt sạch sau mỗi ca sản xuất và công nhân không được mặc ra ngoài khu vực sản xuất.", "Công nhân có thể mặc quần áo bảo hộ ra ngoài khu vực sản xuất nếu không tiếp xúc trực tiếp với sản phẩm.", "Quần áo bảo hộ chỉ cần giặt khi bị bẩn rõ rệt."],1,"Theo Khoản 2.1.14.2.b của Thông tư 47/2009/TT-BNNPTNT, 'Quần áo bảo hộ phải được cơ sở chế biến tập trung giặt sạch sau mỗi ca sản xuất. Công nhân không được mặc quần áo bảo hộ ra ngoài khu vực sản xuất.'",2);
  add(3,"Khi cán bộ quản lý hoặc khách tham quan vào phân xưởng sản xuất thủy sản, họ phải tuân thủ quy định nào về trang phục và vật dụng cá nhân?",["Được phép mang đồ trang sức và đồ vật cá nhân miễn là không làm rơi.", "Không được mang đồ trang sức, đồ vật dễ rơi, hoặc đồ vật gây nguy cơ mất vệ sinh và phải mặc bảo hộ lao động.", "Chỉ cần mặc áo khoác bảo hộ bên ngoài trang phục cá nhân.", "Không cần mặc bảo hộ nếu chỉ tham quan trong thời gian ngắn."],1,"Theo Khoản 2.1.14.2.đ của Thông tư 47/2009/TT-BNNPTNT, 'Cán bộ quản lý, khách tham quan không được mang đồ trang sức, đồ vật dễ rơi, hoặc đồ vật gây nguy cơ mất vệ sinh và phải mặc bảo hộ lao động khi vào phân xưởng sản xuất.'",1);
  add(3,"Công nhân tiếp xúc trực tiếp với sản phẩm thủy sản phải rửa tay vào những thời điểm nào sau đây?",["Chỉ trước khi đi vào khu vực chế biến.", "Sau khi đi vệ sinh và sau khi tiếp xúc với bất kì tác nhân có khả năng gây nhiễm bẩn nào.", "Trước khi đi vào khu vực chế biến, sau khi đi vệ sinh và sau khi tiếp xúc với bất kì tác nhân có khả năng gây nhiễm bẩn nào.", "Chỉ khi cảm thấy tay bẩn."],2,"Theo Khoản 2.1.14.3.a của Thông tư 47/2009/TT-BNNPTNT, công nhân phải rửa tay: 'i. Trước khi đi vào khu vực chế biến, ii. Sau khi đi vệ sinh, iii. Sau khi tiếp xúc với bất kì tác nhân có khả năng gây nhiễm bẩn nào.'",1);
  add(3,"Theo quy định về xác định lô hàng, mã số và hồ sơ của mỗi lô nguyên liệu nhập vào phải có thông tin về những nội dung nào?",["Chỉ cần tên loài thủy sản và khối lượng.", "Cơ sở cung cấp nguyên liệu, ngày và giờ nhận nguyên liệu, tên loài thủy sản, khối lượng, các thông số về chất lượng và an toàn (bao gồm cả nhiệt độ bảo quản nguyên liệu).", "Chỉ cần cơ sở cung cấp nguyên liệu và ngày nhận.", "Tên loài thủy sản, khối lượng và giá thành."],1,"Theo Khoản 2.2.1 của Thông tư 47/2009/TT-BNNPTNT, mã số và hồ sơ của mỗi lô phải có thông tin về: '2.2.1.1. Cơ sở cung cấp nguyên liệu, 2.2.1.2. Ngày và giờ nhận nguyên liệu, 2.2.1.3. Tên loài thuỷ sản, 2.2.1.4. Khối lượng, 2.2.1.5. Các thông số về chất lượng và an toàn (bao gồm cả nhiệt độ bảo quản nguyên liệu).'",2);
  add(3,"Mục đích của việc ghi mã số lô hàng trên bao bì thành phẩm là gì?",["Để phân loại sản phẩm theo màu sắc.", "Để xác định giá bán của sản phẩm.", "Để có thể truy xuất được lô hàng từ thành phẩm về đến nguyên liệu.", "Để quảng bá thương hiệu của cơ sở sản xuất."],2,"Theo Khoản 2.2.2 của Thông tư 47/2009/TT-BNNPTNT, 'Mã số phải được ghi trên bao bì thành phẩm để có thể truy xuất được lô hàng từ thành phẩm về đến nguyên liệu.'",2);
  add(3,"Một phương tiện vận chuyển sản phẩm thủy sản đã được sử dụng để vận chuyển sản phẩm khác có khả năng gây nhiễm bẩn. Theo quy định, cơ sở phải làm gì trước khi sử dụng lại phương tiện này để vận chuyển sản phẩm thủy sản?",["Có thể sử dụng lại ngay nếu sản phẩm khác đã được dỡ bỏ.", "Phải được vệ sinh và khử trùng cẩn thận.", "Chỉ cần lau sạch bề mặt tiếp xúc trực tiếp với sản phẩm.", "Không được phép sử dụng lại cho sản phẩm thủy sản."],1,"Theo Khoản 2.3.1.2 của Thông tư 47/2009/TT-BNNPTNT, 'Nếu đã sử dụng để vận chuyển sản phẩm khác, phương tiện phải được vệ sinh và khử trùng cẩn thận trước khi sử dụng lại để vận chuyển sản phẩm thuỷ sản.'",2);
  add(3,"Quy định về việc làm vệ sinh và khử trùng phương tiện, dụng cụ vận chuyển sản phẩm thủy sản là gì?",["Chỉ cần làm vệ sinh và khử trùng sau mỗi chuyến vận chuyển.", "Chỉ cần làm vệ sinh và khử trùng trước mỗi chuyến vận chuyển.", "Phải được làm vệ sinh và khử trùng trước và sau mỗi chuyến vận chuyển.", "Không cần làm vệ sinh và khử trùng nếu sản phẩm đã được đóng gói kín."],2,"Theo Khoản 2.3.1.4 của Thông tư 47/2009/TT-BNNPTNT, 'Phương tiện, dụng cụ vận chuyển sản phẩm thuỷ sản phải được làm vệ sinh và khử trùng trước và sau mỗi chuyến vận chuyển.'",1);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT), phương tiện vận chuyển (xe chuyển hoặc container) sản phẩm thực phẩm phải đáp ứng yêu cầu nào về nhiệt độ?",["Phải có khả năng bảo quản thực phẩm ở nhiệt độ thích hợp và cho phép theo dõi được nhiệt độ này.", "Chỉ cần có khả năng bảo quản thực phẩm ở nhiệt độ thích hợp, không cần thiết bị theo dõi.", "Chỉ cần có thiết bị theo dõi nhiệt độ, không bắt buộc bảo quản ở nhiệt độ thích hợp.", "Không có quy định cụ thể về nhiệt độ, chỉ cần đảm bảo an toàn."],0,"Khoản 2.3.2 của Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT) quy định rõ: \"xe chuyển hoặc container được sử dụng để vận chuyển sản phẩm thực phẩm phải có khả năng bảo quản thực phẩm ở nhiệt độ thích hợp và cho phép theo dõi được nhiệt độ này.\"",1);
  add(3,"Ai là người có trách nhiệm đảm bảo việc vận chuyển và bảo quản sản phẩm thủy sản đang được lưu trữ phải phù hợp với các quy định trong Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Người vận chuyển và thủ kho.", "Chỉ người vận chuyển.", "Chỉ thủ kho.", "Ban giám đốc cơ sở sản xuất."],0,"Khoản 2.3.3 của Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT) nêu rõ: \"Người vận chuyển và thủ kho có trách nhiệm đảm bảo việc vận chuyển và bảo quản sản phẩm đang được lưu trữ, phải phù hợp với những quy định trong Quy chuẩn này.\"",1);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, yêu cầu chung về quản lý chất lượng và ATVS thực phẩm đối với cơ sở là gì?",["Cơ sở phải xây dựng và áp dụng hệ thống quản lý chất lượng theo đúng quy định.", "Cơ sở chỉ cần tuân thủ các quy định về vệ sinh cá nhân.", "Cơ sở chỉ cần đảm bảo sản phẩm cuối cùng đạt chất lượng.", "Cơ sở được khuyến khích áp dụng hệ thống quản lý chất lượng, không bắt buộc."],0,"Khoản 2.4.1 của Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT) quy định: \"Cơ sở phải xây dựng và áp dụng hệ thống quản lý chất lượng theo đúng quy định nêu tại\" (ý là theo đúng quy định của Quy chuẩn hoặc các văn bản pháp luật liên quan).",1);
  add(3,"Một cơ sở sản xuất thủy sản đang vận chuyển lô hàng cá tra đông lạnh bằng container. Trong quá trình vận chuyển, hệ thống theo dõi nhiệt độ của container bị hỏng và không thể ghi nhận nhiệt độ trong 2 giờ cuối cùng của hành trình. Theo Quy chuẩn 47/2009/TT-BNNPTNT, tình huống này vi phạm yêu cầu nào?",["Yêu cầu về khả năng bảo quản nhiệt độ thích hợp của phương tiện vận chuyển.", "Yêu cầu về khả năng cho phép theo dõi nhiệt độ của phương tiện vận chuyển.", "Trách nhiệm của người vận chuyển và thủ kho trong việc bảo quản sản phẩm.", "Cả A và B."],1,"Khoản 2.3.2 của Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT) quy định phương tiện vận chuyển phải \"cho phép theo dõi được nhiệt độ này\". Việc hệ thống theo dõi nhiệt độ bị hỏng và không ghi nhận được nhiệt độ trong quá trình vận chuyển là vi phạm trực tiếp yêu cầu về khả năng theo dõi nhiệt độ.",2);
  add(5,"Theo QCVN 02-02:2009/BNNPTNT, cơ sở sản xuất thủy sản phải có đủ số nhân viên làm nhiệm vụ kiểm soát chất lượng trong quá trình sản xuất. Yêu cầu này được quy định tại mục nào?",["2.4.2.2", "2.4.2.1", "2.5.1", "2.6.1.1"],1,"Mục 2.4.2.1 quy định \"Cơ sở phải có đủ số nhân viên làm nhiệm vụ kiểm soát chất lượng trong quá trình sản xuất\".",1);
  add(5,"Nhân viên phụ trách và các nhân viên kiểm soát chất lượng phải đáp ứng yêu cầu nào sau đây?",["Có bằng cấp đại học bất kỳ", "Có kinh nghiệm và hiểu biết về công nghệ chế biến, kiểm soát chất lượng và đánh giá chất lượng sản phẩm thủy sản", "Chỉ cần tham gia khóa đào tạo nội bộ", "Không có yêu cầu đặc biệt"],1,"Mục 2.4.2.2 nêu rõ yêu cầu \"Người phụ trách và các nhân viên kiểm soát chất lượng phải có kinh nghiệm và hiểu biết về công nghệ chế biến, kiểm soát chất lượng và đánh giá chất lượng sản phẩm thuỷ sản\".",1);
  add(5,"Để đáp ứng yêu cầu về phòng kiểm nghiệm, cơ sở có thể thực hiện cách nào sau đây?",["Sử dụng phòng chung với các ngành khác mà không cần đánh giá", "Có phòng kiểm nghiệm riêng hoặc ký hợp đồng với danh mục các phòng kiểm nghiệm bên ngoài được cơ quan có thẩm quyền chỉ định", "Không cần phòng kiểm nghiệm nếu có nhân viên QC", "Chỉ cần một góc nhỏ trong nhà máy làm phòng kiểm nghiệm"],1,"Mục 2.4.3 quy định \"Cơ sở phải có phòng kiểm nghiệm riêng, hoặc phải ký hợp đồng/có Danh mục các phòng kiểm nghiệm bên ngoài được Cơ quan có thẩm quyền đánh giá, chỉ định là Phòng kiểm nghiệm đủ năng lực\".",2);
  add(5,"Trước khi đóng gói, sản phẩm thủy sản tươi phải được làm lạnh xuống nhiệt độ nào?",["+6 °C hoặc cao hơn", "+4 °C hoặc thấp hơn, nhưng không dưới -1 °C", "-5 °C", "0 °C đến +10 °C"],1,"Mục 2.5.1 quy định \"Trước khi đóng gói, sản phẩm đã qua xử lý phải được làm lạnh xuống nhiệt độ +4 °C hoặc thấp hơn, nhưng không dưới -1 °C\".",1);
  add(5,"Về việc sử dụng nước đá bảo quản sản phẩm thủy sản tươi, yêu cầu nào sau đây là đúng?",["Nước đá chỉ cần có khi thời tiết nóng", "Nước đá phải đủ để duy trì nhiệt độ yêu cầu trong suốt quá trình vận chuyển", "Chỉ cần một lớp băng mỏng trên bề mặt sản phẩm", "Nước đá phải được đun sôi trước khi dùng"],1,"Mục 2.5.2 nêu rõ \"Nước đá dùng để bảo quản, đóng gói sản phẩm thuỷ sản tươi phải đủ để duy trì nhiệt độ theo yêu cầu khi vận chuyển sản phẩm\".",2);
  add(5,"Khi sản phẩm thủy sản tươi được chuyển đến cơ sở chế biến hoặc tiêu thụ mà chưa được chế biến, nhiệt độ bảo quản phải nằm trong khoảng nào?",["-10 °C đến -5 °C", "-1 °C đến +4 °C", "+5 °C đến +10 °C", "0 °C đến +2 °C"],1,"Mục 2.5.3 quy định \"Sản phẩm thuỷ sản khi được chuyển đến các cơ sở chế biến, tiêu thụ, nếu chưa chế biến, hoặc tiêu thụ ngay, phải được bảo quản ở nhiệt độ từ -1 °C đến +4 °C\".",1);
  add(5,"Quá trình rã đông sản phẩm thủy sản phải kết thúc khi nhiệt độ tâm sản phẩm đạt bao nhiêu?",["0 °C", "-1 °C", "+2 °C", "-5 °C"],1,"Mục 2.6.1.2 quy định \"Quá trình rã đông phải kết thúc khi nhiệt độ tâm sản phẩm đạt -1 °C\".",2);
  add(5,"Trong các tác nhân lạnh được phép sử dụng cho quá trình cấp đông, tác nhân nào không được liệt kê trong QCVN?",["Không khí", "Nitơ lỏng", "Không khí, nitơ lỏng, đioxyt cacbon rắn", "Nitơ lỏng, oxi lỏng"],2,"Mục 2.6.2.4 cho phép sử dụng \"không khí, nitơ lỏng, đioxyt cacbon rắn\" làm tác nhân lạnh; oxi lỏng không nằm trong danh sách.",2);
  add(5,"Nước dùng để mạ băng cho thủy sản đông lạnh phải đáp ứng yêu cầu nào?",["Nước máy bình thường, nhiệt độ bất kỳ", "Nước sạch và được làm lạnh ở nhiệt độ dưới +4 °C", "Nước muối để tăng độ bám dính", "Nước nóng để tan băng nhanh"],1,"Mục 2.6.3.2 quy định \"Nước để mạ băng phải là nước sạch và được làm lạnh ở nhiệt độ dưới +4 °C\".",2);
  add(5,"Khi thực hiện xử lý nhiệt cho sản phẩm thủy sản, cơ sở phải thực hiện các biện pháp nào sau đây?",["Chỉ kiểm tra nhiệt độ cuối cùng của sản phẩm", "Kiểm tra thường xuyên các thông số chính như nhiệt độ và thời gian, đồng thời thực nghiệm với từng loại sản phẩm", "Không cần kiểm tra nếu dùng thiết bị tự động", "Kiểm tra chỉ thời gian, không cần quan tâm đến nhiệt độ"],2,"Mục 2.7.2 và 2.7.3 yêu cầu \"Quá trình xử lý nhiệt phải đảm bảo nâng nhiệt độ sản phẩm đến nhiệt độ quy định và trong khoảng thời gian đã xác định. Phải thường xuyên kiểm tra các thông số chính có liên quan như nhiệt độ, thời gian\"; đồng thời phải thực nghiệm với từng loại sản phẩm (mục 2.7.1).",3);
  add(3,"Cơ quan nào chịu trách nhiệm quy định trình tự, thủ tục, phương thức đánh giá, chứng nhận sự phù hợp của các cơ sở chế biến thủy sản đối với Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Bộ Y tế", "Bộ Công Thương", "Bộ Nông nghiệp và Phát triển Nông thôn", "Sở Nông nghiệp và Phát triển Nông thôn các tỉnh"],2,"Theo Khoản 3.2 của Thông tư 47/2009/TT-BNNPTNT, trình tự, thủ tục, phương thức đánh giá, chứng nhận sự phù hợp của các cơ sở chế biến thủy sản đối với Quy chuẩn này được thực hiện theo quy định cụ thể của Bộ Nông nghiệp và Phát triển Nông thôn.",1);
  add(3,"Các cơ sở sản xuất, kinh doanh thủy sản nào phải đảm bảo các yêu cầu trong Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT)?",["Chỉ các cơ sở sản xuất thủy sản xuất khẩu.", "Chỉ các cơ sở sản xuất thủy sản tiêu thụ nội địa.", "Các cơ sở sản xuất, kinh doanh thủy sản dùng làm thực phẩm xuất khẩu hoặc tiêu thụ nội địa.", "Các cơ sở sản xuất, kinh doanh thủy sản có quy mô lớn."],2,"Theo Khoản 3.3 của Thông tư 47/2009/TT-BNNPTNT, các cơ sở sản xuất, kinh doanh thủy sản dùng làm thực phẩm xuất khẩu hoặc tiêu thụ nội địa phải đảm bảo các yêu cầu trong quy chuẩn này.",1);
  add(3,"Ngoài việc đáp ứng các quy định trong Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT), các cơ sở sản xuất, kinh doanh thủy sản cụ thể còn cần phải đáp ứng yêu cầu nào khác?",["Chỉ cần đáp ứng các quy định của địa phương.", "Đáp ứng các quy định trong quy chuẩn riêng cho từng loại hình sản xuất, kinh doanh thủy sản.", "Chỉ cần đáp ứng các tiêu chuẩn quốc tế nếu xuất khẩu.", "Không cần đáp ứng thêm bất kỳ quy định nào khác."],1,"Theo Khoản 3.4 của Thông tư 47/2009/TT-BNNPTNT, các cơ sở sản xuất, kinh doanh thủy sản cụ thể ngoài việc đáp ứng các quy định tương ứng trong quy chuẩn này cần phải đáp ứng các quy định trong quy chuẩn riêng cho từng loại hình sản xuất, kinh doanh thủy sản.",2);
  add(3,"Cơ quan nào chịu trách nhiệm thanh tra việc thực hiện Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT) và xử lý các vi phạm?",["Cục An toàn thực phẩm (Bộ Y tế)", "Thanh tra Bộ Công Thương", "Thanh tra chuyên ngành Bộ Nông nghiệp và Phát triển Nông thôn", "Ủy ban nhân dân các cấp"],2,"Theo Khoản 3.5 của Thông tư 47/2009/TT-BNNPTNT, Thanh tra chuyên ngành Bộ Nông nghiệp và Phát triển Nông thôn chịu trách nhiệm thanh tra việc thực hiện Quy chuẩn này và xử lý các vi phạm theo quy định.",1);
  add(5,"Quy chuẩn QCVN 02-02:2009/BNNPTNT áp dụng cho đối tượng nào?",["Các cơ sở sản xuất, kinh doanh thủy sản dùng làm thực phẩm trên toàn quốc", "Chỉ các doanh nghiệp xuất khẩu thủy sản", "Các nhà máy chế biến thực phẩm không thuộc ngành thủy sản", "Các cơ sở nuôi trồng thủy sản không chế biến"],0,"Theo mục 1.2 của Quy chuẩn, quy chuẩn áp dụng cho các cơ sở sản xuất kinh doanh thủy sản dùng làm thực phẩm thuộc phạm vi quản lý của Bộ Nông nghiệp và Phát triển nông thôn trên toàn quốc.",1);
  add(5,"Trong QCVN 02-02, \"Yêu cầu tiên quyết đối với HACCP\" (Prerequisites for HACCP) bao gồm:",["Chỉ có quy trình kiểm soát điểm tới hạn (CCP)", "Các yêu cầu về cơ sở vật chất, quy phạm sản xuất và quy phạm vệ sinh", "Chỉ các biện pháp phòng ngừa mối nguy sinh học", "Chỉ việc đào tạo nhân viên về HACCP"],1,"Mục 1.3.2 định nghĩa Yêu cầu tiên quyết đối với HACCP là các yêu cầu về cơ sở vật chất, quy phạm sản xuất (GMP) và quy phạm vệ sinh (SSOP/GHP) cần thiết để tạo điều kiện cho chương trình HACCP hoạt động hiệu quả.",2);
  add(5,"Khái niệm \"Good Manufacturing Practice (GMP)\" trong quy chuẩn được hiểu là:",["Quy trình làm sạch thiết bị sau mỗi ca sản xuất", "Những biện pháp, thao tác thực hành nhằm kiểm soát mọi yếu tố ảnh hưởng tới chất lượng sản phẩm", "Hệ thống quản lý tài chính của doanh nghiệp", "Phương pháp phân tích mối nguy trong chuỗi cung ứng"],1,"Theo mục 1.3.3, GMP là những biện pháp, thao tác thực hành cần phải tuân thủ nhằm kiểm soát mọi yếu tố ảnh hưởng tới quá trình hình thành chất lượng sản phẩm.",1);
  add(5,"Điểm kiểm soát tới hạn (CCP) được xác định dựa trên:",["Kết quả của quyết định sử dụng công nghệ mới", "Sơ đồ quyết định (Decision Tree) và khả năng kiểm soát mối nguy tại công đoạn đó", "Mức độ tiêu thụ sản phẩm trên thị trường", "Chi phí đầu tư thiết bị"],1,"Mục 1.3.13 và 1.3.12 nêu rằng CCP là công đoạn sản xuất tại đó các biện pháp kiểm soát được thực hiện; việc xác định CCP thường dùng Decision Tree để đánh giá khả năng kiểm soát mối nguy.",2);
  add(5,"Giới hạn tới hạn (Critical Limit) là:",["Mức giá trị tối đa của sản lượng sản xuất trong một ngày", "Mức giá trị của các chỉ tiêu hoặc tiêu chí được xác định cho từng biện pháp tại mỗi CCP", "Thời gian tối đa cho phép dừng máy trong quá trình sản xuất", "Số lượng nhân công tối thiểu cần có ở mỗi công đoạn"],1,"Mục 1.3.14 định nghĩa Critical Limit là mức giá trị của các chỉ tiêu hoặc tiêu chí được xác định cho từng biện pháp tại mỗi CCP để kiểm soát mối nguy.",1);
  add(5,"Trong quy chuẩn, \"Hành động sửa chữa (Corrective Action)\" được thực hiện khi:",["Có yêu cầu thay đổi nhãn mác sản phẩm", "Giới hạn tới hạn bị vi phạm", "Kết thúc một đợt kiểm tra nội bộ", "Nhân viên nghỉ phép"],1,"Mục 1.3.16 mô tả Corrective Action là các hành động dự kiến thực hiện khi giới hạn tới hạn bị vi phạm nhằm khắc phục hậu quả và ngăn ngừa tái diễn.",2);
  add(5,"Theo QCVN 02-02, \"Mối nguy đáng kể (Significant hazard)\" là:",["Mối nguy có khả năng xuất hiện thấp và hậu quả nhẹ", "Mối nguy có nhiều khả năng xảy ra và gây hậu quả nghiêm trọng cho sức khỏe người tiêu dùng", "Mối nguy chỉ ảnh hưởng đến màu sắc của sản phẩm", "Mối nguy không ảnh hưởng đến an toàn thực phẩm"],1,"Mục 1.3.9 định nghĩa Significant hazard là mối nguy có nhiều khả năng xảy ra, gây hậu quả nghiêm trọng cho sức khỏe người tiêu dùng.",1);
  add(5,"Trong một tình huống thực tế, một cơ sở chế biến cá tươi nhận thấy nhiệt độ bảo quản sau khi rã đông thường vượt quá 5°C trong 30 phút. Hành động nào sau đây là Corrective Action phù hợp theo quy chuẩn?",["Ghi nhận lại dữ liệu và tiếp tục sản xuất", "Tăng tốc độ rã đông bằng cách dùng máy làm lạnh mạnh hơn", "Dừng dây chuyền, kiểm tra lại thiết bị làm lạnh, loại bỏ sản phẩm không đạt và thực hiện đào tạo lại nhân viên về kiểm soát nhiệt độ", "Giảm thời gian bảo quản bằng cách bán nhanh hơn"],2,"Khi giới hạn tới hạn (nhiệt độ bảo quản) bị vi phạm, theo mục 1.3.16 Corrective Action phải dừng dây chuyền, xác định nguyên nhân (thiết bị), loại bỏ sản phẩm không đạt và thực hiện các biện pháp ngăn ngừa tái diễn như đào tạo lại nhân viên.",3);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, Chương trình HACCP được định nghĩa là gì?",["Hệ thống các biện pháp tập trung vào kiểm soát chất lượng sản phẩm cuối cùng.", "Hệ thống các biện pháp mà cơ sở áp dụng nhằm đảm bảo an toàn thực phẩm và chất lượng sản phẩm; được xây dựng trên quan điểm phân tích và kiểm soát mối nguy trước khi chúng xảy ra, bao gồm cả các thủ tục tự thẩm tra và hiệu chỉnh chương trình.", "Kế hoạch chỉ nhằm nhận diện và đánh giá mối nguy tiềm ẩn trong nguyên liệu.", "Tập hợp các quy trình vệ sinh và khử trùng trong cơ sở sản xuất."],1,"Dựa theo Khoản 1.3.18 của Thông tư 47/2009/TT-BNNPTNT: 'Chương trình HACCP... Là hệ thống các biện pháp mà cơ sở áp dụng nhằm đảm bảo an toàn thực phẩm và chất lượng sản phẩm; được xây dựng trên quan điểm phân tích và kiểm soát mối nguy trước khi chúng xảy ra, bao gồm cả các thủ tục tự thẩm tra và hiệu chỉnh chương trình.'",1);
  add(3,"Hoạt động nào sau đây được xem là 'Sơ chế' theo Thông tư 47/2009/TT-BNNPTNT?",["Gia nhiệt và xông khói sản phẩm thủy sản.", "Làm khô và ướp tẩm gia vị.", "Chia tách ra từng phần, bỏ xương, lột da, làm sạch, bóc vỏ, băm/nghiền, cán mỏng, làm lạnh, đông lạnh hay rã đông.", "Chiết xuất và kết hợp các hoạt động làm thay đổi sản phẩm ban đầu."],2,"Dựa theo Khoản 1.3.19 của Thông tư 47/2009/TT-BNNPTNT: 'Sơ chế: là hoạt động chia tách ra từng phần, bỏ xương, lột da, làm sạch, bóc vỏ, băm/nghiền, cán mỏng, làm lạnh, đông lạnh hay rã đông.' Các lựa chọn A, B, D thuộc định nghĩa 'Chế biến' tại Khoản 1.3.20.",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, Quy phạm sản xuất (GMP) phải được thiết lập bằng văn bản cho từng công đoạn trong tất cả các dây chuyền công nghệ sản xuất và phải quy định rõ ràng những nội dung nào?",["Chỉ các thủ tục làm vệ sinh và khử trùng.", "Thao tác kỹ thuật của công nhân, các thông số cần đảm bảo, trách nhiệm của từng cá nhân quản lý sản xuất, tổ chức thực hiện và có hồ sơ theo dõi đầy đủ việc thực hiện Quy phạm đó.", "Chỉ các biện pháp kiểm soát mối nguy đáng kể.", "Các yêu cầu về lưu trữ hồ sơ của kế hoạch HACCP."],1,"Dựa theo Khoản 2.1.2 của Thông tư 47/2009/TT-BNNPTNT: 'Cơ sở phải thiết lập bằng văn bản Quy phạm sản xuất (GMP) cho từng công đoạn trong tất cả các dây chuyền công nghệ sản xuất, quy định rõ ràng và hướng dẫn chi tiết thao tác kỹ thuật của công nhân, các thông số cần đảm bảo, trách nhiệm của từng cá nhân quản lý sản xuất, tổ chức thực hiện và có hồ sơ theo dõi đầy đủ việc thực hiện Quy phạm đó.'",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, Quy phạm vệ sinh (SSOP/GHP) phải nêu rõ những nội dung nào?",["Các thủ tục, quy trình, phương pháp làm vệ sinh và khử trùng, biện pháp kiểm soát, phương pháp giám sát cho từng lĩnh vực đảm bảo vệ sinh công nghiệp, tổ chức thực hiện và có hồ sơ theo dõi đầy đủ việc thực hiện Quy phạm đó.", "Các thông số kỹ thuật của từng công đoạn sản xuất.", "Các mối nguy đáng kể và biện pháp kiểm soát chúng.", "Trách nhiệm của từng cá nhân quản lý sản xuất."],0,"Dựa theo Khoản 2.1.3 của Thông tư 47/2009/TT-BNNPTNT: 'Cơ sở phải thiết lập bằng văn bản Quy phạm vệ sinh (SSOP/GHP), nêu rõ các thủ tục, quy trình, phương pháp làm vệ sinh và khử trùng, biện pháp kiểm soát, phương pháp giám sát cho từng lĩnh vực đảm bảo vệ sinh công nghiệp, tổ chức thực hiện và có hồ sơ theo dõi đầy đủ việc thực hiện Quy phạm đó.'",1);
  add(3,"Về yêu cầu chung đối với kế hoạch HACCP, Thông tư 47/2009/TT-BNNPTNT quy định như thế nào về việc xây dựng kế hoạch?",["Được phép xây dựng một kế hoạch HACCP chung cho tất cả các loại sản phẩm của cơ sở.", "Phải thiết lập bằng văn bản, được xây dựng riêng biệt cho từng loại sản phẩm trên dây chuyền công nghệ nhất định, nhưng được phép xây dựng và áp dụng một kế hoạch HACCP chung cho các sản phẩm cùng nhóm sản phẩm tương tự, được sản xuất trên cùng một dây chuyền công nghệ.", "Chỉ cần thiết lập kế hoạch HACCP cho các sản phẩm có rủi ro cao.", "Không yêu cầu phải thiết lập bằng văn bản."],1,"Dựa theo Khoản 2.2.1.1 của Thông tư 47/2009/TT-BNNPTNT: 'Cơ sở phải thiết lập kế hoạch HACCP bằng văn bản, được xây dựng riêng biệt cho từng loại sản phẩm trên dây chuyền công nghệ nhất định. Ðược phép xây dựng và áp dụng một kế hoạch HACCP chung cho các sản phẩm cùng nhóm sản phẩm tương tự, được sản xuất trên cùng một dây chuyền công nghệ.'",2);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, khi phân tích mối nguy, cơ sở phải tiến hành nhận diện và đánh giá các mối nguy nào?",["Chỉ các mối nguy phát sinh trong quá trình chế biến tại cơ sở.", "Chỉ các mối nguy do nhiễm từ môi trường sống của nguyên liệu thủy sản.", "Mọi mối nguy có khả năng xảy ra trong điều kiện thực tế cụ thể tại từng công đoạn trên dây chuyền công nghệ của cơ sở, bao gồm cả các mối nguy tiềm ẩn trong bản thân nguyên liệu thủy sản, do nhiễm từ môi trường sống hoặc do các yếu tố khác trước khi nguyên liệu được đưa vào cơ sở.", "Các mối nguy đã được xác định trong các tài liệu hướng dẫn chung của ngành."],2,"Dựa theo Khoản 2.2.2.1 và 2.2.2.2 của Thông tư 47/2009/TT-BNNPTNT: 'Cơ sở phải tiến hành phân tích mối nguy để nhận diện và đánh giá chính xác mọi mối nguy có khả năng xẩy ra trong điều kiện thực tế cụ thể tại từng công đoạn trên dây chuyền công nghệ của cơ sở. Các mối nguy tiềm ẩn trong bản thân nguyên liệu thuỷ sản, phụ thuộc vào bản chất của loài thuỷ sản, do nhiễm từ môi trường sống hoặc do các yếu tố khác trước khi nguyên liệu được đưa vào cơ sở, cũng phải được phân tích và đánh giá đầy đủ trong kế hoạch HACCP.'",2);
  add(3,"Trong quá trình phân tích mối nguy, nếu không xác định được biện pháp hữu hiệu nào để kiểm soát mối nguy đáng kể, cơ sở phải làm gì theo Thông tư 47/2009/TT-BNNPTNT?",["Tiếp tục sản xuất và ghi nhận mối nguy đó vào hồ sơ.", "Thay đổi dạng sản phẩm, hoặc sửa đổi quy trình công nghệ tại công đoạn đang xét hay ở các công đoạn trước đó.", "Bỏ qua mối nguy đó nếu khả năng xảy ra thấp.", "Chuyển giao trách nhiệm kiểm soát mối nguy cho nhà cung cấp nguyên liệu."],1,"Dựa theo Khoản 2.2.2.5 của Thông tư 47/2009/TT-BNNPTNT: 'Nếu không xác định được biện pháp hữu hiệu nào để kiểm soát mối nguy đáng kể, thì phải thay đổi dạng sản phẩm, hoặc sửa đổi quy trình công nghệ tại công đoạn đang xét hay ở các công đoạn trước đó.'",3);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, 'Cơ sở thu mua' được định nghĩa là gì?",["Nơi diễn ra hoạt động gia nhiệt, xông khói thủy sản.", "Nơi diễn ra hoạt động tiếp nhận, rửa, bảo quản ban đầu nguyên liệu thủy sản để cung cấp cho các cơ sở chế biến thủy sản, các chợ cá hoặc các điểm tiêu thụ trực tiếp.", "Công trình xây dựng chuyên dùng để tổ chức bán buôn nguyên liệu thủy sản.", "Phương tiện thủy chuyên dùng để khai thác và vận chuyển nguyên liệu thủy sản."],1,"Dựa theo Khoản 1.3.23 của Thông tư 47/2009/TT-BNNPTNT: 'Cơ sở thu mua: là nơi diễn ra hoạt động tiếp nhận, rửa, bảo quản ban đầu nguyên liệu thủy sản để cung cấp cho các cơ sở chế biến thủy sản, các chợ cá hoặc các điểm tiêu thụ trực tiếp.'",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, mỗi kế hoạch HACCP phải đảm bảo nhận diện được mọi mối nguy đáng kể và có biện pháp kiểm soát những mối nguy đó một cách hữu hiệu. Ngoài ra, kế hoạch HACCP phải bao gồm đủ những nội dung nào?",["Chỉ bao gồm phân tích mối nguy.", "Từ mục 2.2.2 đến mục 2.2.8.", "Chỉ các quy phạm vệ sinh (SSOP/GHP).", "Các hướng dẫn về marketing sản phẩm."],1,"Dựa theo Khoản 2.2.1.4 của Thông tư 47/2009/TT-BNNPTNT: 'Mỗi kế hoạch HACCP phải bao gồm đủ những nội dung từ mục 2.2.2 đến mục 2.2.8 dưới đây.'",1);
  add(3,"Việc phân tích mối nguy trong kế hoạch HACCP phải được tiến hành như thế nào theo Thông tư 47/2009/TT-BNNPTNT?",["Dựa trên kinh nghiệm của công nhân sản xuất.", "Lần lượt cho từng công đoạn của dây chuyền công nghệ, có căn cứ khoa học, nhằm xác định đúng và đầy đủ các mối nguy đáng kể, căn cứ trên khả năng xảy ra và tính nghiêm trọng của từng mối nguy đã được nhận diện.", "Chỉ tập trung vào các mối nguy sinh học.", "Chỉ cần liệt kê các mối nguy mà không cần đánh giá khả năng xảy ra hay tính nghiêm trọng."],1,"Dựa theo Khoản 2.2.2.3 của Thông tư 47/2009/TT-BNNPTNT: 'Việc phân tích mối nguy phải được tiến hành lần lượt cho từng công đoạn của dây chuyền công nghệ, có căn cứ khoa học, nhằm xác định đúng và đầy đủ các mối nguy đáng kể, căn cứ trên khả năng xảy ra và tính nghiêm trọng của từng mối nguy đã được nhận diện.'",2);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, phương pháp nào sau đây được sử dụng để xác định các điểm kiểm soát tới hạn (CCP)?",["Sơ đồ quyết định CCP hoặc các phương pháp tương đương khác.", "Phân tích thống kê dữ liệu sản xuất trong 5 năm gần nhất.", "Đánh giá cảm quan bởi chuyên gia độc lập.", "Tham khảo ý kiến của toàn bộ công nhân viên trong dây chuyền."],0,"Mục 2.2.3.1 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Sử dụng Sơ đồ quyết định CCP, hoặc các phương pháp tương đương khác để xác định điểm kiểm soát tới hạn.'",1);
  add(3,"Khi thiết lập giới hạn tới hạn tại mỗi CCP, cơ sở sản xuất thủy sản phải đảm bảo điều kiện nào sau đây?",["Giới hạn tới hạn phải được thiết lập dựa trên kinh nghiệm của người quản lý sản xuất.", "Phải có đầy đủ căn cứ khoa học để khẳng định giới hạn tới hạn sẽ ngăn ngừa, loại bỏ hoặc làm giảm mối nguy tới mức chấp nhận được.", "Giới hạn tới hạn chỉ cần phù hợp với quy định nội bộ của cơ sở.", "Giới hạn tới hạn chỉ cần dễ giám sát, không cần căn cứ khoa học."],1,"Mục 2.2.4.2 của Thông tư 47/2009/TT-BNNPTNT nêu rõ: 'Cơ sở phải có đầy đủ căn cứ khoa học để khẳng định rằng, với giới hạn tới hạn đã thiết lập, mối nguy sẽ được ngăn ngừa, loại bỏ hoặc làm giảm tới mức chấp nhận được.'",2);
  add(3,"Theo Quy chuẩn, thủ tục giám sát tại mỗi CCP phải quy định rõ các yếu tố nào?",["Đối tượng giám sát, phương pháp giám sát, tần suất giám sát, người có trách nhiệm giám sát.", "Chi phí giám sát, thời gian thực hiện, công cụ hỗ trợ, báo cáo kết quả.", "Mục tiêu giảm thiểu mối nguy, kế hoạch đào tạo, danh sách thiết bị, quy trình bảo trì.", "Tên sản phẩm, số lô, ngày sản xuất, hạn sử dụng."],0,"Mục 2.2.5.3 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Tại mỗi CCP, thủ tục giám sát phải quy định rõ các yếu tố sau đây: a. Ðối tượng giám sát; b. Phương pháp giám sát; c. Tần suất giám sát; d. Người có trách nhiệm giám sát.'",1);
  add(3,"Theo Quy chuẩn, việc thẩm tra kết quả giám sát tại các CCP phải được thực hiện trong khoảng thời gian nào kể từ ngày có kết quả giám sát?",["Ít nhất trong vòng 24 giờ.", "Ít nhất trong vòng một tuần.", "Ít nhất trong vòng một tháng.", "Bất cứ khi nào có yêu cầu từ cấp trên."],1,"Mục 2.2.5.5 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Việc thẩm tra kết quả giám sát ít nhất phải được thực hiện trong vòng một tuần kể từ ngày có kết quả giám sát.'",2);
  add(3,"Một cơ sở sản xuất thủy sản phát hiện giới hạn tới hạn tại một CCP bị vi phạm. Lô sản phẩm được sản xuất trong khoảng thời gian giữa lần giám sát phát hiện sự vi phạm và lần giám sát cho kết quả bình thường ngay trước đó phải được xử lý như thế nào?",["Tự động đưa ra thị trường nếu không có khiếu nại từ khách hàng.", "Xử lý theo thủ tục đã được thiết lập để kiểm soát và phân biệt với các lô sản phẩm bình thường.", "Tiêu hủy toàn bộ mà không cần đánh giá thêm.", "Tái chế thành sản phẩm cấp thấp hơn mà không cần thủ tục đặc biệt."],1,"Mục 2.2.6.3 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Lô sản phẩm được sản xuất trong khoảng thời gian giữa lần giám sát phát hiện ra sự vi phạm giới hạn tới hạn và lần giám sát cho kết quả bình thường ngay trước đó, phải được xử lý theo thủ tục đã được thiết lập để kiểm soát và phân biệt được với các lô sản phẩm bình thường.'",3);
  add(3,"Trong trường hợp không có bất kỳ sự thay đổi nào có thể ảnh hưởng đến kế hoạch HACCP, việc đánh giá lại kế hoạch HACCP bắt buộc phải được thực hiện với tần suất tối thiểu là bao lâu một lần?",["Sáu tháng một lần.", "Ít nhất mỗi năm một lần.", "Hai năm một lần.", "Khi có yêu cầu từ cơ quan quản lý nhà nước."],1,"Mục 2.2.7.2.b của Thông tư 47/2009/TT-BNNPTNT quy định: 'Khi không có sự thay đổi nào thì bắt buộc cũng phải thực hiện việc đánh giá lại kế hoạch HACCP ít nhất mỗi năm một lần nhằm đảm bảo kiểm soát hữu hiệu các mối nguy đáng kể.'",1);
  add(3,"Mục đích chính của thủ tục tự thẩm tra hệ thống HACCP là gì?",["Để giảm thiểu chi phí kiểm tra từ bên ngoài.", "Để xác định sự tuân thủ của hệ thống HACCP so với kế hoạch đã thiết lập và đánh giá tính hiệu quả của kế hoạch trong việc đảm bảo an toàn thực phẩm.", "Để đào tạo nhân viên mới về các quy trình sản xuất.", "Để lập báo cáo tài chính hàng quý."],1,"Mục 2.2.7.1 của Thông tư 47/2009/TT-BNNPTNT nêu rõ: '...nhằm xác định sự tuân thủ của hệ thống HACCP so với kế hoạch HACCP đã thiết lập và đánh giá tính hiệu quả của kế hoạch HACCP trong việc đảm bảo an toàn thực phẩm.'",2);
  add(3,"Hồ sơ giám sát tại mỗi CCP phải có những thông tin nào bắt buộc theo Quy chuẩn?",["Chỉ cần các thông số kỹ thuật và ngày tháng giám sát.", "Các thông số kỹ thuật, chữ ký của người giám sát, ngày tháng giám sát, chữ ký của người thẩm tra kết quả giám sát, ngày tháng thẩm tra.", "Chỉ cần chữ ký của người giám sát và chữ ký của người đứng đầu cơ sở.", "Các thông số kỹ thuật và chữ ký của người quản lý chất lượng."],1,"Mục 2.2.5.4 và 2.2.5.5 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Hồ sơ giám sát ngoài các thông số kỹ thuật phải có chữ ký của người giám sát, ngày tháng giám sát.' và 'Hồ sơ giám sát phải có chữ ký của người giám sát, người thẩm tra kết quả giám sát, ngày tháng giám sát, ngày tháng thẩm tra.'",2);
  add(3,"Theo Quy chuẩn, hành động sửa chữa dự kiến khi giới hạn tới hạn bị vi phạm tại CCP phải được lập dưới hình thức nào?",["Chỉ cần thỏa thuận miệng giữa các bên liên quan.", "Bằng văn bản hợp lý.", "Ghi chú trong nhật ký sản xuất.", "Thông báo qua email cho các bộ phận liên quan."],1,"Mục 2.2.6.1 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Cơ sở phải dự kiến hành động sửa chữa hợp lý bằng văn bản để áp dụng mỗi khi giới hạn tới hạn bị vi phạm tại từng CCP.'",1);
  add(3,"Tại mỗi điểm kiểm soát tới hạn (CCP) có thể kiểm soát được bao nhiêu mối nguy đáng kể?",["Chỉ duy nhất một mối nguy đáng kể.", "Một hoặc nhiều mối nguy đáng kể.", "Tối đa hai mối nguy đáng kể.", "Không giới hạn số lượng mối nguy đáng kể, miễn là có thể kiểm soát."],1,"Mục 2.2.3.2 của Thông tư 47/2009/TT-BNNPTNT nêu rõ: 'Tại mỗi CCP có thể kiểm soát một hoặc nhiều mối nguy đáng kể.'",1);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT), việc tự thẩm tra Chương trình HACCP phải do đối tượng nào tiến hành?",["Chỉ những cán bộ của cơ quan quản lý nhà nước có thẩm quyền.", "Cán bộ đã được đào tạo và đủ năng lực của cơ sở.", "Bất kỳ nhân viên nào trong cơ sở được giao nhiệm vụ.", "Các chuyên gia tư vấn độc lập từ nước ngoài."],1,"Mục 2.2.7.3 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Việc tự thẩm tra phải do những cán bộ đã được đào tạo và đủ năng lực tiến hành. Trong trường hợp thiếu cán bộ, cơ sở có thể yêu cầu cán bộ của các cơ quan, tổ chức khác thực hiện việc thẩm tra HACCP.\"",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, hồ sơ ghi chép của cơ sở liên quan đến hệ thống HACCP ít nhất phải bao gồm những thông tin cơ bản nào sau đây?",["Tên và địa chỉ cơ sở, ngày tháng năm ghi chép, chữ ký người ghi chép, kết quả giám sát, ngày tháng năm thẩm tra và chữ ký người thẩm tra, tên hoặc ký mã hiệu sản phẩm/lô hàng.", "Chỉ cần kết quả giám sát và chữ ký của người giám sát.", "Thông tin về khách hàng và giá thành sản phẩm.", "Kế hoạch sản xuất chi tiết của 5 năm tới."],0,"Mục 2.2.8.3 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Tất cả các hồ sơ ghi chép của cơ sở... ít nhất phải bao gồm đầy đủ các thông tin cơ bản sau: a. Tên và địa chỉ của cơ sở; b. Ngày tháng năm, thời điểm tiến hành ghi chép và chữ ký của người ghi chép; c. Kết quả giám sát; d. Ngày tháng năm thẩm tra và chữ ký của người thẩm tra hồ sơ; đ. Tên hoặc ký mã hiệu của sản phẩm, của lô hàng có liên quan.\"",1);
  add(3,"Thời gian lưu trữ hồ sơ tối thiểu đối với sản phẩm thủy sản tươi sống theo Thông tư 47/2009/TT-BNNPTNT là bao lâu?",["1 năm.", "6 tháng.", "2 năm.", "3 tháng."],1,"Mục 2.2.8.5.a của Thông tư 47/2009/TT-BNNPTNT quy định: \"6 tháng đối với sản phẩm tươi sống.\"",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, thời gian lưu trữ hồ sơ tối thiểu đối với sản phẩm thủy sản đông lạnh, chế biến và hồ sơ theo dõi thiết bị hoặc các quá trình là bao lâu?",["6 tháng.", "1 năm.", "2 năm.", "3 năm."],2,"Mục 2.2.8.5.b và 2.2.8.5.c của Thông tư 47/2009/TT-BNNPTNT quy định: \"2 năm đối với sản phẩm thuỷ sản đông lạnh, chế biến;\" và \"2 năm đối với hồ sơ theo dõi thiết bị hoặc các quá trình.\"",1);
  add(3,"Khi cơ sở lưu trữ hồ sơ HACCP trong máy tính (computer) theo Thông tư 47/2009/TT-BNNPTNT, cần phải có thủ tục quy định những nội dung nào để chống việc sửa đổi, xóa hoặc mất dữ liệu?",["Chỉ cần quy định nội dung lưu trữ và quy trình thao tác.", "Nội dung lưu trữ, quy trình thao tác, xử lý dữ liệu, lưu trữ dữ liệu, bảo mật, người có trách nhiệm và các chi tiết liên quan khác.", "Chỉ cần quy định người có trách nhiệm và bảo mật dữ liệu.", "Chỉ cần sao lưu dữ liệu định kỳ."],1,"Mục 2.2.8.6 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Cơ sở được phép lưu trữ một số loại hồ sơ trong máy tính (computer). Trong trường hợp đó phải có thủ tục quy định nội dung lưu trữ, quy trình thao tác, xử lý dữ liệu, lưu trữ dữ liệu, bảo mật, người có trách nhiệm và các chi tiết liên quan khác để chống được việc sửa đổi, xoá hoặc mất dữ liệu.\"",2);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, cơ sở phải có văn bản phân công trách nhiệm của cán bộ xem xét và thẩm tra hồ sơ ghi chép theo các mức thời gian nào?",["Hàng ngày, hàng tuần, hàng tháng và xem xét tổng thể theo kế hoạch định kỳ.", "Chỉ hàng tháng và hàng năm.", "Chỉ khi có sự cố hoặc yêu cầu của cơ quan chức năng.", "Tùy thuộc vào loại sản phẩm và quy mô cơ sở."],0,"Mục 2.2.8.7 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Cơ sở phải có văn bản phân công trách nhiệm của cán bộ xem xét và thẩm tra hồ sơ ghi chép theo các mức thời gian: a. Hàng ngày; b. Hàng tuần; c. Hàng tháng; d. Xem xét tổng thể theo kế hoạch định kỳ.\"",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, Chương trình HACCP (sổ tay chất lượng) của cơ sở phải bao gồm đầy đủ các thông tin cơ bản nào sau đây, NGOẠI TRỪ?",["Tên cơ sở, địa chỉ, số điện thoại, fax.", "Sơ đồ tổ chức của cơ sở.", "Danh mục các sản phẩm cạnh tranh trên thị trường.", "Bản vẽ mặt bằng sản xuất được cập nhật kịp thời."],2,"Mục 2.3.1 của Thông tư 47/2009/TT-BNNPTNT quy định các thông tin cơ bản gồm: \"a. Tên cơ sở, địa chỉ, số điện thoại, fax; b. Tên người chịu trách nhiệm cao nhất của cơ sở; c. Sơ đồ tổ chức của cơ sở; d. Bản vẽ mặt bằng sản xuất được cập nhật kịp thời...; đ. Danh mục các trang thiết bị công nghệ chủ yếu của cơ sở và tính năng kỹ thuật của từng thiết bị.\" Danh mục sản phẩm cạnh tranh không được liệt kê.",2);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, chính sách chất lượng và an toàn thực phẩm của cơ sở phải do ai phê duyệt và ban hành?",["Trưởng phòng Quản lý chất lượng.", "Người lãnh đạo cao nhất của cơ sở.", "Cán bộ phụ trách HACCP.", "Cơ quan quản lý nhà nước có thẩm quyền."],1,"Mục 2.3.2 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Cơ sở phải có văn bản về các chính sách đảm bảo chất lượng và an toàn thực phẩm do người lãnh đạo cao nhất của cơ sở phê duyệt và ban hành.\"",1);
  add(3,"Chính sách chất lượng của cơ sở theo Thông tư 47/2009/TT-BNNPTNT ít nhất phải đảm bảo nội dung và yêu cầu nào sau đây?",["Có văn bản quyết định phê duyệt và cho phép thực hiện kế hoạch HACCP, ghi rõ loại sản phẩm và vị trí sản xuất được kiểm soát, xác định phạm vi áp dụng hệ thống HACCP.", "Chỉ cần nêu cam kết chung chung về chất lượng sản phẩm.", "Tập trung vào mục tiêu lợi nhuận của cơ sở.", "Mô tả chi tiết quy trình sản xuất của từng sản phẩm."],0,"Mục 2.3.2.1 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Có văn bản quyết định phê duyệt và cho phép thực hiện kế hoạch HACCP, ghi rõ loại sản phẩm và vị trí sản xuất được kiểm soát, xác định phạm vi áp dụng hệ thống HACCP.\"",2);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, đối với hồ sơ đã ghi kết quả giám sát, cơ sở phải tuân thủ quy định nào sau đây?",["Có thể tẩy xóa, sửa chữa nếu có sai sót nhỏ.", "Phải được giữ gìn cẩn thận, không tẩy xóa, sửa chữa và thay đổi.", "Chỉ cần lưu trữ trong thời gian ngắn để tham khảo.", "Có thể thay đổi nội dung để phù hợp với tình hình sản xuất."],1,"Mục 2.2.8.4 của Thông tư 47/2009/TT-BNNPTNT quy định: \"Hồ sơ đã ghi kết quả giám sát phải được giữ gìn cẩn thận, không tẩy xoá, sửa chữa và thay đổi.\"",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, cơ sở sản xuất thủy sản phải cam kết bằng văn bản về việc áp dụng Chương trình HACCP đã được phê duyệt. Ngoài ra, văn bản này cần quy định rõ điều gì để đảm bảo Chương trình HACCP hoạt động hiệu quả?",["Nghĩa vụ, trách nhiệm và quyền hạn của các cán bộ chủ chốt.", "Quy trình kiểm tra định kỳ của cơ quan quản lý.", "Danh sách các nhà cung cấp nguyên liệu chính.", "Kế hoạch marketing và phân phối sản phẩm."],0,"Mục 2.3.2.4 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Cam kết bằng văn bản áp dụng đúng theo Chương trình HACCP đã được phê duyệt tại cơ sở. Quy định rõ nghĩa vụ, trách nhiệm và quyền hạn của các cán bộ chủ chốt nhằm đảm bảo Chương trình HACCP hoạt động có hiệu quả.'",1);
  add(3,"Ai là người có trách nhiệm ra quyết định bằng văn bản thành lập Đội HACCP tại cơ sở sản xuất thủy sản theo Thông tư 47/2009/TT-BNNPTNT?",["Trưởng phòng Quản lý Chất lượng.", "Người lãnh đạo cao nhất của cơ sở.", "Đại diện của cơ quan kiểm tra nhà nước.", "Toàn thể công nhân viên trong cơ sở."],1,"Mục 2.3.3.1 của Thông tư 47/2009/TT-BNNPTNT nêu rõ: 'Người lãnh đạo cao nhất của cơ sở phải ra quyết định bằng văn bản thành lập Đội HACCP kèm theo bản danh sách và phân công trách nhiệm rõ ràng cho các thành viên của Đội.'",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, các thành viên của Đội HACCP cần có những tiêu chuẩn nào để đảm bảo xây dựng và thực hiện Chương trình HACCP hiệu quả?",["Có kinh nghiệm ít nhất 5 năm trong ngành thủy sản.", "Đã được đào tạo về HACCP, có đủ kiến thức và kinh nghiệm.", "Là nhân viên lâu năm của cơ sở.", "Có bằng cấp đại học trở lên."],1,"Mục 2.3.3.2 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Đội HACCP phải bao gồm những người đã được đào tạo về HACCP, có đủ kiến thức và kinh nghiệm để xây dựng và tổ chức thực hiện Chương trình HACCP có hiệu quả.'",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, cơ sở phải xây dựng thủ tục bằng văn bản nhằm đảm bảo Đội HACCP nhận được thông tin đầy đủ và kịp thời về những thay đổi nào sau đây?",["Các sản phẩm mới, thay đổi về nguyên liệu, thay đổi trong hệ thống công nghệ và thiết bị.", "Tình hình tài chính của cơ sở, kế hoạch mở rộng thị trường, chiến lược giá sản phẩm.", "Lịch trình bảo trì máy móc không liên quan đến an toàn thực phẩm, thông tin cá nhân của nhân viên.", "Các hoạt động xã hội của công ty, thông tin về đối thủ cạnh tranh."],0,"Mục 2.3.3.3 của Thông tư 47/2009/TT-BNNPTNT liệt kê các loại thông tin mà Đội HACCP cần nhận được, bao gồm: 'a. Các sản phẩm mới; b. Những thay đổi về nguyên liệu, sản phẩm hoặc dịch vụ; c. Những thay đổi trong hệ thống công nghệ và thiết bị của cơ sở;...' Đáp án A bao gồm các mục a, b, c.",2);
  add(3,"Khi Đội HACCP nhận được thông tin về những thay đổi liên quan đến sản phẩm, nguyên liệu, công nghệ, nhà xưởng, v.v., trách nhiệm chính của Đội là gì theo Thông tư 47/2009/TT-BNNPTNT?",["Báo cáo trực tiếp lên cơ quan nhà nước có thẩm quyền.", "Đánh giá những thay đổi và điều chỉnh kế hoạch HACCP để thích ứng với các điều kiện mới.", "Tổ chức họp toàn thể nhân viên để thông báo về các thay đổi.", "Yêu cầu ngừng sản xuất ngay lập tức cho đến khi các thay đổi được giải quyết."],1,"Mục 2.3.3.4 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Đội HACCP phải đánh giá những thay đổi nêu trên và điều chỉnh kế hoạch HACCP để đảm bảo thích ứng với các điều kiện mới.'",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, để đánh giá được những mối nguy đáng kể, bản mô tả sản phẩm ít nhất phải bao gồm thông tin gì về nguyên liệu thủy sản chính?",["Giá thành nhập khẩu và lợi nhuận dự kiến.", "Tên gọi và tên khoa học, đặc điểm lý, hoá, sinh học cần lưu ý, khu vực khai thác/nuôi trồng.", "Lịch sử giao dịch với nhà cung cấp, số lượng tồn kho hiện tại.", "Thông tin về đối thủ cạnh tranh sử dụng nguyên liệu tương tự."],1,"Mục 2.3.4.1 của Thông tư 47/2009/TT-BNNPTNT quy định bản mô tả sản phẩm về nguyên liệu phải bao gồm: 'a. Tên gọi và tên khoa học của nguyên liệu thuỷ sản chính; b. Ðặc điểm lý, hoá, sinh học cần lưu ý; c. Khu vực khai thác hoặc nuôi trồng, khoảng cách, thời gian vận chuyển đến cơ sở; d. Cách thức bảo quản, vận chuyển, tiếp nhận; đ. Biện pháp xử lý trước khi chế biến.' Đáp án B bao gồm các mục a, b, c.",2);
  add(3,"Khi mô tả sản phẩm theo Thông tư 47/2009/TT-BNNPTNT, thông tin nào sau đây BẮT BUỘT phải có đối với sản phẩm cuối cùng?",["Quy cách, kiểu bao gói, điều kiện bảo quản, thời hạn sử dụng và phương thức xử lý trước khi sử dụng.", "Chi phí sản xuất, giá bán lẻ đề xuất và chiến lược quảng cáo.", "Danh sách các nhà phân phối và thị trường mục tiêu.", "Lịch sử phát triển sản phẩm và các phiên bản trước đó."],0,"Mục 2.3.4.2 của Thông tư 47/2009/TT-BNNPTNT liệt kê các thông tin bắt buộc về sản phẩm, bao gồm: 'a. Quy cách; b. Các thành phần khác ngoài nguyên liệu chính; c. Tóm tắt các công đoạn chế biến; d. Kiểu bao gói; đ. Ðiều kiện bảo quản; e. Ðiều kiện phân phối, vận chuyển; g. Thời hạn sử dụng; h. Yêu cầu về dán nhãn; i. Các điều kiện đặc biệt; k. Phương thức xử lý trước khi sử dụng; l. Ðối tượng sử dụng.' Đáp án A bao gồm nhiều mục quan trọng trong số đó.",2);
  add(3,"Sơ đồ quy trình công nghệ chế biến sản phẩm theo Thông tư 47/2009/TT-BNNPTNT phải được lập bằng văn bản, được phê duyệt và đảm bảo những yêu cầu nào?",["Bao gồm tất cả các công đoạn của quá trình sản xuất, đúng với các công đoạn thực tế, có đầy đủ các thông số kỹ thuật và thao tác tại mỗi bước.", "Chỉ cần bao gồm các công đoạn chính, không cần chi tiết các thông số kỹ thuật.", "Chỉ cần thể hiện các công đoạn xử lý nguyên liệu chính, bỏ qua các thành phần khác.", "Có thể được vẽ tay và không cần phê duyệt chính thức."],0,"Mục 2.3.5 của Thông tư 47/2009/TT-BNNPTNT quy định sơ đồ quy trình công nghệ phải được lập bằng văn bản, được phê duyệt và đảm bảo: 'a. Bao gồm tất cả các công đoạn của quá trình sản xuất...; b. Ðúng với các công đoạn thực tế; c. Có đầy đủ các thông số kỹ thuật và thao tác tại mỗi bước; d. Có bản thuyết minh chi tiết các bước của quá trình sản xuất.' Đáp án A bao gồm các yêu cầu a, b, c.",2);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, Quy phạm sản xuất (GMP) được xây dựng như thế nào?",["Chỉ cần xây dựng một GMP chung cho toàn bộ cơ sở.", "Được xây dựng cho từng sản phẩm hoặc nhóm sản phẩm tương tự, bao gồm các GMP của từng công đoạn hoặc một phần công đoạn sản xuất.", "Chỉ xây dựng cho các công đoạn có nguy cơ cao về an toàn thực phẩm.", "Được xây dựng bởi cơ quan nhà nước có thẩm quyền và áp dụng chung cho tất cả các cơ sở."],1,"Mục 2.3.6.1 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Quy phạm sản xuất (GMP) được xây dựng cho từng sản phẩm hoặc nhóm sản phẩm tương tự, bao gồm các GMP của từng công đoạn hoặc một phần công đoạn sản xuất trong quy trình công nghệ chế biến sản phẩm.'",1);
  add(3,"Một Quy phạm sản xuất (GMP) theo Thông tư 47/2009/TT-BNNPTNT phải bao gồm ít nhất các nội dung nào sau đây?",["Mô tả rõ yêu cầu kỹ thuật hoặc quy trình chế biến, nêu rõ lý do thực hiện, mô tả chính xác các thao tác/thủ tục và phân công cụ thể việc thực hiện/giám sát.", "Danh sách đầy đủ các nhà cung cấp thiết bị và phụ tùng thay thế.", "Báo cáo tài chính hàng quý và dự báo lợi nhuận.", "Kế hoạch tuyển dụng nhân sự và chính sách lương thưởng."],0,"Mục 2.3.6.2 của Thông tư 47/2009/TT-BNNPTNT liệt kê các nội dung tối thiểu của một GMP: 'a. Mô tả rõ yêu cầu kỹ thuật hoặc quy trình chế biến tại công đoạn hoặc một phần công đoạn sản xuất đó; b. Nêu rõ lý do phải thực hiện các yêu cầu hoặc quy trình kỹ thuật đã nêu; c. Mô tả chính xác các thao tác, thủ tục phải tuân thủ...; d. Phân công cụ thể việc thực hiện và giám sát.' Đáp án A bao gồm các mục này.",2);
  add(5,"Theo Thông tư 47/2009/TT-BNNPTNT, cơ sở phải xây dựng biểu mẫu giám sát việc thực hiện GMP như thế nào?",["Một biểu mẫu duy nhất cho toàn bộ GMP và CCP, không cần tuân thủ mục 2.2.8", "Biểu mẫu riêng cho mỗi GMP, không cho phép ghép chung", "Biểu mẫu phải tuân thủ quy định tại mục 2.2.8; nếu thích hợp có thể ghép chung một biểu mẫu để giám sát nhiều GMP và CCP", "Không cần biểu mẫu, chỉ ghi chép bằng tay"],2,"Điều 2.3.6.3 quy định: \"Cơ sở phải xây dựng các biểu mẫu giám sát việc thực hiện GMP, theo đúng những yêu cầu quy định tại mục 2.2.8. Nếu thích hợp và thuận tiện, có thể ghép chung một biểu mẫu để giám sát nhiều GMP và CCP.\"",1);
  add(5,"Trong quy phạm vệ sinh (SSOP/GHP) theo mục 2.3.7.1, yếu tố nào sau đây **KHÔNG** được liệt kê là một lĩnh vực cần kiểm soát?",["Chất lượng nước dùng trong sản xuất", "Quản lý chất thải", "Kiểm soát độ ẩm trong kho bảo quản", "Vệ sinh cá nhân"],2,"Mục 2.3.7.1 liệt kê các lĩnh vực a, b, c, d, đ, e, g, h, i, k. Kiểm soát độ ẩm trong kho không nằm trong danh sách này.",1);
  add(5,"Mỗi thành phần của Quy phạm vệ sinh phải bao gồm ít nhất bốn nội dung. Nội dung nào sau đây **KHÔNG** phải có trong mỗi thành phần?",["Nêu rõ các quy định của Việt Nam và quốc tế liên quan", "Mô tả chi tiết các thủ tục và thao tác phải thực hiện", "Đánh giá tài chính chi phí thực hiện quy phạm", "Phân công cụ thể việc thực hiện và giám sát"],2,"Theo mục 2.3.7.2, bốn nội dung bắt buộc là a) quy định pháp lý, b) mô tả điều kiện cụ thể, c) mô tả chi tiết thủ tục, d) phân công thực hiện. Đánh giá tài chính không phải yêu cầu bắt buộc.",2);
  add(5,"Kế hoạch HACCP phải bao gồm các nội dung nào?",["Chỉ bao gồm phân tích mối nguy và xác định CCP", "Bao gồm đầy đủ các nội dung từ mục 2.2.1 đến mục 2.2.8", "Chỉ cần có các biện pháp kiểm soát sau khi sản phẩm đã hoàn thành", "Không yêu cầu lập kế hoạch nếu cơ sở đã có SSOP"],1,"Mục 2.3.8 nêu rõ: \"Kế hoạch HACCP đối với mỗi sản phẩm phải bao gồm đầy đủ các nội dung đã được quy định trong các mục từ mục 2.2.1 đến mục 2.2.8.\"",1);
  add(5,"Khi thiết lập thủ tục truy xuất và thu hồi/xử lý, cơ sở phải thực hiện các bước nào sau đây?",["Chỉ lập văn bản quy định, không cần thông báo bên liên quan", "Lập văn bản, thực hiện thông báo kịp thời đến các bên hữu quan, và ghi chép đầy đủ vào hồ sơ", "Chỉ thông báo cho khách hàng mà không cần lưu trữ hồ sơ", "Thực hiện thu hồi mà không cần lập kế hoạch đào tạo nhân viên"],1,"Các điểm 2.3.9.1‑2.3.9.4 quy định: phải có văn bản quy định, thông báo kịp thời đến cơ quan thẩm quyền, khách hàng; ghi chép vào hồ sơ và lưu trữ đầy đủ.",2);
  add(5,"Về đào tạo HACCP, nội dung nào sau đây **KHÔNG** phải được nêu trong chương trình đào tạo?",["Kiến thức cơ bản về HACCP phù hợp với quy chuẩn này", "Yêu cầu về trình độ của người biên soạn chương trình", "Chi tiết về lợi nhuận kinh doanh của công ty", "Kiểm tra sau mỗi khoá đào tạo"],2,"Mục 2.3.10.3‑2.3.10.5 quy định các nội dung: kiến thức cơ bản, người biên soạn phải đủ trình độ, kiểm tra sau khoá, lưu trữ hồ sơ. Lợi nhuận kinh doanh không phải là nội dung đào tạo HACCP.",2);
  add(5,"Thiết bị dùng để giám sát điểm kiểm soát tới hạn (CCP) phải được:",["Hiệu chuẩn một lần duy nhất khi mua mới", "Kiểm soát và hiệu chuẩn theo quy định của các Quy chuẩn quốc gia, tiêu chuẩn Việt Nam hoặc tiêu chuẩn quốc tế", "Không cần hiệu chuẩn nếu có độ chính xác cao", "Chỉ cần hiệu chuẩn khi có sự cố"],1,"Mục 2.3.11.1 nêu: \"Mọi thiết bị dùng để giám sát điểm kiểm soát tới hạn ... phải được kiểm soát và hiệu chỉnh theo quy định tại các Quy chuẩn quốc gia, tiêu chuẩn Việt Nam hoặc tiêu chuẩn quốc tế.\"",1);
  add(5,"Nếu cơ sở có thiết bị tự hiệu chỉnh, yêu cầu nào sau đây phải được thực hiện?",["Không cần lập văn bản, chỉ thực hiện tự động", "Cơ sở phải có văn bản nêu rõ thủ tục và phương pháp hiệu chỉnh", "Chỉ cần ghi lại kết quả hiệu chỉnh trong sổ nhật ký", "Hiệu chỉnh chỉ thực hiện khi có yêu cầu của khách hàng"],1,"Mục 2.3.11.2 quy định: \"Đối với các thiết bị cơ sở đủ khả năng tự hiệu chỉnh, cơ sở phải có văn bản nêu rõ thủ tục và phương pháp hiệu chỉnh.\"",2);
  add(5,"Trong việc thẩm tra hiệu quả của Quy phạm vệ sinh, cơ sở phải:",["Lấy mẫu và kiểm tra các chỉ tiêu vệ sinh công nghiệp định kỳ, lưu trữ kết quả theo mục 2.2.8", "Chỉ kiểm tra khi có khiếu nại từ khách hàng", "Thực hiện kiểm tra một lần mỗi năm và không cần lưu trữ hồ sơ", "Sử dụng chỉ các chỉ tiêu nội bộ mà không cần tham khảo tiêu chuẩn"],0,"Mục 2.3.7.5 yêu cầu: \"Cơ sở phải có kế hoạch thẩm tra hiệu quả của việc thực hiện Quy phạm vệ sinh bằng cách định kỳ tiến hành lấy mẫu để kiểm tra các chỉ tiêu vệ sinh công nghiệp. Kết quả thẩm tra ... phải được lưu trữ trong hồ sơ theo đúng những quy định tại mục 2.2.8.\"",2);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT), nếu cơ sở sản xuất có phòng kiểm nghiệm chất lượng riêng, yêu cầu bắt buộc là gì?",["Chỉ cần có giấy phép hoạt động của phòng kiểm nghiệm.", "Phải có thủ tục giám sát và thẩm định kết quả kiểm nghiệm.", "Định kỳ gửi mẫu đến phòng kiểm nghiệm bên ngoài để đối chiếu.", "Đảm bảo tất cả nhân viên phòng kiểm nghiệm có chứng chỉ quốc tế."],1,"Theo Điều 2.3.12.1 của Thông tư 47/2009/TT-BNNPTNT, 'Nếu cơ sở có phòng kiểm nghiệm chất lượng riêng, phải có thủ tục giám sát và thẩm định kết quả kiểm nghiệm.'",1);
  add(3,"Trong trường hợp cơ sở sản xuất thủy sản không có phòng kiểm nghiệm riêng hoặc phòng kiểm nghiệm của cơ sở không đáp ứng phân tích các chỉ tiêu liên quan đến quản lý chất lượng, cơ sở đó phải thực hiện điều gì?",["Dừng hoạt động sản xuất cho đến khi có phòng kiểm nghiệm đạt chuẩn.", "Ký hợp đồng thường xuyên với phòng kiểm nghiệm bên ngoài và có thủ tục giám sát, thẩm định kết quả kiểm nghiệm.", "Tự đào tạo nhân viên để thực hiện kiểm nghiệm nội bộ.", "Chỉ cần cam kết đảm bảo chất lượng sản phẩm mà không cần kiểm nghiệm bên ngoài."],1,"Theo Điều 2.3.12.2 của Thông tư 47/2009/TT-BNNPTNT, 'Nếu cơ sở không có phòng kiểm nghiệm riêng hoặc phòng kiểm nghiệm của cơ sở không đáp ứng phân tích các chỉ tiêu liên quan đến quản lý chất lượng thì phải có hợp đồng thường xuyên với phòng kiểm nghiệm bên ngoài và phải có thủ tục giám sát và thẩm định kết quả kiểm nghiệm của phòng kiểm nghiệm này.'",1);
  add(3,"Cơ quan Nhà nước nào chịu trách nhiệm quản lý thống nhất các hoạt động đánh giá và chứng nhận hợp quy theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Bộ Nông nghiệp và Phát triển nông thôn.", "Cục Thú y.", "Cục Quản lý Chất lượng Nông lâm sản và Thủy sản (NAFIQAD).", "Sở Nông nghiệp và Phát triển nông thôn các tỉnh."],2,"Theo Điều 3.1 của Thông tư 47/2009/TT-BNNPTNT, 'Cục Quản lý Chất lượng Nông lâm sản và Thủy sản (NAFIQAD) là cơ quan Nhà nước quản lý thống nhất các hoạt động đánh giá và chứng nhận hợp quy theo quy chuẩn này; chịu trách nhiệm tổ chức kiểm tra giám sát việc thực hiện quy chuẩn này.'",1);
  add(3,"Trình tự, thủ tục, phương thức đánh giá, chứng nhận sự phù hợp của các cơ sở chế biến thủy sản đối với Quy chuẩn này được thực hiện theo quy định cụ thể của cơ quan nào?",["Cục Quản lý Chất lượng Nông lâm sản và Thủy sản (NAFIQAD).", "Bộ Nông nghiệp và Phát triển nông thôn.", "Sở Nông nghiệp và Phát triển nông thôn.", "Các hiệp hội ngành nghề thủy sản."],1,"Theo Điều 3.2 của Thông tư 47/2009/TT-BNNPTNT, 'Trình tự, thủ tục, phương thức đánh giá, chứng nhận sự phù hợp của các cơ sở chế biến thủy sản đối với Quy chuẩn này được thực hiện theo quy định cụ thể của Bộ Nông nghiệp và Pháp triển Nông thôn.'",1);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, các cơ sở sản xuất kinh doanh thủy sản dùng làm thực phẩm phải có trách nhiệm gì?",["Chỉ cần tuân thủ các quy định về vệ sinh chung của địa phương.", "Xây dựng và thực hiện các quy định về quản lý chất lượng đáp ứng quy định nêu tại quy chuẩn này.", "Đăng ký chứng nhận ISO 9001.", "Chỉ cần báo cáo định kỳ cho cơ quan quản lý mà không cần xây dựng quy định nội bộ."],1,"Theo Điều 3.3 của Thông tư 47/2009/TT-BNNPTNT, 'Các cơ sở sản xuất kinh doanh thủy sản dùng làm thực phẩm phải xây dựng và thực hiện các quy định về quản lý chất lượng đáp ứng quy định nêu tại quy chuẩn này.'",1);
  add(3,"Đối với tàu khai thác và tàu thu mua thủy sản, theo Thông tư 47/2009/TT-BNNPTNT, cần thực hiện các chương trình quản lý chất lượng nào?",["Chỉ cần thực hiện HACCP.", "Thực hiện SSOP, GMP theo hướng dẫn và biểu mẫu của Cơ quan chuyên môn.", "Thực hiện ISO 22000.", "Không cần thực hiện chương trình quản lý chất lượng cụ thể nào."],1,"Theo Điều 3.3.1 của Thông tư 47/2009/TT-BNNPTNT, 'Tàu khai thác, tàu thu mua thủy sản: Thực hiện SSOP, GMP theo hướng dẫn và biểu mẫu của Cơ quan chuyên môn giúp Giám đốc Sở Nông nghiệp và Phát triển nông thôn quản lý về chất lượng ATTP nông lâm thủy sản.'",1);
  add(3,"Ai chịu trách nhiệm xây dựng và tổ chức thực hiện GMP, SSOP tại cảng cá và chợ cá đầu mối theo Quy chuẩn này?",["Cơ quan chuyên môn của Sở Nông nghiệp và Phát triển nông thôn.", "Các thương lái và người kinh doanh tại cảng/chợ.", "Ban quản lý đơn vị.", "Cục Quản lý Chất lượng Nông lâm sản và Thủy sản (NAFIQAD)."],2,"Theo Điều 3.3.2 của Thông tư 47/2009/TT-BNNPTNT, 'Cảng cá, chợ cá đầu mối: Ban quản lý đơn vị chịu trách nhiệm xây dựng và tổ chức thực hiện GMP, SSOP theo các quy định nêu tại Quy chuẩn này.'",1);
  add(3,"Một cơ sở thu mua thủy sản phải xây dựng và thực hiện chương trình quản lý chất lượng nào theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Chương trình HACCP.", "Chương trình SSOP và GMP.", "Hệ thống quản lý chất lượng ISO 9001.", "Chỉ cần tuân thủ các quy định về vệ sinh cơ bản."],1,"Theo Điều 3.3.3 của Thông tư 47/2009/TT-BNNPTNT, 'Cơ sở thu mua: phải xây dựng và thực hiện GMP, SSOP theo các quy định nêu tại Quy chuẩn này.'",1);
  add(3,"Đối với cơ sở sơ chế, chế biến thủy sản, yêu cầu về chương trình đảm bảo chất lượng và an toàn thực phẩm là gì theo Thông tư 47/2009/TT-BNNPTNT?",["Chỉ cần thực hiện GMP và SSOP.", "Phải xây dựng và thực hiện Chương trình đảm bảo chất lượng và ATTP theo nguyên tắc HACCP.", "Đăng ký chứng nhận VietGAP.", "Thực hiện các quy định về vệ sinh môi trường của địa phương."],1,"Theo Điều 3.3.4 của Thông tư 47/2009/TT-BNNPTNT, 'Cơ sở sơ chế, chế biến thủy sản: Phải xây dựng và thực hiện Chương trình đảm bảo chất lượng và ATTP theo nguyên tắc HACCP dựa trên các quy định nêu tại Quy chuẩn này.'",1);
  add(3,"Cơ quan nào chịu trách nhiệm thanh tra việc thực hiện Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản và xử lý các vi phạm theo quy định?",["Cục Quản lý Chất lượng Nông lâm sản và Thủy sản (NAFIQAD).", "Thanh tra chuyên ngành Bộ Nông nghiệp và phát triển nông thôn.", "Công an môi trường.", "Ủy ban nhân dân cấp tỉnh."],1,"Theo Điều 3.4 của Thông tư 47/2009/TT-BNNPTNT, 'Thanh tra chuyên ngành Bộ Nông nghiệp và phát triển nông thôn chịu trách nhiệm thanh tra việc thực hiện Quy chuẩn này và xử lý các vi phạm theo quy định.'",1);
  add(3,"Theo QCVN 02-03:2009/BNNPTNT, đối tượng nào sau đây KHÔNG thuộc phạm vi áp dụng của Quy chuẩn về điều kiện đảm bảo vệ sinh an toàn thực phẩm trong cơ sở chế biến thủy sản ăn liền?",["Cơ sở chế biến thủy sản dùng làm thực phẩm ăn liền", "Cơ sở chế biến đồ hộp thủy sản", "Cơ sở chế biến tôm hấp đông lạnh để ăn liền", "Cơ sở chế biến cá ngừ tươi đóng gói chân không để ăn liền"],1,"Dựa trên Mục 1.2.2 của QCVN 02-03:2009/BNNPTNT, Quy chuẩn này không áp dụng đối với các cơ sở chế biến đồ hộp thủy sản, cơ sở chế biến các loại mắm, nước mắm, sản phẩm hun khói.",1);
  add(3,"Theo QCVN 02-03:2009/BNNPTNT, khái niệm 'Sản phẩm thủy sản ăn liền' được hiểu như thế nào?",["Là loại thực phẩm thủy sản đã qua xử lý nhiệt, không còn vi sinh vật gây bệnh, người tiêu dùng có thể sử dụng ăn ngay mà không cần qua bất cứ công đoạn chế biến nào khác.", "Là sản phẩm thủy sản tươi chỉ qua công đoạn làm lạnh hoặc cấp đông để bảo quản.", "Là sản phẩm thủy sản đã qua chế biến sơ bộ nhưng vẫn cần đun nấu lại trước khi sử dụng.", "Là sản phẩm thủy sản hun khói được đóng gói và bảo quản lạnh."],0,"Dựa trên Mục 1.3.3 của QCVN 02-03:2009/BNNPTNT, 'Sản phẩm thủy sản ăn liền' là loại thực phẩm thủy sản đã qua xử lý nhiệt ở dạng tươi, được bảo quản lạnh hay cấp đông, nhưng không còn tồn tại vi sinh vật gây bệnh, người tiêu dùng có thể sử dụng ăn ngay được mà không cần qua bất cứ công đoạn chế biến nào khác.",1);
  add(3,"Yêu cầu nào sau đây là BẮT BUỘC đối với luồng không khí trong khu vực xử lý thủy sản ăn liền theo QCVN 02-03:2009/BNNPTNT?",["Luồng không khí chỉ lưu thông theo một chiều từ khu vực xử lý thủy sản ăn liền sang các khu vực khác.", "Luồng không khí có thể lưu thông hai chiều giữa khu vực ăn liền và khu sơ chế nguyên liệu.", "Luồng không khí phải được giữ tĩnh, không có sự lưu thông.", "Luồng không khí được phép lưu thông tự do giữa các khu vực để đảm bảo thông thoáng."],0,"Dựa trên Mục 2.1.1.2 của QCVN 02-03:2009/BNNPTNT, khu vực xử lý thủy sản ăn liền phải được thiết kế đảm bảo luồng không khí chỉ lưu thông theo một chiều từ khu vực xử lý thủy sản ăn liền sang các khu vực khác.",1);
  add(3,"Theo QCVN 02-03:2009/BNNPTNT, quy định về rãnh thoát nước trong khu vực xử lý thủy sản ăn liền là gì?",["Được phép có rãnh thoát nước hở từ khu vực khác chảy qua nếu có lưới chắn.", "Không được để bất kỳ rãnh thoát nước hở từ khu vực khác chảy qua khu vực xử lý thủy sản ăn liền.", "Rãnh thoát nước phải được thiết kế để chảy ngược vào khu sơ chế để tái sử dụng nước.", "Rãnh thoát nước phải được che kín hoàn toàn nhưng vẫn được phép chảy từ khu vực khác qua."],1,"Dựa trên Mục 2.1.1.3 của QCVN 02-03:2009/BNNPTNT, không được để bất kỳ rãnh thoát nước hở từ khu vực khác chảy qua khu vực xử lý thủy sản ăn liền.",1);
  add(3,"Trong cơ sở chế biến thủy sản ăn liền, việc thực hiện quá trình xử lý thủy sản chín ăn liền và thủy sản sống ăn liền trong cùng một khu vực được phép khi nào?",["Không bao giờ được phép thực hiện trong cùng một khu vực để tránh lây nhiễm chéo.", "Được phép nếu chúng có cùng ngưỡng vi sinh.", "Chỉ được phép nếu có sự giám sát liên tục của cán bộ chất lượng.", "Được phép nếu có vách ngăn di động ngăn cách tạm thời."],1,"Dựa trên Mục 2.1.1.4 của QCVN 02-03:2009/BNNPTNT, quá trình xử lý thủy sản chín ăn liền và thủy sản sống ăn liền được phép thực hiện trong cùng khu vực nếu chúng có cùng ngưỡng vi sinh.",2);
  add(3,"Theo QCVN 02-03:2009/BNNPTNT, bán thành phẩm chỉ được phép vận chuyển từ khu sơ chế hoặc khu xử lý nhiệt sang khu xử lý thủy sản ăn liền bằng cách nào?",["Đưa qua cửa chính ra vào khu vực ăn liền.", "Sử dụng xe đẩy chuyên dụng đi qua hành lang chung.", "Đưa qua ô cửa.", "Sử dụng băng chuyền kín đi xuyên qua tường."],2,"Dựa trên Mục 2.1.1.5 của QCVN 02-03:2009/BNNPTNT, bán thành phẩm chỉ được phép vận chuyển từ khu sơ chế hoặc khu xử lý nhiệt sang khu xử lý thủy sản ăn liền bằng cách đưa qua ô cửa.",1);
  add(3,"Quy định nào sau đây là đúng về thiết bị và dụng cụ dùng trong xử lý, chế biến thủy sản ăn liền theo QCVN 02-03:2009/BNNPTNT?",["Thiết bị và dụng cụ có thể dùng chung với khu sơ chế nếu được vệ sinh kỹ sau mỗi lần sử dụng.", "Thiết bị và dụng cụ phải được dùng riêng cho mục đích này và được bảo quản ở trong khu vực xử lý thủy sản ăn liền.", "Thiết bị và dụng cụ có thể dùng chung với khu xử lý nhiệt nếu được khử trùng trước khi đưa vào khu vực ăn liền.", "Không có quy định riêng về việc dùng riêng thiết bị và dụng cụ cho khu vực ăn liền."],1,"Dựa trên Mục 2.1.2.1 của QCVN 02-03:2009/BNNPTNT, thiết bị và dụng cụ dùng trong xử lý, chế biến thủy sản ăn liền phải được dùng riêng cho mục đích này và được bảo quản ở trong khu vực xử lý thủy sản ăn liền.",1);
  add(3,"Ngoài phương tiện rửa và làm khô tay, cơ sở chế biến thủy sản ăn liền phải trang bị thêm phương tiện gì tại cửa ra vào và bên trong khu vực xử lý thủy sản ăn liền cho công nhân?",["Phương tiện làm sạch giày dép.", "Phương tiện khử trùng tay công nhân.", "Phương tiện thay quần áo bảo hộ lao động mới.", "Phương tiện kiểm tra nhiệt độ cơ thể."],1,"Dựa trên Mục 2.1.2.2 của QCVN 02-03:2009/BNNPTNT, tại cửa ra vào và bên trong khu vực xử lý thủy sản ăn liền, ngoài phương tiện rửa và làm khô tay, phải trang bị đủ phương tiện khử trùng tay công nhân.",1);
  add(3,"Trước khi vào khu vực xử lý thủy sản ăn liền, công nhân phải được trang bị phương tiện gì để đảm bảo vệ sinh?",["Phương tiện thay toàn bộ quần áo bảo hộ lao động mới.", "Phương tiện làm sạch bụi bám trên mũ, quần áo bảo hộ lao động.", "Phương tiện kiểm tra sức khỏe tổng quát.", "Phương tiện khử trùng toàn thân bằng hóa chất."],1,"Dựa trên Mục 2.1.2.3 của QCVN 02-03:2009/BNNPTNT, phải trang bị phương tiện làm sạch bụi bám trên mũ, quần áo bảo hộ lao động của công nhân trước khi vào khu vực xử lý thủy sản ăn liền.",1);
  add(3,"Khi thực hiện xử lý nhiệt thủy sản ăn liền, yêu cầu đối với nước sạch, hơi nước, không khí và dầu ăn là gì?",["Chỉ cần đảm bảo sạch về mặt cảm quan.", "Phải đảm bảo an toàn vệ sinh và không là nguồn lây nhiễm cho sản phẩm.", "Chỉ cần đạt tiêu chuẩn nước sinh hoạt thông thường.", "Không có quy định cụ thể về hơi nước, không khí và dầu ăn."],1,"Dựa trên Mục 2.1.3.1.a của QCVN 02-03:2009/BNNPTNT, phải sử dụng nước sạch theo quy định của Bộ Y tế. Hơi nước, không khí và dầu ăn phải đảm bảo ATVS và không là nguồn lây nhiễm cho sản phẩm.",1);
  add(3,"Theo QCVN 02-03:2009/BNNPTNT, cơ sở chế biến thủy sản ăn liền phải thực hiện điều gì liên quan đến thời gian và nhiệt độ xử lý nhiệt?",["Chỉ cần ghi chép lại nhiệt độ cuối cùng của sản phẩm sau khi xử lý nhiệt.", "Phải lập kế hoạch và thực hiện giám sát thời gian và nhiệt độ xử lý nhiệt theo quy định.", "Chỉ cần kiểm tra định kỳ hàng tháng về nhiệt độ xử lý nhiệt.", "Không cần giám sát nếu có thiết bị xử lý nhiệt tự động."],1,"Dựa trên Mục 2.1.3.1.b của QCVN 02-03:2009/BNNPTNT, cơ sở phải lập kế hoạch và thực hiện giám sát thời gian và nhiệt độ xử lý nhiệt theo quy định.",1);
  add(3,"Tại khu vực xử lý nhiệt của cơ sở chế biến thủy sản ăn liền, cần trang bị những loại dụng cụ đo nào?",["Dụng cụ đo độ pH và độ mặn.", "Dụng cụ đo độ ẩm không khí và tốc độ gió.", "Dụng cụ đo nhiệt độ bán thành phẩm và thời gian xử lý nhiệt.", "Dụng cụ đo áp suất và lưu lượng nước."],2,"Dựa trên Mục 2.1.3.1.c của QCVN 02-03:2009/BNNPTNT, tại khu vực xử lý nhiệt phải trang bị các loại dụng cụ đo nhiệt độ bán thành phẩm và thời gian xử lý nhiệt.",1);
  add(5,"Sau khi xử lý nhiệt, bán thành phẩm phải được làm nguội và duy trì nhiệt độ trong khoảng nào?",["-5°C đến 0°C", "-1°C đến +4°C", "0°C đến +5°C", "2°C đến +8°C"],1,"Theo mục 2.1.3.2 b của Thông tư 47/2009/TT-BNNPTNT, sau khi làm nguội bán thành phẩm phải được bảo quản sao cho nhiệt độ duy trì từ -1°C đến +4°C.",1);
  add(5,"Trong quá trình làm nguội, nguồn nước nào được phép sử dụng theo quy định?",["Nước sông", "Nước biển", "Nước sạch theo Điều 1.3.11", "Nước tái sử dụng"],2,"Mục 2.1.3.2 a quy định việc sử dụng nước sạch theo Điều 1.3.11 của QCVN 02-01:2009/BNNPTNT để làm nguội.",1);
  add(5,"Thuỷ sản ăn liền tươi sống có mối nguy ký sinh trùng phải được bảo quản ít nhất bao lâu khi nhiệt độ tâm sản phẩm đạt -20°C?",["5 ngày", "7 ngày", "10 ngày", "14 ngày"],1,"Mục 2.1.5.3 quy định thời gian bảo quản tối thiểu 7 ngày khi nhiệt độ ở tâm sản phẩm đạt -20°C.",2);
  add(5,"Tần suất vệ sinh và khử trùng bổ sung giữa các ca sản xuất ở khu vực xử lý thuỷ sản ăn liền là:",["Mỗi 30 phút một lần", "Mỗi 1 giờ một lần", "Mỗi 2 giờ một lần", "Chỉ vào cuối ca"],1,"Mục 2.1.6.1 a yêu cầu vệ sinh, khử trùng bổ sung giữa ca sản xuất với tần suất 1 giờ 1 lần.",1);
  add(5,"Trong các yêu cầu về vệ sinh công nhân, trang thiết bị nào không bắt buộc phải mặc trong khu vực xử lý thuỷ sản ăn liền?",["Quần áo bảo hộ", "Ủng bảo hộ", "Mũ che kín tóc", "Bảo hiểm tai"],3,"Mục 2.1.6.2 a liệt kê quần áo bảo hộ, ủng, mũ, khẩu trang và găng tay; không có yêu cầu về bảo hiểm tai.",1);
  add(5,"Công nhân trực tiếp xử lý thuỷ sản ăn liền phải rửa và khử trùng tay với tần suất:",["Mỗi 30 phút một lần", "Mỗi 1 giờ một lần", "Mỗi 2 giờ một lần", "Chỉ khi bắt đầu và kết thúc ca"],1,"Mục 2.1.6.2 d quy định rửa và khử trùng tay 1 giờ một lần trong giờ làm việc.",2);
  add(5,"Cơ sở chế biến thuỷ sản ăn liền phải xây dựng và áp dụng chương trình quản lý chất lượng dựa trên tiêu chuẩn nào?",["QCVN 02-01", "QCVN 02-02", "QCVN 02-03", "QCVN 02-04"],1,"Mục 2.2.1 yêu cầu cơ sở áp dụng chương trình GMP, SSOP và HACCP theo QCVN 02-02:2009/BNNPTNT.",1);
  add(5,"Chứng nhận hợp quy cho cơ sở chế biến thuỷ sản ăn liền dựa trên quyết định nào của Bộ Khoa học và Công nghệ?",["Quyết định 24/2007/QĐ-BKHCN", "Quyết định 30/2008/QĐ-BKHCN", "Quyết định 12/2009/QĐ-BKHCN", "Quyết định 05/2006/QĐ-BKHCN"],0,"Mục 3.1.1 quy định cơ sở phải thực hiện chứng nhận hợp quy theo Quyết định số 24/2007/QĐ-BKHCN ngày 28/9/2007.",2);
  add(5,"Nếu thuỷ sản ăn liền chưa được bao gói kín, quy định về việc cấp đông đồng thời với sản phẩm khác là:",["Được phép nếu cùng ngưỡng vi sinh vật", "Không được phép", "Chỉ được nếu nhiệt độ dưới -30°C", "Phải được đóng gói riêng trong túi hút chân không"],1,"Mục 2.1.4 quy định thuỷ sản ăn liền chưa bao gói kín không được cấp đông đồng thời với sản phẩm khác không cùng ngưỡng vi sinh vật.",2);
  add(5,"Nhân viên phải kiểm tra sức khỏe định kỳ mỗi bao lâu để được phép làm việc trong khu vực xử lý thuỷ sản ăn liền?",["3 tháng", "6 tháng", "12 tháng", "2 năm"],1,"Mục 2.1.6.2 đ yêu cầu kiểm tra sức khỏe định kỳ 6 tháng 1 lần và phải có hồ sơ khám sức khỏe của cơ quan y tế.",1);
  add(5,"Cơ quan nào có trách nhiệm hướng dẫn phương thức đánh giá, chứng nhận hợp quy cho cơ sở chế biến thủy sản ăn liền?",["Sở Nông nghiệp và Phát triển nông thôn địa phương", "Bộ Nông nghiệp và Phát triển nông thôn", "Tổ chức chứng nhận được chỉ định", "Cơ quan quản lý nhà nước chuyên ngành"],1,"Theo Điều 3.1.3 của Thông tư 47/2009/TT-BNNPTNT, phương thức đánh giá, chứng nhận hợp quy cho cơ sở chế biến thủy sản ăn liền thực hiện theo hướng dẫn của Bộ Nông nghiệp và Phát triển nông thôn.",1);
  add(5,"Sau khi được chứng nhận hợp quy, cơ sở chế biến thủy sản ăn liền phải thực hiện nghĩa vụ nào sau đây?",["Nộp báo cáo sản xuất định kỳ cho Bộ Nông nghiệp và Phát triển nông thôn.", "Thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành do Bộ Nông nghiệp và Phát triển nông thôn chỉ định.", "Đăng ký lại giấy phép kinh doanh với chính quyền địa phương.", "Chờ cơ quan chức năng đến kiểm tra đột xuất."],1,"Theo Điều 3.2.1 của Thông tư 47/2009/TT-BNNPTNT, cơ sở chế biến thủy sản ăn liền được chứng nhận hợp quy phải thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành do Bộ Nông nghiệp và Phát triển nông thôn chỉ định.",1);
  add(5,"Việc công bố hợp quy cho cơ sở chế biến thủy sản ăn liền được thực hiện theo quy định tại văn bản pháp luật nào?",["Điều 14 Luật Tiêu chuẩn và Quy chuẩn kỹ thuật.", "Điều 14 Nghị định số 127/2007/NĐ-CP.", "Điều 14 Thông tư 47/2009/TT-BNNPTNT.", "Điều 14 Nghị định số 01/8/2007/NĐ-CP."],1,"Theo Điều 3.2.2 của Thông tư 47/2009/TT-BNNPTNT, việc công bố hợp quy thực hiện theo quy định tại Điều 14 Nghị định số 127/2007/NĐ-CP.",1);
  add(5,"Đối tượng nào chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Chỉ có cơ sở chế biến thủy sản ăn liền.", "Chỉ có Tổ chức chứng nhận.", "Cơ sở chế biến thủy sản ăn liền và Tổ chức chứng nhận.", "Chủ cơ sở chế biến thủy sản ăn liền."],2,"Theo Điều 3.3.1 của Thông tư 47/2009/TT-BNNPTNT, cơ sở chế biến thủy sản ăn liền và Tổ chức chứng nhận chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất.",1);
  add(5,"Cơ quan nào có thẩm quyền tiến hành thanh tra, kiểm tra định kỳ hoặc đột xuất đối với cơ sở chế biến thủy sản ăn liền và Tổ chức chứng nhận?",["Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương.", "Bộ Y tế và cơ quan y tế địa phương.", "Bộ Khoa học và Công nghệ.", "Các hiệp hội ngành nghề thủy sản."],0,"Theo Điều 3.3.1 của Thông tư 47/2009/TT-BNNPTNT, Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương có thẩm quyền thanh tra, kiểm tra.",1);
  add(5,"Việc tiến hành thanh tra, kiểm tra và xử lý vi phạm trong lĩnh vực này phải tuân thủ nguyên tắc nào?",["Tuân thủ theo quy định của pháp luật hiện hành.", "Theo hướng dẫn của Tổ chức chứng nhận.", "Theo thỏa thuận giữa cơ sở và cơ quan kiểm tra.", "Theo quy định riêng của từng địa phương."],0,"Theo Điều 3.3.2 của Thông tư 47/2009/TT-BNNPTNT, việc tiến hành thanh tra, kiểm tra và xử lý vi phạm phải tuân thủ theo quy định của pháp luật hiện hành.",1);
  add(5,"Trách nhiệm chính của chủ cơ sở chế biến thủy sản ăn liền được quy định trong Quy chuẩn kỹ thuật này là gì?",["Chỉ đạo các đơn vị chức năng phổ biến quy chuẩn.", "Tuân thủ các quy định của Quy chuẩn kỹ thuật nhằm đảm bảo vệ sinh an toàn thực phẩm.", "Tiến hành chứng nhận hợp quy cho cơ sở.", "Thanh tra, kiểm tra định kỳ hoặc đột xuất."],1,"Theo Điều 3.4.1 của Thông tư 47/2009/TT-BNNPTNT, chủ cơ sở chế biến thủy sản ăn liền có trách nhiệm tuân thủ các quy định của Quy chuẩn kỹ thuật nhằm đảm bảo vệ sinh an toàn thực phẩm.",1);
  add(5,"Trong trường hợp các quy định tại Quy chuẩn kỹ thuật này có sự thay đổi, bổ sung hoặc thay thế, thì việc thực hiện sẽ theo nguyên tắc nào?",["Tiếp tục áp dụng quy định cũ cho đến khi có thông báo chính thức.", "Thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.", "Cơ sở tự quyết định áp dụng quy định nào phù hợp nhất.", "Chờ hướng dẫn chi tiết từ Tổ chức chứng nhận."],1,"Theo Điều 3.4.3 của Thông tư 47/2009/TT-BNNPTNT, trong trường hợp các quy định tại quy chuẩn này có sự thay đổi, bổ sung hoặc thay thế thì thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.",1);
  add(3,"Theo QCVN 02-04:2009/BNNPTNT, đối tượng áp dụng của Quy chuẩn này là gì?",["Chỉ các doanh nghiệp nhà nước sản xuất đồ hộp thủy sản.", "Tất cả các tổ chức và cá nhân sản xuất đồ hộp thủy sản.", "Các cơ sở chế biến thủy sản xuất khẩu.", "Các cơ sở sản xuất đồ hộp thủy sản có quy mô lớn."],1,"Khoản 1.2 của QCVN 02-04:2009/BNNPTNT quy định: 'Quy chuẩn này áp dụng cho tất cả các tổ chức và cá nhân sản xuất đồ hộp thủy sản.'",1);
  add(3,"Trong Quy chuẩn QCVN 02-04:2009/BNNPTNT, 'Thanh trùng Paxtơ' được định nghĩa như thế nào?",["Chế độ nhiệt độ thanh trùng đủ cao để tiêu diệt vi sinh vật kháng nhiệt, sản phẩm có hạn sử dụng trên 6 tháng.", "Chế độ nhiệt độ thanh trùng tương đối thấp, thường dưới 100°C, sản phẩm có hạn sử dụng trong vài ngày hoặc lâu hơn, nhưng không quá 6 tháng và phải bảo quản có điều kiện.", "Quá trình loại bỏ khí trong hộp ra ngoài bằng nhiệt hay máy hút chân không.", "Quá trình xếp các lô hộp mới được thanh trùng ở trong phòng có nhiệt độ thích hợp để ổn định sản phẩm."],1,"Khoản 1.3.5.a của QCVN 02-04:2009/BNNPTNT giải thích: 'Thanh trùng Paxtơ (Pasteurisation) là chế độ nhiệt độ thanh trùng tương đối thấp, thường là dưới 1000C (2120F), sản phẩm có hạn sử dụng trong vài ngày hoặc lâu hơn, nhưng không quá 6 tháng và phải bảo quản có điều kiện.'",1);
  add(3,"Theo QCVN 02-04:2009/BNNPTNT, 'Tiệt trùng' là gì?",["Chế độ nhiệt độ thanh trùng tương đối thấp, thường dưới 100°C, sản phẩm có hạn sử dụng không quá 6 tháng.", "Quá trình làm chín nguyên liệu ở mức độ nhất định bằng các phương pháp như chần, hấp, luộc.", "Chế độ nhiệt độ thanh trùng đủ cao, với thời gian đủ dài để tiêu diệt vi sinh vật kháng nhiệt, sản phẩm có hạn sử dụng trên 6 tháng.", "Quá trình loại bỏ khí trong hộp nhằm giảm áp suất bên trong hộp khi thanh trùng."],2,"Khoản 1.3.5.b của QCVN 02-04:2009/BNNPTNT giải thích: 'Tiệt trùng (sterilisation) là chế độ nhiệt độ thanh trùng đủ cao, với thời gian đủ dài để tiêu diệt vi sinh vật kháng nhiệt, Sản phẩm có hạn sử dụng trên 6 tháng.'",1);
  add(3,"'Bảo ôn đồ hộp' được định nghĩa như thế nào trong QCVN 02-04:2009/BNNPTNT?",["Quá trình làm nguội nhanh bán thành phẩm sau xử lý nhiệt bằng nước lạnh hoặc không khí.", "Quá trình ghép kín nắp với hộp bằng máy ghép mí đảm bảo ngăn cách hoàn toàn sản phẩm với không khí bên ngoài.", "Quá trình xếp các lô hộp mới được thanh trùng ở trong phòng có nhiệt độ thích hợp, trong thời gian quy định để sản phẩm trong hộp ổn định và phát hiện các hiện tượng hư hỏng.", "Quá trình gia nhiệt đồ hộp trong thiết bị thanh trùng nhằm tiêu diệt hay kìm hãm hoạt động của vi sinh vật."],2,"Khoản 1.3.6 của QCVN 02-04:2009/BNNPTNT giải thích: 'Bảo ôn đồ hộp là quá trình xếp các lô hộp mới được thanh trùng ở trong phòng có nhiệt độ thích hợp, trong thời gian quy định để sản phẩm trong hộp ổn định và phát hiện các hiện tượng hư hỏng của đồ hộp do các nguyên nhân vật lý, hoá học, vi sinh.'",1);
  add(3,"Theo QCVN 02-04:2009/BNNPTNT, khu vực xử lý nhiệt trong cơ sở sản xuất đồ hộp thủy sản phải đáp ứng yêu cầu nào?",["Phải được bố trí ở vị trí kín đáo, tránh ánh sáng trực tiếp.", "Phải được bố trí ở vị trí thích hợp, đảm bảo thông thoáng, dễ thoát nhiệt, thoát ẩm và ít ảnh hưởng nhất đến các khu vực khác.", "Phải có nhiệt độ ổn định ở mức dưới 25°C để tránh làm hỏng sản phẩm.", "Phải được cách ly hoàn toàn với các khu vực khác để đảm bảo vô trùng tuyệt đối."],1,"Khoản 2.1.1 của QCVN 02-04:2009/BNNPTNT quy định: 'Khu vực xử lý nhiệt phải được bố trí ở vị trí thích hợp, đảm bảo thông thoáng, dễ thoát nhiệt, thoát ẩm và ít ảnh hưởng nhất đến các khu vực khác.'",2);
  add(3,"Khi làm nguội bán thành phẩm sau xử lý nhiệt bằng nước lạnh theo QCVN 02-04:2009/BNNPTNT, nước lạnh sử dụng phải đáp ứng yêu cầu nào?",["Nước lạnh phải là nước sạch, dư lượng clorin ít nhất phải bằng 0.5 ppm.", "Nước lạnh phải là nước sạch, dư lượng clorin ít nhất phải bằng 1 ppm.", "Nước lạnh phải là nước đã qua xử lý UV.", "Nước lạnh phải là nước đun sôi để nguội."],1,"Khoản 2.2.2 của QCVN 02-04:2009/BNNPTNT quy định: 'Nước lạnh dùng làm nguội phải là nước sạch, dư lượng clorin ít nhất phải bằng 1ppm.'",2);
  add(3,"Đối với thùng chứa nước sốt/dầu trong quá trình sản xuất đồ hộp thủy sản, QCVN 02-04:2009/BNNPTNT yêu cầu gì?",["Thùng chứa phải làm bằng vật liệu không gỉ và có dung tích lớn.", "Thùng chứa phải có nắp đậy, có bộ phận cấp nhiệt để duy trì nhiệt độ nước sốt/dầu theo quy định.", "Thùng chứa phải được đặt trong phòng lạnh để bảo quản.", "Thùng chứa phải được vệ sinh bằng hóa chất chuyên dụng mỗi ngày."],1,"Khoản 2.3 của QCVN 02-04:2009/BNNPTNT quy định: 'Thùng chứa nước sốt/dầu trong quá trình sản xuất phải có nắp đậy, có bộ phận cấp nhiệt để duy trì nhiệt độ nước sốt/dầu theo quy định.'",2);
  add(3,"Theo QCVN 02-04:2009/BNNPTNT, vỏ hộp dùng trong sản xuất đồ hộp thủy sản phải đáp ứng yêu cầu nào về chất lượng?",["Vỏ hộp phải có khả năng tái chế cao và thân thiện với môi trường.", "Vỏ hộp phải không gây độc, không làm biến đổi chất lượng, màu sắc, mùi vị của thực phẩm và chịu được các tác động cơ lý trong quá trình sản xuất, vận chuyển và tiêu thụ.", "Vỏ hộp phải được sản xuất từ nguyên liệu nhập khẩu để đảm bảo chất lượng.", "Vỏ hộp phải có thiết kế bắt mắt và dễ dàng mở."],1,"Khoản 2.4.1 của QCVN 02-04:2009/BNNPTNT quy định: 'Vỏ hộp phải đáp ứng yêu cầu: Không gây độc, không làm biến đổi chất lượng, màu sắc, mùi vị của thực phẩm và chịu được các tác động cơ lý trong quá trình sản xuất, vận chuyển và tiêu thụ.'",2);
  add(5,"Theo QCVN 47/2009, khi rửa hộp bằng nước nóng hoặc hơi nước, yêu cầu nào sau đây là đúng?",["Nước phải có áp lực và nhiệt độ đủ để làm sạch nhưng không cần kiểm soát nhiệt độ cụ thể.", "Nước phải đạt áp lực và nhiệt độ tối thiểu được quy định trong tiêu chuẩn, đảm bảo khả năng khử vi sinh.", "Chỉ cần nước sạch, áp lực và nhiệt độ không quan trọng nếu thời gian rửa đủ lâu.", "Nước phải được làm lạnh trước khi rửa để tránh biến dạng hộp."],1,"Điều 2.4.3 yêu cầu nước nóng hoặc hơi nước dùng để rửa hộp phải đảm bảo đủ áp lực và nhiệt độ cần thiết, nhằm đảm bảo hiệu quả làm sạch và khử vi sinh.",1);
  add(5,"Trong quy trình ghép mí hộp, máy ghép mí phải được điều chỉnh trước mỗi ca để:",["Giảm tốc độ sản xuất nhằm tiết kiệm năng lượng.", "Đảm bảo kích thước mí hộp nằm trong giới hạn an toàn.", "Tăng độ dày của mí hộp để tăng độ bền.", "Giảm tần suất kiểm tra bằng mắt thường."],1,"Theo mục 2.7.2, máy ghép mí phải được điều chỉnh trước mỗi ca và trong quá trình sản xuất để đảm bảo kích thước mí hộp nằm trong giới hạn an toàn.",1);
  add(5,"Tần suất kiểm tra mí hộp bằng mắt thường là:",["Mỗi 5 phút một lần.", "Mỗi 15 phút một lần.", "Mỗi 30 phút một lần.", "Mỗi 60 phút một lần."],1,"Mục 2.6.3 (a) quy định kiểm tra mí hộp bằng mắt thường với tần suất 15 phút một lần.",1);
  add(5,"Khi sử dụng máy ghép mí chân không, độ chân không tối thiểu phải đạt:",["150 mmHg", "200 mmHg", "250 mmHg", "300 mmHg"],2,"Điều 2.6.2 quy định độ chân không tối thiểu của thiết bị ghép mí chân không phải đạt 250 mmHg.",1);
  add(5,"Thiết bị thanh trùng phải được hiệu chuẩn ít nhất bao nhiêu lần trong một năm?",["Mỗi tháng một lần.", "Mỗi 3 tháng một lần.", "Mỗi 6 tháng một lần.", "Mỗi năm một lần."],1,"Mục 2.9.3 nêu rằng nhiệt kế và đồng hồ đo áp suất của thiết bị thanh trùng phải được hiệu chuẩn ít nhất 3 tháng 1 lần, tức là 4 lần/năm.",1);
  add(5,"Theo quy chuẩn, thời gian tối đa từ khi hộp được ghép mí đến khi đưa vào nồi thanh trùng không được vượt quá:",["30 phút", "1 giờ", "2 giờ", "3 giờ"],2,"Điều 2.9.1 quy định năng suất nồi thanh trùng phải phù hợp sao cho thời gian từ ghép mí đến khi đưa vào thanh trùng không quá 2 giờ.",1);
  add(5,"Khi làm nguội đồ hộp sau thanh trùng, nhiệt độ trung tâm của sản phẩm phải giảm xuống dưới mức nào?",["30 °C", "40 °C", "45 °C", "50 °C"],1,"Mục 2.10.1 yêu cầu sau khi thanh trùng, đồ hộp phải được làm nguội nhanh cho đến khi nhiệt độ sản phẩm ở tâm hộp xuống dưới 40 °C (104 °F).",1);
  add(5,"Nếu nước làm nguội được sử dụng trong thùng chứa riêng, quy định nào sau đây là đúng?",["Nước có thể tái sử dụng cho nhiều lô đồ hộp nếu được lọc lại.", "Nước chỉ được sử dụng một lần và phải thay mới cho lô tiếp theo.", "Nước phải được đun sôi trước khi tái sử dụng.", "Nước có thể được pha loãng bằng nước lạnh để tăng thể tích."],1,"Theo mục 2.10.3, nếu làm nguội trong thùng chứa nước riêng, nước làm nguội chỉ được sử dụng cho 1 lần và phải được thay khi tiến hành làm nguội lô đồ hộp tiếp theo.",2);
  add(5,"Trong kho bảo ôn, các yêu cầu sau không đúng là:",["Kho phải kín, đủ ánh sáng và đủ rộng để chứa toàn bộ sản phẩm.", "Các kệ phải được lót giấy hoặc vải trước khi xếp hộp.", "Mỗi lô đồ hộp không cần có thẻ hoặc bảng ghi để tránh nhầm lẫn.", "Kho phải có hệ thống thông gió để duy trì độ ẩm phù hợp."],2,"Mục 2.11.3 quy định các lô đồ hộp xếp trong kho phải có thẻ, bảng ghi hoặc các phương tiện đánh dấu phù hợp để tránh nhầm lẫn; do đó lựa chọn C là không đúng.",2);
  add(5,"Một nhà máy phát hiện mí hộp có khuyết tật trong quá trình kiểm tra. Hành động tiếp theo phải là:",["Tiếp tục chạy máy và ghi lại khuyết tật để xử lý sau.", "Dừng máy, tiến hành kiểm tra và hiệu chỉnh máy ngay lập tức.", "Bỏ qua khuyết tật nếu tỷ lệ khuyết tật dưới 1%.", "Chỉ ghi lại khuyết tật trong báo cáo ngày cuối cùng."],1,"Theo mục 2.6.3 (c), nếu phát hiện mí hộp có khuyết tật, phải dừng máy, tiến hành kiểm tra và hiệu chỉnh máy ngay lập tức để ngăn ngừa sản phẩm không đạt tiêu chuẩn.",3);
  add(5,"Theo quy chuẩn QCVN, khi nào hộp đồ hộp thủy sản được phép dán nhãn?",["Sau khi hoàn thành quá trình bảo ôn và kiểm tra đạt yêu cầu", "Ngay khi hộp được sản xuất xong", "Sau khi đóng gói và vận chuyển tới kho", "Khi khách hàng yêu cầu"],0,"Điều 2.12.2 quy định: \"Đồ hộp hết thời kỳ bảo ôn, kiểm tra đạt yêu cầu mới được tiến hành dán nhãn.\"",1);
  add(5,"Yêu cầu về keo dán nhãn và mực in nhãn trong quy chuẩn là:",["Phải không ảnh hưởng tới chất lượng vỏ hộp", "Phải có màu xanh để dễ nhận biết", "Phải được sản xuất trong nước", "Phải có khả năng chịu nhiệt trên 120°C"],0,"Theo khoản 2.12.3: \"Keo dán nhãn, mực in nhãn không ảnh hưởng tới chất lượng vỏ hộp.\"",1);
  add(5,"Trong kho bảo quản thành phẩm đồ hộp thủy sản, yếu tố nào sau đây KHÔNG phải được đảm bảo?",["Kho phải thoáng mát, khô ráo", "Có giá, kệ chắc chắn để xếp sản phẩm", "Có hệ thống chiếu sáng mạnh 24/24h", "Ngăn chặn côn trùng và loài gặm nhấm"],2,"Điều 2.13.1 nêu rõ các yêu cầu: vệ sinh, thoáng mát, khô ráo, ngăn côn trùng, kệ chắc chắn. Không yêu cầu chiếu sáng mạnh liên tục.",1);
  add(5,"Đối với kho bảo quản sản phẩm thanh trùng Paxtơ, quy chuẩn yêu cầu:",["Kho phải được cách nhiệt tốt và trang bị máy lạnh đủ công suất", "Kho phải có hệ thống sấy khô tự động", "Kho phải duy trì nhiệt độ trên 30°C", "Kho không cần thiết bị đo nhiệt độ"],0,"Khoản 2.13.3 quy định: \"Kho bảo quản phải được cách nhiệt tốt và được trang bị máy lạnh đủ công suất, để bảo đảm nhiệt độ của toàn sản phẩm đạt hoặc thấp hơn nhiệt độ bảo quản theo quy định.\"",2);
  add(5,"Khi thực hiện kiểm tra thành phẩm đồ hộp, mẫu phải được lưu giữ ở nhiệt độ và thời gian nào?",["37°C trong 10 ngày", "4°C trong 5 ngày", "25°C trong 7 ngày", "45°C trong 3 ngày"],0,"Điều 2.14.2 quy định: \"Đồ hộp mẫu phải được lưu giữ ở nhiệt độ và thời gian quy định (37°C, 10 ngày) và tiến hành kiểm tra các vi khuẩn chịu nhiệt.\"",2);
  add(5,"Theo quy chuẩn, hồ sơ kiểm soát chất lượng phải được lưu giữ ít nhất trong thời gian:",["Bằng hoặc dài hơn hạn sử dụng của sản phẩm", "12 tháng kể từ ngày sản xuất", "6 tháng kể từ ngày xuất kho", "3 năm kể từ ngày kiểm tra cuối cùng"],0,"Khoản 2.15.1 nêu: \"Thời gian lưu giữ ít nhất bằng hạn sử dụng của sản phẩm.\"",2);
  add(5,"Ai là cơ quan chịu trách nhiệm chứng nhận hợp quy cho cơ sở sản xuất đồ hộp thủy sản?",["Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Y tế", "Cục An toàn Thực phẩm", "Sở Thủy sản địa phương"],0,"Điều 3.1.2: \"Tổ chức chứng nhận sự phù hợp được Bộ Nông nghiệp và Phát triển nông thôn chỉ định tiến hành chứng nhận hợp quy cơ sở Sản xuất đồ hộp thủy sản.\"",1);
  add(5,"Khi một lô đồ hộp chưa hoàn thành việc kiểm tra mẫu lưu giữ, hành động nào sau đây là sai?",["Đưa lô đồ hộp ra thị trường tiêu thụ", "Tiếp tục lưu giữ mẫu cho đến khi kiểm tra xong", "Ghi lại kết quả kiểm tra tạm thời", "Thông báo cho cơ quan quản lý nếu phát hiện bất thường"],0,"Theo khoản 2.14.2, \"Lô đồ hộp không được đưa ra thị trường tiêu thụ khi việc kiểm tra mẫu lưu giữ chưa kết thúc.\"",3);
  add(5,"Trong trường hợp có sự thay đổi, bổ sung quy chuẩn kỹ thuật, cơ sở sản xuất phải:",["Thực hiện theo văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành", "Tiếp tục áp dụng quy chuẩn cũ cho đến khi có thông báo riêng", "Chỉ áp dụng nếu khách hàng yêu cầu", "Tự quyết định thời gian áp dụng"],0,"Khoản 3.4.3 quy định: \"Thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.\"",2);
  add(5,"Ai chịu trách nhiệm chính trong việc tuân thủ các quy định của Quy chuẩn kỹ thuật về ATVSTP trong sản xuất đồ hộp thủy sản?",["Chủ cơ sở sản xuất", "Nhân viên kiểm soát chất lượng", "Cơ quan quản lý nhà nước", "Nhà cung cấp nguyên liệu"],0,"Điều 3.4.1: \"Chủ cơ sở Sản xuất đồ hộp thủy sản có trách nhiệm tuân thủ các quy định của Quy chuẩn kỹ thuật nhằm đảm bảo vệ sinh an toàn thực phẩm.\"",1);
  add(3,"Theo QCVN 02-05: 2009/BNNPTNT, đối tượng nào sau đây KHÔNG thuộc phạm vi áp dụng của Quy chuẩn này?",["Cơ sở chế biến thủy sản khô dùng làm thực phẩm.", "Cơ sở chế biến thủy sản khô tẩm gia vị.", "Cơ sở chế biến thủy sản khô thủ công, quy mô hộ gia đình.", "Cơ sở chế biến thủy sản khô hun khói."],2,"Theo Khoản 1.2.2 của QCVN 02-05: 2009/BNNPTNT, Quy chuẩn này không áp dụng cho các cơ sở chế biến thủy sản khô thủ công, quy mô hộ gia đình và các cơ sở chế biến sản phẩm khô ăn liền.",1);
  add(3,"Trong Quy chuẩn QCVN 02-05: 2009/BNNPTNT, 'Khu vực ướt' được định nghĩa như thế nào?",["Khu vực tiến hành các công đoạn chế biến thủy sản bằng các thiết bị phơi, sấy.", "Khu vực tiếp nhận, phân loại, xử lý và chế biến các sản phẩm và bán thành phẩm thủy sản phải sử dụng nước hoặc nước đá.", "Khu vực bao gói và bảo quản sản phẩm cuối cùng.", "Khu vực chỉ dùng để ướp muối và tẩm gia vị sản phẩm."],1,"Theo Khoản 1.3.1 của QCVN 02-05: 2009/BNNPTNT, 'Khu vực ướt là khu vực tiếp nhận, phân loại, xử lý và chế biến các sản phẩm và bán thành phẩm thủy sản phải sử dụng nước hoặc nước đá'.",1);
  add(3,"Theo QCVN 02-05: 2009/BNNPTNT, cơ sở chế biến thủy sản khô phải tuân thủ những quy định chung về địa điểm, thiết bị, hệ thống xử lý chất thải, quản lý chất lượng, nhà vệ sinh, phương tiện làm vệ sinh và khử trùng, và công nhân chế biến của Quy chuẩn nào sau đây?",["QCVN 02-02: 2009/BNNPTNT về Cơ sở chế biến nước mắm.", "QCVN 02-01: 2009/BNNPTNT về Cơ sở chế biến thủy sản – Điều kiện chung đảm bảo an toàn thực phẩm.", "QCVN 02-03: 2009/BNNPTNT về Cơ sở chế biến thủy sản đông lạnh.", "QCVN 02-04: 2009/BNNPTNT về Cơ sở chế biến thủy sản đóng hộp."],1,"Theo mục 2 'Quy định về kỹ thuật' của QCVN 02-05: 2009/BNNPTNT, cơ sở chế biến thủy sản khô phải theo đúng những quy định chung đối với cơ sở chế biến thủy sản về các khía cạnh đã nêu của QCVN 02-01: 2009/BNNPTNT.",2);
  add(3,"Yêu cầu nào sau đây là BẮT BUỘC đối với nền nhà xưởng trong khu vực ướt của cơ sở chế biến thủy sản khô theo QCVN 02-05: 2009/BNNPTNT?",["Làm từ vật liệu cứng, bền, không độc, không ngấm nước, không đọng nước, không trơn và có rãnh thoát nước tốt.", "Có thể làm bằng đất nện hoặc vật liệu xốp để hút ẩm tốt.", "Được lát gạch men sáng màu để dễ quan sát.", "Chỉ cần đảm bảo không trơn trượt là đủ."],0,"Theo Khoản 2.1.2.b) của QCVN 02-05: 2009/BNNPTNT, nền nhà xưởng trong khu vực ướt phải làm từ vật liệu cứng, bền, không độc, không ngấm nước, không đọng nước, không trơn và có rãnh thoát nước tốt.",1);
  add(3,"Khi thiết kế khu vực phơi và sân phơi của cơ sở chế biến thủy sản khô, yêu cầu nào sau đây là quan trọng nhất để đảm bảo an toàn thực phẩm theo QCVN 02-05: 2009/BNNPTNT?",["Có mặt bằng đủ rộng, thoáng gió, không đọng nước và được làm bằng vật liệu bền, cứng, không độc, có độ nghiêng hợp lý để dễ thoát nước, dễ làm vệ sinh.", "Nằm gần khu vực dân cư để tiện vận chuyển sản phẩm.", "Có thể sử dụng vật liệu thấm nước để giữ ẩm cho sản phẩm.", "Không cần mái che vì sản phẩm cần phơi nắng trực tiếp."],0,"Theo Khoản 2.1.3.b) của QCVN 02-05: 2009/BNNPTNT, khu vực phơi và sân phơi phải có mặt bằng đủ rộng, thoáng gió không đọng nước; cách xa đường giao thông, xa mặt nước rộng: ao, hồ; không có bụi khói, khí thải hoặc nguồn ô nhiễm khác; mặt sân phơi phải được làm bằng vật liệu bền, cứng, không độc, có độ nghiêng hợp lý để dễ thoát nước, dễ làm vệ sinh. Phương án A bao gồm đầy đủ các yếu tố quan trọng nhất được quy định.",2);
  add(3,"Theo QCVN 02-05: 2009/BNNPTNT, vật liệu dùng để chế tạo thiết bị, dụng cụ trong khu vực ướt (như ướp muối, tẩm gia vị) phải đáp ứng yêu cầu nào?",["Làm bằng vật liệu bền, không độc, không gỉ, không ăn mòn và được phép dùng trong thực phẩm.", "Ưu tiên vật liệu có giá thành rẻ để giảm chi phí sản xuất.", "Có thể làm bằng gỗ tự nhiên để tăng tính truyền thống.", "Chỉ cần đảm bảo dễ vệ sinh là đủ, không cần quá quan trọng về vật liệu."],0,"Theo Khoản 2.2.1.a) của QCVN 02-05: 2009/BNNPTNT, thiết bị, dụng cụ để ướp muối, tẩm gia vị, sản phẩm phải làm bằng vật liệu bền, không độc, không gỉ, không ăn mòn, được phép dùng trong thực phẩm.",1);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản (Thông tư 47/2009/TT-BNNPTNT), giàn phơi sản phẩm thủy sản khô phải đặt cách mặt sân ít nhất bao nhiêu mét?",["0,3m", "0,5m", "0,8m", "1,0m"],1,"Theo Điều 2.2.2.a của Thông tư 47/2009/TT-BNNPTNT, giàn phơi phải đặt cách mặt sân ít nhất 0,5m.",1);
  add(3,"Vật liệu nào sau đây KHÔNG được phép sử dụng để làm giàn phơi sản phẩm thủy sản khô theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Tre", "Gỗ", "Lưới nilon", "Kim loại gỉ sét"],3,"Theo Điều 2.2.2.a của Thông tư 47/2009/TT-BNNPTNT, được phép dùng các loại vật liệu như tre, gỗ, lưới nilon để làm giàn phơi. Tuy nhiên, bề mặt tiếp xúc với sản phẩm phải được làm bằng vật liệu không gây độc. Kim loại gỉ sét không đáp ứng yêu cầu này và có thể gây độc hoặc nhiễm bẩn.",1);
  add(3,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, người làm việc tại khu vực khô phải thực hiện biện pháp vệ sinh cá nhân nào khi thao tác với bán thành phẩm và thành phẩm?",["Chỉ cần mặc quần áo bảo hộ sáng màu", "Chỉ cần đội mũ bảo hộ che kín tóc", "Phải đeo găng tay", "Phải đeo khẩu trang"],2,"Theo Điều 2.4.2 của Thông tư 47/2009/TT-BNNPTNT, người làm việc tại khu vực khô phải đeo găng tay khi thao tác với bán thành phẩm và thành phẩm.",1);
  add(3,"Yêu cầu nào sau đây là BẮT BUỘC đối với việc bảo quản vật liệu bao gói thủy sản khô theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Bảo quản cùng với thành phẩm để tiện sử dụng", "Bảo quản ở nơi riêng biệt, kín, khô ráo, chống được sự xâm nhập của côn trùng và động vật gây hại", "Có thể để vật liệu bao gói ngoài trời nếu có che chắn tạm thời", "Không cần quan tâm đến độ bền chắc của vật liệu bao gói"],1,"Theo Điều 2.5.1.b của Thông tư 47/2009/TT-BNNPTNT, vật liệu bao gói thủy sản khô phải được bảo quản ở nơi riêng biệt, kín, khô ráo, chống được sự xâm nhập của côn trùng và động vật gây hại.",1);
  add(3,"Một cơ sở sản xuất thủy sản khô đang vận chuyển sản phẩm của mình cùng với một lô phân bón hữu cơ để tiết kiệm chi phí. Hành động này có phù hợp với Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản không?",["Phù hợp, miễn là sản phẩm thủy sản khô được đóng gói cẩn thận", "Phù hợp, nếu phương tiện vận chuyển được vệ sinh sạch sẽ sau khi dỡ hàng", "Không phù hợp, vì không được bảo quản hoặc vận chuyển sản phẩm thủy sản khô cùng với các loại sản phẩm khác", "Phù hợp, nếu có sự đồng ý của khách hàng"],2,"Theo Điều 2.5.2.a của Thông tư 47/2009/TT-BNNPTNT, 'Không được bảo quản hoặc vận chuyển sản phẩm thủy sản khô cùng với các loại sản phẩm khác.' Việc vận chuyển cùng phân bón hữu cơ là không phù hợp vì có thể gây nhiễm chéo.",2);
  add(5,"Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, cơ sở chế biến thủy sản khô phải thực hiện chứng nhận hợp quy về điều kiện đảm bảo vệ sinh an toàn thực phẩm dựa trên quy định nào?",["Nghị định số 127/2007/NĐ-CP", "Quyết định số 24/2007/QĐ-KBKHCN", "Thông tư 47/2009/TT-BNNPTNT", "Luật An toàn thực phẩm"],1,"Theo Điều 3.1.1 của Thông tư 47/2009/TT-BNNPTNT, cơ sở chế biến thủy sản khô phải thực hiện chứng nhận hợp quy về điều kiện đảm bảo vệ sinh an toàn thực phẩm theo Quyết định số 24/2007/QĐ-KBKHCN ngày 28 tháng 9 năm 2007 về “Quy định về hoạt động chứng nhận hợp chuẩn, chứng nhận hợp quy, công bố hợp chuẩn, công bố hợp quy”.",1);
  add(5,"Sau khi được chứng nhận hợp quy, cơ sở chế biến thủy sản khô phải thực hiện thủ tục gì tiếp theo theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản?",["Gửi báo cáo định kỳ cho Bộ Nông nghiệp và Phát triển nông thôn", "Công bố hợp quy và gửi hồ sơ về cơ quan quản lý Nhà nước chuyên ngành", "Đăng ký lại giấy phép kinh doanh", "Chỉ cần lưu giữ giấy chứng nhận tại cơ sở"],1,"Theo Điều 3.2.1 của Thông tư 47/2009/TT-BNNPTNT, cơ sở chế biến thủy sản khô được chứng nhận hợp quy phải thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về cơ quan quản lý Nhà nước chuyên ngành do Bộ Nông nghiệp và Phát triển nông thôn chỉ định.",1);
  add(5,"Cơ quan nào có thẩm quyền thanh tra, kiểm tra định kỳ hoặc đột xuất đối với cơ sở chế biến thủy sản khô và Tổ chức chứng nhận hợp quy?",["Chỉ có Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý Nhà nước có thẩm quyền ở địa phương", "Chỉ có cơ quan quản lý Nhà nước có thẩm quyền ở địa phương", "Tổ chức chứng nhận hợp quy tự kiểm tra"],1,"Theo Điều 3.3.1 của Thông tư 47/2009/TT-BNNPTNT, Cơ sở chế biến thủy sản khô và Tổ chức chứng nhận chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất của Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý Nhà nước có thẩm quyền ở địa phương.",1);
  add(3,"Một cơ sở chế biến thủy sản khô đang sử dụng giàn phơi bằng tre, đặt cách mặt đất 0,3 mét. Theo Quy chuẩn kỹ thuật quốc gia về điều kiện ATVSTP trong sản xuất thủy sản, cơ sở này cần điều chỉnh gì để đảm bảo tuân thủ?",["Không cần điều chỉnh vì tre là vật liệu được phép sử dụng", "Nâng giàn phơi lên ít nhất 0,5 mét so với mặt sân", "Thay thế giàn phơi bằng vật liệu không gỉ", "Chỉ cần đảm bảo giàn phơi được vệ sinh sạch sẽ"],1,"Theo Điều 2.2.2.a của Thông tư 47/2009/TT-BNNPTNT, giàn phơi được phép làm bằng tre nhưng phải đặt cách mặt sân ít nhất 0,5m. Do đó, cơ sở cần nâng giàn phơi lên.",3);
  add(3,"Trong quá trình sản xuất thủy sản khô, việc kiểm tra, phân tích các chỉ tiêu nào là bắt buộc đối với sản phẩm theo quy định hiện hành?",["Chỉ tiêu cảm quan và hóa lý", "Chỉ tiêu vi sinh và hóa lý", "Chỉ tiêu cảm quan, hóa lý và vi sinh", "Chỉ tiêu độc tố và kim loại nặng"],2,"Theo Điều 2.3 của Thông tư 47/2009/TT-BNNPTNT, cơ sở 'Phải kiểm tra, phân tích các chỉ tiêu cảm quan, hóa lý, vi sinh bắt buộc đối với sản phẩm thủy sản khô theo quy định hiện hành'.",1);
  add(5,"Quy chuẩn QCVN 02-06:2009/BNNPTNT quy định áp dụng cho đối tượng nào?",["Cơ sở sản xuất nước mắm và cơ sở pha đấu, đóng chai nước mắm", "Cơ sở chế biến nước mắm quy mô hộ gia đình", "Nhà hàng, quán ăn phục vụ món nước mắm", "Cơ sở nhập khẩu nước mắm"],0,"Theo mục 1.2.1 của QCVN 02-06, quy chuẩn áp dụng cho cơ sở sản xuất nước mắm và cơ sở pha đấu, đóng chai nước mắm.",1);
  add(5,"Đối tượng nào không thuộc phạm vi áp dụng của QCVN 02-06?",["Cơ sở sản xuất nước mắm quy mô công nghiệp", "Cơ sở pha đấu, đóng chai nước mắm", "Cơ sở chế biến nước mắm quy mô hộ gia đình", "Cơ sở xuất khẩu nước mắm"],2,"Mục 1.2.2 nêu rõ quy chuẩn không áp dụng cho cơ sở chế biến nước mắm quy mô hộ gia đình.",1);
  add(5,"Về vị trí địa lý, cơ sở sản xuất nước mắm phải đáp ứng yêu cầu nào sau đây?",["Gần khu dân cư để thuận tiện giao hàng", "Xa khu dân cư, xa nguồn lây nhiễm và không ảnh hưởng tới môi trường xung quanh", "Nằm trong khu công nghiệp có nhiều nguồn nước", "Gần sông để lấy nước tự nhiên"],1,"Điều 2.1.1 quy định cơ sở phải được xây dựng ở vị trí thích hợp, xa khu dân cư, xa nguồn lây nhiễm, không ảnh hưởng tới vệ sinh môi trường.",2);
  add(5,"Yêu cầu về nguồn điện và nước sạch cho cơ sở sản xuất nước mắm được nêu ở mục nào?",["2.1.1", "2.1.2", "2.2.1", "2.2.4"],1,"Mục 2.1.2 quy định cơ sở phải được cung cấp đủ nguồn điện, nước sạch theo yêu cầu sản xuất.",2);
  add(5,"Tiêu chuẩn về mái nhà của nhà xưởng sản xuất nước mắm là:",["Mái nhà phải có màu sáng để phản xạ nhiệt", "Mái nhà phải ngăn được nước mưa và bụi bẩn từ phía trên rơi xuống", "Mái nhà có thể làm bằng tôn mỏng không cần lớp cách nhiệt", "Mái nhà được làm bằng vật liệu thấm nước để giữ ẩm"],1,"Theo mục 2.2.3(a), mái nhà phải ngăn được nước mưa, bụi bẩn từ phía trên rơi xuống.",2);
  add(5,"Về vật liệu tường trong nhà xưởng, yêu cầu nào sau đây là đúng?",["Tường phải được sơn màu tối để giảm nhiệt", "Tường phải làm bằng vật liệu phù hợp, dễ làm vệ sinh", "Tường có thể làm bằng gỗ thô không cần sơn", "Tường không cần chịu lực, chỉ cần thẩm mỹ"],1,"Mục 2.2.3(b) quy định bề mặt tường phải làm bằng vật liệu phù hợp, dễ làm vệ sinh.",2);
  add(5,"Điều kiện về nền nhà xưởng và sân phơi chượp bao gồm:",["Phải làm bằng gạch không có rãnh thoát nước", "Phải làm bằng vật liệu phù hợp, không đọng nước, không rạn nứt và có rãnh thoát nước", "Có thể dùng đất nông trại nếu bề mặt bằng", "Không yêu cầu đặc biệt vì sẽ được phủ lớp nhựa"],1,"Mục 2.2.3(c) yêu cầu nền nhà xưởng và sân phơi chượp phải làm bằng vật liệu phù hợp, không đọng nước, không rạn nứt và có rãnh thoát nước.",2);
  add(5,"Khu vực chứa phế thải sau khi nấu chượp phải được thiết kế như thế nào?",["Mở, không cần thông gió, để dễ dàng quan sát", "Kín, cách biệt, có thông gió riêng, dễ làm vệ sinh và khử trùng", "Đặt ngay cạnh khu vực chế biến để giảm khoảng cách vận chuyển", "Có thể dùng bể nước để ngập phế thải"],1,"Mục 2.2.6 quy định khu vực chứa phế thải phải kín, cách biệt, được thông gió riêng, dễ làm vệ sinh và khử trùng.",3);
  add(5,"Phòng thay quần áo bảo hộ lao động cho công nhân phải được bố trí theo quy định nào?",["Có thể đặt chung với phòng ăn", "Phải có riêng, đáp ứng quy định tại 2.1.11.3 của Thông tư 47/2009/TT-BNNPTNT", "Không bắt buộc nếu công nhân không mặc đồng phục", "Chỉ cần có tủ đựng áo"],1,"Mục 2.2.7 nêu phải có phòng thay quần áo bảo hộ lao động cho công nhân theo quy định tại 2.1.11.3 của Thông tư 47/2009.",2);
  add(5,"Theo QCVN 02-01:2009/BNNPTNT, cơ sở sản xuất thực phẩm thuỷ sản phải có khu vực vệ sinh cho công nhân dựa vào quy định nào?",["Điều 2.1.11.4", "Điều 2.2.5", "Điều 3.1.2", "Điều 4.3.1"],0,"Câu 2.2.8 nêu rằng phải có khu vực vệ sinh cho công nhân theo quy định tại 2.1.11.4 của QCVN 02-01:2009/BNNPTNT.",1);
  add(5,"Trong quy chuẩn, khu vực rửa và khử trùng tay phải:",["Được bố trí ở ngoài khu vực sản xuất", "Phù hợp với thực tế và luôn sẵn sàng sử dụng", "Chỉ cần có nước lạnh", "Không cần có dụng cụ rửa tay"],1,"Điều 2.2.9 quy định phải có khu vực rửa và khử trùng tay phù hợp với thực tế.",1);
  add(5,"Nguồn nước sạch dùng cho cơ sở sản xuất phải đáp ứng yêu cầu của cơ quan nào?",["Bộ Nông nghiệp", "Bộ Y tế", "Bộ Công Thương", "Bộ Môi trường"],1,"Điều 2.3.1 yêu cầu nguồn nước sạch phải đáp ứng đúng yêu cầu quy định của Bộ Y tế.",1);
  add(5,"Theo QCVN, các thiết bị cung cấp nước sạch (đường ống, bể chứa) phải đáp ứng các tiêu chí sau, ngoại trừ:",["Thiết kế phù hợp, không rò rỉ", "Không độc hại, dễ làm vệ sinh", "Phải được làm bằng thép không gỉ", "Phải được đậy kín"],2,"Điều 2.3.2 liệt kê ba tiêu chí: thiết kế phù hợp, không rò rỉ; không độc hại, dễ làm vệ sinh; và phải được đậy kín. Không yêu cầu vật liệu phải là thép không gỉ.",2);
  add(5,"Trước khi xả ra môi trường, nước thải phải:",["Được lọc qua cát", "Được xử lý để không ảnh hưởng môi trường", "Chỉ cần giảm mùi", "Được pha loãng với nước sạch"],1,"Điều 2.3.5 quy định nước thải trước khi xả ra phải được xử lý đảm bảo không ảnh hưởng môi trường xung quanh.",1);
  add(5,"Ánh sáng trong khu vực sản xuất và đóng gói phải đáp ứng yêu cầu:",["Chỉ dùng ánh sáng tự nhiên", "Cường độ đủ để thực hiện các hoạt động sản xuất kinh doanh", "Phải có độ sáng tối thiểu 500 lux", "Phải có đèn LED màu xanh"],1,"Điều 2.4.1 yêu cầu sử dụng ánh sáng tự nhiên hoặc nhân tạo với cường độ đủ để thực hiện các hoạt động sản xuất kinh doanh.",1);
  add(5,"Thiết bị, dụng cụ tiếp xúc trực tiếp với chượp và nước mắm phải:",["Làm bằng nhựa PVC", "Làm bằng vật liệu bền, không độc, không gỉ, không ảnh hưởng tới chất lượng nước mắm", "Có thể làm bằng gỗ nếu được sơn phủ", "Chỉ cần có khả năng chịu muối"],1,"Điều 2.5.1 quy định thiết bị, dụng cụ phải làm bằng vật liệu bền, không độc, không gỉ, không ảnh hưởng tới chất lượng nước mắm và chịu được tác động của muối.",2);
  add(5,"Nguyên liệu cá dùng để sản xuất nước mắm phải đáp ứng tiêu chuẩn nào?",["TCVN 3521-79 về cá biển ướp muối làm chượp", "TCVN 4500-91 về cá tươi", "TCVN 3521-79 về cá ngọt", "TCVN 5000-00 về cá đóng hộp"],0,"Điều 2.6.1 b) quy định cá dùng để sản xuất nước mắm phải là loại cá đạt tiêu chuẩn của cá biển ướp muối làm chượp theo TCVN 3521-79.",1);
  add(5,"Về chất tẩy rửa và khử trùng, quy chuẩn cấm sử dụng loại hoá chất nào trong khu vực sản xuất?",["Thuốc khử trùng có nồng độ cao", "Hoá chất diệt động vật (chuột…) ", "Nước oxy già", "Dầu gội đầu"],1,"Điều 2.6.4 b) cấm sử dụng hoá chất diệt động vật (chuột…) trong khu vực sản xuất, chứa sản phẩm và đóng gói.",1);
  add(5,"Một nhà máy sản xuất nước mắm đang sử dụng ống dẫn nước bằng thép carbon chưa được sơn phủ, dẫn tới hiện tượng rỉ sét và vết bẩn trên bề mặt ống. Vi phạm quy chuẩn nào?",["Điều 2.3.2 về thiết bị cung cấp nước sạch", "Điều 2.5.1 về vật liệu thiết bị tiếp xúc trực tiếp", "Điều 2.4.2 về đèn chiếu sáng", "Điều 2.7.1 về kế hoạch vệ sinh"],0,"Ống dẫn nước là một phần của hệ thống cấp nước. Điều 2.3.2 yêu cầu các thiết bị cung cấp nước sạch (đường ống, bể chứa) phải không rò rỉ, không độc hại, dễ làm vệ sinh và phải được đậy kín. Sử dụng ống thép carbon chưa sơn gây rỉ và không đáp ứng tiêu chí \"không độc, không gỉ, dễ làm vệ sinh\" nên vi phạm Điều 2.3.2.",3);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, cán bộ, công nhân tham gia sản xuất nước mắm phải đảm bảo điều kiện vệ sinh cá nhân nào?",["Chỉ cần không mắc các bệnh truyền nhiễm.", "Đảm bảo vệ sinh cá nhân, không mắc các bệnh truyền nhiễm và định kỳ kiểm tra sức khoẻ hàng năm.", "Chỉ cần định kỳ kiểm tra sức khoẻ hàng năm.", "Đảm bảo vệ sinh cá nhân và chỉ kiểm tra sức khỏe khi có dấu hiệu bệnh."],1,"Điều 2.7.1.d của Thông tư 47/2009/TT-BNNPTNT quy định: 'Cán bộ, công nhân khi tham gia vào sản xuất phải đảm bảo vệ sinh cá nhân, không mắc các bệnh truyền nhiễm và định kỳ kiểm tra sức khoẻ hàng năm.'",1);
  add(3,"Yêu cầu nào sau đây KHÔNG đúng đối với bao bì chứa nước mắm theo Thông tư 47/2009/TT-BNNPTNT?",["Phải bền chắc và không độc.", "Phải có mặt nhẵn và không bị ăn mòn.", "Phải làm từ vật liệu có thể tái chế dễ dàng.", "Không được làm ảnh hưởng đến chất lượng nước mắm."],2,"Khoản 2.8.1 của Thông tư 47/2009/TT-BNNPTNT quy định bao bì chứa nước mắm phải bền chắc, không độc, không gỉ, mặt nhẵn, không bị ăn mòn, không làm ảnh hưởng đến chất lượng nước mắm. Không có quy định về việc phải làm từ vật liệu có thể tái chế dễ dàng.",1);
  add(3,"Theo Thông tư 47/2009/TT-BNNPTNT, bao bì chứa nước mắm phải được bảo quản ở đâu?",["Nơi khô ráo, sạch sẽ, nhưng có thể chung với khu vực sản xuất.", "Nơi riêng biệt, thoáng, khô ráo, sạch sẽ và an toàn.", "Nơi thoáng mát, có thể tiếp xúc trực tiếp với ánh nắng mặt trời.", "Nơi ẩm ướt để tránh khô cứng vật liệu bao bì."],1,"Khoản 2.8.1 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Bao bì được bảo quản ở nơi riêng biệt, thoáng, khô ráo, sạch sẽ và an toàn.'",1);
  add(3,"Việc ghi nhãn nước mắm phải tuân thủ theo quy định tại văn bản pháp luật nào?",["Nghị định 15/2018/NĐ-CP.", "Nghị định 89/2006/NĐ-CP ngày 30/8/2006.", "Thông tư 01/2013/TT-BNNPTNT.", "Quyết định 24/2007/QĐ-BKHCN."],1,"Khoản 2.8.2 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Việc ghi nhãn nước mắm phải theo quy định tại Nghị định 89/2006/NĐ-CP ngày 30/8/2006.'",1);
  add(3,"Điều kiện nào sau đây là bắt buộc đối với kho bảo quản nước mắm theo Thông tư 47/2009/TT-BNNPTNT?",["Chỉ cần sạch sẽ và thoáng mát.", "Phải có đủ giá, bục để kê xếp sản phẩm và ngăn chặn được côn trùng, động vật xâm nhập.", "Có thể để sản phẩm trực tiếp trên nền đất nếu nền khô ráo.", "Không yêu cầu ngăn chặn côn trùng nếu sản phẩm đã được đóng gói kín."],1,"Khoản 2.8.3 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Kho bảo quản nước mắm phải sạch sẽ, thoáng mát; có đủ giá, bục để kê xếp sản phẩm; ngăn chặn được côn trùng và động vật xâm nhập.'",1);
  add(3,"Yêu cầu đối với phương tiện vận chuyển nước mắm theo Thông tư 47/2009/TT-BNNPTNT là gì?",["Chỉ cần sạch sẽ và hợp vệ sinh.", "Phải sạch sẽ, hợp vệ sinh và có thiết bị che mưa, nắng.", "Có thể vận chuyển chung với các loại hàng hóa khác không liên quan.", "Chỉ cần đảm bảo không rò rỉ nước mắm ra ngoài."],1,"Khoản 2.8.4 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Phương tiện vận chuyển nước mắm phải sạch sẽ, hợp vệ sinh, có thiết bị che mưa, nắng.'",1);
  add(3,"Một cơ sở sản xuất nước mắm có công suất thực tế 600.000 lít/năm phải thực hiện chương trình quản lý chất lượng nào theo Thông tư 47/2009/TT-BNNPTNT?",["Quy phạm thực hành sản xuất tốt (GMP) và quy phạm vệ sinh chuẩn (SSOP).", "Chương trình quản lý chất lượng và an toàn thực phẩm theo HACCP.", "Chỉ cần truy xuất nguồn gốc.", "Không cần chương trình quản lý chất lượng cụ thể nào."],1,"Khoản 2.9.1 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Cơ sở có công suất thực tế 500.000 lít/năm trở lên: Hoạt động sản xuất của cơ sở phải thực hiện đúng chương trình quản lý chất lượng và an toàn thực phẩm theo HACCP quy định tại QCVN 02-02: 2009/BNNPTNT...'",2);
  add(3,"Một cơ sở sản xuất nước mắm có công suất thực tế 400.000 lít/năm phải thực hiện các quy phạm nào theo Thông tư 47/2009/TT-BNNPTNT?",["Chương trình quản lý chất lượng và an toàn thực phẩm theo HACCP.", "Quy phạm thực hành sản xuất tốt (GMP), quy phạm vệ sinh chuẩn (SSOP) và truy xuất nguồn gốc.", "Chỉ cần GMP.", "Chỉ cần SSOP và truy xuất nguồn gốc."],1,"Khoản 2.9.2 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Cơ sở có công suất thực tế nhỏ hơn 500.000 lít/năm: Hoạt động sản xuất của cơ sở phải thực hiện đúng quy phạm thực hành sản xuất tốt (GMP), quy phạm vệ sinh chuẩn (SSOP) và truy xuất nguồn gốc.'",2);
  add(3,"Thời gian tối thiểu để lưu giữ bộ hồ sơ về quản lý vệ sinh an toàn thực phẩm của cơ sở sản xuất nước mắm là bao lâu?",["1 năm.", "2 năm.", "3 năm.", "5 năm."],1,"Khoản 2.9.3 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Thời gian lưu giữ hồ sơ ít nhất là 2 năm.'",1);
  add(5,"Cơ sở sản xuất nước mắm phải thực hiện chứng nhận hợp quy về điều kiện đảm bảo vệ sinh an toàn thực phẩm theo văn bản nào?",["Nghị định 89/2006/NĐ-CP.", "Quyết định số 24/2007/QĐ-BKHCN ngày 28 tháng 9 năm 2007.", "Nghị định số 127/2007/NĐ-CP.", "QCVN 02-02:2009/BNNPTNT."],1,"Khoản 3.1.1 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Cơ sở sản xuất nước mắm phải thực hiện chứng nhận hợp quy về điều kiện đảm bảo vệ sinh an toàn thực phẩm theo Quyết định số 24/2007/QĐ-BKHCN ngày 28 tháng 9 năm 2007 về “Quy định về hoạt động chứng nhận hợp chuẩn, chứng nhận hợp quy, công bố hợp chuẩn, công bố hợp quy”.'",1);
  add(5,"Tổ chức chứng nhận sự phù hợp được thành lập và hoạt động theo văn bản pháp luật nào?",["Quyết định số 24/2007/QĐ-BKHCN.", "Luật Tiêu chuẩn và Quy chuẩn kỹ thuật.", "Nghị định số 127/2007/NĐ-CP ngày 01/8/2007.", "Thông tư 47/2009/TT-BNNPTNT."],2,"Khoản 3.1.2 của Thông tư 47/2009/TT-BNNPTNT quy định: 'Tổ chức chứng nhận sự phù hợp được thành lập và hoạt động theo Nghị định số 127/2007/NĐ-CP ngày 01/8/2007 về “Quy định chi tiết thi hành một số điều của Luật Tiêu chuẩn và Quy chuẩn kỹ thuật”.'",1);
  add(3,"Phương thức đánh giá, chứng nhận cơ sở sản xuất nước mắm hợp quy được thực hiện theo hướng dẫn của cơ quan nào?",["Bộ Y tế", "Bộ Công Thương", "Bộ Nông nghiệp và Phát triển nông thôn", "Ủy ban nhân dân cấp tỉnh"],2,"Theo Khoản 3.1.3 của Quy chuẩn kỹ thuật, phương thức đánh giá, chứng nhận cơ sở sản xuất nước mắm hợp quy thực hiện theo hướng dẫn của Bộ Nông nghiệp và Phát triển nông thôn.",1);
  add(3,"Sau khi được chứng nhận hợp quy, cơ sở sản xuất nước mắm phải thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về đâu?",["Bộ Y tế", "Cơ quan quản lý nhà nước chuyên ngành do Bộ Nông nghiệp và Phát triển nông thôn chỉ định", "Sở Nông nghiệp và Phát triển nông thôn địa phương", "Tổ chức chứng nhận đã cấp chứng nhận hợp quy"],1,"Theo Khoản 3.2.1 của Quy chuẩn kỹ thuật, cơ sở sản xuất nước mắm được chứng nhận hợp quy phải thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành do Bộ Nông nghiệp và Phát triển nông thôn chỉ định.",1);
  add(3,"Việc công bố hợp quy đối với cơ sở sản xuất nước mắm thực hiện theo quy định tại văn bản nào?",["Điều 14 Nghị định số 127/2007/NĐ-CP ngày 01/8/2007", "Điều 15 Nghị định số 127/2007/NĐ-CP ngày 01/8/2007", "Điều 14 Thông tư 47/2009/TT-BNNPTNT", "Điều 15 Thông tư 47/2009/TT-BNNPTNT"],0,"Theo Khoản 3.2.2 của Quy chuẩn kỹ thuật, việc công bố hợp quy thực hiện theo quy định tại Điều 14 Nghị định số 127/2007/NĐ-CP ngày 01/8/2007.",1);
  add(3,"Đối tượng nào chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất về điều kiện vệ sinh an toàn thực phẩm trong sản xuất nước mắm?",["Chỉ cơ sở sản xuất nước mắm", "Chỉ Tổ chức chứng nhận", "Cơ sở sản xuất nước mắm và Tổ chức chứng nhận", "Chỉ Bộ Nông nghiệp và Phát triển nông thôn"],2,"Theo Khoản 3.3.1 của Quy chuẩn kỹ thuật, cơ sở sản xuất nước mắm và Tổ chức chứng nhận chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất của Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương.",1);
  add(3,"Cơ quan nào có thẩm quyền thực hiện thanh tra, kiểm tra định kỳ hoặc đột xuất đối với cơ sở sản xuất nước mắm và Tổ chức chứng nhận?",["Bộ Nông nghiệp và Phát triển nông thôn", "Cơ quan quản lý nhà nước có thẩm quyền ở địa phương", "Cả Bộ Nông nghiệp và Phát triển nông thôn và cơ quan quản lý nhà nước có thẩm quyền ở địa phương", "Bộ Y tế"],2,"Theo Khoản 3.3.1 của Quy chuẩn kỹ thuật, cơ sở sản xuất nước mắm và Tổ chức chứng nhận chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất của Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương.",1);
  add(3,"Trách nhiệm chính của chủ cơ sở sản xuất nước mắm theo Quy chuẩn kỹ thuật này là gì?",["Phổ biến Quy chuẩn cho người lao động.", "Tuân thủ các quy định của Quy chuẩn kỹ thuật nhằm đảm bảo vệ sinh an toàn thực phẩm.", "Báo cáo định kỳ về Bộ Nông nghiệp và Phát triển nông thôn.", "Đăng ký lại chứng nhận hợp quy hàng năm."],1,"Theo Khoản 3.4.1 của Quy chuẩn kỹ thuật, chủ cơ sở sản xuất nước mắm có trách nhiệm tuân thủ các quy định của Quy chuẩn kỹ thuật nhằm đảm bảo vệ sinh an toàn thực phẩm.",1);
  add(3,"Trong trường hợp các quy định tại Quy chuẩn kỹ thuật này có sự thay đổi, bổ sung hoặc thay thế, việc thực hiện sẽ theo quy định của văn bản nào?",["Văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.", "Văn bản mới do Bộ Y tế ký ban hành.", "Văn bản mới do Thủ tướng Chính phủ ký ban hành.", "Các quy định hiện hành của Quy chuẩn này cho đến khi có văn bản hướng dẫn chi tiết."],0,"Theo Khoản 3.4.3 của Quy chuẩn kỹ thuật, trong trường hợp các quy định tại Quy chuẩn này có sự thay đổi, bổ sung hoặc thay thế thì thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.",1);
  add(3,"Đơn vị nào chịu trách nhiệm biên soạn QCVN 02-07: 2009/BNNPTNT?",["Bộ Nông nghiệp và Phát triển nông thôn", "Cục Quản lý Chất lượng Nông lâm sản và Thủy sản", "Vụ Khoa học Công nghệ và Môi trường", "Cục Thú y"],1,"Theo Lời nói đầu của QCVN 02-07: 2009/BNNPTNT, Quy chuẩn này do Cục Quản lý Chất lượng Nông lâm sản và Thủy sản biên soạn.",1);
  add(3,"QCVN 02-07: 2009/BNNPTNT quy định điều kiện đảm bảo vệ sinh an toàn thực phẩm cho loại nhuyễn thể hai mảnh vỏ nào sau đây?",["Chỉ các loài hầu và ngao.", "Các loài nhuyễn thể thuộc họ hầu, ngao, vẹm và sò.", "Chỉ các loài vẹm và sò.", "Tất cả các loài nhuyễn thể có thể ăn nguyên con."],1,"Khoản 1.1 Phạm vi điều chỉnh nêu rõ Quy chuẩn này quy định những điều kiện đảm bảo vệ sinh an toàn thực phẩm trong sản xuất các loài nhuyễn thể, lớp hai mảnh vỏ thuộc các họ: hầu (Ostreidae), ngao (Veneridae, Mactridae, Tridacnidae và Lucinidae), vẹm (Mytilidae) và sò (Arcidae).",1);
  add(3,"Đối tượng áp dụng của QCVN 02-07: 2009/BNNPTNT là gì?",["Các hộ gia đình nuôi nhuyễn thể hai mảnh vỏ.", "Các cơ sở làm sạch và chế biến nhuyễn thể hai mảnh vỏ dùng làm thực phẩm.", "Các nhà hàng, quán ăn kinh doanh nhuyễn thể hai mảnh vỏ.", "Các đơn vị kiểm tra, giám sát chất lượng nhuyễn thể hai mảnh vỏ."],1,"Khoản 1.2 Đối tượng áp dụng quy định Quy chuẩn này áp dụng cho các cơ sở làm sạch và chế biến nhuyễn thể hai mảnh vỏ dùng làm thực phẩm.",1);
  add(3,"Theo QCVN 02-07: 2009/BNNPTNT, \"Nước biển sạch\" được định nghĩa như thế nào?",["Nước biển không chứa bất kỳ chất gây ô nhiễm nào.", "Nước biển hay nước cửa sông không chứa tảo biển và các chất gây ô nhiễm ở mức có tác động xấu đến chất lượng và an toàn của nhuyễn thể hai mảnh vỏ.", "Nước biển đã qua xử lý hóa học để loại bỏ vi khuẩn.", "Nước biển có độ mặn tiêu chuẩn và không có mùi lạ."],1,"Khoản 1.3.1 Giải thích từ ngữ định nghĩa Nước biển sạch là nước biển hay nước cửa sông không chứa tảo biển và các chất gây ô nhiễm ở mức có tác động xấu đến chất lượng và an toàn của nhuyễn thể hai mảnh vỏ.",1);
  add(3,"Quá trình \"Làm sạch\" nhuyễn thể hai mảnh vỏ theo Quy chuẩn này yêu cầu điều kiện nào sau đây?",["Lưu giữ nhuyễn thể trong nước ngọt pha loãng để chúng nhả cát.", "Lưu giữ sống nhuyễn thể trong nước biển hoặc nước muối pha loãng có nồng độ muối tương đương với vùng thu hoạch, đủ thời gian để nhả hết cát, bùn và chất bẩn.", "Ngâm nhuyễn thể trong dung dịch khử trùng để loại bỏ vi khuẩn.", "Rửa sạch nhuyễn thể bằng vòi nước áp lực cao."],1,"Khoản 1.3.3 Giải thích từ ngữ định nghĩa Làm sạch là quá trình lưu giữ sống nhuyễn thể hai mảnh vỏ trong nước biển hoặc nước muối pha loãng có nồng độ muối tương đương với nồng độ muối trong nước biển tại vùng thu hoạch nhuyễn thể hai mảnh vỏ đó, trong khoảng thời gian đủ để chúng nhả hết cát, bùn và các chất bẩn khác để đạt tiêu chuẩn dùng chế biến thực phẩm.",2);
  add(3,"Theo QCVN 02-07: 2009/BNNPTNT, nhuyễn thể hai mảnh vỏ chỉ được phép thu hoạch ở những vùng nước như thế nào?",["Bất kỳ vùng nước nào có nhuyễn thể phân bố tự nhiên.", "Những vùng nước nuôi hoặc có nhuyễn thể phân bố tự nhiên đã được kiểm soát và được phép thu hoạch.", "Các vùng nước ven biển có độ sâu dưới 10 mét.", "Các vùng nước được cấp phép khai thác thủy sản."],1,"Khoản 2.1 Thu hoạch nhuyễn thể hai mảnh vỏ quy định nhuyễn thể hai mảnh vỏ chỉ được phép thu hoạch ở những vùng nước nuôi hoặc có nhuyễn thể hai mảnh vỏ phân bố tự nhiên đã được kiểm soát và được phép thu hoạch.",1);
  add(3,"Điều kiện nào sau đây KHÔNG phải là yêu cầu đối với việc bố trí khu vực làm sạch nhuyễn thể hai mảnh vỏ?",["Có hệ thống cấp điện, nước sạch hay nước biển sạch đáp ứng đủ.", "Không bị ảnh hưởng của mùi hôi thối, khói, bụi bẩn và các nguồn gây ô nhiễm khác.", "Phải nằm gần khu dân cư đông đúc để tiện cho việc vận chuyển.", "Không bị ngập nước khi trời mưa hoặc khi thủy triều dâng cao."],2,"Khoản 2.2.1.1 Khu vực làm sạch nhuyễn thể hai mảnh vỏ quy định khu vực này phải được bố trí ở nơi có đường giao thông thuận tiện; có hệ thống cấp điện, nước sạch hay nước biển sạch đáp ứng đủ cho yêu cầu sản xuất; không bị ảnh hưởng của mùi hôi thối, khói, bụi bẩn và các nguồn gây ô nhiễm khác; không bị ngập nước khi trời mưa hoặc khi thuỷ triều dâng cao. Việc nằm gần khu dân cư đông đúc không phải là yêu cầu, thậm chí có thể gây ra các nguồn ô nhiễm.",2);
  add(3,"Về cấu trúc xây dựng, khu vực làm sạch nhuyễn thể hai mảnh vỏ phải đáp ứng yêu cầu nào?",["Tường và nền được làm bằng vật liệu thấm nước, dễ dàng thay thế.", "Phải bố trí liền kề với các khu xử lý khác để tối ưu hóa không gian.", "Tường và nền được làm bằng vật liệu bền, không thấm nước, dễ làm vệ sinh; nền bảo đảm thoát nước tốt và được bảo trì thường xuyên.", "Có thể không cần mái che nếu thời tiết khô ráo."],2,"Khoản 2.2.1.2 quy định khu vực làm sạch phải bố trí cách biệt với các khu xử lý khác và được xây dựng chắc chắn, có mái che. Tường và nền được làm bằng vật liệu bền, không thấm nước, dễ làm vệ sinh. Nền bảo đảm thoát nước tốt và được bảo trì thường xuyên.",2);
  add(3,"Trong quá trình ngâm nhả cát tại cơ sở làm sạch nhuyễn thể hai mảnh vỏ, một công nhân đặt các khay chứa nhuyễn thể trực tiếp xuống đáy bể. Hành động này có tuân thủ Quy chuẩn không?",["Tuân thủ, miễn là bể đã được vệ sinh sạch sẽ.", "Không tuân thủ, vì nhuyễn thể phải được đặt cách đáy bể ít nhất 8-10 cm để ngăn cách với cát, bùn và nhớt.", "Tuân thủ, nếu công nhân đảm bảo thay nước thường xuyên.", "Không tuân thủ, vì nhuyễn thể không được đặt trong khay mà phải ngâm trực tiếp."],1,"Khoản 2.2.1.4 quy định: \"Trong quá trình ngâm nhả cát, nhuyễn thể hai mảnh vỏ phải được đựng vào các vỉ, giá hoặc khay, và được đặt cách đáy bể một khoảng ít nhất từ 8-10 cm để ngăn cách nhuyễn thể hai mảnh vỏ với cát, bùn và nhớt do chúng nhả ra trong quá trình ngâm lắng xuống đáy.\" Do đó, việc đặt khay trực tiếp xuống đáy bể là không tuân thủ.",3);
  add(3,"Yêu cầu nào sau đây là BẮT BUỘC đối với phòng thay đồ bảo hộ lao động cho công nhân tại khu vực làm sạch nhuyễn thể hai mảnh vỏ?",["Phòng thay đồ phải có cửa thông trực tiếp vào khu vực làm sạch để tiện lợi.", "Phòng thay đồ phải được bố trí riêng cho công nhân nam và nữ.", "Phòng thay đồ chỉ cần có đủ chỗ cho công nhân thay quần áo.", "Phòng thay đồ có thể dùng chung với nhà vệ sinh để tiết kiệm diện tích."],1,"Khoản 2.2.1.5.b quy định phòng thay đồ bảo hộ lao động cho công nhân phải \"Được bố trí riêng cho công nhân nam và nữ.\" Các phương án A, C, D đều không đúng hoặc không đầy đủ theo quy định tại 2.2.1.5.a, c, d.",2);
  add(3,"Theo QCVN 02-07: 2009/BNNPTNT, nhà vệ sinh tại khu vực làm sạch nhuyễn thể hai mảnh vỏ phải đảm bảo điều kiện nào?",["Bố trí liền kề và có cửa thông trực tiếp vào khu vực làm sạch.", "Thiết kế hợp vệ sinh, được trang bị hệ thống xả nước cưỡng bức, có phương tiện rửa tay bên cạnh và cung cấp đủ nước, giấy vệ sinh, xà phòng.", "Chỉ cần có đủ nước và xà phòng rửa tay.", "Có thể không cần chiếu sáng và thông gió tốt nếu được vệ sinh thường xuyên."],1,"Khoản 2.2.1.6 quy định nhà vệ sinh phải: \"a. Bố trí ở gần, nhưng cách ly hoàn toàn với khu vực làm sạch và không mở cửa thông trực tiếp vào khu vực làm sạch. b. Thiết kế hợp vệ sinh, được trang bị hệ thống xả nước cưỡng bức. c. Được chiếu sáng và thông gió tốt, không có mùi hôi thối. d. Có phương tiện rửa tay bên cạnh nhà vệ sinh. đ. Cung cấp đủ nước, giấy vệ sinh và xà phòng rửa tay.\" Phương án B tổng hợp đầy đủ các yêu cầu chính.",2);
  add(5,"Theo quy chuẩn, cơ sở cần bao nhiêu nhà vệ sinh riêng cho nam và nữ nếu có 30 công nhân trong một ca sản xuất?",["1 nhà vệ sinh", "2 nhà vệ sinh", "3 nhà vệ sinh", "5 nhà vệ sinh"],2,"Bảng quy định (phần g) yêu cầu 25-49 người phải có ít nhất 3 nhà vệ sinh riêng cho nam và nữ. Với 30 người thuộc nhóm này, đáp án đúng là 3.",1);
  add(5,"Nước dùng trong quá trình ngâm làm sạch nhuyễn thể hai mảnh vỏ phải đáp ứng yêu cầu nào?",["Nước máy bình thường", "Nước sạch hoặc nước biển sạch theo Điều 1.3.1 và 1.3.2", "Nước mưa thu thập", "Nước đã qua xử lý thải"],1,"Điều 2.2.2.3 quy định nước dùng phải là nước sạch hoặc nước biển sạch như nêu tại Điều 1.3.1 và 1.3.2 của Quy chuẩn.",1);
  add(5,"Sau mỗi mẻ ngâm làm sạch, bể ngâm và dụng cụ phải được thực hiện gì?",["Chỉ rửa lại bằng nước", "Làm vệ sinh và nếu cần thiết phải khử trùng", "Thay mới toàn bộ thiết bị", "Không cần làm gì nếu không có dấu bẩn"],1,"Theo Điều 2.2.2.1, sau mỗi mẻ ngâm làm sạch, bể ngâm, dụng cụ và khu vực xung quanh phải được làm vệ sinh, nếu cần thiết phải khử trùng.",1);
  add(5,"Các hoá chất độc hại dùng để diệt chuột bọ phải được bảo quản như thế nào?",["Để trong bồn rửa chung", "Bảo quản trong tủ riêng có khoá", "Đặt trên kệ mở", "Pha trộn trực tiếp vào nước ngâm"],1,"Điều 2.2.2.7 quy định hoá chất độc hại phải được bảo quản trong tủ riêng có khoá và tuyệt đối không để chúng nhiễm vào nhuyễn thể.",2);
  add(5,"Có thể đưa các lô nhuyễn thể hai mảnh vỏ được thu hoạch từ các vùng khác nhau vào cùng một bể ngâm làm sạch không?",["Có, nếu cùng loài", "Có, nếu cùng thời gian thu hoạch", "Không, phải cùng vùng, cùng loài, cùng thời gian", "Có, không có hạn chế nào"],2,"Điều 2.2.2.8 quy định các lô nhuyễn thể phải cùng loài, cùng vùng và cùng thời gian thu hoạch mới được đưa vào cùng một bể ngâm.",2);
  add(5,"Các hồ sơ mà cơ sở làm sạch phải lưu giữ ít nhất 2 năm không bao gồm:",["Kết quả kiểm tra vi sinh vật của nước cấp cho bể ngâm", "Kết quả kiểm tra vi sinh vật của nhuyễn thể sau khi làm sạch (đối với nhuyễn thể ăn sống/tái)", "Bản sao Giấy chứng nhận xuất xứ nhuyễn thể", "Danh sách nhân viên làm việc trong ca"],3,"Điều 2.2.2.12 liệt kê các tài liệu phải lưu giữ: a, b, c, d (kết quả vi sinh nước, vi sinh nhuyễn thể, chứng từ xuất xứ, tên địa chỉ nơi chuyển). Danh sách nhân viên không được yêu cầu lưu trữ trong mục này.",2);
  add(5,"Nếu phát hiện chuột xâm nhập vào khu vực làm sạch nhuyễn thể, biện pháp nào phải được thực hiện theo quy chuẩn?",["Cho chuột tự ra ngoài", "Sử dụng thuốc diệt chuột trực tiếp trong bể ngâm", "Thiết lập kế hoạch và các biện pháp ngăn ngừa hiệu quả như bẫy, vật cản", "Không làm gì vì không ảnh hưởng tới chất lượng"],2,"Điều 2.2.2.6 yêu cầu có kế hoạch và các biện pháp ngăn ngừa hiệu quả chuột, bọ, chim chóc xâm nhập vào khu vực làm sạch.",3);
  add(5,"Đối với nhuyễn thể hai mảnh vỏ dùng để ăn sống hoặc ăn tái, cơ sở phải lưu giữ thêm hồ sơ nào?",["Chỉ lưu giữ kết quả kiểm tra vi sinh của nước", "Lưu giữ kết quả kiểm tra vi sinh của nhuyễn thể sau khi làm sạch", "Chỉ lưu giữ thời gian ngâm", "Không cần lưu giữ hồ sơ bổ sung"],1,"Điều 2.2.2.12 mục b quy định đối với nhuyễn thể dùng để ăn sống hoặc ăn tái, phải lưu giữ kết quả kiểm tra vi sinh của nhuyễn thể sau khi làm sạch.",3);
  add(5,"Theo quy định 2.3.5, phương tiện vận chuyển nhuyễn thể hai mảnh vỏ sống phải được làm gì?",["Chỉ làm sạch trước mỗi chuyến", "Chỉ làm sạch sau mỗi chuyến", "Làm sạch cả trước và sau mỗi chuyến", "Không cần làm sạch"],2,"Điều 2.3.5 quy định: \"Phương tiện vận chuyển cần được vệ sinh sạch sẽ trước và sau mỗi chuyến vận chuyển.\" Do đó đáp án C (chỉ số 2) là đúng.",1);
  add(5,"Trong quá trình vận chuyển, nhuyễn thể hai mảnh vỏ sống không được để ở điều kiện nào sau khi áp dụng quy định 2.3.6?",["Nhiệt độ quá cao hoặc quá thấp", "Nhiệt độ ổn định 4 °C", "Được bảo quản trong băng đá", "Được để trong tủ lạnh"],0,"Điều 2.3.6 nêu rõ: \"không được để nhuyễn thể hai mảnh vỏ bị nóng quá hay lạnh quá, hoặc không được để chúng ở điều kiện nhiệt độ chênh lệch quá nhiều.\" Vì vậy đáp án A (chỉ số 0) là đúng.",1);
  add(5,"Trên nhãn bao gói nhuyễn thể hai mảnh vỏ sống ăn sống hoặc ăn tái (theo 2.5.2), nội dung nào sau đây không bắt buộc?",["Tên, địa chỉ cơ sở bao gói", "Tên loài (thương mại và khoa học)", "Vùng thu hoạch, ngày thu hoạch", "Nhiệt độ nấu chín tối thiểu"],3,"Điều 2.5.2 quy định các nội dung a‑d trên nhãn; không có yêu cầu ghi nhiệt độ nấu chín. Do đó đáp án D (chỉ số 3) là đúng.",1);
  add(5,"Nhuyễn thể hai mảnh vỏ sống cung cấp cho nhà máy chế biến được phép vận chuyển mà không cần bao gói, ghi nhãn theo quy định nào?",["2.3.8", "2.3.5", "2.5.1", "3.1.1"],0,"Điều 2.3.8 quy định: \"Nhuyễn thể hai mảnh vỏ sống cung cấp cho nhà máy chế biến... được phép vận chuyển không cần bao gói, ghi nhãn...\" Vì vậy đáp án A (chỉ số 0) là đúng.",2);
  add(5,"Theo 2.5.5, phương pháp ghi nhãn nào sau đây không được chấp nhận?",["In trực tiếp lên bao bì", "Ghim hoặc dán chặt nhãn riêng", "Bỏ nhãn vào trong bao đóng gói", "Viết tay bằng bút trên sản phẩm"],3,"Điều 2.5.5 liệt kê ba cách ghi nhãn được phép: a) in trực tiếp, b) ghim/dán, c) bỏ nhãn vào trong bao. Viết tay trên sản phẩm không nằm trong danh sách, vì vậy đáp án D (chỉ số 3) là đúng.",1);
  add(5,"Nhãn bao gói phải đáp ứng yêu cầu nào theo 2.5.4?",["Có thể tái sử dụng nhiều lần", "Không thấm nước và bền", "Làm bằng giấy mỏng", "Có thể tẩy xoá khi cần"],1,"Điều 2.5.4 quy định: \"Nhãn chỉ được dùng một lần và được làm bằng vật liệu bền, không thấm nước.\" Do đó đáp án B (chỉ số 1) là đúng.",1);
  add(5,"Cơ sở chế biến nhuyễn thể hai mảnh vỏ đông lạnh phải tuân thủ quy định chung của QCVN nào?",["QCVN 02‑01:2008/BNNPTNT", "QCVN 03‑02:2010/BNNPTNT", "QCVN 04‑03:2012/BNNPTNT", "QCVN 05‑04:2014/BNNPTNT"],0,"Điều 2.4.1 nêu: \"Cơ sở sơ chế, chế biến nhuyễn thể hai mảnh vỏ đông lạnh phải tuân thủ quy định chung... tại điều 2.1 của QCVN 02‑01:2008/BNNPTNT.\" Vì vậy đáp án A (chỉ số 0) là đúng.",2);
  add(5,"Việc bảo quản hoặc vận chuyển nhuyễn thể hai mảnh vỏ sống cùng với các sản phẩm khác có thể gây nhiễm bẩn vi phạm điều nào?",["2.3.4", "2.3.9", "2.5.1", "3.1.1"],1,"Điều 2.3.9 quy định: \"Không bảo quản hoặc vận chuyển nhuyễn thể hai mảnh vỏ sống cùng với các sản phẩm khác có thể gây nhiễm bẩn cho nhuyễn thể hai mảnh vỏ.\" Do đó đáp án B (chỉ số 1) là đúng.",2);
  add(5,"Một lô hàng nhuyễn thể hai mảnh vỏ sống được vận chuyển bằng xe tải đã được vệ sinh chỉ trước khi xuất phát, nhưng không được vệ sinh sau chuyến trước. Hành vi này vi phạm quy định nào?",["2.3.5", "2.3.6", "2.5.1", "3.1.2"],0,"Theo điều 2.3.5, phương tiện vận chuyển phải được vệ sinh sạch sẽ \"trước và sau mỗi chuyến vận chuyển\". Việc không vệ sinh sau chuyến trước là vi phạm quy định này, nên đáp án A (chỉ số 0) là đúng.",3);
  add(5,"Cơ quan nào được Bộ Nông nghiệp và Phát triển nông thôn chỉ định để tiến hành chứng nhận hợp quy cho cơ sở sản xuất nhuyễn thể hai mảnh vỏ?",["Bộ Nông nghiệp và Phát triển nông thôn", "Tổ chức chứng nhận do Bộ chỉ định", "Cơ quan quản lý nhà nước địa phương", "Chủ cơ sở sản xuất"],0,"Theo đoạn văn, \"được Bộ Nông nghiệp và Phát triển nông thôn chỉ định tiến hành chứng nhận hợp quy cho cơ sở sản xuất nhuyễn thể hai mảnh vỏ\" (phần 3.1.3). Vì vậy đáp án đúng là A.",1);
  add(5,"Sau khi được chứng nhận hợp quy, cơ sở sản xuất nhuyễn thể hai mảnh vỏ phải thực hiện việc nào sau đây?",["Không cần công bố thông tin", "Công bố trên báo chí địa phương", "Gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành do Bộ chỉ định", "Gửi hồ sơ cho Bộ Y tế"],2,"Điều 3.2.1 quy định: \"Cơ sở sản xuất... phải thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành do Bộ Nông nghiệp và Phát triển nông thôn chỉ định\".",1);
  add(5,"Việc công bố hợp quy được thực hiện theo quy định của văn bản nào?",["Điều 14 Nghị định số 127/2007/NĐ-CP", "Điều 10 Luật An toàn thực phẩm", "Thông tư 47/2009/TT-BNNPTNT", "Nghị quyết 45/2010/QH13"],0,"Trong mục 3.2.2 nêu rõ: \"Việc công bố hợp quy thực hiện theo quy định tại Điều 14 Nghị định số 127/2007/NĐ-CP\".",1);
  add(5,"Ai chịu trách nhiệm thanh tra, kiểm tra định kỳ hoặc đột xuất đối với cơ sở sản xuất nhuyễn thể hai mảnh vỏ đã được chứng nhận hợp quy?",["Cơ quan quản lý nhà nước chuyên ngành", "Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương", "Tổ chức chứng nhận", "Chủ cơ sở sản xuất"],1,"Mục 3.3.1 quy định: \"Cơ sở... và Tổ chức chứng nhận chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất của Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương\".",2);
  add(5,"Khi có sự thay đổi, bổ sung hoặc thay thế các quy định trong quy chuẩn này, cơ sở sản xuất phải thực hiện theo văn bản nào?",["Theo quyết định của Chủ cơ sở", "Theo văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành", "Theo thông tư của Bộ Y tế", "Theo nghị quyết của Quốc hội"],1,"Mục 3.4.3 nêu: \"Thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành\".",2);
  add(5,"Nếu một cơ sở sản xuất nhuyễn thể hai mảnh vỏ không thực hiện công bố hợp quy theo quy định, hậu quả pháp lý có thể là gì?",["Không có hậu quả", "Bị xử phạt hành chính theo quy định của pháp luật hiện hành", "Bị thu hồi chứng nhận hợp quy ngay lập tức", "Bị đình chỉ hoạt động sản xuất"],1,"Mục 3.3.2 quy định: \"Việc tiến hành thanh tra, kiểm tra và xử lý vi phạm phải tuân thủ theo quy định của pháp luật hiện hành\". Vi phạm công bố hợp quy là vi phạm hành chính, thường bị xử phạt hành chính.",3);
  add(5,"QCVN 02-08:2009/BNNPTNT quy định về điều kiện gì?",["An toàn thực phẩm cho cơ sở sản xuất nước đá thuỷ sản", "Chất lượng không khí trong nhà máy", "Tiêu chuẩn đóng gói thủy sản", "Quy trình kiểm dịch xuất khẩu thủy sản"],0,"Theo mục 1.1 của QCVN 02-08:2009, quy chuẩn này quy định các điều kiện đảm bảo vệ sinh an toàn thực phẩm cho cơ sở sản xuất và phân phối nước đá dùng để bảo quản nguyên liệu và sản phẩm thuỷ sản.",1);
  add(5,"Đối tượng áp dụng của QCVN 02-08:2009 là:",["Chỉ các doanh nghiệp lớn sản xuất nước đá", "Tất cả các tổ chức, cá nhân hoạt động sản xuất kinh doanh nước đá thuỷ sản", "Các nhà nhập khẩu nước đá", "Các cơ sở chế biến thủy sản không dùng nước đá"],1,"Mục 1.2 nêu rõ quy chuẩn áp dụng cho tất cả các tổ chức, cá nhân hoạt động sản xuất kinh doanh nước đá thuỷ sản.",1);
  add(5,"Trong QCVN, “nước sạch” được hiểu là:",["Nước đã qua xử lý bằng clo", "Nước đạt tiêu chuẩn theo quy định của Bộ Y tế", "Nước có độ pH từ 6-8", "Nước không có mùi"],1,"Giải thích từ ngữ mục 1.3.1 quy định nước sạch là nước đạt tiêu chuẩn theo quy định của Bộ Y tế.",1);
  add(5,"Yêu cầu về địa điểm xây dựng cơ sở sản xuất nước đá thuỷ sản không bao gồm:",["Phải xây dựng ở xa nơi có nguồn gây ô nhiễm", "Phải có đủ nguồn nước sạch hoặc nước biển sạch", "Phải gần nguồn điện công cộng", "Phải tránh bị đọng hoặc ngập nước"],2,"Mục 2.1 liệt kê các yêu cầu: 2.1.1 xa nguồn ô nhiễm, 2.1.2 có đủ nguồn nước sạch/biển sạch, 2.1.3 có nguồn điện đảm bảo, 2.1.4 không bị đọng/ngập nước. Yêu cầu “gần nguồn điện công cộng” không có trong văn bản.",1);
  add(5,"Mặt bể làm nước đá, bể chứa nước làm nước đá và bể ra khuôn nước đá phải được thiết kế:",["Cao hơn nền xưởng ít nhất 30 cm", "Cao hơn nền xưởng ít nhất 60 cm", "Bằng mặt nền xưởng", "Có thể thấp hơn nền xưởng nếu có bậc thang"],1,"Mục 2.2.5 quy định các bể phải được thiết kế cao hơn nền xưởng từ 60 cm trở lên, có bậc lên xuống thuận tiện cho sản xuất.",1);
  add(5,"Về vật liệu và cấu tạo nắp các bể làm nước đá, quy chuẩn yêu cầu:",["Phải làm bằng thép không gỉ, có lớp sơn màu trắng", "Phải làm bằng vật liệu không độc, chắc chắn, kín khít, phẳng, không đọng nước và dễ làm vệ sinh", "Phải có lỗ thoát khí để giảm áp suất", "Phải có cửa sổ quan sát bên trong"],1,"Mục 2.2.6 nêu rõ nắp bể làm nước đá phải làm bằng vật liệu không độc, cấu tạo chắc chắn, kín khít, phẳng, không đọng nước và dễ làm vệ sinh.",1);
  add(5,"Hệ thống cung cấp nước cho sản xuất nước đá phải được làm bằng:",["Vật liệu nhựa PVC", "Vật liệu không gỉ", "Vật liệu sắt thông thường", "Vật liệu gỗ đã được xử lý"],1,"Mục 2.3.2 quy định hệ thống cung cấp nước (bể chứa, đường ống, vòi nước) phải được làm bằng vật liệu không gỉ, thiết kế thuận tiện và dễ làm vệ sinh.",1);
  add(5,"Nếu cơ sở sử dụng nguồn nước khác cho mục đích không liên quan tới sản xuất nước đá, quy chuẩn yêu cầu:",["Có thể dùng chung cùng ống cấp nước sạch", "Phải bố trí hệ thống cung cấp nước này riêng biệt để tránh nhiễm chéo", "Không cần ghi nhận nguồn nước trong hồ sơ", "Phải xử lý bằng clo trước khi dùng"],1,"Mục 2.3.3 quy định nếu có nguồn nước khác cho các mục đích khác, hệ thống cung cấp nước này phải được bố trí riêng biệt với hệ thống nước sạch dùng cho sản xuất, tránh gây nhiễm chéo.",2);
  add(5,"Các thiết bị chứa gas và ống dẫn gas trong cơ sở sản xuất nước đá phải:",["Được làm bằng nhôm để giảm trọng lượng", "Đảm bảo an toàn, không bị rò rỉ", "Có thể đặt gần bể làm nước đá nếu có thông gió", "Phải được sơn màu đỏ để nhận diện"],1,"Mục 2.4.1 quy định các thiết bị chứa gas, ống dẫn gas phải đảm bảo an toàn, không bị rò rỉ.",1);
  add(5,"Trong một trường hợp thực tế, một cơ sở sản xuất nước đá thuỷ sản sử dụng nước từ sông không qua xử lý và không đáp ứng tiêu chuẩn Bộ Y tế. Hành vi này:",["Đúng, vì nước sông luôn sạch", "Sai, vi phạm mục 2.3.1 về việc sử dụng nước sạch", "Được chấp nhận nếu nước sông có màu trong", "Chỉ cần kiểm tra lại sau 6 tháng"],1,"Mục 2.3.1 yêu cầu nước dùng để sản xuất nước đá phải là nước sạch theo quy định của Bộ Y tế. Sử dụng nước sông chưa qua xử lý không đáp ứng tiêu chuẩn, do đó vi phạm quy chuẩn.",3);
  add(5,"Theo QCVN 47/2009, trước khi sử dụng, khuôn sản xuất nước đá phải được thực hiện việc gì?",["Bảo quản trong tủ lạnh", "Vệ sinh sạch sẽ", "Ngâm trong dung dịch khử trùng 30 phút", "Phơi khô dưới ánh nắng"],1,"Điều 2.5.1 (a) quy định khuôn sản xuất nước đá và các dụng cụ phải được vệ sinh sạch sẽ trước khi dùng.",1);
  add(5,"Dung dịch nước muối dùng để sản xuất nước đá phải được xử lý như thế nào?",["Đun sôi 10 phút", "Lọc và làm sạch trước khi đưa vào bể làm nước đá", "Pha loãng với nước tinh khiết", "Thêm chất khử trùng ngay khi đưa vào bể"],1,"Theo mục (b) của Điều 2.5.1, dung dịch nước muối phải được lắng lọc, làm sạch trước khi đưa vào bể làm nước đá.",1);
  add(5,"Trong quá trình bốc dỡ và vận chuyển nước đá, điều nào sau đây KHÔNG được phép?",["Đặt nước đá trên nền đất", "Sử dụng vật liệu tiếp xúc đã được vệ sinh", "Bảo quản trong thùng cách nhiệt", "Kiểm tra nhiệt độ nước đá"],0,"Mục (d) của Điều 2.5.1 cấm nước đá tiếp xúc trực tiếp trên nền đất hoặc nền nhà xưởng.",1);
  add(5,"Công nhân sản xuất nước đá phải thực hiện việc nào sau khi đi vệ sinh?",["Rửa tay bằng xà phòng và khử trùng ủng", "Chỉ rửa tay bằng nước sạch", "Thay áo bảo hộ ngay lập tức", "Sử dụng dung dịch khử trùng mà không rửa tay"],0,"Điều 2.5.2 (c) yêu cầu công nhân rửa sạch tay bằng xà phòng và khử trùng ủng trước khi làm việc hoặc ngay sau khi đi vệ sinh.",1);
  add(5,"Theo QCVN, hồ sơ quản lý vệ sinh an toàn phải được lưu giữ trong thời gian bao lâu?",["1 năm", "2 năm", "3 năm", "5 năm"],1,"Mục (b) của Điều 2.5.4 quy định thời gian lưu giữ hồ sơ quản lý là 2 năm.",1);
  add(5,"Cơ sở sản xuất nước đá thủy sản phải thực hiện chứng nhận hợp quy dựa trên quyết định nào?",["Quyết định số 24/2007/QĐ-BKHCN ngày 28/9/2007", "Quyết định số 45/2010/QĐ-BKHCN ngày 15/3/2010", "Quyết định số 12/2015/QĐ-BKHCN ngày 01/01/2015", "Quyết định số 30/2008/QĐ-BKHCN ngày 10/10/2008"],0,"Điều 3.1.1 yêu cầu cơ sở thực hiện chứng nhận hợp quy theo Quyết định số 24/2007/QĐ-BKHCN ngày 28/9/2007.",2);
  add(5,"Ai là cơ quan chỉ định tiến hành chứng nhận hợp quy cho cơ sở sản xuất nước đá thủy sản?",["Bộ Y tế", "Bộ Nông nghiệp và Phát triển nông thôn", "Cục An toàn Thực phẩm", "Sở Y tế địa phương"],1,"Theo Điều 3.1.2, Bộ Nông nghiệp và Phát triển nông thôn chỉ định tiến hành chứng nhận hợp quy.",2);
  add(5,"Trong trường hợp có sự thay đổi, bổ sung quy chuẩn kỹ thuật về điều kiện vệ sinh ATTP, cơ sở phải thực hiện theo văn bản nào?",["Quyết định của Thủ tướng", "Nghị định của Chính phủ", "Văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành", "Thông tư của Bộ Y tế"],2,"Điều 3.4.3 quy định khi có thay đổi, bổ sung quy chuẩn, phải thực hiện theo văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.",3);
  add(5,"Khi tiến hành thanh tra, kiểm tra định kỳ hoặc đột xuất, cơ sở sản xuất nước đá thủy sản phải tuân thủ quy định của:",["Luật Thương mại", "Luật Bảo vệ môi trường", "Luật Tiêu chuẩn và Quy chuẩn kỹ thuật", "Luật Đầu tư"],2,"Điều 3.3.2 nêu rằng việc thanh tra, kiểm tra và xử lý vi phạm phải tuân thủ quy định của pháp luật hiện hành, trong bối cảnh này là Luật Tiêu chuẩn và Quy chuẩn kỹ thuật.",2);
  add(5,"Một cơ sở sản xuất nước đá không thực hiện việc thay nước trong bể ra khuôn sau mỗi ca sản xuất. Hành vi này vi phạm quy định nào?",["Điều 2.5.1 (c)", "Điều 2.5.2 (a)", "Điều 2.5.3 (b)", "Điều 3.1.1"],0,"Điều 2.5.1 (c) yêu cầu nước trong bể ra khuôn nước đá phải được thay nước sau mỗi ca sản xuất; không thực hiện là vi phạm.",3);
  add(5,"Quy chuẩn QCVN 02-09:2009/BNNPTNT quy định phạm vi điều chỉnh nào?",["Tất cả các loại thực phẩm", "Kho lạnh thương mại thuỷ sản", "Nhà máy chế biến thuỷ sản", "Các nhà hàng và khách sạn"],1,"Theo mục 1.1 của QCVN, quy chuẩn này chỉ quy định các điều kiện vệ sinh an toàn thực phẩm đối với kho lạnh thương mại thuỷ sản dùng để bảo quản sản phẩm thuỷ sản đông lạnh.",1);
  add(5,"Đối tượng nào không áp dụng quy chuẩn này?",["Doanh nghiệp kinh doanh kho lạnh thương mại", "Kho lạnh nằm trong dây chuyền sản xuất của nhà máy chế biến thuỷ sản đông lạnh", "Các cá nhân sử dụng kho lạnh để bảo quản thuỷ sản", "Tất cả các tổ chức, cá nhân sử dụng kho lạnh"],1,"Mục 1.2.2 nêu rõ quy chuẩn không áp dụng cho kho lạnh nằm trong dây chuyền sản xuất của nhà máy chế biến thuỷ sản đông lạnh.",1);
  add(5,"Yêu cầu về vị trí địa lý của kho lạnh theo QCVN là:",["Phải xây dựng gần sông để tiện lấy nước", "Có thể đặt ở khu vực thấp, dễ ngập", "Được xây dựng ở nơi cao ráo, không bị ngập hoặc đọng nước, xa nguồn gây ô nhiễm", "Không có yêu cầu vị trí cụ thể"],2,"Điều 2.1.1 quy định kho lạnh phải được xây dựng ở nơi cao ráo, không bị ngập hoặc đọng nước và xa các nguồn gây ô nhiễm.",1);
  add(5,"Độ cao tối thiểu của nền kho lạnh so với mặt bằng quanh kho phải nằm trong khoảng:",["0,5 - 0,8 m", "0,8 - 1,4 m", "1,5 - 2,0 m", "Không có quy định cụ thể"],1,"Theo mục 2.2.1, nền kho lạnh, phòng đệm phải cao 0,8-1,4 m so với mặt bằng quanh kho.",1);
  add(5,"Chiều rộng tối thiểu của phòng đệm phải đạt:",["3 m", "4 m", "5 m", "6 m"],2,"Trong mục 2.2.1, quy định chiều rộng tối thiểu của phòng đệm là 5 m.",1);
  add(5,"Về vật liệu của tường, trần và cửa trong kho lạnh, yêu cầu nào sau đây là đúng?",["Có thể dùng gỗ chưa xử lý vì chi phí thấp", "Phải là vật liệu không độc, không gỉ, không ngấm nước, cách nhiệt tốt và dễ vệ sinh", "Chỉ cần chịu tải trọng, không cần quan tâm đến tính độc hại", "Không cần đáp ứng tiêu chuẩn nào vì sẽ được làm sạch thường xuyên"],1,"Mục 2.2.4 và 2.2.6 quy định vật liệu phải không độc, không gỉ, không ngấm nước, có khả năng cách nhiệt tốt, bề mặt nhẵn, dễ làm vệ sinh và khử trùng.",2);
  add(5,"Nhiệt kế tự ghi trong kho lạnh phải có độ chính xác tối đa là:",["1,0°C", "0,5°C", "0,1°C", "Không quy định độ chính xác"],1,"Mục 2.3.5 quy định nhiệt kế tự ghi phải có độ chính xác 0,50°C.",2);
  add(5,"Thiết bị làm lạnh trong kho lạnh phải đáp ứng yêu cầu nào sau đây?",["Công suất đủ cho 50% tải tối đa", "Công suất đủ để bảo quản sản phẩm ở nhiệt độ yêu cầu ngay cả khi kho đạt mức tối đa, môi chất lạnh không ảnh hưởng môi trường", "Chỉ cần có khả năng làm lạnh, không cần kiểm định", "Có thể dùng môi chất lạnh bất kỳ mà không cần xét duyệt"],1,"Mục 2.3.1 yêu cầu thiết bị làm lạnh phải có công suất đủ để bảo quản sản phẩm ở nhiệt độ cần thiết và ổn định, kể cả khi kho chứa hàng đạt mức tối đa, và môi chất làm lạnh phải được phép sử dụng, không ảnh hưởng đến môi trường.",2);
  add(5,"Khi xả băng, thiết kế kho lạnh phải đảm bảo:",["Nước băng được giữ lại trong kho để tái sử dụng", "Nước từ giàn lạnh, trên trần và nền kho phải chảy hết ra ngoài", "Nước được thu gom vào bể chứa riêng", "Không có yêu cầu cụ thể về việc xả băng"],1,"Mục 2.2.7 quy định khi xả băng, nước từ giàn lạnh, trên trần kho và nền kho phải chảy hết ra ngoài để tránh nhiễm bám và giảm nguy cơ ô nhiễm.",2);
  add(5,"Tình huống: Một kho lạnh thương mại thuỷ sản được xây dựng tại khu vực có nguy cơ ngập nước trong mùa mưa. Theo QCVN, hành động nào là đúng?",["Tiếp tục hoạt động vì đã lắp hệ thống bơm thoát nước", "Cải tạo vị trí hoặc di dời kho để đáp ứng yêu cầu không ngập nước", "Chỉ cần lắp rèm chắn để ngăn nước vào", "Không cần thay đổi vì quy chuẩn không quy định về ngập nước"],1,"Theo mục 2.1.1, kho lạnh phải được xây dựng ở nơi cao ráo, không bị ngập hoặc đọng nước. Nếu hiện trạng không đáp ứng, phải cải tạo hoặc di dời để tuân thủ quy định.",3);
  add(5,"Theo Điều 3.1.3 của Thông tư 47/2009/TT-BNNPTNT, việc đánh giá và chứng nhận cơ sở kho lạnh thủy sản hợp quy được thực hiện theo hướng dẫn của cơ quan nào?",["Bộ Y tế", "Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Công Thương", "Cục An toàn Thực phẩm"],1,"Đoạn 3.1.3 nêu rõ \"Phương thức đánh giá, chứng nhận cơ sở kho lạnh thuỷ sản hợp quy thực hiện theo hướng dẫn của Bộ Nông nghiệp và Phát triển nông thôn\". Do đó đáp án B là đúng.",1);
  add(5,"Việc công bố hợp quy của cơ sở kho lạnh thủy sản phải tuân thủ quy định tại Điều nào của Nghị định nào?",["Điều 10 Nghị định 123/2009/NĐ-CP", "Điều 14 Nghị định 127/2007/NĐ-CP", "Điều 8 Nghị định 115/2008/NĐ-CP", "Điều 12 Nghị định 130/2006/NĐ-CP"],1,"Trong mục 3.2.2, văn bản quy định: \"Việc công bố hợp quy thực hiện theo quy định tại Điều 14 Nghị định số 127/2007/NĐ-CP\". Vì vậy đáp án B là đúng.",1);
  add(5,"Ai có thẩm quyền thực hiện thanh tra, kiểm tra định kỳ hoặc đột xuất đối với cơ sở kho lạnh thủy sản đã được chứng nhận hợp quy?",["Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền địa phương", "Cục Thủy sản chỉ", "Bộ Tài chính", "Cục Quản lý Thị trường"],0,"Điều 3.3.1 quy định: \"Cơ sở kho lạnh thủy sản và Tổ chức chứng nhận chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất của Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền địa phương.\" Do đó đáp án A là đúng.",2);
  add(5,"Khi có sự thay đổi, bổ sung hoặc thay thế các quy định tại Quy chuẩn này, cơ sở kho lạnh thủy sản phải thực hiện theo văn bản nào?",["Theo quyết định của Chủ cơ sở", "Theo quy định của Luật Đầu tư", "Theo văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành", "Theo thông báo của Sở Y tế địa phương"],2,"Mục 3.4.3 nêu rõ: \"...thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.\" Vì vậy đáp án C là đúng.",2);
  add(5,"Một cơ sở kho lạnh thủy sản đã được chứng nhận hợp quy nhưng không gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành. Theo quy định trong Thông tư, hành vi này có thể dẫn đến:",["Không ảnh hưởng gì vì đã có chứng nhận", "Bị thu hồi chứng nhận và xử lý vi phạm theo quy định pháp luật hiện hành", "Chỉ cần nộp hồ sơ trong vòng 30 ngày mà không có hình phạt", "Được cơ quan quản lý xem xét giảm mức phạt nếu có lời giải thích"],1,"Theo mục 3.2.1, cơ sở phải thực hiện công bố hợp quy và gửi hồ sơ về cơ quan quản lý nhà nước. Việc không thực hiện là vi phạm quy định, và theo mục 3.3.2 \"việc tiến hành thanh tra, kiểm tra và xử lý vi phạm phải tuân thủ theo quy định của pháp luật hiện hành\". Do đó cơ sở có thể bị thu hồi chứng nhận và chịu xử lý vi phạm, nên đáp án B là đúng.",3);
  add(5,"Theo QCVN 02-10:2009/BNNPTNT, một cơ sở thu mua thủy sản phải đáp ứng yêu cầu nào về nguồn nước sinh hoạt?",["Nước cấp từ nguồn công cộng phải được xử lý qua hệ thống lọc RO và đạt tiêu chuẩn QCVN 06-01:2010", "Nước cấp phải được kiểm tra định kỳ ít nhất một lần mỗi tháng và đáp ứng tiêu chuẩn QCVN 06-01:2010 về nước sinh hoạt", "Nước cấp có thể lấy trực tiếp từ giếng khoan nếu có giấy chứng nhận an toàn", "Nước cấp không cần kiểm tra nếu đã qua xử lý khử trùng bằng clo"],1,"Điều 9 QCVN 02-10:2009 quy định nguồn nước sinh hoạt phải được cung cấp từ hệ thống cấp nước công cộng hoặc hệ thống riêng đáp ứng tiêu chuẩn QCVN 06-01:2010 và phải kiểm tra định kỳ ít nhất một lần mỗi tháng.",2);
  add(5,"Trong quy chuẩn QCVN 02-10:2009, việc kiểm soát côn trùng và chuột tại cơ sở thu mua thủy sản được quy định ở mục nào?",["Điều 12, Khoản 1", "Điều 14, Khoản 3", "Điều 15, Khoản 2", "Điều 18, Khoản 1"],2,"Điều 15, Khoản 2 QCVN 02-10:2009 quy định cơ sở phải thực hiện các biện pháp phòng ngừa, kiểm soát côn trùng và chuột, bao gồm việc lắp đặt bẫy, sử dụng thuốc diệt côn trùng và duy trì vệ sinh môi trường.",1);
  add(5,"Nếu phát hiện vi phạm về vệ sinh công nhân tại cơ sở thu mua, biện pháp xử lý theo QCVN 02-10:2009 là:",["Cảnh cáo bằng văn bản và yêu cầu khắc phục trong 24 giờ", "Đình chỉ hoạt động ngay lập tức cho đến khi khắc phục", "Áp dụng hình phạt tiền và yêu cầu cải thiện trong 7 ngày", "Gửi báo cáo lên Bộ Nông nghiệp và Phát triển Nông thôn để quyết định"],0,"Theo Điều 20 QCVN 02-10:2009, vi phạm về vệ sinh công nhân sẽ bị cảnh cáo bằng văn bản và yêu cầu khắc phục trong thời hạn 24 giờ; nếu không khắc phục sẽ áp dụng các biện pháp xử phạt nặng hơn.",2);
  add(5,"Trong quy chuẩn QCVN 02-10:2009, yêu cầu về thiết bị bảo quản thủy sản (đông lạnh) bao gồm:",["Nhiệt độ bảo quản phải duy trì không quá -10°C", "Nhiệt độ bảo quản phải duy trì không quá -18°C và được ghi lại liên tục", "Nhiệt độ bảo quản không cần ghi chép nếu thiết bị có công tắc tự động", "Nhiệt độ bảo quản chỉ cần kiểm tra mỗi ngày một lần"],1,"Điều 11 QCVN 02-10:2009 quy định thiết bị bảo quản phải duy trì nhiệt độ không quá -18°C và phải có hệ thống ghi chép nhiệt độ liên tục để kiểm soát.",1);
  add(5,"Theo QCVN 02-10:2009, tài liệu nào phải được lưu trữ ít nhất 24 tháng tại cơ sở thu mua thủy sản?",["Bản sao giấy chứng nhận nguồn gốc sản phẩm", "Báo cáo kiểm tra chất lượng nước sinh hoạt", "Sổ nhật ký vệ sinh và kiểm soát dịch hại", "Hợp đồng mua bán với nhà cung cấp"],2,"Điều 16 QCVN 02-10:2009 quy định sổ nhật ký vệ sinh, kiểm soát dịch hại và các biện pháp phòng ngừa phải được lưu trữ ít nhất 24 tháng để phục vụ kiểm tra, giám sát.",2);
  add(5,"Trong một tình huống thực tế, nếu một lô cá nhập khẩu được phát hiện có dấu hiệu nhiễm vi khuẩn Salmonella, quy trình xử lý theo QCVN 02-10:2009 bao gồm các bước nào sau đây?",["Tách lô hàng, thông báo cơ quan quản lý, thực hiện tiêu hủy và ghi lại trong sổ nhật ký", "Chỉ thông báo cơ quan quản lý và chờ kết quả xét nghiệm bổ sung", "Tiêu hủy ngay lập tức mà không cần thông báo, vì nguy cơ cao", "Gửi lô hàng về nhà cung cấp để họ tự chịu trách nhiệm"],0,"Theo Điều 22 QCVN 02-10:2009, khi phát hiện sản phẩm có nguy cơ gây hại sức khỏe (ví dụ Salmonella), cơ sở phải tách lô hàng, thông báo ngay cho cơ quan quản lý nhà nước, thực hiện tiêu hủy theo quy định và ghi lại chi tiết trong sổ nhật ký kiểm soát an toàn thực phẩm.",3);
  add(5,"Theo đoạn trích, đơn vị nào chịu trách nhiệm chỉ đạo các đơn vị chức năng phổ biến, hướng dẫn và thực hiện Quy chuẩn kỹ thuật?",["Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Y tế", "Bộ Công Thương", "Bộ Nông nghiệp và Phát triển nông thôn cùng với Bộ Y tế"],0,"Đoạn 3.4.2 nêu rõ \"Bộ Nông nghiệp và Phát triển nông thôn tổ chức chỉ đạo các đơn vị chức năng phổ biến, hướng dẫn và thực hiện Quy chuẩn kỹ thuật này\". Do đó đáp án A là đúng.",1);
  add(5,"Khi có sự thay đổi, bổ sung hoặc thay thế các quy định tại Quy chuẩn này, việc thực hiện phải dựa trên văn bản nào?",["Thông tư 47/2009/TT-BNNPTNT ban hành lần đầu", "Bất kỳ công văn nào của cơ quan địa phương", "Văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành", "Quyết định của Thủ tướng Chính phủ"],2,"Đoạn 3.4.3 quy định: \"thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành\". Vì vậy đáp án C là đúng.",1);
  add(5,"Mục đích chính của Quy chuẩn kỹ thuật quốc gia này là gì?",["Tăng sản lượng xuất khẩu thủy sản", "Đảm bảo vệ sinh an toàn thực phẩm", "Giảm chi phí sản xuất", "Thúc đẩy nuôi trồng hữu cơ"],1,"Đoạn mở đầu nêu \"Quy chuẩn kỹ thuật nhằm đảm bảo vệ sinh an toàn thực phẩm\". Do đó đáp án B là đúng.",1);
  add(5,"Trong các mục được trích dẫn, đoạn nào nêu rõ vai trò của Bộ Nông nghiệp và Phát triển nông thôn trong việc chỉ đạo thực hiện Quy chuẩn?",["Mục 3.4.1", "Mục 3.4.2", "Mục 3.4.3", "Mục 4.1.1"],1,"Vai trò chỉ đạo được nêu ở mục 3.4.2: \"Bộ Nông nghiệp và Phát triển nông thôn tổ chức chỉ đạo...\". Vì vậy đáp án B là đúng.",2);
  add(5,"Nếu có thay đổi quy định và được thay thế bằng văn bản mới, chữ ký của người nào là cần thiết để văn bản đó có hiệu lực?",["Chủ tịch nước", "Thủ tướng Chính phủ", "Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn", "Giám đốc Cục An toàn Thực phẩm"],2,"Theo mục 3.4.3, việc thực hiện các thay đổi phải dựa trên \"văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành\"; do đó chữ ký của Bộ trưởng là bắt buộc. Đáp án C là đúng.",2);
  add(5,"Quy chuẩn QCVN 02-11:2009/BNNPTNT quy định về điều kiện vệ sinh an toàn thực phẩm áp dụng cho loại hình nào sau đây?",["Cửa hàng bán lẻ cá tươi cho người tiêu dùng cuối cùng", "Chợ bán buôn hoặc bán đấu giá thủy sản làm nguyên liệu cho các cơ sở chế biến thủy sản", "Nhà máy chế biến thủy sản công nghiệp", "Nhà hàng, khách sạn phục vụ món hải sản"],1,"Theo mục 1.1 ‘Phạm vi điều chỉnh’, quy chuẩn này áp dụng cho chợ bán buôn hoặc bán đấu giá thủy sản làm nguyên liệu cho các cơ sở chế biến thủy sản.",1);
  add(5,"Đối tượng áp dụng của QCVN 02-11:2009/BNNPTNT bao gồm:",["Chỉ các cơ quan quản lý nhà nước về thị trường thủy sản", "Các tổ chức, cá nhân hoạt động sản xuất, kinh doanh dịch vụ trong chợ cá và cơ quan quản lý chợ cá", "Chỉ các nhà cung cấp nguyên liệu thủy sản cho chợ cá", "Các nhà xuất khẩu thủy sản"],1,"Mục 1.2 ‘Đối tượng áp dụng’ nêu rõ quy chuẩn áp dụng cho các cơ quan quản lý chợ cá, các tổ chức và cá nhân hoạt động sản xuất, kinh doanh dịch vụ trong chợ cá.",1);
  add(5,"Trong các yêu cầu về địa điểm của chợ cá, điều nào sau đây **KHÔNG** phải đáp ứng?",["Gần cảng cá, bến cá hoặc khu vực có nguồn nguyên liệu tập trung", "Có đường giao thông thuận tiện cho việc đi lại và vận chuyển", "Nằm trong khu dân cư để thuận tiện cho người tiêu dùng", "Có nguồn nước, nguồn điện đáp ứng tiêu chuẩn và yêu cầu sử dụng"],2,"Mục 2.1.4 yêu cầu chợ cá phải cách biệt với khu dân cư và xa các nguồn gây nhiễm; do đó việc nằm trong khu dân cư không phải là yêu cầu.",1);
  add(5,"Theo mục 2.2.2, khu vực nào **KHÔNG** được liệt kê là một trong các khu vực hoạt động cần bố trí riêng biệt hoặc liền kề trong chợ cá?",["Nơi tập kết bảo quản, phân loại và bày bán nguyên liệu", "Khu vực văn phòng, khu chờ đợi của công nhân", "Khu vực trưng bày sản phẩm chế biến sẵn cho người tiêu dùng", "Hệ thống kho lạnh bảo quản nguyên liệu, dự trữ nước đá"],2,"Mục 2.2.2 liệt kê a) b) d) e) g) ... không có mục 'Khu vực trưng bày sản phẩm chế biến sẵn cho người tiêu dùng'; chợ cá chỉ bán nguyên liệu thô.",2);
  add(5,"Về vật liệu của các cột nhà trong chợ cá, quy định yêu cầu phải:",["Được sơn màu trắng để phản chiếu ánh sáng", "Ốp gạch men hoặc láng xi măng bóng tới chiều cao 2 m từ nền nhà, hoặc sơn không gỉ nếu là cột sắt", "Sử dụng thép không gỉ 100 % không cần sơn", "Được phủ lớp nhựa PVC để chống thấm"],1,"Mục 2.5 quy định: các cột nhà phải được ốp gạch men, hoặc láng xi măng bóng tới chiều cao 2 m; nếu là cột sắt phải sơn đảm bảo không gỉ sét.",2);
  add(5,"Nhiệt độ bảo quản tối đa cho thủy sản trong kho lạnh của chợ cá theo mục 2.3.1 là:",["-5 °C đến +5 °C", "0 °C đến +10 °C", "-1 °C đến +40 °C", "+2 °C đến +25 °C"],2,"Mục 2.3.1 nêu rõ kho lạnh hoặc thùng cách nhiệt phải duy trì nhiệt độ của thủy sản từ -1 °C đến +40 °C trong suốt thời gian bảo quản.",1);
  add(5,"Trong chợ cá, các bể chứa nước và vòi nước phải được bố trí sao cho đáp ứng yêu cầu nào sau đây?",["Chỉ cần có vòi nước lạnh để làm mát thủy sản", "Phải có vòi nước rửa tay, có xà phòng rửa tay để vệ sinh tay người lao động", "Cần có hệ thống lọc nước sinh học để tái sử dụng nước", "Phải được lắp đặt trong khu vực kho lạnh"],1,"Mục 2.10 quy định rằng trong chợ phải bố trí vòi nước rửa tay, có xà phòng rửa tay, đáp ứng yêu cầu vệ sinh cho người lao động.",2);
  add(5,"Phương tiện bốc xếp, vận chuyển thủy sản tại chợ cá phải đáp ứng tiêu chí nào sau đây?",["Được làm bằng gỗ tự nhiên để giảm chi phí", "Phải là phương tiện chuyên dùng, chế tạo từ vật liệu không gây độc cho thủy sản, dễ làm vệ sinh và khử trùng", "Có thể sử dụng cùng với các loại hàng hóa khác nếu không gây nhiễm bẩn trực tiếp", "Phải có khả năng di chuyển tự động không cần người lái"],1,"Mục 2.4.1 (theo QCVN 02-01) quy định phương tiện bốc xếp, vận chuyển phải là phương tiện chuyên dùng, chế tạo từ vật liệu không gây độc cho thủy sản, dễ làm vệ sinh, khử trùng.",2);
  add(5,"Theo QCVN 02-01:2009, phương tiện dùng để bốc xếp, vận chuyển thủy sản phải được thực hiện gì trước khi sử dụng?",["Bảo dưỡng định kỳ mỗi tháng", "Vệ sinh khử trùng cẩn thận", "Sơn phủ lớp bảo vệ chống ăn mòn", "Kiểm tra nhiệt độ và độ ẩm"],1,"Điều 2.4.2 của Thông tư 47/2009/TT-BNNPTNT quy định: “phương tiện phải được vệ sinh khử trùng cẩn thận trước khi sử dụng bốc xếp, vận chuyển thủy sản”.",1);
  add(5,"Trong khu vực chợ cá, khu vệ sinh phải được bố trí như thế nào so với khu mua bán?",["Nằm liền kề để tiện di chuyển", "Cách biệt và luôn giữ sạch sẽ", "Được chia sẻ chung với khu bán hàng", "Không yêu cầu đặc biệt"],1,"Theo mục 2.5.1, “Khu vệ sinh ở chợ cá phải cách biệt với khu vực mua bán và luôn được giữ vệ sinh sạch sẽ”.",1);
  add(5,"Đối với dụng cụ làm vệ sinh tại chợ cá, yêu cầu nào sau đây là đúng?",["Chỉ cần có đủ số lượng, không quan tâm chất lượng", "Đủ số lượng, chủng loại, đảm bảo chất lượng và được cất giữ đúng quy định", "Phải được mua từ nhà cung cấp trong nước", "Phải được thay mới hàng tuần"],1,"Mục 2.5.2 quy định: “Dụng cụ làm vệ sinh phải đủ số lượng, chủng loại, đảm bảo chất lượng, được sử dụng và cất giữ đúng quy định”.",1);
  add(5,"Theo QCVN, phế thải tại chợ cá phải được bảo quản và xử lý như thế nào?",["Được bỏ vào thùng rác mở và đổ ra môi trường", "Đặt trong thùng chứa kín, không ăn mòn, có nắp đậy và được vệ sinh, khử trùng sau mỗi chu kỳ hoạt động", "Chỉ cần đậy nắp thùng khi không sử dụng", "Được đổ trực tiếp vào cống thoát nước"],1,"Mục 2.5.4 nêu rõ: “Phế thải phải thu gom vào trong thùng chứa kín, làm bằng vật liệu không bị ăn mòn, có nắp đậy… Thùng chứa phế thải phải được vệ sinh và khử trùng sau mỗi chu kỳ hoạt động”.",1);
  add(5,"Người bán buôn tại chợ cá phải ghi chép những nội dung nào trong sổ ghi chép lô thủy sản?",["Chỉ ghi tên cơ sở cung cấp và khối lượng", "Tên cơ sở, tên thủy sản, khối lượng, nguồn gốc, ngày giờ nhập và bán, nhận xét cảm quan và nhiệt độ", "Ghi chỉ ngày tháng nhập kho", "Ghi chỉ thông tin về giá bán"],1,"Mục 2.6.1 liệt kê 6 nội dung bắt buộc: tên cơ sở cung cấp, tên thủy sản, khối lượng, nguồn gốc, ngày‑giờ nhập‑bán, và các thông số chất lượng (cảm quan, nhiệt độ, quy cách bảo quản).",2);
  add(5,"Cơ sở chợ cá muốn được công bố hợp quy phải thực hiện bước nào sau khi đã được chứng nhận hợp quy?",["Nộp hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành", "Chỉ cần treo giấy chứng nhận tại chỗ", "Gửi báo cáo tài chính năm trước", "Thực hiện kiểm tra nội bộ mỗi tháng"],0,"Mục 3.2.1 quy định: “Cơ sở chợ cá được chứng nhận hợp quy phải thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành”.",2);
  add(5,"Trong trường hợp có vi phạm quy chuẩn kỹ thuật tại chợ cá, cơ quan nào có thẩm quyền thanh tra, kiểm tra?",["Sở Y tế địa phương", "Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương", "Cục Quản lý Thị trường", "Công an xã"],1,"Mục 3.3.1 nêu rõ: “Cơ sở chợ cá và Tổ chức chứng nhận chịu sự thanh tra, kiểm tra định kỳ hoặc đột xuất của Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương”.",2);
  add(5,"Một công nhân làm việc tại chợ cá không tuân thủ quy định về vệ sinh cá nhân. Theo QCVN, ai chịu trách nhiệm chính trong việc giám sát và xử lý?",["Cán bộ quản lý chuyên trách của chợ cá", "Người bán lẻ", "Bộ Y tế", "Cơ quan thuế"],0,"Theo mục 2.5.3b, chợ cá phải có quy định về vệ sinh và có cán bộ quản lý chuyên trách theo dõi, giám sát việc thực hiện. Do đó, trách nhiệm giám sát và xử lý vi phạm thuộc về cán bộ quản lý chuyên trách.",3);
  add(5,"QCVN 02-12:2009/BNNPTNT quy định về điều kiện vệ sinh an toàn thực phẩm trong sản xuất thủy sản tại cảng cá, mục đích chính của quy chuẩn này là gì?",["A. Đảm bảo nguồn cung cấp thủy sản đáp ứng tiêu chuẩn xuất khẩu", "B. Kiểm soát chất lượng nước biển tại khu vực khai thác", "C. Đảm bảo an toàn vệ sinh thực phẩm, ngăn ngừa nguy cơ nhiễm khuẩn và độc hại trong quá trình xử lý, bảo quản thủy sản tại cảng", "D. Tăng năng suất khai thác thủy sản tại các cảng cá"],2,"Theo QCVN 02-12:2009, mục tiêu chính là bảo đảm an toàn vệ sinh thực phẩm (ATVSTP) trong toàn bộ chuỗi xử lý, bảo quản thủy sản tại cảng cá, ngăn ngừa các yếu tố gây ô nhiễm và bảo vệ sức khỏe người tiêu dùng (Điều 1, Khoản 1).",1);
  add(5,"Theo QCVN 02-12:2009, đối tượng áp dụng của quy chuẩn này là:",["A. Tất cả các nhà máy chế biến thủy sản trên toàn quốc", "B. Các cảng cá, khu vực tiếp nhận, bảo quản, xử lý thủy sản trên biển và trên đất liền", "C. Các nhà hàng, quán ăn có phục vụ món hải sản", "D. Các doanh nghiệp xuất khẩu thủy sản"],1,"QCVN 02-12:2009 áp dụng cho các cảng cá, khu vực tiếp nhận, bảo quản, xử lý thủy sản (Điều 2, Khoản 1). Không bao gồm nhà máy chế biến, nhà hàng hay doanh nghiệp xuất khẩu nếu không nằm trong khu vực cảng cá.",1);
  add(5,"Trong quy chuẩn QCVN 02-12:2009, yêu cầu về nguồn nước sử dụng trong quá trình bảo quản thủy sản tại cảng cá là:",["A. Nước biển không cần xử lý, chỉ cần lọc sơ bộ", "B. Nước phải đáp ứng tiêu chuẩn QCVN 02-03:2009 về nước sinh hoạt", "C. Nước phải được xử lý đạt tiêu chuẩn QCVN 02-04:2009 về nước dùng cho thực phẩm", "D. Không có yêu cầu cụ thể về chất lượng nước"],2,"QCVN 02-12 quy định nguồn nước dùng cho bảo quản, rửa thủy sản phải đáp ứng tiêu chuẩn QCVN 02-04:2009 (Nước dùng cho thực phẩm), nhằm ngăn ngừa ô nhiễm vi sinh và hoá chất (Điều 4, Khoản 2).",2);
  add(5,"Theo QCVN 02-12:2009, các biện pháp vệ sinh công nhân trong cảng cá bao gồm:",["A. Đeo khẩu trang và găng tay khi làm việc trong khu vực xử lý", "B. Tắm rửa, thay quần áo sạch trước khi vào khu vực xử lý, và có phòng thay đồ riêng", "C. Chỉ cần rửa tay bằng xà phòng trước khi bắt đầu công việc", "D. Không yêu cầu đặc biệt vì thủy sản đã được xử lý nhiệt"],1,"Quy chuẩn yêu cầu công nhân phải tắm rửa, thay quần áo sạch, sử dụng trang thiết bị bảo hộ (găng tay, khẩu trang) và có phòng thay đồ, phòng vệ sinh riêng (Điều 6, Khoản 1).",2);
  add(5,"Nếu phát hiện vi sinh vật vượt mức cho phép trong nước rửa thủy sản tại cảng, hành động nào sau đây là đúng theo QCVN 02-12:2009?",["A. Tiếp tục sử dụng nước đó cho đến khi có kết quả xét nghiệm mới", "B. Ngưng sử dụng nước, thực hiện xử lý khử trùng và kiểm tra lại trước khi tiếp tục", "C. Chỉ cần giảm thời gian bảo quản thủy sản", "D. Thêm chất khử trùng vào nước mà không cần kiểm tra lại"],1,"Khi phát hiện vi sinh vượt mức, QCVN yêu cầu ngưng sử dụng, tiến hành khử trùng, kiểm tra lại chất lượng nước trước khi tiếp tục (Điều 7, Khoản 3). Việc tiếp tục dùng nước không an toàn sẽ vi phạm quy chuẩn.",3);
  add(5,"Trong trường hợp xảy ra sự cố ô nhiễm thực phẩm tại cảng cá (ví dụ: rò rỉ chất tẩy rửa vào khu vực bảo quản), quy trình xử lý sự cố theo QCVN 02-12:2009 bao gồm các bước nào sau đây?",["A. Ngay lập tức dừng hoạt động, thông báo cho cơ quan quản lý, thực hiện khử trùng khu vực và thu hồi sản phẩm bị ảnh hưởng", "B. Chỉ ghi nhận sự cố và báo cáo trong báo cáo tháng cuối", "C. Tiếp tục hoạt động, chỉ thay đổi nguồn nước sử dụng", "D. Đợi đến khi khách hàng phản ánh để mới có hành động"],0,"QCVN 02-12 quy định khi có sự cố ô nhiễm, phải dừng ngay hoạt động, thông báo cơ quan quản lý, thực hiện khử trùng, thu hồi sản phẩm và ghi chép đầy đủ (Điều 9, Khoản 1).",3);
  add(5,"Quy chuẩn QCVN 02-12:2009/BNNPTNT quy định phạm vi điều chỉnh gì?",["Đảm bảo vệ sinh an toàn thực phẩm thủy sản tại cảng cá", "Quy định tiêu chuẩn chất lượng nước biển", "Quy định về xuất khẩu thủy sản", "Quy chuẩn về bảo vệ môi trường khu vực ven biển"],0,"Theo mục 1.1 của Quy chuẩn, phạm vi điều chỉnh là \"điều kiện đảm bảo vệ sinh an toàn thực phẩm thủy sản đối với cảng cá\".",1);
  add(5,"Đối tượng áp dụng của Quy chuẩn này là:",["Chỉ các doanh nghiệp xuất khẩu thủy sản", "Tổ chức, cá nhân quản lý cảng và hoạt động sản xuất, kinh doanh dịch vụ trong cảng cá", "Người tiêu dùng cuối cùng", "Các nhà máy chế biến thủy sản nội địa"],1,"Mục 1.2 nêu rõ: \"Quy chuẩn này áp dụng cho tổ chức, cá nhân quản lý cảng và hoạt động sản xuất, kinh doanh dịch vụ trong cảng cá\".",1);
  add(5,"Theo mục 2.1.1, một cảng cá phải đáp ứng các yêu cầu nào sau đây?",["Có vị trí địa lý thuận tiện, nguồn nước, nguồn điện bảo đảm, cách biệt với khu dân cư, không bị ngập nước", "Chỉ cần có nguồn điện và gần khu dân cư", "Cần có nguồn nước nhưng không quan tâm đến vị trí địa lý", "Phải nằm trong khu công nghiệp và có hệ thống xử lý chất thải"],0,"Mục 2.1.1 quy định ba tiêu chí: (1) vị trí địa lý thuận tiện, có nguồn nước, nguồn điện; (2) cách biệt với khu dân cư và nguồn gây nhiễm; (3) không bị ngập, đọng nước.",2);
  add(5,"Yêu cầu về mặt cầu tàu (cầu tàu) được nêu trong mục 2.3.1 bao gồm:",["Phải có kích thước phù hợp, vật liệu thích hợp, mặt cầu không trơn, chịu va đập, thoát nước tốt, dễ vệ sinh, khử trùng", "Chỉ cần có kích thước lớn và chịu tải trọng", "Cần có hệ thống chiếu sáng nhưng không yêu cầu vật liệu", "Phải được làm bằng thép không gỉ nhưng không cần thoát nước"],0,"Mục 2.3.1.c ghi rõ: \"Mặt cầu tàu phải phẳng, không trơn, chịu va đập, thoát nước tốt; dễ làm vệ sinh, khử trùng\"; các yêu cầu khác cũng được liệt kê trong mục này.",1);
  add(5,"Đối với hệ thống đường giao thông nội bộ cảng cá, yêu cầu bề mặt đường là:",["Cứng, phẳng, không trơn, không đọng nước", "Mềm, có thể ngập nước khi mưa", "Chỉ cần có dấu hiệu chỉ dẫn", "Có thể làm bằng đất nông nghiệp"],0,"Mục 2.3.2.b quy định: \"Bề mặt đường phải cứng, phẳng, không trơn, không đọng nước\".",1);
  add(5,"Một cảng cá có kho lạnh đông phải đáp ứng các tiêu chuẩn nào sau đây?",["Vật liệu cách nhiệt tốt, có nhiệt kế, máy lạnh đủ công suất duy trì nhiệt độ –18°C hoặc thấp hơn", "Chỉ cần có máy lạnh mà không cần nhiệt kế", "Kho phải được làm bằng gỗ và không cần kiểm soát nhiệt độ", "Nhiệt độ kho chỉ cần duy trì trên 0°C"],0,"Mục 2.3.4.a nêu rõ: \"Vật liệu làm kho phải cách nhiệt tốt, có nhiệt kế, máy lạnh đủ công suất để nhiệt độ đạt –18°C hoặc thấp hơn\".",2);
  add(5,"Về kho dụng cụ, hoá chất, quy định nào sau đây là đúng?",["Phải có kho riêng, giá kê cách sàn ít nhất 0,3 m, thùng chứa kín, ghi nhãn tiếng Việt", "Có thể để dụng cụ trực tiếp trên sàn kho mà không cần thùng kín", "Không cần ghi nhãn tiếng Việt trên thùng chứa", "Kho có thể đặt gần khu vực xử lý thuỷ sản mà không cần cách ly"],0,"Mục 2.3.5.a‑b quy định: \"Kho riêng, giá kê cách sàn ít nhất 0,3 m; chất tẩy rửa, khử trùng phải đựng trong thùng kín, ghi rõ bằng tiếng Việt\".",2);
  add(5,"Hệ thống xử lý nước thải tại cảng cá phải tuân thủ tiêu chuẩn nào?",["TCVN 5945‑2005 về nước thải công nghiệp", "ISO 9001", "Bộ tiêu chuẩn quốc tế về an toàn thực phẩm HACCP", "Tiêu chuẩn về chất lượng không khí QCVN 06‑2010"],0,"Mục 2.3.7.b ghi rõ: \"Nước thải phải được xử lý theo đúng những quy định về nước thải công nghiệp của TCVN 5945‑2005\".",1);
  add(5,"Nếu một cảng cá nằm gần khu dân cư và có nguy cơ gây nhiễm cho thuỷ sản, theo QCVN 02‑12, biện pháp nào cần thực hiện?",["Di chuyển hoặc thực hiện các biện pháp cách ly, đảm bảo không gây nhiễm cho thuỷ sản", "Không cần thay đổi vì vị trí không ảnh hưởng đến sản phẩm", "Chỉ cần lắp đặt hệ thống lọc không khí", "Tăng cường quảng cáo để thu hút khách hàng"],0,"Mục 2.1.2 yêu cầu \"cách biệt với khu dân cư và cách xa các nguồn gây nhiễm cho thuỷ sản\"; nếu vi phạm, cần di chuyển hoặc áp dụng biện pháp cách ly để đáp ứng yêu cầu này.",3);
  add(5,"Một khu vực đường giao thông nội bộ trong cảng cá bị trơn và đọng nước. Vi phạm quy chuẩn nào?",["Mục 2.3.2.b yêu cầu bề mặt đường phải cứng, phẳng, không trơn, không đọng nước", "Mục 2.3.1.c về mặt cầu tàu", "Mục 2.3.5.b về kho hoá chất", "Mục 2.3.6.a về hệ thống cống rãnh"],0,"Theo mục 2.3.2.b, bề mặt đường giao thông nội bộ phải \"cứng, phẳng, không trơn, không đọng nước\"; do đó hiện trạng trên là vi phạm quy định này.",3);
  add(5,"Theo Thông tư 47/2009/TT-BNNPTNT, chất thải rắn tại cảng cá phải được thu gom và vận chuyển ra khỏi khu vực cảng ít nhất mỗi bao nhiêu giờ một lần?",["2 giờ", "3 giờ", "4 giờ", "6 giờ"],2,"Điều 2.3.8 khoản a quy định: \"Chất thải rắn phải được thu gom và được vận chuyển ra khỏi khu vực cảng cá ít nhất 4 giờ một lần\".",1);
  add(5,"Nơi chứa chất thải rắn tại cảng cá phải đáp ứng những yêu cầu nào sau đây?",["Phải mở, để không khí lưu thông tự nhiên", "Cần kín, cách biệt với khu có thuỷ sản và dễ làm vệ sinh, khử trùng", "Có thể đặt sát khu vực bốc dỡ thuỷ sản nếu có mái che", "Không cần có biện pháp ngăn ngừa mối mọt"],1,"Điều 2.3.8 khoản b quy định: \"Nơi chứa chất thải phải kín, cách biệt với khu có thuỷ sản và dễ làm vệ sinh, khử trùng\".",1);
  add(5,"Yêu cầu về nhà vệ sinh cho công nhân trong cảng cá bao gồm:",["Chỉ cần có nước sạch, không cần giấy vệ sinh", "Phải được thiết kế hợp vệ sinh, đủ số lượng; nước, xà phòng và giấy vệ sinh được cung cấp đủ theo nhu cầu", "Có thể dùng nước tái chế cho việc rửa tay", "Không cần có vòi rửa tay nếu có bồn rửa chung"],1,"Điều 2.3.9 nêu rõ: \"Nhà vệ sinh cho công nhân phải được thiết kế hợp vệ sinh, đủ số lượng; nước, xà phòng và giấy vệ sinh được cung cấp đủ theo nhu cầu\".",1);
  add(5,"Đối với bãi đỗ xe của cảng cá, yêu cầu nào sau đây là sai?",["Bãi đỗ xe phải được bố trí ở nơi thích hợp", "Bãi đỗ xe phải có diện tích đủ rộng, nền cứng, phẳng, thoát nước tốt", "Bãi đỗ xe có thể đặt trực tiếp trên bãi thuỷ sản nếu có lớp vải phủ", "Bãi đỗ xe phải đáp ứng tiêu chuẩn an toàn giao thông nội bộ"],2,"Điều 2.3.10 quy định a và b: bãi đỗ xe phải bố trí ở nơi thích hợp, diện tích đủ rộng, nền cứng, phẳng, thoát nước tốt. Không cho phép đặt trên bãi thuỷ sản.",1);
  add(5,"Hệ thống chiếu sáng trong cảng cá phải đáp ứng các tiêu chí nào?",["Chỉ cần đủ sáng cho khu vực văn phòng", "Đèn chiếu sáng phải được bố trí ở nơi cần thiết và đủ sáng, đồng thời có chụp bảo hiểm an toàn tại những nơi có thuỷ sản", "Có thể sử dụng đèn cũ không còn hiệu suất nếu có ánh sáng phụ trợ", "Không cần bảo hiểm an toàn nếu đèn được lắp ở trên mái"],1,"Điều 2.3.11 a, b quy định: hệ thống đèn chiếu sáng phải được bố trí ở nơi cần thiết và đủ sáng, đáp ứng mọi hoạt động; đèn chiếu sáng phải có chụp bảo hiểm an toàn tại những nơi có thuỷ sản.",1);
  add(5,"Nước đá sử dụng trong cảng cá phải đáp ứng tiêu chuẩn nào?",["Nước máy bình thường", "Nước sạch đạt tiêu chuẩn của Bộ Y tế và được sản xuất tại cơ sở phù hợp với QCVN 02-08:2009/BNNPTNT", "Nước tái chế sau xử lý sinh học", "Nước đóng chai nhập khẩu"],1,"Điều 2.4.1 a quy định: \"Nước đá sử dụng trong cảng cá phải làm từ nước sạch đạt tiêu chuẩn của Bộ Y tế; được sản xuất tại các cơ sở phù hợp với QCVN 02-08 2009/BNNPTNT\".",2);
  add(5,"Khi lượng nước cung cấp không đủ và không đạt chất lượng, cảng cá phải có hệ thống nào để đáp ứng nhu cầu sản xuất?",["Chỉ cần mua nước đóng chai", "Hệ thống bể lắng, lọc, khử trùng và bể chứa nước dự trữ đạt yêu cầu an toàn vệ sinh thực phẩm", "Sử dụng nước mưa không qua xử lý", "Không cần biện pháp gì nếu sản lượng giảm"],1,"Điều 2.4.2 b quy định: \"Nếu lượng nước cung cấp không đủ và không đạt chất lượng thì cảng cá phải có hệ thống bể lắng, lọc, khử trùng và bể chứa nước dự trữ đạt yêu cầu an toàn vệ sinh thực phẩm và nhu cầu sản xuất lúc cao điểm mùa vụ\".",2);
  add(5,"Hệ thống ống dẫn nước dùng cho việc tiếp xúc với thuỷ sản phải được thiết kế như thế nào?",["Có thể dùng chung với hệ thống cấp nước sinh hoạt", "Phải tách riêng với hệ thống dẫn nước cho mục đích khác", "Chỉ cần màu sắc khác nhau để phân biệt", "Không cần bất kỳ biện pháp tách rời nào"],1,"Điều 2.4.2 c quy định: \"Hệ thống ống dẫn nước dùng cho việc liên quan tiếp xúc đến thuỷ sản phải tách riêng với hệ thống dẫn nước cho mục đích khác\".",2);
  add(5,"Về kho chứa xăng dầu trong cảng cá, quy định nào sau đây là đúng?",["Kho có thể đặt ngay cạnh khu vực bốc dỡ thuỷ sản để tiện lợi", "Kho phải bố trí xa và tách biệt với khu vực có nguyên liệu thuỷ sản; bồn chứa và đường ống phải kín, bền, không gây nhiễm cho sản phẩm", "Không cần có biện pháp ngăn rò rỉ nếu có hệ thống cảnh báo khói", "Có thể dùng bồn nhựa thông thường cho việc lưu trữ xăng dầu"],1,"Điều 2.4.3 a, b quy định: \"Kho chứa xăng dầu phải bố trí xa và tách biệt với khu vực có nguyên liệu thuỷ sản; bồn chứa và hệ thống đường ống dẫn xăng dầu phải kín, bền và được bố trí đảm bảo không gây nhiễm cho sản phẩm\".",2);
  add(5,"Theo quy định về vệ sinh cá nhân trong cảng cá, người nào sau đây không được phép làm việc hoặc tiếp xúc với thuỷ sản?",["Người có bệnh truyền nhiễm", "Người đã hoàn thành khóa đào tạo vệ sinh", "Người được kiểm tra sức khỏe định kỳ hàng năm", "Người mặc đồng phục bảo hộ"],0,"Điều 2.6.1 a quy định: \"Người có bệnh truyền nhiễm không được làm việc hoặc tiếp xúc với thuỷ sản\".",1);
  add(5,"Theo đoạn trích, cơ sở cảng cá phải thực hiện chứng nhận hợp quy dựa trên quyết định nào?",["Quyết định số 24/2007/QĐ-BKHCN ngày 28/9/2007", "Quyết định số 30/2008/QĐ-BKHCN ngày 15/10/2008", "Quyết định số 12/2006/QĐ-BKHCN ngày 01/5/2006", "Quyết định số 45/2009/QĐ-BKHCN ngày 20/12/2009"],0,"Đoạn 3.1.1 nêu rõ cơ sở cảng cá phải thực hiện chứng nhận hợp quy theo Quyết định số 24/2007/QĐ-BKHCN ngày 28/9/2007 “Quy định về hoạt động chứng nhận hợp chuẩn, chứng nhận hợp quy, công bố hợp chuẩn, công bố hợp quy”.",1);
  add(5,"Tổ chức chứng nhận sự phù hợp cho cơ sở cảng cá được thành lập và hoạt động theo nghị định nào?",["Nghị định số 127/2007/NĐ-CP ngày 01/8/2007", "Nghị định số 100/2005/NĐ-CP ngày 15/3/2005", "Nghị định số 150/2009/NĐ-CP ngày 20/11/2009", "Nghị định số 80/2006/NĐ-CP ngày 10/7/2006"],0,"Theo mục 3.1.2, tổ chức chứng nhận được thành lập và hoạt động dựa trên Nghị định số 127/2007/NĐ-CP ngày 01/8/2007 về “Quy định chi tiết thi hành một số điều của Luật Tiêu chuẩn và Quy chuẩn kỹ thuật”.",1);
  add(5,"Sau khi được chứng nhận hợp quy, cơ sở cảng cá phải thực hiện nghĩa vụ nào sau đây?",["Tiếp tục khai thác mà không cần báo cáo", "Công bố hợp quy và gửi hồ sơ công bố tới cơ quan quản lý nhà nước chuyên ngành", "Xin cấp giấy phép xuất khẩu quốc tế", "Thực hiện kiểm dịch hải sản theo Thông tư 26/2016"],1,"Mục 3.2.1 quy định: Cơ sở cảng cá được chứng nhận hợp quy phải thực hiện công bố hợp quy và gửi hồ sơ công bố hợp quy về cơ quan quản lý nhà nước chuyên ngành do Bộ Nông nghiệp và Phát triển nông thôn chỉ định.",2);
  add(5,"Ai có thẩm quyền thanh tra, kiểm tra định kỳ hoặc đột xuất cơ sở cảng cá đã chứng nhận hợp quy?",["Bộ Y tế", "Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền ở địa phương", "Cục Hải quan", "Bộ Công Thương"],1,"Mục 3.3.1 nêu rõ cơ sở cảng cá và tổ chức chứng nhận chịu sự thanh tra, kiểm tra của Bộ Nông nghiệp và Phát triển nông thôn hoặc cơ quan quản lý nhà nước có thẩm quyền tại địa phương.",1);
  add(5,"Yêu cầu về chương trình quản lý chất lượng của cảng cá được nêu trong đoạn văn là gì?",["Chỉ cần có chương trình quản lý chất lượng quốc tế ISO 9001", "Phải có chương trình quản lý chất lượng phù hợp với khả năng của cảng và hồ sơ theo dõi xuất nhập để truy xuất nguồn gốc sản phẩm", "Không yêu cầu chương trình quản lý chất lượng nào", "Cần có chương trình quản lý chất lượng do Bộ Y tế phê duyệt"],1,"Trong mục 2.7, yêu cầu: \"Cảng cá phải có chương trình quản lý chất lượng phù hợp với điều kiện khả năng của cảng và phải có hồ sơ thoi dõi xuất nhập thuỷ sản qua cảng, đảm bảo dễ dàng trong việc truy xuất nguồn gốc sản phẩm.\"",2);
  add(5,"Cơ quan nào chịu trách nhiệm chỉ đạo, phổ biến, hướng dẫn và thực hiện Quy chuẩn kỹ thuật quốc gia về điều kiện vệ sinh an toàn thực phẩm trên tàu cá?",["Bộ Y tế", "Bộ Nông nghiệp và Phát triển nông thôn", "Bộ Công Thương", "Cục An toàn Thực phẩm"],1,"Theo Điều 3.4.2 của QCVN 02‑13:2009, Bộ Nông nghiệp và Phát triển nông thôn (Bộ Nông nghiệp) là đơn vị tổ chức chỉ đạo, phổ biến, hướng dẫn và thực hiện Quy chuẩn này.",1);
  add(5,"Khi có sự thay đổi, bổ sung hoặc thay thế các quy định tại QCVN 02‑13:2009, việc áp dụng các quy định mới phải thực hiện như thế nào?",["Tự ý áp dụng ngay khi nhận được thông tin", "Theo quyết định của Chủ tịch UBND tỉnh", "Theo văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành", "Không áp dụng cho đến khi có thông báo công khai rộng rãi"],2,"Điều 3.4.3 quy định: \"Trong trường hợp các quy định tại Quy chuẩn này có sự thay đổi, bổ sung hoặc thay thế thì thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành.\"",1);
  add(5,"Trong các yêu cầu về nguồn nước sinh hoạt trên tàu cá theo QCVN 02‑13:2009, yếu tố nào sau đây KHÔNG được chấp nhận?",["Nguồn nước phải được xử lý đạt tiêu chuẩn vi sinh", "Nguồn nước phải được lấy trực tiếp từ biển mà không qua xử lý", "Nguồn nước phải được bảo quản trong bồn kín, không ô nhiễm", "Nguồn nước phải được kiểm tra định kỳ theo chỉ tiêu"],1,"Quy chuẩn quy định nguồn nước sinh hoạt phải được xử lý đạt tiêu chuẩn vi sinh, bảo quản kín và kiểm tra định kỳ (Điều 5, mục 5.2). Việc lấy nước trực tiếp từ biển mà không qua xử lý không đáp ứng yêu cầu vệ sinh an toàn thực phẩm.",2);
  add(5,"Nếu phát hiện vi phạm các yêu cầu về vệ sinh an toàn thực phẩm trên tàu cá, cơ quan nào có thẩm quyền xử lý hành chính vi phạm?",["Cục An toàn Thực phẩm", "Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn", "Sở Nông nghiệp tỉnh", "Tổ chức kiểm dịch hải sản quốc gia"],2,"Theo Điều 9 của QCVN 02‑13:2009, Sở Nông nghiệp (hoặc Sở Nông nghiệp và Phát triển Nông thôn) của tỉnh là cơ quan chịu trách nhiệm kiểm tra, giám sát và xử lý vi phạm hành chính liên quan đến quy chuẩn này.",2);
  add(5,"Đối với việc bảo đảm vệ sinh công nhân trên tàu cá, quy chuẩn yêu cầu nào sau đây là đúng?",["Không yêu cầu rửa tay trước khi tiếp xúc thực phẩm", "Yêu cầu nhân viên mặc áo bảo hộ sạch và rửa tay bằng dung dịch khử trùng trước khi tiếp xúc thực phẩm", "Cho phép nhân viên ăn uống trong khu vực chế biến", "Không cần kiểm tra sức khỏe định kỳ của công nhân"],1,"Điều 6.3 của QCVN 02‑13:2009 quy định công nhân phải mặc đồng phục sạch, rửa tay bằng dung dịch khử trùng và không được ăn uống trong khu vực chế biến để đảm bảo vệ sinh thực phẩm.",2);
  add(5,"Trong một chuyến đi, nhiệt độ của kho lạnh trên tàu cá tăng lên 12 °C, vượt quá giới hạn cho phép. Theo QCVN 02‑13:2009, hành động nào là đúng nhất?",["Tiếp tục vận chuyển mà không làm gì", "Giảm nhiệt độ ngay, ghi lại sự cố, kiểm tra chất lượng sản phẩm và báo cáo lên cơ quan quản lý", "Đổ bỏ toàn bộ sản phẩm ngay lập tức", "Báo cáo sự cố chỉ sau khi về cảng mà không thay đổi quy trình bảo quản"],1,"Điều 7.5 yêu cầu khi phát hiện sai lệch về nhiệt độ lưu trữ, phải khắc phục ngay (giảm nhiệt độ), ghi lại biên bản sự cố, kiểm tra lại chất lượng sản phẩm và thông báo cho cơ quan quản lý để tránh nguy cơ ôi thiu.",3);
  add(5,"Trong QCVN 02‑13:2009, chương nào quy định các yêu cầu về thiết bị và cơ sở vật chất trên tàu cá?",["Chương 1", "Chương 3", "Chương 5", "Chương 7"],1,"Các yêu cầu về thiết bị, cơ sở vật chất, hệ thống xử lý nước, kho lạnh, vv. được quy định chi tiết trong Chương 3 của QCVN 02‑13:2009.",1);
  add(5,"Nội quy vệ sinh trên tàu cá phải quy định rõ những nội dung nào?",["Chỉ thời gian làm vệ sinh", "Phương pháp, tần suất làm vệ sinh và trách nhiệm của từng cá nhân", "Danh mục vật tư tiêu hao", "Kế hoạch khai thác cá"],1,"Theo đoạn văn, nội quy vệ sinh phải quy định rõ phương pháp, tần suất làm vệ sinh cho phù hợp với từng loại tàu cá và xác định trách nhiệm cụ thể của từng cá nhân (điểm b).",1);
  add(5,"Trên tàu cá, người chịu trách nhiệm chính về vệ sinh an toàn và chất lượng thủy sản là:",["Thuyền trưởng", "Kỹ sư trưởng", "Người được chỉ định chịu trách nhiệm chính về vệ sinh an toàn và chất lượng thủy sản", "Chủ sở hữu tàu"],2,"Đoạn văn ghi rõ: \"Trên tàu cá phải có người chịu trách nhiệm chính về vệ sinh an toàn và chất lượng thủy sản\" (điểm c).",1);
  add(5,"Hồ sơ theo dõi kiểm soát chất lượng và vệ sinh an toàn phải được:",["Lưu trữ tại văn phòng công ty và không cần cập nhật", "Gửi lên Bộ Nông nghiệp mỗi tháng", "Cập nhật và lưu trữ đầy đủ", "Chỉ lưu trữ bản sao điện tử"],2,"Theo nội dung: \"Hồ sơ theo dõi kiểm soát chất lượng và vệ sinh an toàn phải được cập nhật và lưu trữ đầy đủ\" (điểm d).",1);
  add(5,"Việc công bố tàu cá hợp quy phải dựa trên quy định của văn bản nào?",["Nghị định số 127/2007/NĐ-CP ngày 01/8/2007", "Luật Thủy sản năm 2017", "Thông tư 47/2009/TT-BNNPTNT", "Quyết định số 45/2015/QĐ-BNN"],0,"Đoạn 3.1.b nêu rõ việc công bố tàu cá hợp quy phải tuân theo Điều 14 Nghị định số 127/2007/NĐ-CP ngày 01/8/2007.",2);
  add(5,"Ai chịu trách nhiệm kiểm tra, giám sát và thanh tra việc tuân thủ Quy chuẩn kỹ thuật này trên tàu cá?",["Chỉ chủ sở hữu tàu", "Bộ Y tế", "Các cơ quan có thẩm quyền do Bộ Nông nghiệp và Phát triển nông thôn chỉ định", "Tổ chức quốc tế"],2,"Theo mục 3.2.1, chủ sở hữu phải chịu sự kiểm tra, giám sát và thanh tra của các cơ quan có thẩm quyền do Bộ Nông nghiệp và Phát triển nông thôn chỉ định.",2);
  add(5,"Khi có sự thay đổi, bổ sung hoặc thay thế quy chuẩn này, phải thực hiện theo quy định nào?",["Tiếp tục áp dụng quy chuẩn cũ cho đến khi có thông báo", "Áp dụng quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành", "Chỉ áp dụng khi có quyết định của UBND tỉnh", "Không cần thay đổi nếu đã được công bố hợp quy"],1,"Mục 3.2.3 quy định: \"Thực hiện theo quy định văn bản mới do Bộ trưởng Bộ Nông nghiệp và Phát triển nông thôn ký ban hành\" khi có thay đổi.",2);
  add(5,"Tình huống: Một tàu cá không cập nhật hồ sơ kiểm soát chất lượng và vệ sinh an toàn trong ba chuyến đi liên tiếp. Theo quy chuẩn, biện pháp xử lý nào phù hợp nhất?",["Đình chỉ hoạt động của tàu ngay lập tức", "Áp dụng hình phạt tiền theo quy định xử phạt vi phạm hành chính", "Yêu cầu tàu cập nhật hồ sơ, tiến hành kiểm tra lại và có thể áp dụng biện pháp xử phạt nếu không khắc phục", "Không có biện pháp nào vì quy chuẩn không quy định"],2,"Vì hồ sơ phải được \"cập nhật và lưu trữ đầy đủ\" (điểm d), việc không thực hiện sẽ bị cơ quan kiểm tra yêu cầu khắc phục và có thể áp dụng hình phạt hành chính theo quy định chung về vi phạm an toàn thực phẩm.",3);

  return list;
})();
